INSERT INTO `dialogueline` (`dialogueID`, `npcID`, `narrativeID`, `sceneID`, `dialogueLine`, `sequenceOrder`) VALUES
(222, 5, 301, NULL, 'Tugasku ialah menenangkan negara selepas 13 Mei 1969, mendengar semua pihak dan merangka satu ideologi yang menyatukan rakyat. Satu kesilapan boleh mencetuskan perpecahan baharu, {nama}.', 1),
(223, 5, 301, NULL, 'Aku belajar bahawa perpaduan tidak lahir daripada paksaan, tetapi daripada pegangan bersama yang dihayati oleh semua kaum.', 2),
(224, 5, 301, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin yang mentadbir negara melalui MAGERAN selepas peristiwa 13 Mei 1969. Keputusanmu menentukan masa depan perpaduan. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(225, 42, 301, 'e3_n1_s1', 'Tun, keadaan sudah reda tetapi rakyat masih curiga antara satu sama lain. Siapa yang akan mentadbir negara sekarang?', 1),
(226, NULL, 301, 'e3_n1_s1', 'Satu badan khas akan mengambil alih pentadbiran. Jangan biar kekosongan melahirkan kekacauan.', 2),
(227, 42, 301, 'e3_n1_s1', 'Tun, ramai bertanya nama badan itu. Jangan sampai kita menyebut nama yang salah.', 3),
(228, 43, 301, 'e3_n1_s1', 'Dan selepas itu, Tun? Bagaimana kita memastikan peristiwa ini tidak berulang?', 4),
(229, 43, 301, 'e3_n1_s2', 'Tun, rakyat hidup di tempat berasingan. Peta ini menunjukkan kampung, ladang dan pekan, tetapi tiga bukti hilang.', 1),
(230, NULL, 301, 'e3_n1_s2', 'Cari bukti kegiatan dan tempat tinggal setiap kaum.', 2),
(231, 43, 301, 'e3_n1_s2', 'Jika kita tidak jumpa, laporan kepada MAGERAN akan tidak lengkap.', 3),
(232, 42, 301, 'e3_n1_s2', 'Tun, ini punca perbezaan, bukan hanya akibat.', 4),
(233, 42, 301, 'e3_n1_s3', 'Tun, kali ini kita tidak boleh memutuskan seorang diri. Majlis Perundingan Negara akan membabitkan banyak wakil.', 1),
(234, NULL, 301, 'e3_n1_s3', 'Ya. Wakil kerajaan, parti politik, agama, guru, akhbar dan kesatuan pekerja akan duduk bersama.', 2),
(235, 43, 301, 'e3_n1_s3', 'Tetapi berapa jumlah wakil, Tun? Rekod mesti tepat.', 3),
(236, 42, 301, 'e3_n1_s3', 'Dan siapa yang merangka Rukun Negara?', 4),
(237, 43, 301, 'e3_n1_s4', 'Tun, lima matlamat telah ditulis. Tetapi lukisan di dinding tidak menunjukkan ia dengan jelas.', 1),
(238, NULL, 301, 'e3_n1_s4', 'Cari lima bukti tersembunyi: bendera, buku perlembagaan, timbangan, tempat ibadat dan panel digital.', 2),
(239, 42, 301, 'e3_n1_s4', 'Jika tersilap, rakyat akan menghafal matlamat yang salah.', 3),
(240, 43, 301, 'e3_n1_s4', 'Cepat, Tun, mesyuarat bermula sebentar lagi.', 4),
(241, 42, 301, 'e3_n1_s5', 'Tun, pengisytiharan akan dibuat oleh Yang di-Pertuan Agong Keempat. Hari ini bersempena ulang tahun Hari Kebangsaan yang ke-13.', 1),
(242, NULL, 301, 'e3_n1_s5', 'Tarikh itu 31 Ogos 1970. Peristiwa sebelum itu mesti disusun dengan betul.', 2),
(243, 42, 301, 'e3_n1_s5', 'Jika tersilap, sejarah Rukun Negara akan tercatat salah.', 3),
(244, 43, 301, 'e3_n1_s5', 'Susun kad-kad ini, Tun.', 4),
(245, 43, 301, 'e3_n1_s6', 'Tun, lima matlamat dan maksudnya bercampur. Jika dicetak salah, jutaan salinan akan tersilap.', 1),
(246, NULL, 301, 'e3_n1_s6', 'Aku akan memadankan satu demi satu.', 2),
(247, 42, 301, 'e3_n1_s6', 'Tun, cepat sebelum pencetak menunggu.', 3),
(248, 43, 301, 'e3_n1_s6', 'Tulis dengan tepat.', 4),
(249, 41, 302, NULL, 'Tugasku ialah mendengar rakyat dari kampung, ladang dan bandar, dan menjelaskan mengapa Rukun Negara diperlukan. Jika suara mereka tidak dihargai, perpaduan tidak akan hidup, {nama}.', 1),
(250, 41, 302, NULL, 'Aku belajar bahawa perpaduan bermula apabila kita mengenali kehidupan jiran berlainan kaum dan menghormati pegangan mereka.', 2),
(251, 41, 302, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin MIC yang mengenali penderitaan di ladang dan di bandar. Dengar suara rakyat dan jawab dengan hati. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(252, 44, 302, 'e3_n2_s1', 'Tun, saya berniaga di bandar. Kawan-kawan India menoreh getah, dan orang Melayu bertani. Mengapa kita berbeza begini?', 1),
(253, 45, 302, 'e3_n2_s1', 'Tun, kerana pentadbiran British membawa masuk pekerja untuk sektor ekonomi, bukan?', 2),
(254, 46, 302, 'e3_n2_s1', 'Tapi kalau kami tersalah catat, laporan Tun nanti salah, kan?', 3),
(255, NULL, 302, 'e3_n2_s1', 'Mari padankan kaum dengan kegiatan ekonomi masing-masing.', 4),
(256, 49, 302, 'e3_n2_s2', 'Tun, saya tinggal di ladang. Hafiz di kampung. Wei Jie di bandar. Kami jarang berjumpa.', 1),
(257, 50, 302, 'e3_n2_s2', 'Betul, Tun. Sebab itu saya tidak tahu apa yang dirasa mereka.', 2),
(258, 47, 302, 'e3_n2_s2', 'Tapi kalau tak berjumpa, masakan kami boleh berkawan?', 3),
(259, NULL, 302, 'e3_n2_s2', 'Baca nota ini dan tentukan kesannya.', 4),
(260, 45, 302, 'e3_n2_s3', 'Tun, bagaimana kita menjelaskan kepada rakyat mengapa 13 Mei berlaku?', 1),
(261, NULL, 302, 'e3_n2_s3', 'Setiap sebab membawa kepada sebab seterusnya. Mari susun rantaian itu.', 2),
(262, 45, 302, 'e3_n2_s3', 'Kalau tersilap susun, orang menyalahkan kaum yang salah.', 3),
(263, 49, 302, 'e3_n2_s3', 'Susun betul-betul, Tun.', 4),
(264, 48, 302, 'e3_n2_s4', 'Tun, prinsip pertama menyebut kepercayaan kepada Tuhan. Mengapa penting untuk kami yang berlainan agama?', 1),
(265, 46, 302, 'e3_n2_s4', 'Kalau kami berlainan agama, apakah itu tidak memisahkan kami?', 2),
(266, 50, 302, 'e3_n2_s4', 'Tun, saya takut kalau salah faham pula.', 3),
(267, NULL, 302, 'e3_n2_s4', 'Baca penjelasan ini dan pilihlah jawapan yang betul.', 4),
(268, 51, 302, 'e3_n2_s5', 'Tun, lima prinsip itu tersimpan dalam taman ini. Tetapi di mana tiga petunjuk pertama?', 1),
(269, NULL, 302, 'e3_n2_s5', 'Cari tiga petunjuk: orang berdoa, jata negara dan tugu negara.', 2),
(270, 52, 302, 'e3_n2_s5', 'Tun, saya mahu tahu juga apa kaitan jata negara dengan raja.', 3),
(271, 51, 302, 'e3_n2_s5', 'Jika tak jumpa, kami tak boleh jelaskan kepada anak.', 4),
(272, 44, 302, 'e3_n2_s6', 'Tun, kami tak tahu mana maksud mana prinsip. Papan ini bercampur.', 1),
(273, 45, 302, 'e3_n2_s6', 'Padankan, Tun, supaya kami dapat hafal dengan betul.', 2),
(274, 47, 302, 'e3_n2_s6', 'Tersilap sedikit, anak-anak sekolah akan hafal yang salah.', 3),
(275, NULL, 302, 'e3_n2_s6', 'Mari padankan lima prinsip dengan maksudnya.', 4),
(276, 1, 303, NULL, 'Tugasku ialah mengajak rakyat berikrar bersama dan menunjukkan bahawa Rukun Negara bukan sekadar teks, tetapi panduan hidup harian, {nama}.', 1),
(277, 1, 303, NULL, 'Aku belajar bahawa Rukun Negara berperanan menjadikan rakyat bersatu padu, bertoleransi, patriotik dan berintegriti.', 2),
(278, 1, 303, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Perdana Menteri pertama yang memikul luka negara. Dengar suara rakyat muda dan tua. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(279, 52, 303, 'e3_n3_s1', 'Tunku, bagaimana Rukun Negara membantu kami menghormati kawan yang berlainan agama?', 1),
(280, NULL, 303, 'e3_n3_s1', 'Prinsip kepercayaan kepada Tuhan membentuk masyarakat patuh pada ajaran agama masing-masing.', 2),
(281, 48, 303, 'e3_n3_s1', 'Tunku, adakah orang beragama dapat mengelakkan rasuah dan dadah?', 3),
(282, 52, 303, 'e3_n3_s1', 'Pilih jawapan yang betul.', 4),
(283, 50, 303, 'e3_n3_s2', 'Tunku, kawan saya kata bendera itu kain biasa sahaja. Betulkah?', 1),
(284, 48, 303, 'e3_n3_s2', 'Tunku, dia kata Negaraku tidak perlu dihormati.', 2),
(285, NULL, 303, 'e3_n3_s2', 'Cinta akan negara dilihat melalui rasa hormat kepada lambang kedaulatan.', 3),
(286, 50, 303, 'e3_n3_s2', 'Jawab untuk kawan kami, Tunku.', 4),
(287, 50, 303, 'e3_n3_s3', 'Tunku, mengapa kita mesti patuh undang-undang? Kalau tiada siapa nampak, tiada apa-apa berlaku.', 1),
(288, 49, 303, 'e3_n3_s3', 'Tunku, saya dengar kegiatan jenayah boleh menggugat keselamatan negara.', 2),
(289, NULL, 303, 'e3_n3_s3', 'Rukun Negara membimbing rakyat daripada kegiatan jenayah.', 3),
(290, 50, 303, 'e3_n3_s3', 'Terangkan, Tunku.', 4),
(291, 44, 303, 'e3_n3_s4', 'Tunku, mereka bertengkar sebab makanan. Saya hampir mahu tutup kedai.', 1),
(292, 49, 303, 'e3_n3_s4', 'Tunku, kita sepatutnya bertolak ansur, bukan?', 2),
(293, NULL, 303, 'e3_n3_s4', 'Rukun Negara mengukuhkan perpaduan masyarakat melalui permuafakatan dan toleransi.', 3),
(294, 44, 303, 'e3_n3_s4', 'Pilih jawapan yang betul, Tunku.', 4),
(295, 52, 303, 'e3_n3_s5', 'Tunku, ada enam peranan Rukun Negara. Tapi kad ini bercampur.', 1),
(296, NULL, 303, 'e3_n3_s5', 'Peranan itu: kepelbagaian agama, patriotik, undang-undang, perpaduan, nilai murni dan jati diri.', 2),
(297, 49, 303, 'e3_n3_s5', 'Tunku, jangan lupa integriti.', 3),
(298, 52, 303, 'e3_n3_s5', 'Padankan, Tunku, supaya kami boleh hafal.', 4),
(299, 52, 303, 'e3_n3_s6', 'Tunku, empat petunjuk tersembunyi di taman ini. Cari semuanya!', 1),
(300, NULL, 303, 'e3_n3_s6', 'Aku akan mencari satu demi satu.', 2),
(301, 51, 303, 'e3_n3_s6', 'Tunku, jangan terlepas yang di hujung.', 3),
(302, 52, 303, 'e3_n3_s6', 'Jika terlepas, kami tak dapat beri gambaran prinsip kepada adik.', 4),
(303, 61, 401, NULL, 'Tugasku ialah menjaga rentak setiap kaum supaya tidak hilang ditelan zaman. Jika satu bunyi terlupa, satu cerita ikut hilang, {nama}.', 1),
(304, 61, 401, NULL, 'Aku belajar bahawa alat muzik dan tarian pelbagai kaum memperlihatkan kebijaksanaan nenek moyang dan menjadi warisan yang perlu kita hargai bersama.', 2),
(305, 61, 401, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemuzik yang mengembara membawa alat muzik pelbagai kaum. Dengar setiap rentak dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(306, 64, 401, 'e4_n1_s1', 'Pakcik, mengapa pengacara guna banyak bahasa? Cakap Melayu sahaja pun cukup.', 1),
(307, 69, 401, 'e4_n1_s1', 'Aku cakap Hokkien dengan datuk, tetapi kawan sekelas ada yang cakap Kantonis.', 2),
(308, 65, 401, 'e4_n1_s1', 'Di rumah, kami bertutur Tamil. Ada juga kawan yang bertutur Telugu.', 3),
(309, NULL, 401, 'e4_n1_s1', 'Setiap kaum ada bahasanya. Padankan sebelum pengacara tersilap menyebut kaum di hadapan penonton.', 4),
(310, 70, 401, 'e4_n1_s2', 'Dalam kad itu tertulis tiga kumpulan kami. Tetapi budak bandar ini tersilap menyebutnya semalam.', 1),
(311, 74, 401, 'e4_n1_s2', 'Saya ingat kumpulan Orang Asli sama dengan Iban dan Bidayuh, Tok Batin.', 2),
(312, 70, 401, 'e4_n1_s2', 'Kau mesti betulkan, kerana kami terkenal dengan kraf, ubat herba dan bahasa mengikut suku.', 3),
(313, NULL, 401, 'e4_n1_s2', 'Aku akan baca nota itu dahulu sebelum menjawab.', 4),
(314, 69, 401, 'e4_n1_s3', 'Pakcik, kata orang Baba dan Nyonya itu Cina biasa sahaja. Betulkah?', 1),
(315, 65, 401, 'e4_n1_s3', 'Tetapi nenek kata orang Chetti itu keturunan India yang berkahwin dengan penduduk tempatan.', 2),
(316, 64, 401, 'e4_n1_s3', 'Dan aku dengar Sikh memakai sarban. Kenapa mereka tidak bertutur seperti kita?', 3),
(317, NULL, 401, 'e4_n1_s3', 'Mari padankan kaum-kaum ini dengan ciri sebenar mereka.', 4),
(318, 68, 401, 'e4_n1_s4', 'Di Sarawak, kaum kami yang terbesar. Pakaian pua kumbu kami digayakan semasa Hari Gawai.', 1),
(319, 66, 401, 'e4_n1_s4', 'Di Sabah, kaum kami pula yang terbesar. Kami memakai pakaian tradisional semasa Pesta Kaamatan.', 2),
(320, 68, 401, 'e4_n1_s4', 'Kalau tersilap catat, pengunjung akan menyangka kaum lain lebih besar.', 3),
(321, NULL, 401, 'e4_n1_s4', 'Aku akan baca catatan ini dan buat keputusan yang adil.', 4),
(322, 63, 401, 'e4_n1_s5', 'Pakcik Pemuzik, papan petunjuk jatuh. Pasukan Sarawak berdiri di tempat Sabah!', 1),
(323, NULL, 401, 'e4_n1_s5', 'Kita betulkan dengan mencari lima sudut yang mewakili Melayu, Cina, India, Sarawak dan Sabah.', 2),
(324, 66, 401, 'e4_n1_s5', 'Cepat, persembahan Sabah hampir bermula.', 3),
(325, 68, 401, 'e4_n1_s5', 'Kalau tersilap, pemuzik membunyikan alat yang salah.', 4),
(326, 74, 401, 'e4_n1_s6', 'Pakcik, untuk apa kita simpan alat lama? Muzik komputer lebih senang.', 1),
(327, NULL, 401, 'e4_n1_s6', 'Setiap alat muzik ada bahan dan caranya sendiri. Padankan dahulu sebelum kau menilai.', 2),
(328, 65, 401, 'e4_n1_s6', 'Nenek kata veenai itu bukan sebarang alat.', 3),
(329, NULL, 401, 'e4_n1_s6', 'Mari lihat bahan dan ciri alat muzik ini dahulu.', 4),
(330, 65, 401, 'e4_n1_s7', 'Dahulu makyung ditonton di istana. Tetapi senarai ini sudah bercampur.', 1),
(331, 65, 401, 'e4_n1_s7', 'Aku mahu menari bharata natyam, tetapi namaku tercatat di sebelah tarian lain.', 2),
(332, 68, 401, 'e4_n1_s7', 'Aku menari ngajat. Jangan sampai kami tersilap iring muzik.', 3),
(333, NULL, 401, 'e4_n1_s7', 'Padankan tarian dengan tujuan dan cirinya, sebelum tirai dibuka.', 4),
(334, 70, 401, 'e4_n1_s8', 'Penari kami menghias diri dengan bunga, daun kelapa, daun palas dan kulit kayu.', 1),
(335, 74, 401, 'e4_n1_s8', 'Tetapi di atas tikar ada kad bhangra juga, Tok Batin. Yang mana kepunyaan Orang Asli?', 2),
(336, NULL, 401, 'e4_n1_s8', 'Baca kad ini dengan teliti, kerana tarian ini identiti sesebuah kaum.', 3),
(337, 70, 401, 'e4_n1_s8', 'Jawab dengan betul, nak.', 4),
(338, 62, 402, NULL, 'Tugasku ialah membuka peti cerita ini satu demi satu supaya cucu-cucu tahu bagaimana datuk nenek mereka hidup, {nama}.', 1),
(339, 62, 402, NULL, 'Aku belajar bahawa petempatan dan kegiatan ekonomi dahulu berbeza, tetapi kini kita boleh tinggal bersama dan cerita rakyat memberi iktibar kepada kita.', 2),
(340, 62, 402, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, nenek yang menyimpan cerita setiap kaum. Dengar soalan cucu-cucu dan jawab dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(341, 64, 402, 'e4_n2_s1', 'Nenek, mengapa kampung Melayu dahulu semuanya berdekatan sungai dan laut?', 1),
(342, 74, 402, 'e4_n2_s1', 'Betulkah semua orang Melayu dahulu hanya menjadi petani?', 2),
(343, NULL, 402, 'e4_n2_s1', 'Baca catatan ini dahulu, jangan terus meneka-neka.', 3),
(344, 64, 402, 'e4_n2_s1', 'Nenek, kalau kami tersilap, kami akan mengajar orang lain dengan salah.', 4),
(345, 69, 402, 'e4_n2_s2', 'Datuk aku pelombong dan peniaga di pekan. Dia tak pernah ke ladang.', 1),
(346, 65, 402, 'e4_n2_s2', 'Datukku bekerja di ladang. Kami tinggal di pinggir bandar.', 2),
(347, 65, 402, 'e4_n2_s2', 'Kedua-duanya betul. Padankan sebelum kamu berebut cerita.', 3),
(348, NULL, 402, 'e4_n2_s2', 'Padankan petempatan dan pekerjaan setiap kaum.', 4),
(349, 70, 402, 'e4_n2_s3', 'Datuk nenek kami berpindah-randah dalam hutan. Kami bukan di satu negeri sahaja.', 1),
(350, 74, 402, 'e4_n2_s3', 'Nenek, apa yang mereka makan? Mereka tidak ke pasar?', 2),
(351, NULL, 402, 'e4_n2_s3', 'Mereka berburu, mengutip hasil hutan dan membuat kraf.', 3),
(352, NULL, 402, 'e4_n2_s3', 'Tetapi di negeri mana mereka paling ramai? Baca dahulu.', 4),
(353, 67, 402, 'e4_n2_s4', 'Nenek, kaum kami tinggal di tepi sungai. Betulkah?', 1),
(354, 68, 402, 'e4_n2_s4', 'Kaum kami tinggal berhampiran lembah sungai dan menjadi petani.', 2),
(355, NULL, 402, 'e4_n2_s4', 'Tetapi kaum lain di pedalaman dan di pantai. Padankan semuanya.', 3),
(356, NULL, 402, 'e4_n2_s4', 'Aku mahu cerita yang benar, bukan sekadar cerita yang sedap.', 4),
(357, 66, 402, 'e4_n2_s5', 'Datuk saya mengusahakan padi di pedalaman. Kaum kami tinggal jauh dari pantai.', 1),
(358, 71, 402, 'e4_n2_s5', 'Kaum kami pula bekerja sebagai petani atau nelayan.', 2),
(359, NULL, 402, 'e4_n2_s5', 'Ada kaum lain di pantai yang membuat perahu. Padankan semuanya.', 3),
(360, NULL, 402, 'e4_n2_s5', 'Setiap kaum ada peranannya. Jangan tertukar.', 4),
(361, 74, 402, 'e4_n2_s6', 'Nenek, mengapa kini kita boleh tinggal dalam satu kawasan perumahan sedangkan dahulu berasingan?', 1),
(362, NULL, 402, 'e4_n2_s6', 'Susun peristiwa ini mengikut urutan, dan jawapannya akan nampak.', 2),
(363, 64, 402, 'e4_n2_s6', 'Nenek, kalau susunannya salah, kami akan menyangka kita sentiasa begini.', 3),
(364, NULL, 402, 'e4_n2_s6', 'Mari lihat bagaimana perubahan ini berlaku.', 4),
(365, 72, 402, 'e4_n2_s7', 'Nenek, mereka kata aku nakal kerana mempermain-mainkan raja. Tapi aku bijak, bukan?', 1),
(366, 74, 402, 'e4_n2_s7', 'Nenek, bagaimana Si Luncai boleh terlepas daripada hukuman raja?', 2),
(367, NULL, 402, 'e4_n2_s7', 'Susun kejadiannya satu demi satu. Jangan terlompat bahagian.', 3),
(368, NULL, 402, 'e4_n2_s7', 'Cerita rakyat tiada pemilik khusus, tetapi dimiliki bersama.', 4),
(369, 73, 402, 'e4_n2_s8', 'Aku Puteri Santubong. Aku menenun kain untuk kampung kami.', 1),
(370, 74, 402, 'e4_n2_s8', 'Nenek, mengapa mereka bertukar menjadi gunung?', 2),
(371, 74, 402, 'e4_n2_s8', 'Mereka melanggar syarat tidak boleh bergaduh sesama sendiri.', 3),
(372, NULL, 402, 'e4_n2_s8', 'Padankan watak dan peranan mereka dalam cerita ini.', 4),
(373, 63, 403, NULL, 'Tugasku ialah memastikan semua kanak-kanak bermain bersama, tanpa mengira kaum, supaya mereka belajar bekerjasama, {nama}.', 1),
(374, 63, 403, NULL, 'Aku belajar bahawa permainan tradisional memupuk kerjasama, kreativiti dan persaingan sihat. Toleransi antara kaum ialah asas perpaduan.', 2),
(375, 63, 403, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga gelanggang permainan tradisional. Dengar sorakan kanak-kanak dan jawab dengan bijak. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(376, 74, 403, 'e4_n3_s1', 'Tok, kenapa congkak dimainkan di anjung tetapi wau di padang?', 1),
(377, 64, 403, 'e4_n3_s1', 'Aku tak faham mana yang permainan anjung, laman dan lapang.', 2),
(378, NULL, 403, 'e4_n3_s1', 'Cari lima petunjuk di gelanggang ini untuk kategori permainan.', 3),
(379, 74, 403, 'e4_n3_s1', 'Kalau tersalah letak, kami bermain di tempat yang tidak sesuai.', 4),
(380, NULL, 403, 'e4_n3_s2', 'Seorang kanak-kanak tersilap menyebut batu seremban sebagai congkak. Mereka berbalah.', 1),
(381, 65, 403, 'e4_n3_s2', 'Tok, aku pasti congkak yang menggunakan lubang di papan.', 2),
(382, 74, 403, 'e4_n3_s2', 'Yang itu Go, kerana ada buah hitam dan putih. Betulkah?', 3),
(383, NULL, 403, 'e4_n3_s2', 'Padankan permainan dengan cara bermain supaya tiada lagi pertengkaran.', 4),
(384, 74, 403, 'e4_n3_s3', 'Tok, permainan lapang dimainkan di mana-mana sahaja, bukan?', 1),
(385, 66, 403, 'e4_n3_s3', 'Tetapi aku dengar sepak manggis dari Sabah, bukan dari Sarawak.', 2),
(386, 67, 403, 'e4_n3_s3', 'Dan tibau dimainkan oleh kaum Melanau di Sarawak.', 3),
(387, NULL, 403, 'e4_n3_s3', 'Padankan permainan lapang dengan ciri dan tempatnya.', 4),
(388, 69, 403, 'e4_n3_s4', 'Tok, yoyo Cina dan go itu dari China. Orang Melayu tidak main, bukan?', 1),
(389, 65, 403, 'e4_n3_s4', 'Chaturangam dan paramapadham dari India. Kami main di rumah.', 2),
(390, 65, 403, 'e4_n3_s4', 'Permainan di negara kita ada unsur dari Timur Tengah, China, India dan Alam Melayu.', 3),
(391, NULL, 403, 'e4_n3_s4', 'Baca kad ini dan tentukan permainan yang seperti catur.', 4),
(392, 74, 403, 'e4_n3_s5', 'Tok, bolehkah bola sepak dan badminton dikatakan permainan warisan kebangsaan juga?', 1),
(393, 74, 403, 'e4_n3_s5', 'Tidak semua permainan tercatat dalam senarai itu.', 2),
(394, 66, 403, 'e4_n3_s5', 'Congkak dan sepak raga ada, bukan?', 3),
(395, NULL, 403, 'e4_n3_s5', 'Baca papan kenyataan ini sebelum menjawab.', 4),
(396, 66, 403, 'e4_n3_s6', 'Dalam cerita nenek, ayam gergasi itu membawa orang kampung terbang. Ke mana mereka jatuh?', 1),
(397, 71, 403, 'e4_n3_s6', 'Di mana-mana ayam itu mengibarkan sayap, di situlah mereka membina petempatan.', 2),
(398, NULL, 403, 'e4_n3_s6', 'Kita cari tiga petunjuk legenda ini di gambar.', 3),
(399, 66, 403, 'e4_n3_s6', 'Kalau tersilap, cerita asal usul kaum kami menjadi kabur.', 4),
(400, 74, 403, 'e4_n3_s7', 'Mereka bercakap bahasa lain dan ketawa. Aku rasa mereka mengejek kami.', 1),
(401, 69, 403, 'e4_n3_s7', 'Kami hanya bercakap Hokkien dengan datuk. Mengapa kamu marah?', 2),
(402, 69, 403, 'e4_n3_s7', 'Kalau tidak bertoleransi, perbalahan kecil menjadi pergaduhan besar.', 3),
(403, NULL, 403, 'e4_n3_s7', 'Baca kad ini dan fikirkan kepentingan toleransi antara kaum.', 4),
(404, 74, 403, 'e4_n3_s8', 'Tok, untuk apa kita simpan semua budaya lama ini? Siapa yang peduli?', 1),
(405, 64, 403, 'e4_n3_s8', 'Pelancong itu peduli. Mereka datang kerana keunikan kita.', 2),
(406, NULL, 403, 'e4_n3_s8', 'Dan jika tidak dikongsi, kita hanya menyimpan seorang diri. Padankan akibatnya.', 3),
(407, NULL, 403, 'e4_n3_s8', 'Aku akan padankan kepentingan menghargai keunikan dan berkongsi maklumat.', 4),
(408, 81, 501, NULL, 'Tugasku ialah mencatat agama dan kepercayaan dengan adil dan hormat. Satu catatan yang salah boleh menyinggung hati sebuah masyarakat, {nama}.', 1),
(409, 81, 501, NULL, 'Aku belajar bahawa setiap agama menuntut penganutnya melakukan perkara baik. Menghormati agama kaum lain menjamin kehidupan aman dan sejahtera.', 2),
(410, 81, 501, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengkaji yang membawa buku nota lapangan. Catat dengan teliti dan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(411, 84, 501, 'e5_n1_s1', 'Kami Islam hanya menyembah Allah Yang Maha Esa. Tetapi kad pengasas di sini bercampur-baur.', 1),
(412, 86, 501, 'e5_n1_s1', 'Aku Buddha, dan kad ini mengatakan Guru Nanak pengasas agamaku!', 2),
(413, 88, 501, 'e5_n1_s1', 'Itu salah, kerana Guru Nanak pengasas agama kami. Kad ini mesti dibetulkan.', 3),
(414, NULL, 501, 'e5_n1_s1', 'Padankan agama dengan pengasas atau asas ajarannya.', 4),
(415, 85, 501, 'e5_n1_s2', 'Cikgu, jangan letak Bible di sebelah al-Quran tanpa label yang betul.', 1),
(416, 84, 501, 'e5_n1_s2', 'Kitab kami al-Quran, dan ajarannya berpandukan Hadis juga.', 2),
(417, 87, 501, 'e5_n1_s2', 'Veda kitab suci agama Hindu. Jangan tersilap.', 3),
(418, NULL, 501, 'e5_n1_s2', 'Padankan kitab dan buku dengan agamanya.', 4),
(419, 98, 501, 'e5_n1_s3', 'Kavitha, apakah yang penganut Hindu percaya tentang kehidupan selepas mati?', 1),
(420, 87, 501, 'e5_n1_s3', 'Aku percaya Hukum Karma, tetapi aku tak pasti bagaimana menerangkannya.', 2),
(421, NULL, 501, 'e5_n1_s3', 'Baca kad ini dengan teliti.', 3),
(422, 98, 501, 'e5_n1_s3', 'Jawab betul-betul, supaya kawan-kawan lain faham dan tidak mengejek.', 4),
(423, 89, 501, 'e5_n1_s4', 'Mereka sangka Konfusius dan Tao sama. Padahal tidak sama.', 1),
(424, 86, 501, 'e5_n1_s4', 'Konfusius mementingkan moral dalam buku Analek, bukan?', 2),
(425, 89, 501, 'e5_n1_s4', 'Betul. Tetapi tolong baca kad ini dan terangkan perbezaan itu.', 3),
(426, NULL, 501, 'e5_n1_s4', 'Aku akan membaca dan menjawab dengan hormat.', 4),
(427, 98, 501, 'e5_n1_s5', 'Cikgu, mengapa ada begitu banyak agama di sini?', 1),
(428, NULL, 501, 'e5_n1_s5', 'Setiap agama sampai dengan cara tertentu. Cuba baca nota ini.', 2),
(429, 84, 501, 'e5_n1_s5', 'Jangan tersilap, kerana ada yang menyangka semua dibawa orang asing sahaja.', 3),
(430, NULL, 501, 'e5_n1_s5', 'Aku akan baca nota dan jawab.', 4),
(431, 85, 501, 'e5_n1_s6', 'Setiap Ahad kami ke gereja.', 1),
(432, 88, 501, 'e5_n1_s6', 'Kami percaya satu Tuhan, Waheguru.', 2),
(433, 84, 501, 'e5_n1_s6', 'Kami ada dua teras: Rukun Islam dan Rukun Iman.', 3),
(434, NULL, 501, 'e5_n1_s6', 'Padankan dahulu amalan dengan agamanya.', 4),
(435, 98, 501, 'e5_n1_s7', 'Cikgu, pelancong itu panggil semua rumah ibadat \'temple\'. Betulkah?', 1),
(436, 98, 501, 'e5_n1_s7', 'Setiap agama ada nama rumah ibadatnya sendiri.', 2),
(437, NULL, 501, 'e5_n1_s7', 'Cari enam rumah ibadat dan kenal pasti nama masing-masing.', 3),
(438, 98, 501, 'e5_n1_s7', 'Cepat, bas pelancong akan bergerak sebentar lagi.', 4),
(439, 88, 501, 'e5_n1_s8', 'Cikgu, untuk apa kita beragama?', 1),
(440, 85, 501, 'e5_n1_s8', 'Mama kata agama mengajar kita menjadi baik.', 2),
(441, 89, 501, 'e5_n1_s8', 'Tetapi apa kepentingannya kepada masyarakat?', 3),
(442, NULL, 501, 'e5_n1_s8', 'Mari baca kad refleksi ini bersama.', 4),
(443, 82, 502, NULL, 'Tugasku ialah mengingatkan semua orang bahawa kepercayaan setiap kaum perlu difahami dan dihormati, {nama}.', 1),
(444, 82, 502, NULL, 'Aku belajar bahawa kepercayaan masyarakat dipengaruhi oleh alam semesta. Semua agama dan kepercayaan menuntut penganutnya melakukan perkara baik.', 2),
(445, 82, 502, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ketua bomoh Kadazandusun yang menjaga semangat padi. Dengar setiap wakil dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(446, 98, 502, 'e5_n2_s1', 'Bobohizan, mengapa orang percaya gua dan pokok ada roh? Adakah itu agama?', 1),
(447, 91, 502, 'e5_n2_s1', 'Itu kepercayaan kami. Nenek moyang kami menghormati semangat di sekeliling.', 2),
(448, NULL, 502, 'e5_n2_s1', 'Baca kad ini dahulu. Jangan mengejek apa yang belum kita fahami.', 3),
(449, 91, 502, 'e5_n2_s1', 'Namanya mesti disebut dengan betul.', 4),
(450, 91, 502, 'e5_n2_s2', 'Kami suku Mah Meri mengadakan Puja Pantai untuk memohon perlindungan daripada semangat laut.', 1),
(451, 90, 502, 'e5_n2_s2', 'Kami suku Temiar pula mengadakan upacara ritual untuk menghalau kuasa jahat.', 2),
(452, 98, 502, 'e5_n2_s2', 'Mengapa upacara mereka berbeza?', 3),
(453, NULL, 502, 'e5_n2_s2', 'Padankan mereka dengan upacara dan tujuannya.', 4),
(454, 92, 502, 'e5_n2_s3', 'Kami masyarakat Iban percaya Petara akan menyampaikan alamat dan petanda melalui mimpi dan bayangan.', 1),
(455, 83, 502, 'e5_n2_s3', 'Aku Lemambang, penyair upacara Miring. Aku bermula dengan jampi mantera.', 2),
(456, 98, 502, 'e5_n2_s3', 'Tetapi apakah sebenarnya Petara?', 3),
(457, NULL, 502, 'e5_n2_s3', 'Padankan istilah dengan maknanya.', 4),
(458, 94, 502, 'e5_n2_s4', 'Sebelum membuka tanah baharu, kami membaca jampi mantera supaya tiada gangguan kuasa ghaib.', 1),
(459, 98, 502, 'e5_n2_s4', 'Tetapi apa yang dilakukan untuk pesakit itu?', 2),
(460, 94, 502, 'e5_n2_s4', 'Kami mengadakan upacara yang dikenali dengan satu nama.', 3),
(461, NULL, 502, 'e5_n2_s4', 'Baca nota dan beri nama upacara itu.', 4),
(462, 95, 502, 'e5_n2_s5', 'Di Kota Belud kami mengadakan Ngeduang. Keluarga si mati menjamu tetamu sebagai sedekah.', 1),
(463, 98, 502, 'e5_n2_s5', 'Dan di Semporna pula, Bobohizan?', 2),
(464, NULL, 502, 'e5_n2_s5', 'Bajau di pantai timur mengadakan Mag\'ombo untuk menghargai warisan nenek moyang.', 3),
(465, NULL, 502, 'e5_n2_s5', 'Padankan nama upacara dengan lokasi dan maksud.', 4),
(466, 93, 502, 'e5_n2_s6', 'Bobohizan, apakah sebenarnya Kinorohingan? Orang kata ia nama kampung.', 1),
(467, 93, 502, 'e5_n2_s6', 'Kinorohingan ialah Tuhan untuk meminta keselamatan dan perlindungan.', 2),
(468, 98, 502, 'e5_n2_s6', 'Dan Magavau?', 3),
(469, NULL, 502, 'e5_n2_s6', 'Padankan istilah dengan maksudnya.', 4),
(470, 95, 502, 'e5_n2_s7', 'Upacara Mag\'ombo dan Ngeduang berbeza lokasi, tetapi kedua-duanya warisan kami.', 1),
(471, 98, 502, 'e5_n2_s7', 'Di mana kita boleh nampak tanda-tanda upacara itu?', 2),
(472, NULL, 502, 'e5_n2_s7', 'Cari empat petunjuk dalam gambar ini.', 3),
(473, 95, 502, 'e5_n2_s7', 'Jangan terlepas yang di tikar jamuan.', 4),
(474, 83, 502, 'e5_n2_s8', 'Aku Bobohizan, ketua bomoh Kadazandusun.', 1),
(475, 83, 502, 'e5_n2_s8', 'Aku Lemambang, penyair upacara Miring.', 2),
(476, 90, 502, 'e5_n2_s8', 'Aku Tok Batin Temiar, aku mengetuai ritual halau kuasa jahat.', 3),
(477, NULL, 502, 'e5_n2_s8', 'Padankan setiap penjaga adat dengan kaum atau upacaranya.', 4),
(478, 83, 503, NULL, 'Tugasku ialah melagukan syair yang mengajak semua orang memahami hak beragama dan menghormati rumah ibadat, {nama}.', 1),
(479, 83, 503, NULL, 'Aku belajar bahawa Perlembagaan Persekutuan menjamin agama lain boleh diamalkan dengan aman dan damai. Kita juga perlu menjaga adab di rumah ibadat.', 2),
(480, 83, 503, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penyair upacara yang melagukan puji-pujian. Dengar syair dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(481, 98, 503, 'e5_n3_s1', 'Cikgu, bagaimana agama Islam diakui sebagai agama Persekutuan?', 1),
(482, 96, 503, 'e5_n3_s1', 'Parti-parti politik dan pertubuhan menghantar memorandum. Urutannya mesti betul.', 2),
(483, NULL, 503, 'e5_n3_s1', 'Susun kad-kad ini mengikut urutan.', 3),
(484, 98, 503, 'e5_n3_s1', 'Kalau salah, murid akan hafal sejarah yang salah.', 4),
(485, 96, 503, 'e5_n3_s2', 'Beta ialah Ketua Agama Islam di negeri beta, kerana negeri ini mempunyai Raja.', 1),
(486, 97, 503, 'e5_n3_s2', 'Negeriku tiada Raja. Siapa Ketua Agama Islam di sini?', 2),
(487, 98, 503, 'e5_n3_s2', 'Cikgu, bagaimana dengan Kuala Lumpur, Labuan dan Putrajaya?', 3),
(488, NULL, 503, 'e5_n3_s2', 'Padankan setiap peruntukan Perkara 3 dengan isinya.', 4),
(489, 88, 503, 'e5_n3_s3', 'Katanya kami tidak bebas beragama. Betulkah?', 1),
(490, 85, 503, 'e5_n3_s3', 'Aku dengar ada Perkara 11. Apakah isinya?', 2),
(491, NULL, 503, 'e5_n3_s3', 'Baca kad dan padankan fasalnya.', 3),
(492, 88, 503, 'e5_n3_s3', 'Jangan salah, nanti orang percaya kata-kata pemuda itu.', 4),
(493, 98, 503, 'e5_n3_s4', 'Cikgu, rumah ibadat ini macam kuil semua. Boleh masuk sahaja?', 1),
(494, 87, 503, 'e5_n3_s4', 'Tidak boleh. Setiap rumah ibadat ada adab dan namanya sendiri.', 2),
(495, NULL, 503, 'e5_n3_s4', 'Cari enam rumah ibadat dan kenal pasti agamanya.', 3),
(496, 89, 503, 'e5_n3_s4', 'Cepat, sebelum mereka masuk tanpa memahami adab.', 4),
(497, 84, 503, 'e5_n3_s5', 'Masjid Negara di Kuala Lumpur boleh menampung 15 000 jemaah.', 1),
(498, 98, 503, 'e5_n3_s5', 'Tetapi masjid mana yang dibina abad ke-18?', 2),
(499, 84, 503, 'e5_n3_s5', 'Dan Masjid Al-Qadim di Sibu dibina pada 1830.', 3),
(500, NULL, 503, 'e5_n3_s5', 'Padankan masjid dengan maklumatnya.', 4),
(501, 85, 503, 'e5_n3_s6', 'Gereja St. Michael di Sandakan dibina pada tahun 1893.', 1),
(502, 86, 503, 'e5_n3_s6', 'Tokong Cheng Hoon Teng dibina pada tahun 1645.', 2),
(503, 88, 503, 'e5_n3_s6', 'Wadda Gurdwara Sahib pula dibina pada tahun 1901.', 3),
(504, NULL, 503, 'e5_n3_s6', 'Padankan rumah ibadat dengan keistimewaannya.', 4),
(505, 98, 503, 'e5_n3_s7', 'Cikgu, mengapa kita perlu menjaga adab di rumah ibadat orang lain?', 1),
(506, 86, 503, 'e5_n3_s7', 'Aku takut tersilap kerana ada adab yang berbeza.', 2),
(507, 89, 503, 'e5_n3_s7', 'Jika tersilap, penganut boleh terguris hati.', 3),
(508, NULL, 503, 'e5_n3_s7', 'Baca kad ini dan fahamkan dahulu sebabnya.', 4),
(509, 98, 503, 'e5_n3_s8', 'Cikgu, saya sudah faham. Tetapi bagaimana hendak merumuskannya?', 1),
(510, 84, 503, 'e5_n3_s8', 'Kami perlu menghormati supaya tidak berbalah.', 2),
(511, 88, 503, 'e5_n3_s8', 'Dan supaya persefahaman dan silaturahim terjaga.', 3),
(512, NULL, 503, 'e5_n3_s8', 'Padankan rumusan dengan alasannya.', 4),
(513, 101, 601, NULL, 'Tugasku ialah membuat hiasan untuk semua perayaan. Jika aku tersilap hiasan atau tarikh, pelanggan akan berasa perayaan mereka tidak dihormati, {nama}.', 1),
(514, 101, 601, NULL, 'Aku belajar bahawa perayaan disambut penuh muhibah dan kita wajar menghormati perayaan kaum lain demi masyarakat yang harmoni.', 2),
(515, 101, 601, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penggiat kraf yang membuat hiasan perayaan. Dengar tempahan pelanggan dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(516, 104, 601, 'e6_n1_s1', 'Aku menempah hiasan Aidilfitri. Tarikhnya tertulis 1 Syawal, bukan?', 1),
(517, 106, 601, 'e6_n1_s1', 'Tahun Baharu Cina kami pada hari pertama kalendar Cina. Jangan terbalik.', 2),
(518, 108, 601, 'e6_n1_s1', 'Dan Krismas pada 25 Disember. Jangan tertukar dengan Gawai, ya.', 3),
(519, NULL, 601, 'e6_n1_s1', 'Padankan perayaan dengan tarikhnya sebelum hiasan dihantar.', 4),
(520, 104, 601, 'e6_n1_s2', 'Aku keliru antara Aidilfitri dan Aidiladha. Apa yang berbeza?', 1),
(521, 113, 601, 'e6_n1_s2', 'Kawanku kata dua-duanya hari raya untuk bergembira sahaja.', 2),
(522, NULL, 601, 'e6_n1_s2', 'Baca kad ini dahulu dan tentukan perayaan yang melibatkan ibadah korban.', 3),
(523, 104, 601, 'e6_n1_s2', 'Jangan tersilap, nanti hiasan tidak sesuai.', 4),
(524, 106, 601, 'e6_n1_s3', 'Tahun Baharu Cina bermula dengan makan malam keluarga. Selepas itu apa lagi?', 1),
(525, 107, 601, 'e6_n1_s3', 'Kata nenek perayaannya berlanjutan sampai hari Chap Goh Meh.', 2),
(526, NULL, 601, 'e6_n1_s3', 'Susun kegiatan itu mengikut urutan.', 3),
(527, 106, 601, 'e6_n1_s3', 'Jika silap, keluarga akan terlepas hari penting.', 4),
(528, 105, 601, 'e6_n1_s4', 'Deepavali disambut pada bulan Aippasi. Kami menghias rumah dengan kolam dan pelita.', 1),
(529, 110, 601, 'e6_n1_s4', 'Vaisakhi pula pada bulan Vaisakh, dengan sembahyang di Gurdwara.', 2),
(530, 105, 601, 'e6_n1_s4', 'Dan Thaipusam di bulan ke-10, ada pembayar niat.', 3),
(531, NULL, 601, 'e6_n1_s4', 'Padankan perayaan dengan cirinya.', 4),
(532, 111, 601, 'e6_n1_s5', 'Gawai kami pada 1 Jun. Kami bersyukur atas hasil tani, dan ngajat ditarikan di rumah panjang.', 1),
(533, 109, 601, 'e6_n1_s5', 'Kaamatan kami pada bulan Mei, dengan Magavau oleh Bobohizan.', 2),
(534, 111, 601, 'e6_n1_s5', 'Jangan campur, kerana Gawai bukan Kaamatan.', 3),
(535, NULL, 601, 'e6_n1_s5', 'Padankan perayaan dengan ciri-cirinya.', 4),
(536, 108, 601, 'e6_n1_s6', 'Krismas pada 25 Disember. Kami memperingati kelahiran Jesus Christ.', 1),
(537, 107, 601, 'e6_n1_s6', 'Wesak pula pada bulan Mei. Kami memandikan patung Buddha Siddharta.', 2),
(538, 113, 601, 'e6_n1_s6', 'Dan mengapa mandi patung? Apa maknanya?', 3),
(539, NULL, 601, 'e6_n1_s6', 'Baca kad ini dan padankan perayaan dengan cirinya.', 4),
(540, 90, 601, 'e6_n1_s7', 'Suku Jakun menyebutnya Tahon Baro, dan suku Semai menyebutnya Jis Pai.', 1),
(541, 91, 601, 'e6_n1_s7', 'Suku Mah Meri menyebutnya Tawun Empai. Betulkah?', 2),
(542, 113, 601, 'e6_n1_s7', 'Dan suku Temuan menyebutnya apa?', 3),
(543, NULL, 601, 'e6_n1_s7', 'Padankan suku dengan nama sambutannya.', 4),
(544, 114, 601, 'e6_n1_s8', 'Setiap Jun, kapal kami dihias indah. Tahukah kamu perayaan apa ini?', 1),
(545, 113, 601, 'e6_n1_s8', 'Nelayan itu kata perayaan ini ada penaung. Siapa dia?', 2),
(546, NULL, 601, 'e6_n1_s8', 'Baca papan perayaan ini dengan teliti sebelum menjawab.', 3),
(547, 114, 601, 'e6_n1_s8', 'Jangan tersilap, nanti pelancong menyebarkan kisah salah.', 4),
(548, 102, 602, NULL, 'Tugasku ialah membawa anak-anak pulang beraya dan membandingkan cara dahulu dengan cara kini, supaya mereka tahu tradisi tidak hilang, {nama}.', 1),
(549, 102, 602, NULL, 'Aku belajar bahawa cara sambutan perayaan berubah, tetapi amalan seperti balik kampung, duit raya dan kunjung-mengunjung kekal sehingga kini.', 2),
(550, 102, 602, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ibu moden yang pulang beraya ke kampung. Dengar cerita nenek dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(551, 113, 602, 'e6_n2_s1', 'Mak, mengapa kita ada banyak perayaan? Tujuannya sama ke?', 1),
(552, 112, 602, 'e6_n2_s1', 'Tidak sama. Ada perayaan agama, tahun baharu, kesyukuran dan banyak lagi.', 2),
(553, NULL, 602, 'e6_n2_s1', 'Padankan tujuan dengan perayaan yang diraikan untuk tujuan itu.', 3),
(554, 113, 602, 'e6_n2_s1', 'Kalau tersilap, aku akan beritahu kawan perkara yang salah.', 4),
(555, 113, 602, 'e6_n2_s2', 'Nenek, kenapa dulu hantar kad? Kini cukup tekan butang sahaja.', 1),
(556, 112, 602, 'e6_n2_s2', 'Dahulu kad dikirim melalui pos atau diserahkan sendiri.', 2),
(557, NULL, 602, 'e6_n2_s2', 'Padankan cara dahulu dan kini.', 3),
(558, 112, 602, 'e6_n2_s2', 'Jangan terbalik, nanti cucu salah faham.', 4),
(559, 112, 602, 'e6_n2_s3', 'Dahulu kami bergambar di kedai gambar dengan kamera besar.', 1),
(560, 113, 602, 'e6_n2_s3', 'Mana buktinya, nenek? Gambar ini kabur.', 2),
(561, NULL, 602, 'e6_n2_s3', 'Cari empat bukti dalam gambar ini.', 3),
(562, 112, 602, 'e6_n2_s3', 'Teliti, cucu.', 4),
(563, 105, 602, 'e6_n2_s4', 'Kolam kami kini dibuat dengan beras atau hampas kelapa berwarna-warni.', 1),
(564, 112, 602, 'e6_n2_s4', 'Dahulu kolam dibuat daripada tepung.', 2),
(565, 113, 602, 'e6_n2_s4', 'Mana kolam yang betul?', 3),
(566, NULL, 602, 'e6_n2_s4', 'Cari empat bukti dalam gambar ini.', 4),
(567, 106, 602, 'e6_n2_s5', 'Dulu datuk makan besar di rumah. Kini kami ke restoran. Salahkah?', 1),
(568, 112, 602, 'e6_n2_s5', 'Tradisinya masih ada, cuma tempatnya berubah.', 2),
(569, NULL, 602, 'e6_n2_s5', 'Baca nota ini dan tentukan perubahannya.', 3),
(570, 106, 602, 'e6_n2_s5', 'Jangan tersilap, supaya datukku tidak berkecil hati.', 4),
(571, 113, 602, 'e6_n2_s6', 'Nek, kenapa tidak beli sahaja? Kan lebih senang.', 1),
(572, 112, 602, 'e6_n2_s6', 'Dahulu kuih dibuat dengan bahan dan kaedah tradisional, secara gotong-royong.', 2),
(573, NULL, 602, 'e6_n2_s6', 'Baca kad ini dan padankan perubahannya.', 3),
(574, 112, 602, 'e6_n2_s6', 'Faham dahulu, baru bandingkan.', 4),
(575, 113, 602, 'e6_n2_s7', 'Nek, kuih ini beli sahaja. Tradisi sudah hilang ke?', 1),
(576, 112, 602, 'e6_n2_s7', 'Peralatan moden memudahkan penyediaan kuih, dan kuih raya juga mudah dibeli.', 2),
(577, NULL, 602, 'e6_n2_s7', 'Cari empat bukti dalam gambar ini.', 3),
(578, 113, 602, 'e6_n2_s7', 'Cepat, kedai nak tutup.', 4),
(579, 109, 602, 'e6_n2_s8', 'Dahulu pemenang dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban.', 1),
(580, 113, 602, 'e6_n2_s8', 'Dan kini bagaimana?', 2),
(581, NULL, 602, 'e6_n2_s8', 'Cari empat bukti dalam gambar ini.', 3),
(582, 109, 602, 'e6_n2_s8', 'Teliti, kerana ini warisan kami.', 4),
(583, 113, 602, 'e6_n2_s9', 'Nek, apa yang tak berubah dari dulu hingga sekarang?', 1),
(584, 112, 602, 'e6_n2_s9', 'Banyak. Tetapi kita perlu pilih yang betul.', 2),
(585, NULL, 602, 'e6_n2_s9', 'Baca kad dan tentukan amalan yang kekal.', 3),
(586, 112, 602, 'e6_n2_s9', 'Pilih dengan teliti.', 4),
(587, 103, 603, NULL, 'Tugasku ialah melayan pelanggan semua kaum dengan hormat. Jika aku tersilap, perayaan mereka akan tersinggung, {nama}.', 1),
(588, 103, 603, NULL, 'Aku belajar bahawa menghormati kepelbagaian sambutan perayaan mengekalkan keamanan dan keharmonian negara.', 2),
(589, 103, 603, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, peniaga rumah kedai yang menjual keperluan semua perayaan. Layan setiap pelanggan dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(590, 104, 603, 'e6_n3_s1', 'Perayaan apakah yang diraikan melalui Rumah Terbuka Malaysia?', 1),
(591, 106, 603, 'e6_n3_s1', 'Aku dengar ada enam. Tetapi aku tak ingat semuanya.', 2),
(592, NULL, 603, 'e6_n3_s1', 'Baca kad ini dan tentukan senarai yang betul.', 3),
(593, 104, 603, 'e6_n3_s1', 'Jangan tersilap, nanti pelanggan lain kecewa.', 4),
(594, 104, 603, 'e6_n3_s2', 'Mengapa kita perlu meraikan perayaan bersama keluarga?', 1),
(595, 113, 603, 'e6_n3_s2', 'Hanya telefon sahaja pun cukup, bukan?', 2),
(596, NULL, 603, 'e6_n3_s2', 'Baca kad ini dan tentukan kepentingan meraikan perayaan bersama keluarga.', 3),
(597, 104, 603, 'e6_n3_s2', 'Jawab betul-betul, kerana aku mahu ajar anakku.', 4),
(598, 106, 603, 'e6_n3_s3', 'Aku mahu melawat rumah jiran Melayu. Bagaimana adabnya?', 1),
(599, NULL, 603, 'e6_n3_s3', 'Setiap perayaan ada adab tersendiri.', 2),
(600, NULL, 603, 'e6_n3_s3', 'Baca kad ini dan tentukan kepentingan menghormati kepelbagaian sambutan dan adab perayaan.', 3),
(601, 106, 603, 'e6_n3_s3', 'Aku mahu elakkan salah faham.', 4),
(602, 111, 603, 'e6_n3_s4', 'Dahulu Gawai hanya diraikan petani kaum Dayak dengan upacara ritual. Kini ramai tetamu datang.', 1),
(603, 106, 603, 'e6_n3_s4', 'Aku datang kerana jiranku jemput, tetapi aku keliru.', 2),
(604, NULL, 603, 'e6_n3_s4', 'Padankan sambutan Gawai dan Unduk Ngadau dahulu dengan kini.', 3),
(605, 111, 603, 'e6_n3_s4', 'Betulkan, supaya tetamu faham.', 4),
(606, 113, 603, 'e6_n3_s5', 'Mana satu cara dahulu dan mana satu cara kini?', 1),
(607, 105, 603, 'e6_n3_s5', 'Aku tahu kolam dahulu daripada tepung.', 2),
(608, 106, 603, 'e6_n3_s5', 'Dan makan besar dahulu di rumah.', 3),
(609, NULL, 603, 'e6_n3_s5', 'Padankan perubahan setiap tradisi.', 4),
(610, 113, 603, 'e6_n3_s6', 'Cikgu kata kita kena buat analisis SWOT tentang warisan perayaan. Apa itu?', 1),
(611, 113, 603, 'e6_n3_s6', 'Kekuatan, kelemahan, peluang dan halangan.', 2),
(612, NULL, 603, 'e6_n3_s6', 'Padankan setiap istilah SWOT dengan contohnya.', 3),
(613, 113, 603, 'e6_n3_s6', 'Jangan campur aduk, nanti markah dipotong.', 4),
(614, 104, 603, 'e6_n3_s7', 'Boleh ringkaskan perbezaan dahulu dan kini?', 1),
(615, 113, 603, 'e6_n3_s7', 'Dan apa yang masih kekal?', 2),
(616, NULL, 603, 'e6_n3_s7', 'Padankan amalan dengan penerangannya.', 3),
(617, 104, 603, 'e6_n3_s7', 'Jangan lupa Rumah Terbuka.', 4),
(618, 121, 701, NULL, 'Tugasku merakam siaran khas tentang Perdana Menteri. Jika tarikh atau nama salah, penonton akan menerima sejarah yang salah, {nama}.', 1),
(619, 121, 701, NULL, 'Aku belajar bahawa pemimpin yang berjasa wajar dihormati dan pengorbanan mereka dijadikan iktibar.', 2),
(620, 121, 701, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wartawan muda di Pejabat Perdana Menteri. Tanya dengan teliti dan catat dengan betul. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(621, 132, 701, 'e7_n1_s1', 'Penerbit mahu aku menyebut Perdana Menteri dipilih terus oleh rakyat. Betul ke?', 1),
(622, 132, 701, 'e7_n1_s1', 'Jangan tergesa-gesa. Baca nota ini dahulu sebelum bersiaran.', 2),
(623, NULL, 701, 'e7_n1_s1', 'Aku akan semak siapa yang melantik Perdana Menteri dan apa jawatannya.', 3),
(624, 132, 701, 'e7_n1_s1', 'Cepat, siaran bermula sebentar lagi.', 4),
(625, NULL, 701, 'e7_n1_s2', 'Pita ini bercampur. Siapa dahulu, siapa kemudian?', 1),
(626, 122, 701, 'e7_n1_s2', 'Kalau terbalik, penonton akan belajar sejarah yang songsang.', 2),
(627, NULL, 701, 'e7_n1_s2', 'Aku akan susun mengikut tarikh mula berkhidmat.', 3),
(628, 122, 701, 'e7_n1_s2', 'Ingat, tarikhnya mesti betul.', 4),
(629, NULL, 701, 'e7_n1_s3', 'Rakaman ini kabur. Mana buktinya kemerdekaan dicapai melalui rundingan?', 1),
(630, 124, 701, 'e7_n1_s3', 'Rakyat bersorak apabila kemerdekaan diisytiharkan.', 2),
(631, NULL, 701, 'e7_n1_s3', 'Aku akan cari bukti dalam gambar.', 3),
(632, NULL, 701, 'e7_n1_s3', 'Tunjukkan dengan tepat.', 4),
(633, 124, 701, 'e7_n1_s4', 'Tunku, boleh ceritakan latar hidup tuan?', 1),
(634, 124, 701, 'e7_n1_s4', 'Aku dilahirkan di Alor Setar dan belajar undang-undang di Cambridge.', 2),
(635, 122, 701, 'e7_n1_s4', 'Aku pula bimbang tarikh dan gelaran tersilap.', 3),
(636, NULL, 701, 'e7_n1_s4', 'Aku akan padankan biodata dengan maklumat yang betul.', 4),
(637, NULL, 701, 'e7_n1_s5', 'Skripku kata Tun Razak menutup semua pejabat kerajaan. Betulkah?', 1),
(638, 125, 701, 'e7_n1_s5', 'Itu salah. Aku menubuhkan Majlis Gerakan Negara.', 2),
(639, NULL, 701, 'e7_n1_s5', 'Aku akan semak nota pencapaian.', 3),
(640, NULL, 701, 'e7_n1_s5', 'Baca betul-betul.', 4),
(641, NULL, 701, 'e7_n1_s6', 'Di manakah rumah kelahiran Tun Razak?', 1),
(642, 125, 701, 'e7_n1_s6', 'Di Pulau Keladi, Pekan, Pahang.', 2),
(643, 122, 701, 'e7_n1_s6', 'Dan pelajarannya di mana?', 3),
(644, NULL, 701, 'e7_n1_s6', 'Aku akan padankan biodata dengan tepat.', 4),
(645, NULL, 701, 'e7_n1_s7', 'Mengapa Tun Hussein digelar Bapa Perpaduan?', 1),
(646, 126, 701, 'e7_n1_s7', 'Aku memperkenalkan program yang menggalakkan perpaduan dalam kalangan rakyat.', 2),
(647, 122, 701, 'e7_n1_s7', 'Aku keliru antara ASN dengan program perpaduan.', 3),
(648, NULL, 701, 'e7_n1_s7', 'Aku akan padankan kedua-duanya.', 4),
(649, 122, 701, 'e7_n1_s8', 'Siapa Bapa Kemerdekaan? Siapa Bapa Pembangunan?', 1),
(650, 122, 701, 'e7_n1_s8', 'Ada dua yang hampir serupa. Jangan keliru.', 2),
(651, NULL, 701, 'e7_n1_s8', 'Aku akan padankan gelaran dengan pemimpinnya.', 3),
(652, 122, 701, 'e7_n1_s8', 'Teliti, nanti penonton menegur.', 4),
(653, 122, 702, NULL, 'Tugasku mengajar murid mengenali tugas Perdana Menteri. Jika aku tersilap, murid akan mempelajari fakta yang salah, {nama}.', 1),
(654, 122, 702, NULL, 'Aku belajar bahawa kepemimpinan yang berwibawa memajukan ekonomi, menjamin keselamatan dan menyatukan rakyat.', 2),
(655, 122, 702, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, guru Sejarah di bilik darjah. Dengar soalan murid dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(656, 123, 702, 'e7_n2_s1', 'Cikgu, gambar ini tugas Perdana Menteri yang mana?', 1),
(657, 127, 702, 'e7_n2_s1', 'Aku mengadakan mesyuarat dengan Ketua-ketua Setiausaha Kementerian.', 2),
(658, 126, 702, 'e7_n2_s1', 'Aku bertemu Presiden Anwar Sadat pada 1977.', 3),
(659, NULL, 702, 'e7_n2_s1', 'Aku akan padankan gambar dengan tugasnya.', 4),
(660, 123, 702, 'e7_n2_s2', 'Cikgu, siapa yang melantik Jemaah Menteri?', 1),
(661, 132, 702, 'e7_n2_s2', 'Perdana Menteri mencadangkan senarai, dan aku melantik mereka.', 2),
(662, NULL, 702, 'e7_n2_s2', 'Dan siapa yang mempengerusikan mesyuarat Jemaah Menteri?', 3),
(663, NULL, 702, 'e7_n2_s2', 'Aku akan padankan tugas dengan penjelasannya.', 4),
(664, 123, 702, 'e7_n2_s3', 'Tun Dr. Mahathir doktor perubatan, bukan?', 1),
(665, 127, 702, 'e7_n2_s3', 'Aku lahir di Alor Setar dan belajar perubatan di Singapura.', 2),
(666, NULL, 702, 'e7_n2_s3', 'Dan klinik beliau masih beroperasi hari ini.', 3),
(667, NULL, 702, 'e7_n2_s3', 'Aku akan padankan biodata dengan maklumat yang betul.', 4),
(668, 123, 702, 'e7_n2_s4', 'Cikgu, apa bukti Wawasan 2020 itu nyata?', 1),
(669, 127, 702, 'e7_n2_s4', 'Putrajaya, KLIA, Menara Berkembar Petronas dan HICOM.', 2),
(670, NULL, 702, 'e7_n2_s4', 'Cari buktinya dalam gambar ini.', 3),
(671, NULL, 702, 'e7_n2_s4', 'Aku akan cari empat bukti pencapaian.', 4),
(672, 123, 702, 'e7_n2_s5', 'Bukankah Tun Dr. Mahathir hanya sekali jadi Perdana Menteri?', 1),
(673, 127, 702, 'e7_n2_s5', 'Tidak. Aku menjadi Perdana Menteri kali kedua pada 2018.', 2),
(674, 127, 702, 'e7_n2_s5', 'Dan apa wawasan baharu beliau?', 3),
(675, NULL, 702, 'e7_n2_s5', 'Aku akan baca nota dan tentukan jawapannya.', 4),
(676, 123, 702, 'e7_n2_s6', 'Tun Abdullah ini belajar apa, cikgu?', 1),
(677, 128, 702, 'e7_n2_s6', 'Aku belajar Pengajian Islam di Universiti Malaya.', 2),
(678, NULL, 702, 'e7_n2_s6', 'Dan beliau pernah menjadi Setiausaha MAGERAN.', 3),
(679, NULL, 702, 'e7_n2_s6', 'Aku akan padankan biodata dengan maklumat yang betul.', 4),
(680, 123, 702, 'e7_n2_s7', 'Koridor Wilayah Ekonomi dan Pelan Integriti Nasional sama ke, cikgu?', 1),
(681, 128, 702, 'e7_n2_s7', 'Tidak. Satu untuk ekonomi, satu untuk akhlak.', 2),
(682, 128, 702, 'e7_n2_s7', 'Baca nota ini dan tentukan fungsi setiap satu.', 3),
(683, NULL, 702, 'e7_n2_s7', 'Aku akan semak nota sebelum menjawab.', 4),
(684, 123, 702, 'e7_n2_s8', 'Cikgu, apa moto 1Malaysia?', 1),
(685, 129, 702, 'e7_n2_s8', 'Rakyat Didahulukan, Pencapaian Diutamakan.', 2),
(686, 129, 702, 'e7_n2_s8', 'Dan apa tujuan Gagasan 1Malaysia?', 3),
(687, NULL, 702, 'e7_n2_s8', 'Aku akan padankan biodata dan pencapaian Dato\' Sri Najib.', 4),
(688, 123, 702, 'e7_n2_s9', 'Cikgu, apa sumbangan Tan Sri Muhyiddin?', 1),
(689, 130, 702, 'e7_n2_s9', 'Aku menubuhkan Majlis Tindakan Ekonomi dan membantu rakyat semasa PKP.', 2),
(690, 131, 702, 'e7_n2_s9', 'Aku memperkenalkan konsep Keluarga Malaysia.', 3),
(691, NULL, 702, 'e7_n2_s9', 'Aku akan padankan sumbangan kedua-duanya.', 4),
(692, 123, 703, NULL, 'Tugasku melengkapkan album kad koleksi dengan betul. Jika silap, projek sekolah akan menyalahkan jasa pemimpin, {nama}.', 1),
(693, 123, 703, NULL, 'Aku belajar bahawa menghormati pemimpin dan menyokong kepimpinan negara memastikan kedaulatan dan perpaduan rakyat kekal terpelihara.', 2),
(694, 123, 703, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid penyelidik dengan album kad koleksi. Semak setiap halaman dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(695, 122, 703, 'e7_n3_s1', 'Pada zaman Kesultanan Melayu Melaka, siapakah ketua pembesar kerajaan?', 1),
(696, NULL, 703, 'e7_n3_s1', 'Kalau tidak silap, Perdana Menteri.', 2),
(697, NULL, 703, 'e7_n3_s1', 'Aku akan baca nota perbandingan sebelum menulis.', 3),
(698, 122, 703, 'e7_n3_s1', 'Teliti, jangan campur dua zaman.', 4),
(699, NULL, 703, 'e7_n3_s2', 'Aku sudah ada empat pertama. Lima lagi bagaimana?', 1),
(700, 122, 703, 'e7_n3_s2', 'Susun mengikut tarikh mereka mula berkhidmat.', 2),
(701, NULL, 703, 'e7_n3_s2', 'Aku akan padankan semuanya.', 3),
(702, NULL, 703, 'e7_n3_s2', 'Kalau tersilap, album ini tidak boleh dihantar.', 4),
(703, 124, 703, 'e7_n3_s3', 'Cikgu, mengapa pembentukan Malaysia dikira pencapaian Tunku?', 1),
(704, 124, 703, 'e7_n3_s3', 'Aku berjaya merealisasikan pembentukan Malaysia pada 16 September 1963.', 2),
