(708, NULL, 703, 'e7_n3_s4', 'Aku ingat, tetapi tidak pasti.', 2),
(709, NULL, 703, 'e7_n3_s4', 'Aku akan padankan semua enam.', 3),
(710, 122, 703, 'e7_n3_s4', 'Jangan campur, ini peperiksaan kecil.', 4),
