(712, NULL, 703, 'e7_n3_s5', 'Supaya negara hebat, tetapi itu sahaja?', 2),
(713, NULL, 703, 'e7_n3_s5', 'Aku akan baca kad sebelum menjawab.', 3),
(714, 122, 703, 'e7_n3_s5', 'Fikir tentang negara dan rakyat.', 4),
(715, 122, 703, 'e7_n3_s6', 'Bagaimana kita menghargai Perdana Menteri, cikgu?', 1),
(716, 122, 703, 'e7_n3_s6', 'Bukan dengan kata-kata kosong sahaja.', 2),
(717, NULL, 703, 'e7_n3_s6', 'Aku akan baca kad dan pilih yang betul.', 3),
(718, NULL, 703, 'e7_n3_s6', 'Satu kad pun jangan tersilap.', 4),
(719, 122, 703, 'e7_n3_s7', 'Mengapa kita perlu menyokong kepimpinan negara?', 1),
