(721, NULL, 703, 'e7_n3_s7', 'Aku akan padankan setiap peringkat dengan faedahnya.', 3),
(722, NULL, 703, 'e7_n3_s7', 'Jangan campur aduk.', 4),
(723, 122, 703, 'e7_n3_s8', 'Unit ini mengajar dua nilai teras sivik. Apakah nilai itu?', 1),
(724, NULL, 703, 'e7_n3_s8', 'Satu aku tahu, bertanggungjawab. Satu lagi?', 2),
(725, NULL, 703, 'e7_n3_s8', 'Aku akan baca nota dan pilih jawapan yang betul.', 3),
(726, 122, 703, 'e7_n3_s8', 'Teliti, nilai itu berkaitan dengan hubungan kita dengan pemimpin.', 4),
(727, 141, 801, NULL, 'Tugasku menjaga mesin ladang supaya ekonomi berjalan. Jika aku keliru antara cara dahulu dan kini, kerja petani akan terganggu, {nama}.', 1),
