(729, 141, 801, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, juruteknik yang menjaga jentera di ladang. Dengar keluhan petani dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
