(739, 146, 801, 'e8_n1_s3', 'Kata datuk, dahulu orang mendulang.', 2),
(740, NULL, 801, 'e8_n1_s3', 'Aku akan baca nota di belakang gambar.', 3),
(741, 146, 801, 'e8_n1_s3', 'Jangan terbalik.', 4),
(742, 146, 801, 'e8_n1_s4', 'Getah sudah ditanam sejak lama.', 1),
(743, 145, 801, 'e8_n1_s4', 'Kelapa sawit pun bermula dalam tempoh yang sama.', 2),
(744, NULL, 801, 'e8_n1_s4', 'Aku akan semak nota dan menentukan masa kedua-dua industri bermula.', 3),
(745, NULL, 801, 'e8_n1_s4', 'Jangan agak-agak, kerana tarikh mesti tepat.', 4),
(746, 146, 801, 'e8_n1_s5', 'Kad-kad ini jatuh. Siapa boleh susun semula?', 1),
