(748, 145, 801, 'e8_n1_s5', 'Dan sawit menghasilkan biodiesel.', 3),
(749, NULL, 801, 'e8_n1_s5', 'Aku akan padankan manfaat dengan penerangannya.', 4),
(750, 146, 801, 'e8_n1_s6', 'Industri hiliran dan biodiesel selalu dikelirukan.', 1),
(751, 146, 801, 'e8_n1_s6', 'Aku hanya tahu menoreh getah.', 2),
