(755, 146, 801, 'e8_n1_s7', 'Aku tahu sarung tangan dibuat daripada getah.', 2),
(756, 145, 801, 'e8_n1_s7', 'Minyak sawit pula ada pelbagai bentuk.', 3),
(757, NULL, 801, 'e8_n1_s7', 'Aku akan padankan hasil dengan sumbernya.', 4),
(758, 144, 801, 'e8_n1_s8', 'Ringkaskan perubahan dari dahulu hingga kini.', 1),
(759, 144, 801, 'e8_n1_s8', 'Apa yang hilang? Apa yang kekal?', 2),
(760, NULL, 801, 'e8_n1_s8', 'Aku akan menyusun peristiwa mengikut peringkat perkembangan.', 3),
(761, 144, 801, 'e8_n1_s8', 'Ingat, kemajuan datang secara berperingkat.', 4),
(762, 142, 802, NULL, 'Tugasku memeriksa mutu dan fakta. Jika satu cop salah, seluruh laporan ekonomi menjadi cacat, {nama}.', 1),
