(764, 142, 802, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, inspektor yang memeriksa kilang dan industri. Semak setiap borang dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
