(766, NULL, 802, 'e8_n2_s1', 'Aku ragu. Mari semak nota.', 2),
(767, NULL, 802, 'e8_n2_s1', 'Aku akan baca nota sebelum mencop.', 3),
(768, 147, 802, 'e8_n2_s1', 'Jika cop LULUS salah, kita semua malu.', 4),
