(770, NULL, 802, 'e8_n2_s2', 'Dan juga melahirkan usahawan.', 2),
(771, NULL, 802, 'e8_n2_s2', 'Aku akan padankan sumbangan dengan penerangannya.', 3),
(772, 147, 802, 'e8_n2_s2', 'Jangan cop dahulu sebelum semak.', 4),
(773, 147, 802, 'e8_n2_s3', 'Wartawan itu tanya, buat apa menaja perlumbaan?', 1),
(774, NULL, 802, 'e8_n2_s3', 'Fikir tentang pendapatan negara.', 2),
(775, NULL, 802, 'e8_n2_s3', 'Aku akan baca nota penajaan.', 3),
(776, 147, 802, 'e8_n2_s3', 'Jawapan pendek dan tepat.', 4),
(777, 147, 802, 'e8_n2_s4', 'Susun tarikh ini mengikut urutan peristiwa.', 1),
(778, 147, 802, 'e8_n2_s4', 'Jangan lupa Proton Saga dan PERODUA.', 2),
(779, NULL, 802, 'e8_n2_s4', 'Aku akan susun peristiwa mengikut tahun.', 3),
(780, NULL, 802, 'e8_n2_s4', 'Laporan perlu dihantar sebelum waktu pejabat tamat.', 4),
