(796, 148, 802, 'e8_n2_s8', 'Padankan dengan betul, kerana pelancong menunggu.', 4),
(797, 143, 803, NULL, 'Tugasku menyusun rak dengan barangan buatan Malaysia dan menceritakan kisahnya. Jika aku tersilap, pelanggan akan hilang kepercayaan, {nama}.', 1),
(798, 143, 803, NULL, 'Aku belajar bahawa membeli barangan buatan Malaysia memajukan ekonomi dan menimbulkan rasa bangga terhadap negara.', 2),
(799, 143, 803, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemilik kedai jenama Malaysia. Layan pelanggan dengan jujur. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(800, 149, 803, 'e8_n3_s1', 'Poster kempen ini dilancarkan bila?', 1),
(801, NULL, 803, 'e8_n3_s1', 'Aku tahu, tetapi mahu pelanggan menjawab sendiri.', 2),
