(803, 149, 803, 'e8_n3_s1', 'Jawab betul, nanti aku marah.', 4),
(804, 149, 803, 'e8_n3_s2', 'Aku letak minyak pelincir di rak buah-buahan.', 1),
(805, NULL, 803, 'e8_n3_s2', 'Itu salah. Mari kita susun semula.', 2),
(806, NULL, 803, 'e8_n3_s2', 'Aku akan padankan produk dengan kategorinya.', 3),
(807, 149, 803, 'e8_n3_s2', 'Cepat, aku mahu keluar.', 4),
(808, 149, 803, 'e8_n3_s3', 'Apa bukti pencapaian ekonomi pesat negara?', 1),
(809, 149, 803, 'e8_n3_s3', 'Lihat sekeliling, ada tiga bidang.', 2),
(810, NULL, 803, 'e8_n3_s3', 'Aku akan cari empat bukti dalam gambar.', 3),
(811, 149, 803, 'e8_n3_s3', 'Fikir pembangunan, perhubungan dan perdagangan.', 4),
