(813, NULL, 803, 'e8_n3_s4', 'Setiap satu ada ciri sendiri.', 2),
(814, NULL, 803, 'e8_n3_s4', 'Aku akan padankan pencapaian dengan penerangannya.', 3),
(815, 149, 803, 'e8_n3_s4', 'Jangan campur, kerana aku akan menyalin ke buku.', 4),
(816, 149, 803, 'e8_n3_s5', 'Mengapa perlu bangga dengan barangan buatan Malaysia?', 1),
(817, NULL, 803, 'e8_n3_s5', 'Ada sebab ekonomi dan sebab identiti.', 2),
