(822, NULL, 803, 'e8_n3_s6', 'Aku akan baca kad dan tentukan pernyataan yang betul.', 3),
(823, NULL, 803, 'e8_n3_s6', 'Jangan terpengaruh pernyataan pelik.', 4),
(824, 122, 803, 'e8_n3_s7', 'Sebagai warganegara, apa peranan setiap peringkat?', 1),
(825, 149, 803, 'e8_n3_s7', 'Aku keliru antara diri, masyarakat dan negara.', 2),
(826, NULL, 803, 'e8_n3_s7', 'Aku akan padankan setiap peringkat dengan peranannya.', 3),
