(1020, NULL, 1003, 'e10_n3_s3', 'Aku akan baca kad dan memilih jawapan yang betul.', 3),
(1021, 225, 1003, 'e10_n3_s3', 'Pilih dengan teliti.', 4),
(1022, 225, 1003, 'e10_n3_s4', 'Tan Sri Razali Ismail dan Datuk Dr. Mazlan Othman. Siapa yang mana?', 1),
(1023, 225, 1003, 'e10_n3_s4', 'Jawatan mereka tinggi di PBB.', 2),
(1024, NULL, 1003, 'e10_n3_s4', 'Aku akan padankan tokoh dengan jawatannya.', 3),
(1025, 225, 1003, 'e10_n3_s4', 'Teliti, kerana ini pengiktirafan antarabangsa.', 4),
(1026, 222, 1003, 'e10_n3_s5', 'Cari empat bukti warisan dunia dalam kaca.', 1),
(1027, 222, 1003, 'e10_n3_s5', 'Mulu, Kinabalu, Melaka dan Lenggong menanti.', 2),
(1028, NULL, 1003, 'e10_n3_s5', 'Aku akan cari empat bukti dalam gambar.', 3),
(1029, 222, 1003, 'e10_n3_s5', 'Teliti, jangan terlepas.', 4),
(1030, 225, 1003, 'e10_n3_s6', 'Ada empat kategori pengiktirafan UNESCO.', 1),
(1031, 225, 1003, 'e10_n3_s6', 'Aku selalu tertukar antara Memori Dunia dengan Warisan Tidak Ketara.', 2),
(1032, NULL, 1003, 'e10_n3_s6', 'Aku akan padankan kategori dengan contohnya.', 3),
(1033, NULL, 1003, 'e10_n3_s6', 'Teliti kerana ini pengiktirafan PBB.', 4),
(1034, 225, 1003, 'e10_n3_s7', 'Pengiktirafan UNESCO bermula bila?', 1),
(1035, 225, 1003, 'e10_n3_s7', 'Aku ingat tahun 2000.', 2),
(1036, NULL, 1003, 'e10_n3_s7', 'Aku akan susun pengiktirafan mengikut tahun.', 3),
(1037, 225, 1003, 'e10_n3_s7', 'Teliti, kerana ada banyak tahun.', 4),
(1038, 225, 1003, 'e10_n3_s8', 'Mengapa Malaysia menjalin hubungan baik dengan negara luar?', 1),
(1039, 225, 1003, 'e10_n3_s8', 'Untuk keamanan?', 2),
(1040, NULL, 1003, 'e10_n3_s8', 'Aku akan baca kad dan memilih jawapan yang betul.', 3),
(1041, NULL, 1003, 'e10_n3_s8', 'Fikir tentang keselamatan dan kemakmuran.', 4),
(1042, 225, 1003, 'e10_n3_s9', 'Apa peranan diri, masyarakat dan negara dalam hubungan baik?', 1),
(1043, 225, 1003, 'e10_n3_s9', 'Aku keliru antara ketiganya.', 2),
(1044, NULL, 1003, 'e10_n3_s9', 'Aku akan padankan setiap peringkat dengan peranannya.', 3),
(1045, NULL, 1003, 'e10_n3_s9', 'Jangan campur aduk.', 4),
(1046, 1, 1, NULL, 'Tugasku sebagai Perdana Menteri Persekutuan Tanah Melayu ialah menjelaskan gagasan Malaysia dan meyakinkan Sarawak, Sabah dan Singapura melalui rundingan, bukan paksaan. Jika aku gagal mendengar, tiada Malaysia, {nama}.', 1),
(1047, 1, 1, NULL, 'Aku belajar bahawa perpaduan dibina melalui permuafakatan: mendengar, berunding dan menghormati rakan. Kerana itu kita wajar menghargai jasa dan kebijaksanaan pemimpin.', 2),
(1048, 1, 1, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Perdana Menteri Persekutuan Tanah Melayu. Setiap keputusan yang kau ambil akan menentukan nasib Sarawak, Sabah, Singapura dan Tanah Melayu. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1049, 10, 1, 'e1_n1_s1', 'Tuan, wartawan di Singapura pasti bertanya: ini idea Tuan seorang? Fail-fail ini tersusun terbalik, jadi saya tidak pasti jawapannya.', 1),
(1050, NULL, 1, 'e1_n1_s1', 'Aku bukan yang pertama bercakap tentang penggabungan ini. Tetapi siapa yang mula, Ghazali?', 2),
(1051, 11, 1, 'e1_n1_s1', 'Surat tahun 1887 itu daripada saya. Saya Pengarah British North Borneo Company. Saya mencadangkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat digabungkan.', 3),
(1052, 10, 1, 'e1_n1_s1', 'Itu cadangan pihak British, tuan. Belum ada suara rakyat tempatan.', 4),
(1053, 13, 1, 'e1_n1_s1', 'Pada 1938 kami mahu penggabungan tanah air Melayu. Saya, Ibrahim Haji Yaakob, menamakannya Melayu Raya.', 5),
(1054, 14, 1, 'e1_n1_s1', 'Saya Harun Aminurrashid. Melayu Raya merangkumi Tanah Melayu, Singapura, seluruh Kalimantan, Kepulauan Filipina dan Kepulauan Indonesia.', 6),
(1055, NULL, 1, 'e1_n1_s1', 'Besar sungguh cita-cita itu. Tetapi Filipina dan Indonesia disebut sekali. Mereka tentu tidak senang dengan peta sebesar itu.', 7),
(1056, 10, 1, 'e1_n1_s1', 'Tuan sudah nampak masalahnya. Ingat peta ini, kita akan bertemu dua negara itu lagi. Dan tuan, mengapa wartawan perlu tahu idea ini sudah lama?', 8),
(1057, 5, 1, 'e1_n1_s2', 'Tunku, draf ucapan saya mengatakan Tunku mencadangkan penggabungan pada 1951. Betulkah?', 1),
(1058, NULL, 1, 'e1_n1_s2', 'Tahun 1951 itu Tuan MacDonald, bukan aku. Mana telegramnya, Ghazali?', 2),
(1059, 12, 1, 'e1_n1_s2', 'Saya Gabenor Jeneral British di Asia Tenggara. Pada 1951 saya berbincang dengan pemimpin Persekutuan Tanah Melayu, Sarawak, Sabah dan Singapura tentang penggabungan.', 3),
(1060, 5, 1, 'e1_n1_s2', 'Jadi British sudah bertanya pemimpin kita sebelum Tunku bersuara?', 4),
(1061, NULL, 1, 'e1_n1_s2', 'Ya. Tahun 1955 barulah aku, sebagai Ketua Menteri, mencadangkan Sarawak, Sabah, Singapura dan Brunei menyertai Persekutuan Tanah Melayu.', 5),
(1062, 10, 1, 'e1_n1_s2', 'Tuan, jika Parlimen tersilap tarikh, Singapura akan membetulkan kita di depan umum. Pemimpin di sana sudah lama memerhatikan kita.', 6),
(1063, 5, 1, 'e1_n1_s2', 'Kalau begitu susun semuanya dahulu, Tunku. Siapa yang patut disebut dahulu dalam ucapan?', 7),
(1064, 10, 1, 'e1_n1_s3', 'Tuan, Encik Lee sudah tiba dengan laporan. Mukanya tegang.', 1),
(1065, 4, 1, 'e1_n1_s3', 'Tunku, pengaruh komunis di Singapura semakin kuat. Jika kami berdiri sendiri, saya tidak yakin kami mampu mengawalnya.', 2),
(1066, 5, 1, 'e1_n1_s3', 'Sarawak pun menghadapi ancaman yang sama, Encik Lee.', 3),
(1067, NULL, 1, 'e1_n1_s3', 'Persekutuan Tanah Melayu sudah lama menghadapi komunis. Kita ada pengalaman.', 4),
(1068, 4, 1, 'e1_n1_s3', 'Maksud Tunku, ancaman itu lebih mudah dibendung jika kita bergabung?', 5),
(1069, 10, 1, 'e1_n1_s3', 'Tuan, perhatikan laporan Encik Lee. Dia hanya bercakap tentang Singapura. Di Tanah Melayu ada orang yang akan bertanya mengapa kita menolong Singapura sahaja. Cari buktinya di atas meja.', 6),
(1070, 4, 1, 'e1_n1_s3', 'Bagaimana gabungan ini membantu keselamatan kami, Tunku?', 7),
(1071, 16, 1, 'e1_n1_s4', 'Tunku, jika hanya Singapura bergabung dengan kita, tidakkah satu kaum menjadi terlalu ramai?', 1),
(1072, NULL, 1, 'e1_n1_s4', 'Itu sebab Sarawak, Sabah dan Brunei diajak sekali. Bilangan penduduk antara kaum menjadi lebih seimbang.', 2),
(1073, 41, 1, 'e1_n1_s4', 'Selain itu, apa untungnya kepada rakyat yang tinggal di sana?', 3),
(1074, 5, 1, 'e1_n1_s4', 'Pembangunan infrastruktur, sosial dan ekonomi akan dipercepat. Taraf hidup rakyat akan meningkat.', 4),
(1075, NULL, 1, 'e1_n1_s4', 'Dan kemerdekaan Sarawak, Sabah, Singapura dan Brunei juga dapat dipercepat, jika semua pihak bermuafakat.', 5),
(1076, 10, 1, 'e1_n1_s4', 'Tuan, ada orang di Borneo yang mendengar perkataan dipercepat sebagai dipaksa. Dengar baik-baik apa kata mereka nanti.', 6),
(1077, 16, 1, 'e1_n1_s4', 'Tunku, mengapa Borneo perlu diajak sekali? Itu yang paling saya tidak faham.', 7),
(1078, 10, 1, 'e1_n1_s5', 'Tuan, dewan penuh. Wartawan dari beberapa negara pun ada. Mereka diam sahaja.', 1),
(1079, 4, 1, 'e1_n1_s5', 'Tunku, sebut nama Malaysia dengan jelas. Jangan beri ruang salah faham.', 2),
(1080, NULL, 1, 'e1_n1_s5', 'Aku mengumumkan di sini: Persekutuan Tanah Melayu, Singapura, Sarawak, Sabah dan Brunei akan digabungkan dalam Malaysia.', 3),
(1081, 17, 1, 'e1_n1_s5', 'Sarawak dan Sabah sudah bersetuju, Tunku? Atau Tunku memutuskan untuk mereka?', 4),
(1082, NULL, 1, 'e1_n1_s5', 'Belum. Aku akan ke Sarawak sendiri untuk menjelaskan kepada pemimpin di sana.', 5),
(1083, 10, 1, 'e1_n1_s5', 'Tuan, tidak semua negara jiran akan senang dengan nama ini. Ingat itu. Dan wartawan itu masih menunggu jawapan, Tuan.', 6),
(1084, 2, 1, 'e1_n1_s6', 'Tunku, anak-anak buah saya di pedalaman tidak tahu apa itu Malaysia. Apa yang kami dapat?', 1),
(1085, NULL, 1, 'e1_n1_s6', 'Aku datang bukan memaksa. Aku datang kerana mahu menerangkan.', 2),
(1086, 6, 1, 'e1_n1_s6', 'Kalau Sarawak bergabung, adakah suara kami dihormati dalam kerajaan persekutuan?', 3),
(1087, 15, 1, 'e1_n1_s6', 'Saya mahu mendengar hujah Tunku dahulu sebelum memberi pendapat.', 4),
(1088, NULL, 1, 'e1_n1_s6', 'Aku tidak akan memutuskan sendiri. Biar penduduk Sarawak dan Sabah didengar melalui wakil mereka.', 5),
(1089, 2, 1, 'e1_n1_s6', 'Itu cakap yang baik. Tetapi saya mahu lihat buktinya dahulu.', 6),
(1090, 10, 1, 'e1_n1_s6', 'Tuan, Encik Donald dari Sabah dalam perjalanan ke sini. Dia ada cadangan yang akan mengubah haluan. Dan Tun Jugah masih menunggu, tuan: mengapa tuan datang sendiri?', 7),
(1091, 3, 1, 'e1_n1_s7', 'Tunku, kalau setiap pemimpin menerangkan sendiri-sendiri, rakyat akan keliru. Kita perlu satu jawatankuasa untuk meyakinkan mereka.', 1),
(1092, 9, 1, 'e1_n1_s7', 'Rakyat Sabah mahu tahu: adakah ini cara baharu menjajah kami?', 2),
(1093, NULL, 1, 'e1_n1_s7', 'Jawatankuasa itu boleh dinamakan Jawatankuasa Setia Kawan Malaysia. Pemimpin Sarawak, Sabah dan Persekutuan duduk bersama.', 3),
(1094, 2, 1, 'e1_n1_s7', 'Aku akan duduk sebagai ahli. Tetapi jawatankuasa mesti benar-benar mendengar.', 4),
(1095, 3, 1, 'e1_n1_s7', 'Pada 23 Julai 1961, JSKM ditubuhkan. Misinya satu: meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.', 5),
(1096, 10, 1, 'e1_n1_s7', 'Tuan, cadangan itu sampai ke London. British mahu bukti bahawa rakyat benar-benar bersetuju, bukan sekadar pemimpin. Cari buktinya di bilik ini.', 6),
(1097, 9, 1, 'e1_n1_s7', 'Tunku, apa jawapan yang meyakinkan rakyat Sabah?', 7),
(1098, 16, 1, 'e1_n1_s8', 'Tunku, saya wakil Persekutuan dalam suruhanjaya ini. Tugas ini besar. Penduduk Sarawak dan Sabah mesti mahu bercakap dengan jujur.', 1),
(1099, 10, 1, 'e1_n1_s8', 'Suruhanjaya ini dibentuk pada 17 Januari 1962 untuk mendapatkan reaksi penduduk Sarawak dan Sabah tentang cadangan Malaysia.', 2),
(1100, NULL, 1, 'e1_n1_s8', 'Beritahu mereka: pendapat mereka lebih penting daripada keputusan kami.', 3),
(1101, 16, 1, 'e1_n1_s8', 'Dan jika mereka menolak?', 4),
(1102, NULL, 1, 'e1_n1_s8', 'Maka kita dengar, bukan memaksa.', 5),
(1103, 5, 1, 'e1_n1_s8', 'Tuan, ahli lain, Sir David Watherston dan Sir Anthony Abell, sudah tiba. Suruhanjaya lengkap.', 6),
(1104, 10, 1, 'e1_n1_s8', 'Kami akan menemu ramah dan meneliti memorandum yang dihantar penduduk. Tunku, apakah tujuan suruhanjaya ini sebenarnya?', 7),
(1105, 10, 1, 'e1_n1_s9', 'Tuan, laporan Suruhanjaya Cobbold sudah diserahkan kepada pihak British dan Persekutuan Tanah Melayu.', 1),
(1106, NULL, 1, 'e1_n1_s9', 'Apa dapatannya?', 2),
(1107, 10, 1, 'e1_n1_s9', 'Dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia.', 3),
(1108, 7, 1, 'e1_n1_s9', 'Tunku, parti kami menolak. Kami mahu persekutuan sendiri: Brunei, Sarawak dan Borneo Utara.', 4),
(1109, 6, 1, 'e1_n1_s9', 'Itu pendapat satu parti. Dua pertiga rakyat kata sebaliknya. Perikatan Sarawak menyokong.', 5),
(1110, NULL, 1, 'e1_n1_s9', 'Aku mendengar bantahan SUPP. Aku tidak akan berhenti menerangkan matlamat Malaysia kepada rakyat.', 6),
(1111, 41, 1, 'e1_n1_s9', 'Tunku, kami meneliti draf laporan bersama Jawatankuasa Kabinet. Kami perlu tahu bagaimana menjawab penentang.', 7),
(1112, 5, 1, 'e1_n1_s10', 'Saya memainkan peranan dalam JAK. Ahlinya wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah.', 1),
(1113, 3, 1, 'e1_n1_s10', 'Rangka perlembagaan mesti melindungi kepentingan Sabah dan Sarawak. Itu syarat kami.', 2),
(1114, 15, 1, 'e1_n1_s10', 'Betul. Jika tidak, apa gunanya kami bergabung?', 3),
(1115, NULL, 1, 'e1_n1_s10', 'Syarat itu kita catat. Tujuan JAK ialah menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah.', 4),
(1116, 10, 1, 'e1_n1_s10', 'Tuan, masih ada satu pihak yang belum bersuara. Singapura sedang menunggu rundingan. Mesyuarat ini 30 Ogos 1962.', 5),
(1117, 15, 1, 'e1_n1_s10', 'Tunku, saya tanya sekali lagi: apa gunanya kami bergabung jika kepentingan kami tidak dijamin?', 6),
(1118, 4, 1, 'e1_n1_s11', 'Tunku, rundingan sudah selesai. Tetapi saya mahu rakyat Singapura mengundi sendiri.', 1),
(1119, NULL, 1, 'e1_n1_s11', 'Rakyat berhak menentukan. Apa kaedahnya?', 2),
(1120, 4, 1, 'e1_n1_s11', 'Referendum, iaitu pemungutan suara rakyat.', 3),
(1121, 10, 1, 'e1_n1_s11', 'Pada 1 September 1962, referendum diadakan. Keputusan menunjukkan rakyat Singapura bersetuju.', 4),
(1122, NULL, 1, 'e1_n1_s11', 'Dua langkah sudah selesai: Sarawak dan Sabah menjawab melalui Cobbold, Singapura melalui referendum.', 5),
(1123, 10, 1, 'e1_n1_s11', 'Tuan, tarikh seterusnya di London. Tetapi Jakarta dan Manila belum diam.', 6),
(1124, 4, 1, 'e1_n1_s11', 'Tunku, adakah Sarawak dan Sabah perlu diundi seperti Singapura?', 7),
(1125, 2, 1, 'e1_n1_s12', 'Tunku, aku orang rumah panjang. Aku tidak biasa memegang pena di dewan sebesar ini.', 1),
(1126, NULL, 1, 'e1_n1_s12', 'Kau menandatangani untuk Sarawak, Tun. Jangan gementar.', 2),
(1127, 15, 1, 'e1_n1_s12', 'Saya pun menandatangani untuk Sarawak. Tetapi saya dengar Jakarta dan Manila membantah.', 3),
(1128, 5, 1, 'e1_n1_s12', 'Saya mewakili Persekutuan dalam JAK. Semua syarat perlembagaan sudah dicatat di dokumen ini.', 4),
(1129, 10, 1, 'e1_n1_s12', 'Pada 9 Julai 1963, Perjanjian Malaysia ditandatangani di sini. Tuan mengetuai perwakilan Persekutuan Tanah Melayu.', 5),
(1130, NULL, 1, 'e1_n1_s12', 'Tandatangan sudah ada. Tetapi Indonesia dan Filipina belum percaya.', 6),
(1131, 15, 1, 'e1_n1_s12', 'Tunku, perlukah kita menjawab bantahan Indonesia dan Filipina?', 7),
(1132, 3, 1, 'e1_n1_s13', 'Tunku, mengapa PBB datang lagi? Kami sudah menjawab melalui Cobbold.', 1),
(1133, 10, 1, 'e1_n1_s13', 'PBB mewujudkan United Nations Malaysia Mission, UNMM, pada 12 Ogos 1963 untuk mengesahkan persetujuan penduduk Sarawak dan Sabah.', 2),
(1134, NULL, 1, 'e1_n1_s13', 'Kita tiada apa-apa yang perlu disembunyikan. Biar mereka mengesahkan persetujuan penduduk Sarawak dan Sabah.', 3),
(1135, 4, 1, 'e1_n1_s13', 'Dan jika UNMM mendapati rakyat bersetuju?', 4),
(1136, NULL, 1, 'e1_n1_s13', 'Maka tiada siapa dapat meragui persetujuan mereka.', 5),
(1137, 10, 1, 'e1_n1_s13', 'Tuan, tarikh Pemasyhuran sudah ditetapkan. Tetapi saya khuatir Jakarta tidak akan menerima keputusan itu dengan senang hati.', 6),
(1138, 3, 1, 'e1_n1_s13', 'Tunku, mengapa kita menerima UNMM, bukannya menolak?', 7),
(1139, 5, 1, 'e1_n1_s14', 'Tunku, dokumen Pemasyhuran ada versi Jawi dan versi Rumi. Siapa yang membaca dan menandatangani?', 1),
(1140, NULL, 1, 'e1_n1_s14', 'Aku, Tunku Abdul Rahman Putra Al-Haj, sebagai Perdana Menteri Malaysia.', 2),
(1141, 10, 1, 'e1_n1_s14', 'Tuan, perhatikan kandungan dokumen: negeri-negeri disebut satu demi satu.', 3),
(1142, NULL, 1, 'e1_n1_s14', 'Mulai 16 September 1963, bersamaan 28 Rabiulakhir 1383, Malaysia mengandungi Pahang, Terengganu, Kedah, Johor, Negeri Sembilan, Kelantan, Selangor, Perak, Perlis, Pulau Pinang, Melaka, Singapura, Sabah dan Sarawak.', 4),
(1143, 3, 1, 'e1_n1_s14', 'Pemasyhuran diadakan di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.', 5),
(1144, NULL, 1, 'e1_n1_s14', 'Merdeka! Merdeka! Merdeka! Merdeka! Merdeka! Merdeka! Merdeka!', 6),
(1145, 5, 1, 'e1_n1_s14', 'Tunku, mengapa tarikh 16 September 1963 begitu penting?', 7),
(1146, 9, 1, 'e1_n1_s15', 'Tunku, murid saya bertanya: siapa yang bergabung dengan siapa?', 1),
(1147, NULL, 1, 'e1_n1_s15', 'Persekutuan Tanah Melayu dengan 11 negeri, ditambah Singapura, Sabah dan Sarawak.', 2),
(1148, 18, 1, 'e1_n1_s15', 'Berapa semuanya, Tunku?', 3),
(1149, 5, 1, 'e1_n1_s15', 'Empat belas negeri pada 16 September 1963. Tetapi Singapura akan berubah nanti.', 4),
(1150, 10, 1, 'e1_n1_s15', 'Tuan, perhatikan peta. Ada negeri yang berbeza-beza. Brunei menolak penyertaan dalam Malaysia.', 5),
(1151, 18, 1, 'e1_n1_s15', 'Tunku, mengapa ada Singapura dalam senarai pada 1963?', 6),
(1152, 5, 1, 'e1_n1_s16', 'Tunku, dari 1963 hingga 1966, Indonesia melancarkan konfrontasi kerana menganggap Malaysia mengancam kedudukannya.', 1),
(1153, 10, 1, 'e1_n1_s16', 'Dan Filipina mendakwa Sabah sebahagian daripada wilayahnya.', 2),
(1154, NULL, 1, 'e1_n1_s16', 'Peta Melayu Raya pernah menyebut dua negara itu. Kini mereka menentang kita.', 3),
(1155, 4, 1, 'e1_n1_s16', 'Tunku, pada 1965, Singapura berpisah daripada Malaysia.', 4),
(1156, NULL, 1, 'e1_n1_s16', 'Aku bersedih. Tetapi kita tidak boleh hilang arah.', 5),
(1157, 10, 1, 'e1_n1_s16', 'Tuan, hubungan dengan Indonesia dan Filipina kemudian pulih melalui permuafakatan. Seperti kata orang tua: carik-carik bulu ayam, akhirnya bercantum juga.', 6),
(1158, 5, 1, 'e1_n1_s16', 'Tunku, bagaimana hubungan yang tegang dapat dipulihkan?', 7),
(1159, 10, 1, 'e1_n1_s17', 'Tuan, arkib mahu satu rekod lengkap dari Adelphi hingga Pemasyhuran.', 1),
(1160, NULL, 1, 'e1_n1_s17', 'Aku mulakan di Adelphi, 27 Mei 1961, lalu Sarawak, JSKM, Cobbold, laporan, perjanjian, UNMM dan pemasyhuran.', 2),
(1161, 5, 1, 'e1_n1_s17', 'Setiap langkah mengandungi tenaga ramai orang, Tunku.', 3),
(1162, NULL, 1, 'e1_n1_s17', 'Aku hanya satu daripada ramai. Tugasku ialah mendengar, menerangkan dan menyatukan, supaya Malaysia terbentuk dan negara kekal makmur dan bersatu.', 4),
(1163, 10, 1, 'e1_n1_s17', 'Dan generasi kemudian akan menyebut nama kita sebagai satu cerita yang diwarisi.', 5),
(1164, 5, 1, 'e1_n1_s17', 'Tunku, mengapa permuafakatan begitu penting?', 6),
(1165, 3, 2, NULL, 'Aku Donald Stephens, pemimpin UNKO di Sabah. Tugasku menyuarakan harapan dan kebimbangan rakyat Sabah, dan meyakinkan mereka dengan bukti, bukan janji kosong, {nama}.', 1),
(1166, 3, 2, NULL, 'Aku belajar bahawa permuafakatan lahir apabila suara rakyat didengar dan setiap langkah dijelaskan dengan jujur. Kerana itu pemimpin wajar dihargai.', 2),
(1167, 3, 2, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin UNKO di Sabah. Rakyatmu mahu tahu apa untung dan rugi Malaysia. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1168, 9, 2, 'e1_n2_s1', 'Donald, di pekan orang berbisik Tanah Melayu mahu mengambil Borneo. Kau tahu sesuatu?', 1),
(1169, NULL, 2, 'e1_n2_s1', 'Itu cakap kosong. Tiada siapa pernah menyebutnya kepada kita.', 2),
(1170, 9, 2, 'e1_n2_s1', 'Kalau kosong, kenapa fail berhabuk di bawah mejamu itu ada cop British North Borneo Company?', 3),
(1171, NULL, 2, 'e1_n2_s1', 'Aku sendiri belum membukanya. Pegawai lama meninggalkannya di sini.', 4),
(1172, 9, 2, 'e1_n2_s1', 'Dengar tapak kaki di luar? Orang kampung sudah menunggu jawapan. Baca, supaya kita tidak menjawab dengan tekaan.', 5),
(1173, NULL, 2, 'e1_n2_s1', 'Tulisannya pudar. Aku perlu nyahkod ayat demi ayat.', 6),
(1174, 9, 2, 'e1_n2_s1', 'Kalau British yang memulakan semua ini, kita patut curiga. Orang kampung tanya: adakah idea ini datang daripada orang tempatan?', 7),
(1175, 9, 2, 'e1_n2_s2', 'Empat tarikh, empat nama. Orang kampung akan keliru.', 1),
(1176, NULL, 2, 'e1_n2_s2', 'Mereka tidak perlu menghafal. Mereka perlu nampak talinya: syarikat dahulu, kemudian orang Melayu, kemudian pegawai British, kemudian seorang ketua menteri.', 2),
(1177, 9, 2, 'e1_n2_s2', 'Syarikat berniaga di sini pada 1887. Orang Melayu bermimpi pada 1938. Apa kaitannya dengan kita?', 3),
(1178, 13, 2, 'e1_n2_s2', 'Pada 1938, saya dan Harun Aminurrashid memperjuangkan Melayu Raya: Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia.', 4),
(1179, 12, 2, 'e1_n2_s2', 'Pada 1951, saya Malcolm MacDonald berbincang dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura.', 5),
(1180, NULL, 2, 'e1_n2_s2', 'Jadi sebelum 1955 sudah ada perbincangan. Tunku bukan yang pertama.', 6),
(1181, 9, 2, 'e1_n2_s2', 'Betul. Tetapi seorang pemuda UNKO bertanya: kalau idea ini lama, mengapa tiada yang jadi?', 7),
(1182, 5, 2, 'e1_n2_s3', 'Donald, aku tidak datang membawa tarikh. Aku datang membawa kebimbangan.', 1),
(1183, NULL, 2, 'e1_n2_s3', 'Sabah tenang. Mengapa kami perlu risau tentang komunis?', 2),
(1184, 5, 2, 'e1_n2_s3', 'Bukan Sabah yang paling terdedah. Singapura menghadapi ancaman komunis yang boleh menggugat keselamatan Tanah Melayu. Sarawak juga menghadapi ancaman yang sama.', 3),
(1185, NULL, 2, 'e1_n2_s3', 'Jadi kalau kami menyertai, kami membawa risiko itu bersama?', 4),
(1186, 5, 2, 'e1_n2_s3', 'Tanah Melayu sudah ada pengalaman menghadapi komunis. Dengan Malaysia, ancaman itu dapat dibendung.', 5),
(1187, 9, 2, 'e1_n2_s3', 'Cari buktinya sendiri, Donald. Jangan percaya kata-kata semata-mata.', 6),
(1188, 5, 2, 'e1_n2_s3', 'Donald, kalau seorang tua kampung bertanya adakah mereka akan diperangi, apa jawapanmu?', 7),
(1189, 8, 2, 'e1_n2_s4', 'Datu, Pak Donald, jangan berkisah tentang komunis sahaja. Apa untungnya kepada kami?', 1),
(1190, 9, 2, 'e1_n2_s4', 'Keselamatan bukan satu-satunya sebab. Aku ada risalah dengan empat sebab. Tetapi tiga risalah bercampur, dan aku tidak pasti yang mana betul.', 2),
(1191, NULL, 2, 'e1_n2_s4', 'Datu, baca dahulu, jangan beri risalah yang salah. Satu kesilapan dan orang kampung hilang percaya.', 3),
(1192, 9, 2, 'e1_n2_s4', 'Itulah sebabnya aku memerlukan kau. Aku pemimpin USNO, kau pemimpin UNKO, tetapi kita berdua tidak boleh tersalah.', 4),
(1193, NULL, 2, 'e1_n2_s4', 'Aku ingat satu perkara: keseimbangan kaum. Tanah Melayu dengan Singapura sahaja tidak seimbang. Dengan Sarawak, Sabah dan Brunei, bilangannya seimbang.', 5),
(1194, 9, 2, 'e1_n2_s4', 'Dan kemerdekaan. Pembentukan ini boleh mempercepat kemerdekaan Sarawak, Sabah, Singapura dan Brunei, tetapi perlukan sokongan semua pihak.', 6),
(1195, 8, 2, 'e1_n2_s4', 'Pak Donald, mengapa tidak cukup Tanah Melayu dan Singapura sahaja?', 7),
(1196, 9, 2, 'e1_n2_s5', 'Donald! Kita masih menyusun hujah, dan Tunku sudah bercakap.', 1),
(1197, NULL, 2, 'e1_n2_s5', 'Enam tahun idea itu tidur sejak 1955. Hari ini ia bangun.', 2),
(1198, 9, 2, 'e1_n2_s5', 'Kita tahu dari kertas, bukan dari Tunku sendiri. Aku tidak suka rasa itu.', 3),
(1199, NULL, 2, 'e1_n2_s5', 'Itu pengumuman cadangan, bukan keputusan. Cadangan perlu persetujuan kita.', 4),
(1200, 9, 2, 'e1_n2_s5', 'Kalau begitu pastikan tarikhnya betul, supaya bila wartawan datang kau tidak keliru.', 5),
(1201, NULL, 2, 'e1_n2_s5', 'Dakwatnya kabur. Aku perlu nyahkod.', 6),
(1202, 17, 2, 'e1_n2_s5', 'Encik Donald, apa langkah selepas pengumuman ini?', 7),
(1203, 1, 2, 'e1_n2_s6', 'Saya datang bukan untuk memaksa. Saya datang untuk menerangkan idea pembentukan Malaysia kepada kamu.', 1),
(1204, 6, 2, 'e1_n2_s6', 'Tunku, ramai bertanya kepentingan kami. Kami bukan hanya wilayah tambahan.', 2),
(1205, 15, 2, 'e1_n2_s6', 'Saya menyokong pembentukan ini. Tetapi suara rakyat mesti didengar.', 3),
(1206, 2, 2, 'e1_n2_s6', 'Kami perlukan masa dan perbincangan. Satu lawatan tidak cukup.', 4),
(1207, NULL, 2, 'e1_n2_s6', 'Tunku, Sabah juga menunggu penjelasan yang sama. Satu lawatan mungkin tidak cukup tanpa sebuah jawatankuasa bersama.', 5),
(1208, 1, 2, 'e1_n2_s6', 'Apa cadanganmu, Donald?', 6),
(1209, 15, 2, 'e1_n2_s6', 'Donald, kalau Sarawak mahu berbincang, apa yang kau cadangkan?', 7),
(1210, 1, 2, 'e1_n2_s7', 'Donald, kau mencadangkan jawatankuasa itu. Sekarang kita perlu membinanya.', 1),
(1211, NULL, 2, 'e1_n2_s7', 'Tujuannya satu: meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.', 2),
(1212, 2, 2, 'e1_n2_s7', 'Aku sudah duduk dalam banyak mesyuarat. Yang aku mahu ialah jawapan, bukan ucapan.', 3),
(1213, NULL, 2, 'e1_n2_s7', 'Sebab itu semua parti duduk di meja ini, bukan satu parti sahaja.', 4),
(1214, 9, 2, 'e1_n2_s7', 'Pastikan orang tahu siapa mewakili parti apa. Kalau tersalah, kita nampak tidak teratur.', 5),
(1215, 6, 2, 'e1_n2_s7', 'Dan jangan lupa, kami datang dari Sarawak dengan pandangan sendiri.', 6),
(1216, 17, 2, 'e1_n2_s7', 'Encik Donald, mengapa jawatankuasa ini ditubuhkan pada 23 Julai 1961?', 7),
(1217, 10, 2, 'e1_n2_s8', 'Suruhanjaya ini dibentuk untuk mendapatkan reaksi penduduk Sarawak dan Sabah.', 1),
(1218, 16, 2, 'e1_n2_s8', 'Saya menemu ramah penduduk dan meneliti memorandum mereka tentang pembentukan Malaysia. Tetapi surat bertimbun, Encik Donald.', 2),
(1219, NULL, 2, 'e1_n2_s8', 'Penduduk menulis kerana mereka mahu didengar, bukan sekadar disoal.', 3),
(1220, 10, 2, 'e1_n2_s8', 'Kami dari luar. Yang paling mengetahui rakyat ialah kamu. Jadi kamu tentukan surat yang wajar diberi perhatian.', 4),
(1221, 16, 2, 'e1_n2_s8', 'Surat yang saya perlukan ialah catatan pendirian penduduk, bukan laporan yang kami sendiri akan tulis.', 5),
(1222, NULL, 2, 'e1_n2_s8', 'Itu pengakuan yang jujur. Saya akan tolong pilih.', 6),
(1223, 10, 2, 'e1_n2_s8', 'Donald, kalau penduduk takut bersuara, apa saranmu?', 7),
(1224, 9, 2, 'e1_n2_s9', 'Laporan siap. Dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia.', 1),
(1225, NULL, 2, 'e1_n2_s9', 'Dua pertiga bukan semua. Satu pertiga lagi masih ragu.', 2),
(1226, 6, 2, 'e1_n2_s9', 'SUPP menolak. Mereka mahu membentuk persekutuan sendiri, terdiri daripada Brunei, Sarawak dan Borneo Utara.', 3),
(1227, NULL, 2, 'e1_n2_s9', 'Dan kita? Kita tunjukkan angka dua pertiga, atau kita dengar mereka?', 4),
(1228, 9, 2, 'e1_n2_s9', 'Kedua-duanya. Tetapi sebelum berhujah, susun dahulu apa yang telah berlaku, supaya hujahmu tidak lompat-lompat.', 5),
(1229, 7, 2, 'e1_n2_s9', 'Dua pertiga bukan kami. Kami mahu persekutuan sendiri.', 6),
(1230, 5, 2, 'e1_n2_s10', 'Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk di sini. Saya turut memainkan peranan.', 1),
(1231, NULL, 2, 'e1_n2_s10', 'Janji lisan mudah dilupakan. Kami mahu tulisan.', 2),
(1232, 6, 2, 'e1_n2_s10', 'Dilindungi bagaimana? Dengan kata-kata atau dengan tulisan?', 3),
(1233, 5, 2, 'e1_n2_s10', 'Dengan tulisan. Nyahkod dokumen ini, dan kamu akan lihat.', 4),
(1234, NULL, 2, 'e1_n2_s10', 'Cobbold bertanya. JSKM meyakinkan. Sekarang apa tugas jawatankuasa ini?', 5),
(1235, 9, 2, 'e1_n2_s10', 'Tiga langkah: yakinkan, tanya, kemudian tulis perlindungan.', 6),
(1236, 4, 2, 'e1_n2_s11', 'Rundingan antara Persekutuan Tanah Melayu dan Singapura sudah selesai. Hari ini rakyat memutuskan.', 1),
(1237, NULL, 2, 'e1_n2_s11', 'Mengapa pemimpin PAP menyokong?', 2),
(1238, 4, 2, 'e1_n2_s11', 'Saya menyokong pembentukan Malaysia untuk membendung ideologi komunis di Singapura.', 3),
(1239, NULL, 2, 'e1_n2_s11', 'Dan bagaimana kita tahu rakyat bersetuju?', 4),
(1240, 4, 2, 'e1_n2_s11', 'Referendum, pemungutan suara rakyat. Tetapi pegawai saya salah letak dokumen keputusannya.', 5),
(1241, 5, 2, 'e1_n2_s11', 'Cari yang betul, Donald. Dokumen lain bercampur.', 6),
(1242, 4, 2, 'e1_n2_s11', 'Donald, adakah Sabah akan diundi juga?', 7),
(1243, 9, 2, 'e1_n2_s12', 'Donald, tiga telegram sampai serentak. Satu berkata London, satu berkata Singapura, satu lagi berkata Kuching. Orang ramai menunggu bacaanku.', 1),
(1244, NULL, 2, 'e1_n2_s12', 'Datu, jangan baca yang salah. Orang akan ingat tarikh yang kau sebut.', 2),
(1245, 9, 2, 'e1_n2_s12', 'Itulah sebabnya aku mahu kau pilih. Aku pemimpin USNO, tetapi pada saat begini aku perlukan mata kedua.', 3),
(1246, NULL, 2, 'e1_n2_s12', 'Yang betul menyebut sebuah perjanjian di London. Tunku mengetuai perwakilan Persekutuan Tanah Melayu.', 4),
(1247, 9, 2, 'e1_n2_s12', 'Dan siapa menandatangani dari Sarawak?', 5),
(1248, NULL, 2, 'e1_n2_s12', 'Tun Temenggung Jugah dan Datu Bandar Abang Haji Mustapha.', 6),
(1249, 8, 2, 'e1_n2_s12', 'Pak Donald, siapa yang menandatangani perjanjian itu bagi Sarawak?', 7),
(1250, 9, 2, 'e1_n2_s13', 'Mengapa PBB perlu bertanya lagi? Cobbold sudah bertanya.', 1),
(1251, NULL, 2, 'e1_n2_s13', 'Cobbold mendapat reaksi penduduk dan melapor kepada British dan Persekutuan Tanah Melayu. UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah.', 2),
(1252, 9, 2, 'e1_n2_s13', 'Jadi dua langkah, untuk dua tujuan yang berbeza.', 3),
(1253, NULL, 2, 'e1_n2_s13', 'Dan kita tidak boleh menyorok apa-apa. Biar mereka lihat sendiri.', 4),
(1254, 9, 2, 'e1_n2_s13', 'Cari tiga tanda bahawa bilik ini bilik UNMM, supaya tiada keliru dengan mesyuarat lain.', 5),
(1255, 19, 2, 'e1_n2_s13', 'Encik Donald, apa tujuan kami di sini?', 6),
(1256, 2, 2, 'e1_n2_s14', 'Pemasyhuran diadakan di empat tempat: Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.', 1),
(1257, NULL, 2, 'e1_n2_s14', 'Dokumen itu menyebut perjanjian 9 Julai 1963 antara Persekutuan Tanah Melayu, United Kingdom, Borneo Utara, Sarawak dan Singapura.', 2),
(1258, 9, 2, 'e1_n2_s14', 'Hari ini Sabah, Sarawak dan Singapura tamat daripada menjadi jajahan takluk Queen. Tunku menandatangani dan memasyhurkan sebagai Perdana Menteri Malaysia.', 3),
(1259, NULL, 2, 'e1_n2_s14', 'Dan Malaysia berdiri dengan Persekutuan Tanah Melayu, Singapura, Sabah dan Sarawak.', 4),
(1260, 9, 2, 'e1_n2_s14', 'Ingat tarikh ini: 16 September 1963. Dari 27 Mei 1961, lebih dua tahun.', 5),
(1261, NULL, 2, 'e1_n2_s14', 'Dari idea 1955, lapan tahun.', 6),
(1262, 18, 2, 'e1_n2_s14', 'Pak Donald, apa yang berlaku pada 16 September 1963?', 7),
(1263, 9, 2, 'e1_n2_s15', 'Brunei menolak penyertaan dalam Malaysia. Singapura datang, Sabah dan Sarawak datang, Brunei tidak.', 1),
(1264, NULL, 2, 'e1_n2_s15', 'Tetapi itu bukan masalah terbesar.', 2),
(1265, 9, 2, 'e1_n2_s15', 'Indonesia mengisytiharkan konfrontasi terhadap Malaysia dari 1963 hingga 1966. Mereka menganggap pembentukan Malaysia mengancam kedudukan mereka.', 3),
(1266, NULL, 2, 'e1_n2_s15', 'Tiga tahun. Dan Filipina?', 4),
(1267, 9, 2, 'e1_n2_s15', 'Filipina membuat dakwaan yang lebih dekat dengan kita.', 5),
(1268, NULL, 2, 'e1_n2_s15', 'Nyahkod dokumennya. Aku mahu tahu dengan tepat.', 6),
(1269, 20, 2, 'e1_n2_s15', 'Encik Donald, mungkinkah hubungan dengan Indonesia dan Filipina pulih?', 7),
(1270, 9, 2, 'e1_n2_s16', 'Pemasyhuran sudah lama berlalu. Tetapi kisah tidak habis di situ. Singapura berpisah pada 1965.', 1),
(1271, NULL, 2, 'e1_n2_s16', 'Dan Brunei tidak menyertai. Walau begitu, dahulu aku tidak yakin Malaysia akan berdiri.', 2),
(1272, 9, 2, 'e1_n2_s16', 'Kesungguhan, permuafakatan dan keprihatinan semua pihak yang membawa kita ke sini.', 3),
(1273, NULL, 2, 'e1_n2_s16', 'Muafakat membawa berkat. Aku faham maksudnya sekarang.', 4),
(1274, 9, 2, 'e1_n2_s16', 'Sebelum kau menulis ucapan, susun semula kisah ini. Lapan langkah.', 5),
(1275, 18, 2, 'e1_n2_s16', 'Pak Donald, mengapa kita meraikan Hari Malaysia pada 16 September?', 6),
(1276, 10, 3, NULL, 'Aku Ghazali Shafie. Aku bukan di pentas, aku di bilik fail. Tugasku memastikan setiap tarikh, dokumen dan nama tepat, {nama}.', 1),
(1277, 10, 3, NULL, 'Aku belajar bahawa kejayaan besar bergantung pada kerja teliti di sebalik tabir. Satu tarikh yang salah boleh menggoyahkan sebuah rundingan.', 2),
(1278, 10, 3, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pegawai yang menyusun fail di sebalik tabir. Setiap dokumen mesti tepat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1279, 5, 3, 'e1_n3_s1', 'Ghazali, sebelum Tunku, sudah ada orang bermimpi tentang gabungan. Baca fail ini.', 1),
(1280, NULL, 3, 'e1_n3_s1', 'Tahun 1938. Tulisannya sudah pudar, Tun.', 2),
(1281, 5, 3, 'e1_n3_s1', 'Maka nyahkodlah. Kita tidak boleh bercakap tentang sejarah dengan tekaan.', 3),
(1282, NULL, 3, 'e1_n3_s1', 'Siapa penulisnya?', 4),
(1283, 5, 3, 'e1_n3_s1', 'Ibrahim Yaakob dan Harun Aminurrashid. Mereka memperjuangkan satu konsep yang luas.', 5),
(1284, NULL, 3, 'e1_n3_s1', 'Kalau idea itu sudah lama, mengapa baru sekarang diperkatakan?', 6),
(1285, 5, 3, 'e1_n3_s1', 'Itulah soalan yang akan ditanya wartawan. Jawab dengan fakta.', 7),
(1286, 5, 3, 'e1_n3_s2', 'Empat fail, empat tahun. Jangan biar ia bercampur.', 1),
(1287, NULL, 3, 'e1_n3_s2', '1887 Brassey, 1938 Melayu Raya, 1951 MacDonald, 1955 Tunku.', 2),
(1288, 12, 3, 'e1_n3_s2', 'Pada 1951 saya Malcolm MacDonald berbincang dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura.', 3),
(1289, 13, 3, 'e1_n3_s2', 'Pada 1938 kami memperjuangkan Melayu Raya.', 4),
(1290, 5, 3, 'e1_n3_s2', 'Susun mengikut tarikh. Pegawai yang menyusun fail dengan betul menyusun hujah dengan betul.', 5),
(1291, NULL, 3, 'e1_n3_s2', 'Baik, Tun.', 6),
(1292, 5, 3, 'e1_n3_s3', 'Ghazali, mengapa kita bimbang tentang keselamatan?', 1),
(1293, NULL, 3, 'e1_n3_s3', 'Singapura dan Sarawak menghadapi ancaman komunis. Tanah Melayu sudah berpengalaman menghadapinya.', 2),
(1294, 5, 3, 'e1_n3_s3', 'Buktikan. Aku tidak mahu hujah kosong.', 3),
(1295, NULL, 3, 'e1_n3_s3', 'Peta ini menunjukkan Singapura dan Borneo. Kertas ini menyatakan ancaman itu.', 4),
(1296, 5, 3, 'e1_n3_s3', 'Tunjukkan satu persatu.', 5),
(1297, 5, 3, 'e1_n3_s4', 'Empat sebab. Aku mahu kau padankan sebab dengan penjelasannya.', 1),
(1298, NULL, 3, 'e1_n3_s4', 'Keselamatan, keseimbangan kaum, kemerdekaan dan sosioekonomi.', 2),
(1299, 5, 3, 'e1_n3_s4', 'Jangan hafal. Fahami.', 3),
(1300, NULL, 3, 'e1_n3_s4', 'Baik, Tun.', 4),
(1301, 1, 3, 'e1_n3_s5', 'Ghazali, teks ucapanku hilang. Aku mahu yang betul.', 1),
(1302, NULL, 3, 'e1_n3_s5', 'Tuan, ada beberapa salinan. Saya semak dahulu.', 2),
(1303, 5, 3, 'e1_n3_s5', 'Teliti. Satu kesilapan di hadapan wartawan akan dibaca seluruh negara.', 3),
(1304, 1, 3, 'e1_n3_s5', 'Ucapan itu mengumumkan cadangan pembentukan Malaysia.', 4),
(1305, NULL, 3, 'e1_n3_s5', 'Baik, Tuan.', 5),
(1306, 5, 3, 'e1_n3_s6', 'Nota dari Kuching. Baca betul-betul.', 1),
(1307, NULL, 3, 'e1_n3_s6', 'Tulisannya tidak jelas.', 2),
(1308, 5, 3, 'e1_n3_s6', 'Maka nyahkod.', 3),
(1309, NULL, 3, 'e1_n3_s6', 'Baik, Tun.', 4),
(1310, 5, 3, 'e1_n3_s7', 'Jawatankuasa ini ditubuhkan hari ini. Pastikan kita ada bukti.', 1),
(1311, NULL, 3, 'e1_n3_s7', 'Ada kertas, peta dan papan nama.', 2),
(1312, 5, 3, 'e1_n3_s7', 'Tunjukkan.', 3),
(1313, NULL, 3, 'e1_n3_s7', 'Baik, Tun.', 4),
(1314, 5, 3, 'e1_n3_s8', 'Suruhanjaya ini dibentuk. Kau ahlinya.', 1),
(1315, NULL, 3, 'e1_n3_s8', 'Tugasnya mendapatkan reaksi penduduk.', 2),
(1316, 5, 3, 'e1_n3_s8', 'Baca kertas itu.', 3),
(1317, NULL, 3, 'e1_n3_s8', 'Baik, Tun.', 4),
(1318, 41, 3, 'e1_n3_s9', 'Ghazali, laporan Cobbold ada beberapa salinan. Yang mana satu yang betul?', 1),
(1319, NULL, 3, 'e1_n3_s9', 'Ada yang lama dan ada yang rancangan awal.', 2),
(1320, 5, 3, 'e1_n3_s9', 'Pastikan yang sebenar.', 3),
(1321, 41, 3, 'e1_n3_s9', 'Dua pertiga menyokong. SUPP menolak dan mahu persekutuan sendiri.', 4),
(1322, 5, 3, 'e1_n3_s10', 'JAK menyediakan rangka perlembagaan. Tunjukkan buktinya.', 1),
(1323, NULL, 3, 'e1_n3_s10', 'Dokumen dan wakil empat pihak.', 2),
(1324, 5, 3, 'e1_n3_s10', 'Cari.', 3),
(1325, 5, 3, 'e1_n3_s11', 'Singapura sudah memutuskan.', 1),
(1326, NULL, 3, 'e1_n3_s11', 'Nota ini ringkas.', 2),
(1327, 5, 3, 'e1_n3_s11', 'Nyahkod.', 3),
(1328, 5, 3, 'e1_n3_s12', 'Perjanjian ditandatangani di London hari ini.', 1),
(1329, NULL, 3, 'e1_n3_s12', 'Saya perlu pastikan fail yang betul sampai.', 2),
(1330, 5, 3, 'e1_n3_s12', 'Pilih.', 3),
(1331, NULL, 3, 'e1_n3_s12', 'Baik, Tun.', 4),
(1332, 5, 3, 'e1_n3_s13', 'Empat badan, empat tugas.', 1),
(1333, NULL, 3, 'e1_n3_s13', 'JSKM, Cobbold, JAK dan UNMM.', 2),
(1334, 5, 3, 'e1_n3_s13', 'Padankan.', 3),
(1335, 5, 3, 'e1_n3_s14', 'Dokumen ini akan dibaca di empat tempat.', 1),
(1336, NULL, 3, 'e1_n3_s14', 'Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall.', 2),
(1337, 5, 3, 'e1_n3_s14', 'Cari tanda-tanda dokumen ini.', 3),
(1338, 5, 3, 'e1_n3_s15', 'Cabaran muncul.', 1),
(1339, NULL, 3, 'e1_n3_s15', 'SUPP, Indonesia, Filipina dan Brunei.', 2),
(1340, 5, 3, 'e1_n3_s15', 'Padankan.', 3),
(1341, 5, 3, 'e1_n3_s16', 'Susun lapan langkah.', 1),
(1342, NULL, 3, 'e1_n3_s16', 'Dari Adelphi hingga Pemasyhuran.', 2),
(1343, 5, 3, 'e1_n3_s16', 'Dan iktibarnya?', 3),
(1344, NULL, 3, 'e1_n3_s16', 'Muafakat membawa berkat.', 4),
(1345, 21, 201, NULL, 'Aku Tok Penglipur Lara. Tugasku mencatat dan menurunkan cerita negeri, dan setiap negeri ada lebih daripada satu cerita yang mesti aku sebut dengan jujur, {nama}.', 1),
(1346, 21, 201, NULL, 'Aku belajar bahawa nama negeri, ketuanya, pusatnya dan lagunya menyimpan sejarah dan kemegahan. Mengenalinya menjadikan kita bangga akan warisan negeri.', 2),
(1347, 21, 201, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pencerita tua yang membawa sebuah buku kosong. Setiap negeri akan berbalah tentang ceritanya. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1348, 28, 201, 'e2_n1_s1', 'Tok, datuk saya kata Perlis dari perkataan Siam. Orang sebelah kata dari peristiwa Raja Syed Hussin. Siapa betul?', 1),
(1349, 18, 201, 'e2_n1_s1', 'Tok, kelapa itu hanyut dari hulu parit. Tulisan di catatan ini pun pudar.', 2),
(1350, NULL, 201, 'e2_n1_s1', 'Kedua-duanya ada dalam catatan. Baca dahulu, jangan teka.', 3),
(1351, 28, 201, 'e2_n1_s1', 'Kalau Tok salah tulis, satu kampung akan menghafal yang salah.', 4),
(1352, 18, 201, 'e2_n1_s1', 'Selepas ini kita ke selatan, Tok. Di sana orang pernah memasang perangkap besar.', 5),
(1353, 28, 201, 'e2_n1_s1', 'Tok, apa lagi cerita tentang nama Perlis selain perkataan Siam itu?', 6),
(1354, 29, 201, 'e2_n1_s2', 'Kedah dari \'kheddah\', perangkap gajah! Datuk saya memburu gajah di sini.', 1),
(1355, 30, 201, 'e2_n1_s2', 'Salah! Dari \'qadah\', cawan berkaki yang pedagang Arab jual di Alam Melayu!', 2),
(1356, 18, 201, 'e2_n1_s2', 'Tok, di dinding itu ada tulisan Tamil. Nama dalam tulisan itu lain pula.', 3),
(1357, NULL, 201, 'e2_n1_s2', 'Tiga catatan, tiga bahasa. Kita padankan supaya tiada yang tersisih.', 4),
(1358, 18, 201, 'e2_n1_s2', 'Selepas ini kita ke pulau yang banyak pokok dan pinang, Tok.', 5),
(1359, 29, 201, 'e2_n1_s2', 'Tok, apa nama Kedah dalam tulisan Tamil itu?', 6),
(1360, 27, 201, 'e2_n1_s3', 'Orang Kedah panggil pulau ini Tanjong Penaga kerana banyak pokok penaga. Nama asalnya Pulo Ka Satu!', 1),
(1361, 30, 201, 'e2_n1_s3', 'Salah! Pulau pinang, buah pinang itu barang dagangan kami!', 2),
(1362, 56, 201, 'e2_n1_s3', 'Di Perak, nama negeri dari kilat ikan dalam air. Atau dari bijih timah putih berkilat!', 3),
(1363, 18, 201, 'e2_n1_s3', 'Tok, ada dua negeri di jeti ini. Jangan bercampur.', 4),
(1364, NULL, 201, 'e2_n1_s3', 'Padankan, supaya tiada negeri bercampur.', 5),
(1365, 27, 201, 'e2_n1_s3', 'Tok, peribahasa apa untuk kenal negeri sendiri?', 6),
(1366, 40, 201, 'e2_n1_s4', 'Tok, murid-murid keliru. Mana ibu negeri dan mana bandar diraja?', 1),
(1367, 18, 201, 'e2_n1_s4', 'Tok, titik merah ialah ibu negeri dan titik kuning bandar diraja, kata legenda peta ini.', 2),
(1368, NULL, 201, 'e2_n1_s4', 'Ibu negeri pusat pentadbiran. Bandar diraja ada warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan monumen.', 3),
(1369, 40, 201, 'e2_n1_s4', 'Kalau tersilap, anak murid akan menghafal yang salah.', 4),
(1370, 18, 201, 'e2_n1_s4', 'Esok kita dengar radio kampung, Tok. Ada lagu yang dimainkan setiap pagi.', 5),
(1371, 40, 201, 'e2_n1_s4', 'Tok, bagaimana kita memelihara istana atau bangunan pentadbiran lama?', 6),
(1372, 39, 201, 'e2_n1_s5', 'Tok, majlis bermula sekejap lagi. Lagu Kedah mesti dimainkan dahulu.', 1),
(1373, 18, 201, 'e2_n1_s5', 'Tok, ada kaset bertulis empat tajuk di atas rak.', 2),
(1374, NULL, 201, 'e2_n1_s5', 'Tajuk lagu negeri tidak boleh ditukar. Itu lambang kemegahan.', 3),
(1375, 39, 201, 'e2_n1_s5', 'Kalau saya main lagu negeri lain, tetamu akan rasa dihina.', 4),
(1376, 18, 201, 'e2_n1_s5', 'Selepas ini kita ke kuala sungai. Di sana ada bunyi pedagang lama, Tok.', 5),
(1377, 39, 201, 'e2_n1_s5', 'Tok, lagu Perak, Perlis dan Pulau Pinang pula, apa tajuknya?', 6),
(1378, 27, 201, 'e2_n1_s6', 'Selangor dari pokok mentagau! Pedagang menyebut kuala selangau, lalu jadi Kuala Selangor.', 1),
(1379, 8, 201, 'e2_n1_s6', 'Bukan, dari serangga selangur yang banyak di sungai!', 2),
(1380, 54, 201, 'e2_n1_s6', 'Negeri kami dari sembilan luak. Kata \'negeri\' pun dari \'nagari\'.', 3),
(1381, 18, 201, 'e2_n1_s6', 'Tok, ada tahun tertulis di piagam penghulu itu.', 4),
(1382, NULL, 201, 'e2_n1_s6', 'Padankan, jangan tinggalkan satu pun.', 5),
(1383, 54, 201, 'e2_n1_s6', 'Tok, sebut luak-luak asal Negeri Sembilan itu.', 6),
(1384, 30, 201, 'e2_n1_s7', 'Melaka dari \'Malakat\', tempat pedagang berhimpun!', 1),
(1385, 8, 201, 'e2_n1_s7', 'Dari pokok tempat Parameswara berehat, ketika pelanduk putih kecil menendang anjing pemburuannya!', 2),
(1386, 55, 201, 'e2_n1_s7', 'Dan Johor dari \'jauhar\', batu permata. Dalam Sulalatus Salatin pula Ujong Tanah!', 3),
(1387, 18, 201, 'e2_n1_s7', 'Tok, empat cerita, dua negeri.', 4),
(1388, NULL, 201, 'e2_n1_s7', 'Padankan, supaya halaman buku tidak salah.', 5),
(1389, 55, 201, 'e2_n1_s7', 'Tok, \'Malakat\' itu daripada bahasa apa?', 6),
(1390, 40, 201, 'e2_n1_s8', 'Tok, fail ini habis bercampur. Saya hampir menghantar Klang sebagai ibu negeri.', 1),
(1391, 18, 201, 'e2_n1_s8', 'Tok, Klang ada istana dan bangunan lama. Ibu negerinya pusat pentadbiran.', 2),
(1392, NULL, 201, 'e2_n1_s8', 'Bandar Melaka ialah ibu negeri. Peta tidak menandakan bandar diraja di sana.', 3),
(1393, 40, 201, 'e2_n1_s8', 'Kalau tersilap, majlis tersasar.', 4),
(1394, 18, 201, 'e2_n1_s8', 'Esok kita dengar kaset lagi, Tok. Empat lagu dari empat negeri.', 5),
(1395, 40, 201, 'e2_n1_s8', 'Tok, mengapa ibu negeri berkembang?', 6),
(1396, 39, 201, 'e2_n1_s9', 'Tok, saya perlukan lagu Johor. Dua kaset ini kelihatan serupa.', 1),
(1397, 18, 201, 'e2_n1_s9', 'Tok, satu kaset ada nama pengganti. Pandang tajuknya betul-betul.', 2),
(1398, NULL, 201, 'e2_n1_s9', 'Tajuk lagu Johor menyebut nama negerinya.', 3),
(1399, 39, 201, 'e2_n1_s9', 'Kalau tersilap, Sultan Johor tersinggung.', 4),
(1400, 18, 201, 'e2_n1_s9', 'Kita ke pantai timur selepas ini. Di sana ada pelangi dan taring besar, kata orang.', 5),
(1401, 39, 201, 'e2_n1_s9', 'Tok, tiga lagu lain itu milik negeri mana?', 6),
(1402, 8, 201, 'e2_n1_s10', 'Pahang dari pokok mahang! Dalam Sulalatus Salatin ia Inderapura atau Pura, dan pura itu bandar.', 1),
(1403, 27, 201, 'e2_n1_s10', 'Terengganu dari \'taring anu\', taring besar di Pulau Duyong! Atau \'terangnya ganu\', pelangi!', 2),
(1404, 55, 201, 'e2_n1_s10', 'Kelantan dari \'kilatan\', cahaya terang yang orang Patani nampak. Orang pantai kata gelam hutan!', 3),
(1405, 18, 201, 'e2_n1_s10', 'Tok, enam cerita dalam satu pantai.', 4),
(1406, NULL, 201, 'e2_n1_s10', 'Padankan satu persatu.', 5),
(1407, 55, 201, 'e2_n1_s10', 'Tok, \'kilatan\' itu cahaya yang dilihat oleh siapa?', 6),
(1408, 40, 201, 'e2_n1_s11', 'Tok, empat kad ini bercampur. Pekan bukan pusat pentadbiran.', 1),
(1409, 18, 201, 'e2_n1_s11', 'Tok, Pekan berwarna kuning di peta, ada istana. Kuantan merah.', 2),
(1410, NULL, 201, 'e2_n1_s11', 'Terengganu dan Kelantan hanya ada ibu negeri pada peta.', 3),
(1411, 40, 201, 'e2_n1_s11', 'Jadi hanya Pahang ada kedua-duanya?', 4),
(1412, 18, 201, 'e2_n1_s11', 'Selepas ini lagu, Tok. Kata orang, dua negeri berkongsi tajuk yang sama.', 5),
(1413, 40, 201, 'e2_n1_s11', 'Tok, apa yang ada di bandar diraja?', 6),
(1414, 27, 201, 'e2_n1_s12', 'Lagu ini lagu negeri saya, \'Selamat Sultan\'!', 1),
(1415, 8, 201, 'e2_n1_s12', 'Salah! Lagu negeri saya juga \'Selamat Sultan\'!', 2),
(1416, 18, 201, 'e2_n1_s12', 'Tok, Pahang pun ada lagu: \'Allah Selamatkan Sultan Kami\'.', 3),
(1417, NULL, 201, 'e2_n1_s12', 'Semua betul. Ini nota yang mesti dinyahkod.', 4),
(1418, 18, 201, 'e2_n1_s12', 'Kita menyeberang laut selepas ini, Tok. Ke Borneo, ke tanah yang ada gunung.', 5),
(1419, 27, 201, 'e2_n1_s12', 'Tok, lagu Pahang itu tajuknya apa?', 6),
(1420, 55, 201, 'e2_n1_s13', 'Tok, orang tanya nama Sarawak dan Sabah. Dokumen lama bercampur.', 1),
(1421, 34, 201, 'e2_n1_s13', 'Sarawak dari Sungai Serak yang berubah menjadi Sungai Sarawak, bersempena sejenis bijih galian!', 2),
(1422, 18, 201, 'e2_n1_s13', 'Tok, ada logam \'cerava\' juga, panggilan Portugis.', 3),
(1423, NULL, 201, 'e2_n1_s13', 'Pilih dokumen yang betul.', 4),
(1424, 55, 201, 'e2_n1_s13', 'Sabah tercatat dalam dokumen \'Maharajah of Sabah\' pada tahun tertentu, dan dikaitkan dengan sejenis buah.', 5),
(1425, 55, 201, 'e2_n1_s13', 'Tok, yang mana dokumen yang betul?', 6),
(1426, 8, 201, 'e2_n1_s14', 'Mengapa \'Kuala Lumpur\'? Bukankah bunyinya pelik?', 1),
(1427, 30, 201, 'e2_n1_s14', 'Dan mengapa \'Labuan\'?', 2),
(1428, 18, 201, 'e2_n1_s14', 'Tok, ada kotak \'Tahukah anda\' di buku. Tiga nama, tiga cerita.', 3),
(1429, NULL, 201, 'e2_n1_s14', 'Padankan dahulu. Dan ingat, Wilayah Persekutuan tiada ibu negeri dan bandar diraja.', 4),
(1430, 34, 201, 'e2_n1_s14', 'Tok, siapa yang bernama Putra pada Putrajaya itu?', 5),
(1431, 40, 201, 'e2_n1_s15', 'Ibu negeri kami Kuching. Pusat pentadbiran.', 1),
(1432, 53, 201, 'e2_n1_s15', 'Kami Kota Kinabalu, pusat pekerjaan dan pendidikan.', 2),
(1433, 18, 201, 'e2_n1_s15', 'Tok, di peta ada titik merah di Kuching dan Kota Kinabalu, tetapi tiada titik kuning.', 3),
(1434, NULL, 201, 'e2_n1_s15', 'Peta hanya menanda ibu negeri bagi kedua-duanya.', 4),
(1435, 18, 201, 'e2_n1_s15', 'Selepas ini lagu terakhir, Tok. Satu tentang tanah air, satu tentang ibu pertiwi.', 5),
(1436, 40, 201, 'e2_n1_s15', 'Tok, bagaimana kita menghargai pusat pentadbiran dan kota warisan?', 6),
(1437, 39, 201, 'e2_n1_s16', 'Tok, saya perlukan lagu Sabah. Tiga kaset lagi bercampur.', 1),
(1438, 18, 201, 'e2_n1_s16', 'Tok, satu tajuk menyebut \'Tanah Airku\'. Satu lagi \'Ibu Pertiwiku\'.', 2),
(1439, NULL, 201, 'e2_n1_s16', 'Satu daripada itu milik Sarawak. Satu lagi milik Sabah.', 3),
(1440, 39, 201, 'e2_n1_s16', 'Dan Wilayah Persekutuan?', 4),
(1441, 18, 201, 'e2_n1_s16', 'Selepas ini kita ke istana. Para ketua negeri sudah tiba.', 5),
(1442, 39, 201, 'e2_n1_s16', 'Tok, Ibu Pertiwiku dan Maju dan Sejahtera itu milik siapa?', 6),
(1443, 40, 201, 'e2_n1_s17', 'Tok, ketua-ketua negeri akan tiba. Kad gelaran bercampur. Satu kesilapan dan kita memalukan negara.', 1),
(1444, 18, 201, 'e2_n1_s17', 'Tok, ada gambar upacara pertabalan di dinding. Setiap ketua negeri ada gelaran tersendiri.', 2),
(1445, NULL, 201, 'e2_n1_s17', 'Ketua negeri tonggak utama pemerintahan. Gelaran yang berbeza menunjukkan keunikan negara kita.', 3),
(1446, 40, 201, 'e2_n1_s17', 'Dan ketua Wilayah Persekutuan? Siapa dia?', 4),
(1447, 18, 201, 'e2_n1_s17', 'Selepas ini kita ke pentas pesta, Tok. Buku mesti dilengkapkan.', 5),
(1448, 40, 201, 'e2_n1_s17', 'Tok, mengapa kita perlu mengenali ketua negeri?', 6),
(1449, 17, 201, 'e2_n1_s18', 'Tok, buku ini mencatat dua cerita bagi setiap negeri. Mengapa?', 1),
(1450, NULL, 201, 'e2_n1_s18', 'Kerana nama negeri dicatat secara lisan dan tulisan.', 2),
(1451, 18, 201, 'e2_n1_s18', 'Tok, ada tiga petunjuk di pentas: jata, bendera dan radio lagu negeri.', 3),
(1452, 17, 201, 'e2_n1_s18', 'Tok perlu tunjukkan kepada penonton. Ini lambang kemegahan dan kedaulatan negeri.', 4),
(1453, NULL, 201, 'e2_n1_s18', '\'Tak kenal maka tak cinta.\' Mengenali nama, bendera dan jata menyuburkan rasa sayang akan negara.', 5),
(1454, 17, 201, 'e2_n1_s18', 'Tok, mengapa kita perlu menghormati lambang negeri?', 6),
(1455, 58, 202, NULL, 'Aku Pegawai Istiadat Negara. Tiga hari lagi majlis bermula dan seseorang cuba memalukan aku, {nama}. Setiap kad dan kaset mesti betul.', 1),
(1456, 58, 202, NULL, 'Aku belajar bahawa nama negeri, ketua, ibu negeri, lagu dan lambangnya ialah identiti. Satu kesilapan boleh memalukan sebuah negeri.', 2),
(1457, 58, 202, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pegawai yang diburu waktu. Ada orang menyabot istiadat. Teliti setiap kad dan dengar bisikan Tok.', 3),
(1458, 57, 202, 'e2_n2_s1', 'Pegawai Istiadat, kad ketua Wilayah Persekutuan hilang. Tiga hari lagi istiadat. Awak sanggup?', 1),
(1459, 21, 202, 'e2_n2_s1', 'Dia tersenyum terlalu lebar. Perhatikan jarinya.', 2),
(1460, NULL, 202, 'e2_n2_s1', 'Saya akan nyahkod nota sisa dalam fail ini.', 3),
(1461, 57, 202, 'e2_n2_s1', 'Kalau tersilap, awak yang malu.', 4),
(1462, 21, 202, 'e2_n2_s1', 'Esok kita ke bilik penyusun gelaran. Banyak kad bakal bercampur.', 5),
(1463, 57, 202, 'e2_n2_s1', 'Dan ibu negeri Wilayah Persekutuan pula, apa nama bandarnya?', 6),
(1464, 59, 202, 'e2_n2_s2', 'Pegawai, papan nama Kuala Lumpur, Labuan dan Putrajaya tercabut dan bercampur.', 1),
(1465, 21, 202, 'e2_n2_s2', 'Setiap nama ada kisahnya. Padankan, jangan tebak.', 2),
(1466, NULL, 202, 'e2_n2_s2', 'Siapa yang membuka papan ini?', 3),
(1467, 59, 202, 'e2_n2_s2', 'Seseorang dengan kunci pejabat.', 4),
(1468, 21, 202, 'e2_n2_s2', 'Kunci itu bukan kunci biasa. Jejaknya ke selatan.', 5),
(1469, 59, 202, 'e2_n2_s2', 'Jadi Putrajaya diambil daripada seorang pemimpin?', 6),
(1470, 40, 202, 'e2_n2_s3', 'Gelaran ketua negeri bercampur. Sultan, Raja, Yang di-Pertuan Besar, Yang di-Pertua Negeri.', 1),
(1471, 21, 202, 'e2_n2_s3', 'Ketua negeri ialah tonggak pemerintahan. Gelaran berbeza menunjukkan keunikan negara kita.', 2),
(1472, NULL, 202, 'e2_n2_s3', 'Satu kad salah dan satu negeri tersinggung.', 3),
(1473, 21, 202, 'e2_n2_s3', 'Jangan serahkan kad kepadanya. Esok kita mohon pertolongan seorang pembantu Yang di-Pertua Negeri.', 4),
(1474, 57, 202, 'e2_n2_s3', 'Mengapa gelaran itu penting? Saya boleh tolong susun.', 5),
(1475, 40, 202, 'e2_n2_s4', 'Tuan Pegawai, tuan saya ialah Yang di-Pertua Negeri. Saya perlukan dokumen senarai negeri yang menggunakan gelaran itu.', 1),
(1476, 21, 202, 'e2_n2_s4', 'Hati-hati. Dokumen palsu pun ada di atas meja.', 2),
(1477, NULL, 202, 'e2_n2_s4', 'Saya semak sendiri.', 3),
(1478, 40, 202, 'e2_n2_s4', 'Kalau salah, tuan saya tidak dijemput ke tempat yang betul.', 4),
(1479, 21, 202, 'e2_n2_s4', 'Esok kita ke Selangor. Seseorang meninggalkan jejak di kuala sungai.', 5),
(1480, 40, 202, 'e2_n2_s4', 'Wilayah Persekutuan pula, siapa ketuanya?', 6),
(1481, 27, 202, 'e2_n2_s5', 'Selangor dari pokok mentagau! Pedagang menyebut kuala selangau.', 1),
(1482, 54, 202, 'e2_n2_s5', 'Negeri kami sembilan luak, dan \'negeri\' dari \'nagari\'.', 2),
(1483, 21, 202, 'e2_n2_s5', 'Jejak Zahar berhenti di sini. Nyahkod piagam itu, mungkin dia meninggalkan sesuatu.', 3),
(1484, NULL, 202, 'e2_n2_s5', 'Saya perlu nama yang tepat untuk kad pengacara.', 4),
(1485, 21, 202, 'e2_n2_s5', 'Selepas ini kita ke Melaka. Seseorang meninggalkan tanda di bawah sebatang pokok.', 5),
(1486, 54, 202, 'e2_n2_s5', 'Sebut luak asal Negeri Sembilan!', 6),
(1487, 30, 202, 'e2_n2_s6', 'Melaka dari Malakat, tempat pedagang berhimpun.', 1),
(1488, 8, 202, 'e2_n2_s6', 'Dari pokok tempat Parameswara berehat melihat pelanduk putih.', 2),
(1489, 21, 202, 'e2_n2_s6', 'Nota di akar ini milik Zahar. Nyahkod sebelum dia kembali.', 3),
(1490, NULL, 202, 'e2_n2_s6', 'Ia menyebut Johor.', 4),
(1491, 21, 202, 'e2_n2_s6', 'Kita ke bilik pejabat daerah. Ada fail yang dicuri.', 5),
(1492, 30, 202, 'e2_n2_s6', 'Dan Jauhar? Apa maksudnya?', 6),
(1493, 40, 202, 'e2_n2_s7', 'Pegawai, fail ibu negeri dan bandar diraja bercampur selepas Zahar datang.', 1),
(1494, 21, 202, 'e2_n2_s7', 'Ibu negeri pusat pentadbiran. Bandar diraja ada istana, bangunan pembesar, kedai lama, muzium dan monumen.', 2),
(1495, NULL, 202, 'e2_n2_s7', 'Saya padankan semula.', 3),
(1496, 40, 202, 'e2_n2_s7', 'Dan Bandar Melaka tiada bandar diraja pada peta.', 4),
(1497, 21, 202, 'e2_n2_s7', 'Kemudian kaset lagu di bilik radio. Tolong periksa suis.', 5),
(1498, 40, 202, 'e2_n2_s7', 'Mengapa ibu negeri berkembang?', 6),
(1499, 39, 202, 'e2_n2_s8', 'Pegawai, kaset ini tiada label. Zahar baru keluar dari bilik ini.', 1),
(1500, 21, 202, 'e2_n2_s8', 'Lagu negeri lambang kemegahan. Padankan label dengan negeri.', 2),
(1501, NULL, 202, 'e2_n2_s8', 'Tengah dan selatan: Selangor, Negeri Sembilan, Melaka, Johor.', 3),
(1502, 39, 202, 'e2_n2_s8', 'Kalau tersilap, tetamu terhina.', 4),
(1503, 21, 202, 'e2_n2_s8', 'Esok kita ke utara. Ada sebuah peti pos yang menyimpan nota.', 5),
(1504, 39, 202, 'e2_n2_s8', 'Mengapa lagu negeri penting?', 6),
(1505, 28, 202, 'e2_n2_s9', 'Perlis dari \'prow-lowy\', kelapa hanyut. Ada juga cerita \'peroleh\'.', 1),
(1506, 56, 202, 'e2_n2_s9', 'Perak dari kilatan ikan atau bijih timah putih berkilat.', 2),
(1507, 21, 202, 'e2_n2_s9', 'Nota di peti pos itu mempunyai empat kad. Padankan.', 3),
(1508, NULL, 202, 'e2_n2_s9', 'Zahar mahu saya tersilap di hadapan tetamu.', 4),
(1509, 21, 202, 'e2_n2_s9', 'Jam hampir tengah hari. Sebuah jeti menanti.', 5),
(1510, 28, 202, 'e2_n2_s9', 'Siapa Raja Syed Hussin itu?', 6),
(1511, 30, 202, 'e2_n2_s10', 'Kedah dari \'qadah\', cawan dagang Arab. Orang kata juga dari \'kheddah\', perangkap gajah.', 1),
(1512, 27, 202, 'e2_n2_s10', 'Pulau ini dahulu Pulo Ka Satu. Orang Kedah panggil Tanjong Penaga.', 2),
(1513, 21, 202, 'e2_n2_s10', 'Seseorang menyembunyikan sampul di jeti ini. Padankan nama-nama itu, pasti sampul itu berdekatan.', 3),
(1514, NULL, 202, 'e2_n2_s10', 'Pinang juga barang dagangan penting.', 4),
(1515, 21, 202, 'e2_n2_s10', 'Selepas ini kita ke pejabat daerah. Pegawai itu mengesyaki Zahar.', 5),
(1516, 27, 202, 'e2_n2_s10', 'Mengapa pinang penting pada nama pulau?', 6),
(1517, 40, 202, 'e2_n2_s11', 'Pegawai Istiadat, saya perlukan dokumen ibu negeri dan bandar diraja Perlis, Kedah, Perak dan Pulau Pinang.', 1),
(1518, 21, 202, 'e2_n2_s11', 'Salah satu fail mempunyai cop Zahar. Berhati-hati.', 2),
(1519, NULL, 202, 'e2_n2_s11', 'Saya semak setiap baris.', 3),
(1520, 40, 202, 'e2_n2_s11', 'Kalau salah, kami menghantar jemputan ke bandar yang salah.', 4),
(1521, 21, 202, 'e2_n2_s11', 'Selepas ini kita periksa kaset lagu utara. Zahar belum selesai.', 5),
(1522, 40, 202, 'e2_n2_s11', 'Mengapa bandar diraja penting?', 6),
(1523, 39, 202, 'e2_n2_s12', 'Kaset ini bertajuk \'Aamiin-Aamiin\'. Tidak ada label negeri.', 1),
(1524, 21, 202, 'e2_n2_s12', 'Nyahkod nota ini. Satu negeri di utara sahaja memiliki lagu itu.', 2),
(1525, NULL, 202, 'e2_n2_s12', 'Di negeri itu ketuanya bergelar Raja.', 3),
(1526, 39, 202, 'e2_n2_s12', 'Dan Perak, Kedah, Pulau Pinang?', 4),
(1527, 21, 202, 'e2_n2_s12', 'Kita ke pantai timur esok. Zahar sudah ke sana awal.', 5),
(1528, 39, 202, 'e2_n2_s12', 'Lagu Perak, Kedah dan Pulau Pinang itu tajuknya apa?', 6),
(1529, 27, 202, 'e2_n2_s13', 'Terengganu dari \'taring anu\', taring besar di Pulau Duyong. Ada juga \'terangnya ganu\', pelangi.', 1),
(1530, 8, 202, 'e2_n2_s13', 'Pahang dari pokok mahang. Dalam Sulalatus Salatin ia Inderapura atau Pura, bandar.', 2),
(1531, 55, 202, 'e2_n2_s13', 'Kelantan dari \'kilatan\', cahaya terang. Orang pantai kata gelam hutan.', 3),
(1532, 21, 202, 'e2_n2_s13', 'Padankan setiap cerita. Peta Zahar tentu menyembunyikan sesuatu di sana.', 4),
(1533, 21, 202, 'e2_n2_s13', 'Selepas ini kita ke bilik peta. Empat nama bandar akan bercampur.', 5),
(1534, 55, 202, 'e2_n2_s13', 'Kilatan itu cahaya yang dilihat oleh siapa?', 6),
(1535, 40, 202, 'e2_n2_s14', 'Pegawai Istiadat, empat kad bercampur. Pekan bukan pusat pentadbiran.', 1),
(1536, 21, 202, 'e2_n2_s14', 'Pekan berwarna kuning di peta, ada istana. Kuantan merah.', 2),
(1537, NULL, 202, 'e2_n2_s14', 'Terengganu dan Kelantan hanya ada ibu negeri pada peta.', 3),
(1538, 40, 202, 'e2_n2_s14', 'Siapa yang mengusik kad ini?', 4),
(1539, 21, 202, 'e2_n2_s14', 'Esok pagi kita ke radio terakhir. Zahar tidak akan berhenti.', 5),
(1540, 40, 202, 'e2_n2_s14', 'Bagaimana kita memelihara istana lama?', 6),
(1541, 39, 202, 'e2_n2_s15', 'Pegawai Istiadat, dua negeri kongsi tajuk \'Selamat Sultan\'. Saya tidak mahu tersilap, jadi saya perlukan lagu Pahang.', 1),
(1542, 21, 202, 'e2_n2_s15', 'Ketua Pahang bergelar Sultan, dan lagunya menyebut \'Kami\'.', 2),
(1543, NULL, 202, 'e2_n2_s15', 'Saya pilih dengan teliti.', 3),
(1544, 39, 202, 'e2_n2_s15', 'Kalau tersilap, Sultan Pahang tersinggung.', 4),
(1545, 21, 202, 'e2_n2_s15', 'Esok pagi kita ke Borneo, ke dua negeri yang jauh. Zahar menanti di sana.', 5),
(1546, 39, 202, 'e2_n2_s15', 'Dan \'Selamat Sultan\' itu lagu negeri mana?', 6),
(1547, 28, 202, 'e2_n2_s16', 'Sarawak dari Sungai Serak yang berubah menjadi Sungai Sarawak, bersempena sejenis bijih galian.', 1),
(1548, 27, 202, 'e2_n2_s16', 'Atau \'cerava\', logam antimoni, panggilan Portugis.', 2),
(1549, 21, 202, 'e2_n2_s16', 'Surat ini dari Sabah. Nyahkod, kerana tarikh di dalamnya penting.', 3),
(1550, NULL, 202, 'e2_n2_s16', 'Ada dokumen bertajuk \'Maharajah of Sabah\'.', 4),
(1551, 21, 202, 'e2_n2_s16', 'Esok pagi Hari-H. Zahar akan membuat langkah terakhir.', 5),
(1552, 28, 202, 'e2_n2_s16', 'Dan nama Sarawak itu bagaimana?', 6),
(1553, 40, 202, 'e2_n2_s17', 'Ibu negeri kami Kuching. Lagu kami Ibu Pertiwiku.', 1),
(1554, 53, 202, 'e2_n2_s17', 'Kami Kota Kinabalu. Lagu kami Sabah Tanah Airku.', 2),
(1555, 21, 202, 'e2_n2_s17', 'Wilayah Persekutuan pun ada lagu: Maju dan Sejahtera. Padankan semuanya.', 3),
(1556, NULL, 202, 'e2_n2_s17', 'Peta hanya menanda ibu negeri bagi Kuching dan Kota Kinabalu.', 4),
(1557, 21, 202, 'e2_n2_s17', 'Esok pagi Hari-H. Dalam gelap, Zahar menuju dewan istiadat.', 5),
(1558, 40, 202, 'e2_n2_s17', 'Mengapa kami wajar menghormati lambang negeri?', 6),
(1559, 60, 202, 'e2_n2_s18', 'Pegawai Istiadat, majlis bermula. Tetamu menunggu.', 1),
(1560, 57, 202, 'e2_n2_s18', 'Saya sudah menukar semua kad awak. Awak akan memalukan negara.', 2),
(1561, 21, 202, 'e2_n2_s18', 'Dia mengaku sendiri. Tunjukkan bukti bahawa semuanya betul: jata, bendera dan radio lagu.', 3),
(1562, NULL, 202, 'e2_n2_s18', 'Setiap negeri ada bendera, lagu dan jata sebagai lambang kemegahan dan kedaulatan.', 4),
(1563, 60, 202, 'e2_n2_s18', 'Mengapa kita wajar menghormati lambang negeri?', 5),
(1564, 26, 203, NULL, 'Aku Pengembara Warisan. Pasportku kosong dan setiap penjaga cop hanya memberi cop jika aku tahu fakta yang betul, {nama}.', 1),
(1565, 26, 203, NULL, 'Aku belajar bahawa setiap negeri ada nama, ketua, pusat, lagu dan lambang yang menjadi kebanggaannya. Kenangan perjalanan lebih berharga daripada cop.', 2),
(1566, 26, 203, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengembara yang membawa pasport kosong. Di setiap wilayah ada penjaga cop yang berbalah dengan penduduk. Hanya fakta betul membuka cop.', 3),
(1567, 17, 203, 'e2_n3_s1', 'Pengembara, pasport awak kosong. Penjaga cop Sabah di pondok itu.', 1),
(1568, 31, 203, 'e2_n3_s1', 'Cop Sabah hanya untuk yang tahu mengapa negeri ini bernama Sabah.', 2),
(1569, NULL, 203, 'e2_n3_s1', 'Saya akan padankan fakta dahulu supaya tidak bercakap kosong.', 3),
(1570, 17, 203, 'e2_n3_s1', 'Pondok ini ada pisang dan satu dokumen tua. Teliti.', 4),
(1571, 17, 203, 'e2_n3_s1', 'Selepas ini kita ke tebing sungai di tanah jiran. Ada logam dan bijih menanti.', 5),
(1572, 31, 203, 'e2_n3_s1', 'Apa itu pisang saba?', 6),
(1573, 31, 203, 'e2_n3_s2', 'Surat ini bakal membuka cop Sarawak. Baca.', 1),
(1574, 17, 203, 'e2_n3_s2', 'Dua cerita bersaing di sini: sungai dan logam.', 2),
(1575, NULL, 203, 'e2_n3_s2', 'Saya nyahkod ayat demi ayat.', 3),
(1576, 31, 203, 'e2_n3_s2', 'Nama Sarawak ada hubungan dengan Sungai Serak.', 4),
(1577, 17, 203, 'e2_n3_s2', 'Esok kita bertemu pusat-pusat pentadbiran Borneo.', 5),
(1578, 31, 203, 'e2_n3_s2', 'Dan cerita Portugis? Apa maksudnya?', 6),
(1579, 40, 203, 'e2_n3_s3', 'Ibu negeri kami Kuching. Lagu kami Ibu Pertiwiku.', 1),
(1580, 53, 203, 'e2_n3_s3', 'Ibu negeri kami Kota Kinabalu. Lagu kami Sabah Tanah Airku.', 2),
(1581, 17, 203, 'e2_n3_s3', 'Ketua mereka bergelar Yang di-Pertua Negeri.', 3),
(1582, NULL, 203, 'e2_n3_s3', 'Peta hanya menanda ibu negeri bagi Kuching dan Kota Kinabalu.', 4),
(1583, 17, 203, 'e2_n3_s3', 'Kita menyeberang ke Labuan, wilayah yang bermula dengan perkataan \'labuh\'.', 5),
(1584, 53, 203, 'e2_n3_s3', 'Siapa ketua Wilayah Persekutuan?', 6),
(1585, 148, 203, 'e2_n3_s4', 'Tiga wilayah, tiga nama. Pelancong sedang menunggu penerangan saya.', 1),
(1586, 17, 203, 'e2_n3_s4', 'Nama Putrajaya ada Putra dan jaya. Dengar baik-baik.', 2),
(1587, NULL, 203, 'e2_n3_s4', 'Saya pilih dokumen yang betul.', 3),
(1588, 148, 203, 'e2_n3_s4', 'Kalau tersalah, pelancong menyangka kami tidak mengenali negara sendiri.', 4),
(1589, 17, 203, 'e2_n3_s4', 'Selepas ini kita periksa kad ketua dan lagu wilayah.', 5),
(1590, 148, 203, 'e2_n3_s4', 'Wilayah Persekutuan terdiri daripada apa?', 6),
(1591, 31, 203, 'e2_n3_s5', 'Cop ini mahukan tiga fakta: ketua, lagu dan ibu negeri.', 1),
(1592, 17, 203, 'e2_n3_s5', 'Wilayah Persekutuan bukan negeri biasa. Ketuanya lebih tinggi daripada Sultan.', 2),
(1593, NULL, 203, 'e2_n3_s5', 'Nota ini ada petunjuk.', 3),
(1594, 31, 203, 'e2_n3_s5', 'Baca dengan teliti.', 4),
(1595, 17, 203, 'e2_n3_s5', 'Kita menuju selatan ke sebuah negeri yang bermula dengan perkataan batu permata.', 5),
(1596, 31, 203, 'e2_n3_s5', 'Apa ketua Wilayah Persekutuan dan ibu negerinya?', 6),
(1597, 30, 203, 'e2_n3_s6', 'Johor dari \'jauhar\', batu permata bernilai!', 1),
(1598, 55, 203, 'e2_n3_s6', 'Dalam Sulalatus Salatin ia Ujong Tanah!', 2),
(1599, 31, 203, 'e2_n3_s6', 'Cop Johor untuk yang menyelesaikan nota ini.', 3),
(1600, 17, 203, 'e2_n3_s6', 'Perhatikan batu berkilau dan naskhah di atas meja.', 4),
(1601, 17, 203, 'e2_n3_s6', 'Selepas ini kita padankan pusat dan istana Johor.', 5),
(1602, 30, 203, 'e2_n3_s6', 'Jauhar itu bahasa apa?', 6),
(1603, 40, 203, 'e2_n3_s7', 'Ibu negeri Johor Bahru, bandar diraja Bandar Maharani.', 1),
(1604, 17, 203, 'e2_n3_s7', 'Titik merah pusat pentadbiran, titik kuning istana dan warisan.', 2),
(1605, 40, 203, 'e2_n3_s7', 'Lagu kami Lagu Bangsa Johor. Ketua kami bergelar Sultan.', 3),
(1606, NULL, 203, 'e2_n3_s7', 'Saya padankan semuanya.', 4),
(1607, 17, 203, 'e2_n3_s7', 'Esok kita ke Melaka. Ada sebatang pokok dan seekor pelanduk.', 5),
(1608, 40, 203, 'e2_n3_s7', 'Mengapa bandar diraja penting?', 6),
(1609, 8, 203, 'e2_n3_s8', 'Melaka dari pokok tempat Parameswara berehat!', 1),
(1610, 30, 203, 'e2_n3_s8', 'Dari \'Malakat\', perhimpunan pedagang!', 2),
(1611, 31, 203, 'e2_n3_s8', 'Baca nota di akar pokok ini.', 3),
(1612, 17, 203, 'e2_n3_s8', 'Nota ini menyebut seekor binatang kecil dan seekor anjing.', 4),
(1613, 17, 203, 'e2_n3_s8', 'Selepas ini kita dengar kaset di bilik radio.', 5),
(1614, 30, 203, 'e2_n3_s8', 'Dan Malakat itu apa maksudnya?', 6),
(1615, 39, 203, 'e2_n3_s9', 'Lagu Melaka mesti dimainkan sebelum Yang di-Pertua Negeri tiba.', 1),
(1616, 17, 203, 'e2_n3_s9', 'Ketua Melaka bergelar Yang di-Pertua Negeri. Ibu negerinya Bandar Melaka.', 2),
(1617, NULL, 203, 'e2_n3_s9', 'Saya pilih kaset yang betul.', 3),
(1618, 39, 203, 'e2_n3_s9', 'Kalau salah, ketua kami tersinggung.', 4),
(1619, 17, 203, 'e2_n3_s9', 'Selepas ini ke negeri yang bernama dari \'nagari\'.', 5),
(1620, 39, 203, 'e2_n3_s9', 'Ibu negeri Melaka di mana?', 6),
(1621, 54, 203, 'e2_n3_s10', 'Negeri kami terbentuk daripada sembilan luak.', 1),
(1622, 31, 203, 'e2_n3_s10', 'Padankan fakta, jangan teka.', 2),
(1623, 17, 203, 'e2_n3_s10', 'Ada satu tahun dan satu perkataan Minangkabau.', 3),
(1624, NULL, 203, 'e2_n3_s10', 'Saya cuba.', 4),
(1625, 17, 203, 'e2_n3_s10', 'Kemudian kita cari pusat dan istana Negeri Sembilan.', 5),
(1626, 54, 203, 'e2_n3_s10', 'Sebut sembilan luak itu!', 6),
(1627, 58, 203, 'e2_n3_s11', 'Ibu negeri Seremban, bandar diraja Seri Menanti.', 1),
(1628, 17, 203, 'e2_n3_s11', 'Ketua Negeri Sembilan bergelar Yang di-Pertuan Besar.', 2),
(1629, NULL, 203, 'e2_n3_s11', 'Lagu mereka Berkatlah Yang di-Pertuan Besar.', 3),
(1630, 58, 203, 'e2_n3_s11', 'Padankan semuanya.', 4),
(1631, 17, 203, 'e2_n3_s11', 'Selepas ini kita ke Selangor dan Pahang, dua negeri berjiran dengan kisah nama masing-masing.', 5),
(1632, 58, 203, 'e2_n3_s11', 'Mengapa menghormati ketua negeri penting?', 6),
(1633, 27, 203, 'e2_n3_s12', 'Selangor dari pokok mentagau. Pedagang menyebut kuala selangau.', 1),
(1634, 8, 203, 'e2_n3_s12', 'Atau dari serangga selangur.', 2),
(1635, 31, 203, 'e2_n3_s12', 'Pahang dari pokok mahang. Dalam Sulalatus Salatin ia Inderapura atau Pura.', 3),
(1636, 17, 203, 'e2_n3_s12', 'Pura bermaksud bandar atau pekan.', 4),
(1637, 17, 203, 'e2_n3_s12', 'Kemudian kita menuju pusat dan istana kedua-dua negeri.', 5),
(1638, 31, 203, 'e2_n3_s12', 'Apa maksud pura?', 6),
(1639, 40, 203, 'e2_n3_s13', 'Ibu negeri Shah Alam, bandar diraja Klang. Lagu kami Duli Yang Maha Mulia.', 1),
(1640, 53, 203, 'e2_n3_s13', 'Ibu negeri Kuantan, bandar diraja Pekan. Lagu kami Allah Selamatkan Sultan Kami.', 2),
(1641, 17, 203, 'e2_n3_s13', 'Kedua-dua ketua bergelar Sultan.', 3),
(1642, NULL, 203, 'e2_n3_s13', 'Saya padankan satu per satu.', 4),
(1643, 17, 203, 'e2_n3_s13', 'Kita ke pantai timur. Pelangi menunggu selepas hujan.', 5),
(1644, 40, 203, 'e2_n3_s13', 'Apa gelaran ketua kedua-dua negeri?', 6),
(1645, 27, 203, 'e2_n3_s14', 'Terengganu dari \'taring anu\', taring besar di Pulau Duyong, atau \'terangnya ganu\', pelangi.', 1),
(1646, 55, 203, 'e2_n3_s14', 'Kelantan dari \'kilatan\', cahaya terang yang dilihat orang Patani, atau dari gelam hutan.', 2),
(1647, 17, 203, 'e2_n3_s14', 'Padankan kesemuanya, satu per satu.', 3),
(1648, NULL, 203, 'e2_n3_s14', 'Saya bergerak.', 4),
(1649, 17, 203, 'e2_n3_s14', 'Selepas ini kita periksa lagu dan pusat pantai timur.', 5),
(1650, 27, 203, 'e2_n3_s14', 'Gading apa itu sebenarnya?', 6),
(1651, 31, 203, 'e2_n3_s15', 'Dua negeri di sini kongsi tajuk lagu yang sama. Nota ini menjelaskannya.', 1),
(1652, 17, 203, 'e2_n3_s15', 'Ibu negeri satu ialah Kuala Terengganu, satu lagi Kota Bharu. Tiada bandar diraja ditanda pada peta.', 2),
(1653, NULL, 203, 'e2_n3_s15', 'Saya nyahkod.', 3),
(1654, 31, 203, 'e2_n3_s15', 'Ketua kedua-dua negeri bergelar Sultan.', 4),
(1655, 17, 203, 'e2_n3_s15', 'Kita ke barat. Sebuah lombong menunggu.', 5),
(1656, 31, 203, 'e2_n3_s15', 'Ibu negeri Terengganu dan Kelantan?', 6),
(1657, 56, 203, 'e2_n3_s16', 'Perak dari kilatan ikan, atau bijih timah putih berkilat!', 1),
(1658, 27, 203, 'e2_n3_s16', 'Pulau ini Pulo Ka Satu. Orang Kedah panggil Tanjong Penaga, bersempena pokok penaga.', 2),
(1659, 30, 203, 'e2_n3_s16', 'Pinang juga bahan dagangan penting.', 3),
(1660, 17, 203, 'e2_n3_s16', 'Padankan kesemuanya. Penjaga cop menunggu.', 4),
(1661, 17, 203, 'e2_n3_s16', 'Selepas ini kita periksa dokumen pusat utara.', 5),
(1662, 30, 203, 'e2_n3_s16', 'Mengapa pinang penting pada nama pulau?', 6),
(1663, 40, 203, 'e2_n3_s17', 'Pengembara, saya perlukan dokumen ibu negeri, bandar diraja, lagu dan ketua bagi Perak dan Pulau Pinang.', 1),
(1664, 17, 203, 'e2_n3_s17', 'Ketua Perak bergelar Sultan. Ketua Pulau Pinang bergelar Yang di-Pertua Negeri.', 2),
(1665, NULL, 203, 'e2_n3_s17', 'Saya pilih yang betul.', 3),
(1666, 40, 203, 'e2_n3_s17', 'Dokumen lain bercampur.', 4),
(1667, 17, 203, 'e2_n3_s17', 'Kita ke dua negeri terakhir di utara.', 5),
(1668, 40, 203, 'e2_n3_s17', 'Apa lagu Pulau Pinang?', 6),
(1669, 29, 203, 'e2_n3_s18', 'Kedah dari \'kheddah\', perangkap gajah.', 1),
(1670, 30, 203, 'e2_n3_s18', 'Dari \'qadah\', cawan berkaki. Ada juga \'kadaram\' atau \'kalagam\' dalam tulisan Tamil.', 2),
(1671, 28, 203, 'e2_n3_s18', 'Perlis dari \'prow-lowy\', kelapa hanyut, atau dari \'peroleh\'.', 3),
(1672, 17, 203, 'e2_n3_s18', 'Padankan semuanya.', 4),
(1673, 17, 203, 'e2_n3_s18', 'Cop terakhir. Perlis ialah negeri paling hujung utara.', 5),
(1674, 28, 203, 'e2_n3_s18', 'Siapa Raja Syed Hussin itu?', 6),
(1675, 39, 203, 'e2_n3_s19', 'Lagu Kedah atau lagu Perlis, Pengembara? Saya perlukan Kedah dahulu.', 1),
(1676, 17, 203, 'e2_n3_s19', 'Ketua Kedah bergelar Sultan; ketua Perlis bergelar Raja. Kangar dan Arau; Alor Setar dan Anak Bukit.', 2),
(1677, NULL, 203, 'e2_n3_s19', 'Saya pilih kaset Kedah.', 3),
(1678, 39, 203, 'e2_n3_s19', 'Kalau tersilap, Raja Perlis tersinggung.', 4),
(1679, 17, 203, 'e2_n3_s19', 'Pasport hampir penuh. Satu cop lagi menanti di Wilayah Persekutuan.', 5),
(1680, 39, 203, 'e2_n3_s19', 'Lagu Perlis dan ibu negeri serta bandar diraja?', 6),
(1681, 31, 203, 'e2_n3_s20', 'Cop ini bukan untuk satu negeri. Ia untuk bendera, jata dan lagu semua negeri.', 1),
(1682, 17, 203, 'e2_n3_s20', 'Halaman yang koyak bukan hilang. Ia tersembunyi di pentas.', 2),
(1683, NULL, 203, 'e2_n3_s20', 'Saya cari bukti lambang negeri dahulu.', 3),
(1684, 31, 203, 'e2_n3_s20', 'Setiap negeri mempunyai bendera, lagu dan jata sebagai lambang kemegahan dan kedaulatan.', 4),
(1685, 17, 203, 'e2_n3_s20', 'Kita sampai. Sahabat sebenar bukan cop, tetapi kenangan.', 5),
(1686, 31, 203, 'e2_n3_s20', 'Mengapa kita wajar menghormati lambang negeri?', 6);

