INSERT INTO `learningsupport` (`supportID`, `questID`, `sceneID`, `supportType`, `hint`, `explanation`, `feedback`) VALUES
(99, NULL, 'e3_n1_s1', 'hint', 'Namanya bermula dengan Majlis Gerakan.', NULL, NULL),
(100, 301, NULL, 'hint', 'Selepas 13 Mei 1969, negara ditadbir oleh MAGERAN.', 'Selepas peristiwa 13 Mei 1969, pentadbiran negara dijalankan oleh Majlis Gerakan Negara (MAGERAN).', 'Tepat! MAGERAN dikenal pasti.'),
(101, NULL, 'e3_n1_s2', 'hint', 'Cari ladang, kampung dan rumah kedai.', NULL, NULL),
(102, 302, NULL, 'hint', 'Orang Melayu di kampung, Cina di bandar, India di ladang: kurang peluang berinteraksi.', 'Kegiatan ekonomi berbeza dan tempat tinggal berasingan: Melayu (pertanian sara diri, kampung), Cina (perlombongan dan perniagaan, bandar), India (perladangan, ladang).', 'Berjaya! Tiga bukti ditemui.'),
(103, NULL, 'e3_n1_s3', 'hint', 'Cari perkataan Jawatankuasa Rukun Negara.', NULL, NULL),
(104, 303, NULL, 'hint', 'Jawatankuasa Rukun Negara di bawah MAPEN merangka Rukun Negara pada 4 Mac 1970; MAPEN ada 66 wakil.', '4 Mac 1970: Jawatankuasa Rukun Negara di bawah MAPEN merangka dan memperkenalkan Rukun Negara. MAPEN dianggotai 66 wakil.', 'Hebat! Badan perangka dikenal pasti.'),
(105, NULL, 'e3_n1_s4', 'hint', 'Lima bukti: bendera, buku, timbangan, tempat ibadat, panel.', NULL, NULL),
(106, 304, NULL, 'hint', 'Lima matlamat: perpaduan, demokrasi, masyarakat adil, liberal terhadap kebudayaan, masyarakat progresif.', 'Lima matlamat: perpaduan lebih erat; cara hidup demokrasi; masyarakat adil; liberal terhadap tradisi kebudayaan; masyarakat progresif dengan sains dan teknologi moden.', 'Cemerlang! Lima matlamat ditemui.'),
(107, NULL, 'e3_n1_s5', 'hint', 'Mulakan dengan rusuhan 13 Mei.', NULL, NULL),
(108, 305, NULL, 'hint', '13 Mei 1969, MAGERAN, 4 Mac 1970 (MAPEN), 31 Ogos 1970 (pengisytiharan YDPA Keempat).', 'Rukun Negara: 13 Mei 1969 rusuhan; MAGERAN; 4 Mac 1970 dirangka melalui MAPEN; 31 Ogos 1970 diisytiharkan oleh Yang di-Pertuan Agong Keempat.', 'Cemerlang! Urutan sejarah tersusun.'),
(109, NULL, 'e3_n1_s6', 'hint', 'Lima matlamat, lima maksud.', NULL, NULL),
(110, 306, NULL, 'hint', 'Lima matlamat: perpaduan erat, demokrasi, adil dan saksama, liberal terhadap kebudayaan, progresif dengan sains dan teknologi.', 'Lima matlamat: perpaduan, demokrasi, masyarakat adil, liberal terhadap kebudayaan dan masyarakat progresif.', 'Tepat! Lima matlamat dipadankan.'),
(111, NULL, 'e3_n2_s1', 'hint', 'Satu di sawah, satu di lombong, satu di ladang.', NULL, NULL),
(112, 307, NULL, 'hint', 'Melayu: pertanian sara diri; Cina: perlombongan dan perniagaan; India: perladangan.', 'Perbezaan kegiatan ekonomi: Melayu (pertanian sara diri), Cina (perlombongan dan perniagaan), India (perladangan). Ia mewujudkan jurang ekonomi yang tidak seimbang.', 'Syabas! Kegiatan ekonomi dipadankan.'),
(113, NULL, 'e3_n2_s2', 'hint', 'Fikirkan kekerapan mereka berjumpa.', NULL, NULL),
(114, 308, NULL, 'hint', 'Pengasingan tempat tinggal: kurang peluang berinteraksi antara masyarakat.', 'Pengasingan tempat tinggal (kampung, bandar, ladang) menyebabkan kurangnya peluang berinteraksi.', 'Tepat! Kesan pengasingan dikenal pasti.'),
(115, NULL, 'e3_n2_s3', 'hint', 'Mulakan dengan British membawa pekerja.', NULL, NULL),
(116, 309, NULL, 'hint', 'Rantai: pekerja dibawa masuk, ekonomi berbeza, tempat tinggal berasingan, kurang interaksi, politik berbeza, 13 Mei.', 'Punca: perbezaan kegiatan ekonomi, pengasingan tempat tinggal, perbezaan fahaman politik, yang memuncak sebagai 13 Mei 1969.', 'Cemerlang! Rantai sebab difahami.'),
(117, NULL, 'e3_n2_s4', 'hint', 'Hormat pegangan orang lain.', NULL, NULL),
(118, 310, NULL, 'hint', 'Prinsip 1: agama pegangan utama, hormat amalan agama lain.', 'Kepercayaan kepada Tuhan: agama pegangan utama, hormati amalan agama lain, menyatupadukan masyarakat berbilang kaum.', 'Tepat! Prinsip pertama difahami.'),
(119, NULL, 'e3_n2_s5', 'hint', 'Cari orang berdoa, jata dan tugu.', NULL, NULL),
(120, 311, NULL, 'hint', 'Ketua Utama Negara ialah Yang di-Pertuan Agong.', 'Prinsip 2: Kesetiaan kepada Raja dan Negara. Ketua Utama Negara ialah Yang di-Pertuan Agong. Prinsip ini mewujudkan semangat patriotik.', 'Berjaya! Tiga petunjuk ditemui.'),
(121, NULL, 'e3_n2_s6', 'hint', 'Prinsip ketiga: perlembagaan tertinggi.', NULL, NULL),
(122, 312, NULL, 'hint', 'Lima prinsip: Tuhan, raja dan negara, perlembagaan, undang-undang, sopan santun.', 'Lima prinsip: Kepercayaan kepada Tuhan, Kesetiaan kepada Raja dan Negara, Keluhuran Perlembagaan, Kedaulatan Undang-undang, Kesopanan dan Kesusilaan.', 'Cemerlang! Lima prinsip dipadankan.'),
(123, NULL, 'e3_n3_s1', 'hint', 'Fikirkan patuh dan bersyukur.', NULL, NULL),
(124, 313, NULL, 'hint', 'Prinsip kepercayaan kepada Tuhan: patuh ajaran agama, mengelakkan rasuah, dadah dan keruntuhan moral.', 'Meraikan kepelbagaian agama: masyarakat patuh ajaran agama, rendah diri, bersyukur dan mengelakkan dengki, rasuah, dadah dan keruntuhan moral.', 'Tepat! Peranan prinsip pertama difahami.'),
(125, NULL, 'e3_n3_s2', 'hint', 'Tiga lambang: bendera, jata, lagu.', NULL, NULL),
(126, 314, NULL, 'hint', 'Patriotik: cinta negara, taat setia, sanggup berkorban, hormat Jalur Gemilang, Jata Negara dan Negaraku.', 'Rukun Negara membentuk masyarakat patriotik yang menghormati lambang kedaulatan negara.', 'Hebat! Peranan patriotik difahami.'),
(127, NULL, 'e3_n3_s3', 'hint', 'Fikirkan keamanan.', NULL, NULL),
(128, 315, NULL, 'hint', 'Hormati undang-undang: keamanan, kesejahteraan, jauh daripada jenayah.', 'Rukun Negara memupuk sikap menghormati undang-undang dan membimbing rakyat daripada kegiatan jenayah.', 'Tepat! Kepentingan undang-undang difahami.'),
(129, NULL, 'e3_n3_s4', 'hint', 'Bertolak ansur dengan jiran.', NULL, NULL),
(130, 316, NULL, 'hint', 'Perpaduan: permuafakatan, toleransi, hormat budaya kaum lain.', 'Rukun Negara mengukuhkan perpaduan melalui semangat permuafakatan dan toleransi, serta menghormati budaya kaum lain.', 'Syabas! Peranan perpaduan difahami.'),
(131, NULL, 'e3_n3_s5', 'hint', 'Integriti = kejujuran yang tulen dan tidak berubah.', NULL, NULL),
(132, 317, NULL, 'hint', 'Enam peranan: kepelbagaian agama, patriotik, undang-undang, perpaduan, nilai murni, jati diri (integriti).', 'Peranan Rukun Negara: meraikan kepelbagaian agama, masyarakat patriotik, hormati undang-undang, kukuhkan perpaduan, terapkan nilai murni, bentuk jati diri.', 'Cemerlang! Enam peranan dipadankan.'),
(133, NULL, 'e3_n3_s6', 'hint', 'Cari gulungan, papan, pokok, warga emas.', NULL, NULL),
(134, 318, NULL, 'hint', 'Prinsip 3: keluhuran perlembagaan; 4: kedaulatan undang-undang; 5: kesopanan dan kesusilaan.', 'Prinsip 3 hingga 5: Keluhuran Perlembagaan, Kedaulatan Undang-undang, Kesopanan dan Kesusilaan. Nilai murni membentuk masyarakat berdisiplin dan harmoni.', 'Berjaya! Empat petunjuk ditemui.'),
(135, NULL, 'e4_n1_s1', 'hint', 'Sikh ialah Punjabi. Serani ialah Kristang.', NULL, NULL),
(136, 401, NULL, 'hint', 'Setiap kaum ada bahasa sendiri: Cina (Mandarin, Hokkien), India (Tamil, Telugu), Sikh (Punjabi).', 'Bahasa kaum: Cina (Mandarin, Hokkien, Hakka, Kantonis), India (Tamil, Telugu, Malayalam), Sikh (Punjabi), Serani (Kristang) dan Baba Nyonya (Melayu Baba).', 'Tepat! Bahasa setiap kaum dipadankan.'),
(137, NULL, 'e4_n1_s2', 'hint', 'Satu daripadanya bernama Semang.', NULL, NULL),
(138, 402, NULL, 'hint', 'Orang Asli: Negrito (Semang), Senoi dan Melayu Proto.', 'Orang Asli di Semenanjung terbahagi kepada Negrito (Semang), Senoi dan Melayu Proto. Mereka mengekalkan kraf tangan, ubat herba dan bahasa mengikut suku.', 'Syabas! Tiga kumpulan Orang Asli dikenal pasti.'),
(139, NULL, 'e4_n1_s3', 'hint', 'Baba dan Nyonya bermula daripada pedagang China.', NULL, NULL),
(140, 403, NULL, 'hint', 'Kaum peranakan lahir daripada perkahwinan pedagang dengan penduduk tempatan.', 'Baba dan Nyonya, Chetti serta Serani lahir daripada perkahwinan pedagang dengan penduduk tempatan. Siam menyambut Songkran dan Sikh bertutur Punjabi.', 'Hebat! Ciri setiap kaum dipadankan.'),
(141, NULL, 'e4_n1_s4', 'hint', 'Pua kumbu ialah tenunan Iban.', NULL, NULL),
(142, 404, NULL, 'hint', 'Kaum terbesar: Iban di Sarawak dan Kadazandusun di Sabah.', 'Iban ialah kaum terbesar di Sarawak (pua kumbu, Hari Gawai). Kadazandusun ialah kaum terbesar di Sabah (Pesta Kaamatan).', 'Tepat! Kaum terbesar dikenal pasti.'),
(143, NULL, 'e4_n1_s5', 'hint', 'Cari lima kumpulan: tiga di Semenanjung, dua di Borneo.', NULL, NULL),
(144, 405, NULL, 'hint', 'Lima pentas: Melayu, Cina, India, Sarawak dan Sabah.', 'Alat muzik dan tarian: Melayu (gambus, angklung; makyung, zapin), Cina (gendang, bo; tarian singa), India (veenai, talam; bharata natyam), Sarawak (sape, engkerurai; ngajat), Sabah (kulintangan, sompoton; sumazau).', 'Berjaya! Lima pentas ditemui.'),
(145, NULL, 'e4_n1_s6', 'hint', 'Nafiri ditiup, diperbuat daripada logam.', NULL, NULL),
(146, 406, NULL, 'hint', 'Alat muzik tradisional menggunakan bahan alam: buluh, kayu, kulit haiwan dan logam.', 'Ciri alat muzik: angklung (buluh, ancak), gambus (kayu keras), nafiri (logam, perak), geduk (belulang lembu atau kerbau), sape (meranti), sompoton (buluh, labu kering).', 'Hebat! Alat muzik dan bahannya dipadankan.'),
(147, NULL, 'e4_n1_s7', 'hint', 'Sumazau berkait dengan padi dan Kaamatan.', NULL, NULL),
(148, 407, NULL, 'hint', 'Tarian: makyung (drama), zapin (pesta), singa (Tahun Baharu Cina), bharata natyam (pembuka tirai), ngajat (Gawai), sumazau (padi).', 'Tarian dan tujuan: makyung (drama tradisional), zapin (hiburan), tarian singa (Tahun Baharu Cina), bharata natyam (pembuka tirai), ngajat (Hari Gawai), sumazau (semangat padi).', 'Tepat! Tarian dipadankan dengan tujuannya.'),
(149, NULL, 'e4_n1_s8', 'hint', 'Cari selempang bunga dan kulit kayu.', NULL, NULL),
(150, 408, NULL, 'hint', 'Sewang menggunakan selempang bunga, daun dan kulit kayu.', 'Sewang: tarian Orang Asli untuk ritual, perubatan dan keramaian. Bhangra: tarian Sikh dengan dram dhol, harmonika dan tamborin.', 'Syabas! Tarian sewang dikenal pasti.'),
(151, NULL, 'e4_n2_s1', 'hint', 'Cari perkataan sungai dan pantai.', NULL, NULL),
(152, 409, NULL, 'hint', 'Melayu dahulu: kampung, pesisir pantai, sungai; petani, nelayan, peniaga kecil, perkhidmatan awam.', 'Masyarakat Melayu dahulu tinggal di kampung, pesisir pantai dan sungai; bekerja sebagai petani, nelayan, peniaga kecil-kecilan dan dalam perkhidmatan awam.', 'Tepat! Melayu dahulu difahami.'),
(153, NULL, 'e4_n2_s2', 'hint', 'Pelombong bekerja di lombong, pekerja ladang di ladang.', NULL, NULL),
(154, 410, NULL, 'hint', 'Cina dahulu: pekan dan bandar, pelombong, peniaga. India dahulu: ladang, pinggir bandar.', 'Cina dahulu tinggal di pekan dan bandar sebagai pelombong dan peniaga. India dahulu tinggal di ladang dan pinggir bandar sebagai pekerja ladang, peniaga kecil dan pekerja pelabuhan.', 'Cemerlang! Dua kaum dipadankan.'),
(155, NULL, 'e4_n2_s3', 'hint', 'Pedalaman, berburu, kraf.', NULL, NULL),
(156, 411, NULL, 'hint', 'Orang Asli dahulu: pedalaman, kraf tangan, berburu, hasil hutan.', 'Orang Asli dahulu tinggal di pedalaman (Perak, Selangor, Pahang, Kelantan, Terengganu); mengusahakan kraf tangan, berburu dan mengutip hasil hutan.', 'Tepat! Orang Asli dahulu difahami.'),
(157, NULL, 'e4_n2_s4', 'hint', 'Sagu dan perahu: pesisir pantai.', NULL, NULL),
(158, 412, NULL, 'hint', 'Sarawak dahulu: pedalaman, lembah sungai dan pesisir pantai.', 'Sarawak dahulu: Bidayuh, Kenyah, Kelabit di pedalaman; Iban dan Bisaya di lembah sungai sebagai petani; Melayu, Melanau, Kedayan di pesisir pantai sebagai pedagang, pembuat perahu dan pengusaha sagu.', 'Hebat! Peta kaum Sarawak lengkap.'),
(159, NULL, 'e4_n2_s5', 'hint', 'Rungus terkenal dengan seni kreatif.', NULL, NULL),
(160, 413, NULL, 'hint', 'Sabah dahulu: Murut dan Kadazandusun di pedalaman, Rungus kreatif, Bajau petani atau nelayan.', 'Sabah dahulu: Murut (pedalaman, petani, hasil hutan), Kadazandusun (padi), Rungus (seni kreatif), Bajau (petani atau nelayan), Melayu Brunei, Iranun dan Suluk (pesisir pantai).', 'Cemerlang! Peta kaum Sabah lengkap.'),
(161, NULL, 'e4_n2_s6', 'hint', 'Mulakan dengan sebelum merdeka.', NULL, NULL),
(162, 414, NULL, 'hint', 'Dahulu berasingan mengikut ekonomi. Kini bersama tanpa pemisahan tempat tinggal.', 'Dahulu petempatan mengikut kegiatan ekonomi. Selepas merdeka dan pembentukan Malaysia, pemimpin merancang dasar; kini tiada pengasingan tempat tinggal kerana toleransi dan kemakmuran.', 'Tepat! Perubahan dari dahulu hingga kini tersusun.'),
(163, NULL, 'e4_n2_s7', 'hint', 'Mulakan dengan hukuman raja.', NULL, NULL),
(164, 415, NULL, 'hint', 'Si Luncai bijak, tetapi iktibar cerita ini ialah jangan mempersendakan orang lain.', 'Si Luncai dengan Labu-labunya: dihukum raja, dimasukkan dalam guni, menyanyi lalu terjun dengan labu air. Iktibar: jangan mempersendakan orang lain.', 'Hebat! Jalan cerita Si Luncai tersusun.'),
(165, NULL, 'e4_n2_s8', 'hint', 'Santubong menenun, Sejinjang menumbuk padi.', NULL, NULL),
(166, 416, NULL, 'hint', 'Santubong menenun, Sejinjang menumbuk padi. Mereka bertukar jadi gunung kerana bergaduh.', 'Legenda Santubong Sang Puteri: Puteri Santubong menenun, Puteri Sejinjang menumbuk padi; mereka bertelingkah lalu menjadi gunung. Iktibar: jangan bertengkar sesama sendiri.', 'Tepat! Watak dan jalan cerita Santubong dipadankan.'),
(167, NULL, 'e4_n3_s1', 'hint', 'Wau di langit, congkak di anjung.', NULL, NULL),
(168, 417, NULL, 'hint', 'Tiga jenis: anjung, laman, kawasan lapang.', 'Permainan tradisional terdiri daripada permainan anjung, permainan laman dan permainan kawasan lapang.', 'Berjaya! Lima petunjuk ditemui.'),
(169, NULL, 'e4_n3_s2', 'hint', 'Chap teh dalam bahasa Melayu ialah tating lawi.', NULL, NULL),
(170, 418, NULL, 'hint', 'Congkak: lubang pada papan. Batu seremban: batu kecil. Go: buah hitam dan putih.', 'Congkak (papan berlubang), batu seremban (lima atau tujuh biji batu), go (buah hitam dan putih), kabaddi (dua pasukan), chap teh atau tating lawi (bola lawi), sepak raga (bola rotan).', 'Hebat! Permainan dan cara bermain dipadankan.'),
(171, NULL, 'e4_n3_s3', 'hint', 'Tibau ialah Melanau, sepak manggis ialah Sabah.', NULL, NULL),
(172, 419, NULL, 'hint', 'Wau selepas menuai. Tibau di Sarawak. Sepak manggis di Kota Belud, Sabah.', 'Permainan lapang: wau (selepas musim menuai), tibau (Pesta Kaul Melanau), sepak manggis (Kota Belud, Sabah), gasing (uri dan pangkah).', 'Tepat! Empat permainan lapang dipadankan.'),
(173, NULL, 'e4_n3_s4', 'hint', 'Cari perkataan raja dan tentera.', NULL, NULL),
(174, 420, NULL, 'hint', 'Chaturangam: seperti catur, dua pemain, tewaskan raja.', 'Chaturangam seperti catur: dua pemain, simulasi peperangan, menewaskan raja. Paramapadham seperti dam ular. Go dan yoyo Cina dari budaya Cina.', 'Syabas! Chaturangam dikenal pasti.'),
(175, NULL, 'e4_n3_s5', 'hint', 'Cari congkak pada senarai.', NULL, NULL),
(176, 421, NULL, 'hint', 'Warisan kebangsaan: congkak, batu seremban, kabaddi, tating lawi, sepak raga dan lain-lain.', 'Permainan tradisional warisan kebangsaan termasuk congkak, batu seremban, kabaddi, tating lawi, menyumpit, pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli.', 'Tepat! Warisan kebangsaan dikenal pasti.'),
(177, NULL, 'e4_n3_s6', 'hint', 'Pohon nunuk, ayam gergasi, sungai.', NULL, NULL),
(178, 422, NULL, 'hint', 'Nunuk Ragang: pohon nunuk, ayam gergasi merah bertaji emas, Sungai Liwagu.', 'Legenda Nunuk Ragang menceritakan kemunculan pelbagai kaum di Tambunan dan Ranau, Sabah. Penduduk terpisah dan membina dialek masing-masing. Iktibar: menghargai asal usul keturunan.', 'Cemerlang! Tiga petunjuk ditemui.'),
(179, NULL, 'e4_n3_s7', 'hint', 'Fikirkan keharmonian dan salah faham.', NULL, NULL),
(180, 423, NULL, 'hint', 'Toleransi: tiada pergaduhan, harmoni, patriotisme, elak salah faham.', 'Bertoleransi antara kaum ialah asas perpaduan: tiada pergaduhan, kekalkan keharmonian dan kesejahteraan, kukuhkan patriotisme, elak salah faham.', 'Tepat! Kepentingan toleransi difahami.'),
(181, NULL, 'e4_n3_s8', 'hint', 'Hormat-menghormati mengeratkan perpaduan.', NULL, NULL),
(182, 424, NULL, 'hint', 'Keunikan budaya: tumpuan pelancong, warisan, patriotisme. Berkongsi maklumat: persefahaman dan perpaduan.', 'Menghargai keunikan budaya menarik pelancong, memupuk patriotisme dan memelihara warisan. Berkongsi maklumat memupuk persefahaman dan mengeratkan perpaduan antara kaum.', 'Cemerlang! Kepentingan budaya dipadankan.'),
(183, NULL, 'e5_n1_s1', 'hint', 'Kung Fu Tze dikenali sebagai Konfusius.', NULL, NULL),
(184, 501, NULL, 'hint', 'Buddha: Siddharta Gautama. Sikh: Guru Nanak. Konfusius: Kung Fu Tze. Tao: Lao Tzu.', 'Pengasas: Buddha (Siddharta Gautama), Sikh (Guru Nanak), Konfusius (Kung Fu Tze), Tao (Lao Tzu). Kristian dibawa oleh Jesus Christ. Islam menyembah Allah Yang Maha Esa.', 'Tepat! Agama dan pengasas dipadankan.'),
(185, NULL, 'e5_n1_s2', 'hint', 'Tipitaka Buddha, Veda Hindu.', NULL, NULL),
(186, 502, NULL, 'hint', 'Kitab: al-Quran, Bible, Tipitaka, Veda, Sri Guru Granth Sahib dan Tao Te Ching.', 'Kitab suci: al-Quran (Islam), Bible (Kristian), Tipitaka (Buddha), Veda (Hindu), Sri Guru Granth Sahib (Sikh), Tao Te Ching (Ajaran Tao). Analek ialah buku Ajaran Konfusius.', 'Hebat! Kitab suci dipadankan.'),
(187, NULL, 'e5_n1_s3', 'hint', 'Karma berkait dengan perbuatan.', NULL, NULL),
(188, 503, NULL, 'hint', 'Hindu: Hukum Karma, kelahiran semula, kitab Veda.', 'Agama Hindu: percaya Hukum Karma (berkaitan kelakuan manusia semasa hidup) dan kelahiran semula selepas mati; kitab suci Veda.', 'Tepat! Kepercayaan Hindu difahami.'),
(189, NULL, 'e5_n1_s4', 'hint', 'Analek: moral dan ketaatan ibu bapa.', NULL, NULL),
(190, 504, NULL, 'hint', 'Konfusius: moral, Analek. Tao: harmoni dengan alam, Tao Te Ching.', 'Ajaran Konfusius (Kung Fu Tze): prinsip moral perikemanusiaan, kesusilaan, taat ibu bapa; buku Analek. Ajaran Tao (Lao Tzu): harmoni dengan alam semesta; buku Tao Te Ching.', 'Syabas! Ajaran Konfusius dibezakan dengan Tao.'),
(191, NULL, 'e5_n1_s5', 'hint', 'Tiga golongan: pemerintah, pedagang, golongan agama.', NULL, NULL),
(192, 505, NULL, 'hint', 'Penyebaran: pemerintah, pedagang, golongan agama.', 'Agama disebarkan melalui peranan pemerintah, pedagang dan golongan agama. Rakyat Malaysia mengamalkan Islam, Kristian, Buddha, Hindu, Sikh serta ajaran Konfusius dan Tao.', 'Tepat! Cara penyebaran dikenal pasti.'),
(193, NULL, 'e5_n1_s6', 'hint', 'Waheguru ialah Tuhan bagi Sikh.', NULL, NULL),
(194, 506, NULL, 'hint', 'Islam: Rukun Islam, Rukun Iman. Kristian: Ahad di gereja. Sikh: Waheguru.', 'Islam (Rukun Islam dan Rukun Iman), Kristian (Ahad di gereja), Sikh (Waheguru), Buddha (Empat Kebenaran Mulia, Jalan Lapan Lapis Mulia), Tao (jalan, hidup harmoni dengan alam).', 'Cemerlang! Amalan setiap agama dipadankan.'),
(195, NULL, 'e5_n1_s7', 'hint', 'Gurdwara dan kuil dekat-dekat.', NULL, NULL),
(196, 507, NULL, 'hint', 'Islam masjid; Kristian gereja; Buddha tokong atau wat; Hindu kuil; Sikh gurdwara.', 'Rumah ibadat: masjid (Islam), gereja (Kristian), tokong atau wat (Buddha), tokong (Konfusius dan Tao), kuil (Hindu), gurdwara (Sikh).', 'Cemerlang! Enam rumah ibadat ditemui.'),
(197, NULL, 'e5_n1_s8', 'hint', 'Empat kepentingan: maju, harmoni, disiplin, matlamat.', NULL, NULL),
(198, 508, NULL, 'hint', 'Agama: masyarakat maju, harmoni, berdisiplin, bermatlamat.', 'Kepentingan amalan agama dan kepercayaan: masyarakat lebih maju, hidup harmoni, berdisiplin dan mempunyai matlamat dalam kehidupan.', 'Tepat! Kepentingan agama difahami.'),
(199, NULL, 'e5_n2_s1', 'hint', 'Semangat ada pada gua, pokok, batu.', NULL, NULL),
(200, 509, NULL, 'hint', 'Animisme: semangat dan roh nenek moyang dalam gua, pokok, batu.', 'Animisme: kepercayaan bahawa gua, pokok atau batu besar mempunyai semangat dan roh nenek moyang yang mesti dihormati.', 'Tepat! Animisme dikenal pasti.'),
(201, NULL, 'e5_n2_s2', 'hint', 'Mah Meri di Pulau Carey. Temiar dan Semai ritual.', NULL, NULL),
(202, 510, NULL, 'hint', 'Mah Meri: Puja Pantai. Temiar dan Semai: upacara menghalau kuasa jahat.', 'Mah Meri di Pulau Carey mengadakan Puja Pantai untuk perlindungan dan pengampunan semangat laut. Temiar dan Semai mengadakan upacara ritual untuk menghalau kuasa jahat. Orang Asli percaya penyakit disebabkan kuasa jahat.', 'Syabas! Upacara Orang Asli dipadankan.'),
(203, NULL, 'e5_n2_s3', 'hint', 'Lemambang ialah penyair.', NULL, NULL),
(204, 511, NULL, 'hint', 'Iban: Petara (dewa), Miring (upacara), Lemambang (penyair).', 'Masyarakat Iban mempercayai Petara (dewa) menyampaikan petanda melalui mimpi dan bayangan. Petara dipuja melalui upacara Miring yang dimulai dengan jampi mantera oleh Lemambang.', 'Hebat! Istilah Iban dipadankan.'),
(205, NULL, 'e5_n2_s4', 'hint', 'Bisaya dan Tamarok.', NULL, NULL),
(206, 512, NULL, 'hint', 'Bisaya: jampi mantera membuka tanah, Tamarok halau kuasa ghaib daripada badan pesakit.', 'Bisaya di Sarawak membaca jampi mantera semasa membuka kawasan pertanian baharu dan menjalankan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', 'Tepat! Upacara Tamarok dikenal pasti.'),
(207, NULL, 'e5_n2_s5', 'hint', 'Ngeduang barat, Mag\'ombo timur.', NULL, NULL),
(208, 513, NULL, 'hint', 'Ngeduang: Kota Belud. Mag\'ombo: Semporna.', 'Bajau di pantai barat (Kota Belud) mengadakan Ngeduang untuk menjamu tetamu sebagai sedekah. Bajau di pantai timur (Semporna) mengadakan Mag\'ombo untuk menghargai warisan nenek moyang.', 'Cemerlang! Upacara Bajau dipadankan.'),
(209, NULL, 'e5_n2_s6', 'hint', 'Bobohizan mengetuai upacara.', NULL, NULL),
(210, 514, NULL, 'hint', 'Kinorohingan: Tuhan. Magavau: semangat padi. Bobohizan: ketua bomoh.', 'Kadazandusun mempercayai Kinorohingan (Tuhan untuk meminta keselamatan dan perlindungan), semangat padi melalui upacara Magavau, dan upacara diketuai Bobohizan.', 'Syabas! Istilah Kadazandusun dipadankan.'),
(211, NULL, 'e5_n2_s7', 'hint', 'Perahu, gerbang, tikar, rumah atas air.', NULL, NULL),
(212, 515, NULL, 'hint', 'Mag\'ombo: Semporna. Ngeduang: Kota Belud.', 'Mag\'ombo di Semporna (pantai timur) menghargai warisan turun-temurun; Ngeduang di Kota Belud (pantai barat) menjamu tetamu sebagai sedekah.', 'Berjaya! Empat petunjuk ditemui.'),
(213, NULL, 'e5_n2_s8', 'hint', 'Lima kaum, lima upacara.', NULL, NULL),
(214, 516, NULL, 'hint', 'Bobohizan, Lemambang, Mah Meri, Bisaya, Bajau: setiap kaum ada penjaga adat.', 'Penjaga adat: Bobohizan (Kadazandusun), Lemambang (Iban), Mah Meri (Puja Pantai), Bisaya (Tamarok), Bajau (Ngeduang dan Mag\'ombo).', 'Cemerlang! Penjaga adat dipadankan.'),
(215, NULL, 'e5_n3_s1', 'hint', 'Memorandum dahulu, Perkara 3 kemudian.', NULL, NULL),
(216, 517, NULL, 'hint', 'Memorandum 1957, Islam diakui, Perkara 3, titah perkenan.', 'Islam diakui agama Persekutuan selepas memorandum kepada Suruhanjaya Perlembagaan Tanah Melayu 1957; kedudukannya dalam Perkara 3; perubahan perlu titah perkenan Yang di-Pertuan Agong dan Raja-Raja Melayu.', 'Tepat! Urutan tersusun.'),
(217, NULL, 'e5_n3_s2', 'hint', 'Negeri tanpa Raja: Yang di-Pertuan Agong.', NULL, NULL),
(218, 518, NULL, 'hint', 'Raja ketua agama di negeri berRaja. Yang di-Pertuan Agong di Melaka, Pulau Pinang, Sabah, Sarawak, KL, Labuan, Putrajaya.', 'Perkara 3: (1) Islam agama Persekutuan, agama lain diamalkan dengan aman dan damai; (2) Raja ketua agama Islam di negerinya; (3) Yang di-Pertuan Agong di Melaka, Pulau Pinang, Sabah, Sarawak; (5) di Kuala Lumpur, Labuan dan Putrajaya.', 'Cemerlang! Perkara 3 dipadankan.'),
(219, NULL, 'e5_n3_s3', 'hint', 'Perkara 11 menyentuh hak beragama.', NULL, NULL),
(220, 519, NULL, 'hint', 'Perkara 11(1): hak menganuti dan mengamalkan agama. 11(3)(a): urus hal ehwal agama sendiri.', 'Perkara 11 (1): tiap-tiap orang berhak menganuti dan mengamalkan agamanya. Perkara 11 (3)(a): tiap-tiap kumpulan agama berhak menguruskan hal ehwal agamanya sendiri.', 'Tepat! Perkara 11 dipadankan.'),
(221, NULL, 'e5_n3_s4', 'hint', 'Gurdwara ialah rumah ibadat Sikh.', NULL, NULL),
(222, 520, NULL, 'hint', 'Masjid, gereja, kuil, gurdwara, wat, tokong.', 'Rumah ibadat: masjid (Islam), gereja (Kristian), kuil (Hindu), gurdwara (Sikh), wat atau tokong (Buddha), tokong (Konfusius dan Tao).', 'Berjaya! Enam rumah ibadat ditemui.'),
(223, NULL, 'e5_n3_s5', 'hint', 'Kampung Laut ialah antara yang tertua.', NULL, NULL),
(224, 521, NULL, 'hint', 'Masjid Negara 1965; Kampung Laut abad ke-18; Al-Qadim 1830.', 'Masjid Negara (dibina 1963, dirasmikan 27 Ogos 1965, 15 000 jemaah), Masjid Kampung Laut (abad ke-18, Kota Bharu), Masjid Al-Qadim (1830, Sibu, Tuan Haji Salam Minangkabau).', 'Hebat! Tiga masjid dipadankan.'),
(225, NULL, 'e5_n3_s6', 'hint', 'Cheng Hoon Teng bermaksud Kediaman di Awan Hijau.', NULL, NULL),
(226, 522, NULL, 'hint', 'St. Michael: granit tertua. Cheng Hoon Teng: Kediaman di Awan Hijau. Sri Rajakaliamman: kuil kaca.', 'Gereja St. Michael (1893, granit tertua), Wat Boonyaram (1932, Kodiang), Cheng Hoon Teng (1645, Kediaman di Awan Hijau), Sri Rajakaliamman (kuil kaca), Wadda Gurdwara Sahib (1901, seni bina Moor).', 'Cemerlang! Rumah ibadat dipadankan.'),
(227, NULL, 'e5_n3_s7', 'hint', 'Silaturahim dan perpaduan.', NULL, NULL),
(228, 523, NULL, 'hint', 'Adab: hormati kebebasan beragama, eratkan silaturahim dan perpaduan, kenali agama lain.', 'Memahami adab di rumah ibadat: menghormati kebebasan beragama (Perlembagaan), mengeratkan silaturahim dan perpaduan, mengenali agama lain dan menunjukkan keperibadian terpuji.', 'Tepat! Kepentingan adab difahami.'),
(229, NULL, 'e5_n3_s8', 'hint', 'Hormat membawa harmoni.', NULL, NULL),
(230, 524, NULL, 'hint', 'Hormat kepelbagaian agama: persefahaman, sensitiviti, silaturahim, harmoni, tiada perbalahan.', 'Menghormati kepelbagaian agama dan kepercayaan mengukuhkan persefahaman, menjaga sensitiviti, mengeratkan silaturahim, mewujudkan harmoni dan mengelakkan perbalahan.', 'Cemerlang! Rumusan lengkap.'),
(231, NULL, 'e6_n1_s1', 'hint', 'Aidilfitri 1 Syawal, Aidiladha 10 Zulhijah.', NULL, NULL),
(232, 601, NULL, 'hint', 'Aidilfitri 1 Syawal. Aidiladha 10 Zulhijah. Krismas 25 Disember. Gawai 1 Jun.', 'Tarikh: Aidilfitri (1 Syawal), Aidiladha (10 Zulhijah), Tahun Baharu Cina (hari pertama kalendar Cina), Krismas (25 Disember), Hari Gawai (1 Jun), Pesta Kaamatan (Mei).', 'Tepat! Tarikh perayaan dipadankan.'),
(233, NULL, 'e6_n1_s2', 'hint', 'Korban dan Tasyrik.', NULL, NULL),
(234, 602, NULL, 'hint', 'Aidiladha: 10 Zulhijah, ibadah korban. Aidilfitri: 1 Syawal selepas puasa sebulan.', 'Aidiladha disambut pada 10 Zulhijah dan hari Tasyrik (11, 12, 13) dengan ibadah korban dan sedekah daging. Aidilfitri pada 1 Syawal selepas puasa sebulan.', 'Tepat! Aidiladha dikenal pasti.'),
(235, NULL, 'e6_n1_s3', 'hint', 'Chap Goh Meh ialah hari ke-15.', NULL, NULL),
(236, 603, NULL, 'hint', 'Makan malam, hari pertama, 15 hari, Chap Goh Meh.', 'Tahun Baharu Cina bermula dengan makan malam keluarga, disambut pada hari pertama kalendar Cina dan berlanjutan selama 15 hari hingga Chap Goh Meh.', 'Cemerlang! Urutan Tahun Baharu Cina tersusun.'),
(237, NULL, 'e6_n1_s4', 'hint', 'Deepavali: pelita dan kolam.', NULL, NULL),
(238, 604, NULL, 'hint', 'Deepavali: kolam dan pelita. Thaipusam: Dewa Murugan. Vaisakhi: Gurdwara, syukur tanaman.', 'Deepavali (bulan Aippasi) melambangkan kecerahan mengatasi kegelapan dengan kolam dan pelita. Thaipusam (bulan ke-10) ialah persembahan kepada Dewa Murugan. Vaisakhi (14 Vaisakh) disambut kaum Sikh di Gurdwara.', 'Hebat! Tiga perayaan dipadankan.'),
(239, NULL, 'e6_n1_s5', 'hint', 'Gawai: Sarawak. Kaamatan: Sabah.', NULL, NULL),
(240, 605, NULL, 'hint', 'Gawai: 1 Jun, Sarawak, ngajat. Kaamatan: Mei, Sabah, Magavau.', 'Hari Gawai (1 Jun, Dayak, Iban dan Bidayuh, ngajat di rumah panjang) dan Pesta Kaamatan (Mei, Kadazandusun dan Murut, Magavau, sumazau, Unduk Ngadau); kedua-duanya kesyukuran atas hasil tani.', 'Tepat! Gawai dan Kaamatan dibezakan.'),
(241, NULL, 'e6_n1_s6', 'hint', 'Tiga peristiwa Siddharta pada Wesak.', NULL, NULL),
(242, 606, NULL, 'hint', 'Krismas: Jesus Christ, hadiah, karol. Wesak: Siddharta, mandi patung, makanan kepada sami.', 'Krismas (25 Disember) memperingati kelahiran Jesus Christ. Wesak (Mei) dikaitkan dengan kelahiran, kesempurnaan fikiran dan nirwana Siddharta; patung dimandikan dan makanan diagih kepada sami.', 'Tepat! Krismas dan Wesak dipadankan.'),
(243, NULL, 'e6_n1_s7', 'hint', 'Mah Meri: Tawun Empai.', NULL, NULL),
(244, 607, NULL, 'hint', 'Jakun: Tahon Baro. Semai: Jis Pai. Temuan: Tahun Bahauk. Mah Meri: Tawun Empai.', 'Tahun Baharu Orang Asli bermula 31 Disember: Jakun (Tahon Baro), Semai (Jis Pai), Temuan (Tahun Bahauk), Mah Meri (Tawun Empai). Semai meraikan Hari Genggulang dan Orang Asli Selangor serta Negeri Sembilan meraikan Hari Moyang.', 'Syabas! Sambutan Orang Asli dipadankan.'),
(245, NULL, 'e6_n1_s8', 'hint', 'Penaung nelayan dan tarian branyo.', NULL, NULL),
(246, 608, NULL, 'hint', 'San Pedro: Portugis Melaka, Jun, penaung nelayan, branyo.', 'San Pedro disambut masyarakat berketurunan Portugis di Melaka pada bulan Jun, meraikan penaung nelayan; kapal dihias dan tarian branyo ditarikan.', 'Tepat! San Pedro dikenal pasti.'),
(247, NULL, 'e6_n2_s1', 'hint', 'Deepavali: baik atasi jahat. Wesak: tokoh agama.', NULL, NULL),
(248, 609, NULL, 'hint', 'Lima tujuan: keagamaan, tahun baharu, syukur, baik atasi jahat, tokoh agama.', 'Tujuan perayaan: keagamaan, meraikan tahun baharu, mensyukuri hasil tanaman atau laut, mengharapkan unsur baik mengatasi kejahatan (Deepavali) dan mengingati tokoh agama (Wesak).', 'Tepat! Lima tujuan dipadankan.'),
(249, NULL, 'e6_n2_s2', 'hint', 'Pos dahulu, media sosial kini.', NULL, NULL),
(250, 610, NULL, 'hint', 'Dahulu: pos, serahan tangan, kedai gambar. Kini: elektronik, media sosial, swafoto.', 'Dahulu kad ucapan melalui pos atau serahan tangan dan foto di kedai gambar. Kini ucapan melalui media elektronik dan media sosial, dan swafoto bersama keluarga.', 'Syabas! Cara dahulu dan kini dipadankan.'),
(251, NULL, 'e6_n2_s3', 'hint', 'Cari kamera, latar, kerusi dan lampu.', NULL, NULL),
(252, 611, NULL, 'hint', 'Kamera lama, latar lukisan, kerusi, lampu studio.', 'Dahulu foto keluarga diambil di kedai gambar dengan kamera lama, latar lukisan dan lampu studio. Kini murid mengambil swafoto sendiri.', 'Berjaya! Empat bukti ditemui.'),
(253, NULL, 'e6_n2_s4', 'hint', 'Cari beras berwarna dan pelita.', NULL, NULL),
(254, 612, NULL, 'hint', 'Kolam dahulu: tepung. Kolam kini: beras atau hampas kelapa berwarna-warni.', 'Dahulu kolam Deepavali dibuat daripada tepung. Kini ia dihasilkan daripada beras atau hampas kelapa yang berwarna-warni, tetapi tradisi menghias rumah masih kekal.', 'Cemerlang! Empat bukti ditemui.'),
(255, NULL, 'e6_n2_s5', 'hint', 'Tradisi sama, tempat mungkin berubah.', NULL, NULL),
(256, 613, NULL, 'hint', 'Makan besar: dahulu di rumah, kini ada yang di restoran atau hotel.', 'Makan besar malam Tahun Baharu Cina masih diraikan; dahulu di rumah bersama keluarga, kini ada yang memilih restoran atau hotel.', 'Tepat! Perubahan dikenal pasti.'),
(257, NULL, 'e6_n2_s6', 'hint', 'Dahulu: gotong-royong.', NULL, NULL),
(258, 614, NULL, 'hint', 'Kuih dahulu: bahan dan kaedah tradisional, gotong-royong.', 'Kuih dahulu disediakan dengan bahan dan kaedah tradisional secara gotong-royong. Kini peralatan moden memudahkan penyediaan dan kuih raya mudah dibeli.', 'Tepat! Cara dahulu dikenal pasti.'),
(259, NULL, 'e6_n2_s7', 'hint', 'Rak, juruwang, hamper, papan.', NULL, NULL),
(260, 615, NULL, 'hint', 'Kuih kini: mudah dibeli, penyediaan lebih cepat dengan peralatan moden.', 'Kini peralatan moden memudahkan dan mempercepat penyediaan kuih serta kuih raya mudah dibeli, tetapi semangat berkongsi kuih masih kekal.', 'Berjaya! Empat bukti ditemui.'),
(261, NULL, 'e6_n2_s8', 'hint', 'Huminodun: berkorban.', NULL, NULL),
(262, 616, NULL, 'hint', 'Dahulu: semangat Huminodun. Kini: soal jawab sejarah dan kehidupan masyarakat lampau.', 'Unduk Ngadau dahulu: pemenang dipilih berdasarkan semangat Huminodun (kesanggupan berkorban untuk menyelamatkan generasinya). Kini: sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', 'Cemerlang! Empat bukti ditemui.'),
(263, NULL, 'e6_n2_s9', 'hint', 'Balik kampung, duit raya, kunjung-mengunjung.', NULL, NULL),
(264, 617, NULL, 'hint', 'Kekal: balik kampung, duit raya, angpau, kunjung-mengunjung.', 'Amalan yang kekal: balik ke kampung menjelang perayaan, pemberian duit raya dan angpau, kunjung-mengunjung. Amalan ini mengeratkan perpaduan.', 'Tepat! Amalan kekal dikenal pasti.'),
(265, NULL, 'e6_n3_s1', 'hint', 'Enam perayaan, bukan dua belas.', NULL, NULL),
(266, 618, NULL, 'hint', 'Rumah Terbuka Malaysia: enam perayaan utama.', 'Rumah Terbuka Malaysia ialah enam perayaan utama: Hari Raya Aidilfitri, Tahun Baharu Cina, Deepavali, Hari Gawai, Pesta Kaamatan dan Krismas.', 'Tepat! Enam perayaan Rumah Terbuka dikenal pasti.'),
(267, NULL, 'e6_n3_s2', 'hint', 'Eratkan hubungan, jaga tradisi.', NULL, NULL),
(268, 619, NULL, 'hint', 'Berkumpul keluarga: eratkan hubungan, kukuhkan perpaduan, jaga tradisi, kesejahteraan negara.', 'Meraikan perayaan bersama keluarga mengeratkan hubungan dan perpaduan keluarga, mengelakkan tradisi hilang ditelan zaman dan mengekalkan kesejahteraan negara.', 'Syabas! Kepentingan berkumpul difahami.'),
(269, NULL, 'e6_n3_s3', 'hint', 'Keamanan dan bertolak-ansur.', NULL, NULL),
(270, 620, NULL, 'hint', 'Hormat sambutan: keamanan, harmoni, bertolak-ansur, faham budaya kaum lain.', 'Menghormati kepelbagaian sambutan dan adab perayaan mengekalkan keamanan dan keharmonian negara, memupuk bertolak-ansur dan melahirkan masyarakat yang memahami budaya kaum lain.', 'Tepat! Kepentingan hormat difahami.'),
(271, NULL, 'e6_n3_s4', 'hint', 'Gawai kini terbuka untuk semua kaum.', NULL, NULL),
(272, 621, NULL, 'hint', 'Gawai dahulu petani Dayak, kini semua kaum. Unduk Ngadau dahulu Huminodun, kini soal jawab.', 'Gawai dahulu diraikan petani Dayak dengan upacara ritual; kini oleh pelbagai kaum tanpa mengira pekerjaan. Unduk Ngadau dahulu: semangat Huminodun; kini: soal jawab sejarah.', 'Hebat! Perubahan Gawai dan Unduk Ngadau dipadankan.'),
(273, NULL, 'e6_n3_s5', 'hint', 'Tradisi sama, cara berubah.', NULL, NULL),
(274, 622, NULL, 'hint', 'Kolam: tepung → beras atau hampas kelapa. Makan besar: rumah → restoran. Kuih: tradisional → moden.', 'Perubahan: kolam dahulu daripada tepung, kini beras atau hampas kelapa berwarna-warni; makan besar dahulu di rumah, kini ada di restoran atau hotel; kuih dahulu tradisional dan gotong-royong, kini peralatan moden.', 'Cemerlang! Perubahan tradisi dipadankan.'),
(275, NULL, 'e6_n3_s6', 'hint', 'S, W, O, T.', NULL, NULL),
(276, 623, NULL, 'hint', 'SWOT: kekuatan, kelemahan, peluang, halangan dan cabaran.', 'SWOT warisan perayaan: kekuatan, kelemahan, peluang, halangan dan cabaran untuk mengekalkan warisan perayaan.', 'Tepat! Istilah SWOT dipadankan.'),
(277, NULL, 'e6_n3_s7', 'hint', 'Balik kampung, duit raya, kunjung-mengunjung.', NULL, NULL),
(278, 624, NULL, 'hint', 'Kekal: balik kampung, duit raya, angpau, kunjung-mengunjung. Rumah terbuka untuk semua.', 'Amalan kekal: balik ke kampung, duit raya dan angpau, kunjung-mengunjung. Rumah terbuka boleh dikunjungi semua pada hari perayaan.', 'Cemerlang! Amalan perayaan dirumuskan.'),
(279, NULL, 'e7_n1_s1', 'hint', 'Dilantik oleh Agong dan disokong majoriti Dewan Rakyat.', NULL, NULL),
(280, 701, NULL, 'hint', 'Perdana Menteri: ketua kerajaan, dilantik Agong, perlu sokongan majoriti Dewan Rakyat.', 'Perdana Menteri ialah ketua kerajaan yang mengetuai pentadbiran negara. Beliau dilantik oleh Yang di-Pertuan Agong dan perlu mendapat sokongan majoriti Ahli Dewan Rakyat. Jawatan ini wujud selepas 31 Ogos 1957.', 'Tepat! Jawatan Perdana Menteri dijelaskan.'),
(281, NULL, 'e7_n1_s2', 'hint', 'Tunku dahulu, Mahathir kemudian.', NULL, NULL),
(282, 702, NULL, 'hint', 'Tunku, Razak, Hussein, Mahathir.', 'Urutan: Tunku (1957), Tun Abdul Razak (1970), Tun Hussein Onn (1976), Tun Dr. Mahathir (1981).', 'Cemerlang! Urutan Perdana Menteri disusun.'),
(283, NULL, 'e7_n1_s3', 'hint', 'Tunku, papan, poster, rakyat.', NULL, NULL),
(284, 703, NULL, 'hint', 'Cari Tunku, papan perisytiharan, poster dan rakyat bersorak.', 'Tunku memperjuangkan kemerdekaan secara rundingan dan melaungkan kemerdekaan di Stadium Merdeka pada 31 Ogos 1957. Beliau juga merealisasikan pembentukan Malaysia pada 16 September 1963.', 'Berjaya! Empat bukti ditemui.'),
(285, NULL, 'e7_n1_s4', 'hint', 'Bapa Kemerdekaan.', NULL, NULL),
(286, 704, NULL, 'hint', 'Lahir Alor Setar, Cambridge, Ketua Menteri 1955, Bapa Kemerdekaan.', 'Tunku dilahirkan pada 8 Februari 1903 di Alor Setar, belajar di Penang Free School dan Universiti Cambridge, menjadi Ketua Menteri pada 1955, Perdana Menteri 31 Ogos 1957 hingga 22 September 1970 dan digelar Bapa Kemerdekaan.', 'Tepat! Biodata Tunku dipadankan.'),
(287, NULL, 'e7_n1_s5', 'hint', 'MAGERAN dan DEB.', NULL, NULL),
(288, 705, NULL, 'hint', 'MAGERAN dan DEB.', 'Tun Razak mengembalikan keamanan melalui MAGERAN dan memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan serta menyusun semula masyarakat berbilang kaum. Beliau digelar Bapa Pembangunan.', 'Tepat! Pencapaian Tun Razak dikenal pasti.'),
(289, NULL, 'e7_n1_s6', 'hint', 'Pekan, Kuala Kangsar, Lincoln\'s Inn.', NULL, NULL),
(290, 706, NULL, 'hint', 'Pulau Keladi, Kuala Kangsar, Lincoln\'s Inn, MB Pahang, Bapa Pembangunan.', 'Tun Razak dilahirkan pada 11 Mac 1922 di Pulau Keladi, Pekan, belajar di Kolej Melayu Kuala Kangsar, Raffles College dan Lincoln\'s Inn, pernah menjadi Menteri Besar Pahang, Perdana Menteri 22 September 1970 hingga 14 Januari 1976 dan digelar Bapa Pembangunan.', 'Cemerlang! Biodata Tun Razak dipadankan.'),
(291, NULL, 'e7_n1_s7', 'hint', 'ASN dan Rukun Tetangga.', NULL, NULL),
(292, 707, NULL, 'hint', 'ASN, Rukun Tetangga, Bapa Perpaduan.', 'Tun Hussein Onn memperkenalkan Amanah Saham Nasional Berhad dan Program Rukun Tetangga, menjadi Perdana Menteri dari 15 Januari 1976 hingga 16 Julai 1981 dan digelar Bapa Perpaduan.', 'Tepat! Pencapaian Tun Hussein dipadankan.'),
(293, NULL, 'e7_n1_s8', 'hint', 'Lima gelaran, lima pemimpin.', NULL, NULL),
(294, 708, NULL, 'hint', 'Kemerdekaan: Tunku. Pembangunan: Razak. Perpaduan: Hussein. Pemodenan: Mahathir. Modal Insan: Abdullah.', 'Gelaran: Tunku (Bapa Kemerdekaan), Tun Razak (Bapa Pembangunan), Tun Hussein (Bapa Perpaduan), Tun Dr. Mahathir (Bapa Pemodenan) dan Tun Abdullah (Bapa Pembangunan Modal Insan).', 'Hebat! Gelaran lima pemimpin dipadankan.'),
(295, NULL, 'e7_n2_s1', 'hint', 'Pentadbir, pembangunan, diplomatik, duta.', NULL, NULL),
(296, 709, NULL, 'hint', 'Ketua pentadbir, dasar pembangunan, hubungan diplomatik, mencadangkan duta.', 'Antara tugas Perdana Menteri: menjadi ketua pentadbir utama, memastikan dasar pembangunan dilaksanakan, menjalin hubungan diplomatik dengan negara luar dan mencadangkan pelantikan duta, diplomat dan konsulat.', 'Tepat! Gambar dan tugas dipadankan.'),
(297, NULL, 'e7_n2_s2', 'hint', 'Perdana Menteri mencadangkan, Agong melantik.', NULL, NULL),
(298, 710, NULL, 'hint', 'Menasihati Agong, mengiringi, mencadangkan Jemaah Menteri, mempengerusikan mesyuarat.', 'Perdana Menteri menasihati Agong, mengiringi Agong ke Mesyuarat Majlis Raja-Raja, mencadangkan senarai Jemaah Menteri untuk dilantik Agong dan mempengerusikan mesyuarat Jemaah Menteri.', 'Hebat! Tugas berkaitan Agong dan Jemaah Menteri difahami.'),
(299, NULL, 'e7_n2_s3', 'hint', 'Doktor, Alor Setar, Bapa Pemodenan.', NULL, NULL),
(300, 711, NULL, 'hint', 'Alor Setar, perubatan, Klinik MAHA, 1981-2003, Bapa Pemodenan.', 'Tun Dr. Mahathir dilahirkan pada 10 Julai 1925 di Seberang Perak, Alor Setar, belajar perubatan di Singapura, membuka Klinik MAHA pada 1957, menjadi Perdana Menteri dari 16 Julai 1981 hingga 30 Oktober 2003 dan digelar Bapa Pemodenan.', 'Tepat! Biodata Tun Dr. Mahathir dipadankan.'),
(301, NULL, 'e7_n2_s4', 'hint', 'Menara, kilang, carta, jalan.', NULL, NULL),
(302, 712, NULL, 'hint', 'Menara Berkembar, HICOM, carta Wawasan 2020, jalan raya.', 'Di bawah Tun Dr. Mahathir, Wawasan 2020 direalisasikan melalui Pusat Pentadbiran Putrajaya, KLIA dan Menara Berkembar Petronas di KLCC. Beliau juga memperkenalkan perindustrian berteknologi tinggi melalui HICOM.', 'Berjaya! Empat bukti ditemui.'),
(303, NULL, 'e7_n2_s5', 'hint', 'Kali kedua, wawasan baharu.', NULL, NULL),
(304, 713, NULL, 'hint', 'Kali kedua: 2018-2020, Wawasan Kemakmuran Bersama 2030.', 'Tun Dr. Mahathir menjadi Perdana Menteri kali kedua pada 10 Mei 2018 hingga 24 Februari 2020, memperkenalkan Wawasan Kemakmuran Bersama 2030 dan meneruskan kerjasama dengan negara luar, termasuk lawatan ke Jepun, Thailand dan United Kingdom.', 'Tepat! Wawasan Kemakmuran Bersama 2030 dikenal pasti.'),
(305, NULL, 'e7_n2_s6', 'hint', 'Pengajian Islam dan Bapa Modal Insan.', NULL, NULL),
(306, 714, NULL, 'hint', 'Bayan Lepas, Pengajian Islam, MAGERAN, 2003-2009, Modal Insan.', 'Tun Abdullah dilahirkan pada 26 November 1939 di Kampung Perlis, Bayan Lepas, belajar Pengajian Islam di Universiti Malaya, pernah menjadi Setiausaha MAGERAN, Perdana Menteri dari 31 Oktober 2003 hingga 3 April 2009 dan digelar Bapa Pembangunan Modal Insan.', 'Tepat! Biodata Tun Abdullah dipadankan.'),
(307, NULL, 'e7_n2_s7', 'hint', 'PIN: moral dan etika.', NULL, NULL),
(308, 715, NULL, 'hint', 'PIN: masyarakat bermoral dan beretika. Koridor: pembangunan ekonomi seimbang.', 'Tun Abdullah memperkenalkan Koridor Wilayah Ekonomi (contoh Iskandar Malaysia di Johor) untuk pembangunan ekonomi seimbang dan pelaburan, serta Pelan Integriti Nasional (PIN) untuk membina masyarakat yang bermoral dan beretika.', 'Tepat! Fungsi PIN dikenal pasti.'),
(309, NULL, 'e7_n2_s8', 'hint', '1Malaysia: hubungan antara kaum.', NULL, NULL),
(310, 716, NULL, 'hint', 'Kuala Lipis, Nottingham, 2009-2018, 1Malaysia, GTP.', 'Dato\' Sri Najib dilahirkan pada 23 Julai 1953 di Kuala Lipis, belajar di Universiti Nottingham, menjadi Perdana Menteri dari 3 April 2009 hingga 9 Mei 2018, memperkenalkan Gagasan 1Malaysia dan melancarkan Program Transformasi Kerajaan (GTP).', 'Tepat! Biodata dan pencapaian dipadankan.'),
(311, NULL, 'e7_n2_s9', 'hint', 'MTE dan Keluarga Malaysia.', NULL, NULL),
(312, 717, NULL, 'hint', 'Muhyiddin: MTE dan bantuan PKP. Ismail Sabri: Keluarga Malaysia.', 'Muhyiddin (1 Mac 2020-16 Ogos 2021) menubuhkan Majlis Tindakan Ekonomi dan mengumumkan peruntukan bantuan semasa PKP. Ismail Sabri (mulai 20 Ogos 2021) memperkenalkan konsep Keluarga Malaysia yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 'Cemerlang! Sumbangan dua pemimpin dipadankan.'),
(313, NULL, 'e7_n3_s1', 'hint', 'Bendahara dahulu, PM kini.', NULL, NULL),
(314, 718, NULL, 'hint', 'Dahulu Bendahara, kini Perdana Menteri sejak 1957.', 'Pada zaman Kesultanan Melayu Melaka, Bendahara ialah Ketua Pembesar kerajaan. Kini pentadbiran diketuai Perdana Menteri, jawatan yang diwujudkan selepas 31 Ogos 1957 dan kekal hingga hari ini.', 'Tepat! Perbandingan jawatan difahami.'),
(315, NULL, 'e7_n3_s2', 'hint', 'Abdullah, Najib, Mahathir, Muhyiddin, Ismail Sabri.', NULL, NULL),
(316, 719, NULL, 'hint', 'Abdullah, Najib, Mahathir, Muhyiddin, Ismail Sabri.', 'Urutan terkini: Tun Abdullah (2003), Dato\' Sri Najib (2009), Tun Dr. Mahathir kali kedua (2018), Muhyiddin (2020) dan Dato\' Seri Ismail Sabri (2021).', 'Cemerlang! Lima Perdana Menteri disusun.'),
(317, NULL, 'e7_n3_s3', 'hint', 'Kemerdekaan dan Malaysia.', NULL, NULL),
(318, 720, NULL, 'hint', 'Tunku: rundingan kemerdekaan dan Malaysia 1963.', 'Tunku memperjuangkan kemerdekaan secara rundingan dan merealisasikan pembentukan Malaysia pada 16 September 1963.', 'Tepat! Pencapaian Tunku dikenal pasti.'),
(319, NULL, 'e7_n3_s4', 'hint', 'Enam pemimpin, enam pencapaian.', NULL, NULL),
(320, 721, NULL, 'hint', 'Tunku: merdeka. Razak: DEB. Hussein: ASN. Mahathir: Wawasan 2020. Abdullah: PIN. Najib: GTP.', 'Pencapaian: Tunku (kemerdekaan secara rundingan), Tun Razak (DEB), Tun Hussein (ASN), Tun Dr. Mahathir (Wawasan 2020), Tun Abdullah (PIN) dan Najib (GTP).', 'Hebat! Enam pencapaian dipadankan.'),
(321, NULL, 'e7_n3_s5', 'hint', 'Ekonomi, keselamatan, kerajaan tersusun.', NULL, NULL),
(322, 722, NULL, 'hint', 'Berwibawa: ekonomi, keselamatan, kerajaan tersusun, hormat, negara membangun.', 'Pemimpin berwibawa memajukan sistem ekonomi, menjamin keselamatan, membentuk kerajaan tersusun, menimbulkan rasa hormat antara pemimpin, mewujudkan negara membangun dan memudahkan pelaksanaan dasar-dasar pembangunan.', 'Tepat! Kepentingan pemimpin berwibawa difahami.'),
(323, NULL, 'e7_n3_s6', 'hint', 'Perpaduan, taat setia, nama baik, keamanan.', NULL, NULL),
(324, 723, NULL, 'hint', 'Hargai: perpaduan, taat setia, nama baik negara, keamanan.', 'Cara menghargai Perdana Menteri: mengeratkan perpaduan antara kaum, mengekalkan taat setia terhadap pemimpin, menjaga nama baik negara dan menjaga keamanan negara.', 'Tepat! Cara menghargai pemimpin dikenal pasti.'),
(325, NULL, 'e7_n3_s7', 'hint', 'Diri, masyarakat, negara.', NULL, NULL),
(326, 724, NULL, 'hint', 'Diri hormat, masyarakat bertanggungjawab, negara berdaulat.', 'Sokongan kepada kepimpinan negara bermula daripada diri yang menghormati pemimpin, melahirkan masyarakat yang bertanggungjawab dan memastikan kedaulatan negara serta perpaduan rakyat terpelihara.', 'Hebat! Tiga peringkat dipadankan.'),
(327, NULL, 'e7_n3_s8', 'hint', 'Bertanggungjawab dan hormat-menghormati.', NULL, NULL),
(328, 725, NULL, 'hint', 'Bertanggungjawab dan hormat-menghormati.', 'Nilai teras sivik unit ini ialah bertanggungjawab dan hormat-menghormati, supaya jasa pemimpin dihargai dan kedaulatan negara terpelihara.', 'Tepat! Nilai teras sivik dirumuskan.'),
(329, NULL, 'e8_n1_s1', 'hint', 'Cangkul, rumah kayu, petak kecil.', NULL, NULL),
(330, 801, NULL, 'hint', 'Cangkul, rumah kayu, sawah kecil.', 'Ekonomi tradisional diusahakan secara kecil-kecilan, menggunakan peralatan mudah seperti cangkul dan sabit, memerlukan modal kecil dan tenaga kerja sedikit serta bertujuan untuk keperluan sendiri dan keluarga.', 'Berjaya! Empat bukti ekonomi tradisional ditemui.'),
(331, NULL, 'e8_n1_s2', 'hint', 'Tradisional: keluarga. Komersial: eksport.', NULL, NULL),
(332, 802, NULL, 'hint', 'Tradisional: kecil, alat mudah. Komersial: ladang, mesin, eksport.', 'Ekonomi tradisional: kecil-kecilan, alat mudah, modal kecil, keperluan sendiri. Ekonomi komersial: perladangan, mesin dan jentera, modal besar dan tenaga buruh banyak, untuk kegunaan tempatan dan eksport.', 'Tepat! Dua jenis ekonomi dibezakan.'),
(333, NULL, 'e8_n1_s3', 'hint', 'Dulang dan kapal korek.', NULL, NULL),
(334, 803, NULL, 'hint', 'Perlombongan tradisional: mendulang. Komersial: kapal korek.', 'Perlombongan tradisional menggunakan kaedah mendulang, manakala perlombongan komersial menggunakan jentera seperti kapal korek. Ekonomi komersial menggalakkan pembukaan bandar di kawasan perlombongan.', 'Tepat! Kaedah perlombongan dibezakan.'),
(335, NULL, 'e8_n1_s4', 'hint', 'Awal abad ke-20.', NULL, NULL),
(336, 804, NULL, 'hint', 'Getah dan sawit: sejak awal abad ke-20.', 'Industri getah dan kelapa sawit bermula sejak awal abad ke-20 dan menjadi sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.', 'Tepat! Tempoh getah dan sawit dikenal pasti.'),
(337, NULL, 'e8_n1_s5', 'hint', 'Lima manfaat: pendapatan hingga biodiesel.', NULL, NULL),
(338, 805, NULL, 'hint', 'Pendapatan, pekerjaan, hiliran, asas tani, biodiesel.', 'Industri getah dan kelapa sawit meningkatkan pendapatan negara, menyediakan peluang pekerjaan, mewujudkan industri hiliran, memajukan industri asas tani dan membangunkan industri biodiesel.', 'Hebat! Lima manfaat dipadankan.'),
(339, NULL, 'e8_n1_s6', 'hint', 'Perabot kayu getah ialah contoh hiliran.', NULL, NULL),
(340, 806, NULL, 'hint', 'Hiliran: berkembang daripada kegiatan utama. Contoh: perabot kayu getah.', 'Industri hiliran ialah kegiatan yang berkembang daripada kegiatan ekonomi utama, contohnya pembuatan perabot daripada kayu getah. Biodiesel ialah bahan buangan organik yang digunakan sebagai bahan api.', 'Tepat! Maksud industri hiliran dikenal pasti.'),
(341, NULL, 'e8_n1_s7', 'hint', 'Getah: sarung tangan. Sawit: minyak.', NULL, NULL),
(342, 807, NULL, 'hint', 'Getah: sarung tangan, benang lateks. Sawit: minyak mentah, minyak diproses, sabun.', 'Hasil getah yang dieksport ialah sarung tangan dan benang lateks. Hasil kelapa sawit ialah minyak mentah, minyak yang telah diproses dan produk seperti sabun.', 'Tepat! Hasil eksport dipadankan.'),
(343, NULL, 'e8_n1_s8', 'hint', 'Ekonomi berkembang secara berperingkat.', NULL, NULL),
(344, 808, NULL, 'hint', 'Tradisional, getah dan sawit, petroleum 1910, PETRONAS 1974, PROTON 1983.', 'Perkembangan ekonomi: pertanian dan perlombongan tradisional, getah dan sawit sejak awal abad ke-20, petroleum di Miri 1910, PETRONAS 1974 dan PROTON 1983. Pendapatan negara tidak lagi bergantung pada pertanian sahaja.', 'Cemerlang! Peringkat perkembangan ekonomi disusun.'),
(345, NULL, 'e8_n2_s1', 'hint', '1910 Miri, 1974 PETRONAS.', NULL, NULL),
(346, 809, NULL, 'hint', 'Petroleum: 1910 di Miri. PETRONAS: 1974.', 'Industri petroleum bermula pada tahun 1910 di Miri, Sarawak. PETRONAS ditubuhkan pada tahun 1974 dan dimiliki sepenuhnya oleh kerajaan. The Grand Old Lady di Miri ialah telaga minyak pertama negara.', 'Tepat! Sejarah petroleum dikenal pasti.'),
(347, NULL, 'e8_n2_s2', 'hint', 'Pekerjaan, usahawan, sukan, biasiswa.', NULL, NULL),
(348, 810, NULL, 'hint', 'Pekerjaan, usahawan, penaja sukan, biasiswa, pendapatan tinggi.', 'Industri petroleum menyediakan peluang pekerjaan, melahirkan usahawan melalui stesen minyak, menjadi penaja sukan permotoran, menyediakan biasiswa dan memberikan pulangan pendapatan yang tinggi kepada negara.', 'Hebat! Sumbangan petroleum dipadankan.'),
(349, NULL, 'e8_n2_s3', 'hint', 'Penajaan sukan meningkatkan pendapatan negara.', NULL, NULL),
(350, 811, NULL, 'hint', 'Penajaan sukan permotoran: pendapatan negara meningkat.', 'PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia, dan penganjuran sukan ini meningkatkan pendapatan negara.', 'Tepat! Sebab penajaan sukan dikenal pasti.'),
(351, NULL, 'e8_n2_s4', 'hint', 'Mulakan dengan PROTON 1983.', NULL, NULL),
(352, 812, NULL, 'hint', 'PROTON 1983, Saga 1985, PERODUA 1993, Kancil 1994, Tanjung Malim 2005, Geely 2018.', 'Industri automotif: PROTON 1983 (Shah Alam), Proton Saga Julai 1985, PERODUA 1993, Kancil 1994, kilang kedua PROTON di Tanjung Malim 2005 dan usaha sama dengan Geely 2018.', 'Cemerlang! Garis masa automotif disusun.'),
(353, NULL, 'e8_n2_s5', 'hint', 'Saga: PROTON. Kancil: PERODUA.', NULL, NULL),
(354, 813, NULL, 'hint', 'PROTON: Saga. PERODUA: Kancil dan Nippa.', 'PROTON ditubuhkan di Shah Alam pada 1983 dan mengeluarkan Proton Saga pada Julai 1985; kilang kedua di Tanjung Malim pada 2005. PERODUA ditubuhkan pada 1993 dan mengeluarkan Kancil pada 1994; Nippa dieksport ke United Kingdom.', 'Tepat! PROTON dan PERODUA dipadankan.'),
(355, NULL, 'e8_n2_s6', 'hint', 'Air terjun, jambatan, gua, pantai.', NULL, NULL),
(356, 814, NULL, 'hint', 'Air terjun, jambatan gantung, gua, pantai.', 'Keindahan alam semula jadi seperti hutan, pulau, laut dan gua menarik pelancong. Kempen Tahun Melawat Malaysia dianjurkan sejak 1990 bagi menarik kedatangan pelancong.', 'Berjaya! Empat bukti ditemui.'),
(357, NULL, 'e8_n2_s7', 'hint', 'Lima keistimewaan pelancongan.', NULL, NULL),
(358, 815, NULL, 'hint', 'Sejarah, alam, budaya, agropelancongan, sukan dan pameran.', 'Keistimewaan pelancongan Malaysia: tapak bersejarah, alam semula jadi, keharmonian dan keunikan budaya, agropelancongan (inap desa) serta penganjuran sukan, muzik dan pameran antarabangsa.', 'Hebat! Keistimewaan pelancongan dipadankan.'),
(359, NULL, 'e8_n2_s8', 'hint', 'Sepang, Langkawi, Sarawak.', NULL, NULL),
(360, 816, NULL, 'hint', 'Formula One: Sepang. Muzik Hutan Hujan: Sarawak. LIMA: Langkawi setiap dua tahun.', 'Formula One di Sepang, Le Tour de Langkawi, Festival Muzik Hutan Hujan Sedunia di Sarawak dan LIMA di Pulau Langkawi setiap dua tahun menarik pelancong dan mempromosikan Malaysia.', 'Tepat! Acara antarabangsa dipadankan.'),
(361, NULL, 'e8_n3_s1', 'hint', '1985.', NULL, NULL),
(362, 817, NULL, 'hint', 'Kempen Beli Barangan Buatan Malaysia: 1985.', 'Kempen \'Beli Barangan Buatan Malaysia\' dilancarkan pada tahun 1985. Antara barangan buatan Malaysia termasuklah perabot, barangan elektrik dan elektronik serta produk makanan.', 'Tepat! Tahun kempen dikenal pasti.'),
(363, NULL, 'e8_n3_s2', 'hint', 'Tiga kategori: pertanian, petroleum, automotif.', NULL, NULL),
(364, 818, NULL, 'hint', 'Pertanian: minyak masak, sabun, nanas, durian. Petroleum: petrol, pelincir, gas. Automotif: kereta, motosikal.', 'Produk pertanian: minyak masak, sabun, nanas, durian. Produk petroleum: minyak petrol, pelincir, gas memasak. Produk automotif: kereta dan motosikal.', 'Tepat! Produk dipadankan dengan kategori.'),
(365, NULL, 'e8_n3_s3', 'hint', 'Menara, jambatan, gudang, carta.', NULL, NULL),
(366, 819, NULL, 'hint', 'Menara, jambatan dan jalan, gudang e-dagang, carta menaik.', 'Pencapaian pesat ekonomi dapat dilihat menerusi pembangunan infrastruktur (bangunan pencakar langit), jaringan perhubungan moden yang terancang dan kegiatan e-dagang yang semakin berkembang.', 'Berjaya! Empat bukti ditemui.'),
(367, NULL, 'e8_n3_s4', 'hint', 'E-dagang: perniagaan melalui Internet.', NULL, NULL),
(368, 820, NULL, 'hint', 'Pembangunan: pencakar langit. Perhubungan: jaringan moden. Perdagangan: e-dagang.', 'Pembangunan (bangunan pencakar langit), perhubungan (jaringan moden terancang) dan perdagangan (e-dagang, iaitu urusan perniagaan melalui rangkaian Internet) menunjukkan pencapaian pesat ekonomi negara.', 'Tepat! Tiga pencapaian dipadankan.'),
(369, NULL, 'e8_n3_s5', 'hint', 'Ekonomi, pasaran, identiti.', NULL, NULL),
(370, 821, NULL, 'hint', 'Bangga barangan tempatan: ekonomi, pasaran, identiti, produktiviti.', 'Rasa bangga terhadap barangan buatan Malaysia memajukan sistem ekonomi, memperluaskan pasaran produk tempatan, memperkenalkan identiti negara dan membantu usahawan meningkatkan produktiviti.', 'Tepat! Kepentingan rasa bangga difahami.'),
(371, NULL, 'e8_n3_s6', 'hint', 'Taraf hidup dan daya saing.', NULL, NULL),
(372, 822, NULL, 'hint', 'Kemajuan ekonomi: taraf hidup, infrastruktur, kestabilan, daya saing.', 'Kemajuan ekonomi meningkatkan taraf hidup, membolehkan pelaburan dalam infrastruktur, menyumbang kepada kestabilan sosial dan politik serta meningkatkan daya saing negara.', 'Tepat! Kepentingan kemajuan ekonomi difahami.'),
(373, NULL, 'e8_n3_s7', 'hint', 'Diri, masyarakat, negara.', NULL, NULL),
(374, 823, NULL, 'hint', 'Diri menyokong, masyarakat menambah pendapatan, negara berkongsi kemajuan.', 'Setiap warganegara perlu menyokong usaha meningkatkan ekonomi negara; sokongan masyarakat meningkatkan pendapatan negara; peningkatan pendapatan dan kemajuan ekonomi dikongsi bersama.', 'Hebat! Tiga peringkat dipadankan.'),
(375, NULL, 'e8_n3_s8', 'hint', 'Empat industri pemacu kemajuan.', NULL, NULL),
(376, 824, NULL, 'hint', 'Getah/sawit: abad ke-20. Petroleum: 1910 dan 1974. Automotif: 1983. Pelancongan: 1990.', 'Industri pemacu: getah dan kelapa sawit (awal abad ke-20), petroleum dan gas (1910, PETRONAS 1974), automotif (PROTON 1983, PERODUA 1993) dan pelancongan (Tahun Melawat Malaysia sejak 1990).', 'Cemerlang! Rumusan industri dilengkapkan.'),
(377, NULL, 'e9_n1_s1', 'hint', 'BAM: 1960.', NULL, NULL),
(378, 901, NULL, 'hint', 'BAM: 1960. Atlet: Punch Gunalan, Misbun Sidek, Lee Chong Wei.', 'Persatuan Badminton Malaysia (BAM) ditubuhkan pada tahun 1960, menganjurkan Kejohanan Badminton Kebangsaan dan melahirkan atlet seperti Punch Gunalan, Misbun Sidek dan Lee Chong Wei.', 'Tepat! BAM dan pencapaiannya dipadankan.'),
(379, NULL, 'e9_n1_s2', 'hint', 'Piala Thomas lima kali.', NULL, NULL),
(380, 902, NULL, 'hint', 'Piala Thomas lima kali, Olimpik perak dan gangsa, All England.', 'Pencapaian badminton negara: juara Piala Thomas lima kali, pingat perak dan gangsa Sukan Olimpik serta juara Kejohanan Badminton Terbuka All England bagi acara beregu dan individu lelaki.', 'Tepat! Pencapaian badminton dikenal pasti.'),
(381, NULL, 'e9_n1_s3', 'hint', 'FAM: 1963.', NULL, NULL),
(382, 903, NULL, 'hint', 'FAM: 1963. Olimpik Munich 1972 dan Moscow 1980. Suzuki AFF 2010.', 'FAM ditubuhkan pada 1963 dan menganjurkan Liga Malaysia. Pasukan negara layak ke Sukan Olimpik Munich 1972 dan Moscow 1980 serta menjuarai Piala Suzuki AFF 2010.', 'Tepat! FAM dan pencapaiannya dipadankan.'),
(383, NULL, 'e9_n1_s4', 'hint', 'PUSKAS FIFA 2016.', NULL, NULL),
(384, 904, NULL, 'hint', 'Mohd Faiz Subri: PUSKAS FIFA 2016.', 'Mohd Faiz Subri, ketika menjadi pemain pasukan Pulau Pinang, memenangi anugerah antarabangsa PUSKAS FIFA 2016.', 'Tepat! Anugerah PUSKAS FIFA dikenal pasti.'),
(385, NULL, 'e9_n1_s5', 'hint', 'Pelari, blok, jam randik, pelari kedua.', NULL, NULL),
(386, 905, NULL, 'hint', 'Pelari, blok permulaan, pegawai berjam randik, pelari kedua.', 'Atlet negara memenangi pingat emas 100 meter Sukan Asia pada tahun 1966 dan 1982. Olahraga dikembangkan oleh Kesatuan Olahraga Amatur Malaysia (KOAM) pada 1952 yang kini dikenali sebagai Kesatuan Olahraga Malaysia (KOM).', 'Berjaya! Empat bukti ditemui.'),
(387, NULL, 'e9_n1_s6', 'hint', 'KOAM: 1952, KOM kini.', NULL, NULL),
(388, 906, NULL, 'hint', 'KOAM 1952, kini KOM. Juara Sukan SEA 2017: lapan emas.', 'KOAM ditubuhkan pada tahun 1952 dan kini dikenali sebagai KOM. KOM menganjurkan Kejohanan Olahraga Kebangsaan dan atlet olahraga membantu negara muncul juara Sukan SEA 2017 dengan menyumbang lapan pingat emas.', 'Tepat! Maklumat KOAM dan KOM dikenal pasti.'),
(389, NULL, 'e9_n1_s7', 'hint', 'MHC: 1953.', NULL, NULL),
(390, 907, NULL, 'hint', 'MHC: 1953. Piala Dunia lapan kali, ke-4 pada 1975, naib juara Komanwel 1998.', 'MHC ditubuhkan pada tahun 1953 dan menganjurkan Liga Hoki Kebangsaan. Pasukan hoki negara layak lapan kali ke Piala Dunia, menduduki tempat keempat pada 1975 dan menjadi naib juara Sukan Komanwel 1998.', 'Hebat! Hoki negara dipadankan.'),
(391, NULL, 'e9_n1_s8', 'hint', 'Legenda sukan terdahulu.', NULL, NULL),
(392, 908, NULL, 'hint', 'Jegathesan: pecut. Rajamani: olahraga wanita. Tan Aik Huang: All England. Mokhtar: Supermokh.', 'Dr. M. Jegathesan (Manusia Terpantas Asia), M. Rajamani (olahraga wanita, Olimpik 1964), Tan Aik Huang (juara All England 1966) dan Mokhtar Dahari (Supermokh, 167 penampilan dan 89 gol) ialah legenda sukan negara.', 'Tepat! Empat legenda dipadankan.'),
(393, NULL, 'e9_n2_s1', 'hint', 'Pingat, bendera, trofi, penonton.', NULL, NULL),
(394, 909, NULL, 'hint', 'Pingat emas, bendera, trofi, penonton.', 'Pingat emas, bendera Malaysia, trofi dan sorakan penonton menunjukkan atlet negara mengharumkan nama Malaysia dan rakyat berasa bangga.', 'Berjaya! Empat bukti ditemui.'),
(395, NULL, 'e9_n2_s2', 'hint', 'Badminton, nombor satu dunia.', NULL, NULL),
(396, 910, NULL, 'hint', 'Nombor satu dunia 2006, 2008, 2012, 2013; All England empat kali.', 'Lee Chong Wei ialah pemain badminton nombor satu dunia pada 2006, 2008, 2012 dan 2013, juara Perseorangan Lelaki Terbuka All England empat kali dan penerima Anugerah Pemain Lelaki Terbaik BWF lima kali.', 'Tepat! Pencapaian Lee Chong Wei dikenal pasti.'),
(397, NULL, 'e9_n2_s3', 'hint', 'Skuasy, terjun, basikal trek.', NULL, NULL),
(398, 911, NULL, 'hint', 'Nicol: skuasy. Pandelela: terjun. Azizulhasni: basikal.', 'Nicol Ann David ialah pemain skuasy wanita nombor satu dunia 108 bulan. Pandelela Rinong ialah penyumbang pingat gangsa pertama di Olimpik London 2012 (terjun). Azizulhasni Awang, The Pocket Rocketman, meraih gangsa Rio 2016 dan perak Tokyo 2020.', 'Hebat! Tiga atlet dipadankan.'),
(399, NULL, 'e9_n2_s4', 'hint', '341 penampilan.', NULL, NULL),
(400, 912, NULL, 'hint', 'S. Kuhan: 341 penampilan, ketua pasukan 2000-2006.', 'S. Kuhan ialah penjaring terbanyak Liga Hoki Malaysia (1997, 1999, 2003), ketua pasukan hoki negara 2000 hingga 2006 dan mewakili negara sebanyak 341 kali dalam kejohanan utama.', 'Tepat! Rekod S. Kuhan dikenal pasti.'),
(401, NULL, 'e9_n2_s5', 'hint', '7, 7, 8 emas; enam kali Mr. Asia.', NULL, NULL),
(402, 913, NULL, 'hint', 'Nurul Huda: 7, 7, 8 emas. Abdul Malek: enam kali Mr. Asia.', 'Nurul Huda Abdullah memenangi tujuh emas Sukan SEA 1985, tujuh emas 1987 dan lapan emas 1989. Abdul Malek Mohamed Noor memenangi enam kali gelaran Mr. Asia dan Olahragawan Negara 1986.', 'Tepat! Rekod renang dan bina badan dipadankan.'),
(403, NULL, 'e9_n2_s6', 'hint', 'Ketujuh dunia.', NULL, NULL),
(404, 914, NULL, 'hint', 'Team Secret MY: PMGC 2021, ketujuh dunia.', 'Team Secret MY mewakili Malaysia dalam e-sukan Kejohanan Final Global PUBG Mobile (PMGC) 2021 dan menduduki tempat ketujuh terbaik dunia.', 'Tepat! Pencapaian e-sukan dikenal pasti.'),
(405, NULL, 'e9_n2_s7', 'hint', 'Empat atlet paralimpik dan satu slogan.', NULL, NULL),
(406, 915, NULL, 'hint', 'Bonnie: angkat berat. Ziyad: lontar peluru. Ridzuan: 100 m. Latif: lompat jauh. Slogan: Kami Luar Biasa.', 'Atlet paralimpik: Bonnie Bunyau Gustin (angkat berat, emas Tokyo 2020), Muhammad Ziyad (lontar peluru F20, 16.84 m), Mohamad Ridzuan (100 m T36) dan Abdul Latif (lompat jauh T20, 7.60 m). Slogan mereka ialah Kami Luar Biasa.', 'Cemerlang! Atlet paralimpik dipadankan.'),
(407, NULL, 'e9_n2_s8', 'hint', 'Dikenali, pelancong, ekonomi.', NULL, NULL),
(408, 916, NULL, 'hint', 'Faedah: dikenali dunia, pelancong, ekonomi.', 'Menjadi tuan rumah sukan antarabangsa menjadikan negara dikenali di dunia, menarik pelancong luar negara dan menyumbang kepada pembangunan ekonomi.', 'Tepat! Faedah sukan antarabangsa dikenal pasti.'),
(409, NULL, 'e9_n3_s1', 'hint', 'Enam program, satu matlamat: perpaduan.', NULL, NULL),
(410, 917, NULL, 'hint', 'RIMUP 2005, 1M1S 2011, MSSM tahunan, SUKMA bergilir negeri, SUKIPT IPT, Paralimpik OKU.', 'RIMUP (2005), Dasar 1Murid 1Sukan (2011), Kejohanan MSSM (setiap tahun), SUKMA (bergilir negeri), SUKIPT (IPT) dan Sukan Paralimpik (OKU) memupuk perpaduan kaum melalui sukan.', 'Hebat! Enam program dipadankan.'),
(411, NULL, 'e9_n3_s2', 'hint', 'SUKMA bergilir negeri.', NULL, NULL),
(412, 918, NULL, 'hint', 'SUKMA: sukan terbesar, bergilir negeri, bermula 1986.', 'Temasya Sukan Malaysia (SUKMA) ialah sukan terbesar dalam negara yang dianjurkan secara bergilir-gilir oleh setiap negeri. SUKMA pertama diadakan pada 1986 dan atlet pelbagai kaum mewakili negeri masing-masing.', 'Tepat! SUKMA dikenal pasti.'),
(413, NULL, 'e9_n3_s3', 'hint', 'SEAP dahulu, SEA kemudian.', NULL, NULL),
(414, 919, NULL, 'hint', '1959 SEAP, 1965 tuan rumah, 1977 SEA, 2017 tuan rumah.', 'Sukan SEAP mula dipertandingkan pada 1959, Malaysia menjadi tuan rumah pada 1965, ia dikenali sebagai Sukan SEA pada 1977 dan Malaysia menjadi tuan rumah pada 2017. Malaysia juga menjadi tuan rumah pada 1971, 1977, 1989 dan 2001.', 'Cemerlang! Peristiwa Sukan SEA disusun.'),
(415, NULL, 'e9_n3_s4', 'hint', 'Enam Piala Thomas, dua Hoki Piala Dunia.', NULL, NULL),
(416, 920, NULL, 'hint', 'Piala Thomas: enam kali. Hoki Piala Dunia: 1975 (12 negara), 2002 (16 negara).', 'Piala Thomas dianjurkan enam kali di Malaysia (1970, 1984, 1988, 1992 di Stadium Negara; 2000, 2010 di Stadium Putra). Hoki Piala Dunia dianjurkan pada 1975 (12 negara) dan 2002 (16 negara).', 'Tepat! Penganjuran Piala Thomas dan Hoki Piala Dunia dipadankan.'),
(417, NULL, 'e9_n3_s5', 'hint', 'Enam acara antarabangsa.', NULL, NULL),
(418, 921, NULL, 'hint', 'Permotoran 1991, Le Tour 1996, Komanwel 1998, F1 2000, Piala Monsun 2005, Formula E 2014.', 'Sukan permotoran bermula 1991, Le Tour de Langkawi 1996, Sukan Komanwel 1998 (Asia pertama), Formula One di Sepang 2000, Piala Monsun di Pulau Duyong 2005 dan Formula E di Putrajaya 2014.', 'Hebat! Acara antarabangsa dipadankan.'),
(419, NULL, 'e9_n3_s6', 'hint', 'Orang Utan, bunga raya.', NULL, NULL),
(420, 922, NULL, 'hint', 'Komanwel 1998: Orang Utan dan bunga raya.', 'Malaysia ialah negara Asia pertama menjadi tuan rumah Sukan Komanwel pada 1998. Maskotnya Orang Utan, logonya bunga raya dan stadium utamanya Stadium Nasional Bukit Jalil.', 'Tepat! Maklumat Komanwel dikenal pasti.'),
(421, NULL, 'e9_n3_s7', 'hint', 'Diri, masyarakat, negara.', NULL, NULL),
(422, 923, NULL, 'hint', 'Diri hormat, masyarakat harmoni, negara aman.', 'Diri mengamalkan sikap saling menghormati antara kaum, masyarakat memupuk perpaduan dan keharmonian untuk kesejahteraan, dan negara menikmati keamanan serta kemakmuran bersama.', 'Hebat! Tiga peringkat dipadankan.'),
(423, NULL, 'e9_n3_s8', 'hint', 'Tiga tokoh inspirasi.', NULL, NULL),
(424, 924, NULL, 'hint', 'Azlan Shah: Bapa Hoki. Velappan: AFC. Sieh Kok Chi: Majlis Olimpik Malaysia.', 'Sultan Azlan Shah ialah Bapa Hoki Malaysia dan Presiden Persekutuan Hoki Malaysia 1985-2004; Dato\' Peter Velappan ialah Setiausaha Agung AFC 1978-2007; Dato\' Sieh Kok Chi ialah bekas atlet polo air dan Setiausaha Agung Majlis Olimpik Malaysia 1992-2015.', 'Cemerlang! Tiga pemimpin sukan dipadankan.'),
(425, NULL, 'e10_n1_s1', 'hint', 'Tiga pertubuhan: 1959, 1961, 1967.', NULL, NULL),
(426, 1001, NULL, 'hint', 'SEAFET 1959, ASA 1961, ASEAN 1967.', 'Malaysia menganggotai tiga pertubuhan serantau: SEAFET (1959), ASA (1961) dan ASEAN (1967). SEAFET dan ASA dianggotai Persekutuan Tanah Melayu, Thailand dan Filipina; ASEAN pada awalnya dianggotai lima negara.', 'Tepat! Tiga pertubuhan serantau dipadankan.'),
(427, NULL, 'e10_n1_s2', 'hint', 'Lima negara awal, lima negara menyusul.', NULL, NULL),
(428, 1002, NULL, 'hint', 'SEAFET, ASA, ASEAN, Brunei, Vietnam, Laos dan Myanmar, Kemboja.', 'ASEAN ditubuhkan 8 Ogos 1967 oleh lima negara. Brunei menyertai pada 1984, Vietnam 1995, Laos dan Myanmar 1997 dan Kemboja 1999, menjadikan sepuluh negara anggota.', 'Cemerlang! Pertumbuhan ASEAN disusun.'),
(429, NULL, 'e10_n1_s3', 'hint', 'Bendera, peta, bendera, dokumen.', NULL, NULL),
(430, 1003, NULL, 'hint', 'Bendera Malaysia, peta, bendera Singapura, dokumen.', 'Malaysia menjadi tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN. ASEAN dianggotai 10 negara Asia Tenggara, dengan Singapura antara anggota awal, dan matlamat menjamin keamanan serta kestabilan politik.', 'Berjaya! Empat bukti ditemui.'),
(431, NULL, 'e10_n1_s4', 'hint', 'Jakarta, bukan Kuala Lumpur.', NULL, NULL),
(432, 1004, NULL, 'hint', 'ASEAN: 8 Ogos 1967, 10 negara, ibu pejabat Jakarta.', 'ASEAN ditubuhkan pada 8 Ogos 1967, kini dianggotai 10 negara Asia Tenggara dan ibu pejabatnya terletak di Jakarta, Indonesia.', 'Tepat! Latar belakang ASEAN dikenal pasti.'),
(433, NULL, 'e10_n1_s5', 'hint', 'Keamanan, pertumbuhan, kerjasama, taraf hidup.', NULL, NULL),
(434, 1005, NULL, 'hint', 'Keamanan, pertumbuhan, kerjasama, taraf hidup.', 'Matlamat ASEAN: menjamin keamanan dan kestabilan politik, menggalakkan pertumbuhan ekonomi, kemajuan sosial dan pembangunan kebudayaan, menjalin kerjasama dalam latihan dan penyelidikan serta meningkatkan taraf hidup penduduk.', 'Tepat! Empat matlamat ASEAN dipadankan.'),
(435, NULL, 'e10_n1_s6', 'hint', 'Enam unsur logo ASEAN.', NULL, NULL),
(436, 1006, NULL, 'hint', 'Biru: keamanan. Merah: semangat. Kuning: kemakmuran. Putih: kesucian. Bulatan: kesatuan.', 'Logo ASEAN: biru (keamanan dan kestabilan), merah (semangat dan dinamisme), kuning (kemakmuran), putih (kesucian), sepuluh tangkai padi (impian pengasasan diikat persahabatan dan perpaduan) dan bulatan (kesatuan).', 'Hebat! Makna logo ASEAN dipadankan.'),
(437, NULL, 'e10_n1_s7', 'hint', 'ZOPFAN, urea, Sukan SEA, RECSAM.', NULL, NULL),
(438, 1007, NULL, 'hint', 'ZOPFAN 1971, baja urea Bintulu, Sukan SEA, RECSAM Pulau Pinang.', 'Faedah ASEAN kepada Malaysia: Deklarasi Kuala Lumpur 1971 (ZOPFAN), projek baja urea di Bintulu, penganjuran Sukan SEA dan pembinaan RECSAM di Pulau Pinang.', 'Tepat! Faedah ASEAN dipadankan.'),
(439, NULL, 'e10_n1_s8', 'hint', 'ZOPFAN dan selatan Filipina.', NULL, NULL),
(440, 1008, NULL, 'hint', 'ASEAN: ZOPFAN, selatan Filipina, Vietnam-Kemboja, SEAMEO.', 'Sumbangan Malaysia dalam ASEAN: tuan rumah Mesyuarat Menteri-Menteri Luar, membantu menangani pencerobohan Vietnam terhadap Kemboja, meredakan konflik di selatan Filipina, mengutarakan ZOPFAN dan menyertai SEAMEO.', 'Tepat! Sumbangan Malaysia dalam ASEAN dikenal pasti.'),
(441, NULL, 'e10_n2_s1', 'hint', 'Dewan, bendera, dua peta.', NULL, NULL),
(442, 1009, NULL, 'hint', 'Dewan sidang, bendera, peta dunia, peta utama.', 'Keahlian PBB terbuka kepada semua negara. Malaysia ialah anggota yang aktif menyumbang dan menghantar pasukan pengaman PBB ke pelbagai kawasan konflik.', 'Berjaya! Empat bukti ditemui.'),
(443, NULL, 'e10_n2_s2', 'hint', 'New York dan enam bahasa rasmi.', NULL, NULL),
(444, 1010, NULL, 'hint', 'PBB: 24 Okt 1945, New York, enam bahasa rasmi.', 'PBB ditubuhkan pada 24 Oktober 1945 selepas Perang Dunia Kedua. Keahliannya terbuka kepada semua negara, ibu pejabatnya di New York dan ia menggunakan enam bahasa rasmi.', 'Tepat! Latar belakang PBB dikenal pasti.'),
(445, NULL, 'e10_n2_s3', 'hint', 'Komanwel/PBB 1957, OIC 1969, NAM 1970.', NULL, NULL),
(446, 1011, NULL, 'hint', 'Komanwel dan PBB: 1957. NAM: 1970. OIC: 1969.', 'Malaysia menyertai Komanwel dan PBB pada 1957, NAM sejak 1970 dan OIC sejak penubuhannya pada 1969. NAM dianggotai 120 negara membangun; OIC awalnya 57 negara.', 'Hebat! Pertubuhan antarabangsa dipadankan.'),
(447, NULL, 'e10_n2_s4', 'hint', 'Komanwel: London, 54 negara.', NULL, NULL),
(448, 1012, NULL, 'hint', 'Komanwel: 11 Dis 1931, 54 negara, London.', 'Komanwel dibentuk pada 11 Disember 1931, dianggotai 54 negara bekas tanah jajahan British kecuali Mozambique dan Rwanda, dan Sekretariatnya terletak di London, England.', 'Tepat! Latar belakang Komanwel dikenal pasti.'),
(449, NULL, 'e10_n2_s5', 'hint', 'Pendidikan, perdagangan, kesihatan, belia.', NULL, NULL),
(450, 1013, NULL, 'hint', 'Pendidikan: biasiswa. Perdagangan: pasaran. Kesihatan: COVID-19. Belia dan sukan: 1998.', 'Faedah Komanwel: biasiswa pendidikan tinggi, barangan Malaysia menembusi pasaran antarabangsa, perkongsian data kesihatan menangani wabak seperti COVID-19 serta penganjuran dan penyertaan dalam Sukan Komanwel.', 'Tepat! Faedah Komanwel dipadankan.'),
(451, NULL, 'e10_n2_s6', 'hint', 'Aparteid 1993, Deklarasi Langkawi 1989.', NULL, NULL),
(452, 1014, NULL, 'hint', 'Komanwel: Aparteid 1993, CHOGM 1989, Deklarasi Langkawi 1989.', 'Sumbangan Malaysia dalam Komanwel: mengecam Aparteid dan membantu menamatkannya pada 1993, menjadi tuan rumah CHOGM 1989 dan mengisytiharkan Deklarasi Langkawi 1989 untuk mengawal pencemaran alam sekitar.', 'Tepat! Sumbangan dalam Komanwel dikenal pasti.'),
(453, NULL, 'e10_n2_s7', 'hint', 'Tunku: Setiausaha Agung OIC pertama.', NULL, NULL),
(454, 1015, NULL, 'hint', 'OIC: 25 Sep 1969, Tunku Setiausaha Agung, Jeddah, 57 negara.', 'OIC ditubuhkan pada 25 September 1969; Tunku Abdul Rahman dilantik sebagai Setiausaha Agung pertama. Pejabatnya di Jeddah, Arab Saudi, dianggotai 57 negara dan menggunakan bahasa Arab, Inggeris dan Perancis.', 'Tepat! Latar belakang OIC dikenal pasti.'),
(455, NULL, 'e10_n2_s8', 'hint', 'Bank 1975, Bosnia 1991, UIAM 1983.', NULL, NULL),
(456, 1016, NULL, 'hint', 'Bank Pembangunan Islam 1975, Bosnia 1991, UIAM 1983, tuan rumah 1974 dan 2003, Palestin.', 'Sumbangan Malaysia dalam OIC: membantu penubuhan Bank Pembangunan Islam (1975), menangani isu Bosnia dan Herzegovina (1991), menubuhkan UIAM (1983), menjadi tuan rumah persidangan OIC (1974, 2003) dan menyokong perjuangan rakyat Palestin.', 'Hebat! Sumbangan dalam OIC dipadankan.'),
(457, NULL, 'e10_n3_s1', 'hint', 'Congo dahulu, Lubnan kemudian.', NULL, NULL),
(458, 1017, NULL, 'hint', 'Congo 1961, Majlis Keselamatan 1965, Namibia 1989, Iran-Iraq 1990, Somalia dan Bosnia 1992, Lubnan 2007.', 'Malaysia menghantar pasukan pengaman PBB ke Congo (1961), Namibia (1989), Somalia dan Bosnia (1992) dan Lubnan (2007), pemerhati ke sempadan Iran-Iraq (1990), dan menjadi ahli tidak tetap Majlis Keselamatan (1965, 1989-1990, 1999-2000, 2015-2016).', 'Cemerlang! Misi PBB disusun.'),
(459, NULL, 'e10_n3_s2', 'hint', 'Palestin, dadah, pendidikan, Majlis Keselamatan.', NULL, NULL),
(460, 1018, NULL, 'hint', 'Palestin, dadah Vienna 1987, Pendidikan untuk Semua, Majlis Keselamatan.', 'Sumbangan Malaysia dalam PBB: mencari penyelesaian konflik Palestin-Israel, mendorong persidangan dadah di Vienna 1987 (Tun Dr. Mahathir Presiden), memperjuangkan Pendidikan untuk Semua melalui UNESCO dan menjadi ahli tidak tetap Majlis Keselamatan.', 'Tepat! Sumbangan dalam PBB dipadankan.'),
(461, NULL, 'e10_n3_s3', 'hint', 'Pertahan kepentingan dan sumbang pandangan.', NULL, NULL),
(462, 1019, NULL, 'hint', 'PBB: pertahan kepentingan negara, sumbang pandangan isu global.', 'Faedah menyertai PBB: memelihara dan mempertahankan kepentingan negara dalam keputusan PBB, meneruskan peranan aktif dengan menyumbang pandangan dalam isu global dan meningkatkan komitmen menangani pelbagai isu.', 'Tepat! Faedah PBB dikenal pasti.'),
(463, NULL, 'e10_n3_s4', 'hint', 'Razali: keselamatan. Mazlan: angkasa lepas.', NULL, NULL),
(464, 1020, NULL, 'hint', 'Razali: Majlis Keselamatan 1989-1990, Perhimpunan Agung 1996-1997. Mazlan: Angkasa Lepas.', 'Tan Sri Razali Ismail ialah Pengerusi Majlis Keselamatan PBB (1989-1990) dan Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997). Datuk Dr. Mazlan Othman ialah Pengarah Hal Ehwal Angkasa Lepas PBB (1999-2002 dan 2007). Pasukan Pengaman PBB diiktiraf dengan sijil dan pingat.', 'Hebat! Tokoh Malaysia di PBB dipadankan.'),
(465, NULL, 'e10_n3_s5', 'hint', 'Kinabalu, Mulu, Melaka, Lenggong.', NULL, NULL),
(466, 1021, NULL, 'hint', 'Kinabalu, Mulu, Melaka dan George Town, Lenggong.', 'Tapak Warisan Dunia UNESCO di Malaysia: Taman Negara Gunung Mulu dan Taman Kinabalu (alam semula jadi, 2000), Melaka dan George Town (2008) serta Warisan Arkeologi Lembah Lenggong (2012).', 'Berjaya! Empat bukti ditemui.'),
(467, NULL, 'e10_n3_s6', 'hint', 'Empat kategori UNESCO.', NULL, NULL),
(468, 1022, NULL, 'hint', 'Alam: Mulu, Kinabalu. Kebudayaan: Melaka, George Town, Lenggong. Memori: Hikayat. Tidak Ketara: Makyung.', 'UNESCO mengiktiraf Tapak Warisan Dunia alam (Mulu, Kinabalu) dan kebudayaan (Melaka, George Town, Lenggong), Daftar Memori Dunia (Hikayat Hang Tuah, Sulalatus Salatin, Batu Bersurat Terengganu) dan Warisan Budaya Tidak Ketara (Makyung, Dondang Sayang, Silat, Wangkang).', 'Tepat! Kategori UNESCO dipadankan.'),
(469, NULL, 'e10_n3_s7', 'hint', 'Dari 2000 hingga 2020.', NULL, NULL),
(470, 1023, NULL, 'hint', '2000, 2001, 2005, 2008, 2012, 2018, 2019, 2020.', 'Pengiktirafan UNESCO: Mulu dan Kinabalu (2000), Hikayat Hang Tuah (2001), Makyung (2005), Melaka dan George Town (2008), Lembah Lenggong (2012), Dondang Sayang (2018), Silat (2019) dan Wangkang (2020).', 'Cemerlang! Pengiktirafan UNESCO disusun.'),
(471, NULL, 'e10_n3_s8', 'hint', 'Keselamatan dan kemakmuran.', NULL, NULL),
(472, 1024, NULL, 'hint', 'Hubungan baik: keselamatan dan kemakmuran.', 'Hubungan baik dengan negara luar penting bagi menjamin keselamatan dan kemakmuran rakyat serta negara, dan memastikan kestabilan politik, kemajuan ekonomi serta keharmonian rakyat.', 'Tepat! Kepentingan hubungan baik difahami.'),
(473, NULL, 'e10_n3_s9', 'hint', 'Diri, masyarakat, negara.', NULL, NULL),
(474, 1025, NULL, 'hint', 'Diri jiran, masyarakat perpaduan, negara dihormati.', 'Diri memelihara hubungan baik dengan jiran, masyarakat membentuk perpaduan dan faedah untuk semua, dan kesepakatan menjadikan negara dihormati serta disegani. Pelibatan Malaysia dalam pertubuhan serantau dan antarabangsa bermula sejak merdeka.', 'Hebat! Tiga peringkat dipadankan.'),
(475, NULL, 'e1_n1_s1', 'hint', 'Ghazali menyebut peta Melayu Raya menyentuh Indonesia dan Filipina. Ingat kedua-dua negara itu.', NULL, NULL),
(476, 1, NULL, 'hint', 'Cadangan paling awal datang daripada Lord Brassey pada 1887, diikuti Melayu Raya pada 1938.', 'Tarikh jangkar: 1887 dan 1938.\nSebab: idea gabungan datang daripada pihak British dan tokoh tempatan.\nAkibat: peta Melayu Raya menyentuh Indonesia dan Filipina, dan dua negara itu akan muncul semula.', 'Tepat sekali! Fail-fail itu kini bersusun dan Tunku boleh menjawab wartawan dengan yakin.'),
(477, NULL, 'e1_n1_s2', 'hint', 'Ghazali menyebut Singapura sudah lama memerhatikan. Itu petunjuk tentang Lee Kuan Yew.', NULL, NULL),
(478, 2, NULL, 'hint', 'Susunan idea ialah 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald dan 1955 Tunku.', 'Tarikh jangkar: 1951 dan 1955.\nSebab: MacDonald berbincang dahulu, kemudian Tunku mencadangkan.\nAkibat: idea ini sudah lama wujud, jadi ia bukan idea baharu.', 'Hebat! Susunan 1887, 1938, 1951 dan 1955 tepat. Ucapan Parlimen kini selamat.'),
(479, NULL, 'e1_n1_s3', 'hint', 'Ghazali menyebut ada orang di Tanah Melayu yang akan bertanya soal keseimbangan penduduk.', NULL, NULL),
(480, 3, NULL, 'hint', 'Sebab pertama ialah menjamin keselamatan negara: ancaman komunis di Singapura dan Sarawak dapat dibendung.', 'Tarikh jangkar: Mei 1961.\nSebab: ancaman komunis di Singapura dan Sarawak.\nAkibat: gabungan dilihat dapat membendung ancaman itu.', 'Berjaya! Keempat-empat bukti ditemui. Lee yakin Persekutuan bersungguh-sungguh.'),
(481, NULL, 'e1_n1_s4', 'hint', 'Ingat singkatan KEKS: Keselamatan, Keseimbangan kaum, Kemerdekaan, Sosioekonomi.', NULL, NULL),
(482, 4, NULL, 'hint', 'Empat sebab: keselamatan, keseimbangan kaum, kemerdekaan dipercepat dan sosioekonomi.', 'Tarikh jangkar: Mei 1961.\nSebab: kaum seimbang, kemerdekaan dipercepat, sosioekonomi maju, selain keselamatan.\nAkibat: Sarawak, Sabah dan Brunei diajak bergabung.', 'Bagus! Empat sebab sudah berpadanan. Hujah Tunku kini berlapis dan kukuh.'),
(483, NULL, 'e1_n1_s5', 'hint', 'Ghazali menyebut wartawan menunggu jawapan tentang Borneo. Babak seterusnya di Sarawak.', NULL, NULL),
(484, 5, NULL, 'hint', 'Pada 27 Mei 1961 Tunku mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura.', 'Tarikh jangkar: 27 Mei 1961.\nSebab: Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura.\nAkibat: Tunku mesti menerangkan sendiri di Sarawak.', 'Betul! 27 Mei 1961 di Hotel Adelphi. Langkah pertama sudah dicatat dengan tepat.'),
(485, NULL, 'e1_n1_s6', 'hint', 'Ghazali menyebut nama Donald Stephens dan sebuah cadangan yang mengubah haluan.', NULL, NULL),
(486, 6, NULL, 'hint', 'Pada Julai 1961 Tunku menerangkan idea Malaysia kepada pemimpin Sarawak: Jugah (PESAKA), Ningkan (SNAP) dan Abang Haji Mustapha (PANAS).', 'Tarikh jangkar: Julai 1961.\nSebab: pemimpin Sarawak ragu dan mahu suara mereka didengar.\nAkibat: Donald Stephens akan mencadangkan sebuah jawatankuasa.', 'Bagus! Pemimpin dan parti sudah berpadanan. Jugah mengangguk perlahan.'),
(487, NULL, 'e1_n1_s7', 'hint', 'Ghazali berbisik: British mahukan bukti persetujuan rakyat. Satu suruhanjaya akan menyusul.', NULL, NULL),
(488, 7, NULL, 'hint', 'JSKM ditubuhkan pada 23 Julai 1961 atas cadangan Donald Stephens untuk meyakinkan pemimpin Sarawak dan Sabah.', 'Tarikh jangkar: 23 Julai 1961.\nSebab: JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah.\nAkibat: British mahu bukti persetujuan rakyat.', 'Hebat! Semua bukti penubuhan JSKM ditemui. Jawatankuasa itu kini dipercayai.'),
(489, NULL, 'e1_n1_s8', 'hint', 'Ghazali menyebut seorang wakil SUPP sudah menunggu di luar bilik. Laporan akan datang.', NULL, NULL),
(490, 8, NULL, 'hint', 'Suruhanjaya Cobbold dibentuk pada 17 Januari 1962 untuk mendapatkan reaksi penduduk Sarawak dan Sabah.', 'Tarikh jangkar: 17 Januari 1962.\nSebab: Cobbold dibentuk untuk mendapatkan reaksi penduduk.\nAkibat: laporan akan menentukan langkah seterusnya.', 'Tepat! Peranan setiap tokoh sudah jelas. Penduduk berani menghadap suruhanjaya.'),
(491, NULL, 'e1_n1_s9', 'hint', 'Ghazali menyebut laporan sudah selesai tetapi perlembagaan untuk Sarawak dan Sabah belum disusun.', NULL, NULL),
(492, 9, NULL, 'hint', 'Laporan 21 Jun 1962: dua pertiga menyokong. SUPP menolak kerana mahu persekutuan sendiri bersama Brunei dan Borneo Utara.', 'Tarikh jangkar: 21 Jun 1962.\nSebab: laporan Cobbold mendapati dua pertiga menyokong, tetapi SUPP menolak.\nAkibat: perlembagaan yang melindungi Sarawak dan Sabah perlu disusun.', 'Tepat! Penolak dikenal pasti dan dapatan laporan jelas. Sambanthan siap menjawab penentang.'),
(493, NULL, 'e1_n1_s10', 'hint', 'Ghazali menyebut Singapura sedang menunggu rundingan. Langkah berikutnya ialah referendum.', NULL, NULL),
(494, 10, NULL, 'hint', 'JAK bermesyuarat pada 30 Ogos 1962 untuk menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah.', 'Tarikh jangkar: 30 Ogos 1962.\nSebab: JAK menyediakan rangka perlembagaan yang melindungi Sarawak dan Sabah.\nAkibat: Singapura menunggu rundingan.', 'Betul! Ahli, tujuan dan tarikh JAK jelas. Wakil Sarawak dan Sabah berpuas hati.'),
(495, NULL, 'e1_n1_s11', 'hint', 'Ghazali menyebut Perjanjian di London akan menyusul, tetapi Jakarta dan Manila belum diam.', NULL, NULL),
(496, 11, NULL, 'hint', 'Cobbold (17 Jan), laporan (21 Jun), JAK (30 Ogos) dan referendum (1 Sept 1962) ialah empat langkah berantai.', 'Tarikh jangkar: 1 September 1962.\nSebab: rakyat Singapura mengundi dalam referendum.\nAkibat: keputusan bersetuju membuka jalan ke Perjanjian di London.', 'Betul! Empat langkah tersusun dari Cobbold hingga referendum. Lee tersenyum.'),
(497, NULL, 'e1_n1_s12', 'hint', 'Ghazali berbisik: cara yang adil akan datang daripada sebuah badan dunia.', NULL, NULL),
(498, 12, NULL, 'hint', 'Pada 9 Julai 1963 Perjanjian Malaysia ditandatangani di Marlborough House, London. Jugah dan Abang Haji Mustapha menandatangani bagi Sarawak.', 'Tarikh jangkar: 9 Julai 1963.\nSebab: Perjanjian Malaysia ditandatangani di Marlborough House, London.\nAkibat: Indonesia dan Filipina membantah.', 'Berjaya! Semua bukti ditemui. Perjanjian itu kini sah di mata dunia.'),
(499, NULL, 'e1_n1_s13', 'hint', 'Ghazali menyebut Pemasyhuran dan laungan merdeka yang akan bergema di empat tempat.', NULL, NULL),
(500, 13, NULL, 'hint', 'PBB mewujudkan UNMM pada 12 Ogos 1963 untuk mengesahkan persetujuan penduduk Sarawak dan Sabah.', 'Tarikh jangkar: 12 Ogos 1963.\nSebab: PBB mewujudkan UNMM untuk mengesahkan persetujuan penduduk Sarawak dan Sabah.\nAkibat: Pemasyhuran boleh diteruskan.', 'Betul! UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah. Donald berpuas hati.'),
(501, NULL, 'e1_n1_s14', 'hint', 'Ghazali menyebut laungan merdeka belum dibalas oleh semua orang. Cabaran menanti.', NULL, NULL),
(502, 14, NULL, 'hint', 'Pada 16 September 1963 Tunku memasyhurkan Malaysia di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.', 'Tarikh jangkar: 16 September 1963.\nSebab: Malaysia dimasyhurkan serentak di empat tempat.\nAkibat: cabaran selepas Pemasyhuran bermula.', 'Tepat! Dokumen Pemasyhuran dikenal pasti dengan betul. Hari Malaysia bermula di sini.'),
(503, NULL, 'e1_n1_s15', 'hint', 'Ghazali menyebut Brunei tidak menyertai. Singapura pula akan berpisah suatu hari nanti.', NULL, NULL),
(504, 15, NULL, 'hint', 'Malaysia 1963 terdiri daripada 11 negeri Persekutuan Tanah Melayu, Singapura, Sabah dan Sarawak. Brunei menolak penyertaan.', 'Tarikh jangkar: 16 September 1963.\nSebab: 11 negeri Persekutuan Tanah Melayu, Singapura, Sabah dan Sarawak bergabung.\nAkibat: Singapura berpisah pada 1965.', 'Bagus! Negeri-negeri berpadanan dan murid faham bilangan negeri pada 1963.'),
(505, NULL, 'e1_n1_s16', 'hint', 'Ghazali menyebut hari terakhir akan tiba. Tunku akan melihat kembali tugasnya.', NULL, NULL),
(506, 16, NULL, 'hint', 'Cabaran selepas Pemasyhuran: SUPP menolak, Indonesia melancarkan konfrontasi (1963 hingga 1966), Filipina mendakwa Sabah dan Singapura berpisah pada 1965.', 'Tarikh jangkar: 1963 hingga 1966.\nSebab: Indonesia berkonfrontasi, Filipina mendakwa Sabah dan Singapura berpisah 1965.\nAkibat: hubungan pulih melalui permuafakatan.', 'Bagus! Setiap cabaran dikenal pasti dengan pihaknya. Tunku bersedia menjawab dengan tenang.'),
(507, NULL, 'e1_n1_s17', 'hint', 'Ghazali berkata generasi kemudian akan mewarisi cerita ini.', NULL, NULL),
(508, 17, NULL, 'hint', 'Lapan langkah dari 27 Mei 1961 hingga 16 September 1963 membentuk Malaysia.', 'Tarikh jangkar: 27 Mei 1961 hingga 16 September 1963.\nSebab: permuafakatan semua pihak.\nAkibat: Malaysia terbentuk dan kekal makmur.', 'Syabas! Lapan langkah tersusun dengan tepat. Rekod arkib negara kini lengkap.'),
(509, NULL, 'e1_n2_s1', 'hint', 'Mustapha menyebut ada dua fail lagi. Satu tarikh tidak membuat sejarah.', NULL, NULL),
(510, 18, NULL, 'hint', 'Pada 1887 Lord Brassey mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat.', 'Tarikh jangkar: 1887.\nSebab: Lord Brassey mahu menggabungkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat.\nAkibat: idea gabungan sudah lama wujud, bukan hanya milik Tunku.', 'Tepat! Dakwat pudar menjadi jelas. Mustapha Harun mengangguk perlahan.'),
(511, NULL, 'e1_n2_s2', 'hint', 'Seorang pegawai membawa laporan dari Razak. Mustapha menyebut ada sebab yang lebih mendesak daripada sejarah.', NULL, NULL),
(512, 19, NULL, 'hint', 'Idea gabungan: 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald, 1955 Tunku. Setiap pihak datang dengan cara yang berbeza.', 'Tarikh jangkar: 1955.\nSebab: idea berulang sejak 1887, 1938 dan 1951.\nAkibat: Tunku mencadangkan empat wilayah menyertai Persekutuan Tanah Melayu.', 'Hebat! Empat nama dan empat tahun berpadanan. Orang kampung kini nampak talinya.'),
(513, NULL, 'e1_n2_s3', 'hint', 'Razak menyebut keselamatan hanya satu sebab. Tiga lagi akan ditanya orang kampung.', NULL, NULL),
(514, 20, NULL, 'hint', 'Sebab pertama ialah keselamatan: Singapura dan Sarawak menghadapi ancaman komunis, dan Persekutuan Tanah Melayu berpengalaman menghadapinya.', 'Tarikh jangkar: sebelum 27 Mei 1961.\nSebab: Singapura dan Sarawak menghadapi ancaman komunis.\nAkibat: Malaysia dapat membendung ancaman itu.', 'Berjaya! Ketiga-tiga bukti ditemui. Razak mengangguk dengan puas.'),
(515, NULL, 'e1_n2_s4', 'hint', 'Pagi esok, akhbar sampai lebih cepat daripada pesuruh. Mustapha menepuk dahi.', NULL, NULL),
(516, 21, NULL, 'hint', 'Empat sebab: menjamin keselamatan, mencapai keseimbangan kaum, mempercepat kemerdekaan dan membangunkan sosioekonomi.', 'Tarikh jangkar: sebelum 27 Mei 1961.\nSebab: keselamatan, keseimbangan kaum, kemerdekaan dipercepat, sosioekonomi.\nAkibat: orang kampung faham mengapa gabungan wajar difikirkan.', 'Betul! Dewan senyap, kemudian seorang tua berkata cerita itu masuk akal.'),
(517, NULL, 'e1_n2_s5', 'hint', 'Telegram dari Kuching menyusul. Tunku bertolak ke Sarawak dahulu untuk menerangkan.', NULL, NULL),
(518, 22, NULL, 'hint', 'Pada 27 Mei 1961 Tunku mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura.', 'Tarikh jangkar: 27 Mei 1961.\nSebab: Tunku mengumumkan cadangan di Hotel Adelphi, Singapura.\nAkibat: pemimpin Sarawak dan Sabah perlu diyakinkan.', 'Betul! 27 Mei 1961. Mustapha menulis tarikh itu di lengan bajunya.'),
(519, NULL, 'e1_n2_s6', 'hint', 'Tunku tersenyum. Jawatankuasa yang Donald cadangkan perlu diberi nama.', NULL, NULL),
(520, 23, NULL, 'hint', 'Pada Julai 1961 Tunku melawat Sarawak untuk menerangkan idea pembentukan Malaysia kepada pemimpin tempatan.', 'Tarikh jangkar: Julai 1961.\nSebab: Tunku ke Sarawak untuk menerangkan idea Malaysia.\nAkibat: pemimpin bertanya, dan Donald mencadangkan sebuah jawatankuasa bersama.', 'Berjaya! Ketiga-tiga bukti ditemui. Tunku tersenyum dan meminta Donald memberi nama jawatankuasa itu.'),
(521, NULL, 'e1_n2_s7', 'hint', 'Jugah menyebut meyakinkan pemimpin itu mudah, tetapi rakyat di kampung bukan mudah.', NULL, NULL),
(522, 24, NULL, 'hint', 'JSKM ditubuhkan pada 23 Julai 1961 atas cadangan Donald Stephens, dihadiri pemimpin pelbagai parti.', 'Tarikh jangkar: 23 Julai 1961.\nSebab: JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah.\nAkibat: pemimpin pelbagai parti duduk satu meja.', 'Hebat! Semua pemimpin dan parti berpadanan. Mesyuarat berjalan teratur.'),
(523, NULL, 'e1_n2_s8', 'hint', 'Cobbold mengumpul fail. Pada bulan Jun, laporan diserahkan. Siapkan hati.', NULL, NULL),
(524, 25, NULL, 'hint', 'Suruhanjaya Cobbold dibentuk pada 17 Januari 1962 untuk mendapatkan reaksi penduduk Sarawak dan Sabah melalui temu ramah dan memorandum.', 'Tarikh jangkar: 17 Januari 1962.\nSebab: Cobbold dibentuk untuk mendapatkan reaksi penduduk.\nAkibat: memorandum dan temu ramah dikumpulkan.', 'Betul! Wong tersenyum. Inilah suara rakyat yang dicari Cobbold.'),
(525, NULL, 'e1_n2_s9', 'hint', 'Ningkan menyebut menjawab kebimbangan perlukan kertas. Perlindungan bertulis untuk Sarawak dan Sabah.', NULL, NULL),
(526, 26, NULL, 'hint', 'Lima langkah berantai sehingga laporan Cobbold 21 Jun 1962: dua pertiga menyokong, SUPP menolak.', 'Tarikh jangkar: 21 Jun 1962.\nSebab: laporan Cobbold mendapati dua pertiga menyokong.\nAkibat: SUPP menolak, jadi perlindungan bertulis diperlukan.', 'Betul! Lima langkah tersusun. Hujah Donald kini tidak lompat-lompat.'),
(527, NULL, 'e1_n2_s10', 'hint', 'Dua hari kemudian, Lee Kuan Yew menelefon: rakyat Singapura sudah mengundi.', NULL, NULL),
(528, 27, NULL, 'hint', 'JAK bermesyuarat pada 30 Ogos 1962 dan menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah.', 'Tarikh jangkar: 30 Ogos 1962.\nSebab: JAK menyediakan rangka perlembagaan.\nAkibat: kepentingan Sarawak dan Sabah dilindungi.', 'Betul! JAK dikenal pasti. Ningkan membaca perlahan, kemudian mengangguk.'),
(529, NULL, 'e1_n2_s11', 'hint', 'Razak menyebut perjanjian akan menyusul. Donald, pastikan Sabah bersedia.', NULL, NULL),
(530, 28, NULL, 'hint', 'Pada 1 September 1962 referendum diadakan di Singapura dan rakyat bersetuju dengan pembentukan Malaysia.', 'Tarikh jangkar: 1 September 1962.\nSebab: rundingan Persekutuan dan Singapura selesai, lalu rakyat mengundi.\nAkibat: rakyat Singapura bersetuju.', 'Betul! Lee menghela nafas lega. Dokumen yang betul ditemui.'),
(531, NULL, 'e1_n2_s12', 'hint', 'Mustapha berkata perjanjian sudah ditandatangani, tetapi rakyat belum disahkan. Pasukan PBB sedang menuju ke sini.', NULL, NULL),
(532, 29, NULL, 'hint', 'Pada 9 Julai 1963 Perjanjian Malaysia ditandatangani di Marlborough House, London. Jugah dan Abang Haji Mustapha menandatangani bagi Sarawak.', 'Tarikh jangkar: 9 Julai 1963.\nSebab: Perjanjian Malaysia ditandatangani di Marlborough House, London.\nAkibat: persetujuan penduduk Sarawak dan Sabah perlu disahkan.', 'Betul! Orang ramai bersorak perlahan. Mustapha membaca dengan yakin.'),
(533, NULL, 'e1_n2_s13', 'hint', 'Lima minggu lagi, kata Mustapha, kita akan mendengar pemasyhuran itu.', NULL, NULL),
(534, 30, NULL, 'hint', 'UNMM dibentuk oleh PBB pada 12 Ogos 1963 untuk mengesahkan persetujuan penduduk Sarawak dan Sabah.', 'Tarikh jangkar: 12 Ogos 1963.\nSebab: PBB mewujudkan UNMM untuk mengesahkan persetujuan.\nAkibat: persetujuan penduduk Sarawak dan Sabah disahkan.', 'Berjaya! Ketiga-tiga tanda UNMM ditemui. Tiada siapa dapat meragui lagi.'),
(535, NULL, 'e1_n2_s14', 'hint', 'Mustapha memandang ke laut. Tidak semua orang gembira, ada yang datang dari seberang.', NULL, NULL),
(536, 31, NULL, 'hint', 'Pada 16 September 1963 Malaysia dimasyhurkan di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.', 'Tarikh jangkar: 16 September 1963.\nSebab: Pemasyhuran di empat tempat.\nAkibat: Malaysia terbentuk.', 'Betul! Empat tempat dan empat negeri berpadanan. Bendera naik dengan megah.'),
(537, NULL, 'e1_n2_s15', 'hint', 'Mustapha berkata Singapura juga berpisah pada 1965. Walau begitu kita masih berdiri.', NULL, NULL),
(538, 32, NULL, 'hint', 'Cabaran: Indonesia mengisytiharkan konfrontasi (1963 hingga 1966), Filipina mendakwa Sabah dan Brunei menolak penyertaan.', 'Tarikh jangkar: 1963 hingga 1966.\nSebab: Indonesia berkonfrontasi, Filipina mendakwa Sabah, Brunei tidak menyertai.\nAkibat: hubungan pulih melalui permuafakatan.', 'Betul! Sabah ialah wilayah Donald sendiri. Mustapha menepuk bahu dan berkata kita jawab dengan permuafakatan.'),
(539, NULL, 'e1_n2_s16', 'hint', 'Mustapha berkata perjalanan seterusnya milik generasi akan datang.', NULL, NULL),
(540, 33, NULL, 'hint', 'Lapan langkah dari 27 Mei 1961 hingga 16 September 1963 membentuk Malaysia.', 'Tarikh jangkar: 1965 dan 16 September.\nSebab: Singapura berpisah pada 1965, tetapi Malaysia terus berdiri.\nAkibat: Hari Malaysia disambut sebagai tanda syukur dan perpaduan.', 'Syabas! Lapan langkah tersusun dengan tepat. Ucapan Donald kini lengkap.'),
(541, NULL, 'e1_n3_s1', 'hint', 'Razak menyebut masih ada idea lain sebelum 1961.', NULL, NULL),
(542, 34, NULL, 'hint', 'Pada 1938 Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan konsep Melayu Raya.', 'Tarikh jangkar: 1938.\nSebab: Melayu Raya mahu menyatukan Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia.\nAkibat: idea gabungan sudah wujud sebelum Tunku.', 'Tepat! Razak mengangguk perlahan.'),
(543, NULL, 'e1_n3_s2', 'hint', 'Razak membawa Ghazali ke bilik keselamatan. Sebab pertama menanti.', NULL, NULL),
(544, 35, NULL, 'hint', 'Idea gabungan: 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald, 1955 Tunku.', 'Tarikh jangkar: 1955.\nSebab: idea berulang sejak 1887.\nAkibat: Tunku mencadangkan empat wilayah menyertai Persekutuan.', 'Betul! Empat tahun tersusun rapi.'),
(545, NULL, 'e1_n3_s3', 'hint', 'Razak berkata keselamatan hanya satu daripada empat sebab.', NULL, NULL),
(546, 36, NULL, 'hint', 'Sebab pertama ialah keselamatan: ancaman komunis di Singapura dan Sarawak dapat dibendung bersama.', 'Tarikh jangkar: sebelum 27 Mei 1961.\nSebab: ancaman komunis di Singapura dan Sarawak.\nAkibat: gabungan dapat membendungnya.', 'Berjaya! Semua bukti ditemui.'),
(547, NULL, 'e1_n3_s4', 'hint', 'Razak menyebut Tunku akan membuat pengumuman di Singapura. Teks ucapan mesti tepat.', NULL, NULL),
(548, 37, NULL, 'hint', 'Empat sebab: keselamatan, keseimbangan kaum, kemerdekaan dipercepat dan sosioekonomi.', 'Tarikh jangkar: sebelum 27 Mei 1961.\nSebab: keselamatan, keseimbangan kaum, kemerdekaan, sosioekonomi.\nAkibat: Tunku mengumumkan cadangannya.', 'Hebat! Empat sebab berpadanan.'),
(549, NULL, 'e1_n3_s5', 'hint', 'Selepas pengumuman, Tunku bertolak ke Sarawak.', NULL, NULL),
(550, 38, NULL, 'hint', 'Pada 27 Mei 1961 Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura.', 'Tarikh jangkar: 27 Mei 1961.\nSebab: Tunku mengumumkan cadangan di Hotel Adelphi.\nAkibat: pemimpin Sarawak dan Sabah perlu diyakinkan.', 'Betul! Tunku mengangguk lega.'),
(551, NULL, 'e1_n3_s6', 'hint', 'Dua minggu lagi, satu jawatankuasa bersama akan ditubuhkan.', NULL, NULL),
(552, 39, NULL, 'hint', 'Pada Julai 1961 Tunku melawat Sarawak untuk menerangkan idea pembentukan Malaysia.', 'Tarikh jangkar: Julai 1961.\nSebab: Tunku mahu menerangkan idea Malaysia.\nAkibat: JSKM ditubuhkan.', 'Betul! Tujuan lawatan jelas.'),
(553, NULL, 'e1_n3_s7', 'hint', 'Selepas pemimpin diyakinkan, rakyat pula ditanya.', NULL, NULL),
(554, 40, NULL, 'hint', 'JSKM ditubuhkan pada 23 Julai 1961 untuk meyakinkan pemimpin Sarawak dan Sabah.', 'Tarikh jangkar: 23 Julai 1961.\nSebab: pemimpin Sarawak dan Sabah perlu diyakinkan.\nAkibat: JSKM ditubuhkan.', 'Berjaya! Bukti ditemui.'),
(555, NULL, 'e1_n3_s8', 'hint', 'Lima bulan kemudian, laporan siap.', NULL, NULL),
(556, 41, NULL, 'hint', 'Suruhanjaya Cobbold dibentuk pada 17 Januari 1962 untuk mendapatkan reaksi penduduk.', 'Tarikh jangkar: 17 Januari 1962.\nSebab: mendapatkan reaksi penduduk.\nAkibat: temu ramah dan memorandum dikumpulkan.', 'Betul! Tugas suruhanjaya jelas.'),
(557, NULL, 'e1_n3_s9', 'hint', 'Tiga bulan lagi, JAK bermesyuarat.', NULL, NULL),
(558, 42, NULL, 'hint', 'Laporan Cobbold 21 Jun 1962: dua pertiga menyokong, SUPP menolak dan mahu persekutuan sendiri.', 'Tarikh jangkar: 21 Jun 1962.\nSebab: laporan Cobbold mendapati dua pertiga menyokong.\nAkibat: perlindungan bertulis diperlukan.', 'Betul! Laporan yang tepat.'),
(559, NULL, 'e1_n3_s10', 'hint', 'Dua hari kemudian, Singapura mengundi.', NULL, NULL),
(560, 43, NULL, 'hint', 'JAK bermesyuarat pada 30 Ogos 1962 dan menyediakan rangka perlembagaan.', 'Tarikh jangkar: 30 Ogos 1962.\nSebab: perlindungan bertulis diperlukan.\nAkibat: rangka perlembagaan disediakan.', 'Berjaya! Bukti JAK ditemui.'),
(561, NULL, 'e1_n3_s11', 'hint', 'Perjanjian menanti.', NULL, NULL),
(562, 44, NULL, 'hint', 'Pada 1 September 1962 referendum Singapura diadakan dan rakyat bersetuju.', 'Tarikh jangkar: 1 September 1962.\nSebab: Singapura perlu menyatakan pendirian.\nAkibat: rakyat Singapura bersetuju.', 'Betul! Referendum.'),
(563, NULL, 'e1_n3_s12', 'hint', 'Seterusnya PBB mengesahkan persetujuan penduduk.', NULL, NULL),
(564, 45, NULL, 'hint', 'Pada 9 Julai 1963 Perjanjian Malaysia ditandatangani di Marlborough House, London.', 'Tarikh jangkar: 9 Julai 1963.\nSebab: rangka perlembagaan dan persetujuan.\nAkibat: persetujuan penduduk perlu disahkan.', 'Betul! Fail yang tepat.'),
(565, NULL, 'e1_n3_s13', 'hint', 'Dokumen pemasyhuran menanti.', NULL, NULL),
(566, 46, NULL, 'hint', 'Empat badan: JSKM meyakinkan, Cobbold bertanya, JAK menulis, UNMM mengesahkan.', 'Tarikh jangkar: 1961 hingga 1963.\nSebab: setiap badan ada tugas berbeza.\nAkibat: Malaysia dimasyhurkan.', 'Hebat! Semua berpadanan.'),
(567, NULL, 'e1_n3_s14', 'hint', 'Namun cabaran menanti.', NULL, NULL),
(568, 47, NULL, 'hint', 'Pada 16 September 1963 Malaysia dimasyhurkan di empat tempat.', 'Tarikh jangkar: 16 September 1963.\nSebab: semua langkah selesai.\nAkibat: Malaysia terbentuk.', 'Berjaya! Dokumen lengkap.'),
(569, NULL, 'e1_n3_s15', 'hint', 'Razak mengajak Ghazali merumuskan.', NULL, NULL),
(570, 48, NULL, 'hint', 'Cabaran: SUPP, konfrontasi Indonesia, dakwaan Filipina dan penolakan Brunei.', 'Tarikh jangkar: 1963 hingga 1966.\nSebab: pelbagai pihak membantah.\nAkibat: permuafakatan diperlukan.', 'Betul! Semua berpadanan.'),
(571, NULL, 'e1_n3_s16', 'hint', 'Fail ditutup, tetapi kisah diteruskan oleh generasi akan datang.', NULL, NULL),
(572, 49, NULL, 'hint', 'Lapan langkah dari 27 Mei 1961 hingga 16 September 1963. Muafakat membawa berkat.', 'Tarikh jangkar: 16 September 1963.\nSebab: lapan langkah diselesaikan dengan teliti.\nAkibat: Hari Malaysia disambut setiap tahun.', 'Syabas! Lapan langkah tersusun.'),
(573, NULL, 'e2_n1_s1', 'hint', 'Tok memulakan halaman pertama di Perlis. Perhatikan kelapa di dalam parit dan baca perkataan Siam itu.', NULL, NULL),
(574, 201, NULL, 'hint', 'Perlis: prow-lowy bermaksud kelapa hanyut. Ada juga cerita \'peroleh\' dalam peristiwa Raja Syed Hussin Jamalullail.', 'Tempat: Perlis.\nSebab nama: prow-lowy (kelapa hanyut) atau \'peroleh\' (mandat Raja Syed Hussin).\nKesan: dua cerita sama-sama dicatat.', 'Tepat! Pesawah mengangguk dan Tok menulis halaman pertama Buku Asal Usul.'),
(575, NULL, 'e2_n1_s2', 'hint', 'Halaman kedua ialah Kedah. Satu benda untuk menangkap gajah, satu untuk minum, satu lagi tulisan India Selatan.', NULL, NULL),
(576, 202, NULL, 'hint', 'Kedah: kheddah (perangkap gajah), qadah (cawan berkaki) dan kadaram atau kalagam dalam tulisan Tamil.', 'Tempat: Kedah.\nSebab nama: kheddah, qadah atau kadaram/kalagam.\nKesan: nama Kedah dicatat dalam tiga bahasa.', 'Hebat! Tiga catatan dipadankan dan kedua-dua lelaki itu senyap.'),
(577, NULL, 'e2_n1_s3', 'hint', 'Dua negeri sekali gus: Pulau Pinang dan Perak. Pisahkan cerita setiap negeri.', NULL, NULL),
(578, 203, NULL, 'hint', 'Pulau Pinang: Pulo Ka Satu, Tanjong Penaga, buah pinang. Perak: kilatan ikan, bijih timah putih berkilat.', 'Tempat: Pulau Pinang dan Perak.\nSebab nama: Pulo Ka Satu, Tanjong Penaga, pinang; kilatan ikan, bijih timah.\nKesan: nama menunjukkan alam dan perdagangan.', 'Betul! Nelayan dan pelombong akur dan halaman ketiga siap.'),
(579, NULL, 'e2_n1_s4', 'hint', 'Tok memadankan ibu negeri dan bandar diraja di utara. Lihat titik merah dan kuning di peta.', NULL, NULL),
(580, 204, NULL, 'hint', 'Kangar-Arau, Alor Setar-Anak Bukit, Ipoh-Kuala Kangsar. Pulau Pinang ibu negerinya George Town.', 'Tempat: Perlis, Kedah, Perak, Pulau Pinang.\nSebab: ibu negeri pusat pentadbiran; bandar diraja ada warisan.\nKesan: warisan wajar dipelihara.', 'Cemerlang! Titik merah dan kuning dipadankan dengan betul.'),
(581, NULL, 'e2_n1_s5', 'hint', 'Lagu negeri ialah lambang kemegahan. Tajuk lagu Kedah menyebut \'Sultan\' dan \'Mahkota\'.', NULL, NULL),
(582, 205, NULL, 'hint', 'Lagu utara: Perlis Aamiin-Aamiin, Kedah Allah Selamatkan Sultan Mahkota, Perak Allah Lanjutkan Usia Sultan, Pulau Pinang Untuk Negeri Kita.', 'Tempat: Perlis, Kedah, Perak, Pulau Pinang.\nSebab: lagu negeri lambang kemegahan dan kedaulatan.\nKesan: lagu yang betul menunjukkan hormat.', 'Betul! Lagu Kedah berkumandang dan majlis bermula dengan lancar.'),
(583, NULL, 'e2_n1_s6', 'hint', 'Dua negeri: Selangor dan Negeri Sembilan. Satu daripadanya mempunyai angka 1773.', NULL, NULL),
(584, 206, NULL, 'hint', 'Selangor: mentagau atau selangur. Negeri Sembilan: sembilan luak pada 1773, nagari bermaksud wilayah.', 'Tarikh jangkar: 1773.\nSebab nama: mentagau atau selangur; sembilan luak, \'nagari\'.\nKesan: nama menyimpan gabungan dan alam.', 'Tepat! Nelayan dan penghulu bersalaman.'),
(585, NULL, 'e2_n1_s7', 'hint', 'Dua negeri: Melaka dan Johor. Tok memadankan perdagangan, legenda dan naskhah lama.', NULL, NULL),
(586, 207, NULL, 'hint', 'Melaka: Malakat dan pokok Parameswara. Johor: Jauhar dan Ujong Tanah.', 'Tempat: Melaka dan Johor.\nSebab nama: Malakat, pokok Parameswara; Jauhar, Ujong Tanah.\nKesan: nama dari perdagangan, legenda dan naskhah.', 'Betul! Empat cerita dipadankan dan pembaca naskhah mengangguk.'),
(587, NULL, 'e2_n1_s8', 'hint', 'Tok memadankan ibu negeri dan bandar diraja di tengah semenanjung. Seri Menanti dan Bandar Maharani ialah bandar diraja.', NULL, NULL),
(588, 208, NULL, 'hint', 'Shah Alam-Klang, Seremban-Seri Menanti, Johor Bahru-Bandar Maharani, Bandar Melaka tiada bandar diraja.', 'Tempat: Selangor, Negeri Sembilan, Melaka, Johor.\nSebab: ibu negeri pusat pentadbiran; bandar diraja ada warisan.\nKesan: pembangunan dan warisan dijaga.', 'Betul! Fail dipadankan dan pegawai menarik nafas lega.'),
(589, NULL, 'e2_n1_s9', 'hint', 'Empat lagu dari empat negeri tengah dan selatan. Tajuk yang betul menyebut nama negerinya sendiri.', NULL, NULL),
(590, 209, NULL, 'hint', 'Lagu tengah dan selatan: Selangor Duli Yang Maha Mulia, Negeri Sembilan Berkatlah Yang di-Pertuan Besar, Melaka Melaka Maju Jaya, Johor Lagu Bangsa Johor.', 'Tempat: Selangor, Negeri Sembilan, Melaka, Johor.\nSebab: setiap negeri ada lagu tersendiri.\nKesan: lagu yang betul menunjukkan hormat.', 'Betul! Lagu Johor berkumandang dengan megah.'),
(591, NULL, 'e2_n1_s10', 'hint', 'Pantai timur ada tiga negeri dan enam cerita. Pelangi dan taring milik negeri yang sama.', NULL, NULL),
(592, 210, NULL, 'hint', 'Pantai timur: Pahang mahang dan Inderapura; Terengganu taring anu dan terangnya ganu; Kelantan kilatan dan gelam hutan.', 'Tempat: Pahang, Terengganu, Kelantan.\nSebab nama: mahang, Inderapura; taring anu, terangnya ganu; kilatan, gelam hutan.\nKesan: nama lahir daripada alam dan sejarah.', 'Hebat! Enam cerita dipadankan dan pantai senyap.'),
(593, NULL, 'e2_n1_s11', 'hint', 'Hanya satu negeri di pantai timur mempunyai titik kuning pada peta, iaitu Pahang.', NULL, NULL),
(594, 211, NULL, 'hint', 'Pahang: Kuantan dan Pekan. Terengganu: Kuala Terengganu. Kelantan: Kota Bharu.', 'Tempat: Pahang, Terengganu, Kelantan.\nSebab: ibu negeri pusat pentadbiran; Pekan bandar diraja.\nKesan: warisan pantai timur dihargai.', 'Betul! Peta dipadankan dan pegawai mengangguk.'),
(595, NULL, 'e2_n1_s12', 'hint', 'Lagu negeri ialah lambang kedaulatan. Dua negeri pantai timur berkongsi tajuk yang sama.', NULL, NULL),
(596, 212, NULL, 'hint', 'Terengganu dan Kelantan sama-sama Selamat Sultan. Pahang: Allah Selamatkan Sultan Kami.', 'Tempat: Pahang, Terengganu, Kelantan.\nSebab: Terengganu dan Kelantan sama-sama \'Selamat Sultan\'; Pahang \'Allah Selamatkan Sultan Kami\'.\nKesan: tajuk sama tidak bermaksud negeri sama.', 'Tepat! Dua orang tua tersenyum dan akur.'),
(597, NULL, 'e2_n1_s13', 'hint', 'Tok menyeberang ke Borneo mencatat nama Sarawak dan Sabah. Cari galian, makanan dan tarikh.', NULL, NULL),
(598, 213, NULL, 'hint', 'Sarawak: Sungai Serak dan bijih sarawak atau cerava. Sabah: pisang saba dan dokumen Maharajah of Sabah 1877.', 'Tarikh jangkar: 1877 (dokumen Sabah).\nSebab nama: Sungai Serak, cerava (Sarawak); pisang saba (Sabah).\nKesan: nama dikaitkan dengan galian dan makanan.', 'Betul! Dokumen yang tepat ditemui.'),
(599, NULL, 'e2_n1_s14', 'hint', 'Wilayah Persekutuan terdiri daripada tiga wilayah. Satu nama dari lumpur, satu dari kapal berlabuh, satu dari seorang pemimpin.', NULL, NULL),
(600, 214, NULL, 'hint', 'Wilayah Persekutuan: Kuala Lumpur, Labuan dan Putrajaya. Wilayah ini tiada ibu negeri dan bandar diraja.', 'Tempat: Kuala Lumpur, Labuan, Putrajaya.\nSebab nama: lumpur, labuhan, Putra + jaya.\nKesan: nama menyimpan sejarah perlombongan, pelayaran dan kepimpinan.', 'Betul! Tiga pelawat tersenyum puas.'),
(601, NULL, 'e2_n1_s15', 'hint', 'Tok memadankan ibu negeri Borneo. Satu bandar di tepi sungai, satu lagi di pantai dengan gunung.', NULL, NULL),
(602, 215, NULL, 'hint', 'Sarawak: Kuching. Sabah: Kota Kinabalu. Ibu negeri berkembang kerana pembangunan pentadbiran, kemudahan asas dan pendidikan.', 'Tempat: Sarawak dan Sabah.\nSebab: Kuching dan Kota Kinabalu ialah ibu negeri, pusat pentadbiran dan pekerjaan.\nKesan: pembangunan pentadbiran menyebabkan ibu negeri berkembang.', 'Betul! Dua fail dipadankan dan pegawai tersenyum.'),
(603, NULL, 'e2_n1_s16', 'hint', 'Tok memadankan lagu Borneo dan Wilayah Persekutuan. Tajuk lagu Sabah menyebut \'Sabah\' secara terus.', NULL, NULL),
(604, 216, NULL, 'hint', 'Lagu Borneo dan Wilayah Persekutuan: Sabah Sabah Tanah Airku, Sarawak Ibu Pertiwiku, Wilayah Persekutuan Maju dan Sejahtera.', 'Tempat: Sabah, Sarawak, Wilayah Persekutuan.\nSebab: lagu negeri membentuk identiti dan lambang kemegahan.\nKesan: lagu yang betul menghormati negeri itu.', 'Betul! Lagu Sabah berkumandang dan tetamu bangun berdiri.'),
(605, NULL, 'e2_n1_s17', 'hint', 'Pegawai istiadat mahu Tok menyusun gelaran ketua negeri. Tujuh Sultan, satu Raja, satu Yang di-Pertuan Besar, empat Yang di-Pertua Negeri.', NULL, NULL),
(606, 217, NULL, 'hint', 'Raja di Perlis. Sultan di tujuh negeri. Yang di-Pertuan Besar di Negeri Sembilan. Yang di-Pertua Negeri di empat negeri. Wilayah Persekutuan: Yang di-Pertuan Agong.', 'Tempat: seluruh Malaysia.\nSebab: ketua negeri tonggak pemerintahan; gelaran berbeza ikut negeri.\nKesan: kita menghormati dan taat setia kepada raja.', 'Hebat! Semua kad dipasang dengan betul.'),
(607, NULL, 'e2_n1_s18', 'hint', 'Pesta Warisan. Buku Asal Usul dilengkapkan dengan lambang negeri. Cari sesuatu yang berkibar, tergantung dan berbunyi.', NULL, NULL),
(608, 218, NULL, 'hint', 'Setiap negeri mempunyai bendera, lagu dan jata sebagai lambang kemegahan dan kedaulatan.', 'Tempat: Pesta Warisan Negara, Wilayah Persekutuan.\nSebab: setiap negeri ada bendera, lagu dan jata sebagai identiti.\nKesan: mengenali lambang negeri menaikkan rasa cinta akan negara.', 'Berjaya! Ketiga-tiga lambang ditemui dan Buku Asal Usul dilengkapkan.'),
(609, NULL, 'e2_n2_s1', 'hint', 'Ketua ini bukan Sultan atau Raja negeri. Ketua negara memegang jawatan lebih tinggi.', NULL, NULL),
(610, 219, NULL, 'hint', 'Hari pertama kiraan detik. Kad ketua Wilayah Persekutuan hilang dan dicari melalui nota fail.', 'Tempat: Wilayah Persekutuan.\nSebab: ketua negeri bagi Wilayah Persekutuan ialah Yang di-Pertuan Agong.\nKesan: Wilayah Persekutuan tiada ibu negeri dan bandar diraja.', 'Betul! Kad ketua dipasang dan Encik Zahar mengetap bibir.'),
(611, NULL, 'e2_n2_s2', 'hint', 'Satu nama dari lumpur, satu dari kapal berlabuh, satu dari nama seorang tokoh.', NULL, NULL),
(612, 220, NULL, 'hint', 'Tiga wilayah mempunyai tiga kisah nama. Pegawai Istiadat memadankan papan nama.', 'Tempat: Kuala Lumpur, Labuan, Putrajaya.\nSebab nama: lumpur, labuhan, Putra + jaya.\nKesan: tiga wilayah, tiga sejarah.', 'Betul! Papan nama dipasang semula.'),
(613, NULL, 'e2_n2_s3', 'hint', 'Tujuh Sultan, satu Raja, satu Yang di-Pertuan Besar dan empat Yang di-Pertua Negeri.', NULL, NULL),
(614, 221, NULL, 'hint', 'Pegawai Istiadat menyusun gelaran ketua negeri sambil dicurigai.', 'Tempat: seluruh Malaysia.\nSebab: ketua negeri tonggak pemerintahan.\nKesan: sikap hormat dan taat setia dipupuk.', 'Betul! Semua kad disusun dengan teliti.'),
(615, NULL, 'e2_n2_s4', 'hint', 'Empat negeri: dua di Semenanjung dan dua di Borneo.', NULL, NULL),
(616, 222, NULL, 'hint', 'Pembantu Yang di-Pertua Negeri memerlukan dokumen yang betul.', 'Tempat: Pulau Pinang, Melaka, Sarawak, Sabah.\nSebab: gelaran ketua negeri berbeza.\nKesan: istiadat betul menghormati ketua negeri.', 'Betul! Dokumen yang tepat diserahkan.'),
(617, NULL, 'e2_n2_s5', 'hint', 'Cari sesuatu yang tumbuh di kuala, sesuatu yang terbang di sungai, perkataan Minangkabau dan satu tahun.', NULL, NULL),
(618, 223, NULL, 'hint', 'Hari kedua bermula di Selangor dan Negeri Sembilan. Satu nama membawa angka 1773.', 'Tarikh jangkar: 1773 (luak asal Negeri Sembilan).\nSebab nama: mentagau atau selangur; sembilan luak, \'nagari\'.\nKesan: nama menyimpan gabungan dan alam.', 'Betul! Tahun piagam dicatat dalam kad pengacara.'),
(619, NULL, 'e2_n2_s6', 'hint', 'Nota menyebut naskhah klasik. Nama itu bermaksud hujung sebuah daratan.', NULL, NULL),
(620, 224, NULL, 'hint', 'Pegawai Istiadat menemui nota Zahar di Melaka.', 'Tempat: Melaka dan Johor.\nSebab nama: Malakat, pokok Parameswara; Jauhar, Ujong Tanah.\nKesan: nama dari perdagangan, legenda dan naskhah.', 'Betul! Nota Zahar berjaya dinyahkod.'),
(621, NULL, 'e2_n2_s7', 'hint', 'Dua bandar diraja bernama \'Seri Menanti\' dan \'Bandar Maharani\'. Satu ibu negeri tiada bandar diraja.', NULL, NULL),
(622, 225, NULL, 'hint', 'Fail ibu negeri dan bandar diraja di tengah dan selatan semenanjung dibetulkan.', 'Tempat: Selangor, Negeri Sembilan, Melaka, Johor.\nSebab: ibu negeri ialah pusat pentadbiran; bandar diraja ada warisan.\nKesan: warisan perlu dipelihara.', 'Betul! Fail dipadankan semula.'),
(623, NULL, 'e2_n2_s8', 'hint', 'Tajuk Negeri Sembilan menyebut \'Yang di-Pertuan Besar\'. Tajuk Melaka menyebut Melaka.', NULL, NULL),
(624, 226, NULL, 'hint', 'Zahar menukar label kaset empat lagu negeri.', 'Tempat: Selangor, Negeri Sembilan, Melaka, Johor.\nSebab: lagu ialah lambang kedaulatan.\nKesan: lagu yang betul menghormati negeri.', 'Betul! Label dipasang semula.'),
(625, NULL, 'e2_n2_s9', 'hint', 'Satu benda hanyut di air, satu benda berkilau di dalam air, satu benda berkilat di lombong.', NULL, NULL),
(626, 227, NULL, 'hint', 'Perlis dan Perak memerlukan padanan dua cerita setiap satu.', 'Tempat: Perlis dan Perak.\nSebab nama: kelapa hanyut, peroleh; kilatan ikan, bijih timah.\nKesan: nama dari bahasa Siam, peristiwa dan alam.', 'Betul! Empat kad dipadankan.'),
(627, NULL, 'e2_n2_s10', 'hint', 'Padankan pokok, buah, nama asal pulau, cawan dan tulisan Tamil.', NULL, NULL),
(628, 228, NULL, 'hint', 'Dua negeri sekali gus: Kedah dan Pulau Pinang. Satu sampul tersembunyi dicari.', 'Tempat: Pulau Pinang dan Kedah.\nSebab nama: Pulo Ka Satu, Tanjong Penaga, pinang; kheddah, qadah, kadaram.\nKesan: nama dari alam, perdagangan dan bahasa.', 'Betul! Sampul ditemui di bawah karung pinang.'),
(629, NULL, 'e2_n2_s11', 'hint', 'Ibu negeri ialah pusat pentadbiran, bukan bandar istana.', NULL, NULL),
(630, 229, NULL, 'hint', 'Dokumen ibu negeri dan bandar diraja utara dipilih dengan teliti.', 'Tempat: Perlis, Kedah, Perak, Pulau Pinang.\nSebab: ibu negeri pusat pentadbiran; bandar diraja ada warisan.\nKesan: warisan sejarah dipelihara.', 'Betul! Dokumen utara diserahkan.'),
(631, NULL, 'e2_n2_s12', 'hint', 'Negeri yang ketuanya bergelar Raja ialah negeri paling utara semenanjung.', NULL, NULL),
(632, 230, NULL, 'hint', 'Lagu utara ditentukan melalui nota. Perlis dan \'Raja\' berkait.', 'Tempat: Perlis, Kedah, Perak, Pulau Pinang.\nSebab: lagu negeri ialah lambang kemegahan.\nKesan: tetamu dihormati dengan lagu yang betul.', 'Betul! Lagu Perlis dimainkan untuk Raja.'),
(633, NULL, 'e2_n2_s13', 'hint', 'Padankan pokok, naskhah, taring, pelangi, cahaya dan pokok pantai.', NULL, NULL),
(634, 231, NULL, 'hint', 'Hari terakhir sebelum istiadat. Pantai timur mempunyai tiga negeri dan enam cerita.', 'Tempat: Pahang, Terengganu, Kelantan.\nSebab nama: mahang, Inderapura; taring anu, terangnya ganu; kilatan, gelam hutan.\nKesan: nama lahir daripada alam dan sejarah.', 'Betul! Peta Zahar ditemui di bawah batu.'),
(635, NULL, 'e2_n2_s14', 'hint', 'Hanya satu negeri di sini mempunyai titik kuning pada peta.', NULL, NULL),
(636, 232, NULL, 'hint', 'Ibu negeri dan bandar diraja pantai timur dipadankan melalui peta.', 'Tempat: Pahang, Terengganu, Kelantan.\nSebab: ibu negeri pusat pentadbiran; Pekan bandar diraja.\nKesan: warisan dipelihara.', 'Betul! Kad dipadankan pada peta.'),
(637, NULL, 'e2_n2_s15', 'hint', 'Tajuk lagu Pahang menyebut \'Kami\', bukan \'Mahkota\' atau \'Usia\'.', NULL, NULL),
(638, 233, NULL, 'hint', 'Lagu pantai timur: satu tajuk dikongsi dua negeri, satu lagi milik Pahang.', 'Tempat: Pahang, Terengganu, Kelantan.\nSebab: lagu negeri lambang kemegahan; Terengganu dan Kelantan sama-sama \'Selamat Sultan\'.\nKesan: tajuk yang sama tidak bermaksud negeri sama.', 'Betul! Lagu Pahang berkumandang.'),
(639, NULL, 'e2_n2_s16', 'hint', 'Tahun dokumen ialah 1877. Buah itu dimakan sebagai makanan di pantai barat.', NULL, NULL),
(640, 234, NULL, 'hint', 'Sabah dan Sarawak: dua negeri, dua nama, satu tahun penting.', 'Tarikh jangkar: 1877 (dokumen Sabah).\nSebab nama: Sungai Serak, cerava (Sarawak); pisang saba (Sabah).\nKesan: nama dikaitkan dengan galian dan makanan.', 'Betul! Surat berjaya dinyahkod.'),
(641, NULL, 'e2_n2_s17', 'hint', 'Satu lagu menyebut \'Sabah\', satu menyebut \'Ibu Pertiwi\', satu menyebut \'Maju\'. Dua bandar ialah ibu negeri Borneo.', NULL, NULL),
(642, 235, NULL, 'hint', 'Borneo dan Wilayah Persekutuan: pusat pentadbiran dan lagu dipadankan malam sebelum istiadat.', 'Tempat: Sarawak, Sabah, Wilayah Persekutuan.\nSebab: ibu negeri pusat pentadbiran; lagu lambang kemegahan.\nKesan: identiti negeri dihormati.', 'Betul! Semua kad dan kaset dipadankan.'),
(643, NULL, 'e2_n2_s18', 'hint', 'Cari benda yang berkibar, benda yang tergantung di dinding dan benda yang berbunyi.', NULL, NULL),
(644, 236, NULL, 'hint', 'Hari-H. Pegawai Istiadat menunjukkan bukti lambang negeri yang betul dan mendedahkan Zahar.', 'Tempat: Pesta Warisan Negara, Wilayah Persekutuan.\nSebab: setiap negeri ada bendera, lagu dan jata sebagai identiti.\nKesan: mengenali lambang negeri menaikkan rasa cinta akan negara.', 'Berjaya! Zahar didedahkan dan majlis bermula dengan kad yang betul.'),
(645, NULL, 'e2_n3_s1', 'hint', 'Cari buah di kebun dan kertas yang ada angka tahun.', NULL, NULL),
(646, 237, NULL, 'hint', 'Pengembaraan bermula di Sabah. Cop pertama bergantung pada nama negeri.', 'Tarikh jangkar: 1877.\nSebab nama: pisang saba; dokumen \'Maharajah of Sabah\'.\nKesan: cop Sabah diperoleh.', 'Betul! Cop Sabah pertama dalam pasport.'),
(647, NULL, 'e2_n3_s2', 'hint', 'Nama sungai berubah kerana galian yang disebut sarawak.', NULL, NULL),
(648, 238, NULL, 'hint', 'Cop kedua di Sarawak. Surat berkait dengan sungai dan galian.', 'Tempat: Sarawak.\nSebab nama: Sungai Serak; cerava (antimoni).\nKesan: cop Sarawak diperoleh.', 'Betul! Cop Sarawak ditekan.'),
(649, NULL, 'e2_n3_s3', 'hint', 'Satu gelaran bermula dengan \'Yang di-Pertua\'. Dua bandar ialah ibu negeri.', NULL, NULL),
(650, 239, NULL, 'hint', 'Cop Borneo bergantung pada ibu negeri, lagu dan ketua. Pasport dipenuhi.', 'Tempat: Sarawak dan Sabah.\nSebab: ibu negeri pusat pentadbiran; lagu lambang kemegahan; ketua Yang di-Pertua Negeri.\nKesan: dua cop Borneo lengkap.', 'Betul! Dua cop Borneo lengkap.'),
(651, NULL, 'e2_n3_s4', 'hint', 'Satu nama dari lumpur, satu dari labuhan, satu dari tokoh.', NULL, NULL),
(652, 240, NULL, 'hint', 'Cop ketiga: Wilayah Persekutuan. Tiga nama, tiga kisah.', 'Tempat: Wilayah Persekutuan.\nSebab nama: lumpur, labuhan, Putra + jaya.\nKesan: cop ketiga diperoleh.', 'Betul! Pelancong mencatat penerangan yang tepat.'),
(653, NULL, 'e2_n3_s5', 'hint', 'Wilayah ini tidak dipimpin oleh Sultan atau Yang di-Pertua Negeri.', NULL, NULL),
(654, 241, NULL, 'hint', 'Cop Wilayah Persekutuan: ketua, lagu dan ibu negeri.', 'Tempat: Wilayah Persekutuan.\nSebab: ketua Yang di-Pertuan Agong; lagu Maju dan Sejahtera; tiada ibu negeri.\nKesan: cop Wilayah Persekutuan lengkap.', 'Betul! Cop Wilayah Persekutuan ditekan.'),
(655, NULL, 'e2_n3_s6', 'hint', 'Cari perkataan Arab untuk benda berkilau yang mahal.', NULL, NULL),
(656, 242, NULL, 'hint', 'Cop Johor. Dua cerita: permata dan naskhah.', 'Tempat: Johor.\nSebab nama: Jauhar (batu permata); Ujong Tanah (Sulalatus Salatin).\nKesan: cop Johor diperoleh.', 'Betul! Cop Johor ditekan.'),
(657, NULL, 'e2_n3_s7', 'hint', 'Satu bandar pusat pejabat, satu bandar istana, satu lagu bernama negeri, satu gelaran raja.', NULL, NULL),
(658, 243, NULL, 'hint', 'Pusat, istana, lagu dan ketua Johor dipadankan.', 'Tempat: Johor.\nSebab: Johor Bahru pusat pentadbiran; Bandar Maharani bandar diraja; ketua Sultan.\nKesan: cop Johor lengkap.', 'Betul! Cop Johor lengkap.'),
(659, NULL, 'e2_n3_s8', 'hint', 'Binatang kecil, putih, berani, dan menendang anjing.', NULL, NULL),
(660, 244, NULL, 'hint', 'Cop Melaka. Pengembara menyiasat nama melalui nota.', 'Tempat: Melaka.\nSebab nama: Malakat; pokok tempat Parameswara berehat.\nKesan: cop Melaka diperoleh.', 'Betul! Cop Melaka ditekan.'),
(661, NULL, 'e2_n3_s9', 'hint', 'Tajuk lagu Melaka menyebut Melaka.', NULL, NULL),
(662, 245, NULL, 'hint', 'Lagu Melaka. Ketua bergelar Yang di-Pertua Negeri.', 'Tempat: Melaka.\nSebab: ibu negeri Bandar Melaka; lagu Melaka Maju Jaya; ketua Yang di-Pertua Negeri.\nKesan: cop Melaka lengkap.', 'Betul! Lagu Melaka berkumandang.'),
(663, NULL, 'e2_n3_s10', 'hint', 'Fikirkan perkataan \'nagari\' dan tahun 1773.', NULL, NULL),
(664, 246, NULL, 'hint', 'Cop Negeri Sembilan. Nama berkait dengan angka sembilan.', 'Tarikh jangkar: 1773.\nSebab nama: sembilan luak; \'negeri\' dari \'nagari\'.\nKesan: cop Negeri Sembilan diperoleh.', 'Betul! Cop Negeri Sembilan ditekan.'),
(665, NULL, 'e2_n3_s11', 'hint', 'Lagu dan gelaran sama-sama menyebut \'Yang di-Pertuan Besar\'.', NULL, NULL),
(666, 247, NULL, 'hint', 'Pusat, istana, lagu dan gelaran ketua Negeri Sembilan.', 'Tempat: Negeri Sembilan.\nSebab: Seremban pusat pentadbiran; Seri Menanti bandar diraja; ketua Yang di-Pertuan Besar.\nKesan: cop Negeri Sembilan lengkap.', 'Betul! Cop Negeri Sembilan lengkap.'),
(667, NULL, 'e2_n3_s12', 'hint', 'Selangor ada serangga. Pahang ada pokok dan nama lama dari naskhah.', NULL, NULL),
(668, 248, NULL, 'hint', 'Dua negeri sekali gus: Selangor dan Pahang. Satu pokok dan satu serangga, satu pokok dan satu nama lama.', 'Tempat: Selangor dan Pahang.\nSebab nama: mentagau, selangur; mahang, Inderapura.\nKesan: dua cop diperoleh.', 'Betul! Dua cop ditekan.'),
(669, NULL, 'e2_n3_s13', 'hint', 'Klang dan Pekan ialah bandar diraja. Lagu Pahang menyebut \'Kami\'.', NULL, NULL),
(670, 249, NULL, 'hint', 'Selangor dan Pahang: dua ibu negeri, dua bandar diraja, dua lagu.', 'Tempat: Selangor dan Pahang.\nSebab: ibu negeri pusat pentadbiran; bandar diraja ada warisan; ketua Sultan.\nKesan: dua cop lengkap.', 'Betul! Dua cop lengkap.'),
(671, NULL, 'e2_n3_s14', 'hint', 'Cari benda di langit, benda di pantai, benda di pulau dan benda berkilau.', NULL, NULL),
(672, 250, NULL, 'hint', 'Pantai timur: dua negeri, empat petunjuk nama.', 'Tempat: Terengganu dan Kelantan.\nSebab nama: taring anu, terangnya ganu; kilatan, gelam hutan.\nKesan: nama lahir daripada alam.', 'Betul! Cop pantai timur ditekan.'),
(673, NULL, 'e2_n3_s15', 'hint', 'Dua negeri di pantai timur dan bukan Pahang.', NULL, NULL),
(674, 251, NULL, 'hint', 'Dua negeri berkongsi tajuk lagu \'Selamat Sultan\'.', 'Tempat: Terengganu dan Kelantan.\nSebab: lagu Selamat Sultan dikongsi; ibu negeri Kuala Terengganu dan Kota Bharu; ketua Sultan.\nKesan: cop pantai timur lengkap.', 'Betul! Cop pantai timur lengkap.'),
(675, NULL, 'e2_n3_s16', 'hint', 'Cari benda berkilau, benda berbuah, benda berpokok dan nama lama pulau.', NULL, NULL),
(676, 252, NULL, 'hint', 'Dua negeri: Perak dan Pulau Pinang. Lima petunjuk.', 'Tempat: Perak dan Pulau Pinang.\nSebab nama: kilatan ikan, bijih timah putih; Pulo Ka Satu, Tanjong Penaga, pinang.\nKesan: nama menunjukkan alam dan perdagangan.', 'Betul! Cop Perak dan Pulau Pinang ditekan.'),
(677, NULL, 'e2_n3_s17', 'hint', 'Perak ada Sultan; Pulau Pinang ada Yang di-Pertua Negeri.', NULL, NULL),
(678, 253, NULL, 'hint', 'Perak dan Pulau Pinang: pusat, istana, lagu dan ketua.', 'Tempat: Perak dan Pulau Pinang.\nSebab: Ipoh dan George Town ibu negeri; Kuala Kangsar bandar diraja.\nKesan: cop Perak dan Pulau Pinang lengkap.', 'Betul! Dokumen diserahkan.'),
(679, NULL, 'e2_n3_s18', 'hint', 'Satu benda untuk menangkap gajah, satu benda untuk minum, satu tulisan Tamil, satu kelapa, satu mandat.', NULL, NULL),
(680, 254, NULL, 'hint', 'Dua negeri terakhir: Kedah dan Perlis. Lima padanan.', 'Tempat: Kedah dan Perlis.\nSebab nama: kheddah, qadah, kadaram; prow-lowy, peroleh.\nKesan: dua cop diperoleh.', 'Betul! Dua cop terakhir ditekan.'),
(681, NULL, 'e2_n3_s19', 'hint', 'Tajuk lagu Kedah menyebut \'Mahkota\'.', NULL, NULL),
(682, 255, NULL, 'hint', 'Lagu Kedah dan Perlis. Ibu negeri dan bandar diraja disebut dalam Giliran Anda.', 'Tempat: Kedah dan Perlis.\nSebab: Alor Setar dan Anak Bukit; Kangar dan Arau; Sultan dan Raja.\nKesan: cop utara lengkap.', 'Betul! Lagu Kedah berkumandang.'),
(683, NULL, 'e2_n3_s20', 'hint', 'Cari benda berkibar, benda tergantung di dinding dan benda berbunyi.', NULL, NULL),
(684, 256, NULL, 'hint', 'Cop terakhir. Pengembara menunjukkan bukti lambang negeri dan menemui halaman koyak.', 'Tempat: Pesta Warisan Negara, Wilayah Persekutuan.\nSebab: setiap negeri ada bendera, lagu dan jata sebagai identiti.\nKesan: mengenali lambang negeri menaikkan rasa cinta akan negara.', 'Berjaya! Halaman koyak ditemui dan cop terakhir ditekan.');

