-- --------------------------------------------------------

--
-- Table structure for table `quest`
--

DROP TABLE IF EXISTS `quest`;
CREATE TABLE `quest` (
  `questID` bigint(20) NOT NULL,
  `sceneID` varchar(100) NOT NULL,
  `questName` varchar(255) NOT NULL,
  `instruction` text NOT NULL,
  `questType` varchar(50) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `questContent` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`questContent`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `quest`
--

INSERT INTO `quest` (`questID`, `sceneID`, `questName`, `instruction`, `questType`, `description`, `questContent`) VALUES
(1, 'e1_n1_s1', 'Tiga Fail Lama', 'Padankan setiap tokoh atau cadangan dalam fail lama dengan pasangannya.', '4', 'Memadankan Lord Brassey (1887) dan Melayu Raya (1938) dengan tokoh dan kawasan yang dicadangkan.', '{"pairs":[{"text":"Lord Brassey","pair":1},{"text":"Mencadangkan penggabungan pada 1887","pair":1},{"text":"Ibrahim Yaakob dan Harun Aminurrashid","pair":2},{"text":"Memperjuangkan Melayu Raya pada 1938","pair":2},{"text":"Cadangan Brassey, 1887","pair":3},{"text":"Sarawak, Sabah, Negeri-negeri Melayu, Negeri-negeri Selat","pair":3},{"text":"Melayu Raya, 1938","pair":4},{"text":"Tanah Melayu, Singapura, Kalimantan, Filipina, Indonesia","pair":4}],"aftermath":"Fail tersilap padan, dan Ghazali mengingatkan bahawa wartawan boleh menuduh Tunku mereka-reka sejarah.","turns":[{"after":8,"options":[{"text":"Kerana penggabungan ini dicadangkan pemimpin tempatan dan British sejak lama, bukan idea Tunku seorang.","isCorrect":true,"reaction":"Tepat. Wartawan menulis bahawa Tunku menghargai jasa pemikir lama, dan itu menambah hormat orang."},{"text":"Supaya Tunku boleh mendakwa dialah pencipta idea itu.","isCorrect":false,"reaction":"Wartawan menyoal balas dengan fail 1887, dan Tunku terpaksa menarik balik kenyataan."},{"text":"Supaya wartawan berhenti bertanya tentang Singapura.","isCorrect":false,"reaction":"Wartawan makin curiga dan mengesyaki ada perkara yang disembunyikan."}],"clue":"Idea ini bukan datang daripada satu orang sahaja."}]}'),
(2, 'e1_n1_s2', 'Susun Empat Idea', 'Susun empat idea penggabungan mengikut tahun, dari yang paling awal.', '1', 'Menyusun kronologi idea penggabungan: Brassey 1887, Melayu Raya 1938, MacDonald 1951, Tunku 1955.', '{"timelineItems":[{"id":1,"year":"1887","text":"Lord Brassey mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat","why":"Cadangan paling tua dalam fail. Pengarah syarikat British itu sudah membayangkan wilayah ini bersatu."},{"id":2,"year":"1938","text":"Ibrahim Haji Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya","why":"Selepas cadangan British, tokoh tempatan pula memperjuangkan penggabungan."},{"id":3,"year":"1951","text":"Malcolm MacDonald berbincang penggabungan dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura","why":"Pegawai British menghidupkan semula idea lama dengan berunding secara langsung."},{"id":4,"year":"1955","text":"Tunku mencadangkan Sarawak, Sabah, Singapura dan Brunei menyertai Persekutuan Tanah Melayu","why":"Idea itu akhirnya disebut oleh seorang pemimpin Persekutuan sendiri, ketika beliau Ketua Menteri."}],"aftermath":"Ucapan Parlimen mencampuradukkan tahun, dan Razak hampir menyebut Tunku sebagai pencadang 1951.","turns":[{"after":7,"options":[{"text":"Kedua-duanya, kerana idea datang daripada pemimpin tempatan dan pihak British.","isCorrect":true,"reaction":"Jawapan yang adil. Pemimpin tempatan seperti Ibrahim dan Harun berasa jasa mereka dihargai."},{"text":"Hanya pihak British, kerana mereka lebih berkuasa.","isCorrect":false,"reaction":"Razak hanya menyebut British dalam ucapan, dan pemimpin tempatan seperti Ibrahim dan Harun berasa jasa mereka dilupakan."},{"text":"Hanya Tunku, kerana Tunku Perdana Menteri.","isCorrect":false,"reaction":"Razak menulis begitu, tetapi wartawan menemui fail 1887 dan menuduh Tunku merampas jasa orang lain."}],"clue":"Fikirkan nilai menghargai jasa pemimpin."}]}'),
(3, 'e1_n1_s3', 'Bukti di Bilik Strategi', 'Cari empat bukti yang menunjukkan ancaman komunis dan pengalaman Persekutuan menghadapinya.', '2', 'Mencari bukti sebab keselamatan: ancaman komunis di Singapura dan Sarawak, pengalaman Persekutuan dan keputusan gabungan.', '{"bgImage":"../assets/gameAsset/background/bilik_strategi_keselamatan.png","hotspots":[{"name":"Peta ancaman komunis di Singapura","top":"30%","left":"38%"},{"name":"Peta ancaman komunis di Sarawak","top":"30%","left":"62%"},{"name":"Laporan pengalaman Persekutuan menghadapi komunis","top":"68.9%","left":"31.3%"},{"name":"Papan keputusan: gabungan membendung ancaman","top":"13%","left":"52%"}],"aftermath":"Tanpa bukti yang jelas, Lee menganggap Persekutuan tidak bersungguh-sungguh dan mesyuarat berjalan dingin.","turns":[{"after":7,"options":[{"text":"Ancaman komunis di Singapura dan Sarawak dapat dibendung melalui pembentukan Malaysia.","isCorrect":true,"reaction":"Lee mengangguk. Jawapan itu menenangkan dia dan mesyuarat bergerak ke hadapan."},{"text":"Askar British akan dikerahkan terus ke Singapura.","isCorrect":false,"reaction":"Lee menganggap Persekutuan tidak mahu menolong dan mesyuarat berakhir dingin."},{"text":"Singapura perlu menyelesaikan masalahnya sendiri.","isCorrect":false,"reaction":"Lee tersinggung dan mula berfikir tentang jalan lain."}],"clue":"Gabungan membantu membendung ancaman melalui pengalaman Persekutuan."}]}'),
(4, 'e1_n1_s4', 'Empat Sebab, Empat Penjelasan', 'Padankan setiap sebab pembentukan Malaysia dengan penjelasannya.', '4', 'Memadankan empat sebab: keselamatan, keseimbangan kaum, kemerdekaan dipercepat dan sosioekonomi.', '{"pairs":[{"text":"Menjamin keselamatan negara","pair":1},{"text":"Ancaman komunis di Singapura dan Sarawak dapat dibendung","pair":1},{"text":"Mencapai keseimbangan kaum","pair":2},{"text":"Bilangan penduduk antara kaum menjadi seimbang","pair":2},{"text":"Mempercepat kemerdekaan","pair":3},{"text":"Sarawak, Sabah, Singapura dan Brunei merdeka lebih cepat","pair":3},{"text":"Membangunkan sosioekonomi","pair":4},{"text":"Infrastruktur dan taraf hidup rakyat dipertingkatkan","pair":4}],"aftermath":"Padanan tersilap, dan Wong serta Sambanthan pulang tanpa bersetuju kerana hujah Tunku bercelaru.","turns":[{"after":7,"options":[{"text":"Supaya bilangan penduduk antara kaum menjadi lebih seimbang.","isCorrect":true,"reaction":"Wong dan Sambanthan mengangguk. Hujah itu menjawab kebimbangan mereka."},{"text":"Supaya jumlah penduduk Persekutuan bertambah sahaja.","isCorrect":false,"reaction":"Wong dan Sambanthan pulang tanpa bersetuju kerana hujah itu tidak menjawab soal kaum."},{"text":"Supaya Singapura tidak keseorangan.","isCorrect":false,"reaction":"Sambanthan menjawab bahawa itu bukan sebab yang menenangkan kaum-kaum."}],"clue":"Fikirkan jumlah penduduk pelbagai kaum jika hanya dua wilayah bergabung."}]}'),
(5, 'e1_n1_s5', 'Keratan Akhbar Adelphi', 'Nyahkod keratan akhbar itu dan tentukan tarikh pengumuman Tunku.', '5', 'Mengenal pasti tarikh pengumuman cadangan pembentukan Malaysia: 27 Mei 1961, Hotel Adelphi, Singapura.', '{"clueText":"Keratan akhbar: Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura. Ini langkah pertama ke arah pembentukan Malaysia, sebelum lawatan ke Sarawak dan penubuhan JSKM.","options":[{"text":"27 Mei 1961","isCorrect":true},{"text":"23 Julai 1961","isCorrect":false,"consequence":"Itu tarikh JSKM ditubuhkan, selepas pengumuman. Keratan ini ialah langkah yang pertama."},{"text":"17 Januari 1962","isCorrect":false,"consequence":"Itu tarikh Suruhanjaya Cobbold dibentuk, jauh selepas pengumuman Adelphi."},{"text":"16 September 1963","isCorrect":false,"consequence":"Itu tarikh Pemasyhuran Malaysia, kemuncak cerita ini dan bukan permulaannya."}],"aftermath":"Tarikh tersalah, dan akhbar esok menulis Tunku keliru tentang kisahnya sendiri.","turns":[{"after":6,"options":[{"text":"Belum, tetapi Tunku akan menjelaskan sendiri kepada pemimpin di Sarawak.","isCorrect":true,"reaction":"Wartawan menulis Tunku bersikap jujur. Sarawak menunggu dengan lebih terbuka."},{"text":"Sudah, kerana pemimpin Persekutuan memutuskan bagi pihak mereka.","isCorrect":false,"reaction":"Akhbar menulis tajuk Malaysia dipaksakan, dan Sarawak menjadi lebih curiga."},{"text":"Tiada komen.","isCorrect":false,"reaction":"Wartawan menulis Tunku mengelak, dan khabar angin tersebar di seberang."}],"clue":"Pengumuman bukan keputusan akhir. Rakyat Borneo mesti didengar."}]}'),
(6, 'e1_n1_s6', 'Pemimpin Sarawak dan Parti Mereka', 'Padankan setiap pemimpin Sarawak dengan partinya.', '4', 'Memadankan Jugah (PESAKA), Ningkan (SNAP) dan Abang Haji Mustapha (PANAS).', '{"pairs":[{"text":"Tun Temenggung Jugah","pair":1},{"text":"PESAKA (Parti Pesaka Anak Sarawak)","pair":1},{"text":"Stephen Kalong Ningkan","pair":2},{"text":"SNAP (Sarawak National Party)","pair":2},{"text":"Datu Bandar Abang Haji Mustapha","pair":3},{"text":"PANAS (Parti Negara Sarawak)","pair":3}],"aftermath":"Pemimpin tersalah dipadankan dengan parti, dan Jugah menganggap Tunku tidak mengenali mereka.","turns":[{"after":7,"options":[{"text":"Untuk menerangkan dan mendengar pendapat pemimpin tempatan.","isCorrect":true,"reaction":"Jugah mengangguk. Dia mula percaya Tunku mahu mendengar, bukan sekadar bercakap."},{"text":"Untuk memaklumkan keputusan yang sudah muktamad.","isCorrect":false,"reaction":"Jugah menganggap Tunku tidak jujur lalu keluar dari dewan."},{"text":"Untuk melawat rumah panjang sahaja.","isCorrect":false,"reaction":"Ningkan berkata lawatan ini terlalu besar untuk tujuan sekecil itu."}],"clue":"Tunku datang untuk menerangkan dan mendengar."}]}'),
(7, 'e1_n1_s7', 'Bukti di Bilik JSKM', 'Cari empat bukti yang menunjukkan JSKM ditubuhkan dan siapa yang terlibat.', '2', 'Mencari bukti penubuhan JSKM pada 23 Julai 1961: papan nama, pemimpin Sarawak, pemimpin Sabah dan cadangan Donald Stephens.', '{"bgImage":"../assets/gameAsset/background/bilik_jskm.png","hotspots":[{"name":"Papan nama Jawatankuasa Setia Kawan Malaysia","top":"39%","left":"72%"},{"name":"Pemimpin Sarawak (Jugah) sebagai ahli JSKM","top":"66%","left":"24%"},{"name":"Pemimpin Sabah di meja jawatankuasa","top":"60%","left":"64%"},{"name":"Dokumen cadangan Donald Stephens di atas meja","top":"58%","left":"45%"}],"aftermath":"Tanpa bukti penubuhan, Mustapha Harun mengembalikan fail dan JSKM tidak dipercayai.","turns":[{"after":7,"options":[{"text":"Malaysia dirangka melalui jawatankuasa yang mendengar pemimpin Sarawak dan Sabah.","isCorrect":true,"reaction":"Mustapha Harun mengangguk. Rakyat Sabah mula merasakan mereka turut dihitung."},{"text":"Keputusan sudah dibuat di Kuala Lumpur.","isCorrect":false,"reaction":"Mustapha mengembalikan fail dan JSKM tidak dipercayai."},{"text":"Kita tidak perlu menjawab soalan itu.","isCorrect":false,"reaction":"Mustapha menyangka Tunku mengelak dan rakyat Sabah menjadi curiga."}],"clue":"Jawatankuasa itu wujud untuk mendengar dan meyakinkan."}]}'),
(8, 'e1_n1_s8', 'Siapa dan Apa dalam Suruhanjaya', 'Padankan setiap tokoh atau peristiwa dengan peranannya dalam Suruhanjaya Cobbold.', '4', 'Memadankan Wong Pow Nee, Ghazali, Suruhanjaya Cobbold dan laporan 21 Jun 1962 dengan peranan dan dapatan.', '{"pairs":[{"text":"Tan Sri Wong Pow Nee","pair":1},{"text":"Wakil Persekutuan dalam Suruhanjaya Cobbold","pair":1},{"text":"Ghazali Shafie","pair":2},{"text":"Ahli suruhanjaya dan Ketua Setiausaha Tetap Kementerian Luar","pair":2},{"text":"Suruhanjaya Cobbold, 17 Januari 1962","pair":3},{"text":"Mendapatkan reaksi penduduk Sarawak dan Sabah","pair":3},{"text":"Laporan Cobbold, 21 Jun 1962","pair":4},{"text":"Dua pertiga penduduk menyokong pembentukan Malaysia","pair":4}],"aftermath":"Padanan tersilap, dan penduduk enggan menghadap suruhanjaya yang tujuannya tidak jelas.","turns":[{"after":7,"options":[{"text":"Mendapatkan reaksi penduduk Sarawak dan Sabah.","isCorrect":true,"reaction":"Penduduk menghantar memorandum dengan lebih berani kerana tujuannya jelas."},{"text":"Mengisytiharkan Malaysia kepada penduduk.","isCorrect":false,"reaction":"Penduduk enggan menghadap suruhanjaya dan memorandum tidak dihantar."},{"text":"Menandatangani perjanjian dengan British.","isCorrect":false,"reaction":"Wong menggeleng. Itu langkah lain yang jauh di London."}],"clue":"Suruhanjaya ini datang untuk mendengar, bukan untuk mengisytiharkan."}]}'),
(9, 'e1_n1_s9', 'Petikan Laporan Cobbold', 'Nyahkod petikan laporan itu dan tentukan siapa yang menolak.', '5', 'Memahami dapatan laporan 21 Jun 1962: dua pertiga menyokong dan SUPP menolak kerana mahu persekutuan sendiri.', '{"clueText":"Petikan laporan, 21 Jun 1962: dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia. Satu parti menolak kerana mahu membentuk persekutuan sendiri bersama Brunei dan Borneo Utara.","options":[{"text":"SUPP (Sarawak United People\'s Party)","isCorrect":true},{"text":"PESAKA, pimpinan Tun Temenggung Jugah","isCorrect":false,"consequence":"Jugah menjadi ahli JSKM, jadi parti beliau tidak menolak. Cari parti yang mahu persekutuan sendiri."},{"text":"SNAP, pimpinan Stephen Kalong Ningkan","isCorrect":false,"consequence":"Ningkan menyokong dan membentuk Perikatan Sarawak. Bukan parti ini yang menolak."},{"text":"PANAS, pimpinan Abang Haji Mustapha","isCorrect":false,"consequence":"Abang Haji Mustapha menyokong pembentukan Malaysia, jadi bukan beliau yang menolak."}],"aftermath":"Penolak tersalah dikenal pasti, dan laporan tidak dapat dijawab dengan betul.","turns":[{"after":7,"options":[{"text":"Tunjukkan dapatan laporan dan terus menerangkan matlamat Malaysia.","isCorrect":true,"reaction":"Sambanthan mengangguk. Penentang didengar tanpa menutup pintu rundingan."},{"text":"Abaikan SUPP kerana mereka minoriti.","isCorrect":false,"reaction":"SUPP mengadakan demonstrasi dan akhbar menulis Tunku mengabaikan suara rakyat."},{"text":"Batalkan pembentukan Malaysia.","isCorrect":false,"reaction":"Dua pertiga rakyat berasa dikhianati kerana pilihan majoriti diabaikan."}],"clue":"Suara majoriti dihormati, suara minoriti didengar."}]}'),
(10, 'e1_n1_s10', 'Siapa dalam JAK, Apa Tugasnya', 'Padankan JAK dengan ahli, tujuan dan tarikhnya.', '4', 'Memadankan JAK dengan ahlinya (British, Persekutuan, Sarawak, Sabah), tujuan (rangka perlembagaan) dan tarikh 30 Ogos 1962.', '{"pairs":[{"text":"Ahli JAK","pair":1},{"text":"Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah","pair":1},{"text":"Tujuan JAK","pair":2},{"text":"Menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah","pair":2},{"text":"Tarikh mesyuarat JAK","pair":3},{"text":"30 Ogos 1962","pair":3}],"aftermath":"Padanan tersilap, dan wakil Sabah serta Sarawak bimbang kepentingan mereka diabaikan.","turns":[{"after":6,"options":[{"text":"Kepentingan mereka dilindungi dalam rangka perlembagaan.","isCorrect":true,"reaction":"Abang Haji Mustapha mengangguk. Syarat Sarawak dan Sabah dicatat bertulis."},{"text":"Keputusan sudah ditetapkan.","isCorrect":false,"reaction":"Wakil Sabah dan Sarawak keluar dari bilik mesyuarat."},{"text":"Itu urusan British sahaja.","isCorrect":false,"reaction":"Donald berkata Sabah dan Sarawak bukan penonton dalam perlembagaan mereka sendiri."}],"clue":"Perlindungan mesti ditulis dalam perlembagaan."}]}'),
(11, 'e1_n1_s11', 'Dari Cobbold ke Referendum', 'Susun empat langkah ini mengikut tarikh, dari yang paling awal.', '1', 'Menyusun kronologi: Cobbold dibentuk, laporan Cobbold, JAK dan referendum Singapura.', '{"timelineItems":[{"id":1,"year":"17 Januari 1962","text":"Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk Sarawak dan Sabah","why":"Mulakan dengan langkah yang bertanya kepada rakyat Sarawak dan Sabah."},{"id":2,"year":"21 Jun 1962","text":"Cobbold menyerahkan laporan: dua pertiga penduduk menyokong","why":"Selepas bertanya, suruhanjaya menyerahkan dapatan kepada British dan Persekutuan."},{"id":3,"year":"30 Ogos 1962","text":"JAK bermesyuarat untuk menyediakan rangka perlembagaan","why":"Dapatan laporan memerlukan perlindungan bertulis, maka JAK bersidang."},{"id":4,"year":"1 September 1962","text":"Referendum di Singapura: rakyat bersetuju dengan pembentukan Malaysia","why":"Dua hari selepas JAK, rakyat Singapura pula memberi jawapan melalui undi."}],"aftermath":"Susunan tersilap, dan Lee tidak dapat membuktikan Singapura memberi persetujuan selepas langkah yang betul.","turns":[{"after":7,"options":[{"text":"Sarawak dan Sabah disahkan melalui Suruhanjaya Cobbold, dan Singapura melalui referendum.","isCorrect":true,"reaction":"Lee mengangguk. Dua jalan yang berbeza untuk dua pihak, dan kedua-duanya sah."},{"text":"Tiada siapa perlu diundi.","isCorrect":false,"reaction":"Lee menarik balik sokongan buat sementara kerana rakyat tidak diberi suara."},{"text":"Sarawak dan Sabah akan mengundi minggu depan.","isCorrect":false,"reaction":"Ghazali membetulkan: referendum hanya di Singapura, dan akhbar menyiarkan kenyataan yang salah."}],"clue":"Setiap pihak diminta pendapatnya melalui cara yang sesuai."}]}'),
(12, 'e1_n1_s12', 'Bukti di Marlborough House', 'Cari empat bukti yang menunjukkan Perjanjian Malaysia ditandatangani di sini.', '2', 'Mencari bukti penandatanganan Perjanjian Malaysia: meja perjanjian, dua pen bulu penandatangan Sarawak dan dokumen perjanjian.', '{"bgImage":"../assets/gameAsset/background/marlborough_house.png","hotspots":[{"name":"Meja perjanjian beralas baldu merah","top":"52%","left":"33%"},{"name":"Pen bulu Tun Temenggung Jugah","top":"38%","left":"22%"},{"name":"Pen bulu Datu Bandar Abang Haji Mustapha","top":"40%","left":"38%"},{"name":"Dokumen Perjanjian Malaysia, 9 Julai 1963","top":"53%","left":"31%"}],"aftermath":"Tanpa bukti penandatanganan, Indonesia dan Filipina mendakwa perjanjian itu tidak sah.","turns":[{"after":7,"options":[{"text":"Ya, melalui cara yang adil supaya persetujuan rakyat Sarawak dan Sabah disahkan.","isCorrect":true,"reaction":"Abang Haji Mustapha lega. Cara adil itu akan menutup mulut pengkritik."},{"text":"Tidak, perjanjian sudah ditandatangani.","isCorrect":false,"reaction":"Indonesia dan Filipina bertambah marah dan ketegangan melebar."},{"text":"Ya, dengan mengancam mereka.","isCorrect":false,"reaction":"Ketegangan meluas kerana ancaman tidak pernah mententeramkan sesiapa."}],"clue":"Persetujuan rakyat mesti disahkan dengan adil."}]}'),
(13, 'e1_n1_s13', 'Petikan Misi UNMM', 'Nyahkod petikan itu dan tentukan siapa yang persetujuannya disahkan.', '5', 'Memahami tujuan UNMM, tarikh penubuhannya dan pihak yang persetujuannya disahkan.', '{"clueText":"Petikan misi, 12 Ogos 1963: PBB mewujudkan misi ini untuk mengesahkan persetujuan. Pegawai misi bertemu penduduk Borneo bagi memastikan mereka benar-benar bersetuju dengan pembentukan Malaysia.","options":[{"text":"Penduduk Sarawak dan Sabah","isCorrect":true},{"text":"Penduduk Singapura","isCorrect":false,"consequence":"Rakyat Singapura sudah menjawab melalui referendum 1 September 1962, bukan UNMM."},{"text":"Pemimpin British","isCorrect":false,"consequence":"UNMM tidak mengesahkan pendapat pemimpin British. Ia bertemu penduduk Borneo."},{"text":"Semua rakyat Persekutuan Tanah Melayu","isCorrect":false,"consequence":"Persetujuan yang disahkan ialah persetujuan penduduk Sarawak dan Sabah."}],"aftermath":"Sasaran UNMM tersalah, dan orang ramai menyangka ada sesuatu yang disembunyikan.","turns":[{"after":7,"options":[{"text":"Kerana UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah.","isCorrect":true,"reaction":"Donald lega. Dengan pengesahan PBB, tiada siapa dapat meragui persetujuan mereka."},{"text":"Kita menolak UNMM kerana Cobbold sudah mencukupi.","isCorrect":false,"reaction":"Orang ramai menyangka ada sesuatu yang disembunyikan, dan keraguan bertambah."},{"text":"Kita menerima UNMM supaya Indonesia berhenti marah.","isCorrect":false,"reaction":"Donald berkata tujuan UNMM bukan untuk menyenangkan jiran, tetapi untuk mengesahkan persetujuan rakyat."}],"clue":"UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah."}]}'),
(14, 'e1_n1_s14', 'Petikan Dokumen Pemasyhuran', 'Nyahkod petikan dokumen dan tentukan perkara yang dimasyhurkan.', '5', 'Memahami dokumen Pemasyhuran: yang menandatangani, tarikh, negeri terlibat dan nilai yang dijanjikan.', '{"clueText":"Petikan dokumen: Tunku Abdul Rahman Putra Al-Haj, Perdana Menteri, memasyhurkan bahawa mulai 16 September 1963, negeri-negeri Persekutuan Tanah Melayu bersama Singapura, Sabah dan Sarawak akan kekal menjadi sebuah negara demokrasi yang merdeka lagi berdaulat.","options":[{"text":"Pemasyhuran Malaysia","isCorrect":true},{"text":"Perjanjian Malaysia","isCorrect":false,"consequence":"Perjanjian ditandatangani di London pada 9 Julai 1963. Dokumen ini ialah Pemasyhuran."},{"text":"Laporan Suruhanjaya Cobbold","isCorrect":false,"consequence":"Laporan itu pada 21 Jun 1962. Dokumen ini memasyhurkan Malaysia."},{"text":"Keputusan referendum Singapura","isCorrect":false,"consequence":"Referendum diadakan 1 September 1962. Dokumen ini ialah Pemasyhuran."}],"aftermath":"Dokumen tersalah dikenal pasti, dan Hari Malaysia hilang maknanya dalam kalendar sekolah.","turns":[{"after":7,"options":[{"text":"Malaysia dimasyhurkan dengan kebebasan dan keadilan pada 16 September 1963.","isCorrect":true,"reaction":"Razak mengangguk. Tarikh itu diingati sebagai Hari Malaysia."},{"text":"Tarikh itu hanya perayaan biasa.","isCorrect":false,"reaction":"Hari Malaysia dilupakan dalam kalendar sekolah."},{"text":"Tarikh itu Singapura berpisah dengan Malaysia.","isCorrect":false,"reaction":"Razak membetulkan: itu berlaku pada 1965, bukan 1963."}],"clue":"Malaysia dimasyhurkan pada 16 September 1963."}]}'),
(15, 'e1_n1_s15', 'Kad Negeri di Dewan', 'Padankan setiap negeri atau wilayah dengan keterangan yang betul.', '4', 'Memadankan Persekutuan Tanah Melayu (11 negeri), Singapura, Sabah, Sarawak, Brunei dan Malaysia 1963.', '{"pairs":[{"text":"Persekutuan Tanah Melayu","pair":1},{"text":"Sebelas negeri termasuk Pahang dan Melaka","pair":1},{"text":"Singapura","pair":2},{"text":"Bergabung pada 16 September 1963","pair":2},{"text":"Sabah","pair":3},{"text":"Disebut Borneo Utara dalam perjanjian 1963","pair":3},{"text":"Sarawak","pair":4},{"text":"Dilawat Tunku pada Julai 1961","pair":4},{"text":"Brunei","pair":5},{"text":"Menolak penyertaan dalam Malaysia","pair":5},{"text":"Malaysia 1963","pair":6},{"text":"Empat belas negeri pada tarikh Pemasyhuran","pair":6}],"aftermath":"Kad tersilap padan, dan guru membetulkan murid di hadapan kelas.","turns":[{"after":6,"options":[{"text":"Kerana Singapura bergabung dengan Malaysia pada 16 September 1963.","isCorrect":true,"reaction":"Murid mengangguk dan mengira bilangan negeri dengan betul."},{"text":"Kerana Singapura sentiasa sebahagian Persekutuan.","isCorrect":false,"reaction":"Murid mengira salah dan guru membetulkan di hadapan kelas."},{"text":"Kerana Singapura menggantikan Brunei.","isCorrect":false,"reaction":"Ghazali membetulkan: Brunei menolak, dan Singapura bergabung atas persetujuan sendiri."}],"clue":"Singapura bergabung pada 1963 dan berpisah pada 1965."}]}'),
(16, 'e1_n1_s16', 'Cabaran dan Pihaknya', 'Padankan setiap cabaran dengan pihak yang menimbulkannya.', '4', 'Memadankan cabaran: SUPP menolak, Indonesia konfrontasi 1963 hingga 1966, Filipina mendakwa Sabah dan Singapura berpisah 1965.', '{"pairs":[{"text":"SUPP","pair":1},{"text":"Menolak kerana mahu persekutuan sendiri","pair":1},{"text":"Indonesia","pair":2},{"text":"Konfrontasi terhadap Malaysia, 1963 hingga 1966","pair":2},{"text":"Filipina","pair":3},{"text":"Mendakwa Sabah sebahagian daripada wilayahnya","pair":3},{"text":"Singapura","pair":4},{"text":"Berpisah daripada Malaysia pada 1965","pair":4}],"aftermath":"Padanan tersilap, dan setiap pihak menuduh pihak lain.","turns":[{"after":7,"options":[{"text":"Melalui permuafakatan pemimpin dan kerjasama demi kemakmuran serantau.","isCorrect":true,"reaction":"Razak mengangguk. Carik-carik bulu ayam, akhirnya bercantum juga."},{"text":"Melalui paksaan.","isCorrect":false,"reaction":"Ketegangan berpanjangan dan rakyat menanggung akibatnya."},{"text":"Dengan memutuskan semua hubungan.","isCorrect":false,"reaction":"Kerjasama serantau terhenti dan kemakmuran terjejas."}],"clue":"Permuafakatan memulihkan hubungan yang tegang."}]}'),
(17, 'e1_n1_s17', 'Rekod Lengkap untuk Arkib', 'Susun lapan langkah dari Adelphi hingga Pemasyhuran mengikut tarikh.', '1', 'Menyusun kronologi lapan langkah pembentukan Malaysia dari 27 Mei 1961 hingga 16 September 1963.', '{"timelineItems":[{"id":1,"year":"27 Mei 1961","text":"Tunku mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura","why":"Langkah pertama: cadangan diumumkan kepada umum."},{"id":2,"year":"Julai 1961","text":"Tunku melawat Sarawak untuk menerangkan idea Malaysia","why":"Selepas pengumuman, Tunku menerangkan sendiri kepada pemimpin tempatan."},{"id":3,"year":"23 Julai 1961","text":"JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah","why":"Pemimpin yang ragu memerlukan satu jawatankuasa bersama."},{"id":4,"year":"17 Januari 1962","text":"Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk","why":"Pemimpin sudah diyakinkan, kini rakyat pula perlu ditanya."},{"id":5,"year":"21 Jun 1962","text":"Suruhanjaya Cobbold menyerahkan laporan: dua pertiga menyokong","why":"Dapatan daripada rakyat dihantar kepada British dan Persekutuan."},{"id":6,"year":"9 Julai 1963","text":"Perjanjian Malaysia ditandatangani di Marlborough House, London","why":"Selepas dapatan dan perlembagaan, perjanjian pun ditandatangani."},{"id":7,"year":"12 Ogos 1963","text":"UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah","why":"Persetujuan rakyat Borneo disahkan oleh PBB selepas perjanjian."},{"id":8,"year":"16 September 1963","text":"Pemasyhuran Malaysia di empat tempat","why":"Setelah semua disahkan, Malaysia dimasyhurkan."}],"aftermath":"Langkah bercampur, dan arkib negara mencatat sejarah yang tersilap.","turns":[{"after":6,"options":[{"text":"Tanpa kesungguhan, permuafakatan dan keprihatinan semua pihak, Malaysia tidak akan terbentuk.","isCorrect":true,"reaction":"Razak mengangguk. Cerita Malaysia ialah cerita semua orang, bukan seorang pemimpin."},{"text":"Kerana hanya pemimpin menentukan segalanya.","isCorrect":false,"reaction":"Cerita Malaysia kehilangan suara rakyat Sarawak, Sabah dan Singapura."},{"text":"Kerana ia menjadikan perundingan lebih cepat.","isCorrect":false,"reaction":"Razak berkata kelajuan bukan tujuan. Kesepakatan yang adil ialah tujuan."}],"clue":"Muafakat membawa berkat."}]}'),
(18, 'e1_n2_s1', 'Fail Lord Brassey', 'Nyahkod fail lama itu dan tentukan wilayah yang disebut Brassey selain Sarawak, Sabah dan Negeri-negeri Melayu.', '5', 'Memahami cadangan Lord Brassey 1887: menggabungkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat.', '{"clueText":"Fail lama, 1887, tulisan Lord Brassey, Pengarah British North Borneo Company: dia mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan sekumpulan negeri di Selat Melaka.","options":[{"text":"Negeri-negeri Selat","isCorrect":true},{"text":"Brunei dan Filipina","isCorrect":false,"consequence":"Itu bukan cadangan Brassey. Filipina muncul dalam konsep Melayu Raya 1938."},{"text":"Kepulauan Indonesia","isCorrect":false,"consequence":"Indonesia juga hanya muncul dalam Melayu Raya 1938, bukan fail ini."},{"text":"Hong Kong","isCorrect":false,"consequence":"Tiada kaitan dengan fail ini. Brassey bercakap tentang Borneo dan Tanah Melayu."}],"aftermath":"Fail tidak dapat dibaca, dan Mustapha Harun menyimpulkan idea ini rancangan British semata-mata.","turns":[{"after":7,"options":[{"text":"Idea ini sudah disebut British sejak 1887, tetapi orang tempatan juga akan menyebutnya.","isCorrect":true,"reaction":"Penduduk tenang. Mereka sedar idea ini tidak muncul dalam satu malam."},{"text":"Ini idea baharu Tunku.","isCorrect":false,"reaction":"Mustapha menunjuk tarikh 1887 pada fail dan penduduk ketawa kecil."},{"text":"Ini hanya rancangan British.","isCorrect":false,"reaction":"Mustapha mengingatkan masih ada fail lain yang menyebut tokoh tempatan."}],"clue":"Satu fail tidak cukup. Cari tokoh tempatan dalam fail lain."}]}'),
(19, 'e1_n2_s2', 'Empat Tahun, Empat Idea', 'Padankan setiap tahun dengan tokoh dan idea yang betul.', '4', 'Memadankan 1887 (Brassey), 1938 (Melayu Raya), 1951 (MacDonald) dan 1955 (Tunku).', '{"pairs":[{"text":"1887","pair":1},{"text":"Lord Brassey: Sarawak, Sabah, Negeri-negeri Melayu, Negeri-negeri Selat","pair":1},{"text":"1938","pair":2},{"text":"Ibrahim Yaakob dan Harun Aminurrashid: Melayu Raya","pair":2},{"text":"1951","pair":3},{"text":"Malcolm MacDonald: berbincang dengan pemimpin empat wilayah","pair":3},{"text":"1955","pair":4},{"text":"Tunku: empat wilayah menyertai Persekutuan Tanah Melayu","pair":4}],"aftermath":"Padanan tersilap, dan Mustapha menyebut Melayu Raya bukan cadangan Tunku. Tunku hanya menyebut empat wilayah.","turns":[{"after":7,"options":[{"text":"Setiap idea datang daripada pihak berbeza: syarikat dan pegawai dahulu, kemudian pemimpin tempatan.","isCorrect":true,"reaction":"Pemuda UNKO mengangguk. Dia sedar idea ini dibina secara berperingkat."},{"text":"Tiada siapa mahu menerimanya.","isCorrect":false,"reaction":"Pemuda menunjuk empat nama di atas meja yang membuktikan sebaliknya."},{"text":"Orang Borneo tidak bersetuju.","isCorrect":false,"reaction":"Mustapha berkata belum ada soal selidik rakyat sehingga Suruhanjaya Cobbold."}],"clue":"Tiap idea datang daripada pihak berbeza."}]}'),
(20, 'e1_n2_s3', 'Bukti Keselamatan di Atas Meja', 'Cari tiga bukti yang menunjukkan ancaman komunis dan pengalaman Persekutuan.', '2', 'Mencari bukti sebab keselamatan: ancaman komunis di Singapura, di Sarawak dan pengalaman Persekutuan Tanah Melayu.', '{"bgImage":"../assets/gameAsset/background/bilik_strategi_keselamatan.png","hotspots":[{"name":"Laporan ancaman komunis di Singapura","top":"68.9%","left":"31.3%"},{"name":"Laporan ancaman komunis di Sarawak","top":"80.5%","left":"20.6%"},{"name":"Nota pengalaman Persekutuan menghadapi komunis","top":"72%","left":"56.1%"}],"aftermath":"Tanpa bukti, Razak menganggap hujah Donald lemah dan penduduk kampung kekal bimbang.","turns":[{"after":7,"options":[{"text":"Tujuannya membendung ancaman komunis kerana Tanah Melayu sudah berpengalaman.","isCorrect":true,"reaction":"Razak mengangguk. Tua kampung itu lega kerana jawapan itu jelas."},{"text":"Tiada ancaman langsung.","isCorrect":false,"reaction":"Razak membuka laporan Singapura dan Sarawak lalu menunjuk bahawa ancaman itu nyata."},{"text":"Tentera British akan menjaga kita.","isCorrect":false,"reaction":"Razak berkata itu bukan alasan yang disebut dalam rancangan ini."}],"clue":"Gabungan dapat membendung ancaman."}]}'),
(21, 'e1_n2_s4', 'Risalah Empat Sebab', 'Bantu Mustapha Harun memberi risalah yang betul kepada penduduk kampung.', '3', 'Membantu NPC memilih risalah yang menyenaraikan empat sebab pembentukan Malaysia yang betul.', '{"npcName":"Datu Mustapha","prompt":"Penduduk kampung bertanya mengapa Sabah patut menyertai. Aku perlukan risalah yang menyenaraikan keempat-empat sebab pembentukan Malaysia.","options":[{"text":"Keselamatan, keseimbangan kaum, kemerdekaan cepat, sosioekonomi","item":"dokumen","isCorrect":true},{"text":"Keselamatan, keseimbangan kaum, kemerdekaan cepat, tambah tentera British","item":"dokumen","isCorrect":false,"consequence":"Orang kampung membantah: kami bukan mahu tentera tambahan. Sebab keempat ialah sosioekonomi."},{"text":"Keselamatan dan ekonomi sahaja, tanpa soal kaum dan kemerdekaan","item":"dokumen","isCorrect":false,"consequence":"Seorang tua bertanya tentang kaum kita. Risalah itu terlepas dua sebab."},{"text":"Hanya keseimbangan kaum, kerana Singapura sahaja sudah cukup","item":"dokumen","isCorrect":false,"consequence":"Mustapha menggeleng. Risalah ini tinggal satu sebab dan alasannya salah."}],"aftermath":"Risalah yang salah diedarkan, dan orang kampung mula bertanya adakah pemimpin mereka memahami rancangan ini.","turns":[{"after":7,"options":[{"text":"Dua wilayah itu sahaja tidak seimbang kaumnya. Dengan Sarawak, Sabah dan Brunei, penduduknya seimbang.","isCorrect":true,"reaction":"Orang tua mengangguk. Jawapan itu mudah difahami oleh semua kaum."},{"text":"Singapura terlalu kecil.","isCorrect":false,"reaction":"Orang tua berkata itu bukan hujah dalam rancangan ini."},{"text":"British yang menyuruh.","isCorrect":false,"reaction":"Dewan menjadi riuh dan Mustapha terpaksa meredakan keadaan."}],"clue":"Fikirkan bilangan penduduk antara kaum."}]}'),
(22, 'e1_n2_s5', 'Tajuk Utama Adelphi', 'Nyahkod keratan akhbar dan tentukan tarikh pengumuman Tunku.', '5', 'Mengenal pasti tarikh pengumuman cadangan pembentukan Malaysia: 27 Mei 1961.', '{"clueText":"Keratan akhbar: Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia di Hotel Adelphi, Singapura. Ini berlaku sebelum JSKM, sebelum Suruhanjaya Cobbold dan sebelum Perjanjian Malaysia.","options":[{"text":"27 Mei 1961","isCorrect":true},{"text":"23 Julai 1961","isCorrect":false,"consequence":"Itu tarikh JSKM ditubuhkan, selepas pengumuman."},{"text":"17 Januari 1962","isCorrect":false,"consequence":"Itu tarikh Suruhanjaya Cobbold dibentuk, lebih lewat lagi."},{"text":"16 September 1963","isCorrect":false,"consequence":"Itu tarikh Pemasyhuran Malaysia, kemuncak cerita ini."}],"aftermath":"Tarikh tersalah, dan akhbar esok menulis bahawa pemimpin Sabah keliru tentang kisahnya sendiri.","turns":[{"after":7,"options":[{"text":"Tunku akan menerangkan kepada pemimpin Sarawak dan Sabah, kemudian jawatankuasa dan suruhanjaya meneliti.","isCorrect":true,"reaction":"Wartawan mencatat dan menulis laporan yang adil tentang langkah-langkah itu."},{"text":"Malaysia dimasyhurkan minggu depan.","isCorrect":false,"reaction":"Wartawan menyemak buku notanya dan menggeleng. Banyak langkah perlu dilalui dahulu."},{"text":"Tiada langkah, ini cuma idea.","isCorrect":false,"reaction":"Mustapha mengingatkan bahawa Tunku sudah mengumumkannya secara terbuka."}],"clue":"Pengumuman membawa langkah seterusnya."}]}'),
(23, 'e1_n2_s6', 'Bukti Lawatan di Tebing Sungai', 'Cari tiga bukti yang menunjukkan tujuan lawatan Tunku ke Sarawak.', '2', 'Mencari bukti lawatan Tunku ke Sarawak pada Julai 1961: menerangkan, mendengar dan menjawab soalan.', '{"bgImage":"../assets/gameAsset/background/lawatan_ke_sarawak.png","hotspots":[{"name":"Pemimpin mendengar Tunku menerangkan idea Malaysia","top":"61%","left":"50%"},{"name":"Penduduk berkumpul untuk bertanya tentang Sarawak","top":"80%","left":"30%"},{"name":"Bot dan bendera di tebing, tanda lawatan Julai 1961","top":"57%","left":"71%"}],"aftermath":"Bukti tidak ditemui, dan Ningkan menyindir bahawa pemimpin patut memerhati perbincangan, bukan perabot.","turns":[{"after":7,"options":[{"text":"Satu jawatankuasa bersama pemimpin Sabah dan Sarawak untuk meyakinkan rakyat.","isCorrect":true,"reaction":"Abang Haji Mustapha mengangguk. Cadangan itu menjawab kebimbangan Sarawak."},{"text":"Tunggu keputusan British.","isCorrect":false,"reaction":"Jugah mengerutkan dahi kerana pemimpin tempatan mahu didengar."},{"text":"Setiap wilayah putuskan sendiri.","isCorrect":false,"reaction":"Ningkan berkata kita perlukan permuafakatan, bukan perpecahan."}],"clue":"Jawatankuasa bersama membawa suara dua wilayah."}]}'),
(24, 'e1_n2_s7', 'Tokoh dan Parti di Meja JSKM', 'Padankan setiap tokoh dengan partinya.', '4', 'Memadankan Donald (UNKO), Jugah (PESAKA), Mustapha Harun (USNO), Ningkan (SNAP), Abang Haji Mustapha (PANAS) dan Tunku (UMNO).', '{"pairs":[{"text":"Donald Stephens","pair":1},{"text":"UNKO (United National Kadazan Organization)","pair":1},{"text":"Tun Temenggung Jugah","pair":2},{"text":"PESAKA (Parti Pesaka Anak Sarawak)","pair":2},{"text":"Datu Mustapha Datu Harun","pair":3},{"text":"USNO (United Sabah National Organisation)","pair":3},{"text":"Stephen Kalong Ningkan","pair":4},{"text":"SNAP (Sarawak National Party)","pair":4},{"text":"Datu Bandar Abang Haji Mustapha","pair":5},{"text":"PANAS (Parti Negara Sarawak)","pair":5},{"text":"Tunku Abdul Rahman","pair":6},{"text":"UMNO (United Malays National Organisation)","pair":6}],"aftermath":"Pemimpin tersalah dipadankan, dan Abang Haji Mustapha menegur bahawa dia dari PANAS dan Jugah dari PESAKA.","turns":[{"after":7,"options":[{"text":"Untuk meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.","isCorrect":true,"reaction":"Wartawan menulis jawapan itu dengan jelas dan JSKM dihormati."},{"text":"Untuk menyerahkan laporan kepada British.","isCorrect":false,"reaction":"Wartawan berkata itu tugas Cobbold, nanti."},{"text":"Untuk menandatangani perjanjian.","isCorrect":false,"reaction":"Tunku mengingatkan perjanjian itu di London, tahun depan."}],"clue":"Tujuan JSKM ialah meyakinkan pemimpin."}]}'),
(25, 'e1_n2_s8', 'Surat yang Dicari Wong Pow Nee', 'Bantu Wong Pow Nee memilih surat yang betul untuk suruhanjaya.', '3', 'Membantu NPC memilih memorandum penduduk, bukan laporan atau perjanjian yang belum wujud.', '{"npcName":"Wong Pow Nee","prompt":"Saya mencari surat yang mencatat pendirian penduduk Sabah tentang Malaysia. Surat mana yang patut saya baca?","options":[{"text":"Memorandum penduduk tentang pembentukan Malaysia","item":"surat","isCorrect":true},{"text":"Laporan Cobbold kepada British dan Tanah Melayu","item":"surat","isCorrect":false,"consequence":"Laporan itu belum wujud. Ia ditulis selepas Cobbold selesai bertanya."},{"text":"Perjanjian Malaysia yang ditandatangani di London","item":"surat","isCorrect":false,"consequence":"Perjanjian ini 9 Julai 1963, jauh selepas suruhanjaya."},{"text":"Surat jemputan majlis kampung","item":"surat","isCorrect":false,"consequence":"Wong menggeleng. Surat ini tiada kaitan dengan pendirian penduduk."}],"aftermath":"Surat yang salah dipilih, dan suruhanjaya terlepas pandang suara penduduk.","turns":[{"after":7,"options":[{"text":"Terangkan bahawa suruhanjaya ini datang untuk mendengar, dan memorandum juga diterima.","isCorrect":true,"reaction":"Ghazali mengangguk. Penduduk berani menyuarakan pandangan mereka."},{"text":"Suruh mereka diam.","isCorrect":false,"reaction":"Ghazali menggeleng. Suruhanjaya tidak dapat mengetahui pendirian mereka."},{"text":"Jawab bagi pihak mereka.","isCorrect":false,"reaction":"Wong berkata suruhanjaya perlu mendengar sendiri daripada penduduk."}],"clue":"Penduduk perlu diberi ruang untuk bersuara."}]}'),
(26, 'e1_n2_s9', 'Dari Adelphi ke Laporan', 'Susun lima langkah mengikut tarikh, dari yang paling awal.', '1', 'Menyusun kronologi: pengumuman Adelphi, lawatan Sarawak, JSKM, Cobbold dibentuk dan laporan Cobbold.', '{"timelineItems":[{"id":1,"year":"27 Mei 1961","text":"Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura","why":"Langkah pertama yang membuka seluruh cerita."},{"id":2,"year":"Julai 1961","text":"Tunku melawat Sarawak untuk menerangkan idea Malaysia","why":"Selepas mengumumkan, Tunku menerangkan sendiri kepada pemimpin Sarawak."},{"id":3,"year":"23 Julai 1961","text":"JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah","why":"Pemimpin yang ragu memerlukan jawatankuasa bersama."},{"id":4,"year":"17 Januari 1962","text":"Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk","why":"Selepas pemimpin diyakinkan, rakyat pula ditanya."},{"id":5,"year":"21 Jun 1962","text":"Cobbold menyerahkan laporan: dua pertiga menyokong","why":"Dapatan daripada rakyat dikumpulkan dan diserahkan."}],"aftermath":"Langkah tersusun terbalik, dan Mustapha menyebut bagaimana kita boleh bertanya sebelum meyakinkan.","turns":[{"after":6,"options":[{"text":"Dua pertiga menyokong, dan kami akan terus berunding untuk menjawab kebimbangan kamu.","isCorrect":true,"reaction":"Wakil SUPP diam, kemudian mengangguk perlahan kerana pintu rundingan belum ditutup."},{"text":"Kamu terlalu kecil untuk dihiraukan.","isCorrect":false,"reaction":"Ningkan menegur keras. Suara kecil pun suara."},{"text":"Setuju dengan SUPP.","isCorrect":false,"reaction":"Mustapha berkata itu bukan keputusan laporan, dan dua pertiga rakyat akan tersinggung."}],"clue":"Dua pertiga menyokong, tetapi bantahan perlu dijawab."}]}'),
(27, 'e1_n2_s10', 'Dokumen Mesyuarat 30 Ogos 1962', 'Nyahkod dokumen dan tentukan badan yang dimaksudkan.', '5', 'Mengenal pasti JAK: wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah menyediakan rangka perlembagaan.', '{"clueText":"Dokumen mesyuarat, 30 Ogos 1962: wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk bersama untuk menyediakan rangka perlembagaan yang melindungi kepentingan Sarawak dan Sabah.","options":[{"text":"Jawatankuasa Antara Kerajaan (JAK)","isCorrect":true},{"text":"Jawatankuasa Setia Kawan Malaysia (JSKM)","isCorrect":false,"consequence":"JSKM meyakinkan pemimpin Sarawak dan Sabah, ditubuhkan 23 Julai 1961."},{"text":"Suruhanjaya Cobbold","isCorrect":false,"consequence":"Cobbold mendapatkan reaksi penduduk, bukan menyediakan perlembagaan."},{"text":"United Nations Malaysia Mission (UNMM)","isCorrect":false,"consequence":"UNMM mengesahkan persetujuan penduduk, pada 12 Ogos 1963."}],"aftermath":"Badan tersilap dikenal pasti, dan Ningkan mempersoalkan siapa yang menulis perlindungan itu.","turns":[{"after":6,"options":[{"text":"Cobbold hanya mengumpul pendapat. JAK menulis perlindungan dalam perlembagaan.","isCorrect":true,"reaction":"Ningkan mengangguk. Dua badan berbeza, dua tugas berbeza."},{"text":"JAK menggantikan Cobbold.","isCorrect":false,"reaction":"Razak membetulkan kerana tugas kedua-dua badan berbeza."},{"text":"JAK mengundi.","isCorrect":false,"reaction":"Ningkan menyebut itu referendum, dan referendum hanya di Singapura."}],"clue":"Yakinkan, tanya, tulis perlindungan."}]}'),
(28, 'e1_n2_s11', 'Dokumen Keputusan Referendum', 'Bantu Lee Kuan Yew mencari dokumen keputusan referendum yang betul.', '3', 'Membantu NPC memilih dokumen keputusan referendum Singapura, 1 September 1962.', '{"npcName":"Lee Kuan Yew","prompt":"Dokumen keputusan referendum Singapura hilang di antara timbunan ini. Yang mana satu dokumen yang betul?","options":[{"text":"Keputusan referendum: rakyat Singapura bersetuju","item":"dokumen","isCorrect":true},{"text":"Laporan Cobbold: dua pertiga penduduk Sarawak dan Sabah menyokong","item":"dokumen","isCorrect":false,"consequence":"Dokumen ini tentang Sarawak dan Sabah, bukan Singapura."},{"text":"Perjanjian Malaysia yang ditandatangani di London","item":"dokumen","isCorrect":false,"consequence":"Perjanjian itu belum wujud. Ia 9 Julai 1963."},{"text":"Laporan UNMM tentang persetujuan penduduk Sarawak dan Sabah","item":"dokumen","isCorrect":false,"consequence":"UNMM ditubuhkan Ogos 1963, setahun lebih lewat."}],"aftermath":"Dokumen yang salah dipilih, dan Lee berasa rakyat Singapura tidak diberi perhatian.","turns":[{"after":7,"options":[{"text":"Tidak dengan cara yang sama. Sarawak dan Sabah akan disahkan oleh pasukan Bangsa-Bangsa Bersatu.","isCorrect":true,"reaction":"Lee mengangguk. Setiap pihak diminta pendapat dengan cara yang sesuai."},{"text":"Sabah akan mengundi minggu depan.","isCorrect":false,"reaction":"Razak menggeleng. Referendum hanya di Singapura."},{"text":"Sabah tidak perlu disahkan.","isCorrect":false,"reaction":"Lee berkata ini tidak dipersetujui. Persetujuan Sabah mesti disahkan."}],"clue":"Referendum untuk Singapura, UNMM untuk Sarawak dan Sabah."}]}'),
(29, 'e1_n2_s12', 'Telegram yang Betul', 'Bantu Mustapha Harun memilih telegram tentang Perjanjian Malaysia.', '3', 'Membantu NPC memilih telegram yang betul: Perjanjian Malaysia, Marlborough House, London, 9 Julai 1963.', '{"npcName":"Datu Mustapha","prompt":"Tiga telegram sampai serentak. Yang mana telegram yang betul tentang Perjanjian Malaysia?","options":[{"text":"Perjanjian Malaysia ditandatangani di Marlborough House, London, 9 Julai 1963","item":"telegram","isCorrect":true},{"text":"Cadangan Malaysia diumumkan di Hotel Adelphi, Singapura, 27 Mei 1961","item":"telegram","isCorrect":false,"consequence":"Itu pengumuman Tunku dua tahun lebih awal. Bukan perjanjian."},{"text":"Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi, 17 Januari 1962","item":"telegram","isCorrect":false,"consequence":"Itu langkah awal. Perjanjian datang selepas laporan dan rundingan."},{"text":"Pemasyhuran Malaysia diadakan di Kuala Lumpur, 16 September 1963","item":"telegram","isCorrect":false,"consequence":"Itu pemasyhuran, bukan perjanjian. Ia belum berlaku lagi."}],"aftermath":"Telegram yang salah dibaca, dan orang ramai mengingat tarikh yang tersilap.","turns":[{"after":7,"options":[{"text":"Antaranya Tun Temenggung Jugah dan Datu Bandar Abang Haji Mustapha.","isCorrect":true,"reaction":"Pelajar mencatat nama itu dalam bukunya dengan senyum."},{"text":"Hanya Tunku.","isCorrect":false,"reaction":"Pelajar menunjuk gambar majlis di London yang menunjukkan pemimpin Sarawak."},{"text":"Hanya Lee Kuan Yew dan Razak.","isCorrect":false,"reaction":"Mustapha menggeleng. Wakil Sarawak turut menandatangani."}],"clue":"Jugah dan Abang Haji Mustapha menandatangani bagi Sarawak."}]}'),
(30, 'e1_n2_s13', 'Tanda Bilik UNMM', 'Cari tiga bukti yang menunjukkan bilik ini bilik UNMM.', '2', 'Mencari bukti UNMM 12 Ogos 1963: perwakilan PBB, sepanduk misi dan peti undi penduduk.', '{"bgImage":"../assets/gameAsset/background/bilik_UNMM.png","hotspots":[{"name":"Pegawai PBB berbaret biru sedang menghitung","top":"67%","left":"33%"},{"name":"Sepanduk UNMM: meninjau hasil pungutan suara","top":"10%","left":"41%"},{"name":"Peti undi PBB berisi pandangan penduduk","top":"67%","left":"9%"}],"aftermath":"Bilik tersalah kenal, dan Mustapha menegur bahawa pasukan PBB datang untuk tugas khusus.","turns":[{"after":6,"options":[{"text":"Mengesahkan persetujuan penduduk Sarawak dan Sabah.","isCorrect":true,"reaction":"Ahli UNMM mengangguk dan mula menemu bual penduduk dengan teliti."},{"text":"Menyediakan perlembagaan.","isCorrect":false,"reaction":"Mustapha menyebut itu tugas JAK, bukan UNMM."},{"text":"Menjalankan referendum Singapura.","isCorrect":false,"reaction":"Ahli UNMM menggeleng. Referendum itu 1 September 1962 di Singapura."}],"clue":"UNMM mengesahkan persetujuan penduduk Borneo."}]}'),
(31, 'e1_n2_s14', 'Empat Tempat, Empat Negeri', 'Padankan setiap tempat pemasyhuran dengan negerinya.', '4', 'Memadankan Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall dengan Persekutuan Tanah Melayu, Sarawak, Sabah dan Singapura.', '{"pairs":[{"text":"Kuala Lumpur","pair":1},{"text":"Persekutuan Tanah Melayu","pair":1},{"text":"Kuching","pair":2},{"text":"Sarawak","pair":2},{"text":"Kota Kinabalu","pair":3},{"text":"Sabah","pair":3},{"text":"City Hall","pair":4},{"text":"Singapura","pair":4}],"aftermath":"Tempat tersilap dipadankan, dan Jugah membetulkan bahawa setiap negeri ada tempat pemasyhurannya sendiri.","turns":[{"after":7,"options":[{"text":"Malaysia ditubuhkan. Sabah, Sarawak dan Singapura tamat daripada menjadi jajahan takluk Queen.","isCorrect":true,"reaction":"Kanak-kanak bersorak. Hari itu kini dikenali sebagai Hari Malaysia."},{"text":"Perjanjian ditandatangani.","isCorrect":false,"reaction":"Jugah berkata itu 9 Julai 1963, dua bulan sebelumnya."},{"text":"UNMM datang.","isCorrect":false,"reaction":"Kanak-kanak menyemak kalendar. UNMM datang pada 12 Ogos 1963."}],"clue":"Malaysia dimasyhurkan pada 16 September 1963."}]}'),
(32, 'e1_n2_s15', 'Surat dari Seberang', 'Nyahkod surat itu dan tentukan wilayah yang didakwa Filipina.', '5', 'Memahami dakwaan Filipina ke atas Sabah sebagai cabaran selepas Pemasyhuran.', '{"clueText":"Surat dari Filipina: Filipina mendakwa wilayah tempat Donald Stephens dan Mustapha Harun berkhidmat sebagai sebahagian daripada wilayahnya.","options":[{"text":"Sabah","isCorrect":true},{"text":"Sarawak","isCorrect":false,"consequence":"Dakwaan Filipina ialah ke atas Sabah, wilayah Donald sendiri, bukan Sarawak."},{"text":"Singapura","isCorrect":false,"consequence":"Bukan Singapura. Cabaran Filipina tertumpu pada Sabah."},{"text":"Brunei","isCorrect":false,"consequence":"Brunei menolak penyertaan sendiri, bukan hasil dakwaan Filipina."}],"aftermath":"Wilayah tersilap dikenal pasti, dan jawapan Malaysia kepada Filipina menjadi kabur.","turns":[{"after":7,"options":[{"text":"Carik-carik bulu ayam, akhirnya bercantum juga. Permuafakatan pemimpin memulihkan hubungan.","isCorrect":true,"reaction":"Mustapha mengangguk. Hubungan akhirnya kembali pulih."},{"text":"Tidak mungkin.","isCorrect":false,"reaction":"Mustapha menyebut hubungan akhirnya kembali pulih."},{"text":"Kita lupakan sahaja mereka.","isCorrect":false,"reaction":"Pemudi berkata kerjasama serantau perlu demi kemakmuran."}],"clue":"Permuafakatan memulihkan hubungan yang tegang."}]}'),
(33, 'e1_n2_s16', 'Lapan Langkah untuk Ucapan', 'Susun lapan langkah dari Adelphi hingga Pemasyhuran mengikut tarikh.', '1', 'Menyusun kronologi: 27 Mei 1961, 23 Julai 1961, 17 Januari 1962, 21 Jun 1962, 30 Ogos 1962, 9 Julai 1963, 12 Ogos 1963 dan 16 September 1963.', '{"timelineItems":[{"id":1,"year":"27 Mei 1961","text":"Tunku mengumumkan cadangan Malaysia di Hotel Adelphi, Singapura","why":"Pengumuman membuka seluruh perjalanan."},{"id":2,"year":"23 Julai 1961","text":"JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah","why":"Selepas pengumuman, pemimpin perlu diyakinkan."},{"id":3,"year":"17 Januari 1962","text":"Suruhanjaya Cobbold dibentuk untuk mendapatkan reaksi penduduk","why":"Selepas pemimpin, rakyat pula ditanya."},{"id":4,"year":"21 Jun 1962","text":"Cobbold menyerahkan laporan: dua pertiga menyokong","why":"Dapatan rakyat dihantar kepada British dan Persekutuan."},{"id":5,"year":"30 Ogos 1962","text":"JAK menyediakan rangka perlembagaan yang melindungi Sarawak dan Sabah","why":"Dapatan laporan memerlukan perlindungan bertulis."},{"id":6,"year":"9 Julai 1963","text":"Perjanjian Malaysia ditandatangani di Marlborough House, London","why":"Selepas perlembagaan disediakan, perjanjian ditandatangani."},{"id":7,"year":"12 Ogos 1963","text":"UNMM mengesahkan persetujuan penduduk Sarawak dan Sabah","why":"Selepas perjanjian, PBB mengesahkan persetujuan rakyat Borneo."},{"id":8,"year":"16 September 1963","text":"Pemasyhuran Malaysia di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall","why":"Setelah semua disahkan, Malaysia dimasyhurkan."}],"aftermath":"Langkah tersusun terbalik, dan Mustapha menyebut bagaimana PBB boleh mengesahkan sebelum ada perjanjian.","turns":[{"after":6,"options":[{"text":"Sebagai tanda syukur dan bangga atas permuafakatan dan perpaduan rakyat Malaysia.","isCorrect":true,"reaction":"Murid mengangguk. Hari Malaysia kini lebih bermakna baginya."},{"text":"Kerana Singapura berpisah.","isCorrect":false,"reaction":"Mustapha menggeleng. Perpisahan itu pada 1965."},{"text":"Kerana Tunku dilantik Perdana Menteri.","isCorrect":false,"reaction":"Murid menyemak buku. Bukan itu sebabnya."}],"clue":"Hari Malaysia ialah tanda syukur dan perpaduan."}]}'),
(34, 'e1_n3_s1', 'Fail 1938', 'Nyahkod fail lama itu dan tentukan konsep yang diperjuangkan.', '5', 'Mengenal pasti konsep Melayu Raya 1938 oleh Ibrahim Yaakob dan Harun Aminurrashid.', '{"clueText":"Fail 1938: Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan satu konsep penyatuan Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia.","options":[{"text":"Melayu Raya","isCorrect":true},{"text":"Malaysia","isCorrect":false,"consequence":"Nama Malaysia belum digunakan pada 1938. Konsep ini lebih luas."},{"text":"Negeri-negeri Selat","isCorrect":false,"consequence":"Itu cadangan Brassey 1887, bukan fail 1938."},{"text":"Persekutuan Tanah Melayu","isCorrect":false,"consequence":"Persekutuan ditubuhkan kemudian dan tidak merangkumi Filipina atau Indonesia."}],"aftermath":"Fail tidak dapat dibaca, dan Razak menegur bahawa pegawai tidak boleh menjawab dengan tekaan.","turns":[{"after":6,"options":[{"text":"Idea itu bermula dari tokoh yang berlainan pada tahun berlainan.","isCorrect":true,"reaction":"Razak berpuas hati kerana jawapannya berfakta."},{"text":"Tunku yang mula-mula mencadangkannya.","isCorrect":false,"reaction":"Razak menunjuk fail 1938 di atas meja."},{"text":"Ia rancangan baharu British.","isCorrect":false,"reaction":"Razak berkata British sendiri hanya mencadangkan pada 1887."}],"clue":"Idea gabungan sudah lama wujud."}]}'),
(35, 'e1_n3_s2', 'Empat Idea Mengikut Tahun', 'Susun empat idea gabungan mengikut tahun, dari yang paling awal.', '1', 'Menyusun kronologi idea: 1887, 1938, 1951 dan 1955.', '{"timelineItems":[{"id":1,"year":"1887","text":"Lord Brassey mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat","why":"Idea paling awal datang daripada pengarah syarikat."},{"id":2,"year":"1938","text":"Ibrahim Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya","why":"Kemudian orang Melayu pula mengemukakan konsep sendiri."},{"id":3,"year":"1951","text":"Malcolm MacDonald berbincang dengan pemimpin empat wilayah","why":"Pegawai British kembali membincangkannya."},{"id":4,"year":"1955","text":"Tunku mencadangkan empat wilayah menyertai Persekutuan Tanah Melayu","why":"Idea sampai kepada pemimpin Persekutuan."}],"aftermath":"Susunan tersilap, dan Razak menegur bahawa fail lama mesti disusun mengikut tahun."}'),
(36, 'e1_n3_s3', 'Bukti Keselamatan', 'Cari empat bukti yang menunjukkan sebab keselamatan.', '2', 'Mencari bukti ancaman komunis di Singapura dan Borneo serta kertas laporan dan papan strategi.', '{"bgImage":"../assets/gameAsset/background/bilik_strategi_keselamatan.png","hotspots":[{"name":"Peta Singapura","top":"30%","left":"38%"},{"name":"Peta Borneo","top":"30%","left":"62%"},{"name":"Kertas laporan ancaman","top":"68.9%","left":"31.3%"},{"name":"Papan strategi keselamatan","top":"13%","left":"52%"}],"aftermath":"Bukti tidak dijumpai, dan Razak menganggap hujah Ghazali kurang kukuh."}'),
(37, 'e1_n3_s4', 'Empat Sebab, Empat Penjelasan', 'Padankan setiap sebab dengan penjelasannya.', '4', 'Memadankan empat sebab pembentukan Malaysia dengan penjelasan masing-masing.', '{"pairs":[{"text":"Keselamatan","pair":1},{"text":"Membendung ancaman komunis","pair":1},{"text":"Keseimbangan kaum","pair":2},{"text":"Bilangan penduduk antara kaum menjadi seimbang","pair":2},{"text":"Kemerdekaan","pair":3},{"text":"Mempercepat kemerdekaan Sarawak, Sabah, Singapura dan Brunei","pair":3},{"text":"Sosioekonomi","pair":4},{"text":"Membangunkan ekonomi dan taraf hidup","pair":4}],"aftermath":"Padanan tersilap, dan Razak menegur bahawa empat sebab ini tidak boleh bercampur."}'),
(38, 'e1_n3_s5', 'Teks Ucapan Tunku', 'Bantu Tunku memilih teks ucapan yang betul.', '3', 'Membantu NPC memilih teks ucapan pengumuman Malaysia di Hotel Adelphi.', '{"npcName":"Tunku Abdul Rahman","prompt":"Teks ucapan untuk Hotel Adelphi hilang. Yang mana satu yang betul?","options":[{"text":"Teks pengumuman cadangan Malaysia, 27 Mei 1961","item":"dokumen","isCorrect":true},{"text":"Teks Perjanjian Malaysia, 9 Julai 1963","item":"dokumen","isCorrect":false,"consequence":"Perjanjian itu belum wujud, dua tahun lagi."},{"text":"Laporan Cobbold, 21 Jun 1962","item":"dokumen","isCorrect":false,"consequence":"Laporan itu belum ditulis lagi."},{"text":"Teks Pemasyhuran Malaysia, 16 September 1963","item":"dokumen","isCorrect":false,"consequence":"Pemasyhuran jauh lebih lewat daripada hari ini."}],"aftermath":"Teks yang salah dibawa, dan wartawan menulis tajuk yang mengelirukan."}'),
(39, 'e1_n3_s6', 'Nota Kuching', 'Nyahkod nota dan tentukan tujuan lawatan.', '5', 'Memahami tujuan lawatan Tunku ke Sarawak pada Julai 1961.', '{"clueText":"Nota Julai 1961: Tunku berada di Kuching untuk bertemu pemimpin Sarawak dan menjelaskan satu idea kepada mereka.","options":[{"text":"Menerangkan idea pembentukan Malaysia","isCorrect":true},{"text":"Menandatangani perjanjian","isCorrect":false,"consequence":"Perjanjian ditandatangani di London pada 9 Julai 1963."},{"text":"Menyerahkan laporan Cobbold","isCorrect":false,"consequence":"Laporan Cobbold diserahkan pada 21 Jun 1962."},{"text":"Mengadakan pemasyhuran","isCorrect":false,"consequence":"Pemasyhuran pada 16 September 1963."}],"aftermath":"Tujuan tersilap dibaca, dan Razak menegur bahawa pegawai mesti teliti."}'),
(40, 'e1_n3_s7', 'Bukti JSKM', 'Cari empat bukti bahawa ini mesyuarat JSKM.', '2', 'Mencari bukti penubuhan JSKM pada 23 Julai 1961.', '{"bgImage":"../assets/gameAsset/background/bilik_jskm.png","hotspots":[{"name":"Delegasi Sabah","top":"72%","left":"39%"},{"name":"Delegasi Sarawak","top":"24%","left":"66%"},{"name":"Dokumen mesyuarat","top":"64%","left":"60%"},{"name":"Peta wilayah","top":"45%","left":"58%"}],"aftermath":"Bukti tidak ditemui, dan mesyuarat dianggap kurang teratur."}'),
(41, 'e1_n3_s8', 'Kertas Arahan Cobbold', 'Nyahkod kertas dan tentukan tugas suruhanjaya.', '5', 'Mengenal pasti tugas Suruhanjaya Cobbold: mendapatkan reaksi penduduk Sarawak dan Sabah.', '{"clueText":"Kertas arahan 17 Januari 1962: sebuah suruhanjaya dibentuk untuk menemu ramah penduduk dan meneliti memorandum mereka di Sarawak dan Sabah.","options":[{"text":"Mendapatkan reaksi penduduk","isCorrect":true},{"text":"Menyediakan perlembagaan","isCorrect":false,"consequence":"Itu tugas JAK, bukan Cobbold."},{"text":"Mengesahkan persetujuan penduduk","isCorrect":false,"consequence":"Itu tugas UNMM, setahun kemudian."},{"text":"Menandatangani perjanjian","isCorrect":false,"consequence":"Perjanjian ditandatangani di London."}],"aftermath":"Tugas tersilap dikenal pasti, dan suruhanjaya hilang arah."}'),
(42, 'e1_n3_s9', 'Laporan Cobbold', 'Bantu Sambanthan memilih laporan yang betul.', '3', 'Membantu NPC memilih laporan Cobbold: dua pertiga menyokong.', '{"npcName":"T. Sambanthan","prompt":"Yang mana laporan Cobbold yang betul?","options":[{"text":"Laporan: dua pertiga menyokong, SUPP menolak","item":"dokumen","isCorrect":true},{"text":"Laporan: semua penduduk bersetuju","item":"dokumen","isCorrect":false,"consequence":"Laporan itu salah. Tidak semua bersetuju."},{"text":"Laporan: semua penduduk menolak","item":"dokumen","isCorrect":false,"consequence":"Laporan itu juga salah. Dua pertiga menyokong."},{"text":"Perjanjian Malaysia 1963","item":"dokumen","isCorrect":false,"consequence":"Perjanjian itu belum wujud."}],"aftermath":"Laporan yang salah dibawa, dan rundingan tersasar."}'),
(43, 'e1_n3_s10', 'Bukti JAK', 'Cari tiga bukti bahawa ini mesyuarat JAK.', '2', 'Mencari bukti mesyuarat JAK 30 Ogos 1962.', '{"bgImage":"../assets/gameAsset/background/bilik_mesyuarat_formal.png","hotspots":[{"name":"Wakil British","top":"40%","left":"30%"},{"name":"Wakil Persekutuan","top":"40%","left":"50%"},{"name":"Rangka perlembagaan di meja","top":"60%","left":"45%"}],"aftermath":"Bukti tidak ditemui, dan mesyuarat dianggap tidak sah."}'),
(44, 'e1_n3_s11', 'Nota Keputusan', 'Nyahkod nota dan tentukan peristiwa itu.', '5', 'Mengenal pasti referendum Singapura 1 September 1962.', '{"clueText":"Nota 1 September 1962: rakyat Singapura mengundi untuk menyatakan pendirian mereka tentang pembentukan Malaysia.","options":[{"text":"Referendum","isCorrect":true},{"text":"Pemasyhuran","isCorrect":false,"consequence":"Pemasyhuran pada 16 September 1963."},{"text":"Perjanjian","isCorrect":false,"consequence":"Perjanjian pada 9 Julai 1963."},{"text":"Penubuhan UNMM","isCorrect":false,"consequence":"UNMM pada 12 Ogos 1963."}],"aftermath":"Peristiwa tersilap dikenal pasti."}'),
(45, 'e1_n3_s12', 'Fail Perjanjian', 'Bantu Razak memilih fail perjanjian yang betul.', '3', 'Membantu NPC memilih fail Perjanjian Malaysia: Marlborough House, 9 Julai 1963.', '{"npcName":"Tun Abdul Razak","prompt":"Fail mana yang betul untuk Perjanjian Malaysia?","options":[{"text":"Perjanjian Malaysia, Marlborough House, 9 Julai 1963","item":"dokumen","isCorrect":true},{"text":"Pengumuman Adelphi, 27 Mei 1961","item":"dokumen","isCorrect":false,"consequence":"Itu pengumuman awal, bukan perjanjian."},{"text":"Laporan UNMM, Ogos 1963","item":"dokumen","isCorrect":false,"consequence":"UNMM masih sebulan lagi."},{"text":"Pemasyhuran, 16 September 1963","item":"dokumen","isCorrect":false,"consequence":"Pemasyhuran belum berlaku."}],"aftermath":"Fail yang salah dihantar, dan rundingan tertangguh."}'),
(46, 'e1_n3_s13', 'Empat Badan, Empat Tugas', 'Padankan setiap badan dengan tugasnya.', '4', 'Memadankan JSKM, Cobbold, JAK dan UNMM dengan tugas masing-masing.', '{"pairs":[{"text":"JSKM","pair":1},{"text":"Meyakinkan pemimpin Sarawak dan Sabah","pair":1},{"text":"Suruhanjaya Cobbold","pair":2},{"text":"Mendapatkan reaksi penduduk","pair":2},{"text":"JAK","pair":3},{"text":"Menyediakan rangka perlembagaan","pair":3},{"text":"UNMM","pair":4},{"text":"Mengesahkan persetujuan penduduk","pair":4}],"aftermath":"Padanan tersilap."}'),
(47, 'e1_n3_s14', 'Bukti Pemasyhuran', 'Cari tiga bukti pada dokumen Pemasyhuran.', '2', 'Mencari bukti Pemasyhuran Malaysia 16 September 1963.', '{"bgImage":"../assets/gameAsset/background/perancangan_pembentukan_malaysia.png","hotspots":[{"name":"Tarikh 16 September 1963","top":"30%","left":"40%"},{"name":"Nama Tunku sebagai Perdana Menteri","top":"55%","left":"50%"},{"name":"Empat tempat pemasyhuran","top":"70%","left":"45%"}],"aftermath":"Bukti tidak ditemui."}'),
(48, 'e1_n3_s15', 'Cabaran Selepas Pemasyhuran', 'Padankan setiap pihak dengan cabarannya.', '4', 'Memadankan SUPP, Indonesia, Filipina dan Brunei dengan cabaran masing-masing.', '{"pairs":[{"text":"SUPP","pair":1},{"text":"Mahu persekutuan sendiri","pair":1},{"text":"Indonesia","pair":2},{"text":"Konfrontasi 1963 hingga 1966","pair":2},{"text":"Filipina","pair":3},{"text":"Mendakwa Sabah","pair":3},{"text":"Brunei","pair":4},{"text":"Menolak penyertaan","pair":4}],"aftermath":"Padanan tersilap."}'),
(49, 'e1_n3_s16', 'Lapan Langkah', 'Susun lapan langkah mengikut tarikh.', '1', 'Menyusun kronologi lapan langkah pembentukan Malaysia.', '{"timelineItems":[{"id":1,"year":"27 Mei 1961","text":"Tunku mengumumkan cadangan Malaysia di Hotel Adelphi","why":"Pengumuman membuka perjalanan."},{"id":2,"year":"23 Julai 1961","text":"JSKM ditubuhkan","why":"Pemimpin perlu diyakinkan."},{"id":3,"year":"17 Januari 1962","text":"Suruhanjaya Cobbold dibentuk","why":"Rakyat pula ditanya."},{"id":4,"year":"21 Jun 1962","text":"Laporan Cobbold: dua pertiga menyokong","why":"Dapatan diserahkan."},{"id":5,"year":"30 Ogos 1962","text":"JAK menyediakan rangka perlembagaan","why":"Perlindungan bertulis disediakan."},{"id":6,"year":"9 Julai 1963","text":"Perjanjian Malaysia ditandatangani di London","why":"Persetujuan dimeterai."},{"id":7,"year":"12 Ogos 1963","text":"UNMM mengesahkan persetujuan penduduk","why":"Persetujuan disahkan."},{"id":8,"year":"16 September 1963","text":"Pemasyhuran Malaysia","why":"Malaysia terbentuk."}],"aftermath":"Langkah tersusun terbalik."}'),
(201, 'e2_n1_s1', 'Catatan Pudar di Atas Pangkin', 'Baca catatan pudar itu dan tentukan maksud perkataan Siam yang dikaitkan dengan nama Perlis.', '5', 'Mengetahui asal nama Perlis: prow-lowy (kelapa hanyut) dan peristiwa Raja Syed Hussin Jamalullail.', '{"clueText":"Catatan lama: Nama Perlis dipercayai berasal daripada perkataan Siam, prow-lowy. Ia dikaitkan dengan sesuatu yang dilihat hanyut di air dan ditemui di parit.","options":[{"text":"Kelapa hanyut","isCorrect":true},{"text":"Air jernih","isCorrect":false,"consequence":"Papan kampung ditulis dengan maksud yang salah dan kanak-kanak menghafalnya."},{"text":"Pokok tinggi","isCorrect":false,"consequence":"Pesawah mencari pokok tinggi di sawah dan ketawakan catatan itu."},{"text":"Sungai besar","isCorrect":false,"consequence":"Pelawat bertanya di mana sungai besar itu dan pesawah tidak dapat menjawab."}],"aftermath":"Catatan tidak dapat dibaca dan pesawah menyimpulkan Tok tidak tahu apa-apa tentang negerinya.","turns":[{"after":6,"options":[{"text":"Dari \'peroleh\': mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail.","isCorrect":true,"reaction":"Pesawah tersenyum. Dua cerita itu akan ditulis bersebelahan."},{"text":"Tiada cerita lain.","isCorrect":false,"reaction":"Pesawah menunjuk orang sebelah. Mereka berkeras ada cerita lain."},{"text":"Perlis dari nama sungai.","isCorrect":false,"reaction":"Murid menyemak buku. Tiada catatan sungai."}],"clue":"Selain prow-lowy, ada cerita \'peroleh\' dan mandat Raja Syed Hussin."}]}'),
(202, 'e2_n1_s2', 'Tiga Nama, Tiga Bahasa', 'Padankan setiap nama Kedah dengan maksudnya.', '4', 'Memadankan Kheddah, Qadah dan Kadaram atau kalagam dengan maksud asal nama Kedah.', '{"pairs":[{"text":"Kheddah","pair":1},{"text":"Perangkap gajah","pair":1},{"text":"Qadah","pair":2},{"text":"Cawan atau gelas berkaki yang dijual pedagang Arab","pair":2},{"text":"Kadaram atau kalagam","pair":3},{"text":"Nama Kedah dalam tulisan Tamil","pair":3}],"aftermath":"Padanan tersilap dan dua lelaki bertengkar lebih kuat kerana catatan mereka dipadankan dengan salah.","turns":[{"after":6,"options":[{"text":"Kadaram atau kalagam, kata tulisan Tamil itu.","isCorrect":true,"reaction":"Pemandu gajah mengangguk. Tiga bahasa kini dicatat."},{"text":"Qadah.","isCorrect":false,"reaction":"Penjual cawan menggeleng. Itu nama Arab, bukan Tamil."},{"text":"Kheddah.","isCorrect":false,"reaction":"Pemandu gajah mengaku itu nama untuk perangkap, bukan tulisan Tamil."}],"clue":"Tulisan Tamil mencatat Kedah sebagai kadaram atau kalagam."}]}'),
(203, 'e2_n1_s3', 'Dua Negeri di Jeti', 'Padankan setiap nama atau sebab dengan negerinya.', '4', 'Memadankan Pulo Ka Satu, Tanjong Penaga, buah pinang, kilatan ikan dan bijih timah dengan Pulau Pinang atau Perak.', '{"pairs":[{"text":"Pulo Ka Satu","pair":1},{"text":"Nama asal Pulau Pinang","pair":1},{"text":"Tanjong Penaga","pair":2},{"text":"Gelaran orang Melayu Kedah kerana banyak pokok penaga","pair":2},{"text":"Buah pinang","pair":3},{"text":"Bahan dagangan penting yang dikaitkan dengan Pulau Pinang","pair":3},{"text":"Kilatan ikan di dalam air","pair":4},{"text":"Nama Perak, berkilau seperti perak","pair":4},{"text":"Bijih timah putih berkilat","pair":5},{"text":"Pandangan lain tentang nama Perak","pair":5}],"aftermath":"Padanan tersilap dan nelayan menuduh Tok mencampuradukkan dua negeri.","turns":[{"after":6,"options":[{"text":"\'Tak kenal maka tak cinta.\'","isCorrect":true,"reaction":"Nelayan tersenyum. Mengenali negeri menjadikan kita lebih sayang."},{"text":"\'Alah bisa tegal biasa.\'","isCorrect":false,"reaction":"Murid menggeleng. Peribahasa itu bukan tentang cinta negeri."},{"text":"\'Sediakan payung sebelum hujan.\'","isCorrect":false,"reaction":"Murid menggeleng. Itu bukan peribahasa buku ini."}],"clue":"Peribahasa dalam buku teks: Tak kenal maka tak cinta."}]}'),
(204, 'e2_n1_s4', 'Pusat dan Kota Warisan Utara', 'Padankan setiap ibu negeri dengan bandar dirajanya.', '4', 'Memadankan ibu negeri dan bandar diraja: Kangar dan Arau, Alor Setar dan Anak Bukit, Ipoh dan Kuala Kangsar, George Town dan tiada bandar diraja.', '{"pairs":[{"text":"Kangar (Perlis)","pair":1},{"text":"Arau","pair":1},{"text":"Alor Setar (Kedah)","pair":2},{"text":"Anak Bukit","pair":2},{"text":"Ipoh (Perak)","pair":3},{"text":"Kuala Kangsar","pair":3},{"text":"George Town (Pulau Pinang)","pair":4},{"text":"Tiada bandar diraja ditanda pada peta","pair":4}],"aftermath":"Pegawai menegur dan murid ketawa kerana Tok menukar bandar diraja dengan ibu negeri.","turns":[{"after":6,"options":[{"text":"Memelihara dan memulihara serta menghargai warisan sejarah di situ.","isCorrect":true,"reaction":"Pegawai mengangguk. Istana lama itu akan dijaga."},{"text":"Meruntuhkan bangunan lama.","isCorrect":false,"reaction":"Pegawai menggeleng. Warisan perlu dijaga."},{"text":"Membiarkan sahaja.","isCorrect":false,"reaction":"Murid berkata warisan akan rosak jika dibiarkan."}],"clue":"Warisan sejarah perlu dipelihara dan dipulihara."}]}'),
(205, 'e2_n1_s5', 'Kaset Lagu Kedah', 'Bantu pegawai radio memilih kaset lagu negeri Kedah.', '3', 'Membantu NPC memilih kaset lagu negeri Kedah: Allah Selamatkan Sultan Mahkota.', '{"npcName":"Pegawai Radio","prompt":"Majlis hampir bermula. Saya perlukan kaset lagu negeri Kedah. Yang mana satu?","options":[{"text":"Allah Selamatkan Sultan Mahkota","item":"kaset","isCorrect":true},{"text":"Aamiin-Aamiin","item":"kaset","isCorrect":false,"consequence":"Lagu Perlis dimainkan di hadapan tetamu Kedah dan mereka berpandangan."},{"text":"Allah Lanjutkan Usia Sultan","item":"kaset","isCorrect":false,"consequence":"Lagu Perak bergema dan majlis Kedah tersasar."},{"text":"Untuk Negeri Kita","item":"kaset","isCorrect":false,"consequence":"Lagu Pulau Pinang dimainkan dan tetamu Kedah menunduk malu."}],"aftermath":"Kaset yang salah dimainkan dan tetamu mula berbisik.","turns":[{"after":6,"options":[{"text":"Aamiin-Aamiin (Perlis), Allah Lanjutkan Usia Sultan (Perak), Untuk Negeri Kita (Pulau Pinang).","isCorrect":true,"reaction":"Pegawai mengangguk dan mencatat semua tajuk di buku."},{"text":"Semua sama, Allah Selamatkan Sultan.","isCorrect":false,"reaction":"Pegawai menggeleng. Setiap negeri ada tajuk sendiri."},{"text":"Tiada lagu untuk tiga negeri itu.","isCorrect":false,"reaction":"Pegawai menunjuk senarai lagu negeri dalam buku teks."}],"clue":"Setiap negeri ada lagu tersendiri."}]}'),
(206, 'e2_n1_s6', 'Kuala dan Luak', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan mentagau, selangur, nagari dan 1773.', '{"pairs":[{"text":"Mentagau","pair":1},{"text":"Pokok di kuala sungai yang melahirkan \'kuala selangau\'","pair":1},{"text":"Selangur atau sangur","pair":2},{"text":"Serangga yang banyak di sungai Selangor","pair":2},{"text":"Nagari","pair":3},{"text":"Wilayah dalam dialek Minangkabau","pair":3},{"text":"1773","pair":4},{"text":"Tahun sembilan luak asal Negeri Sembilan","pair":4}],"aftermath":"Penghulu dan nelayan menegur Tok kerana kekeliruan itu.","turns":[{"after":6,"options":[{"text":"Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.","isCorrect":true,"reaction":"Penghulu mengangguk. Sembilan luak dicatat."},{"text":"Kedah, Perak, Perlis, Johor, Pahang, Melaka, Kelantan, Terengganu dan Sabah.","isCorrect":false,"reaction":"Penghulu menggeleng. Itu negeri, bukan luak."},{"text":"Sembilan pulau di Selat Melaka.","isCorrect":false,"reaction":"Penghulu ketawa. Itu bukan luak."}],"clue":"Luak asal ialah Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang."}]}'),
(207, 'e2_n1_s7', 'Dua Negeri di Pelabuhan', 'Padankan setiap nama atau cerita dengan negerinya.', '4', 'Memadankan Malakat, pokok Parameswara, Jauhar dan Ujong Tanah dengan Melaka atau Johor.', '{"pairs":[{"text":"Malakat","pair":1},{"text":"Perhimpunan para pedagang (sumber Arab) bagi Melaka","pair":1},{"text":"Pokok tempat Parameswara berehat","pair":2},{"text":"Pelanduk putih menendang anjing, cerita Melaka","pair":2},{"text":"Jauhar","pair":3},{"text":"Perkataan Arab bagi batu permata bernilai, cerita Johor","pair":3},{"text":"Ujong Tanah","pair":4},{"text":"Nama Johor dalam Sulalatus Salatin","pair":4}],"aftermath":"Padanan tersilap dan pembaca naskhah menuduh Tok mengarang.","turns":[{"after":6,"options":[{"text":"Bahasa Arab. Malakat bermaksud perhimpunan para pedagang.","isCorrect":true,"reaction":"Pembaca naskhah mengangguk. Catatan Arab itu dihormati."},{"text":"Bahasa Tamil.","isCorrect":false,"reaction":"Pembaca naskhah menggeleng. Tamil tiada kaitan dengan Malakat."},{"text":"Bahasa Siam.","isCorrect":false,"reaction":"Pembaca naskhah menggeleng. Siam berkait dengan Perlis."}],"clue":"Malakat ialah sebutan Arab."}]}'),
(208, 'e2_n1_s8', 'Pusat dan Istana Tengah', 'Padankan ibu negeri dengan bandar dirajanya.', '4', 'Memadankan Shah Alam-Klang, Seremban-Seri Menanti, Johor Bahru-Bandar Maharani dan Bandar Melaka dengan tiada bandar diraja.', '{"pairs":[{"text":"Shah Alam (Selangor)","pair":1},{"text":"Klang","pair":1},{"text":"Seremban (Negeri Sembilan)","pair":2},{"text":"Seri Menanti","pair":2},{"text":"Johor Bahru (Johor)","pair":3},{"text":"Bandar Maharani","pair":3},{"text":"Bandar Melaka (Melaka)","pair":4},{"text":"Tiada bandar diraja ditanda pada peta","pair":4}],"aftermath":"Fail dikirim ke pejabat yang salah dan pegawai terpaksa menulis semula.","turns":[{"after":6,"options":[{"text":"Kerana pembangunan pentadbiran, kemudahan asas, institusi pendidikan dan tumpuan pekerjaan.","isCorrect":true,"reaction":"Pegawai mengangguk dan mencatat empat sebab itu."},{"text":"Kerana ia dekat dengan pantai.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu bukan sebab dalam buku."},{"text":"Kerana ia mempunyai istana.","isCorrect":false,"reaction":"Pegawai menggeleng. Istana ada di bandar diraja."}],"clue":"Ibu negeri berkembang kerana pentadbiran, kemudahan, pendidikan dan pekerjaan."}]}'),
(209, 'e2_n1_s9', 'Kaset Lagu Johor', 'Bantu pegawai radio memilih kaset lagu negeri Johor.', '3', 'Membantu NPC memilih kaset lagu Johor: Lagu Bangsa Johor.', '{"npcName":"Pegawai Radio","prompt":"Majlis Johor dua jam lagi. Kaset mana yang betul untuk lagu negeri Johor?","options":[{"text":"Lagu Bangsa Johor","item":"kaset","isCorrect":true},{"text":"Duli Yang Maha Mulia","item":"kaset","isCorrect":false,"consequence":"Lagu Selangor bergema dan Sultan Johor mengerutkan dahi."},{"text":"Berkatlah Yang di-Pertuan Besar","item":"kaset","isCorrect":false,"consequence":"Lagu Negeri Sembilan dimainkan dan majlis tergendala."},{"text":"Melaka Maju Jaya","item":"kaset","isCorrect":false,"consequence":"Lagu Melaka dimainkan dan tetamu Johor berbisik tidak puas hati."}],"aftermath":"Lagu negeri lain dimainkan dan majlis tergendala.","turns":[{"after":6,"options":[{"text":"Selangor, Negeri Sembilan dan Melaka.","isCorrect":true,"reaction":"Pegawai mengangguk dan mencatat tiga tajuk itu."},{"text":"Semuanya negeri Johor.","isCorrect":false,"reaction":"Pegawai menggeleng. Setiap negeri ada lagu sendiri."},{"text":"Perak, Kedah dan Perlis.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu lagu utara."}],"clue":"Duli Yang Maha Mulia, Berkatlah Yang di-Pertuan Besar dan Melaka Maju Jaya."}]}'),
(210, 'e2_n1_s10', 'Enam Cerita di Pantai', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan mahang, Inderapura, taring anu, terangnya ganu, kilatan dan gelam hutan.', '{"pairs":[{"text":"Mahang","pair":1},{"text":"Pokok yang melahirkan nama Pahang","pair":1},{"text":"Inderapura atau Pura","pair":2},{"text":"Nama Pahang dalam Sulalatus Salatin; pura ialah bandar","pair":2},{"text":"Taring anu","pair":3},{"text":"Taring besar seperti gading gajah di Pulau Duyong","pair":3},{"text":"Terangnya ganu","pair":4},{"text":"Pelangi","pair":4},{"text":"Kilatan","pair":5},{"text":"Cahaya terang yang dilihat orang Melayu Patani","pair":5},{"text":"Gelam hutan atau kelam hutan","pair":6},{"text":"Pokok di pesisir pantai Kelantan","pair":6}],"aftermath":"Tiga kumpulan bertelagah lebih kuat apabila padanan tersilap.","turns":[{"after":6,"options":[{"text":"Masyarakat Melayu Patani.","isCorrect":true,"reaction":"Pencerita mengangguk. Cerita Patani dihormati."},{"text":"Orang Minangkabau.","isCorrect":false,"reaction":"Pencerita menggeleng. Minangkabau berkait dengan nagari."},{"text":"Pedagang Arab.","isCorrect":false,"reaction":"Pencerita menggeleng. Arab berkait dengan Malakat dan Jauhar."}],"clue":"Kilatan dilihat oleh masyarakat Melayu Patani."}]}'),
(211, 'e2_n1_s11', 'Peta Pantai Timur', 'Padankan kad dengan ibu negeri atau bandar diraja yang betul.', '4', 'Memadankan ibu negeri Pahang Kuantan, bandar diraja Pahang Pekan, ibu negeri Terengganu Kuala Terengganu dan ibu negeri Kelantan Kota Bharu.', '{"pairs":[{"text":"Ibu negeri Pahang","pair":1},{"text":"Kuantan","pair":1},{"text":"Bandar diraja Pahang","pair":2},{"text":"Pekan","pair":2},{"text":"Ibu negeri Terengganu","pair":3},{"text":"Kuala Terengganu","pair":3},{"text":"Ibu negeri Kelantan","pair":4},{"text":"Kota Bharu","pair":4}],"aftermath":"Surat jemputan ke Pekan dihantar ke Kuantan dan pegawai terpaksa menulis semula.","turns":[{"after":6,"options":[{"text":"Istana, bangunan pembesar, kedai lama, muzium dan monumen.","isCorrect":true,"reaction":"Pegawai mengangguk dan mencatat senarai itu."},{"text":"Hanya pelabuhan.","isCorrect":false,"reaction":"Pegawai menggeleng. Pelabuhan bukan ciri bandar diraja."},{"text":"Hanya bangunan baharu.","isCorrect":false,"reaction":"Pegawai menggeleng. Bandar diraja ada warisan sejarah."}],"clue":"Bandar diraja ada warisan sejarah."}]}'),
(212, 'e2_n1_s12', 'Dua Negeri Satu Tajuk', 'Nyahkod nota dan tentukan dua negeri yang berkongsi tajuk lagu \'Selamat Sultan\'.', '5', 'Mengenal pasti Terengganu dan Kelantan sebagai dua negeri yang menggunakan tajuk lagu Selamat Sultan.', '{"clueText":"Nota: dua negeri di pantai timur menggunakan tajuk lagu yang sama, \'Selamat Sultan\'. Satu lagi negeri di pantai timur, Pahang, mempunyai tajuk lagu yang lain.","options":[{"text":"Terengganu dan Kelantan","isCorrect":true},{"text":"Pahang dan Terengganu","isCorrect":false,"consequence":"Pahang mempunyai tajuk lagu lain, iaitu Allah Selamatkan Sultan Kami."},{"text":"Pahang dan Kelantan","isCorrect":false,"consequence":"Pahang mempunyai tajuk lagu lain, jadi nota itu tidak menyebutnya."},{"text":"Kedah dan Perak","isCorrect":false,"consequence":"Dua negeri itu di utara dan lagu mereka lain."}],"aftermath":"Dua orang tua berhujah semula dan Tok terpaksa menulis semula halaman itu.","turns":[{"after":6,"options":[{"text":"Allah Selamatkan Sultan Kami.","isCorrect":true,"reaction":"Orang tua mengangguk. Tajuk Pahang dicatat."},{"text":"Selamat Sultan.","isCorrect":false,"reaction":"Orang tua menggeleng. Itu tajuk Terengganu dan Kelantan."},{"text":"Allah Lanjutkan Usia Sultan.","isCorrect":false,"reaction":"Orang tua menggeleng. Itu lagu Perak."}],"clue":"Pahang: Allah Selamatkan Sultan Kami."}]}'),
(213, 'e2_n1_s13', 'Dokumen Nama Borneo', 'Bantu ahli sejarah memilih dokumen yang betul tentang nama Sarawak dan Sabah.', '3', 'Membantu NPC memilih dokumen: Sungai Serak, cerava, pisang saba dan Maharajah of Sabah 1877.', '{"npcName":"Ahli Sejarah","prompt":"Yang mana dokumen yang betul tentang nama Sarawak dan Sabah?","options":[{"text":"Sungai Serak dan cerava (Sarawak); pisang saba dan Maharajah of Sabah 1877 (Sabah)","item":"dokumen","isCorrect":true},{"text":"Sungai Serak dan cerava (Sarawak); pisang saba dan Maharajah of Sabah 1773 (Sabah)","item":"dokumen","isCorrect":false,"consequence":"Tahun 1773 ialah tahun luak Negeri Sembilan, bukan dokumen Sabah."},{"text":"Pulo Ka Satu (Sarawak); pisang saba (Sabah)","item":"dokumen","isCorrect":false,"consequence":"Pulo Ka Satu ialah nama asal Pulau Pinang."},{"text":"Sungai Serak (Sabah); pisang saba (Sarawak)","item":"dokumen","isCorrect":false,"consequence":"Nama negeri bertukar dan ahli sejarah menggeleng."}],"aftermath":"Dokumen yang salah dipilih dan ahli sejarah tersilap menerangkan nama kepada pelawat.","turns":[{"after":6,"options":[{"text":"1877, tahun dokumen \'Maharajah of Sabah\'.","isCorrect":true,"reaction":"Ahli sejarah mencatat tahun itu."},{"text":"1773.","isCorrect":false,"reaction":"Ahli sejarah menggeleng. 1773 ialah tahun luak Negeri Sembilan."},{"text":"1887.","isCorrect":false,"reaction":"Ahli sejarah menggeleng. 1887 bukan tahun dokumen Sabah."}],"clue":"Dokumen Maharajah of Sabah ialah pada tahun 1877."}]}'),
(214, 'e2_n1_s14', 'Tiga Wilayah, Tiga Nama', 'Padankan setiap wilayah dengan asal namanya.', '4', 'Memadankan Kuala Lumpur, Labuan dan Putrajaya dengan asal nama masing-masing.', '{"pairs":[{"text":"Kuala Lumpur","pair":1},{"text":"Muara berlumpur akibat melombong bijih timah","pair":1},{"text":"Labuan","pair":2},{"text":"Labuhan, tempat persinggahan kapal","pair":2},{"text":"Putrajaya","pair":3},{"text":"Tunku Abdul Rahman Putra; jaya bermaksud kemenangan atau menuju ke puncak","pair":3}],"aftermath":"Pelawat menyangka Putrajaya bersempena nama orang lain.","turns":[{"after":5,"options":[{"text":"Tunku Abdul Rahman Putra, dan jaya bermaksud kemenangan atau menuju ke puncak.","isCorrect":true,"reaction":"Pelawat mengangguk. Putrajaya dihormati namanya."},{"text":"Tun Abdul Razak.","isCorrect":false,"reaction":"Pelawat menggeleng. Nama itu tidak disebut dalam buku."},{"text":"Tun Mahathir.","isCorrect":false,"reaction":"Pelawat menggeleng. Nama itu tidak disebut dalam buku."}],"clue":"Putrajaya bersempena Tunku Abdul Rahman Putra."}]}'),
(215, 'e2_n1_s15', 'Pusat Pentadbiran Borneo', 'Padankan setiap negeri dengan ibu negerinya dan sebab ibu negeri berkembang.', '4', 'Memadankan Kuching, Kota Kinabalu dan sebab ibu negeri berkembang.', '{"pairs":[{"text":"Ibu negeri Sarawak","pair":1},{"text":"Kuching","pair":1},{"text":"Ibu negeri Sabah","pair":2},{"text":"Kota Kinabalu","pair":2},{"text":"Ibu negeri berkembang kerana","pair":3},{"text":"Pembangunan pentadbiran, kemudahan asas dan institusi pendidikan","pair":3},{"text":"Ibu negeri menjadi tempat tumpuan","pair":4},{"text":"Pekerjaan","pair":4}],"aftermath":"Dua pegawai bertukar fail dan murid keliru.","turns":[{"after":6,"options":[{"text":"Memelihara dan memulihara warisan sejarah di situ.","isCorrect":true,"reaction":"Pegawai mengangguk dan berjanji menjaga istana lama."},{"text":"Membiarkan sahaja.","isCorrect":false,"reaction":"Pegawai menggeleng. Warisan akan rosak."},{"text":"Menggantikannya dengan bangunan baharu.","isCorrect":false,"reaction":"Pegawai menggeleng. Warisan sejarah perlu dipelihara."}],"clue":"Warisan sejarah dipelihara dan dipulihara."}]}'),
(216, 'e2_n1_s16', 'Kaset Lagu Sabah', 'Bantu pegawai radio memilih kaset lagu negeri Sabah.', '3', 'Membantu NPC memilih kaset lagu Sabah: Sabah Tanah Airku.', '{"npcName":"Pegawai Radio","prompt":"Lagu Sabah akan dimainkan sekejap lagi. Yang mana kaset yang betul?","options":[{"text":"Sabah Tanah Airku","item":"kaset","isCorrect":true},{"text":"Ibu Pertiwiku","item":"kaset","isCorrect":false,"consequence":"Lagu Sarawak dimainkan di hadapan tetamu Sabah dan mereka berpandangan."},{"text":"Maju dan Sejahtera","item":"kaset","isCorrect":false,"consequence":"Lagu Wilayah Persekutuan dimainkan dan majlis Sabah tersasar."},{"text":"Melaka Maju Jaya","item":"kaset","isCorrect":false,"consequence":"Lagu Melaka dimainkan dan tetamu Sabah menunduk malu."}],"aftermath":"Kaset yang salah dimainkan dan tetamu Sabah tersinggung.","turns":[{"after":6,"options":[{"text":"Ibu Pertiwiku milik Sarawak, dan Maju dan Sejahtera milik Wilayah Persekutuan.","isCorrect":true,"reaction":"Pegawai mengangguk dan mencatat semua tajuk."},{"text":"Kedua-duanya milik Sabah.","isCorrect":false,"reaction":"Pegawai menggeleng. Sabah hanya ada satu lagu negeri."},{"text":"Kedua-duanya milik Sarawak.","isCorrect":false,"reaction":"Pegawai menggeleng. Maju dan Sejahtera milik Wilayah Persekutuan."}],"clue":"Ibu Pertiwiku ialah Sarawak. Maju dan Sejahtera ialah Wilayah Persekutuan."}]}'),
(217, 'e2_n1_s17', 'Kad Gelaran Ketua Negeri', 'Padankan gelaran dengan negeri yang menggunakannya.', '4', 'Memadankan Raja, Sultan, Yang di-Pertuan Besar dan Yang di-Pertua Negeri dengan negeri masing-masing.', '{"pairs":[{"text":"Raja","pair":1},{"text":"Perlis","pair":1},{"text":"Sultan","pair":2},{"text":"Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan","pair":2},{"text":"Yang di-Pertuan Besar","pair":3},{"text":"Negeri Sembilan","pair":3},{"text":"Yang di-Pertua Negeri","pair":4},{"text":"Pulau Pinang, Melaka, Sarawak dan Sabah","pair":4}],"aftermath":"Kad dipasang salah dan tetamu berasa tersinggung.","turns":[{"after":6,"options":[{"text":"Sikap menghormati dan taat setia kepada raja dapat dipupuk dengan mengenali ketua negeri. Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong.","isCorrect":true,"reaction":"Pegawai mengangguk. Semua tetamu dihormati."},{"text":"Supaya kita dapat mengundi mereka.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu bukan sebab dalam buku."},{"text":"Supaya kita dapat bergelar Sultan.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu bukan sebab dalam buku."}],"clue":"Kenali ketua negeri untuk memupuk hormat dan taat setia."}]}'),
(218, 'e2_n1_s18', 'Lambang di Pentas Pesta', 'Cari tiga lambang negeri di pentas: jata, bendera dan radio lagu.', '2', 'Mencari bukti lambang negeri: jata, bendera dan lagu sebagai identiti dan kemegahan negeri.', '{"bgImage":"../assets/gameAsset/background/wilayah_persekutuan.png","hotspots":[{"name":"Jata: lambang kedaulatan negeri","top":"40.4%","left":"70%"},{"name":"Bendera: lambang identiti negeri","top":"20.9%","left":"72.7%"},{"name":"Radio: lagu Maju dan Sejahtera","top":"86.4%","left":"74.1%"}],"aftermath":"Lambang tidak ditemui dan penonton bertanya adakah Tok benar-benar mengenali negeri.","turns":[{"after":6,"options":[{"text":"Kerana bendera, lagu dan jata ialah identiti dan lambang kemegahan setiap negeri.","isCorrect":true,"reaction":"Penonton bertepuk tangan. Buku ditutup dengan bangga."},{"text":"Kerana ia hiasan sahaja.","isCorrect":false,"reaction":"Penonton menggeleng. Lambang ialah identiti negeri."},{"text":"Supaya negeri lain takut.","isCorrect":false,"reaction":"Penonton menggeleng. Ia bukan untuk menakutkan."}],"clue":"Lambang negeri ialah identiti dan kemegahan."}]}'),
(219, 'e2_n2_s1', 'Nota Sisa dalam Fail', 'Nyahkod nota fail dan tentukan ketua Wilayah Persekutuan.', '5', 'Mengenal pasti ketua Wilayah Persekutuan: Yang di-Pertuan Agong.', '{"clueText":"Nota fail: Wilayah Persekutuan terdiri daripada Kuala Lumpur, Labuan dan Putrajaya. Ketuanya bukan sultan, bukan raja.","options":[{"text":"Yang di-Pertuan Agong","isCorrect":true},{"text":"Sultan","isCorrect":false,"consequence":"Kad dipasang salah dan Encik Zahar tersenyum."},{"text":"Yang di-Pertua Negeri","isCorrect":false,"consequence":"Kad dipasang salah dan Encik Zahar tersenyum."},{"text":"Yang di-Pertuan Besar","isCorrect":false,"consequence":"Kad dipasang salah dan Encik Zahar tersenyum."}],"aftermath":"Kad ketua dipasang salah dan Encik Zahar tersenyum puas.","turns":[{"after":6,"options":[{"text":"Tiada. Wilayah Persekutuan tidak mempunyai ibu negeri dan bandar diraja.","isCorrect":true,"reaction":"Encik Zahar terdiam. Jawapan itu tepat."},{"text":"Putrajaya ialah ibu negeri.","isCorrect":false,"reaction":"Encik Zahar tersenyum. Wilayah Persekutuan tiada ibu negeri."},{"text":"Kuala Lumpur ialah bandar diraja.","isCorrect":false,"reaction":"Tok berbisik, itu salah. Tiada bandar diraja di sana."}],"clue":"Wilayah Persekutuan tiada ibu negeri dan bandar diraja."}]}'),
(220, 'e2_n2_s2', 'Tiga Papan Nama', 'Padankan setiap wilayah dengan asal namanya.', '4', 'Memadankan Kuala Lumpur, Labuan dan Putrajaya dengan asal nama masing-masing.', '{"pairs":[{"text":"Kuala Lumpur","pair":1},{"text":"Muara berlumpur akibat melombong bijih timah","pair":1},{"text":"Labuan","pair":2},{"text":"Labuhan, tempat persinggahan kapal","pair":2},{"text":"Putrajaya","pair":3},{"text":"Tunku Abdul Rahman Putra; jaya bermaksud kemenangan atau menuju ke puncak","pair":3}],"aftermath":"Tetamu bertanya kenapa istiadat salah menyebut nama.","turns":[{"after":6,"options":[{"text":"Ya, bersempena Tunku Abdul Rahman Putra.","isCorrect":true,"reaction":"Juruteknik mengangguk dan memasang papan itu."},{"text":"Tidak, ia nama sebuah sungai.","isCorrect":false,"reaction":"Juruteknik menggeleng. Nama itu bukan sungai."},{"text":"Tidak, ia nama sebuah pulau.","isCorrect":false,"reaction":"Juruteknik menggeleng. Nama itu bukan pulau."}],"clue":"Putrajaya bersempena Tunku Abdul Rahman Putra."}]}'),
(221, 'e2_n2_s3', 'Kad Gelaran Ketua Negeri', 'Padankan gelaran dengan negeri yang menggunakannya.', '4', 'Memadankan Raja, Sultan, Yang di-Pertuan Besar dan Yang di-Pertua Negeri dengan negeri masing-masing.', '{"pairs":[{"text":"Raja","pair":1},{"text":"Perlis","pair":1},{"text":"Sultan","pair":2},{"text":"Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan","pair":2},{"text":"Yang di-Pertuan Besar","pair":3},{"text":"Negeri Sembilan","pair":3},{"text":"Yang di-Pertua Negeri","pair":4},{"text":"Pulau Pinang, Melaka, Sarawak dan Sabah","pair":4}],"aftermath":"Encik Zahar mengambil kad itu dan menyusunnya dengan salah.","turns":[{"after":5,"options":[{"text":"Ia menunjukkan keunikan negara dan menanam sikap hormat serta taat setia kepada raja.","isCorrect":true,"reaction":"Encik Zahar terdiam dan menarik tangannya."},{"text":"Supaya kad nampak cantik.","isCorrect":false,"reaction":"Tok menggeleng. Gelaran bukan hiasan."},{"text":"Supaya semua ketua sama gelaran.","isCorrect":false,"reaction":"Tok menggeleng. Gelaran berbeza menunjukkan keunikan."}],"clue":"Gelaran berbeza menanam hormat dan taat setia kepada raja."}]}'),
(222, 'e2_n2_s4', 'Dokumen Yang di-Pertua Negeri', 'Bantu pembantu memilih dokumen negeri yang menggunakan gelaran Yang di-Pertua Negeri.', '3', 'Membantu NPC memilih dokumen: Pulau Pinang, Melaka, Sarawak dan Sabah.', '{"npcName":"Pembantu Yang di-Pertua Negeri","prompt":"Dokumen mana yang menyenaraikan negeri bergelar Yang di-Pertua Negeri?","options":[{"text":"Pulau Pinang, Melaka, Sarawak dan Sabah","item":"dokumen","isCorrect":true},{"text":"Pulau Pinang, Melaka dan Perlis","item":"dokumen","isCorrect":false,"consequence":"Perlis bergelar Raja, jadi tuan dibawa ke majlis yang salah."},{"text":"Sabah, Sarawak dan Johor","item":"dokumen","isCorrect":false,"consequence":"Johor bergelar Sultan, jadi tuan dibawa ke majlis yang salah."},{"text":"Negeri Sembilan, Pahang dan Sabah","item":"dokumen","isCorrect":false,"consequence":"Negeri Sembilan bergelar Yang di-Pertuan Besar dan Pahang Sultan."}],"aftermath":"Pembantu membawa tuannya ke majlis yang salah.","turns":[{"after":6,"options":[{"text":"Yang di-Pertuan Agong.","isCorrect":true,"reaction":"Pembantu mengangguk dan mencatat jawapan itu."},{"text":"Sultan Selangor.","isCorrect":false,"reaction":"Pembantu menggeleng. Ketua Wilayah Persekutuan bukan sultan negeri."},{"text":"Yang di-Pertua Negeri.","isCorrect":false,"reaction":"Pembantu menggeleng. Gelaran itu untuk empat negeri sahaja."}],"clue":"Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong."}]}'),
(223, 'e2_n2_s5', 'Piagam Sembilan Luak', 'Nyahkod piagam dan tentukan tahun sembilan luak asal Negeri Sembilan.', '5', 'Mengenal pasti tahun 1773 bagi sembilan luak asal Negeri Sembilan.', '{"clueText":"Piagam: Negeri Sembilan bermula daripada sembilan luak. Nagari bermaksud wilayah dalam dialek Minangkabau. Tahun piagam ini ialah tahun gabungan itu dicatat.","options":[{"text":"1773","isCorrect":true},{"text":"1877","isCorrect":false,"consequence":"Itu tahun dokumen Sabah, bukan Negeri Sembilan."},{"text":"1887","isCorrect":false,"consequence":"Tahun itu tiada dalam piagam Negeri Sembilan."},{"text":"1673","isCorrect":false,"consequence":"Tarikh itu terlalu awal dan penghulu menggeleng."}],"aftermath":"Penghulu menegur Pegawai kerana kad pengacara tersilap.","turns":[{"after":6,"options":[{"text":"Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.","isCorrect":true,"reaction":"Penghulu mengangguk. Sembilan luak dicatat."},{"text":"Kedah, Perak, Perlis, Johor, Pahang, Melaka, Kelantan, Terengganu dan Sabah.","isCorrect":false,"reaction":"Penghulu menggeleng. Itu negeri, bukan luak."},{"text":"Sembilan pulau di Selat Melaka.","isCorrect":false,"reaction":"Penghulu ketawa. Itu bukan luak."}],"clue":"Luak asal ialah Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang."}]}'),
(224, 'e2_n2_s6', 'Nota di Akar Pokok', 'Nyahkod nota dan tentukan nama Johor dalam Sulalatus Salatin.', '5', 'Mengenal pasti Ujong Tanah sebagai nama Johor dalam Sulalatus Salatin.', '{"clueText":"Nota: Dalam naskhah Sulalatus Salatin, Johor disebut dengan nama hujung sebuah daratan.","options":[{"text":"Ujong Tanah","isCorrect":true},{"text":"Inderapura","isCorrect":false,"consequence":"Itu nama Pahang dalam naskhah yang sama."},{"text":"Malakat","isCorrect":false,"consequence":"Itu perhimpunan pedagang bagi Melaka."},{"text":"Kadaram","isCorrect":false,"consequence":"Itu nama Kedah dalam tulisan Tamil."}],"aftermath":"Encik Zahar mengubah nota supaya nama Johor tersalah.","turns":[{"after":6,"options":[{"text":"Perkataan Arab \'Jauhar\' bermaksud batu permata bernilai, cerita kedua Johor. Malakat pula perhimpunan pedagang.","isCorrect":true,"reaction":"Peniaga mengangguk. Dua negeri dicatat."},{"text":"Jauhar ialah nama pokok di Melaka.","isCorrect":false,"reaction":"Peniaga menggeleng. Jauhar ialah batu permata."},{"text":"Jauhar ialah nama sungai di Johor.","isCorrect":false,"reaction":"Peniaga menggeleng. Jauhar ialah batu permata."}],"clue":"Jauhar bermaksud batu permata. Malakat perhimpunan pedagang."}]}'),
(225, 'e2_n2_s7', 'Fail yang Dicuri', 'Padankan ibu negeri dengan bandar dirajanya.', '4', 'Memadankan Shah Alam-Klang, Seremban-Seri Menanti, Johor Bahru-Bandar Maharani dan Bandar Melaka dengan tiada bandar diraja.', '{"pairs":[{"text":"Shah Alam (Selangor)","pair":1},{"text":"Klang","pair":1},{"text":"Seremban (Negeri Sembilan)","pair":2},{"text":"Seri Menanti","pair":2},{"text":"Johor Bahru (Johor)","pair":3},{"text":"Bandar Maharani","pair":3},{"text":"Bandar Melaka (Melaka)","pair":4},{"text":"Tiada bandar diraja ditanda pada peta","pair":4}],"aftermath":"Surat jemputan dihantar ke bandar yang salah.","turns":[{"after":6,"options":[{"text":"Kerana pembangunan pentadbiran, kemudahan asas, institusi pendidikan dan tumpuan pekerjaan.","isCorrect":true,"reaction":"Setiausaha mengangguk dan mencatat empat sebab itu."},{"text":"Kerana ia dekat dengan pantai.","isCorrect":false,"reaction":"Setiausaha menggeleng. Itu bukan sebab dalam buku."},{"text":"Kerana ia mempunyai istana.","isCorrect":false,"reaction":"Setiausaha menggeleng. Istana ada di bandar diraja."}],"clue":"Ibu negeri berkembang kerana pentadbiran, kemudahan, pendidikan dan pekerjaan."}]}'),
(226, 'e2_n2_s8', 'Empat Kaset Tanpa Label', 'Padankan setiap lagu dengan negerinya.', '4', 'Memadankan Duli Yang Maha Mulia, Berkatlah Yang di-Pertuan Besar, Melaka Maju Jaya dan Lagu Bangsa Johor.', '{"pairs":[{"text":"Duli Yang Maha Mulia","pair":1},{"text":"Selangor","pair":1},{"text":"Berkatlah Yang di-Pertuan Besar","pair":2},{"text":"Negeri Sembilan","pair":2},{"text":"Melaka Maju Jaya","pair":3},{"text":"Melaka","pair":3},{"text":"Lagu Bangsa Johor","pair":4},{"text":"Johor","pair":4}],"aftermath":"Lagu yang salah dimainkan dan tetamu menunduk malu.","turns":[{"after":6,"options":[{"text":"Ia lambang kemegahan dan kedaulatan negeri.","isCorrect":true,"reaction":"Jururadio mengangguk dan menyusun kaset itu."},{"text":"Ia hanya hiburan.","isCorrect":false,"reaction":"Jururadio menggeleng. Lagu negeri lambang kedaulatan."},{"text":"Ia untuk mengiklankan negeri.","isCorrect":false,"reaction":"Jururadio menggeleng. Itu bukan sebab dalam buku."}],"clue":"Lagu negeri ialah lambang kemegahan dan kedaulatan."}]}'),
(227, 'e2_n2_s9', 'Empat Kad di Peti Pos', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan prow-lowy, peroleh, kilatan ikan dan bijih timah putih dengan Perlis atau Perak.', '{"pairs":[{"text":"Prow-lowy","pair":1},{"text":"Kelapa hanyut (Perlis)","pair":1},{"text":"Peroleh","pair":2},{"text":"Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail","pair":2},{"text":"Kilatan ikan","pair":3},{"text":"Ikan berkilau seperti perak (Perak)","pair":3},{"text":"Bijih timah putih berkilat","pair":4},{"text":"Pandangan lain tentang nama Perak","pair":4}],"aftermath":"Pesawah dan pelombong menegur kekeliruan Pegawai.","turns":[{"after":6,"options":[{"text":"Yang menerima mandat kerana membantu Perlis menentang Siam.","isCorrect":true,"reaction":"Pesawah mengangguk dan tersenyum."},{"text":"Seorang pedagang Arab di Perlis.","isCorrect":false,"reaction":"Pesawah menggeleng. Dia pembesar yang menerima mandat."},{"text":"Seorang pelombong di Perak.","isCorrect":false,"reaction":"Pesawah menggeleng. Dia berkait dengan Perlis."}],"clue":"Raja Syed Hussin menerima mandat kerana membantu Perlis menentang Siam."}]}'),
(228, 'e2_n2_s10', 'Nama di Jeti', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan Pulo Ka Satu, Tanjong Penaga, pinang, qadah dan kadaram.', '{"pairs":[{"text":"Pulo Ka Satu","pair":1},{"text":"Nama asal Pulau Pinang","pair":1},{"text":"Tanjong Penaga","pair":2},{"text":"Gelaran orang Melayu Kedah kerana banyak pokok penaga","pair":2},{"text":"Buah pinang","pair":3},{"text":"Bahan dagangan penting yang dikaitkan dengan Pulau Pinang","pair":3},{"text":"Qadah","pair":4},{"text":"Cawan atau gelas berkaki yang dijual pedagang Arab","pair":4},{"text":"Kadaram","pair":5},{"text":"Nama Kedah dalam tulisan Tamil","pair":5}],"aftermath":"Sampul tidak ditemui dan Zahar berpeluang menukar dokumen.","turns":[{"after":6,"options":[{"text":"Buah pinang bahan dagangan penting yang dikaitkan dengan nama Pulau Pinang.","isCorrect":true,"reaction":"Nelayan mengangguk dan menunjuk karung pinang."},{"text":"Kerana pulau itu berbentuk pinang.","isCorrect":false,"reaction":"Nelayan menggeleng. Itu bukan sebab dalam buku."},{"text":"Kerana pinang ditanam di Kedah sahaja.","isCorrect":false,"reaction":"Nelayan menggeleng. Pinang barang dagangan di sini."}],"clue":"Pinang bahan dagangan penting yang dikaitkan dengan nama Pulau Pinang."}]}'),
(229, 'e2_n2_s11', 'Dokumen Ibu Negeri Utara', 'Bantu pegawai daerah memilih dokumen ibu negeri dan bandar diraja yang betul.', '3', 'Membantu NPC memilih dokumen: Kangar-Arau, Alor Setar-Anak Bukit, Ipoh-Kuala Kangsar, George Town.', '{"npcName":"Pegawai Daerah","prompt":"Dokumen mana yang betul untuk Perlis, Kedah, Perak dan Pulau Pinang?","options":[{"text":"Kangar dan Arau; Alor Setar dan Anak Bukit; Ipoh dan Kuala Kangsar; George Town","item":"dokumen","isCorrect":true},{"text":"Arau ibu negeri Perlis; Kangar bandar diraja","item":"dokumen","isCorrect":false,"consequence":"Jemputan dihantar ke Arau dan Kangar ditinggalkan."},{"text":"Anak Bukit ibu negeri Kedah; Alor Setar bandar diraja","item":"dokumen","isCorrect":false,"consequence":"Jemputan dihantar ke bandar yang salah."},{"text":"Kuala Kangsar ibu negeri Perak; Ipoh bandar diraja","item":"dokumen","isCorrect":false,"consequence":"Jemputan Perak sampai ke tempat yang salah."}],"aftermath":"Jemputan dihantar ke bandar yang salah.","turns":[{"after":6,"options":[{"text":"Ia menyimpan warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan monumen.","isCorrect":true,"reaction":"Pegawai Daerah mengangguk dan menyimpan fail itu."},{"text":"Ia tempat membuat jemputan.","isCorrect":false,"reaction":"Pegawai Daerah menggeleng. Itu bukan sebab dalam buku."},{"text":"Ia hanya untuk pelancong.","isCorrect":false,"reaction":"Pegawai Daerah menggeleng. Ia menyimpan warisan sejarah."}],"clue":"Bandar diraja menyimpan warisan sejarah."}]}'),
(230, 'e2_n2_s12', 'Nota Aamiin-Aamiin', 'Nyahkod nota dan tentukan negeri pemilik lagu Aamiin-Aamiin.', '5', 'Mengenal pasti Perlis sebagai pemilik lagu Aamiin-Aamiin.', '{"clueText":"Nota: Lagu Aamiin-Aamiin dimainkan apabila Raja negeri ini hadir.","options":[{"text":"Perlis","isCorrect":true},{"text":"Perak","isCorrect":false,"consequence":"Perak bergelar Sultan, bukan Raja."},{"text":"Kedah","isCorrect":false,"consequence":"Kedah bergelar Sultan, bukan Raja."},{"text":"Pulau Pinang","isCorrect":false,"consequence":"Pulau Pinang bergelar Yang di-Pertua Negeri."}],"aftermath":"Raja Perlis tidak disambut dengan lagu negerinya.","turns":[{"after":6,"options":[{"text":"Allah Lanjutkan Usia Sultan (Perak), Allah Selamatkan Sultan Mahkota (Kedah) dan Untuk Negeri Kita (Pulau Pinang).","isCorrect":true,"reaction":"Jururadio mengangguk dan mencatat semua tajuk."},{"text":"Semua bertajuk Aamiin-Aamiin.","isCorrect":false,"reaction":"Jururadio menggeleng. Setiap negeri ada tajuk sendiri."},{"text":"Tiada lagu untuk tiga negeri itu.","isCorrect":false,"reaction":"Jururadio menunjuk senarai lagu negeri dalam buku teks."}],"clue":"Perak, Kedah dan Pulau Pinang masing-masing ada lagu tersendiri."}]}'),
(231, 'e2_n2_s13', 'Enam Cerita Pantai Timur', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan mahang, Inderapura, taring anu, terangnya ganu, kilatan dan gelam hutan.', '{"pairs":[{"text":"Mahang","pair":1},{"text":"Pokok yang melahirkan nama Pahang","pair":1},{"text":"Inderapura atau Pura","pair":2},{"text":"Nama Pahang dalam Sulalatus Salatin; pura ialah bandar","pair":2},{"text":"Taring anu","pair":3},{"text":"Taring besar seperti gading gajah di Pulau Duyong","pair":3},{"text":"Terangnya ganu","pair":4},{"text":"Pelangi","pair":4},{"text":"Kilatan","pair":5},{"text":"Cahaya terang yang dilihat orang Melayu Patani","pair":5},{"text":"Gelam hutan atau kelam hutan","pair":6},{"text":"Pokok di pesisir pantai Kelantan","pair":6}],"aftermath":"Peta Zahar tidak ditemui dan Pegawai tersilap nama di hadapan penduduk.","turns":[{"after":6,"options":[{"text":"Masyarakat Melayu Patani.","isCorrect":true,"reaction":"Pencerita mengangguk. Cerita Patani dicatat."},{"text":"Orang Minangkabau.","isCorrect":false,"reaction":"Pencerita menggeleng. Minangkabau berkait dengan nagari."},{"text":"Pedagang Arab.","isCorrect":false,"reaction":"Pencerita menggeleng. Arab berkait dengan Malakat dan Jauhar."}],"clue":"Kilatan dilihat oleh masyarakat Melayu Patani."}]}'),
(232, 'e2_n2_s14', 'Kad Bilik Peta', 'Padankan kad dengan ibu negeri atau bandar diraja yang betul.', '4', 'Memadankan ibu negeri Pahang Kuantan, bandar diraja Pahang Pekan, ibu negeri Terengganu Kuala Terengganu dan ibu negeri Kelantan Kota Bharu.', '{"pairs":[{"text":"Ibu negeri Pahang","pair":1},{"text":"Kuantan","pair":1},{"text":"Bandar diraja Pahang","pair":2},{"text":"Pekan","pair":2},{"text":"Ibu negeri Terengganu","pair":3},{"text":"Kuala Terengganu","pair":3},{"text":"Ibu negeri Kelantan","pair":4},{"text":"Kota Bharu","pair":4}],"aftermath":"Surat jemputan istiadat ke Pekan dihantar ke Kuantan.","turns":[{"after":6,"options":[{"text":"Memelihara dan memulihara serta menghargai warisan sejarah di situ.","isCorrect":true,"reaction":"Pegawai mengangguk dan berjanji menjaga istana lama."},{"text":"Meruntuhkan bangunan lama.","isCorrect":false,"reaction":"Pegawai menggeleng. Warisan perlu dijaga."},{"text":"Membiarkan sahaja.","isCorrect":false,"reaction":"Pegawai menggeleng. Warisan akan rosak jika dibiarkan."}],"clue":"Warisan sejarah perlu dipelihara dan dipulihara."}]}'),
(233, 'e2_n2_s15', 'Kaset Lagu Pahang', 'Bantu jururadio memilih kaset lagu negeri Pahang.', '3', 'Membantu NPC memilih kaset lagu Pahang: Allah Selamatkan Sultan Kami.', '{"npcName":"Jururadio","prompt":"Kaset mana ialah lagu negeri Pahang?","options":[{"text":"Allah Selamatkan Sultan Kami","item":"kaset","isCorrect":true},{"text":"Sabah Tanah Airku","item":"kaset","isCorrect":false,"consequence":"Lagu Sabah dimainkan di hadapan Sultan Pahang."},{"text":"Allah Lanjutkan Usia Sultan","item":"kaset","isCorrect":false,"consequence":"Lagu Perak dimainkan di hadapan Sultan Pahang."},{"text":"Melaka Maju Jaya","item":"kaset","isCorrect":false,"consequence":"Lagu Melaka dimainkan di hadapan Sultan Pahang."}],"aftermath":"Lagu negeri lain dimainkan di hadapan Sultan Pahang.","turns":[{"after":6,"options":[{"text":"Lagu Terengganu dan lagu Kelantan, dua negeri berkongsi tajuk yang sama.","isCorrect":true,"reaction":"Jururadio mengangguk dan mencatat dua negeri itu."},{"text":"Lagu Pahang dan Perak.","isCorrect":false,"reaction":"Jururadio menggeleng. Tajuk itu bukan milik mereka."},{"text":"Lagu Sabah dan Sarawak.","isCorrect":false,"reaction":"Jururadio menggeleng. Tajuk itu dikongsi dua negeri pantai timur."}],"clue":"Selamat Sultan ialah lagu Terengganu dan Kelantan."}]}'),
(234, 'e2_n2_s16', 'Surat dari Sabah', 'Nyahkod surat dan tentukan tahun dokumen Maharajah of Sabah serta buah yang dikaitkan dengan Sabah.', '5', 'Mengenal pasti 1877 dan pisang saba.', '{"clueText":"Surat: Nama Sabah tercatat dalam dokumen sejarah bertajuk Maharajah of Sabah pada tahun ini, dan dikaitkan dengan sejenis buah yang ditanam di pantai barat.","options":[{"text":"1877 dan pisang saba","isCorrect":true},{"text":"1773 dan mahang","isCorrect":false,"consequence":"1773 ialah tahun luak Negeri Sembilan dan mahang berkait dengan Pahang."},{"text":"1887 dan penaga","isCorrect":false,"consequence":"Tahun itu tiada dalam dokumen dan penaga berkait dengan Pulau Pinang."},{"text":"1877 dan pinang","isCorrect":false,"consequence":"Tahun betul tetapi buahnya pisang saba, bukan pinang."}],"aftermath":"Pengacara menyebut tahun salah di hadapan tetamu Sabah.","turns":[{"after":6,"options":[{"text":"Sungai Serak menjadi Sungai Sarawak, bersempena bijih galian bernama sarawak; juga cerava, antimoni, panggilan Portugis.","isCorrect":true,"reaction":"Pesawah mengangguk. Dua cerita dicatat."},{"text":"Sarawak dari pokok mentagau.","isCorrect":false,"reaction":"Pesawah menggeleng. Mentagau berkait dengan Selangor."},{"text":"Sarawak dari kelapa hanyut.","isCorrect":false,"reaction":"Pesawah menggeleng. Itu cerita Perlis."}],"clue":"Sarawak: Sungai Serak, bijih sarawak atau cerava."}]}'),
(235, 'e2_n2_s17', 'Borneo di Talian', 'Padankan setiap kad dengan jawapannya.', '4', 'Memadankan Kuching, Kota Kinabalu, Sabah Tanah Airku, Ibu Pertiwiku dan Maju dan Sejahtera.', '{"pairs":[{"text":"Kuching","pair":1},{"text":"Ibu negeri Sarawak","pair":1},{"text":"Kota Kinabalu","pair":2},{"text":"Ibu negeri Sabah","pair":2},{"text":"Sabah Tanah Airku","pair":3},{"text":"Lagu Sabah","pair":3},{"text":"Ibu Pertiwiku","pair":4},{"text":"Lagu Sarawak","pair":4},{"text":"Maju dan Sejahtera","pair":5},{"text":"Lagu Wilayah Persekutuan","pair":5}],"aftermath":"Lagu Sarawak dimainkan untuk Sabah.","turns":[{"after":6,"options":[{"text":"Ia identiti dan lambang kemegahan negeri.","isCorrect":true,"reaction":"Pegawai mengangguk dan menamatkan panggilan."},{"text":"Ia hanya hiasan.","isCorrect":false,"reaction":"Pegawai menggeleng. Lambang ialah identiti negeri."},{"text":"Ia supaya negeri lain takut.","isCorrect":false,"reaction":"Pegawai menggeleng. Ia bukan untuk menakutkan."}],"clue":"Lambang negeri ialah identiti dan kemegahan."}]}'),
(236, 'e2_n2_s18', 'Bukti di Dewan', 'Cari tiga lambang negeri di dewan: jata, bendera dan radio lagu.', '2', 'Mencari bukti lambang negeri: jata, bendera dan lagu sebagai identiti dan kemegahan.', '{"bgImage":"../assets/gameAsset/background/wilayah_persekutuan.png","hotspots":[{"name":"Jata: lambang kedaulatan negeri","top":"40.4%","left":"70%"},{"name":"Bendera: lambang identiti negeri","top":"20.9%","left":"72.7%"},{"name":"Radio: lagu Maju dan Sejahtera","top":"86.4%","left":"74.1%"}],"aftermath":"Zahar menukar kad dan majlis tersasar.","turns":[{"after":5,"options":[{"text":"Bendera, lagu dan jata ialah identiti dan lambang kemegahan setiap negeri; mengenalinya menaikkan rasa cinta akan negara.","isCorrect":true,"reaction":"Tetamu bertepuk tangan. Zahar menunduk dan pergi."},{"text":"Kerana ia hiasan sahaja.","isCorrect":false,"reaction":"Pengacara menggeleng. Lambang ialah identiti negeri."},{"text":"Supaya negeri lain takut.","isCorrect":false,"reaction":"Pengacara menggeleng. Ia bukan untuk menakutkan."}],"clue":"Lambang negeri ialah identiti dan kemegahan."}]}'),
(237, 'e2_n3_s1', 'Cop Pertama: Sabah', 'Padankan setiap petunjuk nama Sabah dengan maksudnya.', '4', 'Memadankan pisang saba, Maharajah of Sabah dan 1877.', '{"pairs":[{"text":"Pisang saba","pair":1},{"text":"Pisang yang banyak ditanam di pantai barat Sabah sebagai sumber makanan","pair":1},{"text":"Maharajah of Sabah","pair":2},{"text":"Dokumen sejarah yang mencatat nama Sabah","pair":2},{"text":"1877","pair":3},{"text":"Tahun dokumen itu","pair":3}],"aftermath":"Penjaga menolak cop dan Pengembara terpaksa mengulang.","turns":[{"after":6,"options":[{"text":"Pisang yang banyak ditanam di pantai barat Sabah sebagai sumber makanan.","isCorrect":true,"reaction":"Penjaga mengangguk dan menekan cop."},{"text":"Pisang yang hanya untuk hiasan.","isCorrect":false,"reaction":"Penjaga menggeleng. Ia sumber makanan."},{"text":"Pisang yang ditanam di Perlis.","isCorrect":false,"reaction":"Penjaga menggeleng. Ia ditanam di pantai barat Sabah."}],"clue":"Pisang saba ditanam di pantai barat Sabah sebagai makanan."}]}'),
(238, 'e2_n3_s2', 'Surat Berlogam', 'Nyahkod surat dan tentukan asal nama Sarawak.', '5', 'Mengenal pasti Sungai Serak menjadi Sungai Sarawak.', '{"clueText":"Surat: Nama Sarawak berubah daripada nama sungai kecil kepada nama sungai besar, bersempena sejenis galian bijih.","options":[{"text":"Sungai Serak menjadi Sungai Sarawak","isCorrect":true},{"text":"Sungai Gombak menjadi Sungai Klang","isCorrect":false,"consequence":"Itu sungai berkait dengan Kuala Lumpur."},{"text":"Pulo Ka Satu menjadi Pulau Pinang","isCorrect":false,"consequence":"Itu nama asal Pulau Pinang."},{"text":"Ujong Tanah menjadi Johor","isCorrect":false,"consequence":"Itu nama Johor dalam naskhah klasik."}],"aftermath":"Penjaga menggeleng dan menutup pondok.","turns":[{"after":6,"options":[{"text":"Panggilan Portugis dikaitkan dengan \'cerava\', sejenis logam antimoni.","isCorrect":true,"reaction":"Penjaga mengangguk dan menekan cop."},{"text":"Cerava ialah sejenis pokok.","isCorrect":false,"reaction":"Penjaga menggeleng. Ia logam antimoni."},{"text":"Cerava ialah nama sungai.","isCorrect":false,"reaction":"Penjaga menggeleng. Ia logam antimoni."}],"clue":"Cerava ialah antimoni, panggilan Portugis."}]}'),
(239, 'e2_n3_s3', 'Kad Borneo', 'Padankan setiap kad dengan jawapannya.', '4', 'Memadankan Kuching, Kota Kinabalu, Sabah Tanah Airku, Ibu Pertiwiku dan Yang di-Pertua Negeri.', '{"pairs":[{"text":"Kuching","pair":1},{"text":"Ibu negeri Sarawak","pair":1},{"text":"Kota Kinabalu","pair":2},{"text":"Ibu negeri Sabah","pair":2},{"text":"Sabah Tanah Airku","pair":3},{"text":"Lagu Sabah","pair":3},{"text":"Ibu Pertiwiku","pair":4},{"text":"Lagu Sarawak","pair":4},{"text":"Yang di-Pertua Negeri","pair":5},{"text":"Gelaran ketua Sabah dan Sarawak","pair":5}],"aftermath":"Cop ditahan sehingga padanan betul.","turns":[{"after":6,"options":[{"text":"Yang di-Pertuan Agong.","isCorrect":true,"reaction":"Pegawai Sabah mengangguk dan menandatangani kad."},{"text":"Yang di-Pertua Negeri.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu untuk Sabah dan Sarawak."},{"text":"Sultan.","isCorrect":false,"reaction":"Pegawai menggeleng. Wilayah Persekutuan bukan negeri bersultan."}],"clue":"Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong."}]}'),
(240, 'e2_n3_s4', 'Dokumen Tiga Nama', 'Bantu pemandu pelancong memilih dokumen yang betul tentang nama tiga wilayah.', '3', 'Membantu NPC memilih dokumen: lumpur, labuhan dan Putra + jaya.', '{"npcName":"Pemandu Pelancong","prompt":"Dokumen mana yang menerangkan asal nama Kuala Lumpur, Labuan dan Putrajaya dengan betul?","options":[{"text":"Kuala Lumpur: muara berlumpur; Labuan: labuhan kapal; Putrajaya: Tunku Abdul Rahman Putra","item":"dokumen","isCorrect":true},{"text":"Kuala Lumpur: pelangi; Labuan: labuhan kapal; Putrajaya: Tunku Abdul Rahman Putra","item":"dokumen","isCorrect":false,"consequence":"Pelancong menyalin nama yang salah tentang pelangi."},{"text":"Kuala Lumpur: muara berlumpur; Labuan: pokok penaga; Putrajaya: Tunku Abdul Rahman Putra","item":"dokumen","isCorrect":false,"consequence":"Penaga ialah cerita Pulau Pinang, bukan Labuan."},{"text":"Kuala Lumpur: muara berlumpur; Labuan: labuhan kapal; Putrajaya: pisang saba","item":"dokumen","isCorrect":false,"consequence":"Pisang saba ialah cerita Sabah, bukan Putrajaya."}],"aftermath":"Pelancong menyalin nama yang salah.","turns":[{"after":6,"options":[{"text":"Kuala Lumpur, Labuan dan Putrajaya.","isCorrect":true,"reaction":"Pemandu mengangguk dan membawa pelancong ke pentas."},{"text":"Kuala Lumpur, Johor dan Sabah.","isCorrect":false,"reaction":"Pemandu menggeleng. Johor dan Sabah ialah negeri."},{"text":"Putrajaya, Melaka dan Pulau Pinang.","isCorrect":false,"reaction":"Pemandu menggeleng. Melaka dan Pulau Pinang ialah negeri."}],"clue":"Wilayah Persekutuan: Kuala Lumpur, Labuan dan Putrajaya."}]}'),
(241, 'e2_n3_s5', 'Nota di Bawah Kad', 'Nyahkod nota dan tentukan wilayah yang dimaksudkan.', '5', 'Mengenal pasti Wilayah Persekutuan.', '{"clueText":"Nota: Lagu Maju dan Sejahtera dimainkan untuk wilayah yang ketuanya ialah Yang di-Pertuan Agong, dan wilayah ini tidak mempunyai ibu negeri dan bandar diraja.","options":[{"text":"Wilayah Persekutuan","isCorrect":true},{"text":"Negeri Sembilan","isCorrect":false,"consequence":"Negeri Sembilan ketuanya Yang di-Pertuan Besar."},{"text":"Melaka","isCorrect":false,"consequence":"Melaka ketuanya Yang di-Pertua Negeri."},{"text":"Sabah","isCorrect":false,"consequence":"Sabah ketuanya Yang di-Pertua Negeri."}],"aftermath":"Penjaga memadam nota dan Pengembara terpaksa mengulang.","turns":[{"after":6,"options":[{"text":"Ketuanya Yang di-Pertuan Agong dan ibu negerinya tiada.","isCorrect":true,"reaction":"Penjaga mengangguk dan menekan cop."},{"text":"Ketuanya Sultan dan ibu negerinya Putrajaya.","isCorrect":false,"reaction":"Penjaga menggeleng. Wilayah Persekutuan tiada ibu negeri."},{"text":"Ketuanya Raja dan ibu negerinya Kuala Lumpur.","isCorrect":false,"reaction":"Penjaga menggeleng. Ketuanya bukan Raja."}],"clue":"Ketua Yang di-Pertuan Agong; tiada ibu negeri."}]}'),
(242, 'e2_n3_s6', 'Nota Batu Permata', 'Nyahkod nota dan tentukan perkataan yang melahirkan nama Johor.', '5', 'Mengenal pasti Jauhar sebagai asal nama Johor.', '{"clueText":"Nota: Nama Johor dikatakan berasal daripada perkataan Arab bagi batu permata yang bernilai.","options":[{"text":"Jauhar","isCorrect":true},{"text":"Malakat","isCorrect":false,"consequence":"Itu perhimpunan pedagang bagi Melaka."},{"text":"Mahang","isCorrect":false,"consequence":"Itu pokok yang melahirkan nama Pahang."},{"text":"Kheddah","isCorrect":false,"consequence":"Itu perangkap gajah bagi nama Kedah."}],"aftermath":"Penjaga tidak memberi cop kerana nota tidak dinyahkod.","turns":[{"after":6,"options":[{"text":"Bahasa Arab, bermaksud batu permata yang bernilai.","isCorrect":true,"reaction":"Peniaga mengangguk dan tersenyum."},{"text":"Bahasa Siam, bermaksud kelapa hanyut.","isCorrect":false,"reaction":"Peniaga menggeleng. Itu cerita Perlis."},{"text":"Bahasa Tamil, bermaksud cawan.","isCorrect":false,"reaction":"Peniaga menggeleng. Itu cerita lain."}],"clue":"Jauhar ialah bahasa Arab, batu permata bernilai."}]}'),
(243, 'e2_n3_s7', 'Pusat dan Istana Johor', 'Padankan setiap kad dengan jawapan untuk Johor.', '4', 'Memadankan Johor Bahru, Bandar Maharani, Lagu Bangsa Johor dan Sultan.', '{"pairs":[{"text":"Johor Bahru","pair":1},{"text":"Ibu negeri Johor","pair":1},{"text":"Bandar Maharani","pair":2},{"text":"Bandar diraja Johor","pair":2},{"text":"Lagu Bangsa Johor","pair":3},{"text":"Lagu Johor","pair":3},{"text":"Sultan","pair":4},{"text":"Gelaran ketua Johor","pair":4}],"aftermath":"Cop ditahan dan Pengembara diminta mencuba lagi.","turns":[{"after":6,"options":[{"text":"Ia menyimpan warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan monumen.","isCorrect":true,"reaction":"Pegawai mengangguk dan menekan cop."},{"text":"Ia tempat membeli barang.","isCorrect":false,"reaction":"Pegawai menggeleng. Ia menyimpan warisan."},{"text":"Ia pusat pentadbiran sahaja.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu ibu negeri."}],"clue":"Bandar diraja menyimpan warisan sejarah."}]}'),
(244, 'e2_n3_s8', 'Nota di Akar Pokok', 'Nyahkod nota dan tentukan binatang yang menendang anjing.', '5', 'Mengenal pasti pelanduk putih.', '{"clueText":"Nota: Parameswara berehat di bawah pokok ini ketika seekor binatang kecil putih menendang anjing pemburuannya.","options":[{"text":"Pelanduk putih","isCorrect":true},{"text":"Gajah putih","isCorrect":false,"consequence":"Gajah terlalu besar untuk binatang kecil."},{"text":"Harimau putih","isCorrect":false,"consequence":"Harimau bukan binatang kecil."},{"text":"Kijang","isCorrect":false,"consequence":"Kijang tidak putih dan nota menyebut binatang kecil."}],"aftermath":"Orang tua menyindir kerana Pengembara tersilap binatang.","turns":[{"after":6,"options":[{"text":"Sumber Arab menyebut Malakat, perhimpunan para pedagang.","isCorrect":true,"reaction":"Peniaga mengangguk dan tersenyum."},{"text":"Malakat ialah nama pokok.","isCorrect":false,"reaction":"Peniaga menggeleng. Ia perhimpunan pedagang."},{"text":"Malakat ialah nama anjing.","isCorrect":false,"reaction":"Peniaga ketawa dan menggeleng."}],"clue":"Malakat bermaksud perhimpunan para pedagang."}]}'),
(245, 'e2_n3_s9', 'Kaset Lagu Melaka', 'Bantu pegawai radio memilih kaset lagu negeri Melaka.', '3', 'Membantu NPC memilih kaset Melaka Maju Jaya.', '{"npcName":"Pegawai Radio","prompt":"Kaset mana ialah lagu negeri Melaka?","options":[{"text":"Melaka Maju Jaya","item":"kaset","isCorrect":true},{"text":"Lagu Bangsa Johor","item":"kaset","isCorrect":false,"consequence":"Lagu Johor dimainkan di hadapan ketua Melaka."},{"text":"Duli Yang Maha Mulia","item":"kaset","isCorrect":false,"consequence":"Lagu Selangor dimainkan di hadapan ketua Melaka."},{"text":"Untuk Negeri Kita","item":"kaset","isCorrect":false,"consequence":"Lagu Pulau Pinang dimainkan di hadapan ketua Melaka."}],"aftermath":"Lagu negeri lain dimainkan.","turns":[{"after":6,"options":[{"text":"Bandar Melaka. Peta tidak menandakan bandar diraja di sana.","isCorrect":true,"reaction":"Pegawai mengangguk dan menekan cop."},{"text":"Bandar Maharani.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu bandar diraja Johor."},{"text":"Seremban.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu ibu negeri Negeri Sembilan."}],"clue":"Ibu negeri Melaka ialah Bandar Melaka."}]}'),
(246, 'e2_n3_s10', 'Sembilan Kerusi', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan nagari, 1773 dan luak asal.', '{"pairs":[{"text":"Nagari","pair":1},{"text":"Wilayah dalam dialek Minangkabau","pair":1},{"text":"1773","pair":2},{"text":"Tahun luak asal Negeri Sembilan","pair":2},{"text":"Sungai Ujong dan Jelebu","pair":3},{"text":"Antara luak asal Negeri Sembilan","pair":3},{"text":"Segamat dan Klang","pair":4},{"text":"Antara luak asal juga","pair":4}],"aftermath":"Penghulu menegur dan cop ditahan.","turns":[{"after":6,"options":[{"text":"Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.","isCorrect":true,"reaction":"Penghulu mengangguk dan menekan cop."},{"text":"Kedah, Perak, Perlis, Johor, Pahang, Melaka, Kelantan, Terengganu dan Sabah.","isCorrect":false,"reaction":"Penghulu menggeleng. Itu negeri, bukan luak."},{"text":"Sembilan pulau di selat.","isCorrect":false,"reaction":"Penghulu ketawa. Itu bukan luak."}],"clue":"Luak asal ialah Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang."}]}'),
(247, 'e2_n3_s11', 'Istana Negeri Sembilan', 'Padankan setiap kad dengan jawapan untuk Negeri Sembilan.', '4', 'Memadankan Seremban, Seri Menanti, Berkatlah Yang di-Pertuan Besar dan Yang di-Pertuan Besar.', '{"pairs":[{"text":"Seremban","pair":1},{"text":"Ibu negeri Negeri Sembilan","pair":1},{"text":"Seri Menanti","pair":2},{"text":"Bandar diraja Negeri Sembilan","pair":2},{"text":"Berkatlah Yang di-Pertuan Besar","pair":3},{"text":"Lagu Negeri Sembilan","pair":3},{"text":"Yang di-Pertuan Besar","pair":4},{"text":"Gelaran ketua Negeri Sembilan","pair":4}],"aftermath":"Cop ditahan.","turns":[{"after":6,"options":[{"text":"Sikap menghormati dan taat setia kepada raja dapat dipupuk.","isCorrect":true,"reaction":"Pegawai mengangguk dan menekan cop."},{"text":"Supaya kita dapat bergelar raja.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu bukan sebab dalam buku."},{"text":"Supaya kita dapat mengundi mereka.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu bukan sebab dalam buku."}],"clue":"Mengenali ketua negeri memupuk hormat dan taat setia."}]}'),
(248, 'e2_n3_s12', 'Kuala dan Pura', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan mentagau, selangur, mahang dan Inderapura.', '{"pairs":[{"text":"Mentagau","pair":1},{"text":"Pokok di kuala sungai Selangor","pair":1},{"text":"Selangur atau sangur","pair":2},{"text":"Serangga banyak di sungai","pair":2},{"text":"Mahang","pair":3},{"text":"Pokok yang melahirkan nama Pahang","pair":3},{"text":"Inderapura atau Pura","pair":4},{"text":"Nama Pahang dalam Sulalatus Salatin","pair":4}],"aftermath":"Kedua-dua penjaga menolak cop.","turns":[{"after":6,"options":[{"text":"Bandar atau pekan.","isCorrect":true,"reaction":"Penjaga Pahang mengangguk dan menekan cop."},{"text":"Pokok besar.","isCorrect":false,"reaction":"Penjaga menggeleng. Pura bermaksud bandar."},{"text":"Sungai kecil.","isCorrect":false,"reaction":"Penjaga menggeleng. Pura bermaksud bandar."}],"clue":"Pura bermaksud bandar atau pekan."}]}'),
(249, 'e2_n3_s13', 'Dua Peta Pusat', 'Padankan setiap kad dengan negeri dan jawapannya.', '4', 'Memadankan Shah Alam, Klang, Duli Yang Maha Mulia, Kuantan, Pekan dan Allah Selamatkan Sultan Kami.', '{"pairs":[{"text":"Shah Alam","pair":1},{"text":"Ibu negeri Selangor","pair":1},{"text":"Klang","pair":2},{"text":"Bandar diraja Selangor","pair":2},{"text":"Duli Yang Maha Mulia","pair":3},{"text":"Lagu Selangor","pair":3},{"text":"Kuantan","pair":4},{"text":"Ibu negeri Pahang","pair":4},{"text":"Pekan","pair":5},{"text":"Bandar diraja Pahang","pair":5},{"text":"Allah Selamatkan Sultan Kami","pair":6},{"text":"Lagu Pahang","pair":6}],"aftermath":"Cop ditahan.","turns":[{"after":6,"options":[{"text":"Sultan.","isCorrect":true,"reaction":"Pegawai mengangguk dan menekan cop."},{"text":"Raja.","isCorrect":false,"reaction":"Pegawai menggeleng. Raja hanya di Perlis."},{"text":"Yang di-Pertua Negeri.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu untuk empat negeri lain."}],"clue":"Ketua Selangor dan Pahang bergelar Sultan."}]}'),
(250, 'e2_n3_s14', 'Pelangi dan Kilat', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan taring anu, terangnya ganu, kilatan dan gelam hutan.', '{"pairs":[{"text":"Taring anu","pair":1},{"text":"Taring besar di Pulau Duyong","pair":1},{"text":"Terangnya ganu","pair":2},{"text":"Pelangi","pair":2},{"text":"Kilatan","pair":3},{"text":"Cahaya terang yang dilihat orang Patani","pair":3},{"text":"Gelam hutan","pair":4},{"text":"Pokok di pesisir pantai Kelantan","pair":4}],"aftermath":"Penjaga menolak cop kerana padanan tidak lengkap.","turns":[{"after":6,"options":[{"text":"Taring besar seperti gading gajah atau binatang liar lain.","isCorrect":true,"reaction":"Nelayan mengangguk dan menekan cop."},{"text":"Gading daripada ikan paus.","isCorrect":false,"reaction":"Nelayan menggeleng. Ia seperti gading gajah."},{"text":"Gading daripada kayu.","isCorrect":false,"reaction":"Nelayan menggeleng. Ia taring besar."}],"clue":"Taring anu ialah taring besar seperti gading gajah."}]}'),
(251, 'e2_n3_s15', 'Nota di Bawah Radio', 'Nyahkod nota dan tentukan dua negeri yang berkongsi tajuk lagu Selamat Sultan.', '5', 'Mengenal pasti Terengganu dan Kelantan.', '{"clueText":"Nota: Dua negeri di pantai timur menggunakan lagu bertajuk Selamat Sultan. Ibu negeri mereka ialah Kuala Terengganu dan Kota Bharu.","options":[{"text":"Terengganu dan Kelantan","isCorrect":true},{"text":"Pahang dan Terengganu","isCorrect":false,"consequence":"Pahang mempunyai lagu lain, iaitu Allah Selamatkan Sultan Kami."},{"text":"Pahang dan Kelantan","isCorrect":false,"consequence":"Pahang mempunyai lagu lain, iaitu Allah Selamatkan Sultan Kami."},{"text":"Kedah dan Perak","isCorrect":false,"consequence":"Dua negeri itu di utara dan lagu mereka lain."}],"aftermath":"Penjaga menolak cop.","turns":[{"after":6,"options":[{"text":"Kuala Terengganu dan Kota Bharu.","isCorrect":true,"reaction":"Penjaga mengangguk dan menekan cop."},{"text":"Kuantan dan Pekan.","isCorrect":false,"reaction":"Penjaga menggeleng. Itu milik Pahang."},{"text":"Ipoh dan Alor Setar.","isCorrect":false,"reaction":"Penjaga menggeleng. Itu ibu negeri utara."}],"clue":"Ibu negeri Terengganu: Kuala Terengganu; Kelantan: Kota Bharu."}]}'),
(252, 'e2_n3_s16', 'Jeti Perak dan Pulau Pinang', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan kilatan ikan, bijih timah putih, Pulo Ka Satu, Tanjong Penaga dan pinang.', '{"pairs":[{"text":"Kilatan ikan","pair":1},{"text":"Ikan berkilau di dalam air (Perak)","pair":1},{"text":"Bijih timah putih berkilat","pair":2},{"text":"Pandangan lain tentang nama Perak","pair":2},{"text":"Pulo Ka Satu","pair":3},{"text":"Nama asal Pulau Pinang","pair":3},{"text":"Tanjong Penaga","pair":4},{"text":"Gelaran orang Kedah kerana banyak pokok penaga","pair":4},{"text":"Buah pinang","pair":5},{"text":"Bahan dagangan penting","pair":5}],"aftermath":"Penjaga menyindir kerana padanan tersilap.","turns":[{"after":6,"options":[{"text":"Bahan dagangan penting.","isCorrect":true,"reaction":"Pedagang mengangguk dan menekan cop."},{"text":"Kerana pulau itu berbentuk pinang.","isCorrect":false,"reaction":"Pedagang menggeleng. Itu bukan sebab dalam buku."},{"text":"Kerana ia bukan barang dagangan.","isCorrect":false,"reaction":"Pedagang menggeleng. Pinang bahan dagangan penting."}],"clue":"Pinang bahan dagangan penting yang dikaitkan dengan nama Pulau Pinang."}]}'),
(253, 'e2_n3_s17', 'Dokumen Perak dan Pulau Pinang', 'Bantu pegawai daerah memilih dokumen yang betul.', '3', 'Membantu NPC memilih dokumen: Ipoh, Kuala Kangsar, George Town, lagu dan ketua.', '{"npcName":"Pegawai Daerah","prompt":"Dokumen mana yang betul untuk Perak dan Pulau Pinang?","options":[{"text":"Perak: Ipoh, Kuala Kangsar, Sultan; Pulau Pinang: George Town, Yang di-Pertua Negeri","item":"dokumen","isCorrect":true},{"text":"Perak: Kuala Kangsar ibu negeri, Ipoh bandar diraja","item":"dokumen","isCorrect":false,"consequence":"Jemputan dihantar ke bandar yang salah."},{"text":"Perak bergelar Yang di-Pertua Negeri","item":"dokumen","isCorrect":false,"consequence":"Ketua Perak ialah Sultan dan jemputan tersalah."},{"text":"Pulau Pinang bergelar Raja","item":"dokumen","isCorrect":false,"consequence":"Raja hanya di Perlis dan jemputan tersalah."}],"aftermath":"Jemputan salah dihantar.","turns":[{"after":6,"options":[{"text":"Untuk Negeri Kita.","isCorrect":true,"reaction":"Pegawai mengangguk dan menekan cop."},{"text":"Allah Lanjutkan Usia Sultan.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu lagu Perak."},{"text":"Aamiin-Aamiin.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu lagu Perlis."}],"clue":"Lagu Pulau Pinang ialah Untuk Negeri Kita."}]}'),
(254, 'e2_n3_s18', 'Gajah dan Kelapa', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan kheddah, qadah, kadaram, prow-lowy dan peroleh.', '{"pairs":[{"text":"Kheddah","pair":1},{"text":"Perangkap gajah","pair":1},{"text":"Qadah","pair":2},{"text":"Cawan atau gelas berkaki","pair":2},{"text":"Kadaram atau kalagam","pair":3},{"text":"Nama Kedah dalam tulisan Tamil","pair":3},{"text":"Prow-lowy","pair":4},{"text":"Kelapa hanyut","pair":4},{"text":"Peroleh","pair":5},{"text":"Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail","pair":5}],"aftermath":"Cop ditahan.","turns":[{"after":6,"options":[{"text":"Yang menerima mandat kerana membantu Perlis menentang Siam.","isCorrect":true,"reaction":"Pesawah mengangguk dan menekan cop."},{"text":"Seorang pedagang Arab.","isCorrect":false,"reaction":"Pesawah menggeleng. Dia menerima mandat."},{"text":"Seorang pemburu gajah.","isCorrect":false,"reaction":"Pesawah menggeleng. Dia berkait dengan Perlis."}],"clue":"Raja Syed Hussin menerima mandat kerana membantu Perlis menentang Siam."}]}'),
(255, 'e2_n3_s19', 'Kaset Lagu Kedah', 'Bantu pegawai radio memilih kaset lagu negeri Kedah.', '3', 'Membantu NPC memilih kaset Allah Selamatkan Sultan Mahkota.', '{"npcName":"Pegawai Radio","prompt":"Kaset mana ialah lagu negeri Kedah?","options":[{"text":"Allah Selamatkan Sultan Mahkota","item":"kaset","isCorrect":true},{"text":"Aamiin-Aamiin","item":"kaset","isCorrect":false,"consequence":"Lagu Perlis dimainkan di hadapan tetamu Kedah."},{"text":"Allah Lanjutkan Usia Sultan","item":"kaset","isCorrect":false,"consequence":"Lagu Perak dimainkan di hadapan tetamu Kedah."},{"text":"Untuk Negeri Kita","item":"kaset","isCorrect":false,"consequence":"Lagu Pulau Pinang dimainkan di hadapan tetamu Kedah."}],"aftermath":"Lagu negeri lain dimainkan.","turns":[{"after":6,"options":[{"text":"Aamiin-Aamiin. Kangar dan Arau (Perlis); Alor Setar dan Anak Bukit (Kedah).","isCorrect":true,"reaction":"Pegawai mengangguk dan menekan cop."},{"text":"Allah Lanjutkan Usia Sultan; Ipoh dan Kuala Kangsar.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu milik Perak."},{"text":"Untuk Negeri Kita; George Town.","isCorrect":false,"reaction":"Pegawai menggeleng. Itu milik Pulau Pinang."}],"clue":"Lagu Perlis ialah Aamiin-Aamiin. Kangar-Arau; Alor Setar-Anak Bukit."}]}'),
(256, 'e2_n3_s20', 'Cop Terakhir', 'Cari tiga lambang negeri di pentas: jata, bendera dan radio lagu.', '2', 'Mencari bukti lambang negeri: jata, bendera dan lagu sebagai identiti dan kemegahan.', '{"bgImage":"../assets/gameAsset/background/wilayah_persekutuan.png","hotspots":[{"name":"Jata: lambang kedaulatan negeri","top":"40.4%","left":"70%"},{"name":"Bendera: lambang identiti negeri","top":"20.9%","left":"72.7%"},{"name":"Radio: lagu Maju dan Sejahtera","top":"86.4%","left":"74.1%"}],"aftermath":"Cop terakhir tidak diberikan.","turns":[{"after":6,"options":[{"text":"Bendera, lagu dan jata ialah identiti dan lambang kemegahan setiap negeri; mengenalinya menaikkan rasa cinta akan negara.","isCorrect":true,"reaction":"Penjaga mengangguk. Pasport lengkap."},{"text":"Kerana ia hiasan sahaja.","isCorrect":false,"reaction":"Penjaga menggeleng. Lambang ialah identiti negeri."},{"text":"Supaya negeri lain takut.","isCorrect":false,"reaction":"Penjaga menggeleng. Ia bukan untuk menakutkan."}],"clue":"Lambang negeri ialah identiti dan kemegahan."}]}'),
(301, 'e3_n1_s1', 'Papan Tanda di Bilik Gerakan', 'Baca nota dan tentukan badan yang mentadbir negara selepas peristiwa 13 Mei 1969.', '5', 'Mengetahui MAGERAN mentadbir negara selepas 13 Mei 1969 dan mendahului pembentukan Rukun Negara.', '{"clueText":"Nota ringkas: Selepas rusuhan kaum 13 Mei 1969, pentadbiran negara diambil alih oleh sebuah majlis yang diketuai pegawai tertinggi. Majlis inilah yang kemudian membuka jalan kepada penubuhan Jawatankuasa Rukun Negara.","options":[{"text":"Majlis Gerakan Negara (MAGERAN).","isCorrect":true},{"text":"Majlis Perundingan Negara (MAPEN).","isCorrect":false,"consequence":"MAPEN ditubuhkan kemudian untuk merangka Rukun Negara. Pegawai tersasar dan nota dikembalikan."},{"text":"Parlimen Malaysia.","isCorrect":false,"consequence":"Parlimen digantung pada waktu itu. Rakyat keliru siapa yang bertanggungjawab."},{"text":"Suruhanjaya Pilihan Raya.","isCorrect":false,"consequence":"Suruhanjaya itu tidak mentadbir negara. Pegawai terpaksa membetulkan nota."}],"aftermath":"Nota salah dibaca dan pentadbiran sementara tidak jelas. Rakyat bertanya siapa yang memerintah.","turns":[{"after":1,"options":[{"text":"Majlis Gerakan Negara akan menjaga ketenteraman dan menyediakan jalan untuk perpaduan.","isCorrect":true,"reaction":"Betul, Tun. Rakyat akan lebih yakin."},{"text":"Kita biarkan kampung dan bandar menyelesaikan sendiri.","isCorrect":false,"reaction":"Kekeliruan berterusan, dan rakyat berasa ditinggalkan."},{"text":"Kita tangguhkan sehingga semua pihak berhenti berbalah.","isCorrect":false,"reaction":"Penangguhan itu membiarkan suasana tidak harmoni merebak."}],"clue":"Satu badan mentadbir negara dengan segera."}]}'),
(302, 'e3_n1_s2', 'Peta Petempatan Berasingan', 'Cari tiga bukti kegiatan ekonomi dan tempat tinggal yang memisahkan kaum.', '2', 'Memahami pengasingan tempat tinggal dan kegiatan ekonomi sebagai sebab Rukun Negara diperkenalkan.', '{"bgImage":"../assets/gameAsset/background/petempatan_semua_dahulu.png","hotspots":[{"name":"Ladang getah: orang India menoreh dan tinggal di ladang (perladangan)","top":"80%","left":"7%"},{"name":"Kampung dan sawah: orang Melayu bertani sara diri di kampung dan pedalaman","top":"48%","left":"62%"},{"name":"Rumah kedai dan pekan: orang Cina berniaga dan melombong di bandar","top":"72%","left":"85%"}],"aftermath":"Tanpa bukti, laporan tidak lengkap dan punca perpecahan tidak dikenal pasti. MAGERAN meneka-neka.","turns":[{"after":4,"options":[{"text":"Mereka jarang bertemu kerana tinggal berasingan, jadi kurang peluang berinteraksi.","isCorrect":true,"reaction":"Itulah punca yang sebenar, Tun."},{"text":"Mereka jarang bertemu kerana tidak suka satu sama lain.","isCorrect":false,"reaction":"Tuduhan itu menambah curiga antara kaum."},{"text":"Mereka jarang bertemu kerana semua tinggal di bandar.","isCorrect":false,"reaction":"Fakta itu salah. Kampung dan ladang memang terpisah dari bandar."}],"clue":"Tempat tinggal berasingan menyebabkan kurang interaksi."}]}'),
(303, 'e3_n1_s3', 'Rekod Mesyuarat MAPEN', 'Baca rekod dan tentukan badan yang merangka Rukun Negara pada 4 Mac 1970.', '5', 'Mengetahui Rukun Negara dirangka oleh Jawatankuasa Rukun Negara di bawah MAPEN pada 4 Mac 1970; MAPEN dianggotai 66 wakil.', '{"clueText":"Rekod mesyuarat: Pada 4 Mac 1970, satu jawatankuasa yang terletak di bawah Majlis Perundingan Negara (MAPEN) merangka dan memperkenalkan Rukun Negara. MAPEN dianggotai 66 orang wakil daripada pelbagai lapisan masyarakat.","options":[{"text":"Jawatankuasa Rukun Negara di bawah MAPEN.","isCorrect":true},{"text":"Jawatankuasa Antara Kerajaan (JAK).","isCorrect":false,"consequence":"JAK berkaitan pembentukan Malaysia. Rekod dikembalikan dengan nota merah."},{"text":"Jawatankuasa Setia Kawan Malaysia (JSKM).","isCorrect":false,"consequence":"JSKM bertugas pada 1961. Pegawai terkejut dengan jawapan salah."},{"text":"Suruhanjaya Cobbold.","isCorrect":false,"consequence":"Suruhanjaya Cobbold bertugas pada 1962. Rekod mesyuarat menjadi kelam-kabut."}],"aftermath":"Rekod salah dicatat dan sejarah badan yang merangka Rukun Negara hilang.","turns":[{"after":2,"options":[{"text":"Wakil daripada pelbagai lapisan masyarakat memastikan Rukun Negara mewakili semua pihak.","isCorrect":true,"reaction":"Betul, Tun. Semua suara dihargai."},{"text":"Hanya wakil tentera yang perlu hadir.","isCorrect":false,"reaction":"Wakil lain bangun dan membantah. Mereka berasa tidak dihargai."},{"text":"Hanya wakil kerajaan sahaja yang boleh bercakap.","isCorrect":false,"reaction":"Rakyat menuduh MAPEN berat sebelah."}],"clue":"Wakil pelbagai pihak mengambil bahagian."}]}'),
(304, 'e3_n1_s4', 'Lima Matlamat dalam Lukisan', 'Cari lima bukti tersembunyi yang mewakili lima matlamat Rukun Negara.', '2', 'Mengenali lima matlamat Rukun Negara: perpaduan, demokrasi, masyarakat adil, liberal terhadap kebudayaan, masyarakat progresif.', '{"bgImage":"../assets/gameAsset/background/matlamat_rukun_negara.png","hotspots":[{"name":"Bendera dan jata: perpaduan yang lebih erat dalam kalangan masyarakat","top":"12.4%","left":"55.4%"},{"name":"Buku Perlembagaan: memelihara satu cara hidup demokrasi","top":"45.8%","left":"75.4%"},{"name":"Timbangan keadilan: masyarakat adil, kemakmuran dinikmati bersama","top":"29.8%","left":"83.2%"},{"name":"Masjid dan gereja: cara liberal terhadap tradisi kebudayaan yang pelbagai","top":"27.2%","left":"28.1%"},{"name":"Panel digital: masyarakat progresif dengan sains dan teknologi moden","top":"79%","left":"51.3%"}],"aftermath":"Matlamat tidak ditemui dan rakyat tidak memahami tujuan Rukun Negara.","turns":[{"after":1,"options":[{"text":"Lima matlamat itu menjadi cita-cita seluruh rakyat Malaysia.","isCorrect":true,"reaction":"Betul, Tun. Semua perlu menghayatinya."},{"text":"Matlamat itu hanya untuk kerajaan.","isCorrect":false,"reaction":"Rakyat berasa disisihkan dan tidak mahu menghayati Rukun Negara."},{"text":"Matlamat itu boleh diabaikan kerana tidak penting.","isCorrect":false,"reaction":"Pegawai membantah. Matlamat itu pegangan negara."}],"clue":"Matlamat Rukun Negara milik semua."}]}'),
(305, 'e3_n1_s5', 'Kad Peristiwa Rukun Negara', 'Susun empat peristiwa dari peristiwa 13 Mei hingga pengisytiharan Rukun Negara.', '1', 'Menyusun kronologi: 13 Mei 1969, MAGERAN mentadbir negara, 4 Mac 1970 Jawatankuasa Rukun Negara merangka, 31 Ogos 1970 pengisytiharan.', '{"timelineItems":[{"id":1,"year":"13 Mei 1969","text":"Peristiwa rusuhan kaum 13 Mei","why":"Perbezaan kaum yang tidak diurus menjadi rusuhan."},{"id":2,"year":"1969","text":"MAGERAN mentadbir negara selepas 13 Mei","why":"Selepas rusuhan, pentadbiran diambil alih MAGERAN."},{"id":3,"year":"4 Mac 1970","text":"Jawatankuasa Rukun Negara di bawah MAPEN merangka Rukun Negara","why":"Setelah negara tenang, satu ideologi dirangka melalui MAPEN."},{"id":4,"year":"31 Ogos 1970","text":"Rukun Negara diisytiharkan sebagai Pengisytiharan Diraja oleh Yang di-Pertuan Agong Keempat","why":"Rangka yang siap diisytiharkan bersempena Hari Kebangsaan ke-13."}],"aftermath":"Kad tersusun salah dan sejarah Rukun Negara terputus. Sesuatu yang penting hilang daripada ingatan.","turns":[{"after":1,"options":[{"text":"Rukun Negara diisytiharkan pada 31 Ogos 1970 oleh Yang di-Pertuan Agong Keempat.","isCorrect":true,"reaction":"Betul, Tun. Tarikh itu tidak boleh dilupakan."},{"text":"Rukun Negara diisytiharkan pada 31 Ogos 1957.","isCorrect":false,"reaction":"Itu tarikh kemerdekaan, bukan Rukun Negara. Pegawai membetulkan."},{"text":"Rukun Negara diisytiharkan pada 16 September 1963.","isCorrect":false,"reaction":"Itu tarikh Hari Malaysia. Rekod bercampur."}],"clue":"31 Ogos 1970, ulang tahun ke-13 Hari Kebangsaan."}]}'),
(306, 'e3_n1_s6', 'Kad Lima Matlamat', 'Padankan setiap matlamat dengan maksudnya.', '4', 'Memadankan lima matlamat Rukun Negara dengan maksud.', '{"pairs":[{"text":"Perpaduan","pair":1},{"text":"Lebih erat dalam kalangan seluruh masyarakat","pair":1},{"text":"Demokrasi","pair":2},{"text":"Memelihara satu cara hidup demokrasi","pair":2},{"text":"Keadilan","pair":3},{"text":"Kemakmuran negara dinikmati bersama secara adil dan saksama","pair":3},{"text":"Kebudayaan","pair":4},{"text":"Cara liberal terhadap tradisi kebudayaan yang kaya dan pelbagai","pair":4},{"text":"Kemajuan","pair":5},{"text":"Masyarakat progresif yang menggunakan sains dan teknologi moden","pair":5}],"aftermath":"Kad bertukar dan teks yang dicetak salah. Jutaan salinan terpaksa dibatalkan.","turns":[{"after":1,"options":[{"text":"Teks mesti tepat kerana rakyat akan menghafal dan mengamalkannya.","isCorrect":true,"reaction":"Betul, Tun. Tiada ruang untuk silap."},{"text":"Cetak sahaja walaupun tersilap.","isCorrect":false,"reaction":"Kesilapan itu akan disalin jutaan kali, dan rakyat menghafal yang salah."},{"text":"Tangguhkan percetakan selama setahun.","isCorrect":false,"reaction":"Penangguhan melambatkan perpaduan yang amat diperlukan."}],"clue":"Teks perlu tepat sebelum dicetak."}]}'),
(307, 'e3_n2_s1', 'Senarai Kegiatan Ekonomi', 'Padankan setiap kaum dengan kegiatan ekonomi utamanya pada zaman British.', '4', 'Memadankan kaum dengan kegiatan ekonomi: Melayu (pertanian sara diri), Cina (perlombongan dan perniagaan), India (perladangan).', '{"pairs":[{"text":"Orang Melayu","pair":1},{"text":"Pertanian sara diri","pair":1},{"text":"Orang Cina","pair":2},{"text":"Perlombongan dan perniagaan","pair":2},{"text":"Orang India","pair":3},{"text":"Perladangan","pair":3}],"aftermath":"Senarai tersilap dan jurang ekonomi tidak dikenal pasti. Rakyat saling menyalahkan.","turns":[{"after":2,"options":[{"text":"Pentadbiran British membawa masuk pekerja dan membezakan kegiatan ekonomi setiap kaum.","isCorrect":true,"reaction":"Itu betul, Tun. Jurang ekonomi tidak seimbang terbentuk."},{"text":"Setiap kaum memilih sendiri kerana kebetulan.","isCorrect":false,"reaction":"Itu tidak betul. Jurang itu dibentuk oleh dasar pentadbiran."},{"text":"Kaum Melayu dilarang bekerja di bandar.","isCorrect":false,"reaction":"Tiada catatan begitu. Kata-kata itu menimbulkan salah faham."}],"clue":"Pentadbiran British membezakan kegiatan ekonomi."}]}'),
(308, 'e3_n2_s2', 'Nota Tempat Tinggal Berasingan', 'Baca nota dan tentukan kesan pengasingan tempat tinggal.', '5', 'Memahami pengasingan tempat tinggal menyebabkan kurangnya peluang berinteraksi antara masyarakat.', '{"clueText":"Nota: Orang Melayu tinggal di kampung dan pedalaman, orang Cina tinggal di bandar, orang India tinggal di ladang. Mereka jarang bertemu dalam kehidupan harian.","options":[{"text":"Kurangnya peluang berinteraksi antara masyarakat.","isCorrect":true},{"text":"Semua kaum menjadi lebih erat.","isCorrect":false,"consequence":"Pernyataan itu bertentangan dengan keadaan. Mereka makin renggang."},{"text":"Semua kaum berpindah ke bandar.","isCorrect":false,"consequence":"Tiada catatan begitu. Kampung dan ladang masih berasingan."},{"text":"Semua kaum bercakap bahasa yang sama.","isCorrect":false,"consequence":"Bahasa tidak menjadi punca. Nota tersasar."}],"aftermath":"Kesan pengasingan tidak dikenal pasti. Kaum-kaum terus berjauhan.","turns":[{"after":3,"options":[{"text":"Kita beri peluang mereka bertemu, supaya mengenali jiran berlainan kaum.","isCorrect":true,"reaction":"Itu langkah awal yang baik, Tun."},{"text":"Kita biarkan mereka tinggal berasingan.","isCorrect":false,"reaction":"Kekurangan interaksi berterusan dan salah faham tumbuh."},{"text":"Kita paksa mereka berpindah serta-merta.","isCorrect":false,"reaction":"Paksaan itu menimbulkan kemarahan dan kebimbangan."}],"clue":"Beri peluang bertemu."}]}'),
(309, 'e3_n2_s3', 'Rantai Sebab 13 Mei', 'Susun rantai sebab yang membawa kepada rusuhan kaum 13 Mei 1969.', '1', 'Memahami rantai sebab: pekerja dibawa masuk, kegiatan ekonomi berbeza, tempat tinggal berasingan, kurang interaksi, fahaman politik berbeza, 13 Mei 1969.', '{"timelineItems":[{"id":1,"year":"Zaman British","text":"British membawa masuk pekerja dari luar untuk sektor ekonomi","why":"Permulaan: pekerja baharu dibawa masuk."},{"id":2,"year":"Kemudian","text":"Setiap kaum menjalankan kegiatan ekonomi yang berbeza","why":"Pekerja ditempatkan dalam sektor berbeza dan jurang ekonomi terbentuk."},{"id":3,"year":"Seterusnya","text":"Setiap kaum tinggal berasingan di kampung, bandar dan ladang","why":"Kegiatan yang berbeza membawa kepada tempat tinggal berbeza."},{"id":4,"year":"Akibatnya","text":"Peluang berinteraksi antara kaum menjadi kurang dan fahaman politik berbeza","why":"Apabila jarang bertemu, hubungan renggang dan fahaman politik berbeza."},{"id":5,"year":"13 Mei 1969","text":"Rusuhan kaum tercetus","why":"Suasana tidak harmoni memuncak menjadi rusuhan."}],"aftermath":"Rantai terputus dan punca 13 Mei tidak dapat dijelaskan. Rakyat saling menuduh.","turns":[{"after":3,"options":[{"text":"Peristiwa itu bermula daripada jurang dan jarak, bukan daripada satu kaum sahaja.","isCorrect":true,"reaction":"Itu adil, Tun. Kami faham sekarang."},{"text":"Semuanya salah satu kaum sahaja.","isCorrect":false,"reaction":"Tuduhan itu membakar semangat perkauman semula."},{"text":"Tiada sebab, ia hanya kebetulan.","isCorrect":false,"reaction":"Rakyat tidak percaya, dan mereka menuduh kerajaan menyembunyikan sebab."}],"clue":"Banyak sebab saling berkait."}]}'),
(310, 'e3_n2_s4', 'Papan Kenyataan Tempat Ibadat', 'Baca papan kenyataan dan tentukan maksud prinsip pertama Rukun Negara.', '5', 'Memahami Kepercayaan kepada Tuhan: agama pegangan utama, menghormati amalan agama lain dan menyatupadukan masyarakat.', '{"clueText":"Papan kenyataan: Prinsip pertama mengajak setiap orang berpegang kepada agama masing-masing dan menghormati amalan beragama masyarakat lain, supaya masyarakat berbilang kaum bersatu padu.","options":[{"text":"Agama pegangan utama dan menghormati amalan agama lain.","isCorrect":true},{"text":"Semua rakyat mesti menganut satu agama sahaja.","isCorrect":false,"consequence":"Pernyataan itu menakutkan rakyat berlainan agama dan menimbulkan bantahan."},{"text":"Agama tidak penting dalam kehidupan.","isCorrect":false,"consequence":"Rakyat berasa pegangan mereka diremehkan."},{"text":"Hanya satu kaum boleh beribadat di tempat awam.","isCorrect":false,"consequence":"Tuduhan itu salah dan menimbulkan kemarahan."}],"aftermath":"Papan kenyataan disalah baca. Rakyat berasa takut dengan prinsip pertama.","turns":[{"after":3,"options":[{"text":"Kerana berlainan agama, kita belajar menghormati dan hidup berdampingan.","isCorrect":true,"reaction":"Itu yang kami mahu, Tun."},{"text":"Kerana berlainan agama, kita mesti berjauhan.","isCorrect":false,"reaction":"Rakyat bertambah renggang."},{"text":"Kerana berlainan agama, kita menukar agama bersama.","isCorrect":false,"reaction":"Cadangan itu bertentangan dengan prinsip. Rakyat membantah."}],"clue":"Hormat dan hidup berdampingan."}]}'),
(311, 'e3_n2_s5', 'Cari Petunjuk Prinsip 1 dan 2', 'Cari tiga petunjuk yang mewakili prinsip kepercayaan kepada Tuhan dan kesetiaan kepada raja dan negara.', '2', 'Mengenali prinsip 1 dan 2: Kepercayaan kepada Tuhan; Kesetiaan kepada raja dan negara.', '{"bgImage":"../assets/gameAsset/background/prinsip_rukun_negara_.png","hotspots":[{"name":"Orang pelbagai agama berdoa: agama pegangan utama, hormat amalan agama lain","top":"24%","left":"12%"},{"name":"Jata negara: taat setia kepada Yang di-Pertuan Agong, Ketua Utama Negara","top":"25.8%","left":"41.5%"},{"name":"Tugu Negara: semangat patriotik dan taat setia kepada negara","top":"36.8%","left":"91.9%"}],"aftermath":"Petunjuk tidak ditemui dan prinsip tidak dapat dijelaskan kepada anak-anak.","turns":[{"after":3,"options":[{"text":"Ketua Utama Negara ialah Yang di-Pertuan Agong.","isCorrect":true,"reaction":"Betul, Tun. Anak saya akan hafal."},{"text":"Ketua Utama Negara ialah Perdana Menteri.","isCorrect":false,"reaction":"Perdana Menteri ketua kerajaan, bukan Ketua Utama Negara. Anak keliru."},{"text":"Ketua Utama Negara ialah Sultan Johor.","isCorrect":false,"reaction":"Sultan Johor ketua negeri. Jawapan itu salah."}],"clue":"Yang di-Pertuan Agong."}]}'),
(312, 'e3_n2_s6', 'Papan Lima Prinsip', 'Padankan setiap prinsip dengan maksudnya.', '4', 'Memadankan lima prinsip Rukun Negara dengan maksud.', '{"pairs":[{"text":"Kepercayaan kepada Tuhan","pair":1},{"text":"Agama sebagai pegangan utama rakyat Malaysia","pair":1},{"text":"Kesetiaan kepada Raja dan Negara","pair":2},{"text":"Taat setia kepada Yang di-Pertuan Agong sebagai Ketua Utama Negara","pair":2},{"text":"Keluhuran Perlembagaan","pair":3},{"text":"Perlembagaan Persekutuan ialah undang-undang tertinggi negara","pair":3},{"text":"Kedaulatan Undang-undang","pair":4},{"text":"Setiap rakyat menghormati dan mematuhi undang-undang","pair":4},{"text":"Kesopanan dan Kesusilaan","pair":5},{"text":"Amalan nilai murni yang melambangkan keperibadian rakyat","pair":5}],"aftermath":"Papan bertukar dan maksud tersilap. Anak-anak sekolah menghafal prinsip yang salah.","turns":[{"after":3,"options":[{"text":"Perlembagaan Persekutuan ialah undang-undang tertinggi, tiada institusi mengatasinya.","isCorrect":true,"reaction":"Betul, Tun. Itu keluhuran perlembagaan."},{"text":"Perdana Menteri lebih tinggi daripada Perlembagaan.","isCorrect":false,"reaction":"Itu salah. Tiada sesiapa mengatasi Perlembagaan."},{"text":"Perlembagaan boleh diabaikan bila perlu.","isCorrect":false,"reaction":"Rakyat membantah. Perlembagaan wajib dipertahankan."}],"clue":"Perlembagaan paling tinggi."}]}'),
(313, 'e3_n3_s1', 'Kad Peranan Prinsip Pertama', 'Baca kad dan tentukan peranan Rukun Negara dalam meraikan kepelbagaian agama.', '5', 'Memahami peranan Rukun Negara: patuh ajaran agama, mengelakkan dengki, rasuah, dadah dan keruntuhan moral, serta bersyukur.', '{"clueText":"Kad peranan: Masyarakat yang berpegang kepada agama masing-masing patuh ajaran agama, bersikap rendah diri dan bersyukur. Mereka dapat mengelakkan perasaan dengki, khianat, rasuah, penyalahgunaan dadah dan keruntuhan moral.","options":[{"text":"Membentuk masyarakat yang patuh ajaran agama dan mengelakkan keruntuhan moral.","isCorrect":true},{"text":"Membentuk masyarakat yang tidak peduli agama.","isCorrect":false,"consequence":"Murid berasa nilai agama diremehkan dan hormat kepada kawan berkurang."},{"text":"Membentuk masyarakat yang hanya menghormati agama sendiri.","isCorrect":false,"consequence":"Rakyat bertengkar tentang agama dan perpaduan retak."},{"text":"Membentuk masyarakat yang menukar agama setiap tahun.","isCorrect":false,"consequence":"Pernyataan tidak ada dalam Rukun Negara. Murid keliru."}],"aftermath":"Kad disalah baca dan peranan Rukun Negara tidak difahami.","turns":[{"after":1,"options":[{"text":"Kita menghormati agama kawan kerana Rukun Negara mengajak kita hidup berdampingan.","isCorrect":true,"reaction":"Betul, Tunku. Terima kasih."},{"text":"Kita hanya menghormati agama sendiri.","isCorrect":false,"reaction":"Kawan-kawan berasa dipinggirkan dan berjauhan."},{"text":"Kita tidak perlu menghormati sesiapa.","isCorrect":false,"reaction":"Suasana menjadi tegang dan murid saling mengelak."}],"clue":"Hormati pegangan orang lain."}]}'),
(314, 'e3_n3_s2', 'Kad Lambang Kedaulatan', 'Baca kad dan tentukan peranan Rukun Negara dalam membentuk masyarakat patriotik.', '5', 'Memahami peranan patriotik: taat setia, sanggup berkorban, menghormati Jalur Gemilang, Jata Negara dan lagu Negaraku.', '{"clueText":"Kad: Rukun Negara membentuk masyarakat yang mencintai negara, taat setia dan sanggup berkorban. Mereka menghormati lambang kedaulatan negara seperti bendera Jalur Gemilang, Jata Negara dan lagu Negaraku.","options":[{"text":"Membentuk masyarakat patriotik yang menghormati lambang kedaulatan negara.","isCorrect":true},{"text":"Membentuk masyarakat yang tidak peduli lambang negara.","isCorrect":false,"consequence":"Kawan itu semakin berani menyindir dan murid lain menurut."},{"text":"Membentuk masyarakat yang hanya menghormati bendera pada hari tertentu.","isCorrect":false,"consequence":"Hormat yang terhad kepada hari tertentu cepat pudar."},{"text":"Membentuk masyarakat yang menukar lambang negara.","isCorrect":false,"consequence":"Cadangan itu tidak ada dalam Rukun Negara. Murid berbalah."}],"aftermath":"Kad disalah baca dan lambang negara dipandang remeh oleh murid.","turns":[{"after":3,"options":[{"text":"Lambang itu menyatukan kita sebagai rakyat Malaysia, jadi wajib dihormati.","isCorrect":true,"reaction":"Betul, Tunku. Dia terdiam dan mohon maaf."},{"text":"Lambang itu hanya hiasan.","isCorrect":false,"reaction":"Kawan itu tersenyum puas dan terus menyindir."},{"text":"Lambang itu tidak penting kerana ia bukan wang.","isCorrect":false,"reaction":"Murid lain mula ketawa dan hormat berkurang."}],"clue":"Lambang = identiti negara."}]}'),
(315, 'e3_n3_s3', 'Kad Kempen Bebas Dadah', 'Baca kad kempen dan tentukan kepentingan menghormati undang-undang.', '5', 'Memahami peranan Rukun Negara: memupuk sikap menghormati undang-undang untuk keamanan dan kesejahteraan.', '{"clueText":"Kad kempen: Kepatuhan kepada undang-undang dapat mewujudkan keamanan dan kesejahteraan. Rukun Negara membimbing rakyat daripada terlibat dengan kegiatan jenayah yang menggugat keselamatan negara.","options":[{"text":"Mewujudkan keamanan dan kesejahteraan negara.","isCorrect":true},{"text":"Menambah jenayah supaya negara menjadi lebih sibuk.","isCorrect":false,"consequence":"Murid ketawa. Jawapan itu salah dan bertentangan dengan kad."},{"text":"Menghentikan sekolah.","isCorrect":false,"consequence":"Tiada kaitan. Jawapan tersasar."},{"text":"Mengurangkan peranan polis.","isCorrect":false,"consequence":"Kad tidak menyebut. Jawapan itu mengelirukan."}],"aftermath":"Kad disalah baca dan murid menyangka undang-undang boleh diabaikan.","turns":[{"after":1,"options":[{"text":"Kita patuh undang-undang walaupun tiada orang melihat kerana ia menjaga keamanan.","isCorrect":true,"reaction":"Betul, Tunku. Saya akan ingat."},{"text":"Kita patuh hanya apabila ada polis.","isCorrect":false,"reaction":"Murid itu menganggap undang-undang boleh dilanggar bila tiada pengawasan."},{"text":"Kita tidak perlu patuh kerana tiada siapa nampak.","isCorrect":false,"reaction":"Kawan-kawan mula melanggar peraturan dan keadaan menjadi kecoh."}],"clue":"Patuh bukan kerana takut dilihat."}]}'),
(316, 'e3_n3_s4', 'Kad Peranan Perpaduan', 'Baca kad dan tentukan peranan Rukun Negara dalam mengukuhkan perpaduan.', '5', 'Memahami peranan perpaduan: permuafakatan dan toleransi, menghormati budaya kaum lain.', '{"clueText":"Kad: Masyarakat Malaysia perlu mengamalkan semangat permuafakatan dan bersikap toleransi. Rakyat dibimbing untuk memahami dan menghormati budaya kaum lain melalui Rukun Negara.","options":[{"text":"Mengamalkan permuafakatan dan toleransi serta menghormati budaya kaum lain.","isCorrect":true},{"text":"Mengutamakan budaya sendiri dan menolak budaya lain.","isCorrect":false,"consequence":"Kedua-dua pelanggan terus bertengkar dan pasar menjadi riuh."},{"text":"Mengelak berjumpa kaum lain.","isCorrect":false,"consequence":"Jurang menjadi lebih jauh dan salah faham tumbuh."},{"text":"Mengubah semua budaya menjadi satu budaya.","isCorrect":false,"consequence":"Bantahan timbul kerana setiap kaum mahu mengekalkan budayanya."}],"aftermath":"Kad disalah baca dan pasar malam bertukar kecoh.","turns":[{"after":2,"options":[{"text":"Kita bertolak ansur dan menghormati pilihan makanan setiap kaum.","isCorrect":true,"reaction":"Betul, Tunku. Pelanggan itu berjabat tangan."},{"text":"Kita paksa mereka makan makanan yang sama.","isCorrect":false,"reaction":"Pelanggan tersinggung dan beredar."},{"text":"Kita larang mereka berjumpa.","isCorrect":false,"reaction":"Perbalahan berpindah ke tempat lain."}],"clue":"Toleransi dan permuafakatan."}]}'),
(317, 'e3_n3_s5', 'Kad Enam Peranan Rukun Negara', 'Padankan setiap peranan dengan penerangannya.', '4', 'Memadankan enam peranan Rukun Negara: kepelbagaian agama, patriotik, undang-undang, perpaduan, nilai murni, jati diri.', '{"pairs":[{"text":"Meraikan kepelbagaian agama","pair":1},{"text":"Masyarakat patuh ajaran agama masing-masing","pair":1},{"text":"Masyarakat patriotik","pair":2},{"text":"Cinta negara dan hormat lambang kedaulatan","pair":2},{"text":"Menghormati undang-undang","pair":3},{"text":"Terhindar daripada kegiatan jenayah","pair":3},{"text":"Mengukuhkan perpaduan","pair":4},{"text":"Permuafakatan dan toleransi antara kaum","pair":4},{"text":"Menerapkan nilai murni","pair":5},{"text":"Kesopanan dan budi pekerti mulia","pair":5},{"text":"Membentuk jati diri","pair":6},{"text":"Individu yang berintegriti","pair":6}],"aftermath":"Kad bercampur dan murid menghafal peranan yang salah. Peperiksaan menjadi kelam-kabut.","turns":[{"after":3,"options":[{"text":"Integriti bermaksud kejujuran yang tulen dan tidak berubah, seperti tidak meniru dalam peperiksaan.","isCorrect":true,"reaction":"Betul, Tunku. Itu contoh yang jelas."},{"text":"Integriti bermaksud pandai menipu tanpa dikesan.","isCorrect":false,"reaction":"Murid itu keliru dan menyangka menipu tidak mengapa."},{"text":"Integriti bermaksud hanya jujur apabila diperhati.","isCorrect":false,"reaction":"Kejujuran sebenar tidak bergantung kepada pemerhatian."}],"clue":"Jujur sentiasa."}]}'),
(318, 'e3_n3_s6', 'Cari Petunjuk Prinsip 3 hingga 5', 'Cari empat petunjuk yang mewakili prinsip keluhuran perlembagaan, kedaulatan undang-undang, kesopanan dan kesusilaan.', '2', 'Mengenali prinsip 3, 4 dan 5: Keluhuran Perlembagaan, Kedaulatan Undang-undang, Kesopanan dan Kesusilaan.', '{"bgImage":"../assets/gameAsset/background/prinsip_rukun_negara_.png","hotspots":[{"name":"Gulungan pada batu: Perlembagaan ialah undang-undang tertinggi negara","top":"21.4%","left":"65.6%"},{"name":"Papan Kedaulatan Undang-undang: hormati dan patuhi undang-undang","top":"45.5%","left":"25.9%"},{"name":"Menanam pokok bersama: bekerjasama dan saling memahami (kesopanan)","top":"38%","left":"42%"},{"name":"Membantu warga emas: nilai murni dan akhlak mulia","top":"87.7%","left":"17.4%"}],"aftermath":"Petunjuk tidak ditemui dan adik-adik tidak mendapat gambaran prinsip.","turns":[{"after":1,"options":[{"text":"Kita menanam pokok bersama dan membantu warga emas kerana itu nilai murni.","isCorrect":true,"reaction":"Betul, Tunku. Adik-adik akan menirunya."},{"text":"Kita hanya menonton orang lain bekerja.","isCorrect":false,"reaction":"Murid lain menyangka bantuan tidak penting."},{"text":"Kita membantu hanya jika diberi upah.","isCorrect":false,"reaction":"Nilai murni hilang dan rakyat menjadi lokek."}],"clue":"Nilai murni dilakukan dengan ikhlas."}]}'),
(401, 'e4_n1_s1', 'Senarai Bahasa Kaum', 'Padankan setiap kaum dengan bahasa pertuturannya.', '4', 'Mengenal pasti kepelbagaian kaum di Malaysia dan bahasa pertuturan masing-masing.', '{"pairs":[{"text":"Melayu","pair":1},{"text":"Bahasa Melayu","pair":1},{"text":"Cina","pair":2},{"text":"Mandarin, Hokkien, Hakka dan Kantonis","pair":2},{"text":"India","pair":3},{"text":"Tamil, Telugu dan Malayalam","pair":3},{"text":"Sikh","pair":4},{"text":"Bahasa Punjabi","pair":4},{"text":"Serani","pair":5},{"text":"Bahasa Kristang dan bahasa Inggeris","pair":5},{"text":"Baba dan Nyonya","pair":6},{"text":"Dialek Melayu Baba","pair":6}],"aftermath":"Senarai bertukar dan pengacara menyebut bahasa yang salah. Penonton tersinggung dan bertepuk sumbang.","turns":[{"after":1,"options":[{"text":"Setiap kaum ada bahasa sendiri dan keunikan itu perlu dihargai.","isCorrect":true,"reaction":"Betul, pakcik. Pengacara mula menyebut tiga bahasa dan penonton tersenyum."},{"text":"Semua kaum patut bercakap satu bahasa di pentas.","isCorrect":false,"reaction":"Penonton berbisik tidak puas hati kerana bahasa ibunda mereka diketepikan."},{"text":"Bahasa lain tidak penting untuk diketahui.","isCorrect":false,"reaction":"Kanak-kanak lain terdiam dan berasa bahasa mereka disisih."}],"clue":"Hargai keunikan bahasa setiap kaum."}]}'),
(402, 'e4_n1_s2', 'Nota Tok Batin', 'Baca nota dan tentukan tiga kumpulan terbesar Orang Asli di Semenanjung.', '5', 'Mengenal pasti tiga kumpulan terbesar Orang Asli: Negrito (Semang), Senoi dan Melayu Proto.', '{"clueText":"Nota Tok Batin: Di Semenanjung Malaysia, Orang Asli terbahagi kepada tiga kumpulan terbesar. Mereka istimewa kerana mengekalkan kemahiran kraf tangan, ubat-ubatan herba dan bahasa mengikut suku.","options":[{"text":"Negrito (Semang), Senoi dan Melayu Proto.","isCorrect":true},{"text":"Iban, Bidayuh dan Melanau.","isCorrect":false,"consequence":"Itu kaum di Sarawak. Tok Batin menggeleng dan budak bandar malu."},{"text":"Baba, Chetti dan Serani.","isCorrect":false,"consequence":"Itu kaum peranakan di bandar. Tok Batin menyuruh kau membaca semula."},{"text":"Murut, Rungus dan Bajau.","isCorrect":false,"consequence":"Itu kaum di Sabah. Kampung ketawa kecil dan kau tersipu."}],"aftermath":"Nota disalah baca dan tiga kumpulan itu keliru. Tok Batin berasa warisan mereka tidak dihargai.","turns":[{"after":3,"options":[{"text":"Orang Asli bukan kaum yang sama dengan kaum di Sarawak dan Sabah. Mereka ada tiga kumpulan sendiri.","isCorrect":true,"reaction":"Betul, nak. Sekarang kau mengenali kami dengan tepat."},{"text":"Semua kaum pribumi sama sahaja.","isCorrect":false,"reaction":"Tok Batin menarik nafas panjang. Kenyataan itu mengabaikan keunikan kami."},{"text":"Orang Asli hanya wujud di Sabah.","isCorrect":false,"reaction":"Kampung terdiam. Orang Asli sebenarnya tinggal di Semenanjung."}],"clue":"Tiga kumpulan, bukan sama dengan kaum lain."}]}'),
(403, 'e4_n1_s3', 'Kad Kaum Peranakan dan Kaum Kecil', 'Padankan kaum dengan cirinya.', '4', 'Mengenal pasti Baba dan Nyonya, Chetti, Serani, Siam dan Sikh beserta ciri masing-masing.', '{"pairs":[{"text":"Baba dan Nyonya","pair":1},{"text":"Perkahwinan pedagang China dengan penduduk tempatan di Melaka","pair":1},{"text":"Chetti","pair":2},{"text":"Perkahwinan pedagang India dengan penduduk tempatan, bahasa Melayu kreol","pair":2},{"text":"Serani","pair":3},{"text":"Orang Eurasia, tarian branyo dan frapeirra","pair":3},{"text":"Siam","pair":4},{"text":"Menyambut Songkran dan beribadat di wat","pair":4},{"text":"Sikh","pair":5},{"text":"Sarban, bahasa Punjabi dan tarian bhangra","pair":5}],"aftermath":"Kad berselerak dan ciri kaum tersalah letak. Pelanggan pasar tersinggung apabila kaum mereka disalah sebut.","turns":[{"after":3,"options":[{"text":"Mereka menjadi kaum tersendiri dengan bahasa, adat dan makanan yang unik.","isCorrect":true,"reaction":"Itu jawapan yang menghormati mereka, pakcik."},{"text":"Mereka hanya ikut kaum lain, jadi tiada keunikan.","isCorrect":false,"reaction":"Penjual kuih menarik muka masam. Budaya mereka bukan tiruan."},{"text":"Mereka tidak termasuk dalam kepelbagaian kaum.","isCorrect":false,"reaction":"Sikh dan Chetti berasa disisih daripada senarai kaum negara."}],"clue":"Setiap kaum ada keunikan tersendiri."}]}'),
(404, 'e4_n1_s4', 'Catatan Dua Kaum Terbesar', 'Baca catatan dan tentukan kaum terbesar di Sarawak dan Sabah.', '5', 'Mengenal pasti kaum terbesar di Sarawak (Iban) dan Sabah (Kadazandusun).', '{"clueText":"Catatan: Merupakan kaum terbesar di Sarawak, kaum ini bertutur dalam bahasa Iban. Di Sabah pula, kaum terbesar bertutur mengikut dialek sukuan masing-masing dan memakai pakaian tradisional semasa Pesta Kaamatan.","options":[{"text":"Iban di Sarawak dan Kadazandusun di Sabah.","isCorrect":true},{"text":"Bidayuh di Sarawak dan Bajau di Sabah.","isCorrect":false,"consequence":"Bidayuh dan Bajau memang ada, tetapi bukan yang terbesar. Apai Iban berkerut dahi."},{"text":"Melanau di Sarawak dan Murut di Sabah.","isCorrect":false,"consequence":"Dua kaum ini bukan yang terbesar. Linda menggeleng kepala."},{"text":"Kayan di Sarawak dan Rungus di Sabah.","isCorrect":false,"consequence":"Catatan tidak menyebut kaum itu. Kau dipandang hairan."}],"aftermath":"Catatan tersilap baca dan pengunjung diberi maklumat yang salah tentang kaum terbesar di Sarawak dan Sabah.","turns":[{"after":3,"options":[{"text":"Kedua-duanya terbesar di negeri masing-masing, dan keunikan kedua-duanya wajar dihargai.","isCorrect":true,"reaction":"Itu cara yang adil, dan kami berdua tersenyum."},{"text":"Hanya Iban yang penting kerana Sarawak lebih besar.","isCorrect":false,"reaction":"Linda tersinggung dan perbalahan negeri bermula."},{"text":"Hanya Kadazandusun yang penting kerana Sabah lebih makmur.","isCorrect":false,"reaction":"Apai Iban berpaling muka dan majlis menjadi dingin."}],"clue":"Kedua-duanya terbesar di negeri masing-masing."}]}'),
(405, 'e4_n1_s5', 'Cari Lima Sudut Pentas', 'Cari lima sudut pentas yang mewakili Melayu, Cina, India, Sarawak dan Sabah.', '2', 'Mengenal pasti alat muzik dan tarian mengikut kaum: Melayu, Cina, India, Sarawak dan Sabah.', '{"bgImage":"../assets/gameAsset/background/alat_muzik_dan_tarian_tradisional.png","hotspots":[{"name":"Pentas Melayu: gambus dan angklung; tarian makyung dan zapin","top":"25%","left":"32%"},{"name":"Tarian singa: gendang dan bo; masyarakat Cina","top":"22.6%","left":"52.7%"},{"name":"Pentas India: veenai dan talam; tarian bharata natyam","top":"64.4%","left":"32.8%"},{"name":"Pentas Sarawak: sape dan engkerurai; tarian ngajat","top":"61%","left":"62%"},{"name":"Pentas Sabah: kulintangan dan sompoton; tarian sumazau","top":"51.6%","left":"71.7%"}],"aftermath":"Pentas tersilap susun. Alat muzik yang salah dibunyikan dan tarian bertukar tempat.","turns":[{"after":1,"options":[{"text":"Alat muzik dan tarian ialah warisan yang membentuk identiti negara kita.","isCorrect":true,"reaction":"Betul, pakcik. Kami akan menjaganya."},{"text":"Alat muzik lama tidak perlu dijaga lagi.","isCorrect":false,"reaction":"Orang tua di barisan hadapan menggeleng kecewa."},{"text":"Cukuplah alat muzik moden sahaja.","isCorrect":false,"reaction":"Pemuzik lain tersinggung kerana warisan mereka dipandang rendah."}],"clue":"Warisan membentuk identiti negara."}]}'),
(406, 'e4_n1_s6', 'Bengkel Alat Muzik', 'Padankan alat muzik dengan bahan atau cirinya.', '4', 'Mengenal pasti ciri alat muzik: angklung, gambus, nafiri, geduk, sape dan sompoton.', '{"pairs":[{"text":"Angklung","pair":1},{"text":"Buluh diikat pada rangka yang disebut ancak","pair":1},{"text":"Gambus","pair":2},{"text":"Dibuat daripada kayu keras seperti kayu pokok nangka","pair":2},{"text":"Nafiri","pair":3},{"text":"Diperbuat daripada logam, lazimnya perak","pair":3},{"text":"Geduk","pair":4},{"text":"Gendang dua muka dari belulang lembu atau kerbau","pair":4},{"text":"Sape","pair":5},{"text":"Diperbuat daripada kayu meranti, tali dipetik","pair":5},{"text":"Sompoton","pair":6},{"text":"Buluh dilekatkan pada labu kering dengan lilin kelulut","pair":6}],"aftermath":"Bahan tersilap padan dan alat muzik rosak sebelum dimainkan. Murid itu semakin yakin warisan tidak berguna.","turns":[{"after":1,"options":[{"text":"Alat lama dibuat daripada bahan alam menunjukkan kebijaksanaan pencipta, jadi wajar dihargai.","isCorrect":true,"reaction":"Betul, pakcik. Aku mahu belajar membuat angklung."},{"text":"Alat lama tidak istimewa kerana murah.","isCorrect":false,"reaction":"Pemuzik tua terdiam. Kebijaksanaan nenek moyang direndahkan."},{"text":"Alat lama patut dibuang kerana lama.","isCorrect":false,"reaction":"Kata-kata itu menyakiti hati orang yang menjaga bengkel ini."}],"clue":"Bahan alam, kebijaksanaan pencipta."}]}'),
(407, 'e4_n1_s7', 'Senarai Tarian Pentas', 'Padankan tarian dengan ciri atau tujuannya.', '4', 'Mengenal pasti tarian makyung, zapin, singa, bharata natyam, ngajat dan sumazau serta tujuannya.', '{"pairs":[{"text":"Makyung","pair":1},{"text":"Seni drama: lakonan, tarian, muzik dan nyanyian","pair":1},{"text":"Zapin","pair":2},{"text":"Hiburan semasa pesta dan majlis perkahwinan","pair":2},{"text":"Tarian singa","pair":3},{"text":"Tahun Baharu Cina, lambang keharmonian","pair":3},{"text":"Bharata natyam","pair":4},{"text":"Pembuka tirai persembahan kebudayaan India","pair":4},{"text":"Ngajat","pair":5},{"text":"Kaum Iban semasa Hari Gawai dan upacara ritual","pair":5},{"text":"Sumazau","pair":6},{"text":"Menghormati semangat padi, Pesta Kaamatan","pair":6}],"aftermath":"Senarai tersilap dan penari naik pentas tidak sepadan dengan iringan muzik. Penonton tertanya-tanya dan majlis kelam-kabut.","turns":[{"after":1,"options":[{"text":"Setiap tarian ada maksud dan tujuan, jadi iringan muzik mesti betul.","isCorrect":true,"reaction":"Betul, pakcik. Iringan ngajat memang berbeza."},{"text":"Tarian hanya hiburan, iringan tidak penting.","isCorrect":false,"reaction":"Penari ngajat kecewa kerana irama bukan irama mereka."},{"text":"Semua tarian boleh diiringi satu muzik sahaja.","isCorrect":false,"reaction":"Penonton hairan kerana tarian berbeza tetapi bunyi sama."}],"clue":"Tarian ada makna dan iringan tersendiri."}]}'),
(408, 'e4_n1_s8', 'Kad Tarian Api Unggun', 'Baca kad dan tentukan tarian identiti Orang Asli.', '5', 'Mengenal pasti tarian sewang sebagai identiti masyarakat Orang Asli, dan bhangra sebagai tarian masyarakat Sikh.', '{"clueText":"Kad: Tarian ini menjadi identiti masyarakat Orang Asli. Penari menghias diri dengan selempang bunga-bungaan, daun kelapa, daun palas, daun nipah dan kulit kayu. Alat muziknya ialah buluh centong, gendang, kereb, pensol dan tetawak. Ia untuk upacara ritual, perubatan dan majlis keramaian.","options":[{"text":"Tarian sewang.","isCorrect":true},{"text":"Tarian bhangra.","isCorrect":false,"consequence":"Bhangra ditarikan oleh masyarakat Sikh dengan dram dhol. Tok Batin mengangkat kening."},{"text":"Tarian ngajat.","isCorrect":false,"consequence":"Ngajat ialah tarian kaum Iban di Sarawak. Kau dipandang hairan."},{"text":"Tarian sumazau.","isCorrect":false,"consequence":"Sumazau ditarikan kaum Kadazandusun di Sabah. Kad dikembalikan."}],"aftermath":"Kad tersalah baca dan tarian identiti Orang Asli tersilap diperkenalkan. Tok Batin berasa hampa.","turns":[{"after":3,"options":[{"text":"Dengan mengenali tarian setiap kaum, kita belajar menghormati cara hidup mereka.","isCorrect":true,"reaction":"Itu yang kami harapkan, nak."},{"text":"Tarian Orang Asli tidak penting untuk dipelajari.","isCorrect":false,"reaction":"Tok Batin menunduk. Kata-kata itu menutup pintu persahabatan."},{"text":"Tarian setiap kaum sama sahaja.","isCorrect":false,"reaction":"Tok Batin menggeleng. Perbezaan itulah keunikan kami."}],"clue":"Kenali tarian untuk menghormati kaum."}]}'),
(409, 'e4_n2_s1', 'Catatan Laci Pertama', 'Baca catatan dan tentukan petempatan dan kegiatan ekonomi masyarakat Melayu dahulu.', '5', 'Mengenal pasti petempatan dan ekonomi Melayu dahulu: kampung, pesisir pantai dan sungai; petani, nelayan, peniaga kecil dan perkhidmatan awam.', '{"clueText":"Catatan: Sebelum merdeka, petempatan penduduk berdasarkan kegiatan ekonomi atau pekerjaan masing-masing. Masyarakat ini tinggal di kampung, persisiran pantai dan sungai, bekerja sebagai petani, nelayan, peniaga kecil-kecilan dan dalam perkhidmatan awam.","options":[{"text":"Melayu: kampung, pesisir pantai dan sungai; petani, nelayan, peniaga kecil dan perkhidmatan awam.","isCorrect":true},{"text":"Melayu: bandar besar; pelombong dan peniaga besar.","isCorrect":false,"consequence":"Itu gambaran masyarakat Cina. Cucu-cucu menggeleng kepala."},{"text":"Melayu: ladang getah; pekerja ladang dan pekerja pelabuhan.","isCorrect":false,"consequence":"Itu kegiatan masyarakat India dahulu. Nenek mengeluh perlahan."},{"text":"Melayu: pedalaman hutan; pemburu dan pengutip hasil hutan.","isCorrect":false,"consequence":"Itu kegiatan Orang Asli. Catatan dikembalikan."}],"aftermath":"Catatan tersalah baca dan cucu-cucu menyangka semua orang Melayu dahulu sama pekerjaan.","turns":[{"after":1,"options":[{"text":"Petempatan dahulu mengikut sumber, jadi kampung dekat sungai dan pantai.","isCorrect":true,"reaction":"Betul, nenek. Sekarang kami faham."},{"text":"Petempatan dahulu dipilih secara rawak.","isCorrect":false,"reaction":"Cucu-cucu keliru kerana tiada sebab di sebalik pilihan itu."},{"text":"Petempatan dahulu hanya di bandar.","isCorrect":false,"reaction":"Catatan membuktikan salah. Mereka tinggal di kampung dan tepi sungai."}],"clue":"Petempatan mengikut kegiatan ekonomi."}]}'),
(410, 'e4_n2_s2', 'Dua Laci, Dua Kaum', 'Padankan petempatan dan pekerjaan masyarakat Cina dan India dahulu.', '4', 'Mengenal pasti petempatan dan pekerjaan Cina (pekan dan bandar; pelombong dan peniaga) dan India (ladang dan pinggir bandar; ladang, peniaga kecil, pekerja pelabuhan).', '{"pairs":[{"text":"Cina: tempat tinggal","pair":1},{"text":"Pekan dan bandar","pair":1},{"text":"Cina: pekerjaan","pair":2},{"text":"Pelombong dan peniaga","pair":2},{"text":"India: tempat tinggal","pair":3},{"text":"Ladang dan pinggir bandar","pair":3},{"text":"India: pekerjaan","pair":4},{"text":"Pekerja ladang, peniaga kecil dan pekerja pelabuhan","pair":4}],"aftermath":"Laci bertukar isi dan cucu-cucu berselisih tentang cerita datuk mereka sendiri.","turns":[{"after":3,"options":[{"text":"Kedua-dua cerita betul kerana setiap kaum mempunyai pekerjaan dan tempat tinggal berbeza.","isCorrect":true,"reaction":"Nenek bijak. Kami tidak berbalah lagi."},{"text":"Cerita Ah Meng betul, cerita Kavitha salah.","isCorrect":false,"reaction":"Kavitha merajuk kerana cerita datuknya dinafikan."},{"text":"Cerita Kavitha betul, cerita Ah Meng salah.","isCorrect":false,"reaction":"Ah Meng terdiam dan menunduk malu."}],"clue":"Dua cerita, dua pekerjaan, kedua-duanya benar."}]}'),
(411, 'e4_n2_s3', 'Catatan Laci Ketiga', 'Baca catatan dan tentukan petempatan dan kegiatan Orang Asli dahulu.', '5', 'Mengenal pasti petempatan Orang Asli dahulu: pedalaman, terutama di Perak, Selangor, Pahang, Kelantan dan Terengganu; kraf tangan, berburu dan hasil hutan.', '{"clueText":"Catatan: Masyarakat ini tinggal di pedalaman, terutama di Perak, Selangor, Pahang, Kelantan dan Terengganu. Mereka mengusahakan kegiatan kraf tangan, berburu dan mengutip hasil hutan.","options":[{"text":"Pedalaman: kraf tangan, berburu dan mengutip hasil hutan.","isCorrect":true},{"text":"Bandar: melombong dan berniaga.","isCorrect":false,"consequence":"Itu kegiatan masyarakat Cina dahulu. Tok Batin senyum nipis."},{"text":"Ladang: menoreh getah dan bekerja di pelabuhan.","isCorrect":false,"consequence":"Itu kegiatan India dahulu. Catatan dikembalikan."},{"text":"Pantai: nelayan dan pembuat perahu sahaja.","isCorrect":false,"consequence":"Itu gambaran pesisir pantai. Catatan menyebut pedalaman."}],"aftermath":"Catatan disalah baca dan Orang Asli dikatakan duduk di bandar. Tok Batin menggeleng.","turns":[{"after":2,"options":[{"text":"Mereka bergantung kepada hutan dan kraf tangan kerana tinggal di pedalaman.","isCorrect":true,"reaction":"Betul, nenek. Hutan ialah kampung mereka."},{"text":"Mereka bergantung kepada kilang kerana tinggal dekat bandar.","isCorrect":false,"reaction":"Cucu-cucu ketawa kecil kerana catatan menyebut pedalaman."},{"text":"Mereka tidak bekerja kerana hasil hutan tidak berharga.","isCorrect":false,"reaction":"Tok Batin terguris. Hasil hutan ialah rezeki mereka."}],"clue":"Hutan ialah sumber utama mereka."}]}'),
(412, 'e4_n2_s4', 'Peta Kaum Sarawak', 'Padankan kaum di Sarawak dengan petempatan dan kegiatan ekonominya dahulu.', '4', 'Mengenal pasti petempatan dan ekonomi kaum di Sarawak dahulu: pedalaman (Bidayuh, Kenyah, Kelabit), lembah sungai (Iban, Bisaya), pesisir pantai (Melayu, Melanau, Kedayan).', '{"pairs":[{"text":"Bidayuh, Kenyah dan Kelabit","pair":1},{"text":"Pedalaman: padi sawah, padi bukit dan hasil hutan","pair":1},{"text":"Iban dan Bisaya","pair":2},{"text":"Lembah sungai: petani","pair":2},{"text":"Melayu, Melanau dan Kedayan","pair":3},{"text":"Pesisir pantai: pedagang, pembuat perahu, pengusaha sagu","pair":3}],"aftermath":"Peta tersilap dan cucu-cucu menyangka semua kaum Sarawak hidup dengan cara yang sama.","turns":[{"after":2,"options":[{"text":"Kaum yang berbeza tinggal di tempat berbeza kerana sumber dan pekerjaan mereka berbeza.","isCorrect":true,"reaction":"Betul, nenek. Kami mengenali jiran sendiri."},{"text":"Semua kaum Sarawak tinggal di tepi laut.","isCorrect":false,"reaction":"Apai Iban membantah kerana kaumnya di lembah sungai."},{"text":"Kaum Sarawak tidak mempunyai petempatan tetap.","isCorrect":false,"reaction":"Jenny berkerut dahi kerana kaumnya jelas tinggal di lembah sungai."}],"clue":"Sumber alam menentukan petempatan."}]}'),
(413, 'e4_n2_s5', 'Peta Kaum Sabah', 'Padankan kaum di Sabah dengan petempatan dan kegiatannya dahulu.', '4', 'Mengenal pasti petempatan dan ekonomi kaum di Sabah dahulu: Murut, Kadazandusun, Rungus, Bajau, Melayu Brunei, Iranun dan Suluk.', '{"pairs":[{"text":"Murut","pair":1},{"text":"Pedalaman: petani dan mengutip hasil hutan","pair":1},{"text":"Kadazandusun","pair":2},{"text":"Pedalaman: mengusahakan padi","pair":2},{"text":"Rungus","pair":3},{"text":"Pedalaman: terkenal dalam seni perusahaan kreatif","pair":3},{"text":"Bajau","pair":4},{"text":"Petani atau nelayan","pair":4},{"text":"Melayu Brunei, Iranun, Suluk","pair":5},{"text":"Pesisir pantai: nelayan, pembuat perahu, pedagang","pair":5}],"aftermath":"Peta tersilap dan cucu-cucu menyangka semua kaum Sabah menangkap ikan. Pak Bajau menggeleng.","turns":[{"after":2,"options":[{"text":"Bajau boleh menjadi petani atau nelayan, dan kaum lain mempunyai kerja mereka sendiri.","isCorrect":true,"reaction":"Itu betul, nenek. Terima kasih."},{"text":"Semua kaum Sabah menjadi nelayan.","isCorrect":false,"reaction":"Linda memprotes kerana kaumnya mengusahakan padi di pedalaman."},{"text":"Semua kaum Sabah tinggal di bandar.","isCorrect":false,"reaction":"Pak Bajau tergelak kerana petempatan dahulu bukan di bandar."}],"clue":"Setiap kaum mempunyai kegiatan sendiri."}]}'),
(414, 'e4_n2_s6', 'Dari Berasingan kepada Bersama', 'Susun perubahan petempatan dan ekonomi daripada dahulu hingga kini.', '1', 'Memahami perubahan: dahulu petempatan ikut ekonomi; selepas merdeka dan pembentukan Malaysia pemimpin merancang dasar; kini tiada pengasingan tempat tinggal.', '{"timelineItems":[{"id":1,"year":"Sebelum merdeka","text":"Petempatan penduduk berdasarkan kegiatan ekonomi atau pekerjaan masing-masing","why":"Pengasingan tempat tinggal berlaku mengikut pekerjaan."},{"id":2,"year":"Selepas merdeka","text":"Negara semakin makmur dan pemimpin merancang pelbagai dasar pembangunan","why":"Pemimpin mula merancang dasar untuk mengurangkan jurang."},{"id":3,"year":"Seterusnya","text":"Usaha menangani kegiatan ekonomi berasaskan kaum menampakkan kejayaan","why":"Dasar yang dirancang membawa hasil."},{"id":4,"year":"Kini","text":"Rakyat bekerja bersama dan tinggal dalam satu kawasan perumahan tanpa pemisahan","why":"Toleransi dan kemakmuran membolehkan semua hidup bersama."}],"aftermath":"Susunan tersilap dan cucu menyangka petempatan berasingan masih berlaku hari ini.","turns":[{"after":1,"options":[{"text":"Sikap toleransi dan kemakmuran membolehkan kita hidup bersama dalam satu kawasan.","isCorrect":true,"reaction":"Itu jawapan yang membuat nenek tersenyum."},{"text":"Kerana semua orang dipaksa berpindah.","isCorrect":false,"reaction":"Cucu-cucu berasa tidak adil. Tiada catatan paksaan itu."},{"text":"Kerana semua orang bekerja sama jenis kerja.","isCorrect":false,"reaction":"Fakta itu salah. Kini rakyat bekerja dalam pelbagai sektor."}],"clue":"Toleransi dan kemakmuran menyatukan rakyat."}]}'),
(415, 'e4_n2_s7', 'Helah Si Luncai', 'Susun kejadian cerita Si Luncai dengan Labu-labunya mengikut urutan.', '1', 'Memahami jalan cerita Si Luncai dengan Labu-labunya dan iktibar jangan mempersendakan orang lain.', '{"timelineItems":[{"id":1,"year":"Mula-mula","text":"Si Luncai dihukum raja kerana mempermain-mainkan raja dan pembesar","why":"Itulah punca hukumannya."},{"id":2,"year":"Kemudian","text":"Pesuruh raja memasukkan Si Luncai ke dalam guni dan membawanya dengan perahu ke tengah laut","why":"Hukuman mula dijalankan."},{"id":3,"year":"Seterusnya","text":"Si Luncai menyanyikan lagu Si Luncai terjun dengan labu-labunya sehingga pesuruh raja leka","why":"Helahnya menghilangkan perhatian pesuruh."},{"id":4,"year":"Akhirnya","text":"Si Luncai terjun dengan labu air dan pesuruh raja mencampakkan guni berisi labu","why":"Si Luncai selamat sampai ke pantai."}],"aftermath":"Susunan tersilap dan cerita menjadi kelucuan sahaja, tanpa iktibar yang jelas.","turns":[{"after":2,"options":[{"text":"Si Luncai bijak kerana boleh memperdaya pesuruh raja, tetapi iktibarnya jangan mempersendakan orang lain.","isCorrect":true,"reaction":"Betul, nenek. Kami faham iktibarnya."},{"text":"Si Luncai patut ditiru kerana suka mempermain-mainkan orang.","isCorrect":false,"reaction":"Nenek mengerut dahi. Itu bukan pengajaran yang betul."},{"text":"Si Luncai tidak bijak sama sekali.","isCorrect":false,"reaction":"Cucu-cucu bertanya semula kerana beliau berjaya terlepas."}],"clue":"Bijak, tetapi jangan mempersendakan orang lain."}]}'),
(416, 'e4_n2_s8', 'Kad Legenda Santubong', 'Padankan watak dan perkara dalam legenda Santubong Sang Puteri.', '4', 'Memahami legenda Santubong: Puteri Santubong menenun, Puteri Sejinjang menumbuk padi, Putera Serapi dari Matang, dan iktibar jangan bertengkar sesama sendiri.', '{"pairs":[{"text":"Puteri Santubong","pair":1},{"text":"Pandai menenun kain","pair":1},{"text":"Puteri Sejinjang","pair":2},{"text":"Mahir menumbuk padi","pair":2},{"text":"Putera Serapi","pair":3},{"text":"Pemuda dari Matang yang disukai kedua-dua puteri","pair":3},{"text":"Pasir Kuning dan Pasir Putih","pair":4},{"text":"Dua kampung berjiran yang didamaikan","pair":4},{"text":"Akibat melanggar sumpah","pair":5},{"text":"Kedua-dua puteri bertukar menjadi gunung","pair":5}],"aftermath":"Kad bertukar dan legenda disalah ceritakan. Cucu-cucu menyangka kedua-dua puteri bersahabat sehingga akhir.","turns":[{"after":3,"options":[{"text":"Mereka bertukar menjadi gunung kerana bergaduh dan melanggar syarat.","isCorrect":true,"reaction":"Betul, nenek. Iktibarnya jangan bertengkar sesama sendiri."},{"text":"Mereka bertukar menjadi gunung kerana berjaya berdamai.","isCorrect":false,"reaction":"Cucu-cucu keliru. Mereka dikenakan padah kerana bergaduh."},{"text":"Mereka bertukar menjadi gunung kerana memakmurkan kampung.","isCorrect":false,"reaction":"Mereka memang memakmurkan kampung, tetapi bukan itu sebab menjadi gunung."}],"clue":"Padah kerana bergaduh sesama sendiri."}]}'),
(417, 'e4_n3_s1', 'Cari Lima Permainan di Gelanggang', 'Cari lima petunjuk permainan anjung, laman dan kawasan lapang.', '2', 'Mengenal pasti jenis permainan tradisional: anjung, laman dan kawasan lapang.', '{"bgImage":"../assets/gameAsset/background/permainan_tradisional.png","hotspots":[{"name":"Permainan anjung: congkak, batu seremban, go dan chaturangam","top":"28%","left":"15%"},{"name":"Permainan laman: sepak raga","top":"47.8%","left":"45.7%"},{"name":"Permainan lapang: wau di langit","top":"7.2%","left":"63.2%"},{"name":"Permainan lapang: gasing dan tibau","top":"46.3%","left":"62.7%"},{"name":"Permainan laman: chap teh dan kabaddi","top":"61.4%","left":"59.8%"}],"aftermath":"Petunjuk hilang dan permainan dimainkan di tempat tidak sesuai. Sepak raga terbang ke atas anjung.","turns":[{"after":2,"options":[{"text":"Permainan tradisional ada tiga jenis supaya sesuai dengan ruang dan alat.","isCorrect":true,"reaction":"Betul, Tok. Sekarang kami boleh bermain dengan betul."},{"text":"Semua permainan dimainkan di satu tempat sahaja.","isCorrect":false,"reaction":"Gelanggang menjadi sempit dan kanak-kanak berlanggar."},{"text":"Permainan tradisional tidak mempunyai jenis.","isCorrect":false,"reaction":"Kanak-kanak lain mengangkat kening kerana ada tiga jenis yang jelas."}],"clue":"Tiga jenis permainan."}]}'),
(418, 'e4_n3_s2', 'Nama dan Cara Bermain', 'Padankan permainan tradisional dengan cara bermainnya.', '4', 'Mengenal pasti ciri congkak, batu seremban, go, kabaddi, chap teh dan sepak raga.', '{"pairs":[{"text":"Congkak","pair":1},{"text":"Mengisi buah ke dalam lubang pada papan congkak","pair":1},{"text":"Batu seremban","pair":2},{"text":"Lima atau tujuh biji batu kecil dilambung dan disambut","pair":2},{"text":"Go atau Weiqi","pair":3},{"text":"Buah hitam dan putih, menguasai kawasan papan yang lebih besar","pair":3},{"text":"Kabaddi","pair":4},{"text":"Dua pasukan, tujuh pemain, menyentuh pihak lawan","pair":4},{"text":"Chap teh","pair":5},{"text":"Bola lawi bulu ayam ditating, juga dipanggil tating lawi","pair":5},{"text":"Sepak raga","pair":6},{"text":"Bola rotan ditimang dengan kaki, sejak zaman Kesultanan Melayu Melaka","pair":6}],"aftermath":"Padanan tersilap dan permainan dimainkan dengan cara yang salah. Gelanggang menjadi riuh dan kecoh.","turns":[{"after":3,"options":[{"text":"Setiap permainan ada cara bermain sendiri, jadi kita perlu mengenalinya sebelum bermain.","isCorrect":true,"reaction":"Betul, Tok. Kami tidak berbalah lagi."},{"text":"Semua permainan sama sahaja kerana semuanya hiburan.","isCorrect":false,"reaction":"Kanak-kanak membantah kerana alat dan caranya berbeza."},{"text":"Cara bermain tidak penting asalkan menang.","isCorrect":false,"reaction":"Permainan menjadi kecoh dan sesetengah kanak-kanak merajuk."}],"clue":"Setiap permainan ada cara tersendiri."}]}'),
(419, 'e4_n3_s3', 'Empat Permainan Lapang', 'Padankan permainan kawasan lapang dengan ciri atau tempatnya.', '4', 'Mengenal pasti permainan kawasan lapang: wau, tibau, sepak manggis dan gasing.', '{"pairs":[{"text":"Wau","pair":1},{"text":"Lazimnya dimainkan selepas musim menuai","pair":1},{"text":"Tibau","pair":2},{"text":"Pesta Kaul oleh masyarakat Melanau, Sarawak","pair":2},{"text":"Sepak manggis","pair":3},{"text":"Majlis keramaian di Kota Belud, Sabah, sepak bola ke hadiah","pair":3},{"text":"Gasing","pair":4},{"text":"Gasing uri dan gasing pangkah","pair":4}],"aftermath":"Kad tersilap dan kanak-kanak bermain di acara yang salah. Pesta berlangsung dalam kekeliruan.","turns":[{"after":1,"options":[{"text":"Permainan lapang dimainkan di padang kerana memerlukan ruang yang luas.","isCorrect":true,"reaction":"Betul, Tok. Wau tidak boleh terbang di anjung."},{"text":"Permainan lapang boleh dimainkan di dalam bilik.","isCorrect":false,"reaction":"Wau tersangkut di langit-langit dan kanak-kanak ketawa."},{"text":"Permainan lapang tidak memerlukan ruang.","isCorrect":false,"reaction":"Gasing mengenai kaki kawan-kawan kerana ruang sempit."}],"clue":"Permainan lapang perlukan ruang luas."}]}'),
(420, 'e4_n3_s4', 'Kad Catur Peperangan', 'Baca kad dan tentukan permainan yang menyerupai catur dan melambangkan peperangan.', '5', 'Mengenal pasti chaturangam sebagai permainan seperti catur, simulasi peperangan, dan paramapadham seperti dam ular.', '{"clueText":"Kad: Permainan ini dimainkan oleh dua orang pemain, umpama simulasi peperangan bagi memperlihatkan kekuatan tentera. Kemenangan bergantung pada kejayaan menakluk lawan, terutamanya menewaskan raja.","options":[{"text":"Chaturangam.","isCorrect":true},{"text":"Paramapadham.","isCorrect":false,"consequence":"Paramapadham seperti dam ular dan menggunakan dadu. Kad dikembalikan."},{"text":"Congkak.","isCorrect":false,"consequence":"Congkak menggunakan papan berlubang, bukan raja dan tentera. Kanak-kanak ketawa."},{"text":"Yoyo Cina.","isCorrect":false,"consequence":"Yoyo Cina dimainkan secara perseorangan. Kad dikembalikan."}],"aftermath":"Kad tersalah baca dan kanak-kanak menyangka paramapadham menewaskan raja. Permainan jadi huru-hara.","turns":[{"after":3,"options":[{"text":"Permainan dari pelbagai budaya dimainkan bersama di negara kita, dan itu memupuk toleransi.","isCorrect":true,"reaction":"Betul, Tok. Kami main semua permainan sekarang."},{"text":"Permainan luar tidak patut dimainkan di sini.","isCorrect":false,"reaction":"Kanak-kanak kecewa kerana mahu bermain dengan semua kawan."},{"text":"Permainan dari luar lebih baik daripada permainan kita.","isCorrect":false,"reaction":"Kanak-kanak tempatan terguris dan perbalahan bermula."}],"clue":"Pelbagai permainan menyatukan kanak-kanak."}]}'),
(421, 'e4_n3_s5', 'Papan Warisan Kebangsaan', 'Baca papan kenyataan dan tentukan permainan yang diangkat sebagai warisan kebangsaan.', '5', 'Mengenal pasti permainan warisan kebangsaan: congkak, batu seremban, kabaddi, tating lawi, menyumpit, pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli.', '{"clueText":"Papan kenyataan: Congkak, batu seremban, kabaddi, tating lawi, menyumpit, pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli telah diangkat sebagai warisan kebangsaan negara.","options":[{"text":"Congkak dan sepak raga.","isCorrect":true},{"text":"Bola sepak dan badminton.","isCorrect":false,"consequence":"Itu sukan moden yang tiada dalam senarai warisan. Papan menunjukkan permainan tradisional."},{"text":"Boling dan tenis.","isCorrect":false,"consequence":"Itu sukan moden. Kanak-kanak menggeleng."},{"text":"Permainan komputer.","isCorrect":false,"consequence":"Permainan komputer bukan permainan tradisional warisan kebangsaan."}],"aftermath":"Papan tersilap baca dan permainan moden dikatakan warisan kebangsaan. Kanak-kanak keliru.","turns":[{"after":2,"options":[{"text":"Permainan tradisional diangkat sebagai warisan supaya generasi akan datang terus memainkannya.","isCorrect":true,"reaction":"Betul, Tok. Kami mahu mengajar adik-adik."},{"text":"Permainan tradisional tidak perlu dikekalkan.","isCorrect":false,"reaction":"Tok menarik muka masam. Warisan akan hilang tanpa usaha kita."},{"text":"Permainan tradisional hanya untuk orang tua.","isCorrect":false,"reaction":"Kanak-kanak ketawa kerana mereka sendiri suka bermain."}],"clue":"Kekalkan permainan tradisional untuk generasi akan datang."}]}'),
(422, 'e4_n3_s6', 'Cari Petunjuk Nunuk Ragang', 'Cari tiga petunjuk dalam legenda Nunuk Ragang.', '2', 'Memahami legenda Nunuk Ragang: kemunculan pelbagai kaum di Tambunan dan Ranau, ayam gergasi, pohon nunuk dan Sungai Liwagu.', '{"bgImage":"../assets/gameAsset/background/nunuk_ragang.png","hotspots":[{"name":"Pohon nunuk: tempat penduduk Sungai Liwagu berehat","top":"52.5%","left":"40.1%"},{"name":"Sungai Liwagu: tempat asal penduduk sebelum terbang dan berpecah","top":"80.4%","left":"86.7%"},{"name":"Ayam gergasi merah bertaji emas yang mengibar sayap","top":"35.5%","left":"46.6%"}],"aftermath":"Petunjuk tidak ditemui dan asal usul pelbagai kaum Sabah terus kabur.","turns":[{"after":1,"options":[{"text":"Legenda ini menggambarkan asal usul pelbagai kaum Sabah dan mengajar kita menghargai keturunan.","isCorrect":true,"reaction":"Betul, Tok. Kami bangga dengan asal usul kami."},{"text":"Legenda ini hanya cerita khayalan, tidak penting.","isCorrect":false,"reaction":"Linda berasa asal usul kaumnya dipandang remeh."},{"text":"Legenda ini bercerita tentang kemunculan kaum Iban.","isCorrect":false,"reaction":"Pak Bajau membetulkan kerana cerita ini tentang kaum di Tambunan dan Ranau."}],"clue":"Hargai asal usul keturunan."}]}'),
(423, 'e4_n3_s7', 'Kad Asas Perpaduan', 'Baca kad dan tentukan kepentingan bertoleransi antara kaum sebagai asas perpaduan.', '5', 'Memahami kepentingan bertoleransi: tiada pergaduhan, mengekalkan keharmonian dan kesejahteraan, mengukuhkan patriotisme, mengelakkan salah faham.', '{"clueText":"Kad: Sikap bertoleransi memastikan tidak berlakunya pergaduhan. Ia mengekalkan keharmonian dan kesejahteraan negara, mengukuhkan semangat patriotisme dalam diri, dan mengelakkan salah faham antara kaum.","options":[{"text":"Mengekalkan keharmonian dan mengelakkan salah faham antara kaum.","isCorrect":true},{"text":"Menambah salah faham supaya orang berhati-hati.","isCorrect":false,"consequence":"Kanak-kanak ketawa. Jawapan itu bertentangan dengan kad."},{"text":"Mengasingkan kaum supaya tidak berjumpa.","isCorrect":false,"consequence":"Perpisahan menambah curiga dan menjauhkan kawan."},{"text":"Memastikan satu kaum sahaja yang menentukan peraturan.","isCorrect":false,"consequence":"Kanak-kanak lain membantah kerana mereka tidak didengari."}],"aftermath":"Kad tersalah baca dan kanak-kanak terus berbalah. Permainan terhenti dan taman menjadi sunyi.","turns":[{"after":3,"options":[{"text":"Kita bertanya dan bertoleransi, kerana tidak semua yang kita tidak faham itu ejekan.","isCorrect":true,"reaction":"Itu jawapan yang matang, Tok. Mereka bersalam."},{"text":"Kita balas ejekan dengan ejekan.","isCorrect":false,"reaction":"Perbalahan menjadi pergaduhan dan kanak-kanak menangis."},{"text":"Kita larang mereka bercakap bahasa sendiri.","isCorrect":false,"reaction":"Larangan itu menyinggung perasaan dan mengundang bantahan."}],"clue":"Bertanya dan bertoleransi."}]}'),
(424, 'e4_n3_s8', 'Kepentingan Keunikan Budaya', 'Padankan perkara dengan kepentingannya.', '4', 'Memahami kepentingan menghargai keunikan budaya tempatan dan berkongsi maklumat tentang kepelbagaian kaum.', '{"pairs":[{"text":"Keunikan seni warisan","pair":1},{"text":"Menjadi tumpuan pelancong dari luar negara","pair":1},{"text":"Keunikan seni tradisional","pair":2},{"text":"Memupuk semangat patriotisme dalam diri rakyat","pair":2},{"text":"Keunikan budaya tempatan","pair":3},{"text":"Warisan negara yang perlu dipelihara","pair":3},{"text":"Berkongsi maklumat kaum","pair":4},{"text":"Memupuk persefahaman antara pelbagai kaum","pair":4},{"text":"Sikap hormat-menghormati","pair":5},{"text":"Mengeratkan perpaduan antara kaum","pair":5}],"aftermath":"Padanan tersilap dan murid yakin budaya tidak penting. Pelancong hanya mengambil gambar lalu pergi tanpa memahami.","turns":[{"after":1,"options":[{"text":"Keunikan budaya kita menjadi warisan dan menarik pelancong, jadi wajar dijaga.","isCorrect":true,"reaction":"Betul, Tok. Aku akan berkongsi dengan kawan-kawan."},{"text":"Budaya lama menyusahkan dan tidak perlu dijaga.","isCorrect":false,"reaction":"Murid lain terdiam kerana tidak setuju."},{"text":"Budaya hanya penting untuk orang tua.","isCorrect":false,"reaction":"Tok tersenyum pahit. Anak muda juga pewaris budaya."}],"clue":"Jaga budaya sebagai warisan."}]}'),
(501, 'e5_n1_s1', 'Kad Pengasas Agama', 'Padankan agama dan ajaran dengan pengasas atau asas ajarannya.', '4', 'Mengenal pasti pengasas dan asas agama: Islam, Kristian, Buddha, Sikh, Ajaran Konfusius dan Ajaran Tao.', '{"pairs":[{"text":"Islam","pair":1},{"text":"Menyembah Allah Yang Maha Esa","pair":1},{"text":"Kristian","pair":2},{"text":"Dibawa oleh Jesus Christ","pair":2},{"text":"Buddha","pair":3},{"text":"Diasaskan oleh Siddharta Gautama","pair":3},{"text":"Sikh","pair":4},{"text":"Diasaskan oleh Guru Nanak","pair":4},{"text":"Ajaran Konfusius","pair":5},{"text":"Diasaskan oleh Kung Fu Tze","pair":5},{"text":"Ajaran Tao","pair":6},{"text":"Diasaskan oleh Lao Tzu","pair":6}],"aftermath":"Kad tersilap padan dan projek sekolah mencatat pengasas yang salah. Sahabat-sahabat tersinggung.","turns":[{"after":4,"options":[{"text":"Setiap agama mempunyai pengasas dan asas sendiri, jadi catatan mesti betul.","isCorrect":true,"reaction":"Betul. Kami berasa dihormati."},{"text":"Semua agama sama sahaja, jadi tidak perlu catat.","isCorrect":false,"reaction":"Aishah menggeleng. Perbezaan itulah yang perlu dihormati."},{"text":"Cukup mencatat satu agama sahaja.","isCorrect":false,"reaction":"Sahabat-sahabat lain terkilan kerana agama mereka diabaikan."}],"clue":"Setiap agama ada pengasas sendiri."}]}'),
(502, 'e5_n1_s2', 'Rak Kitab Suci', 'Padankan kitab suci atau buku dengan agamanya.', '4', 'Mengenal pasti kitab suci: al-Quran (Islam), Bible (Kristian), Tipitaka (Buddha), Veda (Hindu), Sri Guru Granth Sahib (Sikh), Tao Te Ching (Tao).', '{"pairs":[{"text":"Al-Quran dan Hadis","pair":1},{"text":"Agama Islam","pair":1},{"text":"Bible","pair":2},{"text":"Agama Kristian","pair":2},{"text":"Tipitaka","pair":3},{"text":"Agama Buddha","pair":3},{"text":"Veda","pair":4},{"text":"Agama Hindu","pair":4},{"text":"Sri Guru Granth Sahib","pair":5},{"text":"Agama Sikh","pair":5},{"text":"Tao Te Ching","pair":6},{"text":"Ajaran Tao","pair":6}],"aftermath":"Kitab terletak di rak yang salah dan label bertukar. Seorang penganut tersinggung melihat kitab sucinya salah letak.","turns":[{"after":1,"options":[{"text":"Kitab suci perlu diletakkan di tempat yang betul sebagai tanda hormat kepada penganutnya.","isCorrect":true,"reaction":"Betul. Itu tanda hormat kepada agama kami."},{"text":"Letak sahaja kitab di mana-mana.","isCorrect":false,"reaction":"Penganut tersinggung. Kitab suci wajar dihormati."},{"text":"Kitab suci hanya buku biasa.","isCorrect":false,"reaction":"Daniel menggeleng. Bible kitab suci kami."}],"clue":"Hormati kitab suci setiap agama."}]}'),
(503, 'e5_n1_s3', 'Kad Hukum Karma', 'Baca kad dan tentukan kepercayaan penganut agama Hindu.', '5', 'Memahami agama Hindu: percaya Hukum Karma dan kelahiran semula selepas mati; kitab suci Veda.', '{"clueText":"Kad: Penganut agama ini mempercayai Hukum Karma yang berkaitan dengan kelakuan manusia semasa hidup dan kelahiran semula selepas mati. Kitab sucinya dikenali sebagai Veda.","options":[{"text":"Hukum Karma dan kelahiran semula selepas mati.","isCorrect":true},{"text":"Empat Kebenaran Mulia dan Jalan Lapan Lapis Mulia.","isCorrect":false,"consequence":"Itu ajaran Buddha. Kavitha mengangkat kening."},{"text":"Beribadat di gereja setiap hari Ahad.","isCorrect":false,"consequence":"Itu amalan penganut Kristian. Kad dikembalikan."},{"text":"Percaya kepada satu Tuhan bernama Waheguru.","isCorrect":false,"consequence":"Itu kepercayaan Sikh. Kavitha tersenyum nipis."}],"aftermath":"Kad tersalah baca dan kanak-kanak itu mengejek kepercayaan Kavitha. Mereka bertengkar.","turns":[{"after":3,"options":[{"text":"Kita tidak mengejek kerana setiap agama mengajar perkara baik dan perlu dihormati.","isCorrect":true,"reaction":"Betul. Kavitha tersenyum lega."},{"text":"Kita boleh mengejek sedikit sahaja.","isCorrect":false,"reaction":"Kavitha terdiam dan menunduk."},{"text":"Kita abaikan sahaja kepercayaan itu.","isCorrect":false,"reaction":"Kanak-kanak lain tidak belajar apa-apa tentang kawan mereka."}],"clue":"Hormati kepercayaan setiap agama."}]}'),
(504, 'e5_n1_s4', 'Kad Ajaran Konfusius', 'Baca kad dan tentukan prinsip moral dalam Ajaran Konfusius.', '5', 'Memahami Ajaran Konfusius: prinsip moral tinggi seperti perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa; terkandung dalam buku Analek. Ajaran Tao: keharmonian dengan alam semesta.', '{"clueText":"Kad: Penganut ajaran ini percaya ajarannya menekankan prinsip moral yang tinggi seperti perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa. Ajaran ini terkandung dalam buku Analek dan diasaskan oleh Kung Fu Tze.","options":[{"text":"Ajaran Konfusius.","isCorrect":true},{"text":"Ajaran Tao.","isCorrect":false,"consequence":"Ajaran Tao diasaskan oleh Lao Tzu dan menekankan keharmonian dengan alam semesta. Kenny menggeleng."},{"text":"Agama Hindu.","isCorrect":false,"consequence":"Agama Hindu berkaitan Hukum Karma dan Veda. Kad dikembalikan."},{"text":"Agama Kristian.","isCorrect":false,"consequence":"Agama Kristian dibawa oleh Jesus Christ. Kenny tersenyum sedikit."}],"aftermath":"Kad tersalah baca dan Konfusius dikatakan sama dengan Tao. Kenny berasa ajaran mereka tidak dihargai.","turns":[{"after":3,"options":[{"text":"Kedua-dua ajaran berbeza, jadi kita perlu menghormati perbezaan itu.","isCorrect":true,"reaction":"Itu yang kami harapkan."},{"text":"Kedua-duanya sama sahaja, tidak perlu dibezakan.","isCorrect":false,"reaction":"Kenny kecewa. Perbezaan itu penting."},{"text":"Salah satu ajaran lebih baik daripada yang lain.","isCorrect":false,"reaction":"Perbandingan itu menyinggung penganut yang berbeza."}],"clue":"Hormati perbezaan ajaran."}]}'),
(505, 'e5_n1_s5', 'Nota Penyebaran Agama', 'Baca nota dan tentukan cara penyebaran agama di Malaysia.', '5', 'Memahami agama disebarkan melalui peranan pemerintah, pedagang dan golongan agama.', '{"clueText":"Nota: Terdapat pelbagai agama di Malaysia seperti agama Islam, Kristian, Buddha, Hindu dan Sikh. Terdapat juga ajaran Konfusius dan Tao. Penyebaran agama tersebut berlaku dengan pelbagai cara.","options":[{"text":"Melalui peranan pemerintah, pedagang dan golongan agama.","isCorrect":true},{"text":"Melalui perang dan paksaan sahaja.","isCorrect":false,"consequence":"Pernyataan itu tiada dalam nota. Murid mengerutkan dahi."},{"text":"Melalui pasar malam sahaja.","isCorrect":false,"consequence":"Jawapan itu mengelirukan dan tidak berasas."},{"text":"Melalui hadiah wang kepada rakyat.","isCorrect":false,"consequence":"Nota tidak menyebut hadiah wang. Kau diminta membaca semula."}],"aftermath":"Nota tersalah baca dan murid menyangka agama tersebar melalui paksaan. Sahabat-sahabat tersinggung.","turns":[{"after":1,"options":[{"text":"Agama tersebar melalui pelbagai cara yang aman, dan itu patut kita hormati.","isCorrect":true,"reaction":"Betul. Kami berasa lega."},{"text":"Agama tersebar kerana paksaan.","isCorrect":false,"reaction":"Murid-murid bertengkar sesama sendiri."},{"text":"Agama tersebar secara kebetulan.","isCorrect":false,"reaction":"Cikgu menggeleng kerana ada sebab dan cara yang jelas."}],"clue":"Penyebaran melalui cara yang aman."}]}'),
(506, 'e5_n1_s6', 'Amalan Setiap Agama', 'Padankan agama atau ajaran dengan amalan atau kepercayaannya.', '4', 'Mengenal pasti amalan dan kepercayaan: Islam (Rukun Islam dan Rukun Iman), Kristian (Ahad), Sikh (Waheguru), Buddha (Empat Kebenaran Mulia), Tao (Tao jalan).', '{"pairs":[{"text":"Islam","pair":1},{"text":"Dua teras: Rukun Islam dan Rukun Iman","pair":1},{"text":"Kristian","pair":2},{"text":"Ahad dikhaskan untuk aktiviti keagamaan di gereja","pair":2},{"text":"Sikh","pair":3},{"text":"Percaya kepada satu Tuhan bernama Waheguru","pair":3},{"text":"Buddha","pair":4},{"text":"Empat Kebenaran Mulia dan Jalan Lapan Lapis Mulia","pair":4},{"text":"Ajaran Tao","pair":5},{"text":"Tao bermaksud jalan, hidup harmoni dengan alam","pair":5}],"aftermath":"Kad tersilap dan amalan satu agama diletakkan pada agama lain. Rakan-rakan terasa dipinggirkan.","turns":[{"after":3,"options":[{"text":"Amalan setiap agama berbeza, dan kita perlu memahaminya supaya dapat menghormati.","isCorrect":true,"reaction":"Betul, itu membantu kami hidup aman."},{"text":"Amalan agama lain tidak perlu dipelajari.","isCorrect":false,"reaction":"Rakan-rakan terasa disisih."},{"text":"Amalan semua agama sama sahaja.","isCorrect":false,"reaction":"Itu salah, dan kau dibetulkan oleh rakan-rakan."}],"clue":"Fahami amalan agama lain untuk menghormati."}]}'),
(507, 'e5_n1_s7', 'Cari Enam Rumah Ibadat', 'Cari rumah ibadat bagi Islam, Kristian, Buddha, Konfusius dan Tao, Hindu dan Sikh.', '2', 'Mengenal pasti nama rumah ibadat: masjid, gereja, tokong, wat, kuil dan gurdwara.', '{"bgImage":"../assets/gameAsset/background/tempat_beribadat_berdekat.png","hotspots":[{"name":"Masjid: rumah ibadat bagi penganut Islam","top":"66.3%","left":"17.2%"},{"name":"Gereja: rumah ibadat bagi penganut Kristian","top":"62.4%","left":"33%"},{"name":"Tokong: rumah ibadat Konfusius dan Tao, juga Buddha","top":"60.4%","left":"50.8%"},{"name":"Wat atau tokong: rumah ibadat bagi penganut Buddha","top":"61.6%","left":"61.7%"},{"name":"Kuil: rumah ibadat bagi penganut Hindu","top":"62%","left":"71.5%"},{"name":"Gurdwara: rumah ibadat bagi penganut Sikh","top":"66.3%","left":"88%"}],"aftermath":"Nama rumah ibadat tersalah sebut dan pelancong menyebarkan maklumat yang salah.","turns":[{"after":2,"options":[{"text":"Setiap agama ada rumah ibadat tersendiri, dan kita perlu menghormati semuanya.","isCorrect":true,"reaction":"Betul. Pelancong pun mengangguk."},{"text":"Semua rumah ibadat sama sahaja namanya.","isCorrect":false,"reaction":"Pelancong terus tersilap dan ketawa kecil."},{"text":"Rumah ibadat tidak penting.","isCorrect":false,"reaction":"Rumah ibadat ialah tempat aktiviti keagamaan, bukan perkara remeh."}],"clue":"Hormati setiap rumah ibadat."}]}'),
(508, 'e5_n1_s8', 'Kad Refleksi Kepentingan Agama', 'Baca kad dan tentukan kepentingan amalan agama dan kepercayaan dalam kehidupan.', '5', 'Memahami kepentingan agama: menjadikan masyarakat maju, harmoni, berdisiplin dan mempunyai matlamat.', '{"clueText":"Kad: Amalan agama dan kepercayaan menjadikan masyarakat lebih maju, mewujudkan masyarakat yang hidup dalam suasana harmoni, memastikan masyarakat sentiasa berdisiplin dan memimpin masyarakat supaya mempunyai matlamat dalam kehidupan.","options":[{"text":"Menjadikan masyarakat maju, harmoni, berdisiplin dan bermatlamat.","isCorrect":true},{"text":"Menjadikan masyarakat sentiasa berbalah.","isCorrect":false,"consequence":"Rakan-rakan menggeleng. Jawapan itu bertentangan dengan kad."},{"text":"Menjadikan masyarakat tidak berdisiplin.","isCorrect":false,"consequence":"Kad menyebut sebaliknya. Kau dibetulkan."},{"text":"Menjadikan masyarakat tiada matlamat hidup.","isCorrect":false,"consequence":"Kad menyatakan agama memimpin masyarakat supaya bermatlamat."}],"aftermath":"Kad tersalah baca dan rakan-rakan menyangka agama tidak penting. Perbincangan berhenti begitu sahaja.","turns":[{"after":3,"options":[{"text":"Agama membimbing kita melakukan perkara baik, jadi masyarakat menjadi aman.","isCorrect":true,"reaction":"Itu jawapan yang membuat kami bersetuju."},{"text":"Agama hanya menyusahkan hidup.","isCorrect":false,"reaction":"Rakan-rakan tersentak dan menggeleng."},{"text":"Agama tidak ada kaitan dengan masyarakat.","isCorrect":false,"reaction":"Cikgu menggeleng kerana kaitan itu jelas."}],"clue":"Agama membimbing masyarakat melakukan perkara baik."}]}'),
(509, 'e5_n2_s1', 'Kad Kepercayaan Alam', 'Baca kad dan tentukan nama kepercayaan yang menganggap alam mempunyai semangat dan roh nenek moyang.', '5', 'Memahami animisme: kepercayaan bahawa gua, pokok atau batu besar mempunyai semangat dan roh nenek moyang yang mesti dihormati.', '{"clueText":"Kad: Kepercayaan ini dipengaruhi oleh alam semesta. Masyarakat percaya bahawa gua, pokok atau batu besar mempunyai semangat dan roh nenek moyang yang mesti dihormati.","options":[{"text":"Animisme.","isCorrect":true},{"text":"Konfusius.","isCorrect":false,"consequence":"Konfusius ialah ajaran moral, bukan kepercayaan tentang semangat alam. Kad dikembalikan."},{"text":"Hukum Karma.","isCorrect":false,"consequence":"Hukum Karma ialah kepercayaan Hindu. Murid itu berkerut dahi."},{"text":"Empat Kebenaran Mulia.","isCorrect":false,"consequence":"Itu ajaran Buddha. Kad dikembalikan."}],"aftermath":"Kad tersalah baca dan kepercayaan alam diejek sebagai mengarut. Penduduk pantai tersinggung.","turns":[{"after":1,"options":[{"text":"Kepercayaan ini perlu dihormati kerana ia warisan nenek moyang mereka.","isCorrect":true,"reaction":"Itu yang kami harapkan, nak."},{"text":"Kepercayaan ini bodoh dan tidak masuk akal.","isCorrect":false,"reaction":"Penduduk kampung terdiam dan berpaling."},{"text":"Kepercayaan ini boleh dipaksa ditukar.","isCorrect":false,"reaction":"Bobohizan membantah. Tiada paksaan dalam menghormati kepercayaan."}],"clue":"Hormati kepercayaan nenek moyang."}]}'),
(510, 'e5_n2_s2', 'Dua Suku, Dua Upacara', 'Padankan suku Orang Asli dengan upacara dan tujuannya.', '4', 'Mengenal pasti kepercayaan Orang Asli: Mah Meri (Puja Pantai), Temiar dan Semai (upacara ritual), penyakit disebabkan kuasa jahat.', '{"pairs":[{"text":"Suku Mah Meri","pair":1},{"text":"Puja Pantai: perlindungan dan pengampunan daripada semangat laut","pair":1},{"text":"Suku Temiar dan Semai","pair":2},{"text":"Upacara ritual menghalau kuasa jahat","pair":2},{"text":"Kepercayaan Orang Asli","pair":3},{"text":"Penyakit disebabkan oleh kuasa jahat","pair":3}],"aftermath":"Padanan tersilap dan kampung menyangka upacara satu suku boleh digantikan dengan suku lain. Tok Batin berasa disisih.","turns":[{"after":3,"options":[{"text":"Setiap suku ada upacara dan sebab sendiri, jadi kita menghormati perbezaan itu.","isCorrect":true,"reaction":"Itu jawapan yang baik, nak."},{"text":"Upacara mereka sama sahaja, tidak perlu dipelajari.","isCorrect":false,"reaction":"Tok Batin menggeleng. Perbezaan itu bermakna."},{"text":"Upacara mereka lapuk dan patut ditinggalkan.","isCorrect":false,"reaction":"Pak Mah Meri berpaling muka dan tidak lagi bercakap."}],"clue":"Setiap suku ada upacara sendiri."}]}'),
(511, 'e5_n2_s3', 'Istilah Upacara Miring', 'Padankan istilah upacara Iban dengan maknanya.', '4', 'Memahami kepercayaan Iban: Petara (dewa), upacara Miring, Lemambang (penyair), jampi mantera.', '{"pairs":[{"text":"Petara","pair":1},{"text":"Dewa yang menyampaikan petanda melalui mimpi dan bayangan","pair":1},{"text":"Upacara Miring","pair":2},{"text":"Upacara khusus untuk memuja Petara","pair":2},{"text":"Lemambang","pair":3},{"text":"Penyair yang melakukan upacara Miring","pair":3},{"text":"Jampi mantera","pair":4},{"text":"Bacaan permulaan upacara Miring","pair":4}],"aftermath":"Istilah tersilap padan dan tetamu menyangka Petara ialah nama tempat. Apai Jelani menggeleng.","turns":[{"after":3,"options":[{"text":"Petara ialah dewa yang dipuja, bukan nama tempat.","isCorrect":true,"reaction":"Betul, nak. Kamu memahami kami."},{"text":"Petara ialah nama kampung.","isCorrect":false,"reaction":"Apai Jelani ketawa kecil dan membetulkan."},{"text":"Petara ialah alat muzik.","isCorrect":false,"reaction":"Lemambang menggeleng dan tersenyum nipis."}],"clue":"Petara ialah dewa."}]}'),
(512, 'e5_n2_s4', 'Nota Upacara Bisaya', 'Baca nota dan tentukan nama upacara yang menghalau kuasa ghaib daripada badan pesakit.', '5', 'Memahami kepercayaan Bisaya: jampi mantera ketika membuka kawasan pertanian baharu dan upacara Tamarok untuk menghalau kuasa ghaib daripada badan pesakit.', '{"clueText":"Nota: Masyarakat Bisaya di Sarawak bekerja sebagai petani dan mempercayai kuasa ghaib. Jampi mantera dibaca untuk mengelakkan gangguan kuasa ghaib semasa membuka kawasan pertanian baharu. Satu upacara diadakan untuk menghalau kuasa ghaib daripada badan pesakit.","options":[{"text":"Upacara Tamarok.","isCorrect":true},{"text":"Upacara Miring.","isCorrect":false,"consequence":"Miring ialah upacara Iban untuk memuja Petara. Nota dikembalikan."},{"text":"Upacara Ngeduang.","isCorrect":false,"consequence":"Ngeduang ialah upacara Bajau. Pak Tani Bisaya menggeleng."},{"text":"Upacara Puja Pantai.","isCorrect":false,"consequence":"Puja Pantai ialah upacara Mah Meri. Nota dikembalikan."}],"aftermath":"Nota tersalah baca dan pesakit dibiarkan tanpa upacara. Pak Tani Bisaya risau.","turns":[{"after":2,"options":[{"text":"Upacara itu dijalankan untuk menghalau kuasa ghaib daripada badan pesakit.","isCorrect":true,"reaction":"Betul, nak. Pesakit itu berasa tenang."},{"text":"Upacara itu dijalankan untuk memanggil roh jahat.","isCorrect":false,"reaction":"Pak Tani Bisaya terkejut. Tujuannya sebaliknya."},{"text":"Upacara itu dijalankan untuk menjual hasil tani.","isCorrect":false,"reaction":"Jawapan itu tiada kaitan dengan upacara."}],"clue":"Menghalau kuasa ghaib daripada pesakit."}]}'),
(513, 'e5_n2_s5', 'Dua Wajah Upacara Bajau', 'Padankan upacara Bajau dengan lokasi dan maksudnya.', '4', 'Mengenal pasti upacara Bajau: Ngeduang (pantai barat, Kota Belud, jamuan sedekah) dan Mag\'ombo (pantai timur, Semporna, menghargai warisan).', '{"pairs":[{"text":"Ngeduang","pair":1},{"text":"Keluarga si mati menjamu tetamu sebagai sedekah","pair":1},{"text":"Kota Belud","pair":2},{"text":"Pantai barat Sabah, upacara Ngeduang","pair":2},{"text":"Mag\'ombo","pair":3},{"text":"Menghargai dan menghormati warisan nenek moyang","pair":3},{"text":"Semporna","pair":4},{"text":"Pantai timur Sabah, upacara Mag\'ombo","pair":4}],"aftermath":"Padanan tersilap dan pelajar menyangka Ngeduang dan Mag\'ombo upacara yang sama. Pak Bajau berasa dipandang remeh.","turns":[{"after":2,"options":[{"text":"Bajau di pantai berlainan mempunyai upacara berbeza, tetapi kedua-duanya menghormati nenek moyang.","isCorrect":true,"reaction":"Betul, Bobohizan. Terima kasih."},{"text":"Kedua-dua upacara sama sahaja.","isCorrect":false,"reaction":"Pak Bajau menggeleng dan membetulkan."},{"text":"Upacara Bajau hanya wujud di Semporna.","isCorrect":false,"reaction":"Pak Bajau membetulkan. Ngeduang di Kota Belud juga ada."}],"clue":"Dua upacara berbeza, satu semangat."}]}'),
(514, 'e5_n2_s6', 'Istilah Kadazandusun', 'Padankan istilah kepercayaan Kadazandusun dengan maksudnya.', '4', 'Memahami kepercayaan Kadazandusun: Kinorohingan (Tuhan untuk meminta keselamatan dan perlindungan), Magavau (upacara semangat padi), Bobohizan (ketua bomoh).', '{"pairs":[{"text":"Kinorohingan","pair":1},{"text":"Tuhan untuk meminta keselamatan dan perlindungan","pair":1},{"text":"Magavau (Maga\'au)","pair":2},{"text":"Upacara semangat padi semasa Pesta Kaamatan","pair":2},{"text":"Bobohizan","pair":3},{"text":"Ketua bomoh yang mengetuai upacara","pair":3}],"aftermath":"Istilah tersilap dan tetamu salah faham tentang Kinorohingan. Linda terasa bangga kaumnya disalah sebut.","turns":[{"after":2,"options":[{"text":"Kinorohingan ialah Tuhan, dan upacara Magavau dijalankan semasa Pesta Kaamatan.","isCorrect":true,"reaction":"Betul, Bobohizan. Linda tersenyum."},{"text":"Kinorohingan ialah nama sebuah kampung.","isCorrect":false,"reaction":"Linda menggeleng dan membetulkan."},{"text":"Magavau ialah pesta makanan sahaja.","isCorrect":false,"reaction":"Bobohizan membetulkan. Magavau berkaitan semangat padi."}],"clue":"Kinorohingan ialah Tuhan."}]}'),
(515, 'e5_n2_s7', 'Cari Petunjuk Upacara Bajau', 'Cari empat petunjuk upacara Bajau di perkampungan atas air.', '2', 'Memahami upacara Bajau: Mag\'ombo (Semporna) dan Ngeduang (Kota Belud).', '{"bgImage":"../assets/gameAsset/background/upacara_pantai.png","hotspots":[{"name":"Perahu berhias: Mag\'ombo, upacara Bajau di Semporna","top":"40.9%","left":"77.6%"},{"name":"Gerbang upacara: Mag\'ombo menghargai warisan turun-temurun","top":"46.1%","left":"51.1%"},{"name":"Tikar jamuan: Ngeduang menjamu tetamu sebagai sedekah, Kota Belud","top":"78.5%","left":"17.5%"},{"name":"Rumah di atas air: perkampungan Bajau di pantai timur","top":"25.4%","left":"14.2%"}],"aftermath":"Petunjuk tidak ditemui dan pelancong pulang dengan maklumat yang salah.","turns":[{"after":2,"options":[{"text":"Kita boleh mempelajari budaya Bajau tanpa mengubah cara hidup mereka.","isCorrect":true,"reaction":"Betul, nak."},{"text":"Kita suruh mereka tukar upacara supaya senang difahami.","isCorrect":false,"reaction":"Pak Bajau tersinggung dan upacara dihentikan."},{"text":"Kita ambil gambar tanpa meminta izin.","isCorrect":false,"reaction":"Penduduk berasa tidak dihormati."}],"clue":"Pelajari dengan hormat dan izin."}]}'),
(516, 'e5_n2_s8', 'Para Penjaga Adat', 'Padankan penjaga adat dengan kaum atau upacaranya.', '4', 'Merumuskan tokoh upacara: Bobohizan (Kadazandusun), Lemambang (Iban), Mah Meri (Puja Pantai), Bisaya (Tamarok), Bajau (Ngeduang dan Mag\'ombo).', '{"pairs":[{"text":"Bobohizan","pair":1},{"text":"Ketua bomoh Kadazandusun, Magavau","pair":1},{"text":"Lemambang","pair":2},{"text":"Penyair upacara Miring Iban","pair":2},{"text":"Suku Mah Meri","pair":3},{"text":"Puja Pantai di Pulau Carey","pair":3},{"text":"Masyarakat Bisaya","pair":4},{"text":"Tamarok menghalau kuasa ghaib","pair":4},{"text":"Masyarakat Bajau","pair":5},{"text":"Ngeduang dan Mag\'ombo","pair":5}],"aftermath":"Padanan tersilap dan persidangan berakhir dengan kekeliruan tentang siapa menjaga apa.","turns":[{"after":3,"options":[{"text":"Kepercayaan setiap kaum perlu difahami dan dihormati agar kehidupan aman.","isCorrect":true,"reaction":"Itu jawapan yang membawa kami pulang dengan tenang."},{"text":"Kepercayaan kaum lain tidak perlu difahami.","isCorrect":false,"reaction":"Wakil-wakil lain terasa tidak dihargai."},{"text":"Hanya satu kepercayaan yang betul.","isCorrect":false,"reaction":"Persidangan menjadi tegang dan wakil meninggalkan dewan."}],"clue":"Fahami dan hormati semua kepercayaan."}]}'),
(517, 'e5_n3_s1', 'Kad Kedudukan Agama Islam', 'Susun peristiwa kedudukan agama Islam dalam Perlembagaan mengikut urutan.', '1', 'Memahami proses: memorandum kepada Suruhanjaya Perlembagaan Tanah Melayu 1957, Islam diakui agama Persekutuan, termaktub dalam Perkara 3, perubahan perlu titah perkenan.', '{"timelineItems":[{"id":1,"year":"Menjelang 1957","text":"Parti politik dan pertubuhan menghantar memorandum kepada Suruhanjaya Perlembagaan Tanah Melayu 1957","why":"Permulaan: cadangan dihantar kepada suruhanjaya."},{"id":2,"year":"Selepas itu","text":"Agama Islam diakui sebagai agama Persekutuan","why":"Memorandum diterima dan kedudukan itu diakui."},{"id":3,"year":"Kemudian","text":"Kedudukannya termaktub dalam Perkara 3 Perlembagaan Persekutuan","why":"Pengakuan itu ditulis dalam Perlembagaan."},{"id":4,"year":"Kini","text":"Perubahan perlu mendapat titah perkenan Yang di-Pertuan Agong dan Raja-Raja Melayu","why":"Syarat ini menjaga kedudukan itu daripada diubah sewenang-wenangnya."}],"aftermath":"Urutan terbalik dan murid mencatat sejarah yang salah. Guru menggeleng kecewa.","turns":[{"after":2,"options":[{"text":"Kedudukan itu termaktub dalam Perlembagaan dan wajar dihormati.","isCorrect":true,"reaction":"Betul, nak. Itu menjaga perpaduan."},{"text":"Kedudukan itu boleh diubah oleh sesiapa sahaja.","isCorrect":false,"reaction":"Perubahan perlu titah perkenan. Guru membetulkan."},{"text":"Kedudukan itu tidak tercatat di mana-mana.","isCorrect":false,"reaction":"Guru menggeleng. Ia termaktub dalam Perkara 3."}],"clue":"Perkara 3 menjaga kedudukan Islam."}]}'),
(518, 'e5_n3_s2', 'Papan Perkara 3', 'Padankan peruntukan Perkara 3 dengan isinya.', '4', 'Memahami Perkara 3 (1), (2), (3) dan (5) Perlembagaan Persekutuan.', '{"pairs":[{"text":"Perkara 3 (1)","pair":1},{"text":"Islam agama Persekutuan, agama lain diamalkan dengan aman dan damai","pair":1},{"text":"Perkara 3 (2)","pair":2},{"text":"Raja ialah Ketua Agama Islam di negeri berRaja","pair":2},{"text":"Perkara 3 (3)","pair":3},{"text":"Yang di-Pertuan Agong: Melaka, Pulau Pinang, Sabah, Sarawak","pair":3},{"text":"Perkara 3 (5)","pair":4},{"text":"Yang di-Pertuan Agong: Kuala Lumpur, Labuan dan Putrajaya","pair":4}],"aftermath":"Papan salah baca dan murid menyangka Perdana Menteri ialah Ketua Agama Islam. Tuanku Sultan menggeleng.","turns":[{"after":3,"options":[{"text":"Yang di-Pertuan Agong ialah Ketua Agama Islam bagi negeri yang tidak mempunyai Raja.","isCorrect":true,"reaction":"Betul, nak."},{"text":"Perdana Menteri ialah Ketua Agama Islam bagi negeri itu.","isCorrect":false,"reaction":"Tuanku Sultan menggeleng. Itu tidak tercatat dalam Perkara 3."},{"text":"Tiada sesiapa menjadi Ketua Agama Islam bagi negeri itu.","isCorrect":false,"reaction":"Yang di-Pertua Negeri berasa dipandang remeh."}],"clue":"Negeri tanpa Raja: Yang di-Pertuan Agong."}]}'),
(519, 'e5_n3_s3', 'Kad Perkara 11', 'Padankan fasal dalam Perkara 11 dengan isinya.', '4', 'Memahami Perkara 11 (1) dan Perkara 11 (3)(a) Perlembagaan Persekutuan tentang kebebasan beragama.', '{"pairs":[{"text":"Perkara 11 (1)","pair":1},{"text":"Tiap-tiap orang berhak menganuti dan mengamalkan agamanya","pair":1},{"text":"Perkara 11 (3)(a)","pair":2},{"text":"Tiap-tiap kumpulan agama berhak menguruskan hal ehwal agamanya sendiri","pair":2}],"aftermath":"Fasal tersilap dan pemuda itu terus menyebarkan salah faham tentang kebebasan beragama.","turns":[{"after":3,"options":[{"text":"Perlembagaan menjamin hak beragama, jadi kita menghormati amalan agama masing-masing.","isCorrect":true,"reaction":"Itu yang kami mahu dengar."},{"text":"Perlembagaan tidak menjamin hak beragama.","isCorrect":false,"reaction":"Kad Perkara 11 membuktikan sebaliknya. Pemuda itu dibetulkan."},{"text":"Hanya satu agama berhak diamalkan.","isCorrect":false,"reaction":"Itu bertentangan dengan Perkara 3 (1) dan Perkara 11 (1)."}],"clue":"Hak beragama dijamin."}]}'),
(520, 'e5_n3_s4', 'Cari Rumah Ibadat di Pameran', 'Cari rumah ibadat untuk setiap agama dan ajaran.', '2', 'Mengenal pasti nama rumah ibadat: masjid, gereja, kuil, gurdwara, wat dan tokong.', '{"bgImage":"../assets/gameAsset/background/tempat_beribadat_semua.png","hotspots":[{"name":"Masjid: rumah ibadat bagi penganut Islam","top":"21.9%","left":"14.7%"},{"name":"Gereja: rumah ibadat bagi penganut Kristian","top":"20.6%","left":"40.1%"},{"name":"Kuil: rumah ibadat bagi penganut Hindu","top":"28.2%","left":"53.2%"},{"name":"Gurdwara: rumah ibadat bagi penganut Sikh","top":"47%","left":"12.9%"},{"name":"Wat atau tokong: rumah ibadat bagi penganut Buddha","top":"52.9%","left":"51.2%"},{"name":"Tokong: rumah ibadat bagi Ajaran Konfusius dan Ajaran Tao","top":"65%","left":"31%"}],"aftermath":"Pelancong masuk tanpa memahami adab dan penjaga rumah ibadat tersinggung.","turns":[{"after":2,"options":[{"text":"Setiap rumah ibadat mempunyai adab dan kita perlu mengetahuinya sebelum masuk.","isCorrect":true,"reaction":"Betul. Penjaga pun tersenyum."},{"text":"Kita masuk sahaja kerana semua rumah ibadat sama.","isCorrect":false,"reaction":"Penjaga rumah ibadat membantah kerana adab tidak diketahui."},{"text":"Kita tidak perlu masuk langsung.","isCorrect":false,"reaction":"Pelancong terlepas peluang mengenali kepelbagaian agama dengan hormat."}],"clue":"Ketahui adab sebelum masuk."}]}'),
(521, 'e5_n3_s5', 'Tiga Masjid Bersejarah', 'Padankan masjid dengan maklumatnya.', '4', 'Memahami Masjid Negara (dirasmikan 27 Ogos 1965, 15 000 jemaah), Masjid Kampung Laut (abad ke-18, Kelantan), Masjid Al-Qadim (1830, Sibu).', '{"pairs":[{"text":"Masjid Negara","pair":1},{"text":"Dirasmikan 27 Ogos 1965, boleh menampung 15 000 jemaah","pair":1},{"text":"Masjid Kampung Laut","pair":2},{"text":"Dibina abad ke-18, antara masjid tertua di Alam Melayu","pair":2},{"text":"Masjid Al-Qadim","pair":3},{"text":"Dibina 1830 di Sibu oleh Tuan Haji Salam Minangkabau","pair":3}],"aftermath":"Kad bertukar dan laporan memuatkan tahun yang salah. Guru memanggil pelajar semula.","turns":[{"after":2,"options":[{"text":"Masjid itu bukti sejarah dan perlu dijaga bersama.","isCorrect":true,"reaction":"Betul. Kami akan menulis laporan dengan lengkap."},{"text":"Masjid lama tidak perlu dijaga lagi.","isCorrect":false,"reaction":"Guru menggeleng kerana warisan boleh hilang."},{"text":"Masjid lama hanya milik satu kaum.","isCorrect":false,"reaction":"Pelajar lain membantah kerana warisan itu milik negara."}],"clue":"Jaga bangunan bersejarah."}]}'),
(522, 'e5_n3_s6', 'Rumah Ibadat Bersejarah', 'Padankan rumah ibadat dengan keistimewaannya.', '4', 'Memahami keistimewaan: Gereja St. Michael (gereja granit tertua), Wat Boonyaram (wat Siam di Kodiang), Cheng Hoon Teng (Kediaman di Awan Hijau), Sri Rajakaliamman (kuil kaca), Wadda Gurdwara Sahib (seni bina Moor).', '{"pairs":[{"text":"Gereja St. Michael","pair":1},{"text":"Gereja granit tertua di Malaysia, Sandakan, 1893","pair":1},{"text":"Wat Boonyaram","pair":2},{"text":"Wat Siam Buddha di Kodiang, Kedah, 1932","pair":2},{"text":"Tokong Cheng Hoon Teng","pair":3},{"text":"Kediaman di Awan Hijau, Melaka, 1645","pair":3},{"text":"Kuil Sri Rajakaliamman","pair":4},{"text":"Kuil kaca pertama dan satu-satunya di Malaysia","pair":4},{"text":"Wadda Gurdwara Sahib","pair":5},{"text":"Seni bina Moor dan moden, tapak warisan di Pulau Pinang","pair":5}],"aftermath":"Keistimewaan tersilap dan pameran memuatkan fakta yang salah. Pengunjung keliru.","turns":[{"after":3,"options":[{"text":"Rumah ibadat bersejarah menunjukkan kepelbagaian agama dan warisan negara.","isCorrect":true,"reaction":"Betul. Pengunjung kagum."},{"text":"Rumah ibadat tidak mempunyai nilai sejarah.","isCorrect":false,"reaction":"Rakan-rakan membantah kerana sejarahnya jelas."},{"text":"Hanya rumah ibadat besar yang bernilai.","isCorrect":false,"reaction":"Rakan-rakan tidak bersetuju kerana semuanya warisan."}],"clue":"Rumah ibadat ialah warisan negara."}]}'),
(523, 'e5_n3_s7', 'Kad Adab Rumah Ibadat', 'Baca kad dan tentukan kepentingan memahami adab ketika berada di rumah ibadat.', '5', 'Memahami kepentingan adab: menghormati kebebasan beragama, mengeratkan silaturahim dan perpaduan, mengenali agama lain, menunjukkan keperibadian terpuji.', '{"clueText":"Kad: Memahami adab dapat menghormati kebebasan beragama kaum lain yang termaktub dalam Perlembagaan Persekutuan, mengeratkan hubungan silaturahim dan perpaduan, mengenali agama lain, dan menunjukkan sifat keperibadian yang terpuji.","options":[{"text":"Menghormati kebebasan beragama dan mengeratkan perpaduan.","isCorrect":true},{"text":"Menyisihkan agama lain supaya tidak berbalah.","isCorrect":false,"consequence":"Penyisihan menambah curiga. Kad dikembalikan."},{"text":"Mengelak daripada masuk ke rumah ibadat lain.","isCorrect":false,"consequence":"Kad menyatakan sebaliknya: kita perlu mengenali agama lain."},{"text":"Menjadikan semua rumah ibadat sama.","isCorrect":false,"consequence":"Kad tidak menyatakan begitu. Setiap agama ada rumah ibadat tersendiri."}],"aftermath":"Kad tersalah baca dan murid memasuki rumah ibadat tanpa adab. Penjaga menegur dan lawatan terhenti.","turns":[{"after":1,"options":[{"text":"Kita menjaga adab kerana menghormati kebebasan beragama dan mengeratkan perpaduan.","isCorrect":true,"reaction":"Betul, nak. Kamu sudah bersedia."},{"text":"Kita menjaga adab hanya jika diperhati guru.","isCorrect":false,"reaction":"Murid lain mula tidak menghormati bila guru berpaling."},{"text":"Kita tidak perlu menjaga adab kerana itu bukan agama kita.","isCorrect":false,"reaction":"Penjaga rumah ibadat kecewa dan lawatan dibatalkan."}],"clue":"Adab menunjukkan hormat."}]}'),
(524, 'e5_n3_s8', 'Rumusan Hormat Kepelbagaian Agama', 'Padankan perkara dengan kepentingannya.', '4', 'Memahami kepentingan menghormati kepelbagaian agama: persefahaman, sensitiviti, silaturahim, harmoni, mengelak perbalahan.', '{"pairs":[{"text":"Menghormati agama lain","pair":1},{"text":"Mengukuhkan rasa persefahaman dalam masyarakat","pair":1},{"text":"Menjaga sensitiviti","pair":2},{"text":"Mendidik diri menghormati pelbagai kaum","pair":2},{"text":"Mengeratkan silaturahim","pair":3},{"text":"Hubungan baik antara kaum","pair":3},{"text":"Hidup dalam harmoni","pair":4},{"text":"Setiap masyarakat aman dan sejahtera","pair":4},{"text":"Mengelakkan perbalahan","pair":5},{"text":"Tiada pergaduhan antara kaum","pair":5}],"aftermath":"Rumusan tersilap dan murid pulang tanpa memahami kepentingan menghormati kepelbagaian agama.","turns":[{"after":1,"options":[{"text":"Hormat kepada kepelbagaian agama mewujudkan persefahaman dan perpaduan.","isCorrect":true,"reaction":"Betul, nak. Itulah yang kita mahu."},{"text":"Hormat tidak penting kerana agama masing-masing.","isCorrect":false,"reaction":"Rakan-rakan menggeleng kerana sikap itu menjauhkan mereka."},{"text":"Hormat hanya untuk agama sendiri.","isCorrect":false,"reaction":"Rakan-rakan lain terasa tersisih."}],"clue":"Hormat kepelbagaian membawa perpaduan."}]}'),
(601, 'e6_n1_s1', 'Kertas Tempahan Basah', 'Padankan perayaan dengan tarikh sambutannya.', '4', 'Mengenal pasti tarikh perayaan: Aidilfitri (1 Syawal), Aidiladha (10 Zulhijah), Tahun Baharu Cina (hari pertama kalendar Cina), Krismas (25 Disember), Hari Gawai (1 Jun), Pesta Kaamatan (Mei).', '{"pairs":[{"text":"Hari Raya Aidilfitri","pair":1},{"text":"1 Syawal mengikut kalendar Islam","pair":1},{"text":"Hari Raya Aidiladha","pair":2},{"text":"10 Zulhijah mengikut kalendar Islam","pair":2},{"text":"Tahun Baharu Cina","pair":3},{"text":"Hari pertama dalam kalendar Cina","pair":3},{"text":"Krismas","pair":4},{"text":"25 Disember setiap tahun","pair":4},{"text":"Hari Gawai","pair":5},{"text":"1 Jun setiap tahun","pair":5},{"text":"Pesta Kaamatan","pair":6},{"text":"Bulan Mei setiap tahun","pair":6}],"aftermath":"Tarikh tersilap dan hiasan tiba pada hari yang salah. Pelanggan kecewa kerana perayaan mereka tidak dihormati.","turns":[{"after":3,"options":[{"text":"Setiap perayaan ada tarikh dan makna tersendiri, jadi kita perlu menghormatinya.","isCorrect":true,"reaction":"Betul. Hiasan kami dihantar tepat pada masanya."},{"text":"Semua perayaan sama sahaja, jadi tarikh tidak penting.","isCorrect":false,"reaction":"Pelanggan memprotes kerana perayaan mereka dianggap remeh."},{"text":"Hiasan boleh dihantar bila-bila masa sahaja.","isCorrect":false,"reaction":"Perayaan berlalu tanpa hiasan dan pelanggan kecewa."}],"clue":"Hormati tarikh setiap perayaan."}]}'),
(602, 'e6_n1_s2', 'Kad Dua Hari Raya', 'Baca kad dan tentukan perayaan yang melibatkan ibadah korban.', '5', 'Membezakan Aidilfitri (1 Syawal, selepas puasa sebulan) dengan Aidiladha (10 Zulhijah, hari Tasyrik 11, 12 dan 13, ibadah korban dan sedekah daging).', '{"clueText":"Kad: Perayaan ini disambut oleh masyarakat Islam pada 10 Zulhijah dan diteruskan pada hari Tasyrik, iaitu 11, 12 dan 13 Zulhijah. Umat Islam mengadakan ibadah korban dan memberikan sedekah daging korban tersebut.","options":[{"text":"Hari Raya Aidiladha.","isCorrect":true},{"text":"Hari Raya Aidilfitri.","isCorrect":false,"consequence":"Aidilfitri disambut pada 1 Syawal selepas puasa sebulan. Kad dikembalikan."},{"text":"Pesta Kaamatan.","isCorrect":false,"consequence":"Kaamatan perayaan kaum Kadazandusun dan Murut. Aishah tersenyum kecil."},{"text":"Deepavali.","isCorrect":false,"consequence":"Deepavali perayaan masyarakat Hindu. Kad dikembalikan."}],"aftermath":"Kad tersalah baca dan hiasan Aidilfitri dihantar untuk Aidiladha. Aishah menggeleng.","turns":[{"after":1,"options":[{"text":"Kedua-dua hari raya mempunyai makna dan tarikh berbeza, jadi hiasan juga berbeza.","isCorrect":true,"reaction":"Betul. Hiasan Aidiladha disesuaikan dengan maknanya."},{"text":"Kedua-dua hari raya sama sahaja, satu hiasan memadai.","isCorrect":false,"reaction":"Aishah kecewa kerana makna perayaannya diabaikan."},{"text":"Aidiladha tidak penting untuk dihias.","isCorrect":false,"reaction":"Pelanggan menegur kerana perayaan itu juga disambut dengan meriah."}],"clue":"Dua hari raya, dua makna."}]}'),
(603, 'e6_n1_s3', 'Urutan Tahun Baharu Cina', 'Susun kegiatan Tahun Baharu Cina mengikut urutan.', '1', 'Memahami Tahun Baharu Cina: makan malam keluarga, hari pertama kalendar Cina, berlanjutan 15 hari hingga Chap Goh Meh.', '{"timelineItems":[{"id":1,"year":"Malam sebelum itu","text":"Seluruh ahli keluarga berkumpul untuk makan malam bersama-sama","why":"Perayaan bermula dengan makan malam keluarga."},{"id":2,"year":"Hari pertama","text":"Tahun Baharu Cina disambut pada hari pertama dalam kalendar Cina","why":"Itulah hari sambutan utama."},{"id":3,"year":"Selama 15 hari","text":"Perayaan berlanjutan dengan sambutan di rumah dan tempat awam","why":"Perayaan tidak berakhir pada hari pertama sahaja."},{"id":4,"year":"Hari ke-15","text":"Perayaan berakhir pada hari Chap Goh Meh","why":"Hari terakhir sambutan."}],"aftermath":"Urutan tersilap dan keluarga terlepas hari penting. Ah Meng menggaru kepala.","turns":[{"after":2,"options":[{"text":"Perayaan itu meraikan tahun baharu dan menyatukan keluarga.","isCorrect":true,"reaction":"Betul. Keluarga kami berasa bangga."},{"text":"Perayaan itu hanya untuk makan besar sahaja.","isCorrect":false,"reaction":"Ah Meng berasa maksud perayaan dikecilkan."},{"text":"Perayaan itu hanya berlangsung satu hari.","isCorrect":false,"reaction":"Nenek membetulkan kerana ia berlanjutan selama 15 hari."}],"clue":"Meraikan tahun baharu dan menyatukan keluarga."}]}'),
(604, 'e6_n1_s4', 'Tiga Perayaan India dan Sikh', 'Padankan perayaan dengan ciri atau makna sambutannya.', '4', 'Memahami Deepavali (Aippasi, kecerahan mengatasi kegelapan, kolam dan pelita), Thaipusam (Dewa Murugan, pembayar niat), Vaisakhi (bulan Vaisakh, Gurdwara, syukur tanaman).', '{"pairs":[{"text":"Deepavali","pair":1},{"text":"Kecerahan mengatasi kegelapan, kolam dan pelita","pair":1},{"text":"Thaipusam","pair":2},{"text":"Pembayar niat membawa persembahan kepada Dewa Murugan","pair":2},{"text":"Vaisakhi","pair":3},{"text":"Kaum Sikh bersembahyang di Gurdwara dan mensyukuri hasil tanaman","pair":3}],"aftermath":"Kad bertukar dan hiasan Deepavali digantung di Gurdwara. Harjit dan Kavitha kecewa.","turns":[{"after":1,"options":[{"text":"Setiap perayaan ada makna sendiri, jadi hiasan mesti sesuai.","isCorrect":true,"reaction":"Betul, kami berasa dihargai."},{"text":"Semua hiasan boleh digantung di mana-mana sahaja.","isCorrect":false,"reaction":"Pelanggan terasa dipandang remeh."},{"text":"Hiasan perayaan tidak perlu mengikut makna.","isCorrect":false,"reaction":"Tempahan dikembalikan kerana hiasan tidak sesuai."}],"clue":"Hiasan mesti sesuai dengan makna."}]}'),
(605, 'e6_n1_s5', 'Gawai dan Kaamatan', 'Padankan perayaan petani dengan kaum dan cirinya.', '4', 'Membezakan Hari Gawai (Dayak, Iban dan Bidayuh, 1 Jun, ngajat) dengan Pesta Kaamatan (Kadazandusun dan Murut, Mei, Magavau, sumazau, Unduk Ngadau).', '{"pairs":[{"text":"Hari Gawai","pair":1},{"text":"Kaum Dayak, Iban dan Bidayuh, 1 Jun, ngajat di rumah panjang","pair":1},{"text":"Pesta Kaamatan","pair":2},{"text":"Kadazandusun dan Murut, bulan Mei, Magavau oleh Bobohizan","pair":2},{"text":"Tarian sumazau","pair":3},{"text":"Diadakan semasa Pesta Kaamatan","pair":3},{"text":"Unduk Ngadau","pair":4},{"text":"Pertandingan semasa Pesta Kaamatan","pair":4}],"aftermath":"Kad bertukar dan Gawai dikatakan perayaan Sabah. Apai Jelani dan Linda berasa perayaan mereka disalah faham.","turns":[{"after":3,"options":[{"text":"Kedua-duanya kesyukuran hasil tani, tetapi tarikh dan kaum yang menyambutnya berbeza.","isCorrect":true,"reaction":"Betul, kami faham sekarang."},{"text":"Kedua-duanya sama dan disambut kaum yang sama.","isCorrect":false,"reaction":"Apai Jelani dan Linda membantah serentak."},{"text":"Kedua-duanya tidak mempunyai tujuan.","isCorrect":false,"reaction":"Mereka menggeleng kerana kedua-duanya kesyukuran atas hasil tani."}],"clue":"Kesyukuran hasil tani, tarikh berlainan."}]}'),
(606, 'e6_n1_s6', 'Krismas dan Wesak', 'Padankan perayaan dengan ciri atau makna sambutannya.', '4', 'Memahami Krismas (25 Disember, kelahiran Jesus Christ, hadiah dan karol) dan Wesak (Mei, tiga peristiwa Siddharta, memandikan patung Buddha, makanan kepada sami).', '{"pairs":[{"text":"Krismas","pair":1},{"text":"Memperingati kelahiran Jesus Christ, hadiah dan karol","pair":1},{"text":"Hari Wesak","pair":2},{"text":"Tiga peristiwa penting hidup Siddharta Gautama","pair":2},{"text":"Memandikan patung Buddha","pair":3},{"text":"Penyucian diri semasa Wesak","pair":3},{"text":"Karol","pair":4},{"text":"Nyanyian gembira dari rumah ke rumah semasa Krismas","pair":4}],"aftermath":"Kad bertukar dan karol dikatakan nyanyian Wesak. Daniel dan Mei Ling terasa dilucutkan makna perayaan mereka.","turns":[{"after":3,"options":[{"text":"Mandi patung bermakna penyucian diri semasa Wesak.","isCorrect":true,"reaction":"Betul. Murid itu mengangguk faham."},{"text":"Mandi patung bermakna bermain air.","isCorrect":false,"reaction":"Mei Ling menggeleng kerana maknanya lebih mendalam."},{"text":"Mandi patung bermakna menyambut tahun baharu.","isCorrect":false,"reaction":"Itu tidak betul. Wesak mengingati peristiwa penting dalam hidup Siddharta."}],"clue":"Mandi patung: penyucian diri."}]}'),
(607, 'e6_n1_s7', 'Tahun Baharu Orang Asli', 'Padankan suku Orang Asli dengan nama sambutan tahun baharu atau perayaannya.', '4', 'Mengenal pasti sambutan Orang Asli: Jakun (Tahon Baro), Semai (Jis Pai), Temuan (Tahun Bahauk), Mah Meri (Tawun Empai), Genggulang (Semai), Hari Moyang (Selangor dan Negeri Sembilan).', '{"pairs":[{"text":"Suku Jakun","pair":1},{"text":"Tahon Baro","pair":1},{"text":"Suku Semai","pair":2},{"text":"Jis Pai","pair":2},{"text":"Suku Temuan","pair":3},{"text":"Tahun Bahauk","pair":3},{"text":"Suku Mah Meri","pair":4},{"text":"Tawun Empai","pair":4},{"text":"Suku Semai berdoa kesejahteraan","pair":5},{"text":"Hari Genggulang","pair":5},{"text":"Orang Asli Selangor dan Negeri Sembilan","pair":6},{"text":"Hari Moyang","pair":6}],"aftermath":"Nama sambutan tersilap dan Orang Asli terasa perayaan mereka tidak dikenali. Tok Batin menunduk.","turns":[{"after":3,"options":[{"text":"Setiap suku mempunyai nama sambutan sendiri, jadi kita menghormati perbezaan itu.","isCorrect":true,"reaction":"Betul, nak. Kami berasa dihargai."},{"text":"Semua suku menyebut nama yang sama.","isCorrect":false,"reaction":"Pak Mah Meri tersenyum pahit kerana namanya tidak diketahui."},{"text":"Orang Asli tidak mempunyai sambutan tahun baharu.","isCorrect":false,"reaction":"Tok Batin terguris. Sambutan itu bermula pada 31 Disember."}],"clue":"Setiap suku ada nama sambutan sendiri."}]}'),
(608, 'e6_n1_s8', 'Papan Perayaan Pelabuhan', 'Baca papan dan tentukan perayaan masyarakat berketurunan Portugis di Melaka.', '5', 'Memahami San Pedro: disambut masyarakat berketurunan Portugis di Melaka pada bulan Jun, meraikan penaung nelayan, kapal dihias, tarian branyo.', '{"clueText":"Papan: Perayaan ini disambut oleh masyarakat berketurunan Portugis di Melaka pada bulan Jun. Perayaan ini meraikan penaung nelayan. Kapal-kapal dihias indah oleh nelayan dan tarian branyo yang diwarisi sejak dahulu ditarikan.","options":[{"text":"San Pedro.","isCorrect":true},{"text":"Hari Gawai.","isCorrect":false,"consequence":"Gawai disambut pada 1 Jun di Sarawak. Papan menyebut Melaka."},{"text":"Thaipusam.","isCorrect":false,"consequence":"Thaipusam disambut oleh masyarakat Hindu. Papan dikembalikan."},{"text":"Wesak.","isCorrect":false,"consequence":"Wesak disambut oleh penganut Buddha. Pelancong keliru."}],"aftermath":"Papan tersalah baca dan pelancong pulang dengan cerita salah tentang San Pedro.","turns":[{"after":1,"options":[{"text":"San Pedro ialah perayaan masyarakat berketurunan Portugis dan patut dihormati.","isCorrect":true,"reaction":"Betul. Pelancong turut bertepuk."},{"text":"San Pedro hanya perayaan pelancong.","isCorrect":false,"reaction":"Pak Nelayan terkilan kerana perayaan itu warisan mereka."},{"text":"San Pedro tidak mempunyai tujuan.","isCorrect":false,"reaction":"Pak Nelayan membetulkan. Tujuannya meraikan penaung nelayan."}],"clue":"San Pedro: warisan masyarakat Portugis."}]}'),
(609, 'e6_n2_s1', 'Lima Tujuan Perayaan', 'Padankan tujuan perayaan dengan perayaannya.', '4', 'Memahami tujuan perayaan: keagamaan, meraikan tahun baharu, mensyukuri hasil tanaman atau hasil laut, unsur baik mengatasi kejahatan, mengingati tokoh agama.', '{"pairs":[{"text":"Keagamaan","pair":1},{"text":"Aidilfitri, Aidiladha, Krismas dan Thaipusam","pair":1},{"text":"Meraikan tahun baharu","pair":2},{"text":"Tahun Baharu Cina, Tahon Baro, Jis Pai dan Tawun Empai","pair":2},{"text":"Mensyukuri hasil tanaman atau hasil laut","pair":3},{"text":"Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro","pair":3},{"text":"Mengharapkan unsur baik mengatasi kejahatan","pair":4},{"text":"Deepavali","pair":4},{"text":"Mengingati tokoh agama","pair":5},{"text":"Hari Wesak","pair":5}],"aftermath":"Tujuan tersilap dan anak-anak menyangka semua perayaan sama sahaja. Nenek menggeleng.","turns":[{"after":1,"options":[{"text":"Setiap perayaan ada tujuan tersendiri, jadi kita menghormati cara sambutan berbeza.","isCorrect":true,"reaction":"Betul. Nenek tersenyum."},{"text":"Semua perayaan sama sahaja tujuannya.","isCorrect":false,"reaction":"Anak-anak keliru kerana ada banyak tujuan berbeza."},{"text":"Perayaan hanya untuk bergembira.","isCorrect":false,"reaction":"Nenek menggeleng kerana ada tujuan agama dan kesyukuran."}],"clue":"Setiap perayaan ada tujuan sendiri."}]}'),
(610, 'e6_n2_s2', 'Dari Kad ke Skrin', 'Padankan cara menyampaikan ucapan dahulu dan kini.', '4', 'Membezakan cara sambutan dahulu dan kini: kad ucapan melalui pos atau serahan tangan, kini melalui media elektronik dan media sosial; foto di kedai gambar, kini swafoto.', '{"pairs":[{"text":"Ucapan dahulu","pair":1},{"text":"Kad dihantar melalui pos atau serahan tangan","pair":1},{"text":"Ucapan kini","pair":2},{"text":"Dihantar melalui media elektronik dan media sosial","pair":2},{"text":"Foto dahulu","pair":3},{"text":"Foto keluarga diambil di kedai gambar","pair":3},{"text":"Foto kini","pair":4},{"text":"Swafoto bersama keluarga dimuat naik di media sosial","pair":4}],"aftermath":"Cara tersilap dan cucu menyangka nenek tidak pernah menghantar ucapan. Nenek terguris.","turns":[{"after":1,"options":[{"text":"Cara sambutan berubah, tetapi tujuan mengucap selamat tetap sama.","isCorrect":true,"reaction":"Betul. Nenek senyum lebar."},{"text":"Ucapan dahulu tidak bermakna kerana lambat.","isCorrect":false,"reaction":"Nenek terguris. Setiap kad membawa makna."},{"text":"Ucapan kini tidak bermakna kerana digital.","isCorrect":false,"reaction":"Cucu terasa dirinya dipandang remeh."}],"clue":"Cara berubah, makna kekal."}]}'),
(611, 'e6_n2_s3', 'Cari Bukti Kedai Gambar', 'Cari empat bukti cara bergambar semasa perayaan dahulu.', '2', 'Mengenal pasti cara dahulu mengambil foto keluarga di kedai gambar berbanding swafoto kini.', '{"bgImage":"../assets/gameAsset/background/mengambil_foto_dahulu.png","hotspots":[{"name":"Kamera lama: foto keluarga diambil di kedai gambar","top":"49.5%","left":"14.9%"},{"name":"Latar lukisan studio kedai gambar untuk foto keluarga dahulu","top":"40%","left":"55%"},{"name":"Kerusi untuk bergambar bersama keluarga di kedai gambar","top":"70%","left":"52%"},{"name":"Lampu studio kedai gambar pada zaman dahulu","top":"20.7%","left":"97.7%"}],"aftermath":"Bukti tidak ditemui dan cucu menyangka kisah nenek hanya dongeng.","turns":[{"after":1,"options":[{"text":"Gambar dahulu ialah bukti sejarah keluarga yang perlu dijaga.","isCorrect":true,"reaction":"Betul, cucu. Nenek akan tunjuk album."},{"text":"Gambar lama tidak perlu disimpan.","isCorrect":false,"reaction":"Nenek terdiam. Album itu kenangan keluarga."},{"text":"Gambar lama tidak penting kerana kabur.","isCorrect":false,"reaction":"Nenek terguris kerana gambar itu satu-satunya bukti kenangan lama."}],"clue":"Simpan gambar sebagai bukti sejarah."}]}'),
(612, 'e6_n2_s4', 'Cari Bukti Kolam Kini', 'Cari empat bukti kolam Deepavali masa kini.', '2', 'Membezakan kolam dahulu (tepung) dengan kini (beras atau hampas kelapa berwarna-warni).', '{"bgImage":"../assets/gameAsset/background/kolam_deepavali_sekarang.png","hotspots":[{"name":"Kolam kini daripada beras atau hampas kelapa berwarna-warni","top":"48.2%","left":"34.8%"},{"name":"Kanak-kanak melukis kolam beramai-ramai","top":"60.6%","left":"81.9%"},{"name":"Keluarga duduk bersama membuat kolam pada Deepavali","top":"42.2%","left":"10.7%"},{"name":"Pelita di tengah kolam semasa Deepavali","top":"65.3%","left":"36.8%"}],"aftermath":"Bukti tidak ditemui dan cucu menyangka kolam sentiasa dibuat dengan cara yang sama.","turns":[{"after":3,"options":[{"text":"Bahan berubah tetapi tradisi menghias rumah dengan kolam masih diteruskan.","isCorrect":true,"reaction":"Betul. Itulah kesinambungannya."},{"text":"Tradisi kolam sudah hilang.","isCorrect":false,"reaction":"Kavitha menggeleng kerana kolam masih dibuat."},{"text":"Kolam hanya hiasan tanpa makna.","isCorrect":false,"reaction":"Kavitha terguris. Ia sebahagian tradisi Deepavali."}],"clue":"Bahan berubah, tradisi kekal."}]}'),
(613, 'e6_n2_s5', 'Nota Makan Besar', 'Baca nota dan tentukan perubahan tradisi makan besar Tahun Baharu Cina.', '5', 'Memahami perubahan: tradisi makan besar masih diraikan, tetapi sesetengah keluarga memilih makan di restoran atau hotel.', '{"clueText":"Nota: Tradisi makan besar di rumah dengan berkumpul bersama-sama keluarga pada malam Tahun Baharu Cina masih diraikan. Walau bagaimanapun, terdapat keluarga yang memilih untuk menikmatinya di tempat lain.","options":[{"text":"Tradisi masih diraikan tetapi ada keluarga memilih restoran atau hotel.","isCorrect":true},{"text":"Tradisi sudah dihentikan sepenuhnya.","isCorrect":false,"consequence":"Nota menyatakan tradisi masih diraikan. Ah Meng membetulkan."},{"text":"Semua keluarga memilih makan di rumah sahaja.","isCorrect":false,"consequence":"Nota menyebut sebahagian memilih tempat lain."},{"text":"Makan besar bertukar menjadi pertandingan memasak.","isCorrect":false,"consequence":"Tiada maklumat itu dalam nota."}],"aftermath":"Nota tersalah baca dan keluarga Ah Meng bertengkar tentang tempat makan besar.","turns":[{"after":1,"options":[{"text":"Tempat boleh berubah, tetapi berkumpul bersama keluarga tetap penting.","isCorrect":true,"reaction":"Betul, nek. Datuk tersenyum."},{"text":"Berkumpul bersama keluarga tidak penting lagi.","isCorrect":false,"reaction":"Ah Meng terkilan. Nilai itulah inti tradisi."},{"text":"Restoran mengubah makna perayaan sepenuhnya.","isCorrect":false,"reaction":"Nenek menggeleng kerana makna perayaan masih sama."}],"clue":"Berkumpul bersama keluarga tetap penting."}]}'),
(614, 'e6_n2_s6', 'Kad Penyediaan Kuih', 'Baca kad dan tentukan cara menyediakan kuih dahulu.', '5', 'Memahami cara penyediaan kuih dahulu: bahan dan kaedah tradisional serta dilakukan secara gotong-royong.', '{"clueText":"Kad: Penyediaan kuih-muih dahulu menggunakan bahan dan kaedah tradisional. Kerja itu dilakukan secara gotong-royong oleh jiran dan keluarga.","options":[{"text":"Menggunakan bahan dan kaedah tradisional secara gotong-royong.","isCorrect":true},{"text":"Menggunakan mesin moden dengan seorang pekerja.","isCorrect":false,"consequence":"Kad menyebut kaedah tradisional dan gotong-royong."},{"text":"Membeli kuih siap di kedai.","isCorrect":false,"consequence":"Itu cara kini. Kad menerangkan cara dahulu."},{"text":"Mengimport kuih dari luar negara.","isCorrect":false,"consequence":"Tiada dalam kad. Nenek ketawa kecil."}],"aftermath":"Kad tersalah baca dan cucu menyangka nenek tidak pernah bekerjasama dengan jiran. Nenek terguris.","turns":[{"after":2,"options":[{"text":"Gotong-royong mengeratkan hubungan jiran dan keluarga.","isCorrect":true,"reaction":"Betul. Nenek tersenyum bangga."},{"text":"Gotong-royong menyusahkan dan tidak perlu.","isCorrect":false,"reaction":"Jiran yang membantu terdiam."},{"text":"Gotong-royong hanya untuk orang tua.","isCorrect":false,"reaction":"Cucu ditegur kerana semua boleh membantu."}],"clue":"Gotong-royong mengeratkan hubungan."}]}'),
(615, 'e6_n2_s7', 'Cari Bukti Kuih Kini', 'Cari empat bukti kuih raya mudah dibeli pada masa kini.', '2', 'Memahami kelebihan peralatan moden: memudahkan penyediaan kuih, kuih raya mudah dibeli, mempercepatkan proses penghasilan.', '{"bgImage":"../assets/gameAsset/background/pembelian_kuih_muih_kini.png","hotspots":[{"name":"Rak balang kuih raya: kuih raya mudah dibeli di kedai","top":"44%","left":"43.4%"},{"name":"Juruwang kedai: kuih kini dibeli dengan mudah","top":"52.7%","left":"65.9%"},{"name":"Beg hadiah dan hamper kuih raya yang siap dibungkus","top":"83%","left":"8.4%"},{"name":"Papan Selamat Hari Raya","top":"33.4%","left":"71.9%"}],"aftermath":"Bukti tidak ditemui dan cucu menyangka beli kuih bermakna tradisi mati.","turns":[{"after":2,"options":[{"text":"Beli atau buat sendiri, semangat berkongsi kuih masih kekal.","isCorrect":true,"reaction":"Itu betul, cucu."},{"text":"Beli kuih bermakna tiada tradisi lagi.","isCorrect":false,"reaction":"Nenek menggeleng kerana amalan berkongsi masih ada."},{"text":"Kuih beli tidak boleh dijadikan hidangan raya.","isCorrect":false,"reaction":"Nenek ketawa kerana kuih beli juga dihidang."}],"clue":"Semangat berkongsi kekal."}]}'),
(616, 'e6_n2_s8', 'Cari Bukti Unduk Ngadau', 'Cari empat bukti Pesta Kaamatan dahulu.', '2', 'Memahami Unduk Ngadau: dahulu pemenang dipilih berdasarkan semangat Huminodun (berkorban menyelamatkan generasinya); kini melalui sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', '{"bgImage":"../assets/gameAsset/background/unduk_ngadau_dahulu.png","hotspots":[{"name":"Pemenang Unduk Ngadau dahulu: dipilih berdasarkan semangat Huminodun","top":"32.1%","left":"69.2%"},{"name":"Tiga peserta Unduk Ngadau menunggu keputusan di tepi pentas","top":"51.2%","left":"40.3%"},{"name":"Pentas pondok Pesta Kaamatan di tepi sawah","top":"57.6%","left":"63.2%"},{"name":"Sawah padi: hasil tanaman yang disyukuri semasa Kaamatan dan Gawai","top":"59.5%","left":"8.1%"}],"aftermath":"Bukti tidak ditemui dan semangat Huminodun dilupakan. Linda kecewa.","turns":[{"after":2,"options":[{"text":"Pemilihan berubah, tetapi nilai berkorban dan menghargai sejarah masih penting.","isCorrect":true,"reaction":"Betul, nak."},{"text":"Semangat Huminodun tidak penting lagi.","isCorrect":false,"reaction":"Linda terkilan kerana nilai itu warisan kaumnya."},{"text":"Unduk Ngadau hanya pertandingan rupa.","isCorrect":false,"reaction":"Linda membetulkan. Ia berkaitan semangat Huminodun."}],"clue":"Nilai berkorban kekal penting."}]}'),
(617, 'e6_n2_s9', 'Kad Amalan Kekal', 'Baca kad dan tentukan amalan yang terus kekal dalam sambutan perayaan.', '5', 'Memahami amalan yang kekal: tradisi balik ke kampung, pemberian duit raya dan angpau, kunjung-mengunjung.', '{"clueText":"Kad: Walaupun banyak perubahan, terdapat amalan yang terus kekal dalam masyarakat. Setiap kali menjelang perayaan ramai pulang ke tempat asal, pemberian duit raya atau angpau diteruskan, dan melawat jiran serta saudara kekal sebagai budaya.","options":[{"text":"Balik ke kampung, pemberian duit raya dan angpau, kunjung-mengunjung.","isCorrect":true},{"text":"Kad ucapan melalui pos sahaja.","isCorrect":false,"consequence":"Itu cara dahulu yang sudah berubah."},{"text":"Makan besar hanya di restoran.","isCorrect":false,"consequence":"Itu perubahan kini, bukan amalan kekal."},{"text":"Penyediaan kuih dengan alat tradisional sahaja.","isCorrect":false,"consequence":"Itu telah berubah kerana alat moden digunakan."}],"aftermath":"Kad tersalah baca dan cucu menyangka semua tradisi sudah hilang.","turns":[{"after":2,"options":[{"text":"Amalan itu mengeratkan perpaduan dan perlu diteruskan.","isCorrect":true,"reaction":"Betul. Itulah warisan kita."},{"text":"Amalan itu sudah ketinggalan zaman.","isCorrect":false,"reaction":"Nenek tersinggung. Tradisi itu menyatukan keluarga."},{"text":"Amalan itu hanya untuk kanak-kanak.","isCorrect":false,"reaction":"Semua orang menyertai dan nenek ketawa kecil."}],"clue":"Teruskan amalan yang mengeratkan perpaduan."}]}'),
(618, 'e6_n3_s1', 'Kad Rumah Terbuka Malaysia', 'Baca kad dan tentukan enam perayaan Rumah Terbuka Malaysia.', '5', 'Mengenal pasti enam perayaan Rumah Terbuka Malaysia: Hari Raya Aidilfitri, Tahun Baharu Cina, Deepavali, Hari Gawai, Pesta Kaamatan dan Krismas.', '{"clueText":"Kad: Rumah terbuka ialah rumah yang dapat dikunjungi semua orang pada hari perayaan. Kerajaan Malaysia telah memutuskan enam perayaan sebagai perayaan utama yang dikenali sebagai Rumah Terbuka Malaysia.","options":[{"text":"Aidilfitri, Tahun Baharu Cina, Deepavali, Hari Gawai, Pesta Kaamatan dan Krismas.","isCorrect":true},{"text":"Aidiladha, Thaipusam, Wesak, Vaisakhi, San Pedro dan Genggulang.","isCorrect":false,"consequence":"Itu perayaan lain, tetapi bukan enam yang ditetapkan. Kad dikembalikan."},{"text":"Aidilfitri, Krismas, Wesak, Vaisakhi, San Pedro dan Hari Moyang.","isCorrect":false,"consequence":"Senarai itu tidak betul. Pelanggan mengerutkan dahi."},{"text":"Tahon Baro, Jis Pai, Tawun Empai, Tahun Bahauk, Genggulang dan Hari Moyang.","isCorrect":false,"consequence":"Itu perayaan Orang Asli. Pelanggan menggeleng."}],"aftermath":"Kad tersalah baca dan pelanggan salah faham tentang perayaan yang diraikan secara Rumah Terbuka. Pelanggan menegur.","turns":[{"after":1,"options":[{"text":"Rumah terbuka membolehkan semua kaum saling melawat dan mengeratkan perpaduan.","isCorrect":true,"reaction":"Betul. Pelanggan tersenyum."},{"text":"Rumah terbuka hanya untuk keluarga sendiri.","isCorrect":false,"reaction":"Pelanggan membantah. Ia untuk semua orang."},{"text":"Rumah terbuka tidak diperlukan.","isCorrect":false,"reaction":"Pelanggan menggeleng kerana amalan itu mengeratkan perpaduan."}],"clue":"Rumah terbuka untuk semua."}]}'),
(619, 'e6_n3_s2', 'Kad Kepentingan Berkumpul', 'Baca kad dan tentukan kepentingan meraikan perayaan bersama keluarga.', '5', 'Memahami kepentingan meraikan perayaan bersama keluarga: mengeratkan hubungan, mengukuhkan perpaduan anggota keluarga, mengelakkan tradisi hilang, mengekalkan kesejahteraan negara.', '{"clueText":"Kad: Meraikan perayaan bersama keluarga dapat mengeratkan hubungan dan mengukuhkan perpaduan antara anggota keluarga, mengelakkan tradisi hilang ditelan zaman dan mengekalkan kesejahteraan negara.","options":[{"text":"Mengeratkan hubungan keluarga dan mengelakkan tradisi hilang.","isCorrect":true},{"text":"Mengurangkan perhubungan antara keluarga.","isCorrect":false,"consequence":"Jawapan itu bertentangan dengan kad."},{"text":"Menambahkan tradisi baharu tanpa nilai.","isCorrect":false,"consequence":"Tiada dalam kad. Pelanggan menggeleng."},{"text":"Menggantikan perayaan dengan hari biasa.","isCorrect":false,"consequence":"Itu menghilangkan tradisi. Kad dikembalikan."}],"aftermath":"Kad tersalah baca dan pelanggan menyangka berkumpul bersama keluarga tidak penting.","turns":[{"after":1,"options":[{"text":"Berkumpul bersama keluarga mengeratkan hubungan dan menjaga tradisi.","isCorrect":true,"reaction":"Betul. Pelanggan membeli kad untuk semua jiran."},{"text":"Cukup menelefon tanpa berjumpa.","isCorrect":false,"reaction":"Hubungan menjadi renggang dan tradisi hilang."},{"text":"Berkumpul hanya membazir masa.","isCorrect":false,"reaction":"Pelanggan lain menegur kerana berkumpul penting untuk kesejahteraan."}],"clue":"Berkumpul untuk mengeratkan hubungan."}]}'),
(620, 'e6_n3_s3', 'Kad Hormat Kepelbagaian Sambutan', 'Baca kad dan tentukan kepentingan menghormati kepelbagaian sambutan dan adab perayaan.', '5', 'Memahami kepentingan: mengekalkan keamanan dan keharmonian negara, memupuk bertolak-ansur, melahirkan masyarakat yang memahami budaya kaum lain, melahirkan generasi rasional dan berilmu.', '{"clueText":"Kad: Menghormati kepelbagaian sambutan dan adab perayaan dapat mengekalkan keamanan dan keharmonian negara, memupuk semangat bertolak-ansur serta melahirkan masyarakat yang memahami dan menghormati budaya kaum lain.","options":[{"text":"Mengekalkan keamanan dan keharmonian serta memupuk bertolak-ansur.","isCorrect":true},{"text":"Menimbulkan salah faham antara jiran.","isCorrect":false,"consequence":"Kad menyatakan sebaliknya. Kau dibetulkan."},{"text":"Menjauhkan satu kaum daripada yang lain.","isCorrect":false,"consequence":"Itu menambah curiga. Kad dikembalikan."},{"text":"Menyeragamkan semua perayaan menjadi satu.","isCorrect":false,"consequence":"Kad tidak menyatakan begitu. Setiap perayaan ada keunikan."}],"aftermath":"Kad tersalah baca dan kanak-kanak melanggar adab semasa melawat. Jiran tersinggung.","turns":[{"after":3,"options":[{"text":"Kita bertanya tentang adab dan menghormati cara sambutan jiran.","isCorrect":true,"reaction":"Itu cara yang matang."},{"text":"Kita melawat tanpa bertanya.","isCorrect":false,"reaction":"Jiran terasa tidak dihormati."},{"text":"Kita tidak perlu melawat langsung.","isCorrect":false,"reaction":"Hubungan menjadi renggang."}],"clue":"Tanya tentang adab dan hormati."}]}'),
(621, 'e6_n3_s4', 'Gawai dan Unduk Ngadau Dahulu dan Kini', 'Padankan cara sambutan dahulu dengan kini.', '4', 'Membezakan Hari Gawai dahulu (petani Dayak, upacara ritual) dengan kini (pelbagai kaum tanpa mengira pekerjaan), dan Unduk Ngadau dahulu (semangat Huminodun) dengan kini (soal jawab sejarah).', '{"pairs":[{"text":"Gawai dahulu","pair":1},{"text":"Diraikan petani kaum Dayak dengan upacara ritual","pair":1},{"text":"Gawai kini","pair":2},{"text":"Diraikan pelbagai kaum tanpa mengira pekerjaan","pair":2},{"text":"Unduk Ngadau dahulu","pair":3},{"text":"Dipilih berdasarkan semangat Huminodun","pair":3},{"text":"Unduk Ngadau kini","pair":4},{"text":"Sesi soal jawab tentang sejarah dan kehidupan lampau","pair":4}],"aftermath":"Kad bertukar dan tetamu menyangka Gawai tidak berubah. Tetua menggeleng.","turns":[{"after":3,"options":[{"text":"Perayaan menjadi lebih meriah apabila semua kaum menyertainya dengan hormat.","isCorrect":true,"reaction":"Betul. Tetua tersenyum."},{"text":"Perayaan hanya boleh disertai kaum Dayak.","isCorrect":false,"reaction":"Tetamu pulang dengan hampa."},{"text":"Perayaan tidak perlu dipelihara kerana sudah berubah.","isCorrect":false,"reaction":"Tetua menggeleng. Warisan perlu dijaga."}],"clue":"Perayaan disambut semua kaum dengan hormat."}]}'),
(622, 'e6_n3_s5', 'Pameran Tradisi Dahulu dan Kini', 'Padankan tradisi dahulu dengan perubahannya kini.', '4', 'Membezakan tradisi dahulu dan kini: kolam (tepung → beras atau hampas kelapa berwarna-warni), makan besar (di rumah → ada yang di restoran atau hotel), kuih (tradisional dan gotong-royong → peralatan moden).', '{"pairs":[{"text":"Kolam dibuat daripada tepung","pair":1},{"text":"Beras atau hampas kelapa berwarna-warni","pair":1},{"text":"Makan besar di rumah bersama keluarga","pair":2},{"text":"Ada keluarga memilih restoran atau hotel","pair":2},{"text":"Kuih bahan dan kaedah tradisional, gotong-royong","pair":3},{"text":"Peralatan moden memudahkan penyediaan kuih","pair":3}],"aftermath":"Padanan tersilap dan pelanggan menyangka tradisi tiada perubahan. Pameran mengelirukan.","turns":[{"after":1,"options":[{"text":"Cara berubah mengikut zaman, tetapi tradisi dan semangatnya perlu dikekalkan.","isCorrect":true,"reaction":"Betul. Pameran ini memberi pengajaran."},{"text":"Tradisi lama patut ditinggalkan semuanya.","isCorrect":false,"reaction":"Pelanggan tua tersinggung."},{"text":"Tradisi tidak boleh berubah sama sekali.","isCorrect":false,"reaction":"Pelanggan muda membantah kerana alat moden memudahkan."}],"clue":"Cara berubah, tradisi dikekalkan."}]}'),
(623, 'e6_n3_s6', 'Papan SWOT Warisan Perayaan', 'Padankan istilah SWOT dengan soalan yang dibincangkan.', '4', 'Memahami analisis SWOT tentang warisan perayaan: kekuatan, kelemahan, peluang, halangan dan cabaran untuk mengekalkan warisan.', '{"pairs":[{"text":"Kekuatan","pair":1},{"text":"Apa yang membantu mengekalkan warisan perayaan","pair":1},{"text":"Kelemahan","pair":2},{"text":"Apa yang menyukarkan mempertahankan warisan perayaan","pair":2},{"text":"Peluang","pair":3},{"text":"Peluang untuk mengekalkan warisan perayaan","pair":3},{"text":"Halangan dan cabaran","pair":4},{"text":"Cabaran mengekalkan warisan perayaan","pair":4}],"aftermath":"Kad tersilap dan analisis kumpulan tidak menjawab soalan. Cikgu menggeleng.","turns":[{"after":1,"options":[{"text":"Kita menganalisis supaya dapat mengekalkan warisan perayaan.","isCorrect":true,"reaction":"Betul. Murid-murid mula menulis."},{"text":"Kita menganalisis supaya perayaan ditamatkan.","isCorrect":false,"reaction":"Pekerja terkejut. Tujuannya mengekalkan warisan."},{"text":"Kita tidak perlu menganalisis.","isCorrect":false,"reaction":"Cikgu menggeleng kerana analisis membantu merancang."}],"clue":"Analisis SWOT membantu mengekalkan warisan."}]}'),
(624, 'e6_n3_s7', 'Ringkasan Amalan Perayaan', 'Padankan amalan dengan penerangannya.', '4', 'Merumus amalan yang kekal: balik ke kampung, pemberian duit raya dan angpau, kunjung-mengunjung, Rumah Terbuka.', '{"pairs":[{"text":"Balik ke kampung","pair":1},{"text":"Tradisi menjelang perayaan yang kekal","pair":1},{"text":"Duit raya dan angpau","pair":2},{"text":"Pemberian yang kekal sehingga kini","pair":2},{"text":"Kunjung-mengunjung","pair":3},{"text":"Amalan budaya yang kekal dalam masyarakat","pair":3},{"text":"Rumah terbuka","pair":4},{"text":"Rumah yang dapat dikunjungi semua orang pada hari perayaan","pair":4}],"aftermath":"Kad tersilap dan ringkasan mengelirukan pelanggan terakhir.","turns":[{"after":1,"options":[{"text":"Perayaan yang dihormati mengeratkan perpaduan dan menjaga kesejahteraan negara.","isCorrect":true,"reaction":"Betul. Kedai ditutup dengan senyuman."},{"text":"Perayaan tidak berkaitan dengan perpaduan.","isCorrect":false,"reaction":"Pelanggan menggeleng dan keluar."},{"text":"Perayaan hanya membazir wang.","isCorrect":false,"reaction":"Pelanggan tersinggung kerana perayaan mengeratkan hubungan."}],"clue":"Perayaan mengeratkan perpaduan."}]}'),
(701, 'e7_n1_s1', 'Nota Jawatan Perdana Menteri', 'Baca nota dan tentukan siapa yang melantik Perdana Menteri dan apakah jawatannya.', '5', 'Memahami jawatan Perdana Menteri: ketua kerajaan, dilantik oleh Yang di-Pertuan Agong, perlu sokongan majoriti Ahli Dewan Rakyat, diwujudkan selepas 31 Ogos 1957.', '{"clueText":"Nota: Perdana Menteri mengetuai pentadbiran negara. Beliau dilantik secara rasmi oleh Yang di-Pertuan Agong dan perlu mendapat sokongan majoriti Ahli Dewan Rakyat. Jawatan ini diwujudkan selepas Tanah Melayu merdeka pada 31 Ogos 1957.","options":[{"text":"Ketua kerajaan yang dilantik oleh Yang di-Pertuan Agong.","isCorrect":true},{"text":"Ketua negara yang dipilih terus oleh rakyat.","isCorrect":false,"consequence":"Nota menyatakan sebaliknya. Penerbit menggeleng."},{"text":"Ketua negara yang dilantik oleh Menteri Besar.","isCorrect":false,"consequence":"Menteri Besar tidak melantik Perdana Menteri. Yang di-Pertuan Agong yang melantik."},{"text":"Ketua pembesar yang menggantikan Bendahara pada tahun 1511.","isCorrect":false,"consequence":"Jawatan Perdana Menteri diwujudkan pada 1957, bukan 1511."}],"aftermath":"Skrip tersalah dan siaran menyatakan Perdana Menteri dipilih terus oleh rakyat. Penonton keliru.","turns":[{"after":1,"options":[{"text":"Ketua kerajaan mesti disokong majoriti Dewan Rakyat dan dilantik oleh Agong.","isCorrect":true,"reaction":"Betul. Penerbit mencatat skrip baharu."},{"text":"Perdana Menteri boleh memerintah tanpa sokongan sesiapa.","isCorrect":false,"reaction":"Penerbit membantah. Sokongan majoriti Dewan Rakyat diperlukan."},{"text":"Perdana Menteri sama dengan Bendahara.","isCorrect":false,"reaction":"Itu jawatan zaman Kesultanan Melayu Melaka. Rakaman dihentikan."}],"clue":"Dilantik Agong, disokong majoriti."}]}'),
(702, 'e7_n1_s2', 'Pita Empat Perdana Menteri Pertama', 'Susun empat Perdana Menteri pertama mengikut tarikh mereka mula berkhidmat.', '1', 'Menyusun kronologi: Tunku (31 Ogos 1957), Tun Razak (22 Sep 1970), Tun Hussein (15 Jan 1976), Tun Dr. Mahathir (16 Julai 1981).', '{"timelineItems":[{"id":1,"year":"31 Ogos 1957","text":"Tunku Abdul Rahman menjadi Perdana Menteri pertama","why":"Perdana Menteri pertama selepas merdeka."},{"id":2,"year":"22 September 1970","text":"Tun Abdul Razak menjadi Perdana Menteri kedua","why":"Beliau menggantikan Tunku."},{"id":3,"year":"15 Januari 1976","text":"Tun Hussein Onn menjadi Perdana Menteri ketiga","why":"Beliau menggantikan Tun Razak."},{"id":4,"year":"16 Julai 1981","text":"Tun Dr. Mahathir menjadi Perdana Menteri keempat","why":"Beliau menggantikan Tun Hussein."}],"aftermath":"Pita tersusun salah dan siaran memperkenalkan Perdana Menteri dengan urutan yang songsang.","turns":[{"after":2,"options":[{"text":"Kita menyusun mengikut tarikh supaya penonton memahami urutan pemimpin.","isCorrect":true,"reaction":"Betul. Kerja kau teratur."},{"text":"Nama pemimpin sahaja sudah memadai tanpa tarikh.","isCorrect":false,"reaction":"Penerbit menggeleng. Tarikh membezakan giliran setiap pemimpin."},{"text":"Mana-mana susunan pun sama.","isCorrect":false,"reaction":"Penonton akan keliru tentang urutan pemimpin negara."}],"clue":"Tarikh menentukan urutan."}]}'),
(703, 'e7_n1_s3', 'Cari Bukti Laungan Merdeka', 'Cari empat bukti dalam rakaman laungan kemerdekaan.', '2', 'Mengenal pasti bukti pencapaian Tunku: memperjuangkan kemerdekaan secara rundingan dan laungan kemerdekaan di Stadium Merdeka pada 31 Ogos 1957.', '{"bgImage":"../assets/gameAsset/background/laungan_di_stadium_merdeka.png","hotspots":[{"name":"Tunku di podium: memperjuangkan kemerdekaan secara rundingan","top":"35%","left":"52%"},{"name":"Papan Perisytiharan Kemerdekaan Malaya di podium","top":"69.4%","left":"50.4%"},{"name":"Poster Merdeka! Malaya! yang dipegang rakyat","top":"46.5%","left":"8.7%"},{"name":"Rakyat bersorak dan mengangkat tangan menyambut kemerdekaan","top":"59.4%","left":"73.3%"}],"aftermath":"Bukti tidak ditemui dan siaran gagal menunjukkan bahawa kemerdekaan dicapai secara rundingan.","turns":[{"after":2,"options":[{"text":"Kemerdekaan dicapai secara rundingan dan rakyat menyambutnya dengan gembira.","isCorrect":true,"reaction":"Betul. Rakaman ini bukti sejarah."},{"text":"Kemerdekaan dicapai melalui peperangan.","isCorrect":false,"reaction":"Tunku membetulkan. Beliau berunding secara aman."},{"text":"Rakyat tidak menyambut kemerdekaan.","isCorrect":false,"reaction":"Rakaman menunjukkan rakyat bersorak sambil mengangkat tangan."}],"clue":"Rundingan dan sambutan rakyat."}]}'),
(704, 'e7_n1_s4', 'Biodata Tunku Abdul Rahman', 'Padankan biodata Tunku dengan maklumat yang betul.', '4', 'Memahami biodata Tunku: lahir 8 Februari 1903 di Alor Setar; belajar di Penang Free School dan Universiti Cambridge (undang-undang); Ketua Menteri 1955; Bapa Kemerdekaan.', '{"pairs":[{"text":"Tempat lahir","pair":1},{"text":"Alor Setar, Kedah","pair":1},{"text":"Pelajaran tinggi","pair":2},{"text":"Universiti Cambridge dalam bidang undang-undang","pair":2},{"text":"Jawatan pada tahun 1955","pair":3},{"text":"Ketua Menteri Persekutuan Tanah Melayu","pair":3},{"text":"Gelaran","pair":4},{"text":"Bapa Kemerdekaan","pair":4},{"text":"Pernah berkhidmat sebagai","pair":5},{"text":"Pegawai Daerah di Padang Terap, Langkawi dan Sungai Petani","pair":5}],"aftermath":"Biodata tersilap dan siaran memperkenalkan Tunku dengan gelaran yang salah. Penonton menghantar teguran.","turns":[{"after":3,"options":[{"text":"Biodata yang tepat menghormati jasa pemimpin dan mengelakkan salah faham.","isCorrect":true,"reaction":"Betul. Kita semak sebelum bersiaran."},{"text":"Biodata tidak penting kerana Tunku terkenal.","isCorrect":false,"reaction":"Penerbit menggeleng. Setiap fakta perlu betul."},{"text":"Gelaran boleh ditukar mengikut cita rasa penyiar.","isCorrect":false,"reaction":"Penonton menegur kerana gelaran itu ada sebab sejarahnya."}],"clue":"Biodata mesti tepat."}]}'),
(705, 'e7_n1_s5', 'Nota Pencapaian Tun Razak', 'Baca nota dan tentukan pencapaian Tun Razak selepas peristiwa 13 Mei 1969.', '5', 'Memahami pencapaian Tun Razak: mengembalikan keamanan melalui MAGERAN dan memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat berbilang kaum.', '{"clueText":"Nota: Selepas peristiwa 13 Mei 1969, Tun Abdul Razak mengembalikan keamanan negara melalui pentadbiran Majlis Gerakan Negara (MAGERAN). Beliau memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan rakyat dan menyusun semula masyarakat berbilang kaum.","options":[{"text":"Menubuhkan MAGERAN dan memperkenalkan DEB.","isCorrect":true},{"text":"Menutup semua pejabat kerajaan.","isCorrect":false,"consequence":"Nota tidak menyebut perkara itu. Skrip dibuang."},{"text":"Memperkenalkan Program Rukun Tetangga dan Amanah Saham Nasional.","isCorrect":false,"consequence":"Itu pencapaian Tun Hussein Onn."},{"text":"Membina Putrajaya dan KLIA.","isCorrect":false,"consequence":"Itu pencapaian Tun Dr. Mahathir."}],"aftermath":"Skrip tersalah dan siaran menyatakan Tun Razak menutup pejabat. Penonton marah.","turns":[{"after":2,"options":[{"text":"Beliau memulihkan keamanan dan membasmi kemiskinan supaya masyarakat berbilang kaum seimbang.","isCorrect":true,"reaction":"Betul. Itulah sebab beliau digelar Bapa Pembangunan."},{"text":"Beliau memulihkan keamanan dengan menyekat semua kegiatan ekonomi.","isCorrect":false,"reaction":"Itu tidak benar. DEB bertujuan membasmi kemiskinan."},{"text":"Beliau hanya membina bangunan tanpa mengubah dasar.","isCorrect":false,"reaction":"Tun Razak memperkenalkan dasar, bukan hanya bangunan."}],"clue":"Keamanan dan DEB."}]}'),
(706, 'e7_n1_s6', 'Biodata Tun Abdul Razak', 'Padankan biodata Tun Abdul Razak dengan maklumat yang betul.', '4', 'Memahami biodata Tun Razak: lahir 11 Mac 1922 di Pulau Keladi, Pekan, Pahang; Kolej Melayu Kuala Kangsar, Raffles College, Lincoln\'s Inn; Menteri Besar Pahang; PM 22 Sep 1970-14 Jan 1976; Bapa Pembangunan.', '{"pairs":[{"text":"Tempat lahir","pair":1},{"text":"Pulau Keladi, Pekan, Pahang","pair":1},{"text":"Pelajaran di Perak","pair":2},{"text":"Kolej Melayu Kuala Kangsar","pair":2},{"text":"Pelajaran undang-undang","pair":3},{"text":"Lincoln\'s Inn, London","pair":3},{"text":"Jawatan di negerinya","pair":4},{"text":"Setiausaha Kerajaan Negeri Pahang dan Menteri Besar Pahang","pair":4},{"text":"Gelaran","pair":5},{"text":"Bapa Pembangunan","pair":5}],"aftermath":"Biodata tersilap dan siaran menyatakan Tun Razak belajar di Cambridge. Penonton menegur.","turns":[{"after":3,"options":[{"text":"Kita menghargai pemimpin dengan mengetahui perjalanan hidup mereka.","isCorrect":true,"reaction":"Betul. Itu tanda hormat."},{"text":"Biodata pemimpin tidak perlu dipelajari.","isCorrect":false,"reaction":"Penerbit terkilan. Latar pemimpin membantu kita menghargai jasa."},{"text":"Cukup mengetahui nama sahaja.","isCorrect":false,"reaction":"Siaran menjadi cetek dan mengelirukan."}],"clue":"Pelajari latar hidup pemimpin."}]}'),
(707, 'e7_n1_s7', 'Pencapaian Tun Hussein Onn', 'Padankan pencapaian dan biodata Tun Hussein Onn.', '4', 'Memahami Tun Hussein: Amanah Saham Nasional Berhad (bumiputera memiliki saham), Program Rukun Tetangga (perpaduan rakyat), lahir 12 Feb 1922 di Johor Bahru; PM 15 Jan 1976-16 Jul 1981; Bapa Perpaduan.', '{"pairs":[{"text":"Amanah Saham Nasional Berhad","pair":1},{"text":"Memudahkan kaum bumiputera memiliki saham dalam syarikat berhad","pair":1},{"text":"Program Rukun Tetangga","pair":2},{"text":"Menggalakkan perpaduan dalam kalangan rakyat berbilang kaum","pair":2},{"text":"Gelaran","pair":3},{"text":"Bapa Perpaduan","pair":3},{"text":"Tempoh jawatan","pair":4},{"text":"15 Januari 1976 hingga 16 Julai 1981","pair":4},{"text":"Tempat lahir","pair":5},{"text":"Johor Bahru, Johor","pair":5}],"aftermath":"Pencapaian tersilap dan siaran memberikan jasa Tun Hussein kepada pemimpin lain.","turns":[{"after":2,"options":[{"text":"Program yang menyatukan rakyat berbilang kaum patut diteruskan.","isCorrect":true,"reaction":"Betul. Itulah warisan Bapa Perpaduan."},{"text":"Program perpaduan hanya untuk satu kaum.","isCorrect":false,"reaction":"Rukun Tetangga menggalakkan perpaduan rakyat berbilang kaum."},{"text":"Tun Hussein tidak melakukan apa-apa untuk perpaduan.","isCorrect":false,"reaction":"Penerbit membetulkan. Beliau memperkenalkan Rukun Tetangga."}],"clue":"Program perpaduan untuk semua."}]}'),
(708, 'e7_n1_s8', 'Papan Gelaran Pemimpin', 'Padankan gelaran dengan pemimpinnya.', '4', 'Mengenal pasti gelaran: Tunku (Bapa Kemerdekaan), Tun Razak (Bapa Pembangunan), Tun Hussein (Bapa Perpaduan), Tun Dr. Mahathir (Bapa Pemodenan), Tun Abdullah (Bapa Pembangunan Modal Insan).', '{"pairs":[{"text":"Bapa Kemerdekaan","pair":1},{"text":"Tunku Abdul Rahman","pair":1},{"text":"Bapa Pembangunan","pair":2},{"text":"Tun Abdul Razak","pair":2},{"text":"Bapa Perpaduan","pair":3},{"text":"Tun Hussein Onn","pair":3},{"text":"Bapa Pemodenan","pair":4},{"text":"Tun Dr. Mahathir Mohamad","pair":4},{"text":"Bapa Pembangunan Modal Insan","pair":5},{"text":"Tun Abdullah Ahmad Badawi","pair":5}],"aftermath":"Gelaran bertukar dan Tun Abdullah digelar Bapa Pemodenan di skrin. Penonton menegur.","turns":[{"after":1,"options":[{"text":"Setiap gelaran mencerminkan sumbangan utama pemimpin itu kepada negara.","isCorrect":true,"reaction":"Betul. Siaran ditutup dengan ucapan terima kasih."},{"text":"Gelaran hanya hiasan tanpa makna.","isCorrect":false,"reaction":"Penerbit menggeleng. Setiap gelaran ada sumbangan di sebaliknya."},{"text":"Semua pemimpin berkongsi satu gelaran yang sama.","isCorrect":false,"reaction":"Setiap pemimpin mempunyai gelaran berbeza."}],"clue":"Gelaran mencerminkan sumbangan."}]}'),
(709, 'e7_n2_s1', 'Gambar dan Tugas Perdana Menteri', 'Padankan contoh dalam gambar dengan tugas Perdana Menteri.', '4', 'Memahami tugas PM: ketua pentadbir utama (mesyuarat Ketua Setiausaha), memastikan dasar pembangunan (Tun Razak meninjau Felda), hubungan diplomatik (Tun Hussein bertemu Anwar Sadat 1977), mencadangkan duta (watikah ke Rusia).', '{"pairs":[{"text":"Tun Dr. Mahathir bermesyuarat dengan Ketua-ketua Setiausaha Kementerian","pair":1},{"text":"Menjadi ketua pentadbir utama yang merancang dan menyelaraskan dasar negara","pair":1},{"text":"Tun Razak meninjau tanaman getah di Felda Lurah Bilut","pair":2},{"text":"Memastikan dasar pembangunan dapat ditingkatkan demi kesejahteraan rakyat","pair":2},{"text":"Tun Hussein bertemu Presiden Anwar Sadat pada 1977","pair":3},{"text":"Menjalin hubungan diplomatik dan persahabatan dengan negara luar","pair":3},{"text":"Watikah pelantikan duta Malaysia ke Rusia","pair":4},{"text":"Mencadangkan pelantikan duta, diplomat dan konsulat","pair":4}],"aftermath":"Gambar dipadankan dengan tugas yang salah dan murid mencatat nota yang salah dalam buku.","turns":[{"after":1,"options":[{"text":"Setiap tugas Perdana Menteri bertujuan memajukan negara demi kesejahteraan rakyat.","isCorrect":true,"reaction":"Betul, cikgu."},{"text":"Perdana Menteri hanya bertugas pada hari perayaan.","isCorrect":false,"reaction":"Murid menggeleng. Tugas itu berterusan setiap hari."},{"text":"Perdana Menteri tidak perlu bekerjasama dengan negara lain.","isCorrect":false,"reaction":"Itu salah. Hubungan diplomatik penting untuk negara."}],"clue":"Tugas demi kesejahteraan rakyat."}]}'),
(710, 'e7_n2_s2', 'Tugas Berkaitan Agong dan Jemaah Menteri', 'Padankan tugas Perdana Menteri dengan penerangannya.', '4', 'Memahami tugas PM: menasihati Agong, mengiringi Agong ke Mesyuarat Majlis Raja-Raja, mencadangkan senarai Jemaah Menteri, mempengerusikan mesyuarat Jemaah Menteri.', '{"pairs":[{"text":"Menasihati Yang di-Pertuan Agong","pair":1},{"text":"Berkaitan pemerintahan negara","pair":1},{"text":"Mengiringi Yang di-Pertuan Agong","pair":2},{"text":"Ke Mesyuarat Majlis Raja-Raja","pair":2},{"text":"Mencadangkan senarai Jemaah Menteri","pair":3},{"text":"Untuk dilantik oleh Yang di-Pertuan Agong","pair":3},{"text":"Mempengerusikan Mesyuarat Jemaah Menteri","pair":4},{"text":"Mesyuarat pertama selepas merdeka dipengerusikan oleh Tunku","pair":4}],"aftermath":"Kad bertukar dan murid menyangka Perdana Menteri melantik dirinya sendiri sebagai Agong.","turns":[{"after":1,"options":[{"text":"Perdana Menteri mencadangkan dan Agong yang melantik Jemaah Menteri.","isCorrect":true,"reaction":"Betul. Murid menyalin ke buku."},{"text":"Perdana Menteri melantik Jemaah Menteri sendiri.","isCorrect":false,"reaction":"Agong yang melantik. Cikgu membetulkan."},{"text":"Jemaah Menteri dipilih oleh murid sekolah.","isCorrect":false,"reaction":"Murid ketawa kerana jawapan itu tidak masuk akal."}],"clue":"Perdana Menteri mencadangkan."}]}'),
(711, 'e7_n2_s3', 'Biodata Tun Dr. Mahathir', 'Padankan biodata Tun Dr. Mahathir dengan maklumat yang betul.', '4', 'Memahami biodata Mahathir: lahir 10 Julai 1925 di Seberang Perak, Alor Setar; belajar perubatan di Singapura; Klinik MAHA 1957; Menteri Pelajaran; PM 16 Julai 1981-30 Oktober 2003; Bapa Pemodenan.', '{"pairs":[{"text":"Tempat lahir","pair":1},{"text":"Seberang Perak, Alor Setar, Kedah","pair":1},{"text":"Bidang pelajaran","pair":2},{"text":"Perubatan di Singapura","pair":2},{"text":"Klinik yang dibuka pada tahun 1957","pair":3},{"text":"Klinik MAHA di Alor Setar","pair":3},{"text":"Tempoh Perdana Menteri keempat","pair":4},{"text":"16 Julai 1981 hingga 30 Oktober 2003","pair":4},{"text":"Gelaran","pair":5},{"text":"Bapa Pemodenan","pair":5}],"aftermath":"Biodata tersilap dan murid menulis Tun Dr. Mahathir belajar undang-undang. Cikgu terpaksa membetulkan.","turns":[{"after":2,"options":[{"text":"Pemimpin yang berpendidikan dan berpengalaman dapat mentadbir negara dengan sistematik.","isCorrect":true,"reaction":"Betul. Murid mengangguk."},{"text":"Pendidikan pemimpin tidak penting.","isCorrect":false,"reaction":"Cikgu menggeleng. Latar pendidikan menyumbang kepada pentadbiran yang berkesan."},{"text":"Semua Perdana Menteri belajar bidang yang sama.","isCorrect":false,"reaction":"Murid menyemak dan mendapati bidang mereka berbeza."}],"clue":"Latar pemimpin menyumbang kepada pentadbiran."}]}'),
(712, 'e7_n2_s4', 'Cari Bukti Wawasan 2020', 'Cari empat bukti pencapaian negara di bawah kepimpinan Tun Dr. Mahathir.', '2', 'Memahami pencapaian Mahathir: Wawasan 2020 (Putrajaya, KLIA, Menara Berkembar Petronas di KLCC) dan sektor perindustrian berteknologi tinggi melalui HICOM.', '{"bgImage":"../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png","hotspots":[{"name":"Menara Berkembar Petronas (KLCC): dibina pada zaman Tun Dr. Mahathir","top":"26.5%","left":"22%"},{"name":"Kilang moden: HICOM untuk industri berteknologi tinggi","top":"45%","left":"78%"},{"name":"Papan carta menaik: Wawasan 2020 menuju kemajuan","top":"22%","left":"90%"},{"name":"Jambatan layang dan jalan raya: pembangunan seperti KLIA dan Putrajaya","top":"62%","left":"38%"}],"aftermath":"Bukti tidak ditemui dan murid menyangka Wawasan 2020 hanyalah slogan.","turns":[{"after":2,"options":[{"text":"Wawasan 2020 bertujuan menjadikan Malaysia negara maju.","isCorrect":true,"reaction":"Betul. Murid bersorak."},{"text":"Wawasan 2020 bertujuan menutup kilang.","isCorrect":false,"reaction":"Gambar menunjukkan kilang moden HICOM. Cikgu membetulkan."},{"text":"Wawasan 2020 tiada kaitan dengan pembangunan.","isCorrect":false,"reaction":"Murid menggeleng kerana ia merangkumi Putrajaya dan KLIA."}],"clue":"Wawasan 2020: negara maju."}]}'),
(713, 'e7_n2_s5', 'Nota Perdana Menteri Ketujuh', 'Baca nota dan tentukan maklumat Tun Dr. Mahathir sebagai Perdana Menteri ketujuh.', '5', 'Memahami PM ke-7: Tun Dr. Mahathir kali kedua 10 Mei 2018-24 Feb 2020; Pengerusi PETRONAS dan Penasihat PROTON; lawatan ke Jepun, Thailand dan UK; Wawasan Kemakmuran Bersama 2030.', '{"clueText":"Nota: Tun Dr. Mahathir menjadi Perdana Menteri kali kedua pada 10 Mei 2018 hingga 24 Februari 2020. Beliau pernah berkhidmat sebagai Pengerusi PETRONAS dan Penasihat PROTON, melawat Jepun, Thailand dan United Kingdom serta memperkenalkan satu wawasan baharu.","options":[{"text":"Wawasan Kemakmuran Bersama 2030.","isCorrect":true},{"text":"Wawasan 2020.","isCorrect":false,"consequence":"Itu wawasan beliau pada kali pertama. Nota menyebut wawasan baharu."},{"text":"Gagasan 1Malaysia.","isCorrect":false,"consequence":"Itu diperkenalkan oleh Dato\' Sri Najib."},{"text":"Konsep Keluarga Malaysia.","isCorrect":false,"consequence":"Itu diperkenalkan oleh Dato\' Seri Ismail Sabri."}],"aftermath":"Nota tersalah baca dan murid menulis wawasan beliau sama dengan kali pertama.","turns":[{"after":3,"options":[{"text":"Wawasan baharu itu bermatlamat memakmurkan semua rakyat.","isCorrect":true,"reaction":"Betul, cikgu."},{"text":"Beliau berhenti bekerjasama dengan semua negara luar.","isCorrect":false,"reaction":"Nota menyatakan sebaliknya. Beliau meneruskan kerjasama."},{"text":"Beliau hanya sekali menjadi Perdana Menteri.","isCorrect":false,"reaction":"Murid membetulkan kerana beliau memegang jawatan itu dua kali."}],"clue":"Dua kali PM, wawasan baharu."}]}'),
(714, 'e7_n2_s6', 'Biodata Tun Abdullah Ahmad Badawi', 'Padankan biodata Tun Abdullah dengan maklumat yang betul.', '4', 'Memahami biodata Abdullah: lahir 26 Nov 1939 di Kampung Perlis, Bayan Lepas, Pulau Pinang; Pengajian Islam di Universiti Malaya; Setiausaha MAGERAN; PM 31 Okt 2003-3 Apr 2009; Bapa Pembangunan Modal Insan.', '{"pairs":[{"text":"Tempat lahir","pair":1},{"text":"Kampung Perlis, Bayan Lepas, Pulau Pinang","pair":1},{"text":"Bidang di Universiti Malaya","pair":2},{"text":"Pengajian Islam","pair":2},{"text":"Pernah berkhidmat sebagai","pair":3},{"text":"Setiausaha Majlis Gerakan Negara (MAGERAN)","pair":3},{"text":"Tempoh Perdana Menteri kelima","pair":4},{"text":"31 Oktober 2003 hingga 3 April 2009","pair":4},{"text":"Gelaran","pair":5},{"text":"Bapa Pembangunan Modal Insan","pair":5}],"aftermath":"Biodata tersilap dan murid mengelirukan Tun Abdullah dengan pemimpin lain.","turns":[{"after":2,"options":[{"text":"Modal insan bermaksud membangunkan rakyat yang berilmu dan berakhlak.","isCorrect":true,"reaction":"Betul. Itu sumbangan beliau."},{"text":"Modal insan bermaksud membangunkan bangunan sahaja.","isCorrect":false,"reaction":"Gelaran itu berkaitan pembangunan manusia."},{"text":"Modal insan bermaksud menambah cukai.","isCorrect":false,"reaction":"Itu salah. Modal insan ialah pembangunan rakyat."}],"clue":"Modal insan: pembangunan rakyat."}]}'),
(715, 'e7_n2_s7', 'Nota Koridor dan Integriti', 'Baca nota dan tentukan fungsi Pelan Integriti Nasional.', '5', 'Memahami pencapaian Abdullah: Koridor Wilayah Ekonomi (pembangunan ekonomi seimbang dan pelaburan besar, contoh Iskandar Malaysia di Johor) dan Pelan Integriti Nasional (masyarakat bermoral dan beretika).', '{"clueText":"Nota: Tun Abdullah memperkenalkan Koridor Wilayah Ekonomi untuk memastikan pembangunan ekonomi seimbang dan kemasukan pelaburan yang besar. Beliau juga memperkenalkan Pelan Integriti Nasional (PIN) sebagai pelan untuk membina masyarakat yang bermoral dan beretika.","options":[{"text":"Pelan Integriti Nasional membina masyarakat yang bermoral dan beretika.","isCorrect":true},{"text":"Pelan Integriti Nasional membina Putrajaya dan KLIA.","isCorrect":false,"consequence":"Itu pencapaian Tun Dr. Mahathir."},{"text":"Pelan Integriti Nasional membantu rakyat selepas PKP.","isCorrect":false,"consequence":"Itu bantuan zaman Muhyiddin semasa COVID-19."},{"text":"Pelan Integriti Nasional membasmi kemiskinan melalui DEB.","isCorrect":false,"consequence":"DEB diperkenalkan oleh Tun Razak."}],"aftermath":"Nota tersalah baca dan murid menulis PIN ialah projek bangunan. Cikgu menggeleng.","turns":[{"after":3,"options":[{"text":"Pembangunan perlu seimbang antara ekonomi dan akhlak.","isCorrect":true,"reaction":"Betul. Cikgu tersenyum."},{"text":"Pembangunan hanya perlu ekonomi tanpa akhlak.","isCorrect":false,"reaction":"Itu bertentangan dengan Pelan Integriti Nasional."},{"text":"Pembangunan hanya perlu akhlak tanpa ekonomi.","isCorrect":false,"reaction":"Koridor Wilayah Ekonomi menjelaskan keperluan ekonomi juga."}],"clue":"Seimbang antara ekonomi dan akhlak."}]}'),
(716, 'e7_n2_s8', 'Biodata dan Pencapaian Dato\' Sri Najib', 'Padankan biodata dan pencapaian Dato\' Sri Najib dengan maklumat yang betul.', '4', 'Memahami PM ke-6: lahir 23 Julai 1953 di Kuala Lipis; St. John Institution; Universiti Nottingham (ekonomi industri); Menteri Besar Pahang; PM 3 Apr 2009-9 Mei 2018; Gagasan 1Malaysia dan GTP.', '{"pairs":[{"text":"Tempat lahir","pair":1},{"text":"Kuala Lipis, Pahang","pair":1},{"text":"Pelajaran tinggi","pair":2},{"text":"Universiti Nottingham dalam bidang ekonomi industri","pair":2},{"text":"Tempoh Perdana Menteri keenam","pair":3},{"text":"3 April 2009 hingga 9 Mei 2018","pair":3},{"text":"Gagasan 1Malaysia","pair":4},{"text":"Memperkukuh hubungan dan kerjasama antara kaum","pair":4},{"text":"Program Transformasi Kerajaan (GTP)","pair":5},{"text":"Menjadikan negara berpendapatan tinggi selaras dengan Wawasan 2020","pair":5}],"aftermath":"Biodata tersilap dan murid menukar tujuan 1Malaysia dengan program lain.","turns":[{"after":3,"options":[{"text":"Gagasan itu menekankan kerjasama antara kaum demi kesejahteraan negara.","isCorrect":true,"reaction":"Betul. Murid mencatat nota."},{"text":"Gagasan itu memisahkan kaum mengikut kawasan.","isCorrect":false,"reaction":"Itu bertentangan. Gagasan 1Malaysia memperkukuh hubungan antara kaum."},{"text":"Gagasan itu memberi keutamaan kepada satu kaum sahaja.","isCorrect":false,"reaction":"Motonya mendahulukan rakyat."}],"clue":"Memperkukuh hubungan antara kaum."}]}'),
(717, 'e7_n2_s9', 'Dua Pemimpin Zaman COVID-19', 'Padankan Muhyiddin dan Ismail Sabri dengan biodata dan sumbangan mereka.', '4', 'Memahami PM ke-8 dan ke-9: Muhyiddin (Muar; MTE; bantuan kewangan semasa PKP; 1 Mac 2020-16 Ogos 2021) dan Ismail Sabri (Temerloh; peguam; Keluarga Malaysia; mula 20 Ogos 2021).', '{"pairs":[{"text":"Tan Sri Muhyiddin Md Yassin","pair":1},{"text":"Dilahirkan di Muar, Johor; PM 1 Mac 2020 hingga 16 Ogos 2021","pair":1},{"text":"Majlis Tindakan Ekonomi (MTE)","pair":2},{"text":"Menggalakkan pertumbuhan sosioekonomi dan meningkatkan pelaburan","pair":2},{"text":"Dato\' Seri Ismail Sabri Yaakob","pair":3},{"text":"Dilahirkan di Temerloh, Pahang; PM mulai 20 Ogos 2021","pair":3},{"text":"Konsep Keluarga Malaysia","pair":4},{"text":"Meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia","pair":4}],"aftermath":"Padanan tersilap dan murid menukar sumbangan kedua-dua pemimpin. Cikgu menggeleng.","turns":[{"after":3,"options":[{"text":"Pemimpin prihatin membantu rakyat dan meraikan kepelbagaian.","isCorrect":true,"reaction":"Betul, cikgu."},{"text":"Pemimpin tidak perlu membantu rakyat semasa kecemasan.","isCorrect":false,"reaction":"Murid membantah. Bantuan semasa PKP membantu rakyat."},{"text":"Keluarga Malaysia hanya untuk satu agama.","isCorrect":false,"reaction":"Konsep itu meraikan pelbagai agama, bangsa, kaum dan usia."}],"clue":"Prihatin dan keterangkuman."}]}'),
(718, 'e7_n3_s1', 'Nota Bendahara dan Perdana Menteri', 'Baca nota dan tentukan perbandingan antara Bendahara dan Perdana Menteri.', '5', 'Memahami imbas kembali: pada zaman Kesultanan Melayu Melaka, Bendahara ialah Ketua Pembesar kerajaan; kini pentadbiran diketuai Perdana Menteri; jawatan PM diwujudkan selepas 31 Ogos 1957 dan kekal hingga kini.', '{"clueText":"Nota: Pada zaman Kesultanan Melayu Melaka, Bendahara merupakan Ketua Pembesar kerajaan. Pada masa ini, pentadbiran kerajaan diketuai oleh Perdana Menteri. Jawatan Perdana Menteri diwujudkan selepas Tanah Melayu mencapai kemerdekaan pada 31 Ogos 1957 dan kekal hingga hari ini.","options":[{"text":"Dahulu Bendahara mengetuai pembesar, kini Perdana Menteri mengetuai pentadbiran.","isCorrect":true},{"text":"Dahulu Perdana Menteri mengetuai pembesar, kini Bendahara mengetuai pentadbiran.","isCorrect":false,"consequence":"Susunan itu terbalik. Cikgu menggeleng."},{"text":"Kedua-dua jawatan diwujudkan pada 1957.","isCorrect":false,"consequence":"Jawatan Bendahara lebih tua daripada Perdana Menteri."},{"text":"Kedua-dua jawatan tidak berkaitan dengan pentadbiran.","isCorrect":false,"consequence":"Kedua-duanya mengetuai pentadbiran pada zaman masing-masing."}],"aftermath":"Nota tersalah baca dan album menyatakan Perdana Menteri wujud pada zaman Melaka.","turns":[{"after":1,"options":[{"text":"Kedua-dua jawatan mengetuai pentadbiran pada zaman masing-masing.","isCorrect":true,"reaction":"Betul. Cikgu tersenyum."},{"text":"Bendahara dan Perdana Menteri jawatan yang sama pada zaman yang sama.","isCorrect":false,"reaction":"Zaman mereka berbeza."},{"text":"Jawatan Perdana Menteri sudah dihapuskan.","isCorrect":false,"reaction":"Jawatan itu kekal hingga hari ini."}],"clue":"Jawatan kepala pentadbiran berubah mengikut zaman."}]}'),
(719, 'e7_n3_s2', 'Lima Perdana Menteri Terkini', 'Susun lima Perdana Menteri terkini mengikut tarikh mula berkhidmat.', '1', 'Menyusun kronologi: Abdullah (31 Okt 2003), Najib (3 Apr 2009), Mahathir kali kedua (10 Mei 2018), Muhyiddin (1 Mac 2020), Ismail Sabri (20 Ogos 2021).', '{"timelineItems":[{"id":1,"year":"31 Oktober 2003","text":"Tun Abdullah Ahmad Badawi menjadi Perdana Menteri kelima","why":"Beliau menggantikan Tun Dr. Mahathir."},{"id":2,"year":"3 April 2009","text":"Dato\' Sri Najib menjadi Perdana Menteri keenam","why":"Beliau menggantikan Tun Abdullah."},{"id":3,"year":"10 Mei 2018","text":"Tun Dr. Mahathir menjadi Perdana Menteri ketujuh kali kedua","why":"Beliau kembali selepas Najib."},{"id":4,"year":"1 Mac 2020","text":"Muhyiddin menjadi Perdana Menteri kelapan","why":"Beliau menggantikan Tun Dr. Mahathir."},{"id":5,"year":"20 Ogos 2021","text":"Dato\' Seri Ismail Sabri menjadi Perdana Menteri kesembilan","why":"Beliau menggantikan Muhyiddin."}],"aftermath":"Kad bercampur dan album menyatakan Najib menjadi Perdana Menteri selepas Muhyiddin.","turns":[{"after":2,"options":[{"text":"Sejak 1957 hingga 2021, negara kita mempunyai sembilan orang Perdana Menteri.","isCorrect":true,"reaction":"Betul. Album lengkap."},{"text":"Hanya lima orang Perdana Menteri sejak merdeka.","isCorrect":false,"reaction":"Itu salah. Kau baru menyusun lima daripada sembilan."},{"text":"Tun Dr. Mahathir hanya sekali menjadi Perdana Menteri.","isCorrect":false,"reaction":"Murid menyemak dan mendapati beliau dua kali."}],"clue":"Sembilan Perdana Menteri sejak 1957 hingga 2021."}]}'),
(720, 'e7_n3_s3', 'Nota Pencapaian Tunku', 'Baca nota dan tentukan dua pencapaian Tunku.', '5', 'Memahami pencapaian Tunku: memperjuangkan kemerdekaan secara rundingan dan merealisasikan pembentukan Malaysia pada 16 September 1963.', '{"clueText":"Nota: Tunku Abdul Rahman Putra Al-Haj memperjuangkan kemerdekaan negara secara rundingan. Beliau juga berjaya merealisasikan pembentukan Malaysia pada 16 September 1963.","options":[{"text":"Memperjuangkan kemerdekaan secara rundingan dan merealisasikan pembentukan Malaysia.","isCorrect":true},{"text":"Menubuhkan MAGERAN dan memperkenalkan DEB.","isCorrect":false,"consequence":"Itu pencapaian Tun Razak."},{"text":"Membina Putrajaya dan KLIA.","isCorrect":false,"consequence":"Itu pencapaian Tun Dr. Mahathir."},{"text":"Memperkenalkan Program Transformasi Kerajaan.","isCorrect":false,"consequence":"Itu program Dato\' Sri Najib."}],"aftermath":"Nota tersalah baca dan album menyatakan Tunku menubuhkan MAGERAN.","turns":[{"after":2,"options":[{"text":"Pemimpin yang berunding membawa negara kepada kemerdekaan secara aman.","isCorrect":true,"reaction":"Betul. Itu contoh kepimpinan berwibawa."},{"text":"Kemerdekaan dicapai dengan peperangan.","isCorrect":false,"reaction":"Nota menyatakan kemerdekaan diperjuangkan secara rundingan."},{"text":"Malaysia dibentuk pada 31 Ogos 1957.","isCorrect":false,"reaction":"Tarikh itu hari kemerdekaan. Malaysia dibentuk pada 16 September 1963."}],"clue":"Rundingan dan pembentukan Malaysia."}]}'),
(721, 'e7_n3_s4', 'Jadual Pencapaian Pemimpin', 'Padankan pemimpin dengan pencapaian utama mereka.', '4', 'Merumus pencapaian: Tunku (kemerdekaan secara rundingan), Razak (DEB), Hussein (Amanah Saham Nasional Berhad), Mahathir (Wawasan 2020), Abdullah (PIN), Najib (GTP).', '{"pairs":[{"text":"Tunku Abdul Rahman","pair":1},{"text":"Memperjuangkan kemerdekaan secara rundingan","pair":1},{"text":"Tun Abdul Razak","pair":2},{"text":"Memperkenalkan Dasar Ekonomi Baru (DEB)","pair":2},{"text":"Tun Hussein Onn","pair":3},{"text":"Memperkenalkan Amanah Saham Nasional Berhad","pair":3},{"text":"Tun Dr. Mahathir","pair":4},{"text":"Merealisasikan Wawasan 2020 melalui Putrajaya, KLIA dan KLCC","pair":4},{"text":"Tun Abdullah","pair":5},{"text":"Memperkenalkan Pelan Integriti Nasional (PIN)","pair":5},{"text":"Dato\' Sri Najib","pair":6},{"text":"Melancarkan Program Transformasi Kerajaan (GTP)","pair":6}],"aftermath":"Padanan tersilap dan jadual memberi jasa Tun Razak kepada Tun Hussein. Cikgu memotong markah.","turns":[{"after":1,"options":[{"text":"Setiap pencapaian membawa kemajuan dan kesejahteraan kepada rakyat.","isCorrect":true,"reaction":"Betul. Jadual dilengkapkan."},{"text":"Pencapaian itu hanya berguna kepada pemimpin sendiri.","isCorrect":false,"reaction":"Cikgu menggeleng. Pencapaian itu demi kesejahteraan rakyat."},{"text":"Pencapaian tidak perlu dikenang.","isCorrect":false,"reaction":"Murid terdiam. Jasa pemimpin wajar dihargai."}],"clue":"Pencapaian demi rakyat."}]}'),
(722, 'e7_n3_s5', 'Kad Kepentingan Pemimpin Berwibawa', 'Baca kad dan tentukan kepentingan pemimpin yang memiliki ciri kepimpinan berwibawa.', '5', 'Memahami kepentingan pemimpin berwibawa: memajukan sistem ekonomi, menjamin keselamatan negara, membentuk kerajaan yang tersusun, menimbulkan rasa hormat, mewujudkan negara yang membangun, memudahkan pelaksanaan dasar.', '{"clueText":"Kad: Pemimpin yang berwibawa memajukan sistem ekonomi negara, menjamin keselamatan negara, membentuk kerajaan yang tersusun, menimbulkan rasa hormat antara pemimpin, mewujudkan negara yang membangun dan memudahkan pelaksanaan dasar-dasar pembangunan negara.","options":[{"text":"Memajukan ekonomi, menjamin keselamatan dan membentuk kerajaan tersusun.","isCorrect":true},{"text":"Memecahkan perpaduan dan melemahkan keselamatan.","isCorrect":false,"consequence":"Itu bertentangan dengan kad."},{"text":"Menyukarkan pelaksanaan dasar-dasar pembangunan.","isCorrect":false,"consequence":"Kad menyatakan sebaliknya."},{"text":"Menimbulkan rasa curiga antara pemimpin.","isCorrect":false,"consequence":"Kad menyebut menimbulkan rasa hormat."}],"aftermath":"Kad tersalah baca dan album menulis pemimpin berwibawa melemahkan keselamatan.","turns":[{"after":1,"options":[{"text":"Pemimpin berwibawa melahirkan negara yang maju dan selamat.","isCorrect":true,"reaction":"Betul. Murid menulis dalam album."},{"text":"Pemimpin tidak perlu berwibawa asalkan terkenal.","isCorrect":false,"reaction":"Cikgu menggeleng. Kewibawaan penting untuk pentadbiran."},{"text":"Pemimpin berwibawa hanya untuk menghias ucapan.","isCorrect":false,"reaction":"Kad menunjukkan ia memberi manfaat nyata."}],"clue":"Berwibawa untuk negara maju."}]}'),
(723, 'e7_n3_s6', 'Kad Cara Menghargai Pemimpin', 'Baca kad dan tentukan cara menunjukkan penghargaan kepada Perdana Menteri.', '5', 'Memahami cara menghargai pemimpin: mengeratkan perpaduan antara kaum, mengekalkan taat setia terhadap pemimpin, menjaga nama baik negara, menjaga keamanan negara.', '{"clueText":"Kad: Kita boleh menunjukkan penghargaan kepada Perdana Menteri dengan mengeratkan perpaduan antara kaum, mengekalkan taat setia terhadap pemimpin, menjaga nama baik negara dan menjaga keamanan negara.","options":[{"text":"Mengeratkan perpaduan antara kaum dan menjaga nama baik negara.","isCorrect":true},{"text":"Memecahkan perpaduan antara kaum.","isCorrect":false,"consequence":"Itu bertentangan dengan kad."},{"text":"Mencemarkan nama baik negara.","isCorrect":false,"consequence":"Itu menjatuhkan maruah negara."},{"text":"Mengabaikan keamanan negara.","isCorrect":false,"consequence":"Kad menyatakan kita menjaga keamanan."}],"aftermath":"Kad tersalah baca dan murid menulis cara yang tidak menghargai pemimpin.","turns":[{"after":1,"options":[{"text":"Kita menghormati pemimpin dengan menjaga perpaduan dan keamanan negara.","isCorrect":true,"reaction":"Betul. Itulah tanda penghargaan."},{"text":"Kita menghormati pemimpin dengan menyebarkan fitnah.","isCorrect":false,"reaction":"Fitnah memecahkan perpaduan dan mencemarkan nama baik negara."},{"text":"Kita tidak perlu menghargai pemimpin.","isCorrect":false,"reaction":"Jasa pemimpin wajar dihargai demi kesejahteraan negara."}],"clue":"Hargai dengan perpaduan dan keamanan."}]}'),
(724, 'e7_n3_s7', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan faedah menyokong pemimpin.', '4', 'Memahami cinta akan negara: diri menghormati pemimpin; masyarakat yang menyokong pemimpin berwibawa menjadi bertanggungjawab kepada negara; sikap bertanggungjawab memastikan kedaulatan negara kekal terpelihara.', '{"pairs":[{"text":"Diri","pair":1},{"text":"Kita perlu menghormati pemimpin negara","pair":1},{"text":"Masyarakat","pair":2},{"text":"Sokongan kepada pemimpin berwibawa melahirkan masyarakat bertanggungjawab","pair":2},{"text":"Negara","pair":3},{"text":"Sikap bertanggungjawab memastikan kedaulatan negara terpelihara","pair":3}],"aftermath":"Padanan tersilap dan album menyatakan hormat pemimpin hanya urusan negara. Cikgu membetulkan.","turns":[{"after":1,"options":[{"text":"Sokongan kepada pemimpin menjamin keamanan, kestabilan dan pembangunan negara.","isCorrect":true,"reaction":"Betul. Album selesai."},{"text":"Sokongan kepada pemimpin menyebabkan kekacauan.","isCorrect":false,"reaction":"Sokongan menjamin keamanan dan keharmonian."},{"text":"Sokongan kepada pemimpin tidak perlu kerana tidak membawa kesan.","isCorrect":false,"reaction":"Kestabilan politik dan ekonomi bergantung pada sokongan rakyat."}],"clue":"Sokongan menjamin kestabilan."}]}'),
(725, 'e7_n3_s8', 'Nota Nilai Teras Sivik', 'Baca nota dan tentukan dua nilai teras sivik dalam unit Pemimpin Negara.', '5', 'Memahami nilai teras sivik Unit 7: bertanggungjawab dan hormat-menghormati.', '{"clueText":"Nota: Unit ini mengajar kita menghargai jasa pemimpin yang memajukan negara. Kita perlu menghormati pemimpin dan bersikap bertanggungjawab terhadap negara supaya kedaulatan negara dan perpaduan rakyat kekal terpelihara.","options":[{"text":"Bertanggungjawab dan hormat-menghormati.","isCorrect":true},{"text":"Bersaing dan berebut kuasa.","isCorrect":false,"consequence":"Nota tidak menyebut nilai itu."},{"text":"Menyindir dan memperlekeh pemimpin.","isCorrect":false,"consequence":"Itu bertentangan dengan hormat-menghormati."},{"text":"Mementingkan diri sendiri.","isCorrect":false,"consequence":"Itu bertentangan dengan bertanggungjawab."}],"aftermath":"Nota tersalah baca dan album mencatat nilai yang bertentangan dengan unit ini.","turns":[{"after":1,"options":[{"text":"Hormati pemimpin dan bertanggungjawab terhadap negara.","isCorrect":true,"reaction":"Betul. Album kau layak mendapat markah penuh."},{"text":"Hormat pemimpin hanya apabila mereka ada di hadapan kita.","isCorrect":false,"reaction":"Cikgu menggeleng. Hormat berterusan."},{"text":"Tanggungjawab hanya untuk orang dewasa.","isCorrect":false,"reaction":"Cikgu menegur. Setiap warganegara bertanggungjawab."}],"clue":"Hormat dan bertanggungjawab."}]}'),
(801, 'e8_n1_s1', 'Cari Bukti Ekonomi Tradisional', 'Cari empat bukti ekonomi tradisional dalam sektor pertanian.', '2', 'Mengenal pasti ciri ekonomi tradisional: skala kecil, peralatan mudah (cangkul, sabit), modal kecil, tenaga kerja sedikit, untuk keperluan sendiri dan keluarga.', '{"bgImage":"../assets/gameAsset/background/ekonomi_tradisional.png","hotspots":[{"name":"Cangkul di tepi petak: peralatan mudah ekonomi tradisional","top":"78%","left":"13.7%"},{"name":"Cangkul kedua di tepi pagar: modal kecil dan alat sederhana","top":"75%","left":"86%"},{"name":"Rumah kayu petani: hasil untuk keperluan sendiri dan keluarga","top":"20.8%","left":"22.4%"},{"name":"Petak sawah kecil: dijalankan secara kecil-kecilan","top":"39.3%","left":"59.9%"}],"aftermath":"Bukti tidak ditemui dan Pak Tani menyangka kau mengejek caranya.","turns":[{"after":2,"options":[{"text":"Cara ini sesuai untuk keperluan sendiri dan keluarga.","isCorrect":true,"reaction":"Betul. Itulah maksud ekonomi tradisional."},{"text":"Cara ini hanya untuk dijual ke luar negara.","isCorrect":false,"reaction":"Pak Tani membetulkan. Hasilnya untuk keluarga sendiri."},{"text":"Cara ini memerlukan modal yang sangat besar.","isCorrect":false,"reaction":"Gambar menunjukkan alat mudah dan modal kecil."}],"clue":"Tradisional: kecil dan untuk keluarga."}]}'),
(802, 'e8_n1_s2', 'Tradisional dan Komersial', 'Padankan ciri dengan jenis ekonominya.', '4', 'Membezakan ekonomi tradisional (kecil-kecilan, alat mudah, modal kecil, keperluan sendiri) dengan komersial (perladangan, mesin dan jentera, modal besar, tenaga buruh banyak, tempatan dan eksport).', '{"pairs":[{"text":"Ekonomi tradisional: skala usaha","pair":1},{"text":"Diusahakan secara kecil-kecilan","pair":1},{"text":"Ekonomi tradisional: tujuan","pair":2},{"text":"Untuk keperluan sendiri dan keluarga","pair":2},{"text":"Ekonomi komersial: skala usaha","pair":3},{"text":"Diusahakan secara perladangan","pair":3},{"text":"Ekonomi komersial: peralatan","pair":4},{"text":"Mesin dan jentera penuai","pair":4},{"text":"Ekonomi komersial: modal dan tenaga kerja","pair":5},{"text":"Modal besar dan tenaga buruh yang banyak","pair":5},{"text":"Ekonomi komersial: tujuan","pair":6},{"text":"Kegunaan tempatan dan eksport","pair":6}],"aftermath":"Ciri bertukar dan Pak Tani menyangka mesin hanya boleh dibeli oleh orang kaya. Dia pulang kecewa.","turns":[{"after":1,"options":[{"text":"Cara berubah mengikut zaman, tetapi kedua-duanya menyumbang kepada negara.","isCorrect":true,"reaction":"Betul. Pak Tani mengangguk."},{"text":"Cara tradisional salah dan mesti dihapuskan.","isCorrect":false,"reaction":"Pak Tani terguris kerana cara itu memberi makan keluarganya."},{"text":"Cara komersial tidak memberi manfaat kepada negara.","isCorrect":false,"reaction":"Petani Moden membantah kerana ia menyumbang kepada pendapatan negara."}],"clue":"Kedua-duanya menyumbang kepada negara."}]}'),
(803, 'e8_n1_s3', 'Nota Perlombongan', 'Baca nota dan tentukan kaedah perlombongan tradisional.', '5', 'Memahami perlombongan: tradisional menggunakan kaedah mendulang; komersial menggunakan kapal korek (lombong emas Sungai Lebir, Kelantan); ekonomi komersial menggalakkan pembukaan bandar di kawasan perlombongan.', '{"clueText":"Nota: Aktiviti melombong secara tradisional menggunakan kaedah mendulang. Aktiviti perlombongan secara komersial pula menggunakan jentera seperti kapal korek, contohnya di lombong emas Sungai Lebir, Kelantan. Pengenalan ekonomi komersial menggalakkan pembukaan bandar-bandar di kawasan perlombongan.","options":[{"text":"Tradisional: mendulang. Komersial: kapal korek.","isCorrect":true},{"text":"Tradisional: kapal korek. Komersial: mendulang.","isCorrect":false,"consequence":"Kedua-duanya terbalik. Nota menyebut sebaliknya."},{"text":"Kedua-duanya menggunakan kapal korek.","isCorrect":false,"consequence":"Mendulang ialah kaedah tradisional."},{"text":"Kedua-duanya menggunakan mendulang.","isCorrect":false,"consequence":"Kapal korek digunakan dalam perlombongan komersial."}],"aftermath":"Nota tersalah baca dan buku catatan menyatakan mendulang kaedah moden. Pembaca keliru.","turns":[{"after":2,"options":[{"text":"Ekonomi komersial membawa kemajuan dan menggalakkan pembukaan bandar.","isCorrect":true,"reaction":"Betul. Itulah perubahan yang baik."},{"text":"Ekonomi komersial menutup semua bandar.","isCorrect":false,"reaction":"Nota menyebut sebaliknya. Bandar dibuka di kawasan perlombongan."},{"text":"Kapal korek hanya digunakan oleh penduduk kampung untuk mandi.","isCorrect":false,"reaction":"Kapal korek digunakan untuk melombong."}],"clue":"Komersial menggalakkan pembukaan bandar."}]}'),
(804, 'e8_n1_s4', 'Nota Getah dan Sawit', 'Baca nota dan tentukan tempoh industri getah dan kelapa sawit bermula.', '5', 'Memahami bahawa industri getah dan kelapa sawit bermula sejak awal abad ke-20 dan merupakan sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.', '{"clueText":"Nota: Industri getah dan kelapa sawit yang bermula sejak awal abad ke-20 merupakan sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.","options":[{"text":"Sejak awal abad ke-20.","isCorrect":true},{"text":"Sejak zaman Kesultanan Melayu Melaka.","isCorrect":false,"consequence":"Nota menyebut awal abad ke-20."},{"text":"Selepas tahun 1990.","isCorrect":false,"consequence":"Nota menyebut awal abad ke-20."},{"text":"Sejak tahun 1957.","isCorrect":false,"consequence":"Nota menyebut awal abad ke-20, bukan 1957."}],"aftermath":"Nota tersalah baca dan penoreh menyangka sawit bermula selepas merdeka.","turns":[{"after":1,"options":[{"text":"Industri itu merangsang kemajuan ekonomi negara sejak lama.","isCorrect":true,"reaction":"Betul. Itulah asas perladangan kita."},{"text":"Industri itu baru bermula dan tidak penting.","isCorrect":false,"reaction":"Penoreh membantah. Ia menyumbang sejak awal abad ke-20."},{"text":"Industri itu tidak berkaitan dengan ekonomi.","isCorrect":false,"reaction":"Penoreh menggeleng kerana ia merangsang kemajuan ekonomi."}],"clue":"Getah dan sawit: pemacu lama."}]}'),
(805, 'e8_n1_s5', 'Lima Manfaat Getah dan Sawit', 'Padankan manfaat industri getah dan kelapa sawit dengan penerangannya.', '4', 'Memahami lima sumbangan: meningkatkan pendapatan negara, menyediakan peluang pekerjaan, mewujudkan industri hiliran, memajukan industri asas tani, membangunkan industri biodiesel.', '{"pairs":[{"text":"Meningkatkan pendapatan negara","pair":1},{"text":"Hasil getah dan sawit dieksport, seperti sarung tangan dan minyak","pair":1},{"text":"Menyediakan peluang pekerjaan","pair":2},{"text":"Perladangan memerlukan tenaga kerja yang banyak","pair":2},{"text":"Mewujudkan industri hiliran","pair":3},{"text":"Contohnya pembuatan perabot daripada kayu getah","pair":3},{"text":"Memajukan industri asas tani","pair":4},{"text":"Meningkatkan pengeluaran bahan makanan tempatan","pair":4},{"text":"Membangunkan industri biodiesel","pair":5},{"text":"Sawit diproses menjadi biodiesel, minyak dan sabun","pair":5}],"aftermath":"Kad bertukar dan kilang menyatakan getah tidak memberi peluang pekerjaan. Penoreh terkilan.","turns":[{"after":1,"options":[{"text":"Industri itu memberi pekerjaan dan menjana pendapatan kepada rakyat.","isCorrect":true,"reaction":"Betul. Kerja kau berfaedah."},{"text":"Industri itu hanya memberi keuntungan kepada pemilik ladang.","isCorrect":false,"reaction":"Penduduk membantah kerana banyak peluang pekerjaan disediakan."},{"text":"Industri itu tidak menghasilkan produk selain getah.","isCorrect":false,"reaction":"Sawit menghasilkan minyak, sabun dan biodiesel."}],"clue":"Industri memberi kerja dan pendapatan."}]}'),
(806, 'e8_n1_s6', 'Nota Hiliran dan Biodiesel', 'Baca nota dan tentukan maksud industri hiliran.', '5', 'Memahami industri hiliran: kegiatan yang berkembang daripada kegiatan ekonomi utama, contohnya pembuatan perabot daripada kayu getah; biodiesel: bahan buangan organik yang digunakan sebagai bahan api.', '{"clueText":"Nota: Industri hiliran bermaksud kegiatan yang berkembang daripada kegiatan ekonomi utama. Contohnya, pembuatan perabot daripada kayu getah. Biodiesel pula bermaksud bahan buangan organik yang digunakan sebagai bahan api, dan industri kelapa sawit turut menghasilkan biodiesel sawit.","options":[{"text":"Kegiatan yang berkembang daripada kegiatan ekonomi utama.","isCorrect":true},{"text":"Kegiatan menanam padi secara kecil-kecilan.","isCorrect":false,"consequence":"Itu ciri ekonomi tradisional."},{"text":"Kegiatan menjual barangan melalui Internet.","isCorrect":false,"consequence":"Itu e-dagang."},{"text":"Kegiatan mendulang bijih timah di sungai.","isCorrect":false,"consequence":"Itu kaedah perlombongan tradisional."}],"aftermath":"Nota tersalah baca dan pelawat menyangka industri hiliran ialah kerja menanam. Pelawat pulang keliru.","turns":[{"after":1,"options":[{"text":"Industri hiliran menambah pendapatan negara menerusi pasaran tempatan dan antarabangsa.","isCorrect":true,"reaction":"Betul. Pelawat tersenyum."},{"text":"Industri hiliran hanya membazir kayu.","isCorrect":false,"reaction":"Industri hiliran menyumbang kepada pendapatan negara."},{"text":"Industri hiliran tiada kaitan dengan getah.","isCorrect":false,"reaction":"Perabot daripada kayu getah ialah contoh."}],"clue":"Hiliran menambah pendapatan negara."}]}'),
(807, 'e8_n1_s7', 'Hasil Eksport Getah dan Sawit', 'Padankan hasil eksport dengan industri sumbernya.', '4', 'Memahami hasil eksport: getah (sarung tangan, benang lateks); kelapa sawit (minyak mentah, minyak yang telah diproses, sabun).', '{"pairs":[{"text":"Sarung tangan","pair":1},{"text":"Barangan getah yang dieksport dan dipakai untuk melindungi tangan","pair":1},{"text":"Benang lateks","pair":2},{"text":"Hasil getah yang dieksport untuk membuat barangan kenyal","pair":2},{"text":"Minyak mentah sawit","pair":3},{"text":"Hasil kelapa sawit sebelum diproses","pair":3},{"text":"Minyak sawit diproses","pair":4},{"text":"Hasil kelapa sawit selepas diproses untuk dieksport","pair":4},{"text":"Sabun","pair":5},{"text":"Produk yang diproses daripada kelapa sawit","pair":5}],"aftermath":"Label tersilap dan kotak dihantar ke destinasi yang salah. Penghantar mengeluh.","turns":[{"after":1,"options":[{"text":"Hasil eksport meningkatkan pendapatan negara.","isCorrect":true,"reaction":"Betul. Kotak dihantar dengan tepat."},{"text":"Hasil eksport tidak memberi apa-apa kepada negara.","isCorrect":false,"reaction":"Penghantar menggeleng. Eksport meningkatkan pendapatan."},{"text":"Hasil eksport hanya untuk kegunaan keluarga petani.","isCorrect":false,"reaction":"Itu ciri ekonomi tradisional, bukan eksport."}],"clue":"Eksport meningkatkan pendapatan."}]}'),
(808, 'e8_n1_s8', 'Peringkat Perkembangan Ekonomi', 'Susun peringkat perkembangan ekonomi dan kegiatan pemacu kemajuan negara.', '1', 'Merumus perkembangan: ekonomi tradisional (pertanian dan perlombongan) -> ekonomi komersial -> industri getah dan kelapa sawit -> petroleum (1910) -> PETRONAS (1974) -> PROTON (1983).', '{"timelineItems":[{"id":1,"year":"Zaman awal","text":"Pertanian dan perlombongan tradisional diusahakan kecil-kecilan","why":"Kegiatan awal ekonomi negara."},{"id":2,"year":"Awal abad ke-20","text":"Industri getah dan kelapa sawit berkembang secara perladangan","why":"Ekonomi komersial menggalakkan perladangan."},{"id":3,"year":"1910","text":"Industri petroleum bermula di Miri, Sarawak","why":"Telaga pertama di Miri."},{"id":4,"year":"1974","text":"PETRONAS ditubuhkan dan dimiliki sepenuhnya oleh kerajaan","why":"Memajukan industri petroleum dan gas."},{"id":5,"year":"1983","text":"PROTON ditubuhkan di Shah Alam, Selangor","why":"Industri automotif negara bermula."}],"aftermath":"Susunan tersalah dan ringkasan menyatakan PROTON mendahului getah. Pengurus ladang menggeleng.","turns":[{"after":1,"options":[{"text":"Kemajuan ekonomi bermula daripada pertanian dan berkembang ke pelbagai sektor.","isCorrect":true,"reaction":"Betul. Pengurus mengangguk."},{"text":"Ekonomi negara sentiasa bergantung pada getah sahaja.","isCorrect":false,"reaction":"Pengurus membetulkan. Banyak industri baharu muncul."},{"text":"Ekonomi negara tidak pernah berubah.","isCorrect":false,"reaction":"Ekonomi berkembang daripada tradisional ke komersial."}],"clue":"Ekonomi berkembang berperingkat."}]}'),
(809, 'e8_n2_s1', 'Nota Sejarah Petroleum', 'Baca nota dan tentukan permulaan industri petroleum dan penubuhan PETRONAS.', '5', 'Memahami petroleum: bermula tahun 1910 di Miri, Sarawak; PETRONAS ditubuhkan tahun 1974 dan dimiliki sepenuhnya oleh kerajaan Malaysia; telaga minyak pertama The Grand Old Lady, Miri.', '{"clueText":"Nota: Industri petroleum di negara kita bermula pada tahun 1910 di Miri, Sarawak. Petroliam Nasional Berhad (PETRONAS) yang dimiliki sepenuhnya oleh kerajaan Malaysia ditubuhkan pada tahun 1974. The Grand Old Lady, Miri merupakan telaga minyak yang pertama di negara kita.","options":[{"text":"Bermula 1910 di Miri dan PETRONAS ditubuhkan 1974.","isCorrect":true},{"text":"Bermula 1974 di Miri dan PETRONAS ditubuhkan 1910.","isCorrect":false,"consequence":"Tahun terbalik. Nota menyebut sebaliknya."},{"text":"Bermula 1983 di Shah Alam dan PETRONAS ditubuhkan 1985.","isCorrect":false,"consequence":"Itu tarikh industri automotif."},{"text":"Bermula 1957 di Kuala Lumpur dan PETRONAS ditubuhkan 1963.","isCorrect":false,"consequence":"Tarikh itu tidak betul."}],"aftermath":"Borang diluluskan dengan tarikh salah dan laporan petroleum memuatkan fakta cacat.","turns":[{"after":1,"options":[{"text":"Penubuhan PETRONAS memajukan industri petroleum dan gas negara.","isCorrect":true,"reaction":"Betul. Cop LULUS diberikan."},{"text":"PETRONAS dimiliki oleh syarikat luar negara.","isCorrect":false,"reaction":"Nota menyebut PETRONAS dimiliki sepenuhnya oleh kerajaan Malaysia."},{"text":"PETRONAS tiada kaitan dengan petroleum.","isCorrect":false,"reaction":"Jurutera menggeleng. PETRONAS memajukan industri itu."}],"clue":"PETRONAS dimiliki kerajaan."}]}'),
(810, 'e8_n2_s2', 'Sumbangan Industri Petroleum', 'Padankan sumbangan industri petroleum dan gas dengan penerangannya.', '4', 'Memahami sumbangan petroleum: peluang pekerjaan (pelantar minyak), melahirkan usahawan (stesen minyak), penaja sukan permotoran (Grand Prix), biasiswa (Universiti Teknologi PETRONAS), pulangan pendapatan tinggi.', '{"pairs":[{"text":"Peluang pekerjaan","pair":1},{"text":"Pekerja di pelantar minyak dan pusat pemprosesan","pair":1},{"text":"Melahirkan usahawan","pair":2},{"text":"Pembukaan stesen minyak","pair":2},{"text":"Penaja utama sukan permotoran","pair":3},{"text":"Grand Prix Malaysia meningkatkan pendapatan negara","pair":3},{"text":"Biasiswa pelajaran","pair":4},{"text":"Melanjutkan pelajaran ke Universiti Teknologi PETRONAS","pair":4},{"text":"Pulangan pendapatan tinggi","pair":5},{"text":"Hasil daripada permintaan tinggi dunia terhadap petroleum","pair":5}],"aftermath":"Kad bertukar dan laporan menyatakan petroleum tidak melahirkan usahawan. Jurutera menegur.","turns":[{"after":1,"options":[{"text":"Industri petroleum penting dan wajar dibanggakan.","isCorrect":true,"reaction":"Betul. Cop LULUS diberikan."},{"text":"Industri petroleum tidak penting kepada negara.","isCorrect":false,"reaction":"Jurutera membantah. Ia penjana kemajuan ekonomi."},{"text":"Industri petroleum hanya memberi kerja kepada orang asing.","isCorrect":false,"reaction":"Penduduk tempatan menikmati peluang pekerjaan."}],"clue":"Petroleum penjana ekonomi."}]}'),
(811, 'e8_n2_s3', 'Nota Penajaan Sukan Permotoran', 'Baca nota dan tentukan sebab PETRONAS menaja sukan permotoran.', '5', 'Memahami bahawa PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia dan penganjuran sukan ini meningkatkan pendapatan negara.', '{"clueText":"Nota: PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia. Penganjuran sukan ini meningkatkan pendapatan negara.","options":[{"text":"Penganjuran sukan permotoran meningkatkan pendapatan negara.","isCorrect":true},{"text":"Sukan permotoran menggantikan industri petroleum.","isCorrect":false,"consequence":"Nota tidak menyatakan begitu."},{"text":"Sukan permotoran dianjurkan untuk menutup pelantar minyak.","isCorrect":false,"consequence":"Tiada maklumat itu dalam nota."},{"text":"Sukan permotoran hanya hiburan tanpa sebarang kesan.","isCorrect":false,"consequence":"Nota menyatakan ia meningkatkan pendapatan negara."}],"aftermath":"Nota tersalah baca dan wartawan menulis penajaan itu membazir wang.","turns":[{"after":1,"options":[{"text":"Penajaan sukan memberi manfaat kepada negara dan rakyat.","isCorrect":true,"reaction":"Betul. Wartawan menulis laporan baharu."},{"text":"Penajaan sukan hanya membazir wang.","isCorrect":false,"reaction":"Nota menyatakan ia meningkatkan pendapatan negara."},{"text":"Penajaan sukan tiada kaitan dengan pendapatan.","isCorrect":false,"reaction":"Penganjuran sukan meningkatkan pendapatan negara."}],"clue":"Sukan menambah pendapatan."}]}'),
(812, 'e8_n2_s4', 'Garis Masa Industri Automotif', 'Susun peristiwa penting industri automotif mengikut urutan.', '1', 'Menyusun kronologi: PROTON 1983, Proton Saga Julai 1985, PERODUA 1993, Kancil 1994, kilang kedua PROTON di Tanjung Malim 2005, kerjasama Geely 2018.', '{"timelineItems":[{"id":1,"year":"1983","text":"PROTON ditubuhkan di Shah Alam, Selangor","why":"Kilang pembuatan kereta nasional yang pertama."},{"id":2,"year":"Julai 1985","text":"Proton Saga dilancarkan sebagai model kereta pertama negara","why":"Menjadi pengeluar kereta pertama di Malaysia."},{"id":3,"year":"1993","text":"PERODUA ditubuhkan","why":"Perusahaan Otomobil Kedua Sdn. Bhd."},{"id":4,"year":"1994","text":"Model pertama PERODUA, Kancil, dikeluarkan","why":"Selepas PERODUA ditubuhkan."},{"id":5,"year":"2005","text":"Kilang kedua PROTON dibina di Tanjung Malim, Perak","why":"Kilang kedua selepas Shah Alam."},{"id":6,"year":"2018","text":"PROTON menjalin usaha sama dengan Geely Holding Group","why":"Untuk mengeluarkan model baharu."}],"aftermath":"Susunan tersilap dan laporan menyatakan Kancil dikeluarkan sebelum PERODUA ditubuhkan.","turns":[{"after":1,"options":[{"text":"Pencapaian ini membanggakan negara.","isCorrect":true,"reaction":"Betul. Kilang menyambut laporan itu."},{"text":"Industri automotif tiada kesan kepada ekonomi.","isCorrect":false,"reaction":"Penyelia menggeleng. Pendapatan negara tidak lagi bergantung pada pertanian sahaja."},{"text":"Semua kereta di Malaysia diimport sepenuhnya.","isCorrect":false,"reaction":"PROTON dan PERODUA ialah pengeluar tempatan."}],"clue":"Automotif membanggakan negara."}]}'),
(813, 'e8_n2_s5', 'PROTON dan PERODUA', 'Padankan syarikat automotif dengan butirannya.', '4', 'Memahami PROTON (Shah Alam 1983; Saga Julai 1985; kilang kedua Tanjung Malim 2005; Geely 2018) dan PERODUA (1993; Kancil 1994; Nippa dieksport ke United Kingdom).', '{"pairs":[{"text":"PROTON ditubuhkan","pair":1},{"text":"Kilang pertama di Shah Alam pada tahun 1983","pair":1},{"text":"Proton Saga","pair":2},{"text":"Model kereta pertama negara pada Julai 1985","pair":2},{"text":"Kilang kedua PROTON","pair":3},{"text":"Tanjung Malim, Perak pada tahun 2005","pair":3},{"text":"PERODUA ditubuhkan","pair":4},{"text":"Tahun 1993","pair":4},{"text":"Kancil","pair":5},{"text":"Model pertama PERODUA pada tahun 1994","pair":5},{"text":"Nippa","pair":6},{"text":"Produk PERODUA yang dieksport ke United Kingdom","pair":6}],"aftermath":"Butiran bertukar dan pengunjung mencatat Kancil sebagai model PROTON.","turns":[{"after":1,"options":[{"text":"Industri ini mendorong perkembangan industri berat dan teknologi.","isCorrect":true,"reaction":"Betul. Pengunjung terkesan."},{"text":"Industri ini menyebabkan pendapatan negara menurun.","isCorrect":false,"reaction":"Industri automotif meningkatkan ekonomi negara."},{"text":"Industri ini menghentikan kemajuan teknologi.","isCorrect":false,"reaction":"Ia mendorong perkembangan industri berat dan teknologi."}],"clue":"Automotif mendorong teknologi."}]}'),
(814, 'e8_n2_s6', 'Cari Bukti Alam Semula Jadi', 'Cari empat bukti keindahan alam semula jadi yang menarik pelancong.', '2', 'Memahami keistimewaan Malaysia: keindahan alam semula jadi (flora, fauna, pulau, laut, tanah tinggi) menarik pelancong dan Kempen Tahun Melawat Malaysia sejak tahun 1990.', '{"bgImage":"../assets/gameAsset/background/industri_pelancongan.png","hotspots":[{"name":"Air terjun hutan: alam semula jadi memacu Tahun Melawat Malaysia","top":"28.3%","left":"27.7%"},{"name":"Pelancong di jambatan gantung: tarikan alam semula jadi","top":"24%","left":"5%"},{"name":"Gua batu kapur: tapak semula jadi yang menarik pelancong","top":"64.6%","left":"30.1%"},{"name":"Pelancong bergambar di pantai: Tahun Melawat Malaysia","top":"67.8%","left":"72.8%"}],"aftermath":"Bukti tidak ditemui dan promosi pelancongan gagal menunjukkan daya tarikan negara.","turns":[{"after":1,"options":[{"text":"Alam semula jadi perlu dipelihara supaya terus menarik pelancong.","isCorrect":true,"reaction":"Betul. Pelancong gembira."},{"text":"Alam semula jadi boleh dirosakkan kerana pelancong tetap datang.","isCorrect":false,"reaction":"Itu merugikan industri pelancongan."},{"text":"Alam semula jadi tidak menarik pelancong.","isCorrect":false,"reaction":"Bukti dalam gambar menunjukkan sebaliknya."}],"clue":"Pelihara alam sebagai tarikan."}]}'),
(815, 'e8_n2_s7', 'Keistimewaan Pelancongan Malaysia', 'Padankan keistimewaan pelancongan dengan penerangannya.', '4', 'Memahami keistimewaan pelancongan: tapak dan bangunan bersejarah, keindahan alam semula jadi, keharmonian masyarakat dan keunikan budaya, agropelancongan (inap desa), penganjuran sukan, muzik dan pameran antarabangsa.', '{"pairs":[{"text":"Tapak dan bangunan bersejarah","pair":1},{"text":"Kota A Famosa, Candi Bukit Batu Pahat dan Istana Kenangan","pair":1},{"text":"Keindahan alam semula jadi","pair":2},{"text":"Gunung Kinabalu, Pulau Langkawi dan Gua Niah","pair":2},{"text":"Keharmonian dan keunikan budaya","pair":3},{"text":"Hidup pelbagai kaum menjamin keselamatan dan menarik pelancong","pair":3},{"text":"Agropelancongan","pair":4},{"text":"Konsep inap desa bersama keluarga penduduk tempatan","pair":4},{"text":"Sukan, muzik dan pameran antarabangsa","pair":5},{"text":"Formula One, Le Tour de Langkawi, Festival Muzik Hutan Hujan dan LIMA","pair":5}],"aftermath":"Kad bertukar dan pegawai membentangkan keistimewaan yang salah dalam mesyuarat.","turns":[{"after":1,"options":[{"text":"Keharmonian masyarakat juga menjadi tarikan pelancong.","isCorrect":true,"reaction":"Betul. Pegawai mencatat idea itu."},{"text":"Keharmonian tidak mempengaruhi pelancong.","isCorrect":false,"reaction":"Pegawai membetulkan. Keharmonian menjamin keselamatan pelancong."},{"text":"Hanya bangunan lama yang menarik pelancong.","isCorrect":false,"reaction":"Alam dan budaya juga menarik pelancong."}],"clue":"Keharmonian menarik pelancong."}]}'),
(816, 'e8_n2_s8', 'Acara Antarabangsa di Malaysia', 'Padankan acara antarabangsa dengan tempat atau cirinya.', '4', 'Memahami acara: Formula One di Sepang; Le Tour de Langkawi; Festival Muzik Hutan Hujan Sedunia di Sarawak; LIMA (pameran maritim dan aeroangkasa) di Pulau Langkawi setiap dua tahun.', '{"pairs":[{"text":"Perlumbaan Formula One","pair":1},{"text":"Dianjurkan di Sepang","pair":1},{"text":"Le Tour de Langkawi","pair":2},{"text":"Perlumbaan basikal antarabangsa","pair":2},{"text":"Festival Muzik Hutan Hujan Sedunia","pair":3},{"text":"Dianjurkan di Sarawak","pair":3},{"text":"LIMA","pair":4},{"text":"Pameran maritim dan aeroangkasa di Pulau Langkawi setiap dua tahun","pair":4}],"aftermath":"Peristiwa bertukar tempat dan senarai acara tersalah dicetak. Pegawai terpaksa mencetak semula.","turns":[{"after":1,"options":[{"text":"Acara antarabangsa menarik pelancong dan meningkatkan pendapatan negara.","isCorrect":true,"reaction":"Betul. Pelancong gembira."},{"text":"Acara antarabangsa hanya menyusahkan penduduk.","isCorrect":false,"reaction":"Pegawai menggeleng. Acara itu mempromosikan negara."},{"text":"Acara antarabangsa tiada kesan kepada ekonomi.","isCorrect":false,"reaction":"Ia menarik pelancong dan menambah pendapatan."}],"clue":"Acara menarik pelancong."}]}'),
(817, 'e8_n3_s1', 'Nota Kempen Beli Barangan Buatan Malaysia', 'Baca nota dan tentukan tahun kempen dilancarkan serta contoh barangan.', '5', 'Memahami bahawa Kempen \'Beli Barangan Buatan Malaysia\' dilancarkan pada tahun 1985; contoh: perabot, barangan elektrik dan elektronik, produk makanan.', '{"clueText":"Nota: Kempen \'Beli Barangan Buatan Malaysia\' dilancarkan pada tahun 1985. Antara barangan buatan Malaysia termasuklah perabot, barangan elektrik dan elektronik serta produk makanan.","options":[{"text":"Tahun 1985; contohnya perabot, elektrik dan elektronik, makanan.","isCorrect":true},{"text":"Tahun 1957; contohnya hanya bijih timah.","isCorrect":false,"consequence":"Tahun 1957 ialah tahun kemerdekaan. Nota menyebut 1985."},{"text":"Tahun 1990; contohnya hanya kereta.","isCorrect":false,"consequence":"Tahun 1990 ialah Kempen Tahun Melawat Malaysia."},{"text":"Tahun 1974; contohnya hanya minyak petrol.","isCorrect":false,"consequence":"Tahun 1974 ialah penubuhan PETRONAS."}],"aftermath":"Nota tersalah baca dan poster di kedai menulis tahun yang salah. Pelanggan menegur.","turns":[{"after":1,"options":[{"text":"Membeli barangan tempatan menyokong ekonomi negara.","isCorrect":true,"reaction":"Betul. Pelanggan membeli sebakul barangan."},{"text":"Barangan buatan Malaysia kurang bermutu.","isCorrect":false,"reaction":"Pelanggan terkilan. Kualiti telah mencapai tahap kegunaan tempatan dan antarabangsa."},{"text":"Barangan Malaysia hanya untuk pelancong.","isCorrect":false,"reaction":"Ia untuk kegunaan tempatan dan antarabangsa."}],"clue":"Beli barangan buatan Malaysia."}]}'),
(818, 'e8_n3_s2', 'Rak Barangan Buatan Malaysia', 'Padankan produk dengan kategori industrinya.', '4', 'Memahami produk jenama Malaysia: pertanian (minyak masak, sabun, nanas, durian), petroleum (minyak petrol, minyak pelincir kenderaan, gas memasak), automotif (kereta dan motosikal).', '{"pairs":[{"text":"Minyak masak dan sabun","pair":1},{"text":"Produk pertanian daripada sawit","pair":1},{"text":"Buah durian dan buah nanas","pair":2},{"text":"Produk pertanian berupa buah-buahan","pair":2},{"text":"Minyak petrol","pair":3},{"text":"Bahan api kenderaan daripada petroleum","pair":3},{"text":"Minyak pelincir kenderaan","pair":4},{"text":"Produk petroleum untuk melincirkan enjin","pair":4},{"text":"Gas untuk memasak","pair":5},{"text":"Produk petroleum untuk kegunaan di dapur","pair":5},{"text":"Kereta dan motosikal","pair":6},{"text":"Produk automotif keluaran negara","pair":6}],"aftermath":"Rak tersusun salah dan pelanggan membeli produk yang tidak mereka perlukan. Kedai kecoh.","turns":[{"after":1,"options":[{"text":"Produk ini membanggakan kerana mencapai kualiti kegunaan tempatan dan antarabangsa.","isCorrect":true,"reaction":"Betul. Kedai kembali tenang."},{"text":"Produk ini tidak perlu dibanggakan.","isCorrect":false,"reaction":"Pelanggan terkilan. Produk ini hasil usaha rakyat."},{"text":"Produk ini hanya dijual di luar negara.","isCorrect":false,"reaction":"Produk ini untuk tempatan dan antarabangsa."}],"clue":"Banggakan produk tempatan."}]}'),
(819, 'e8_n3_s3', 'Cari Bukti Pencapaian Ekonomi', 'Cari empat bukti pencapaian pesat ekonomi negara.', '2', 'Memahami pencapaian ekonomi: pembangunan (bangunan pencakar langit), perhubungan (jaringan moden terancang) dan perdagangan (e-dagang yang semakin berkembang).', '{"bgImage":"../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png","hotspots":[{"name":"Menara pencakar langit: pembangunan negara","top":"25.4%","left":"22.1%"},{"name":"Jambatan, kereta api dan jalan raya: perhubungan moden yang terancang","top":"62%","left":"38%"},{"name":"Gudang E-Dagang: perdagangan yang semakin berkembang","top":"45%","left":"78%"},{"name":"Papan iklan carta menaik: e-dagang semakin berkembang","top":"22%","left":"90%"}],"aftermath":"Bukti tidak ditemui dan pelanggan muda menyangka negara tidak berkembang.","turns":[{"after":2,"options":[{"text":"Kita harus bangga dan bersyukur dengan kemakmuran yang dikongsi bersama.","isCorrect":true,"reaction":"Betul. Pelanggan muda tersenyum."},{"text":"Kemakmuran hanya untuk orang kaya.","isCorrect":false,"reaction":"Pelanggan membantah. Kemakmuran dikongsi bersama."},{"text":"Pembangunan tidak perlu dibanggakan.","isCorrect":false,"reaction":"Itu bukti kemakmuran negara."}],"clue":"Bangga dan bersyukur."}]}'),
(820, 'e8_n3_s4', 'Pembangunan, Perhubungan, Perdagangan', 'Padankan pencapaian ekonomi dengan penerangannya.', '4', 'Memahami: pembangunan (bangunan pencakar langit sebagai lambang kemakmuran), perhubungan (jaringan moden terancang mendorong kesinambungan pembangunan), perdagangan (e-dagang membuka peluang kepada rakyat).', '{"pairs":[{"text":"Pembangunan","pair":1},{"text":"Bangunan pencakar langit sebagai lambang kemakmuran negara","pair":1},{"text":"Perhubungan","pair":2},{"text":"Jaringan moden terancang mendorong kesinambungan pembangunan","pair":2},{"text":"Perdagangan","pair":3},{"text":"Kegiatan e-dagang membuka peluang kepada rakyat","pair":3},{"text":"E-dagang","pair":4},{"text":"Proses menjalankan urusan perniagaan melalui rangkaian Internet","pair":4}],"aftermath":"Kad bertukar dan e-dagang diterangkan sebagai jaringan jalan raya. Pelanggan keliru.","turns":[{"after":1,"options":[{"text":"E-dagang membuka peluang kepada rakyat untuk menyumbang kepada ekonomi.","isCorrect":true,"reaction":"Betul. Pelanggan mula berniaga."},{"text":"E-dagang mengurangkan peluang berniaga.","isCorrect":false,"reaction":"Itu salah. E-dagang membuka peluang."},{"text":"E-dagang hanya untuk kedai besar.","isCorrect":false,"reaction":"Rakyat biasa juga boleh berniaga secara dalam talian."}],"clue":"E-dagang membuka peluang."}]}'),
(821, 'e8_n3_s5', 'Kad Rasa Bangga Barangan Tempatan', 'Baca kad dan tentukan kepentingan rasa bangga terhadap barangan buatan Malaysia.', '5', 'Memahami kepentingan: memajukan sistem ekonomi, memperluaskan pasaran produk tempatan, melahirkan rasa bangga, memperkenalkan identiti negara, meningkatkan produktiviti usahawan, memupuk rasa bangga.', '{"clueText":"Kad: Rasa bangga terhadap barangan buatan Malaysia memajukan sistem ekonomi negara, memperluaskan pasaran produk tempatan, memperkenalkan identiti negara dan membantu usahawan meningkatkan produktiviti.","options":[{"text":"Memajukan ekonomi, memperluaskan pasaran tempatan dan memperkenalkan identiti negara.","isCorrect":true},{"text":"Melemahkan pasaran produk tempatan.","isCorrect":false,"consequence":"Kad menyatakan ia memperluaskan pasaran tempatan."},{"text":"Menurunkan produktiviti usahawan.","isCorrect":false,"consequence":"Kad menyatakan usahawan meningkatkan produktiviti."},{"text":"Menyembunyikan identiti negara.","isCorrect":false,"consequence":"Kad menyatakan ia memperkenalkan identiti negara."}],"aftermath":"Kad tersalah baca dan remaja memilih barangan luar kerana menyangka produk tempatan tidak bermanfaat.","turns":[{"after":1,"options":[{"text":"Aku akan memilih produk tempatan kerana ia memajukan ekonomi negara.","isCorrect":true,"reaction":"Betul. Remaja itu membeli beg buatan Malaysia."},{"text":"Aku akan memilih produk luar sahaja.","isCorrect":false,"reaction":"Produk tempatan ialah identiti negara."},{"text":"Produk tempatan tidak perlu disokong.","isCorrect":false,"reaction":"Sokongan membantu usahawan meningkatkan produktiviti."}],"clue":"Sokong produk tempatan."}]}'),
(822, 'e8_n3_s6', 'Kad Kepentingan Kemajuan Ekonomi', 'Baca kad dan tentukan kepentingan kemajuan ekonomi bagi mengekalkan kemakmuran negara.', '5', 'Memahami kepentingan: meningkatkan taraf hidup melalui peluang pekerjaan, infrastruktur, inovasi, kestabilan sosial dan politik, daya saing dengan negara lain.', '{"clueText":"Kad: Kemajuan ekonomi meningkatkan taraf hidup rakyat dengan menyediakan lebih banyak peluang pekerjaan, membolehkan pelaburan dalam infrastruktur seperti jalan raya dan jambatan, menyumbang kepada kestabilan sosial dan politik serta meningkatkan daya saing negara.","options":[{"text":"Meningkatkan taraf hidup, infrastruktur dan daya saing negara.","isCorrect":true},{"text":"Meningkatkan kadar kemiskinan.","isCorrect":false,"consequence":"Kad menyatakan sebaliknya."},{"text":"Menyebabkan kemakmuran negara terjejas.","isCorrect":false,"consequence":"Pendapatan tinggi menyumbang kepada kemakmuran."},{"text":"Meningkatkan masalah kewangan kerajaan.","isCorrect":false,"consequence":"Kemajuan ekonomi tidak meningkatkan masalah itu."}],"aftermath":"Kad tersalah baca dan soal selidik menyatakan kemajuan ekonomi menambah kemiskinan.","turns":[{"after":1,"options":[{"text":"Kemajuan ekonomi mengekalkan kemakmuran negara.","isCorrect":true,"reaction":"Betul. Soal selidik disiapkan."},{"text":"Kemajuan ekonomi menambah kemiskinan.","isCorrect":false,"reaction":"Kad menyatakan sebaliknya."},{"text":"Kemajuan ekonomi tidak berkaitan dengan taraf hidup.","isCorrect":false,"reaction":"Ia meningkatkan taraf hidup rakyat."}],"clue":"Kemajuan ekonomi memakmurkan negara."}]}'),
(823, 'e8_n3_s7', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan peranannya dalam menyokong ekonomi.', '4', 'Memahami cinta akan negara: diri (menyokong usaha meningkatkan ekonomi), masyarakat (sokongan meningkatkan pendapatan negara), negara (pendapatan dan kemajuan ekonomi dikongsi bersama).', '{"pairs":[{"text":"Diri","pair":1},{"text":"Setiap warganegara menyokong usaha meningkatkan ekonomi negara","pair":1},{"text":"Masyarakat","pair":2},{"text":"Sokongan dalam pembangunan ekonomi meningkatkan pendapatan negara","pair":2},{"text":"Negara","pair":3},{"text":"Peningkatan pendapatan dan kemajuan ekonomi dikongsi bersama","pair":3}],"aftermath":"Padanan tersilap dan projek sekolah mendapat markah rendah. Cikgu menggeleng.","turns":[{"after":1,"options":[{"text":"Kita menyokong ekonomi negara supaya kemakmuran terus dikongsi bersama.","isCorrect":true,"reaction":"Betul. Projek mendapat markah penuh."},{"text":"Ekonomi negara hanya urusan kerajaan.","isCorrect":false,"reaction":"Cikgu menggeleng. Setiap warganegara perlu terlibat."},{"text":"Kita tidak perlu menyokong kerana kemakmuran sudah cukup.","isCorrect":false,"reaction":"Sokongan menjamin ekonomi terus berkembang maju."}],"clue":"Setiap warganegara menyokong ekonomi."}]}'),
(824, 'e8_n3_s8', 'Rumusan Industri Pemacu Kemajuan', 'Padankan industri pemacu kemajuan dengan cirinya.', '4', 'Merumus kegiatan ekonomi pemacu kemajuan: getah dan kelapa sawit (awal abad ke-20), petroleum dan gas (1910, PETRONAS 1974), automotif (1983 PROTON), pelancongan (Tahun Melawat Malaysia sejak 1990).', '{"pairs":[{"text":"Getah dan kelapa sawit","pair":1},{"text":"Sektor pertanian utama sejak awal abad ke-20","pair":1},{"text":"Petroleum dan gas","pair":2},{"text":"Bermula 1910 di Miri; PETRONAS ditubuhkan 1974","pair":2},{"text":"Automotif","pair":3},{"text":"PROTON ditubuhkan 1983 dan PERODUA 1993","pair":3},{"text":"Pelancongan","pair":4},{"text":"Kempen Tahun Melawat Malaysia sejak tahun 1990","pair":4}],"aftermath":"Ciri bertukar dan rumusan memberi tarikh PETRONAS kepada industri pelancongan.","turns":[{"after":1,"options":[{"text":"Kegiatan ekonomi yang pelbagai menjana pendapatan dan mengekalkan kemakmuran negara.","isCorrect":true,"reaction":"Betul. Kedai ditutup dengan rasa bangga."},{"text":"Pendapatan negara bergantung pada satu industri sahaja.","isCorrect":false,"reaction":"Pelbagai industri menyumbang kepada pendapatan negara."},{"text":"Industri baharu tidak membantu negara.","isCorrect":false,"reaction":"Industri baharu meningkatkan ekonomi negara."}],"clue":"Pelbagai industri memacu kemajuan."}]}'),
(901, 'e9_n1_s1', 'Persatuan Badminton Malaysia', 'Padankan butiran Persatuan Badminton Malaysia (BAM) dengan maklumatnya.', '4', 'Memahami BAM: ditubuhkan 1960; menganjurkan Kejohanan Badminton Kebangsaan; melahirkan atlet seperti Punch Gunalan, Misbun Sidek dan Lee Chong Wei.', '{"pairs":[{"text":"BAM ditubuhkan pada tahun","pair":1},{"text":"1960","pair":1},{"text":"Kejohanan yang dianjurkan BAM","pair":2},{"text":"Kejohanan Badminton Kebangsaan","pair":2},{"text":"Atlet kebanggaan yang dilahirkan","pair":3},{"text":"Punch Gunalan, Misbun Sidek dan Lee Chong Wei","pair":3},{"text":"Pencapaian antarabangsa","pair":4},{"text":"Juara Piala Thomas lima kali dan pingat Olimpik","pair":4}],"aftermath":"Butiran bertukar dan siaran menyatakan BAM ditubuhkan pada tahun 1963. Peminat menegur.","turns":[{"after":2,"options":[{"text":"Persatuan sukan membangunkan atlet dan mengharumkan nama negara.","isCorrect":true,"reaction":"Betul. Siaran bermula dengan lancar."},{"text":"Persatuan sukan tidak diperlukan kerana atlet berlatih sendiri.","isCorrect":false,"reaction":"Pengulas menggeleng. Persatuan menganjurkan kejohanan dan melahirkan atlet."},{"text":"BAM memajukan sukan bola sepak.","isCorrect":false,"reaction":"Itu peranan FAM. BAM memajukan badminton."}],"clue":"Persatuan membangunkan atlet."}]}'),
(902, 'e9_n1_s2', 'Nota Pencapaian Badminton', 'Baca nota dan tentukan pencapaian badminton negara pada peringkat antarabangsa.', '5', 'Memahami pencapaian badminton: juara Piala Thomas lima kali; pingat perak dan gangsa Sukan Olimpik; juara All England bagi acara beregu dan individu lelaki.', '{"clueText":"Nota: Pencapaian sukan badminton negara cemerlang pada peringkat antarabangsa. Atlet negara muncul juara sebanyak lima kali Kejohanan Piala Thomas dan memenangi pingat perak dan gangsa Sukan Olimpik. Mereka juga pernah menjuarai Kejohanan Badminton Terbuka All England bagi acara beregu dan individu lelaki.","options":[{"text":"Juara Piala Thomas lima kali dan pemenang pingat perak serta gangsa Olimpik.","isCorrect":true},{"text":"Juara Piala Dunia Hoki dan pingat emas Olimpik.","isCorrect":false,"consequence":"Itu tidak betul. Nota menyebut Piala Thomas dan pingat perak serta gangsa Olimpik."},{"text":"Juara Piala Suzuki AFF dan Sukan SEA.","isCorrect":false,"consequence":"Itu pencapaian bola sepak."},{"text":"Juara Sukan Komanwel 1998 sahaja.","isCorrect":false,"consequence":"Nota tidak menyebut perkara itu."}],"aftermath":"Nota tersalah baca dan siaran menyatakan Malaysia pemenang pingat emas Olimpik badminton. Peminat marah.","turns":[{"after":3,"options":[{"text":"Kita harus bangga dengan kejayaan badminton negara.","isCorrect":true,"reaction":"Betul. Peminat bertepuk tangan."},{"text":"Badminton negara tidak pernah menang di peringkat antarabangsa.","isCorrect":false,"reaction":"Peminat membantah dengan nota di tangan."},{"text":"Kejayaan badminton hanya diraih oleh satu kaum.","isCorrect":false,"reaction":"Atlet pelbagai kaum menyumbang kejayaan."}],"clue":"Banggakan kejayaan badminton."}]}'),
(903, 'e9_n1_s3', 'Persatuan Bola Sepak Malaysia', 'Padankan butiran Persatuan Bola Sepak Malaysia (FAM) dengan maklumatnya.', '4', 'Memahami FAM: ditubuhkan 1963; menganjurkan Liga Malaysia; pemain Soh Chin Ann, James Wong, Safawi Rasid; Olimpik Munich 1972 dan Moscow 1980; Piala Suzuki AFF 2010.', '{"pairs":[{"text":"FAM ditubuhkan pada tahun","pair":1},{"text":"1963","pair":1},{"text":"Pertandingan yang dianjurkan FAM","pair":2},{"text":"Liga Bola Sepak Malaysia","pair":2},{"text":"Pemain berbakat","pair":3},{"text":"Soh Chin Ann, James Wong dan Safawi Rasid","pair":3},{"text":"Layak ke Sukan Olimpik","pair":4},{"text":"Munich 1972 dan Moscow 1980","pair":4},{"text":"Juara Piala Suzuki AFF","pair":5},{"text":"Tahun 2010","pair":5}],"aftermath":"Butiran bertukar dan siaran menyatakan Malaysia layak ke Olimpik 1960. Peminat menegur.","turns":[{"after":2,"options":[{"text":"Pemain berbakat dilahirkan melalui liga yang teratur.","isCorrect":true,"reaction":"Betul. Peminat bersorak."},{"text":"Pemain berbakat tidak memerlukan liga.","isCorrect":false,"reaction":"Pengulas membetulkan. Liga melahirkan pemain."},{"text":"FAM ditubuhkan pada tahun 1952.","isCorrect":false,"reaction":"Tahun itu ialah tahun penubuhan KOAM."}],"clue":"Liga melahirkan pemain."}]}'),
(904, 'e9_n1_s4', 'Nota Anugerah PUSKAS FIFA', 'Baca nota dan tentukan anugerah antarabangsa yang pernah dimenangi pemain Malaysia.', '5', 'Memahami bahawa Mohd Faiz Subri, ketika menjadi pemain pasukan Pulau Pinang, memenangi anugerah antarabangsa PUSKAS FIFA 2016.', '{"clueText":"Nota: Mohd Faiz Subri ketika menjadi pemain bola sepak pasukan Pulau Pinang pernah memenangi anugerah antarabangsa PUSKAS FIFA 2016.","options":[{"text":"Anugerah PUSKAS FIFA 2016.","isCorrect":true},{"text":"Anugerah Pemain Lelaki Terbaik BWF.","isCorrect":false,"consequence":"Itu anugerah yang diberikan kepada Lee Chong Wei."},{"text":"Anugerah Atlet Terunggul Sepanjang Zaman Sukan Dunia 2021.","isCorrect":false,"consequence":"Itu anugerah Nicol Ann David."},{"text":"Anugerah Olahragawan Negara 1986.","isCorrect":false,"consequence":"Itu anugerah Abdul Malek Mohamed Noor."}],"aftermath":"Nota tersalah baca dan peminat muda terus tidak percaya pemain negara boleh berjaya.","turns":[{"after":2,"options":[{"text":"Pemain negara juga mampu berjaya di peringkat antarabangsa.","isCorrect":true,"reaction":"Betul. Aku minta maaf."},{"text":"Pemain negara tidak mampu menang anugerah dunia.","isCorrect":false,"reaction":"Nota menunjukkan sebaliknya."},{"text":"Anugerah itu diraih oleh pemain badminton.","isCorrect":false,"reaction":"Itu salah. Anugerah itu untuk pemain bola sepak."}],"clue":"Pemain negara mampu ke peringkat dunia."}]}'),
(905, 'e9_n1_s5', 'Cari Bukti Pecut Sukan Asia', 'Cari empat bukti kejayaan olahraga negara dalam rakaman.', '2', 'Memahami bahawa atlet negara memenangi pingat emas acara 100 meter Sukan Asia pada tahun 1966 dan 1982; olahraga dikembangkan oleh KOAM (kini KOM).', '{"bgImage":"../assets/gameAsset/background/olahraga.png","hotspots":[{"name":"Pelari pecut: pingat emas 100m Sukan Asia pada 1966 dan 1982","top":"45.7%","left":"47.5%"},{"name":"Blok permulaan: acara 100m Sukan Asia","top":"77.2%","left":"54.5%"},{"name":"Pegawai berjam randik: pengurusan olahraga oleh KOM","top":"60%","left":"14.5%"},{"name":"Pelari kedua: atlet olahraga Malaysia dalam Kejohanan Sukan SEA","top":"50.5%","left":"70.8%"}],"aftermath":"Bukti tidak ditemui dan peminat menyangka atlet olahraga negara tidak pernah menang di Sukan Asia.","turns":[{"after":2,"options":[{"text":"Kejayaan olahraga hasil usaha atlet dan persatuan sukan.","isCorrect":true,"reaction":"Betul. Rakaman ini bukti sejarah."},{"text":"Kejayaan olahraga hanya berlaku secara kebetulan.","isCorrect":false,"reaction":"Pengulas membantah. Kejayaan itu hasil latihan dan organisasi."},{"text":"Atlet olahraga tidak pernah menang di Sukan Asia.","isCorrect":false,"reaction":"Rakaman menunjukkan emas 100 meter pada 1966 dan 1982."}],"clue":"Kejayaan hasil usaha."}]}'),
(906, 'e9_n1_s6', 'Nota Kesatuan Olahraga', 'Baca nota dan tentukan maklumat Kesatuan Olahraga Amatur Malaysia (KOAM).', '5', 'Memahami KOAM: ditubuhkan 1952, kini KOM; menganjurkan Kejohanan Olahraga Kebangsaan; atlet Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek; juara Sukan SEA 2017 dengan lapan emas.', '{"clueText":"Nota: Kesatuan Olahraga Amatur Malaysia (KOAM) ditubuhkan pada tahun 1952 dan kini dikenali sebagai Kesatuan Olahraga Malaysia (KOM). KOM menganjurkan Kejohanan Olahraga Kebangsaan. Atlet seperti Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek dilahirkan, dan atlet olahraga membantu negara muncul sebagai juara Kejohanan Sukan SEA 2017 dengan menyumbang lapan pingat emas.","options":[{"text":"KOAM ditubuhkan 1952; kini KOM; juara Sukan SEA 2017 dengan lapan emas.","isCorrect":true},{"text":"KOAM ditubuhkan 1960; kini BAM; juara Sukan SEA 2017 dengan dua emas.","isCorrect":false,"consequence":"BAM ialah persatuan badminton. Nota menyebut 1952 dan KOM."},{"text":"KOAM ditubuhkan 1963; kini FAM; juara Sukan SEA 2017 dengan lapan emas.","isCorrect":false,"consequence":"FAM ialah persatuan bola sepak."},{"text":"KOAM ditubuhkan 1953; kini MHC; juara Sukan SEA 2017 dengan lapan emas.","isCorrect":false,"consequence":"MHC ialah konfederasi hoki."}],"aftermath":"Nota tersalah baca dan siaran menamakan KOAM sebagai persatuan badminton. Peminat marah.","turns":[{"after":2,"options":[{"text":"Persatuan sukan sentiasa menyokong atlet daripada pelbagai kaum.","isCorrect":true,"reaction":"Betul. Siaran bersambung."},{"text":"Persatuan sukan hanya menyokong satu kaum.","isCorrect":false,"reaction":"Atlet pelbagai kaum dilahirkan."},{"text":"Persatuan sukan tidak menganjurkan kejohanan.","isCorrect":false,"reaction":"KOM menganjurkan Kejohanan Olahraga Kebangsaan."}],"clue":"Atlet pelbagai kaum."}]}'),
(907, 'e9_n1_s7', 'Konfederasi Hoki Malaysia', 'Padankan butiran Konfederasi Hoki Malaysia (MHC) dengan maklumatnya.', '4', 'Memahami MHC: ditubuhkan 1953; Liga Hoki Kebangsaan; pemain Poon Fook Loke, Sarjit Singh, Mirnawan Nawawi; layak lapan kali Piala Dunia; tempat keempat 1975; naib juara Komanwel 1998.', '{"pairs":[{"text":"MHC ditubuhkan pada tahun","pair":1},{"text":"1953","pair":1},{"text":"Pertandingan yang dianjurkan","pair":2},{"text":"Liga Hoki Kebangsaan","pair":2},{"text":"Pemain hoki berbakat","pair":3},{"text":"Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi","pair":3},{"text":"Layak ke Hoki Piala Dunia","pair":4},{"text":"Sebanyak lapan kali","pair":4},{"text":"Tempat keempat Hoki Piala Dunia","pair":5},{"text":"Tahun 1975","pair":5},{"text":"Naib juara Sukan Komanwel","pair":6},{"text":"Tahun 1998","pair":6}],"aftermath":"Butiran bertukar dan siaran menyatakan hoki negara tidak pernah layak ke Piala Dunia.","turns":[{"after":2,"options":[{"text":"Kejayaan hoki mengharumkan nama negara.","isCorrect":true,"reaction":"Betul. Peminat bertepuk tangan."},{"text":"Hoki negara tidak pernah mencapai kejayaan antarabangsa.","isCorrect":false,"reaction":"Peminat menunjukkan rekod 1975 dan 1998."},{"text":"Hoki negara hanya popular di sekolah.","isCorrect":false,"reaction":"Pasukan negara pernah layak lapan kali ke Piala Dunia."}],"clue":"Banggakan kejayaan hoki."}]}'),
(908, 'e9_n1_s8', 'Empat Legenda Sukan', 'Padankan legenda sukan dengan pencapaiannya.', '4', 'Mengenal pasti tokoh terdahulu: Dr. M. Jegathesan (Manusia Terpantas Asia; tiga emas Sukan Asia 1966), M. Rajamani (olahraga wanita; Olimpik 1964), Tan Aik Huang (juara All England 1966), Mokhtar Dahari (Supermokh; 167 penampilan, 89 gol).', '{"pairs":[{"text":"Dr. M. Jegathesan","pair":1},{"text":"Manusia Terpantas Asia; tiga emas Sukan Asia Bangkok 1966","pair":1},{"text":"M. Rajamani","pair":2},{"text":"Atlet olahraga wanita; mewakili negara di Olimpik 1964","pair":2},{"text":"Tan Aik Huang","pair":3},{"text":"Juara perseorangan lelaki All England 1966","pair":3},{"text":"Mokhtar Dahari","pair":4},{"text":"Digelar Supermokh; 167 penampilan antarabangsa dan 89 gol","pair":4}],"aftermath":"Legenda bertukar bingkai dan galeri memaparkan gelaran yang salah. Peminat mengeluh.","turns":[{"after":2,"options":[{"text":"Kita perlu menghargai jasa atlet terdahulu yang terdiri daripada pelbagai kaum.","isCorrect":true,"reaction":"Betul. Mereka inspirasi sukan masa kini."},{"text":"Atlet terdahulu tidak perlu dikenang.","isCorrect":false,"reaction":"Pengulas menggeleng. Jasa mereka menjadi inspirasi."},{"text":"Hanya atlet semasa yang penting.","isCorrect":false,"reaction":"Atlet terdahulu meletakkan asas kejayaan masa kini."}],"clue":"Hargai jasa atlet terdahulu."}]}'),
(909, 'e9_n2_s1', 'Cari Bukti Kebanggaan Podium', 'Cari empat bukti kebanggaan negara di podium sukan.', '2', 'Memahami bahawa kejayaan atlet dapat dilihat melalui pingat emas, bendera, trofi dan sorakan rakyat.', '{"bgImage":"../assets/gameAsset/background/semua_podium_sukan.png","hotspots":[{"name":"Pingat emas: lambang kebanggaan atlet negara","top":"25.9%","left":"27.9%"},{"name":"Bendera Malaysia: kebanggaan negara","top":"23%","left":"50.8%"},{"name":"Trofi diangkat: kejayaan atlet kebanggaan negara","top":"37.6%","left":"48.1%"},{"name":"Penonton bersorak: rakyat bangga dengan atlet negara","top":"88%","left":"15%"}],"aftermath":"Bukti tidak ditemui dan murid menyangka atlet bertanding hanya untuk diri sendiri.","turns":[{"after":2,"options":[{"text":"Kita harus bangga apabila bendera negara berkibar dalam temasya sukan dunia.","isCorrect":true,"reaction":"Betul, cikgu."},{"text":"Atlet hanya bertanding untuk wang.","isCorrect":false,"reaction":"Cikgu menggeleng. Atlet mewakili negara."},{"text":"Kejayaan atlet tidak penting untuk rakyat.","isCorrect":false,"reaction":"Murid mengakui rakyat berasa bangga."}],"clue":"Atlet mengharumkan nama negara."}]}'),
(910, 'e9_n2_s2', 'Kad Lee Chong Wei', 'Baca kad dan tentukan pencapaian Lee Chong Wei.', '5', 'Memahami Lee Chong Wei: nombor satu dunia 2006, 2008, 2012 dan 2013; juara perseorangan lelaki Terbuka All England empat kali; Anugerah Pemain Lelaki Terbaik BWF lima kali.', '{"clueText":"Kad: Lee Chong Wei pernah memegang gelaran pemain badminton nombor satu dunia pada tahun 2006, 2008, 2012 dan 2013. Beliau juga juara Perseorangan Lelaki Terbuka All England sebanyak empat kali dan dinobatkan Anugerah Pemain Lelaki Terbaik oleh BWF sebanyak lima kali.","options":[{"text":"Nombor satu dunia empat kali dan juara All England empat kali.","isCorrect":true},{"text":"Pemain skuasy wanita nombor satu dunia selama 108 bulan.","isCorrect":false,"consequence":"Itu pencapaian Nicol Ann David."},{"text":"Penyumbang pingat gangsa pertama negara di Olimpik London 2012.","isCorrect":false,"consequence":"Itu pencapaian Pandelela Rinong."},{"text":"Pelumba basikal pecut individu nombor satu dunia 2021.","isCorrect":false,"consequence":"Itu pencapaian Mohd Azizulhasni Awang."}],"aftermath":"Kad tersalah baca dan murid menulis Lee Chong Wei pemain skuasy. Cikgu menggeleng.","turns":[{"after":2,"options":[{"text":"Kejayaan datang daripada kegigihan dan latihan.","isCorrect":true,"reaction":"Betul. Murid mengambil raket."},{"text":"Kejayaan datang tanpa usaha.","isCorrect":false,"reaction":"Cikgu menegur. Kejayaan datang dengan kegigihan."},{"text":"Lee Chong Wei bermain bola sepak.","isCorrect":false,"reaction":"Beliau pemain badminton."}],"clue":"Kejayaan memerlukan kegigihan."}]}'),
(911, 'e9_n2_s3', 'Tiga Atlet Kebanggaan', 'Padankan atlet dengan pencapaiannya.', '4', 'Memahami: Nicol Ann David (skuasy nombor satu dunia 108 bulan; lapan kali juara Terbuka Dunia); Pandelela Rinong (terjun; gangsa pertama Olimpik London 2012; wanita pertama pembawa bendera); Azizulhasni (basikal trek; The Pocket Rocketman; gangsa Rio 2016, perak Tokyo 2020).', '{"pairs":[{"text":"Nicol Ann David","pair":1},{"text":"Skuasy wanita nombor satu dunia selama 108 bulan","pair":1},{"text":"Pandelela Rinong","pair":2},{"text":"Gangsa pertama negara di Olimpik London 2012 dalam terjun","pair":2},{"text":"Mohd Azizulhasni Awang","pair":3},{"text":"The Pocket Rocketman; gangsa Rio 2016 dan perak Tokyo 2020","pair":3},{"text":"Pembawa bendera wanita pertama","pair":4},{"text":"Pandelela Rinong pada upacara pembukaan Sukan Olimpik","pair":4}],"aftermath":"Poster dipadankan dengan nama yang salah dan murid memberi tabik kepada atlet yang salah.","turns":[{"after":1,"options":[{"text":"Atlet pelbagai kaum mengharumkan nama negara.","isCorrect":true,"reaction":"Betul. Murid mengangguk."},{"text":"Atlet hanya terdiri daripada satu kaum.","isCorrect":false,"reaction":"Cikgu membantah. Negara melahirkan atlet pelbagai kaum."},{"text":"Atlet hanya menang di Malaysia.","isCorrect":false,"reaction":"Mereka juga menang di peringkat antarabangsa."}],"clue":"Atlet pelbagai kaum."}]}'),
(912, 'e9_n2_s4', 'Kad S. Kuhan', 'Baca kad dan tentukan rekod S. Kuhan dalam hoki.', '5', 'Memahami S. Kuhan: penjaring terbanyak Liga Hoki Malaysia 1997, 1999 dan 2003; ketua pasukan hoki 2000-2006; mewakili negara 341 kali.', '{"clueText":"Kad: S. Kuhan ialah penjaring terbanyak Liga Hoki Malaysia pada tahun 1997, 1999 dan 2003. Beliau merupakan ketua pasukan hoki Malaysia dari tahun 2000 hingga 2006 dan mewakili negara sebanyak 341 kali dalam pelbagai kejohanan utama hoki.","options":[{"text":"Mewakili negara 341 kali dan ketua pasukan 2000 hingga 2006.","isCorrect":true},{"text":"Mewakili negara 167 kali dan menjaringkan 89 gol.","isCorrect":false,"consequence":"Itu rekod Mokhtar Dahari dalam bola sepak."},{"text":"Ketua pasukan badminton 2000 hingga 2006.","isCorrect":false,"consequence":"S. Kuhan pemain hoki."},{"text":"Pemenang tujuh emas Sukan SEA Bangkok 1985.","isCorrect":false,"consequence":"Itu rekod Nurul Huda dalam renang."}],"aftermath":"Kad tersalah baca dan murid mengira S. Kuhan hanya sekali mewakili negara.","turns":[{"after":1,"options":[{"text":"Seorang ketua pasukan memimpin dengan teladan.","isCorrect":true,"reaction":"Betul. Murid mengangguk."},{"text":"Seorang ketua pasukan hanya perlu mengarah.","isCorrect":false,"reaction":"Cikgu menegur. Ketua memimpin dengan teladan."},{"text":"Seorang ketua tidak perlu berlatih.","isCorrect":false,"reaction":"Ketua perlu menjadi contoh yang baik."}],"clue":"Ketua memimpin dengan teladan."}]}'),
(913, 'e9_n2_s5', 'Renang dan Bina Badan', 'Padankan atlet dengan pencapaiannya dalam renang dan bina badan.', '4', 'Memahami: Nurul Huda Abdullah (7 emas Bangkok 1985, 7 emas Jakarta 1987, 8 emas Kuala Lumpur 1989); Abdul Malek Mohamed Noor (enam kali Mr. Asia heavyweight; Olahragawan Negara 1986).', '{"pairs":[{"text":"Nurul Huda: Sukan SEA Bangkok 1985","pair":1},{"text":"Tujuh pingat emas","pair":1},{"text":"Nurul Huda: Sukan SEA Jakarta 1987","pair":2},{"text":"Tujuh pingat emas lagi","pair":2},{"text":"Nurul Huda: Sukan SEA Kuala Lumpur 1989","pair":3},{"text":"Lapan pingat emas","pair":3},{"text":"Abdul Malek: gelaran Mr. Asia","pair":4},{"text":"Enam kali kategori heavyweight","pair":4},{"text":"Abdul Malek: Olahragawan Negara","pair":5},{"text":"Dianugerahkan pada tahun 1986","pair":5}],"aftermath":"Rekod bertukar dan murid mengira Nurul Huda hanya menang satu emas.","turns":[{"after":1,"options":[{"text":"Rekod itu hasil latihan dan semangat juang.","isCorrect":true,"reaction":"Betul. Murid mencatat nota."},{"text":"Rekod itu hasil nasib semata-mata.","isCorrect":false,"reaction":"Cikgu menggeleng. Ia hasil latihan."},{"text":"Rekod itu tidak penting untuk dikenang.","isCorrect":false,"reaction":"Rekod itu mengharumkan nama negara."}],"clue":"Rekod hasil latihan."}]}'),
(914, 'e9_n2_s6', 'Kad Team Secret MY', 'Baca kad dan tentukan pencapaian Team Secret MY.', '5', 'Memahami Team Secret MY: mewakili negara dalam e-sukan Kejohanan Final Global PUBG Mobile (PMGC) 2021 dan menduduki tempat ketujuh terbaik dunia.', '{"clueText":"Kad: Team Secret MY mewakili negara dalam e-sukan Kejohanan Final Global PUBG Mobile (PMGC) 2021. Pasukan ini menduduki tempat ketujuh terbaik dunia.","options":[{"text":"Tempat ketujuh terbaik dunia dalam PMGC 2021.","isCorrect":true},{"text":"Juara pertama dunia dalam PMGC 2021.","isCorrect":false,"consequence":"Kad menyebut tempat ketujuh."},{"text":"Tempat ketujuh terbaik Asia dalam PMGC 2019.","isCorrect":false,"consequence":"Kad menyebut PMGC 2021 dan peringkat dunia."},{"text":"Tidak menyertai mana-mana kejohanan antarabangsa.","isCorrect":false,"consequence":"Kad menyatakan sebaliknya."}],"aftermath":"Kad tersalah baca dan murid menyangka e-sukan negara tidak pernah bertanding di peringkat dunia.","turns":[{"after":1,"options":[{"text":"Sukan baharu juga boleh mengharumkan nama negara.","isCorrect":true,"reaction":"Betul. Murid berasa teruja."},{"text":"Hanya sukan tradisional boleh mengharumkan nama negara.","isCorrect":false,"reaction":"Cikgu menggeleng. E-sukan juga mewakili negara."},{"text":"E-sukan tidak boleh mewakili negara.","isCorrect":false,"reaction":"Team Secret MY mewakili Malaysia."}],"clue":"E-sukan juga mengharumkan nama negara."}]}'),
(915, 'e9_n2_s7', 'Atlet Paralimpik Kebanggaan', 'Padankan atlet paralimpik dengan pencapaiannya.', '4', 'Memahami atlet paralimpik: Bonnie Bunyau Gustin (angkat berat; emas Tokyo 2020), Muhammad Ziyad (lontar peluru F20; emas RIO 2016; 16.84 m), Mohamad Ridzuan (100 m T36; emas RIO 2016), Abdul Latif (lompat jauh T20; 7.60 m).', '{"pairs":[{"text":"Bonnie Bunyau Gustin","pair":1},{"text":"Angkat berat; emas Paralimpik Tokyo 2020","pair":1},{"text":"Muhammad Ziyad Zolkefli","pair":2},{"text":"Lontar peluru F20; rekod dunia 16.84 meter","pair":2},{"text":"Mohamad Ridzuan Mohamad Puzi","pair":3},{"text":"100 meter T36 cerebral palsy; emas RIO 2016","pair":3},{"text":"Abdul Latif Romly","pair":4},{"text":"Lompat jauh T20; rekod dunia 7.60 meter","pair":4},{"text":"Slogan atlet paralimpik negara","pair":5},{"text":"Kami Luar Biasa","pair":5}],"aftermath":"Atlet dipadankan dengan acara yang salah dan murid menganggap atlet paralimpik kurang hebat.","turns":[{"after":1,"options":[{"text":"Kesungguhan atlet paralimpik patut menjadi teladan kepada semua.","isCorrect":true,"reaction":"Betul. Perhimpunan bertepuk tangan."},{"text":"Atlet paralimpik kurang layak dihargai.","isCorrect":false,"reaction":"Cikgu menegur. Mereka luar biasa."},{"text":"Atlet paralimpik hanya menyertai untuk suka-suka.","isCorrect":false,"reaction":"Mereka memecah rekod dunia dan memenangi emas."}],"clue":"Atlet paralimpik: luar biasa."}]}'),
(916, 'e9_n2_s8', 'Kad Faedah Sukan Antarabangsa', 'Baca kad dan tentukan faedah menjadi tuan rumah sukan antarabangsa.', '5', 'Memahami faedah penganjuran sukan antarabangsa: negara dikenali di peringkat dunia, menarik pelancong luar negara, menyumbang kepada pembangunan ekonomi; negara dipercayai kerana infrastruktur sukan lengkap.', '{"clueText":"Kad: Negara kita diberikan kepercayaan sebagai tuan rumah sukan antarabangsa kerana memiliki infrastruktur sukan yang lengkap. Peranan ini menjadikan negara dikenali pada peringkat dunia, menarik kedatangan pelancong luar negara dan menyumbang kepada pembangunan ekonomi negara.","options":[{"text":"Dikenali dunia, menarik pelancong dan menyumbang kepada ekonomi.","isCorrect":true},{"text":"Menjejaskan ekonomi dan menolak pelancong.","isCorrect":false,"consequence":"Kad menyatakan sebaliknya."},{"text":"Menghalang atlet tempatan bertanding.","isCorrect":false,"consequence":"Kad tidak menyebut perkara itu."},{"text":"Hanya menambah kos tanpa sebarang faedah.","isCorrect":false,"consequence":"Kad menyatakan faedah kepada ekonomi."}],"aftermath":"Kad tersalah baca dan pengetua menyangka penganjuran sukan hanya membazir wang.","turns":[{"after":1,"options":[{"text":"Sukan antarabangsa membawa imej gemilang dan menambah pendapatan negara.","isCorrect":true,"reaction":"Betul. Pengetua tersenyum."},{"text":"Sukan antarabangsa hanya menyusahkan rakyat.","isCorrect":false,"reaction":"Pengetua menggeleng. Ia membawa banyak faedah."},{"text":"Sukan antarabangsa tidak berkaitan dengan ekonomi.","isCorrect":false,"reaction":"Pelancong luar menyumbang kepada ekonomi."}],"clue":"Sukan membawa imej gemilang."}]}'),
(917, 'e9_n3_s1', 'Enam Program Sukan Perpaduan', 'Padankan program sukan perpaduan dengan penerangannya.', '4', 'Memahami: RIMUP (2005), 1M1S (2011, setiap murid sekurang-kurangnya satu sukan), MSSM (tahunan), SUKMA (bergilir negeri), SUKIPT (peringkat IPT), Sukan Paralimpik (OKU).', '{"pairs":[{"text":"RIMUP, diperkenalkan tahun 2005","pair":1},{"text":"Kerjasama aktiviti sukan antara sekolah memupuk perpaduan murid","pair":1},{"text":"Dasar 1Murid 1Sukan, bermula 2011","pair":2},{"text":"Setiap murid terlibat dalam sekurang-kurangnya satu bidang sukan","pair":2},{"text":"Kejohanan MSSM","pair":3},{"text":"Dianjurkan setiap tahun untuk atlet remaja","pair":3},{"text":"Temasya Sukan Malaysia (SUKMA)","pair":4},{"text":"Dianjurkan secara bergilir-gilir oleh setiap negeri","pair":4},{"text":"SUKIPT","pair":5},{"text":"Kejohanan atlet peringkat institusi pengajian tinggi","pair":5},{"text":"Sukan Paralimpik","pair":6},{"text":"Temasya sukan untuk Orang Kurang Upaya (OKU)","pair":6}],"aftermath":"Keratan bertukar dan buku skrap menyatakan SUKMA dianjurkan oleh sekolah. Cikgu menegur.","turns":[{"after":1,"options":[{"text":"Sukan memupuk perpaduan apabila pelbagai kaum bermain bersama.","isCorrect":true,"reaction":"Betul. Buku skrap diteruskan."},{"text":"Sukan hanya untuk murid yang pandai bermain.","isCorrect":false,"reaction":"Cikgu menegur. 1M1S melibatkan setiap murid."},{"text":"Sukan memecahkan perpaduan.","isCorrect":false,"reaction":"Sukan menyatukan pelbagai kaum."}],"clue":"Sukan memupuk perpaduan."}]}'),
(918, 'e9_n3_s2', 'Nota SUKMA', 'Baca nota dan tentukan temasya sukan terbesar dalam negara.', '5', 'Memahami SUKMA: sukan terbesar dalam negara, dianjurkan bergilir-gilir oleh setiap negeri; SUKMA pertama 1986; atlet pelbagai kaum mewakili negeri.', '{"clueText":"Nota: Temasya Sukan Malaysia (SUKMA) merupakan sukan terbesar dalam negara yang dianjurkan secara bergilir-gilir oleh setiap negeri. SUKMA pertama diadakan pada 1986. Pelibatan atlet pelbagai kaum yang mewakili setiap negeri berjaya membentuk masyarakat yang harmoni.","options":[{"text":"SUKMA, dianjurkan bergilir-gilir oleh setiap negeri.","isCorrect":true},{"text":"MSSM, dianjurkan setiap tahun oleh sekolah sahaja.","isCorrect":false,"consequence":"MSSM bukan temasya terbesar. Nota menyebut SUKMA."},{"text":"SUKIPT, dianjurkan oleh institusi swasta sahaja.","isCorrect":false,"consequence":"SUKIPT untuk atlet IPT."},{"text":"RIMUP, dianjurkan setiap lima tahun.","isCorrect":false,"consequence":"RIMUP ialah rancangan, bukan temasya terbesar."}],"aftermath":"Nota tersalah baca dan buku skrap mencatat MSSM sebagai temasya terbesar.","turns":[{"after":1,"options":[{"text":"Atlet pelbagai kaum yang mewakili negeri membentuk masyarakat harmoni.","isCorrect":true,"reaction":"Betul. Murid mencatat nota."},{"text":"Atlet hanya mewakili satu kaum di setiap negeri.","isCorrect":false,"reaction":"Nota menyatakan atlet pelbagai kaum."},{"text":"SUKMA tidak berkaitan dengan perpaduan.","isCorrect":false,"reaction":"SUKMA membentuk masyarakat yang harmoni."}],"clue":"SUKMA membentuk masyarakat harmoni."}]}'),
(919, 'e9_n3_s3', 'Peristiwa Sukan SEA', 'Susun peristiwa penting Sukan SEA mengikut urutan.', '1', 'Menyusun kronologi: Sukan SEAP mula dipertandingkan 1959; Malaysia tuan rumah pertama 1965; dikenali Sukan SEA pada 1977; Malaysia tuan rumah 2017.', '{"timelineItems":[{"id":1,"year":"1959","text":"Sukan SEAP (Southeast Asian Peninsular Games) mula dipertandingkan","why":"Nama awal sebelum Sukan SEA."},{"id":2,"year":"1965","text":"Malaysia menjadi tuan rumah kejohanan Sukan SEAP","why":"Penganjuran 1965 hingga 1971 dikenali sebagai Sukan SEAP."},{"id":3,"year":"1977","text":"Sukan SEAP dikenali sebagai Sukan SEA","why":"Southeast Asian Games."},{"id":4,"year":"2017","text":"Malaysia menjadi tuan rumah Sukan SEA di Kuala Lumpur","why":"Tuan rumah yang terkini dalam sejarah unit ini."}],"aftermath":"Urutan tersilap dan buku skrap menyatakan Sukan SEA bermula pada 2017.","turns":[{"after":1,"options":[{"text":"Penganjuran Sukan SEA merapatkan hubungan antara negara serantau.","isCorrect":true,"reaction":"Betul. Buku skrap lengkap."},{"text":"Sukan SEA hanya dianjurkan oleh Malaysia.","isCorrect":false,"reaction":"Cikgu membetulkan. Negara serantau bergilir menjadi tuan rumah."},{"text":"Sukan SEA tidak merapatkan hubungan negara.","isCorrect":false,"reaction":"Penganjurannya merapatkan hubungan serantau."}],"clue":"Sukan SEA merapatkan hubungan serantau."}]}'),
(920, 'e9_n3_s4', 'Piala Thomas dan Hoki Piala Dunia', 'Padankan kejohanan dengan tempat atau tahun penganjuran.', '4', 'Memahami: Piala Thomas enam kali (1970, 1984, 1988, 1992 di Stadium Negara; 2000, 2010 di Stadium Putra Bukit Jalil); Hoki Piala Dunia dua edisi (1975 Stadium Merdeka, 12 negara; 2002 Bukit Jalil, 16 negara).', '{"pairs":[{"text":"Piala Thomas 1970, 1984, 1988 dan 1992","pair":1},{"text":"Stadium Negara, Kuala Lumpur","pair":1},{"text":"Piala Thomas 2000 dan 2010","pair":2},{"text":"Stadium Putra, Bukit Jalil","pair":2},{"text":"Hoki Piala Dunia 1975","pair":3},{"text":"Stadium Merdeka dengan 12 buah negara","pair":3},{"text":"Hoki Piala Dunia 2002","pair":4},{"text":"Stadium Hoki Nasional Bukit Jalil dengan 16 buah negara","pair":4}],"aftermath":"Padanan tersilap dan buku skrap menyatakan Hoki Piala Dunia 2002 dianjurkan di Stadium Merdeka.","turns":[{"after":1,"options":[{"text":"Penganjuran kejohanan membawa imej gemilang kepada negara.","isCorrect":true,"reaction":"Betul. Murid melengkapkan halaman."},{"text":"Penganjuran kejohanan tiada manfaat kepada negara.","isCorrect":false,"reaction":"Cikgu menggeleng. Ia mendorong pembangunan sukan."},{"text":"Kejohanan hanya dianjurkan sekali sahaja.","isCorrect":false,"reaction":"Piala Thomas enam kali dan Hoki Piala Dunia dua kali."}],"clue":"Penganjuran membawa imej gemilang."}]}'),
(921, 'e9_n3_s5', 'Acara Antarabangsa di Malaysia', 'Padankan acara sukan antarabangsa dengan butirannya.', '4', 'Memahami: sukan permotoran (MotoGP, SBK) sejak 1991; Le Tour de Langkawi sejak 1996; Komanwel 1998; Formula One sejak 2000; Piala Monsun sejak 2005 (Pulau Duyong); Formula E 2014 di Putrajaya.', '{"pairs":[{"text":"MotoGP dan SBK","pair":1},{"text":"Sukan permotoran antarabangsa bermula tahun 1991","pair":1},{"text":"Le Tour de Langkawi","pair":2},{"text":"Lumba basikal antarabangsa tahunan bermula tahun 1996","pair":2},{"text":"Sukan Komanwel 1998","pair":3},{"text":"Negara Asia pertama menjadi tuan rumah","pair":3},{"text":"Formula One","pair":4},{"text":"Dianjurkan di Sepang International Circuit sejak tahun 2000","pair":4},{"text":"Formula E","pair":5},{"text":"Diadakan di Putrajaya pada tahun 2014","pair":5},{"text":"Piala Monsun","pair":6},{"text":"Sukan perahu layar di Pulau Duyong, Terengganu sejak 2005","pair":6}],"aftermath":"Acara bertukar tempat dan buku skrap mencatat Formula E di Sepang pada tahun 2000.","turns":[{"after":1,"options":[{"text":"Acara itu menarik pelancong dan menjana pendapatan negara.","isCorrect":true,"reaction":"Betul. Murid mencatat."},{"text":"Acara itu tidak berkaitan dengan pelancongan.","isCorrect":false,"reaction":"Le Tour de Langkawi mempromosikan destinasi pelancongan."},{"text":"Acara itu hanya untuk penduduk setempat.","isCorrect":false,"reaction":"Peminat dari seluruh dunia hadir."}],"clue":"Acara menarik pelancong."}]}'),
(922, 'e9_n3_s6', 'Nota Sukan Komanwel 1998', 'Baca nota dan tentukan maklumat Sukan Komanwel 1998.', '5', 'Memahami Komanwel 1998: Malaysia negara Asia pertama menjadi tuan rumah; Stadium Nasional Bukit Jalil; maskot Orang Utan dan logo bunga raya; memupuk setia kawan sesama negara Komanwel.', '{"clueText":"Nota: Malaysia merupakan negara Asia pertama menjadi tuan rumah Sukan Komanwel, iaitu pada tahun 1998. Stadium Nasional Bukit Jalil menjadi stadium utama kejohanan. Imej Orang Utan dipilih sebagai maskot dan bunga raya menjadi logo kejohanan.","options":[{"text":"Orang Utan maskot dan bunga raya logo; tuan rumah Asia pertama.","isCorrect":true},{"text":"Singa maskot dan melur logo.","isCorrect":false,"consequence":"Nota menyebut Orang Utan dan bunga raya."},{"text":"Harimau maskot dan kemboja logo.","isCorrect":false,"consequence":"Nota menyebut Orang Utan dan bunga raya."},{"text":"Gajah maskot dan teratai logo.","isCorrect":false,"consequence":"Nota menyebut Orang Utan dan bunga raya."}],"aftermath":"Nota tersalah baca dan murid menggambar maskot yang salah. Kelas ketawa.","turns":[{"after":2,"options":[{"text":"Sukan Komanwel memupuk setia kawan sesama negara Komanwel.","isCorrect":true,"reaction":"Betul. Murid mengangguk."},{"text":"Sukan Komanwel hanya dianjurkan di Eropah.","isCorrect":false,"reaction":"Malaysia ialah negara Asia pertama tuan rumah."},{"text":"Sukan Komanwel tiada kaitan dengan Malaysia.","isCorrect":false,"reaction":"Malaysia menjadi tuan rumah pada 1998."}],"clue":"Komanwel memupuk setia kawan."}]}'),
(923, 'e9_n3_s7', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan peranannya.', '4', 'Memahami cinta akan negara: diri (saling menghormati antara kaum melalui sukan), masyarakat (perpaduan dan keharmonian menjamin kesejahteraan), negara (keamanan dan kemakmuran dinikmati bersama).', '{"pairs":[{"text":"Diri","pair":1},{"text":"Mengamalkan sikap saling menghormati antara kaum melalui sukan","pair":1},{"text":"Masyarakat","pair":2},{"text":"Perpaduan dan keharmonian kaum menjamin kesejahteraan masyarakat","pair":2},{"text":"Negara","pair":3},{"text":"Keamanan dan kemakmuran dinikmati bersama apabila perpaduan dikekalkan","pair":3}],"aftermath":"Padanan tersilap dan buku skrap menyatakan perpaduan hanya urusan negara.","turns":[{"after":1,"options":[{"text":"Perpaduan kaum perlu dikekalkan supaya sukan terus mencipta kecemerlangan.","isCorrect":true,"reaction":"Betul. Cikgu tersenyum."},{"text":"Perpaduan tidak berkaitan dengan sukan.","isCorrect":false,"reaction":"Sukan ialah alat perpaduan."},{"text":"Perpaduan hanya perlu semasa pertandingan.","isCorrect":false,"reaction":"Perpaduan perlu dikekalkan sepanjang masa."}],"clue":"Kekalkan perpaduan kaum."}]}'),
(924, 'e9_n3_s8', 'Tiga Pemimpin Sukan', 'Padankan pemimpin sukan dengan jawatan atau sumbangannya.', '4', 'Mengenal pasti tokoh: Sultan Azlan Shah (Bapa Hoki Malaysia; Presiden Persekutuan Hoki Malaysia 1985-2004; Piala Sultan Azlan Shah sejak 1992); Dato\' Peter Velappan (Setiausaha Agung AFC 1978-2007); Dato\' Sieh Kok Chi (atlet polo air; Setiausaha Agung MOM 1992-2015).', '{"pairs":[{"text":"Sultan Azlan Muhibbuddin Shah","pair":1},{"text":"Bapa Hoki Malaysia; Presiden Persekutuan Hoki Malaysia 1985-2004","pair":1},{"text":"Piala Sultan Azlan Shah","pair":2},{"text":"Kejohanan hoki lapan pasukan terbaik dunia sejak tahun 1992","pair":2},{"text":"Dato\' Peter Velappan","pair":3},{"text":"Setiausaha Agung Asian Football Confederation 1978-2007","pair":3},{"text":"Dato\' Sieh Kok Chi","pair":4},{"text":"Atlet polo air; Setiausaha Agung Majlis Olimpik Malaysia 1992-2015","pair":4}],"aftermath":"Tokoh bertukar jawatan dan buku skrap mencatat Sultan Azlan Shah sebagai Setiausaha AFC. Cikgu menegur.","turns":[{"after":1,"options":[{"text":"Kepimpinan sukan dan kerjasama atlet mengharumkan nama Malaysia.","isCorrect":true,"reaction":"Betul. Buku skrap siap."},{"text":"Hanya atlet yang mengharumkan nama negara.","isCorrect":false,"reaction":"Pemimpin sukan juga mengharumkan nama Malaysia."},{"text":"Pemimpin sukan tidak perlu dihargai.","isCorrect":false,"reaction":"Cikgu menegur. Jasa mereka besar."}],"clue":"Pemimpin sukan juga berjasa."}]}'),
(1001, 'e10_n1_s1', 'Tiga Pertubuhan Serantau', 'Padankan pertubuhan serantau dengan tahun penyertaan dan anggotanya.', '4', 'Memahami pertubuhan serantau: SEAFET (1959), ASA (1961) dan ASEAN (1967).', '{"pairs":[{"text":"SEAFET, 1959","pair":1},{"text":"Persekutuan Tanah Melayu, Thailand dan Filipina","pair":1},{"text":"ASA, 1961","pair":2},{"text":"Persekutuan Tanah Melayu, Thailand dan Filipina juga","pair":2},{"text":"ASEAN, 1967","pair":3},{"text":"Pada awalnya lima buah negara","pair":3}],"aftermath":"Lencana bertukar dan wakil Indonesia menyangka Malaysia menyertai ASEAN pada tahun 1959.","turns":[{"after":1,"options":[{"text":"Negara berjiran bekerjasama untuk memelihara keharmonian dan kesejahteraan.","isCorrect":true,"reaction":"Betul. Sidang bermula."},{"text":"Negara berjiran bersaing tanpa kerjasama.","isCorrect":false,"reaction":"Wakil Indonesia menggeleng. Pertubuhan serantau bertujuan kerjasama."},{"text":"Pertubuhan serantau menyatukan negara dari benua yang berbeza.","isCorrect":false,"reaction":"Pertubuhan serantau dianggotai negara berjiran."}],"clue":"Pertubuhan serantau: negara berjiran."}]}'),
(1002, 'e10_n1_s2', 'Pertumbuhan Anggota ASEAN', 'Susun peristiwa penting pertumbuhan ASEAN mengikut urutan.', '1', 'Menyusun kronologi: SEAFET 1959, ASA 1961, ASEAN 1967, Brunei 1984, Vietnam 1995, Laos dan Myanmar 1997, Kemboja 1999.', '{"timelineItems":[{"id":1,"year":"1959","text":"Malaysia menyertai SEAFET","why":"Pertubuhan serantau pertama."},{"id":2,"year":"1961","text":"Persekutuan Tanah Melayu menyertai ASA","why":"Pertubuhan serantau kedua."},{"id":3,"year":"1967","text":"ASEAN ditubuhkan dengan lima negara awal","why":"Ditubuhkan pada 8 Ogos 1967."},{"id":4,"year":"1984","text":"Brunei menyertai ASEAN","why":"Anggota baharu pertama."},{"id":5,"year":"1995","text":"Vietnam menyertai ASEAN","why":"Anggota baharu kedua."},{"id":6,"year":"1997","text":"Laos dan Myanmar menyertai ASEAN","why":"Dua anggota serentak."},{"id":7,"year":"1999","text":"Kemboja menyertai ASEAN","why":"Menjadikan sepuluh negara anggota."}],"aftermath":"Susunan tersilap dan peta ASEAN mencatat Kemboja menyertai sebelum Vietnam.","turns":[{"after":1,"options":[{"text":"Anggota bertambah supaya kerjasama serantau lebih luas.","isCorrect":true,"reaction":"Betul. Sidang berjalan lancar."},{"text":"Anggota bertambah kerana peperangan.","isCorrect":false,"reaction":"Wakil Indonesia membetulkan. Ia tentang kerjasama."},{"text":"ASEAN dianggotai dua puluh negara.","isCorrect":false,"reaction":"ASEAN kini dianggotai 10 negara."}],"clue":"Anggota bertambah, kerjasama meluas."}]}'),
(1003, 'e10_n1_s3', 'Cari Bukti ASEAN', 'Cari empat bukti kerjasama ASEAN dalam bilik mesyuarat.', '2', 'Memahami ASEAN: Malaysia tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN; sepuluh negara Asia Tenggara; Singapura antara negara awal; matlamat keamanan dan kestabilan politik.', '{"bgImage":"../assets/gameAsset/background/bilik_mesyuarat.png","hotspots":[{"name":"Bendera Malaysia: tuan rumah Mesyuarat Menteri Luar ASEAN","top":"44.2%","left":"27.2%"},{"name":"Peta Asia Tenggara: ASEAN dianggotai 10 negara Asia Tenggara","top":"21.3%","left":"25.5%"},{"name":"Bendera Singapura: salah satu negara awal ASEAN","top":"46.6%","left":"72.2%"},{"name":"Dokumen perjanjian: matlamat keamanan dan kestabilan politik","top":"81.3%","left":"24.4%"}],"aftermath":"Bukti tidak ditemui dan wakil Indonesia menyangka Malaysia tidak aktif dalam ASEAN.","turns":[{"after":2,"options":[{"text":"Kerjasama serantau menjamin keamanan dan kestabilan politik.","isCorrect":true,"reaction":"Betul. Bilik mesyuarat sunyi mendengar."},{"text":"Kerjasama serantau menyebabkan pergolakan.","isCorrect":false,"reaction":"Dokumen perjanjian menekankan keamanan."},{"text":"Kerjasama serantau hanya melibatkan satu negara.","isCorrect":false,"reaction":"Peta menunjukkan sepuluh negara."}],"clue":"Kerjasama menjamin keamanan."}]}'),
(1004, 'e10_n1_s4', 'Kad Latar Belakang ASEAN', 'Baca kad dan tentukan latar belakang ASEAN.', '5', 'Memahami latar ASEAN: ditubuhkan 8 Ogos 1967; kini 10 negara Asia Tenggara; ibu pejabat di Jakarta, Indonesia.', '{"clueText":"Kad: ASEAN ditubuhkan pada 8 Ogos 1967 dan kini dianggotai oleh 10 buah negara Asia Tenggara. Ibu pejabat ASEAN terletak di Jakarta, Indonesia.","options":[{"text":"Ditubuhkan 8 Ogos 1967; 10 negara; ibu pejabat di Jakarta.","isCorrect":true},{"text":"Ditubuhkan 31 Ogos 1957; 5 negara; ibu pejabat di Kuala Lumpur.","isCorrect":false,"consequence":"31 Ogos 1957 ialah tarikh kemerdekaan Tanah Melayu."},{"text":"Ditubuhkan 16 September 1963; 12 negara; ibu pejabat di Manila.","isCorrect":false,"consequence":"Itu tarikh pembentukan Malaysia."},{"text":"Ditubuhkan 24 Oktober 1945; 193 negara; ibu pejabat di New York.","isCorrect":false,"consequence":"Itu latar belakang PBB."}],"aftermath":"Kad tersalah baca dan wakil baharu menulis ibu pejabat ASEAN di Kuala Lumpur.","turns":[{"after":1,"options":[{"text":"Malaysia ialah antara negara perintis penubuhan ASEAN.","isCorrect":true,"reaction":"Betul. Wakil baharu mengangguk."},{"text":"Malaysia menyertai ASEAN selepas tahun 2000.","isCorrect":false,"reaction":"Malaysia ialah negara perintis tahun 1967."},{"text":"Malaysia tidak terlibat dalam penubuhan ASEAN.","isCorrect":false,"reaction":"Malaysia ialah antara negara perintis."}],"clue":"Malaysia: negara perintis ASEAN."}]}'),
(1005, 'e10_n1_s5', 'Empat Matlamat ASEAN', 'Padankan matlamat penubuhan ASEAN dengan penerangannya.', '4', 'Memahami matlamat ASEAN: keamanan dan kestabilan politik; pertumbuhan ekonomi, kemajuan sosial dan pembangunan kebudayaan; kerjasama latihan dan penyelidikan; meningkatkan taraf hidup penduduk.', '{"pairs":[{"text":"Keamanan","pair":1},{"text":"Menjamin keamanan dan kestabilan politik","pair":1},{"text":"Pertumbuhan","pair":2},{"text":"Menggalakkan pertumbuhan ekonomi, kemajuan sosial dan pembangunan kebudayaan","pair":2},{"text":"Kerjasama","pair":3},{"text":"Menjalin kerjasama dalam bidang latihan dan penyelidikan","pair":3},{"text":"Kesejahteraan","pair":4},{"text":"Meningkatkan taraf hidup penduduk","pair":4}],"aftermath":"Matlamat bertukar dan laporan menyatakan ASEAN ditubuhkan untuk berperang. Pakar ekonomi tersentak.","turns":[{"after":1,"options":[{"text":"Hubungan baik dengan jiran memberi faedah yang dikongsi bersama.","isCorrect":true,"reaction":"Betul. Laporan diterima."},{"text":"Hubungan baik dengan jiran tidak penting.","isCorrect":false,"reaction":"Pakar ekonomi menggeleng. Faedahnya dikongsi bersama."},{"text":"ASEAN ditubuhkan untuk mengasingkan negara anggota.","isCorrect":false,"reaction":"ASEAN ditubuhkan untuk kerjasama."}],"clue":"Hubungan baik memberi faedah bersama."}]}'),
(1006, 'e10_n1_s6', 'Makna Logo ASEAN', 'Padankan unsur logo ASEAN dengan maknanya.', '4', 'Memahami makna logo: biru (keamanan dan kestabilan), merah (semangat dan dinamisme), kuning (kemakmuran), putih (kesucian), sepuluh tangkai padi (impian pengasasan diikat persahabatan dan perpaduan 10 negara), bulatan (kesatuan).', '{"pairs":[{"text":"Warna biru","pair":1},{"text":"Keamanan dan kestabilan","pair":1},{"text":"Warna merah","pair":2},{"text":"Semangat dan dinamisme","pair":2},{"text":"Warna kuning","pair":3},{"text":"Kemakmuran","pair":3},{"text":"Warna putih","pair":4},{"text":"Kesucian","pair":4},{"text":"Sepuluh tangkai padi","pair":5},{"text":"Impian pengasasan ASEAN diikat persahabatan dan perpaduan","pair":5},{"text":"Bulatan","pair":6},{"text":"Kesatuan ASEAN","pair":6}],"aftermath":"Makna bertukar dan kanak-kanak menyangka warna merah melambangkan kemakmuran.","turns":[{"after":1,"options":[{"text":"Logo itu mengingatkan kita kepada perpaduan sepuluh negara.","isCorrect":true,"reaction":"Betul. Kanak-kanak tersenyum."},{"text":"Logo itu hanya hiasan.","isCorrect":false,"reaction":"Setiap unsur ada makna."},{"text":"Logo itu lambang satu negara sahaja.","isCorrect":false,"reaction":"Ia lambang sepuluh negara anggota."}],"clue":"Logo melambangkan perpaduan."}]}'),
(1007, 'e10_n1_s7', 'Faedah Penyertaan dalam ASEAN', 'Padankan faedah penyertaan Malaysia dalam ASEAN dengan butirannya.', '4', 'Memahami faedah: Deklarasi Kuala Lumpur 1971 (ZOPFAN) mengelakkan campur tangan kuasa luar; projek baja urea di Bintulu; Sukan SEA; RECSAM di Pulau Pinang.', '{"pairs":[{"text":"Keamanan dan kestabilan politik","pair":1},{"text":"Deklarasi Kuala Lumpur 1971 mengisytiharkan ZOPFAN","pair":1},{"text":"Pertumbuhan ekonomi","pair":2},{"text":"Projek perindustrian baja urea di Bintulu, Sarawak","pair":2},{"text":"Pertumbuhan sosial","pair":3},{"text":"Menjadi tuan rumah penganjuran Sukan SEA","pair":3},{"text":"Latihan dan penyelidikan","pair":4},{"text":"Pembinaan RECSAM di Pulau Pinang","pair":4}],"aftermath":"Kad bertukar dan wakil muda mencatat RECSAM dibina di Sarawak.","turns":[{"after":1,"options":[{"text":"Faedah ASEAN dikongsi bersama negara anggota.","isCorrect":true,"reaction":"Betul. Wakil Indonesia bersetuju."},{"text":"Faedah ASEAN hanya untuk Malaysia.","isCorrect":false,"reaction":"Faedah dikongsi bersama."},{"text":"Faedah ASEAN tiada kaitan dengan rakyat.","isCorrect":false,"reaction":"Ia meningkatkan taraf hidup penduduk."}],"clue":"Faedah dikongsi bersama."}]}'),
(1008, 'e10_n1_s8', 'Dokumen Sumbangan Malaysia dalam ASEAN', 'Baca dokumen dan tentukan sumbangan Malaysia dalam ASEAN.', '5', 'Memahami sumbangan: tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN; menangani pencerobohan Vietnam ke atas Kemboja; meredakan konflik di selatan Filipina; mengutarakan ZOPFAN; menyertai SEAMEO.', '{"clueText":"Dokumen: Malaysia menjadi tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN, membantu menangani isu pencerobohan Vietnam terhadap Kemboja, membantu meredakan konflik politik di selatan Filipina, mengutarakan penubuhan ZOPFAN dan menyertai Pertubuhan Menteri-Menteri Pelajaran ASEAN (SEAMEO).","options":[{"text":"Mengutarakan ZOPFAN dan membantu meredakan konflik di selatan Filipina.","isCorrect":true},{"text":"Menubuhkan Bank Pembangunan Islam dan UIAM.","isCorrect":false,"consequence":"Itu sumbangan dalam OIC."},{"text":"Menamatkan Aparteid dan mengisytiharkan Deklarasi Langkawi.","isCorrect":false,"consequence":"Itu sumbangan dalam Komanwel."},{"text":"Menghantar pasukan pengaman ke Congo dan Namibia.","isCorrect":false,"consequence":"Itu sumbangan dalam PBB."}],"aftermath":"Dokumen tersalah baca dan wakil sidang mencatat sumbangan Malaysia dalam pertubuhan yang salah.","turns":[{"after":1,"options":[{"text":"Pelibatan Malaysia dalam ASEAN amat dihargai oleh negara anggota.","isCorrect":true,"reaction":"Betul. Sidang berakhir dengan tepukan."},{"text":"Malaysia tidak memberi sumbangan dalam ASEAN.","isCorrect":false,"reaction":"Dokumen menyenaraikan banyak sumbangan."},{"text":"Sumbangan Malaysia tidak dihargai.","isCorrect":false,"reaction":"Pelibatan Malaysia amat dihargai."}],"clue":"Sumbangan Malaysia dihargai."}]}'),
(1009, 'e10_n2_s1', 'Cari Bukti Malaysia di PBB', 'Cari empat bukti penglibatan Malaysia dalam PBB.', '2', 'Memahami PBB: keahlian terbuka kepada semua negara; Malaysia anggota yang aktif menyumbang; Malaysia menghantar pasukan pengaman PBB.', '{"bgImage":"../assets/gameAsset/background/malaysia_di_pentas_dunia.png","hotspots":[{"name":"Dewan sidang: keahlian PBB terbuka kepada semua negara","top":"42.2%","left":"26.9%"},{"name":"Bendera Malaysia: negara anggota PBB yang aktif menyumbang","top":"25.6%","left":"26.5%"},{"name":"Peta dunia di skrin: pasukan pengaman PBB termasuk Malaysia","top":"22.3%","left":"92.5%"},{"name":"Peta di skrin utama: kawasan tugas pasukan pengaman PBB","top":"73.6%","left":"49.5%"}],"aftermath":"Bukti tidak ditemui dan wakil PBB menyangka Malaysia tidak terlibat dalam misi pengaman.","turns":[{"after":1,"options":[{"text":"Pasukan pengaman menjaga keamanan dunia.","isCorrect":true,"reaction":"Betul. Wakil PBB mengangguk."},{"text":"Pasukan pengaman hanya hiasan.","isCorrect":false,"reaction":"Penjaga keamanan menegur. Mereka bertugas di kawasan konflik."},{"text":"Hanya negara besar boleh menjadi anggota PBB.","isCorrect":false,"reaction":"Keahlian PBB terbuka kepada semua negara."}],"clue":"Pasukan pengaman menjaga keamanan."}]}'),
(1010, 'e10_n2_s2', 'Kad Latar Belakang PBB', 'Baca kad dan tentukan latar belakang PBB.', '5', 'Memahami PBB: ditubuhkan 24 Oktober 1945 selepas Perang Dunia Kedua; keahlian terbuka kepada semua negara; ibu pejabat di New York; enam bahasa rasmi.', '{"clueText":"Kad: Pertubuhan Bangsa-Bangsa Bersatu (PBB) ditubuhkan pada 24 Oktober 1945 selepas Perang Dunia Kedua. Keahliannya terbuka kepada semua negara di seluruh dunia. Ibu pejabat PBB terletak di New York, Amerika Syarikat dan bahasa rasminya ialah bahasa Arab, Mandarin, Inggeris, Perancis, Rusia dan Sepanyol.","options":[{"text":"Ditubuhkan 24 Oktober 1945; ibu pejabat di New York; enam bahasa rasmi.","isCorrect":true},{"text":"Ditubuhkan 8 Ogos 1967; ibu pejabat di Jakarta; satu bahasa rasmi.","isCorrect":false,"consequence":"Itu maklumat ASEAN."},{"text":"Ditubuhkan 25 September 1969; ibu pejabat di Jeddah; tiga bahasa rasmi.","isCorrect":false,"consequence":"Itu maklumat OIC."},{"text":"Ditubuhkan 11 Disember 1931; ibu pejabat di London; dua bahasa rasmi.","isCorrect":false,"consequence":"Itu maklumat Komanwel."}],"aftermath":"Kad tersalah baca dan wakil baharu menyangka ibu pejabat PBB di Jeddah.","turns":[{"after":1,"options":[{"text":"PBB menjamin keamanan dan keselamatan dunia.","isCorrect":true,"reaction":"Betul. Wakil baharu mencatat."},{"text":"PBB hanya untuk negara Asia.","isCorrect":false,"reaction":"Keahlian PBB terbuka kepada semua negara."},{"text":"PBB ditubuhkan sebelum Perang Dunia Kedua.","isCorrect":false,"reaction":"Ia ditubuhkan selepas perang."}],"clue":"PBB menjamin keamanan dunia."}]}'),
(1011, 'e10_n2_s3', 'Pertubuhan Antarabangsa Malaysia', 'Padankan pertubuhan antarabangsa dengan tahun penyertaan dan cirinya.', '4', 'Memahami: Komanwel (1957, bekas tanah jajahan British), PBB (1957, terbuka kepada semua negara), NAM (sejak 1970, 120 negara membangun), OIC (sejak penubuhan 1969, 57 negara).', '{"pairs":[{"text":"Komanwel","pair":1},{"text":"Disertai 1957; anggota bekas tanah jajahan British","pair":1},{"text":"PBB","pair":2},{"text":"Disertai 1957; keahlian terbuka kepada semua negara","pair":2},{"text":"NAM","pair":3},{"text":"Disertai sejak 1970; 120 negara membangun Asia, Afrika, Amerika Selatan","pair":3},{"text":"OIC","pair":4},{"text":"Disertai sejak penubuhannya 1969; awalnya 57 negara","pair":4}],"aftermath":"Maklumat bertukar dan mesyuarat bermula dengan nota yang salah tentang NAM.","turns":[{"after":1,"options":[{"text":"Malaysia mengamalkan dasar berbaik-baik dengan semua negara.","isCorrect":true,"reaction":"Betul. Mesyuarat bermula."},{"text":"Malaysia mengasingkan diri daripada dunia.","isCorrect":false,"reaction":"Penjaga keamanan menggeleng. Malaysia menganggotai banyak pertubuhan."},{"text":"Malaysia menjalin hubungan diplomatik dengan semua negara tanpa pengecualian.","isCorrect":false,"reaction":"Malaysia tidak mengadakan hubungan diplomatik dengan Israel dan Korea Utara."}],"clue":"Dasar berbaik-baik dengan negara luar."}]}'),
(1012, 'e10_n2_s4', 'Dokumen Latar Belakang Komanwel', 'Baca dokumen dan tentukan latar belakang Komanwel.', '5', 'Memahami Komanwel: dibentuk 11 Disember 1931; 54 negara bekas tanah jajahan British kecuali Mozambique dan Rwanda; Sekretariat di London; matlamat setia kawan dan kerjasama.', '{"clueText":"Dokumen: Komanwel dibentuk pada 11 Disember 1931 dan dianggotai oleh 54 buah negara bekas tanah jajahan British kecuali Mozambique dan Republik Rwanda. Ibu pejabat Sekretariat Komanwel terletak di London, England. Matlamatnya membina semangat setia kawan dan mewujudkan kerjasama dalam pendidikan, ekonomi, kesihatan serta belia dan sukan.","options":[{"text":"Dibentuk 1931; 54 negara; Sekretariat di London.","isCorrect":true},{"text":"Dibentuk 1945; 193 negara; Sekretariat di New York.","isCorrect":false,"consequence":"Itu maklumat PBB."},{"text":"Dibentuk 1967; 10 negara; Sekretariat di Jakarta.","isCorrect":false,"consequence":"Itu maklumat ASEAN."},{"text":"Dibentuk 1969; 57 negara; Sekretariat di Jeddah.","isCorrect":false,"consequence":"Itu maklumat OIC."}],"aftermath":"Dokumen tersalah baca dan utusan menyangka Komanwel dibentuk selepas Perang Dunia Kedua.","turns":[{"after":1,"options":[{"text":"Komanwel membina semangat setia kawan antara negara anggota.","isCorrect":true,"reaction":"Betul. Utusan Komanwel tersenyum."},{"text":"Komanwel dianggotai semua negara tanpa pengecualian.","isCorrect":false,"reaction":"Hanya bekas tanah jajahan British (kecuali dua)."},{"text":"Komanwel ditubuhkan untuk berperang.","isCorrect":false,"reaction":"Komanwel membina setia kawan."}],"clue":"Komanwel: setia kawan."}]}'),
(1013, 'e10_n2_s5', 'Faedah Penyertaan dalam Komanwel', 'Padankan bidang dengan faedah penyertaan Malaysia dalam Komanwel.', '4', 'Memahami faedah Komanwel: pendidikan (biasiswa Komanwel), perdagangan (barangan menembusi pasaran), kesihatan (berkongsi data menangani wabak COVID-19), belia dan sukan (Sukan Komanwel 1998).', '{"pairs":[{"text":"Pendidikan","pair":1},{"text":"Tawaran biasiswa Komanwel untuk melanjutkan pendidikan tinggi","pair":1},{"text":"Perdagangan","pair":2},{"text":"Memudahkan barangan Malaysia menembusi pasaran antarabangsa","pair":2},{"text":"Kesihatan","pair":3},{"text":"Berkongsi maklumat dan data untuk menangani wabak seperti COVID-19","pair":3},{"text":"Belia dan sukan","pair":4},{"text":"Penganjuran Sukan Komanwel pada tahun 1998","pair":4}],"aftermath":"Bidang bertukar dan utusan mencatat biasiswa Komanwel sebagai faedah perdagangan.","turns":[{"after":1,"options":[{"text":"Komanwel memberi peluang kerjasama kepada pelbagai bidang.","isCorrect":true,"reaction":"Betul. Utusan menutup fail."},{"text":"Komanwel hanya memberi faedah kepada sukan.","isCorrect":false,"reaction":"Faedahnya pelbagai bidang."},{"text":"Komanwel tidak berguna kepada pelajar.","isCorrect":false,"reaction":"Biasiswa Komanwel membantu pelajar."}],"clue":"Komanwel: faedah pelbagai bidang."}]}'),
(1014, 'e10_n2_s6', 'Nota Sumbangan Malaysia dalam Komanwel', 'Baca nota dan tentukan sumbangan Malaysia dalam Komanwel.', '5', 'Memahami sumbangan: mengecam Aparteid di Afrika Selatan; membantu menamatkannya 1993; tuan rumah CHOGM 1989; Deklarasi Langkawi 1989 (pencemaran alam sekitar).', '{"clueText":"Nota: Malaysia mengecam dasar Aparteid di Afrika Selatan yang membezakan penduduk mengikut warna kulit dan membantu menamatkannya pada tahun 1993. Malaysia menjadi tuan rumah Commonwealth Heads of Government Meeting (CHOGM) pada tahun 1989 dan mengisytiharkan Deklarasi Langkawi 1989 tentang pencemaran alam sekitar.","options":[{"text":"Menamatkan Aparteid 1993 dan Deklarasi Langkawi 1989.","isCorrect":true},{"text":"Mengutarakan ZOPFAN dan menyertai SEAMEO.","isCorrect":false,"consequence":"Itu sumbangan dalam ASEAN."},{"text":"Menubuhkan Bank Pembangunan Islam dan UIAM.","isCorrect":false,"consequence":"Itu sumbangan dalam OIC."},{"text":"Menghantar pasukan pengaman ke Namibia.","isCorrect":false,"consequence":"Itu sumbangan dalam PBB."}],"aftermath":"Nota tersalah baca dan utusan menyatakan Aparteid ditamatkan pada tahun 1989.","turns":[{"after":1,"options":[{"text":"Malaysia mengecam ketidakadilan dan memelihara alam sekitar.","isCorrect":true,"reaction":"Betul. Utusan mengangguk."},{"text":"Malaysia menyokong dasar Aparteid.","isCorrect":false,"reaction":"Malaysia mengecam dasar itu."},{"text":"Malaysia tidak peduli tentang alam sekitar.","isCorrect":false,"reaction":"Deklarasi Langkawi berkaitan pencemaran alam sekitar."}],"clue":"Mengecam ketidakadilan."}]}'),
(1015, 'e10_n2_s7', 'Kad Latar Belakang OIC', 'Baca kad dan tentukan latar belakang OIC.', '5', 'Memahami OIC: ditubuhkan 25 September 1969; Tunku Setiausaha Agung pertama; pejabat di Jeddah; 57 negara; bahasa Arab, Inggeris dan Perancis; matlamat memperkukuh perpaduan negara Islam.', '{"clueText":"Kad: OIC ditubuhkan pada 25 September 1969. Tunku Abdul Rahman dilantik sebagai Setiausaha Agung OIC yang pertama. Pejabat OIC terletak di Jeddah, Arab Saudi dan OIC dianggotai 57 buah negara. Bahasa rasminya ialah bahasa Arab, Inggeris dan Perancis.","options":[{"text":"Setiausaha Agung pertama; pejabat di Jeddah; 57 negara.","isCorrect":true},{"text":"Presiden pertama; pejabat di New York; 193 negara.","isCorrect":false,"consequence":"Itu maklumat PBB."},{"text":"Pengerusi pertama; pejabat di London; 54 negara.","isCorrect":false,"consequence":"Itu maklumat Komanwel."},{"text":"Setiausaha Agung pertama; pejabat di Jakarta; 10 negara.","isCorrect":false,"consequence":"Itu maklumat ASEAN."}],"aftermath":"Kad tersalah baca dan wakil mencatat Tunku sebagai Presiden PBB.","turns":[{"after":2,"options":[{"text":"OIC mengukuhkan perpaduan dan mengeratkan hubungan negara Islam.","isCorrect":true,"reaction":"Betul. Tunku tersenyum."},{"text":"OIC hanya untuk negara tertentu di Asia Tenggara.","isCorrect":false,"reaction":"OIC dianggotai 57 negara."},{"text":"OIC bertujuan menjejaskan keamanan.","isCorrect":false,"reaction":"Matlamat OIC mengekalkan keamanan."}],"clue":"OIC: perpaduan negara Islam."}]}'),
(1016, 'e10_n2_s8', 'Sumbangan Malaysia dalam OIC', 'Padankan sumbangan Malaysia dalam OIC dengan butirannya.', '4', 'Memahami sumbangan: Bank Pembangunan Islam 1975; isu Bosnia dan Herzegovina 1991; UIAM 1983; tuan rumah persidangan OIC 1974 dan 2003; menyokong perjuangan rakyat Palestin.', '{"pairs":[{"text":"Membantu penubuhan","pair":1},{"text":"Bank Pembangunan Islam pada tahun 1975","pair":1},{"text":"Menangani isu","pair":2},{"text":"Bosnia dan Herzegovina pada tahun 1991","pair":2},{"text":"Menubuhkan","pair":3},{"text":"Universiti Islam Antarabangsa Malaysia (UIAM) pada tahun 1983","pair":3},{"text":"Menjadi tuan rumah Persidangan OIC","pair":4},{"text":"Tahun 1974 dan 2003","pair":4},{"text":"Menyokong penuh","pair":5},{"text":"Perjuangan rakyat Palestin menentang kekejaman Israel","pair":5}],"aftermath":"Kad bertukar dan UIAM dicatat ditubuhkan pada 1975. Wakil OIC menggeleng.","turns":[{"after":1,"options":[{"text":"Pelibatan Malaysia dalam OIC penting untuk mengekalkan keamanan dunia.","isCorrect":true,"reaction":"Betul. Laporan tahunan siap."},{"text":"Pelibatan Malaysia dalam OIC tidak penting.","isCorrect":false,"reaction":"Wakil OIC menggeleng."},{"text":"Pelibatan Malaysia hanya melalui peperangan.","isCorrect":false,"reaction":"Malaysia mengamalkan rundingan perdamaian."}],"clue":"Rundingan perdamaian mengekalkan keamanan."}]}'),
(1017, 'e10_n3_s1', 'Misi Pasukan Pengaman PBB', 'Susun penglibatan Malaysia dalam PBB mengikut urutan tahun.', '1', 'Menyusun kronologi: Congo (1961), ahli tidak tetap Majlis Keselamatan (1965), Namibia (1989), pemerhati Iran-Iraq (1990), Somalia dan Bosnia (1992), Lubnan (2007).', '{"timelineItems":[{"id":1,"year":"1961","text":"Malaysia menghantar pasukan pengaman PBB ke Congo","why":"Misi pengaman pertama."},{"id":2,"year":"1965","text":"Malaysia menjadi ahli tidak tetap Majlis Keselamatan PBB","why":"Kali pertama daripada empat penggal."},{"id":3,"year":"1989","text":"Malaysia menghantar pasukan pengaman ke Namibia","why":"Selepas Congo."},{"id":4,"year":"1990","text":"Pasukan pemerhati PBB dihantar ke sempadan Iran-Iraq","why":"Sebagai pemerhati."},{"id":5,"year":"1992","text":"Pasukan pengaman dihantar ke Somalia dan Bosnia dan Herzegovina","why":"Dua misi dalam tahun yang sama."},{"id":6,"year":"2007","text":"Pasukan pengaman Malaysia bertugas di Lubnan","why":"Misi yang terkini dalam unit ini."}],"aftermath":"Urutan tersilap dan pameran mencatat Lubnan sebelum Congo. Pelawat tertawa.","turns":[{"after":1,"options":[{"text":"Pasukan pengaman menjaga keamanan dunia dan mengharumkan nama Malaysia.","isCorrect":true,"reaction":"Betul. Pelawat bertepuk tangan."},{"text":"Pasukan pengaman bertugas untuk menjajah negara lain.","isCorrect":false,"reaction":"Itu salah. Mereka menjaga keamanan."},{"text":"Malaysia tidak pernah menghantar pasukan pengaman.","isCorrect":false,"reaction":"Banyak misi dalam sejarah."}],"clue":"Pasukan pengaman: keamanan dunia."}]}'),
(1018, 'e10_n3_s2', 'Sumbangan Malaysia dalam PBB', 'Padankan sumbangan Malaysia dalam PBB dengan butirannya.', '4', 'Memahami sumbangan: isu Palestin-Israel; Persidangan Antarabangsa Dadah di Vienna Jun 1987 (Tun Dr. Mahathir Presiden); \'Pendidikan untuk Semua\' melalui UNESCO; ahli tidak tetap Majlis Keselamatan (1965, 1989-1990, 1999-2000, 2015-2016).', '{"pairs":[{"text":"Konflik Palestin-Israel","pair":1},{"text":"Mencari penyelesaian yang adil dan berkekalan","pair":1},{"text":"Penyalahgunaan dadah","pair":2},{"text":"Persidangan Antarabangsa Dadah di Vienna, Jun 1987","pair":2},{"text":"Presiden Persidangan Dadah 1987","pair":3},{"text":"Tun Dr. Mahathir Mohamad, Perdana Menteri keempat","pair":3},{"text":"Mutu pendidikan","pair":4},{"text":"Memperjuangkan prinsip Pendidikan untuk Semua melalui UNESCO","pair":4},{"text":"Majlis Keselamatan PBB","pair":5},{"text":"Ahli tidak tetap 1965, 1989-1990, 1999-2000 dan 2015-2016","pair":5}],"aftermath":"Kad bertukar dan pelawat membawa pulang cerita bahawa Tunku mempengerusikan persidangan dadah.","turns":[{"after":1,"options":[{"text":"Pandangan Malaysia disuarakan menerusi persidangan PBB.","isCorrect":true,"reaction":"Betul. Pelawat bersetuju."},{"text":"Malaysia tidak perlu bersuara di PBB.","isCorrect":false,"reaction":"Pelawat menggeleng. Pandangan Malaysia disuarakan."},{"text":"Sumbangan Malaysia hanya melalui ketenteraan.","isCorrect":false,"reaction":"Sumbangan juga dalam pendidikan dan dadah."}],"clue":"Malaysia bersuara di PBB."}]}'),
(1019, 'e10_n3_s3', 'Kad Faedah Penyertaan dalam PBB', 'Baca kad dan tentukan faedah penyertaan Malaysia dalam PBB.', '5', 'Memahami faedah PBB: memelihara dan mempertahankan kepentingan negara dalam keputusan PBB; meneruskan peranan aktif dengan menyumbang pendapat; meningkatkan komitmen menangani isu.', '{"clueText":"Kad: Penyertaan dalam PBB membolehkan Malaysia memelihara dan mempertahankan kepentingan negara dalam sebarang keputusan yang diambil oleh PBB. Malaysia juga meneruskan peranan aktif dengan menyumbang pendapat dan pandangan dalam pelbagai isu global serta meningkatkan komitmen menangani pelbagai isu.","options":[{"text":"Mempertahankan kepentingan negara dan menyumbang pandangan dalam isu global.","isCorrect":true},{"text":"Mendapat pinjaman daripada Bank Pembangunan Islam.","isCorrect":false,"consequence":"Itu faedah dalam OIC."},{"text":"Menembusi pasaran negara Komanwel.","isCorrect":false,"consequence":"Itu faedah dalam Komanwel."},{"text":"Membina RECSAM di Pulau Pinang.","isCorrect":false,"consequence":"Itu faedah dalam ASEAN."}],"aftermath":"Kad tersalah baca dan pelawat menyangka PBB memberi pinjaman Bank Pembangunan Islam.","turns":[{"after":1,"options":[{"text":"Pelibatan aktif memberi faedah kepada negara dan dunia.","isCorrect":true,"reaction":"Betul. Pelawat mencatat."},{"text":"Pelibatan aktif tidak penting kerana negara kecil.","isCorrect":false,"reaction":"Pelawat menggeleng. Suara Malaysia dihargai."},{"text":"Pelibatan aktif hanya bertujuan mengejar nama.","isCorrect":false,"reaction":"Tujuannya menyumbang kepada isu global."}],"clue":"Pelibatan aktif memberi faedah."}]}'),
(1020, 'e10_n3_s4', 'Tokoh Malaysia di PBB', 'Padankan tokoh Malaysia dengan jawatan atau pengiktirafannya di PBB.', '4', 'Memahami pengiktirafan: Tan Sri Razali Ismail (Pengerusi Majlis Keselamatan 1989-1990; Pengerusi Perhimpunan Agung sesi ke-51 1996-1997); Datuk Dr. Mazlan Othman (Pengarah Hal Ehwal Angkasa Lepas PBB 1999-2002 dan 2007); Pasukan Pengaman diiktiraf melalui sijil dan pingat.', '{"pairs":[{"text":"Tan Sri Razali Ismail: 1989-1990","pair":1},{"text":"Pengerusi Majlis Keselamatan PBB","pair":1},{"text":"Tan Sri Razali Ismail: 1996-1997","pair":2},{"text":"Pengerusi Perhimpunan Agung PBB sesi ke-51","pair":2},{"text":"Datuk Dr. Mazlan Othman","pair":3},{"text":"Pengarah Hal Ehwal Angkasa Lepas PBB","pair":3},{"text":"Pasukan Pengaman PBB","pair":4},{"text":"Diiktiraf melalui sijil dan pingat perkhidmatan PBB","pair":4}],"aftermath":"Tokoh dipadankan dengan jawatan yang salah dan pameran mencatat Mazlan Othman Pengerusi Majlis Keselamatan.","turns":[{"after":1,"options":[{"text":"Pengiktirafan itu perlu dikekalkan demi nama baik negara.","isCorrect":true,"reaction":"Betul. Pelawat bangga."},{"text":"Pengiktirafan itu tidak perlu dikekalkan.","isCorrect":false,"reaction":"Nama baik negara bergantung pada pengiktirafan."},{"text":"Pengiktirafan itu hanya untuk individu.","isCorrect":false,"reaction":"Ia mengangkat nama Malaysia."}],"clue":"Kekalkan pengiktirafan."}]}'),
(1021, 'e10_n3_s5', 'Cari Bukti Warisan Dunia', 'Cari empat bukti Tapak Warisan Dunia UNESCO di Malaysia.', '2', 'Memahami Tapak Warisan Dunia: alam semula jadi (Taman Negara Gunung Mulu, Taman Kinabalu, 2000) dan kebudayaan (Melaka dan George Town 2008; Lembah Lenggong 2012).', '{"bgImage":"../assets/gameAsset/background/ruang_unesco.png","hotspots":[{"name":"Gunung dalam kaca: Taman Kinabalu di Sabah, warisan alam 2000","top":"50%","left":"8%"},{"name":"Gua batu kapur: Taman Negara Gunung Mulu di Sarawak, warisan 2000","top":"52%","left":"88%"},{"name":"Peta bandar dalam kaca: Melaka dan George Town, warisan 2008","top":"56%","left":"72%"},{"name":"Hologram tengah: Warisan Arkeologi Lembah Lenggong, 2012","top":"42%","left":"50%"}],"aftermath":"Bukti tidak ditemui dan pelawat menyangka Malaysia tiada tapak warisan dunia.","turns":[{"after":1,"options":[{"text":"Warisan dunia perlu dipelihara demi generasi akan datang.","isCorrect":true,"reaction":"Betul. Pelawat bersetuju."},{"text":"Warisan dunia tidak perlu dipelihara.","isCorrect":false,"reaction":"Pemandu menegur. Ia pengiktirafan antarabangsa."},{"text":"Warisan dunia hanya milik satu negeri.","isCorrect":false,"reaction":"Ia warisan negara dan dunia."}],"clue":"Pelihara warisan dunia."}]}'),
(1022, 'e10_n3_s6', 'Kategori Pengiktirafan UNESCO', 'Padankan kategori pengiktirafan UNESCO dengan contohnya.', '4', 'Memahami kategori: Tapak Warisan Dunia Alam Semula Jadi (Mulu, Kinabalu); Tapak Warisan Dunia Kebudayaan (Melaka dan George Town, Lenggong); Daftar Memori Dunia (Hikayat Hang Tuah, Sulalatus Salatin, Batu Bersurat Terengganu); Daftar Warisan Budaya Tidak Ketara (Makyung, Dondang Sayang, Silat, Wangkang).', '{"pairs":[{"text":"Tapak Warisan Dunia Alam Semula Jadi","pair":1},{"text":"Taman Negara Gunung Mulu dan Taman Kinabalu","pair":1},{"text":"Tapak Warisan Dunia Kebudayaan","pair":2},{"text":"Melaka, George Town dan Lembah Lenggong","pair":2},{"text":"Daftar Memori Dunia","pair":3},{"text":"Hikayat Hang Tuah, Sulalatus Salatin dan Batu Bersurat Terengganu","pair":3},{"text":"Daftar Warisan Budaya Tidak Ketara","pair":4},{"text":"Makyung, Dondang Sayang, Silat dan Wangkang","pair":4}],"aftermath":"Kategori bertukar dan pelawat menyangka Hikayat Hang Tuah ialah tapak warisan alam.","turns":[{"after":1,"options":[{"text":"Pengiktirafan UNESCO menunjukkan warisan Malaysia dihargai dunia.","isCorrect":true,"reaction":"Betul. Pelawat bangga."},{"text":"Pengiktirafan UNESCO tidak berkaitan dengan warisan.","isCorrect":false,"reaction":"Ia mengiktiraf tapak, memori dan budaya."},{"text":"Hanya bangunan boleh diiktiraf UNESCO.","isCorrect":false,"reaction":"Manuskrip, tarian dan seni mempertahankan diri turut diiktiraf."}],"clue":"UNESCO menghargai warisan."}]}'),
(1023, 'e10_n3_s7', 'Garis Masa Pengiktirafan UNESCO', 'Susun pengiktirafan UNESCO kepada Malaysia mengikut urutan tahun.', '1', 'Menyusun kronologi: Mulu dan Kinabalu (2000), Hikayat Hang Tuah (2001), Makyung (2005), Melaka dan George Town (2008), Lenggong (2012), Dondang Sayang (2018), Silat (2019), Wangkang (2020).', '{"timelineItems":[{"id":1,"year":"2000","text":"Taman Negara Gunung Mulu dan Taman Kinabalu diiktiraf Tapak Warisan Dunia","why":"Kategori alam semula jadi."},{"id":2,"year":"2001","text":"Hikayat Hang Tuah diiktiraf Daftar Memori Dunia","why":"Kategori memori dunia."},{"id":3,"year":"2005","text":"Makyung diiktiraf Daftar Warisan Budaya Tidak Ketara","why":"Kategori warisan tidak ketara."},{"id":4,"year":"2008","text":"Melaka dan George Town diiktiraf Tapak Warisan Dunia kebudayaan","why":"Bandar bersejarah Selat Melaka."},{"id":5,"year":"2012","text":"Warisan Arkeologi Lembah Lenggong diiktiraf","why":"Tapak warisan di Perak."},{"id":6,"year":"2018","text":"Dondang Sayang diiktiraf Daftar Warisan Budaya Tidak Ketara","why":"Seni muzik tradisional."},{"id":7,"year":"2019","text":"Silat diiktiraf Daftar Warisan Budaya Tidak Ketara","why":"Seni mempertahankan diri."},{"id":8,"year":"2020","text":"Wangkang diiktiraf Daftar Warisan Budaya Tidak Ketara","why":"Pengiktirafan terkini dalam unit ini."}],"aftermath":"Garis masa tersilap dan pameran mencatat Wangkang diiktiraf sebelum Hikayat Hang Tuah.","turns":[{"after":1,"options":[{"text":"Kita perlu berusaha mengekalkan pengiktirafan daripada negara luar.","isCorrect":true,"reaction":"Betul. Pelawat mengangguk."},{"text":"Pengiktirafan tidak perlu dikekalkan selepas diterima.","isCorrect":false,"reaction":"Pengiktirafan perlu dikekalkan."},{"text":"Pengiktirafan datang tanpa usaha.","isCorrect":false,"reaction":"Ia hasil sumbangan dan penjagaan warisan."}],"clue":"Kekalkan pengiktirafan."}]}'),
(1024, 'e10_n3_s8', 'Kad Hubungan Baik dengan Negara Luar', 'Baca kad dan tentukan sebab Malaysia menjalin hubungan baik dengan negara luar.', '5', 'Memahami: Malaysia mengamalkan dasar berbaik-baik dengan semua negara; bertanggungjawab memastikan kestabilan politik, kemajuan ekonomi dan keharmonian rakyat; tidak mengadakan hubungan diplomatik dengan Israel dan Korea Utara.', '{"clueText":"Kad: Malaysia mengamalkan dasar berbaik-baik dengan semua negara dan bertanggungjawab memastikan kestabilan politik, kemajuan ekonomi serta keharmonian rakyatnya. Hubungan baik dengan negara luar penting bagi menjamin keselamatan dan kemakmuran rakyat serta negara.","options":[{"text":"Menjamin keselamatan dan kemakmuran rakyat serta negara.","isCorrect":true},{"text":"Menyebabkan negara dipinggirkan.","isCorrect":false,"consequence":"Kad menyatakan sebaliknya."},{"text":"Mengurangkan kestabilan politik.","isCorrect":false,"consequence":"Hubungan baik memastikan kestabilan."},{"text":"Menjejaskan kemajuan ekonomi.","isCorrect":false,"consequence":"Hubungan baik menyokong kemajuan ekonomi."}],"aftermath":"Kad tersalah baca dan pelawat menyangka hubungan antarabangsa tidak memberi manfaat.","turns":[{"after":1,"options":[{"text":"Hubungan baik menjadikan negara dihormati dan disegani.","isCorrect":true,"reaction":"Betul. Pelawat tersenyum."},{"text":"Hubungan baik hanya penting untuk negara besar.","isCorrect":false,"reaction":"Malaysia juga mendapat faedah."},{"text":"Hubungan baik tidak mempengaruhi keselamatan.","isCorrect":false,"reaction":"Ia menjamin keselamatan dan kemakmuran."}],"clue":"Hubungan baik: dihormati dan disegani."}]}'),
(1025, 'e10_n3_s9', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan peranannya.', '4', 'Memahami cinta akan negara: diri memelihara hubungan baik dengan jiran; masyarakat membentuk perpaduan dan faedah untuk semua; negara dihormati serta disegani melalui kesepakatan.', '{"pairs":[{"text":"Diri","pair":1},{"text":"Memelihara hubungan baik dengan jiran supaya keharmonian dapat dipupuk","pair":1},{"text":"Masyarakat","pair":2},{"text":"Hubungan baik membentuk perpaduan dan mendatangkan faedah kepada semua","pair":2},{"text":"Negara","pair":3},{"text":"Kesepakatan menjadikan negara dihormati serta disegani","pair":3}],"aftermath":"Padanan tersilap dan pelawat pulang tanpa memahami peranan masing-masing.","turns":[{"after":1,"options":[{"text":"Pandangan dan sumbangan Malaysia memastikan kesejahteraan dan keamanan dunia.","isCorrect":true,"reaction":"Betul. Pameran ditutup dengan tepukan."},{"text":"Hubungan baik tidak perlu dijaga selepas merdeka.","isCorrect":false,"reaction":"Pelibatan bermula sejak merdeka dan perlu dikekalkan."},{"text":"Hubungan baik hanya urusan kerajaan.","isCorrect":false,"reaction":"Diri, masyarakat dan negara bertanggungjawab."}],"clue":"Hubungan baik tanggungjawab bersama."}]}');

-- --------------------------------------------------------

--
-- Table structure for table `questcompletion`
--

DROP TABLE IF EXISTS `questcompletion`;
CREATE TABLE `questcompletion` (
  `studentID` varchar(20) NOT NULL,
  `questID` bigint(20) NOT NULL,
  `completedAt` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Table structure for table `question`
--

DROP TABLE IF EXISTS `question`;
CREATE TABLE `question` (
  `questionID` bigint(20) NOT NULL,
  `bankID` bigint(20) NOT NULL,
  `questionText` text NOT NULL,
  `option_a` varchar(255) NOT NULL,
  `option_b` varchar(255) NOT NULL,
  `option_c` varchar(255) NOT NULL,
  `option_d` varchar(255) NOT NULL,
  `correctAnswer` char(1) NOT NULL,
  `hint` varchar(255) DEFAULT NULL,
  `explanation` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `question`
--

INSERT INTO `question` (`questionID`, `bankID`, `questionText`, `option_a`, `option_b`, `option_c`, `option_d`, `correctAnswer`, `hint`, `explanation`) VALUES
(101, 1, 'Siapakah yang mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat pada tahun 1887?', 'Lord Brassey', 'Malcolm MacDonald', 'Ibrahim Haji Yaakob', 'Harun Aminurrashid', 'A', 'Beliau Pengarah British North Borneo Company.', 'Lord Brassey, Pengarah Syarikat Borneo Utara British, mencadangkannya pada 1887. Ini cadangan paling awal.'),
(102, 1, 'Konsep Melayu Raya diperjuangkan oleh tokoh tempatan pada tahun berapa?', '1887', '1951', '1955', '1938', 'D', 'Konsep ini merangkumi Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia.', 'Ibrahim Haji Yaakob dan Harun Aminurrashid memperjuangkan Melayu Raya pada 1938.'),
(103, 1, 'Siapakah Gabenor Jeneral British di Asia Tenggara yang berbincang tentang penggabungan pada tahun 1951?', 'Lord Brassey', 'Tunku Abdul Rahman', 'Malcolm MacDonald', 'Lord Cobbold', 'C', 'Namanya bermula dengan huruf M.', 'Malcolm MacDonald berbincang dengan pemimpin Persekutuan Tanah Melayu, Sarawak, Sabah dan Singapura pada 1951.'),
(104, 1, 'Siapakah yang memberikan idea penggabungan Sarawak, Sabah, Singapura dan Brunei dengan Persekutuan Tanah Melayu pada tahun 1955?', 'Lord Brassey', 'Tunku Abdul Rahman Putra Al-Haj', 'Malcolm MacDonald', 'Ibrahim Haji Yaakob', 'B', 'Ketika itu beliau Ketua Menteri Persekutuan Tanah Melayu.', 'Tunku Abdul Rahman mencadangkannya pada 1955.'),
(105, 1, 'Manakah susunan idea pembentukan Malaysia yang betul mengikut kronologi?', '1887, 1938, 1951, 1955', '1951, 1887, 1938, 1955', '1938, 1887, 1955, 1951', '1955, 1951, 1938, 1887', 'A', 'Mulakan dengan tarikh paling lama dahulu.', 'Susunannya ialah 1887 Brassey, 1938 Melayu Raya, 1951 MacDonald dan 1955 Tunku.'),
(106, 1, 'Apakah sebab pembentukan Malaysia yang berkait dengan ancaman komunis di Singapura dan Sarawak?', 'Mempercepat kemerdekaan', 'Membangunkan sosioekonomi', 'Mencapai keseimbangan kaum', 'Menjamin keselamatan negara', 'D', 'Komunis mengancam keselamatan.', 'Ancaman komunis dapat dibendung melalui pembentukan Malaysia, iaitu sebab menjamin keselamatan negara.'),
(107, 1, 'Mengapakah penggabungan Persekutuan Tanah Melayu dengan Singapura sahaja tidak digalakkan?', 'Singapura terlalu jauh daripada Tanah Melayu', 'Singapura tidak mempunyai pelabuhan dagang', 'Bilangan penduduk antara kaum tidak seimbang', 'Penduduk Singapura menolak penggabungan', 'C', 'Fikirkan jumlah penduduk pelbagai kaum.', 'Penggabungan dengan Singapura sahaja menyebabkan ketidakseimbangan antara kaum. Sarawak, Sabah dan Brunei membantu mengimbanginya.'),
(108, 1, 'Pembentukan Malaysia dapat meningkatkan taraf hidup rakyat melalui pembangunan infrastruktur. Ini sebab...', 'menjamin keselamatan negara', 'membangunkan sosioekonomi', 'mencapai keseimbangan kaum', 'mempercepat kemerdekaan', 'B', 'Taraf hidup dan ekonomi ialah sosioekonomi.', 'Penggabungan mempercepat pembangunan infrastruktur, sosial dan ekonomi serta meningkatkan taraf hidup rakyat.'),
(109, 1, 'Apakah sebab pembentukan Malaysia yang memerlukan permuafakatan dan sokongan semua pihak?', 'Mempercepat kemerdekaan', 'Menjamin keselamatan negara', 'Mencapai keseimbangan kaum', 'Membangunkan sosioekonomi', 'A', 'Sarawak, Sabah, Singapura dan Brunei mahu merdeka.', 'Pembentukan Malaysia mampu mempercepat kemerdekaan Sarawak, Sabah, Singapura dan Brunei, dan ia memerlukan permuafakatan semua pihak.'),
(110, 1, 'Di manakah Tunku Abdul Rahman mengumumkan cadangan pembentukan Malaysia pada 27 Mei 1961?', 'Kuala Lumpur', 'Kuching', 'Kota Kinabalu', 'Hotel Adelphi, Singapura', 'D', 'Ia sebuah hotel di Singapura.', 'Cadangan diumumkan di Hotel Adelphi, Singapura.'),
(111, 1, 'Apakah tujuan lawatan Tunku Abdul Rahman ke Sarawak pada Julai 1961?', 'Menandatangani perjanjian rasmi', 'Memungut cukai daripada penduduk', 'Menerangkan idea Malaysia kepada pemimpin tempatan', 'Membuka sekolah baharu di kampung', 'C', 'Beliau datang untuk bercakap dan mendengar.', 'Lawatan itu bertujuan menerangkan idea pembentukan Malaysia kepada pemimpin tempatan.'),
(112, 1, 'Apakah tujuan Jawatankuasa Setia Kawan Malaysia (JSKM) ditubuhkan pada 23 Julai 1961?', 'Merangka perlembagaan', 'Meyakinkan pemimpin Sarawak dan Sabah', 'Mengadakan referendum di Singapura', 'Mengesahkan persetujuan rakyat', 'B', 'Jawatankuasa ini untuk memujuk pemimpin Borneo.', 'JSKM ditubuhkan untuk meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.'),
(113, 1, 'Siapakah yang mencadangkan penubuhan JSKM?', 'Donald Stephens', 'Tun Abdul Razak', 'Datu Bandar Abang Haji Mustapha', 'Lee Kuan Yew', 'A', 'Beliau pemimpin UNKO dari Sabah.', 'Donald Stephens (Tun Muhammad Fuad Stephens), pemimpin UNKO, mencadangkan JSKM.'),
(114, 1, 'Apakah tujuan Suruhanjaya Cobbold dibentuk pada 17 Januari 1962?', 'Menyediakan rangka perlembagaan negara', 'Mengesahkan persetujuan melalui PBB', 'Menandatangani perjanjian di London', 'Mendapatkan reaksi penduduk Sarawak dan Sabah', 'D', 'Suruhanjaya ini turun mendengar penduduk.', 'Suruhanjaya Cobbold dibentuk bagi mendapatkan reaksi penduduk Sarawak dan Sabah.'),
(115, 1, 'Apakah dapatan laporan Suruhanjaya Cobbold pada 21 Jun 1962?', 'Semua penduduk Borneo menolak', 'Satu pertiga penduduk menyokong', 'Dua pertiga penduduk menyokong', 'Penduduk tidak memberi pandangan', 'C', 'Pecahan dua daripada tiga.', 'Laporan mendapati dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia.'),
(116, 1, 'Siapakah antara ahli Suruhanjaya Cobbold yang mewakili Persekutuan Tanah Melayu?', 'Tun V.T. Sambanthan dan Lee Kuan Yew', 'Ghazali Shafie dan Wong Pow Nee', 'Donald Stephens dan Tun Jugah', 'Tun Abdul Razak dan Datu Mustapha', 'B', 'Seorang daripada MCA.', 'Tun Muhammad Ghazali Shafie dan Tan Sri Wong Pow Nee menganggotai Suruhanjaya Cobbold.'),
(117, 1, 'Apakah tujuan Jawatankuasa Antara Kerajaan (JAK) yang bermesyuarat pada 30 Ogos 1962?', 'Merangka perlembagaan bagi melindungi Sarawak dan Sabah', 'Menandatangani Perjanjian Malaysia di London', 'Memasyhurkan Malaysia di empat bandar', 'Mengesahkan persetujuan rakyat melalui PBB', 'A', 'JAK ialah jawatankuasa antara kerajaan.', 'JAK dianggotai wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah untuk menyediakan rangka perlembagaan.'),
(118, 1, 'Apakah yang diadakan di Singapura pada 1 September 1962?', 'Pemasyhuran Malaysia', 'Mesyuarat UNMM', 'Pelancaran JSKM', 'Referendum', 'D', 'Pemungutan suara rakyat.', 'Referendum, iaitu pemungutan suara rakyat, diadakan di Singapura dan rakyat bersetuju dengan pembentukan Malaysia.'),
(119, 1, 'Di manakah Perjanjian Malaysia ditandatangani pada 9 Julai 1963?', 'Hotel Adelphi, Singapura', 'Stadium Merdeka, Kuala Lumpur', 'Marlborough House, London', 'City Hall, Singapura', 'C', 'Ia terletak di ibu negara British.', 'Perjanjian Malaysia ditandatangani di Marlborough House, London.'),
(120, 1, 'Apakah tujuan United Nations Malaysia Mission (UNMM) diwujudkan pada 12 Ogos 1963?', 'Menyediakan perlembagaan baharu Malaysia', 'Mengesahkan persetujuan penduduk Sarawak dan Sabah', 'Menyerahkan laporan kepada kerajaan British', 'Menandatangani perjanjian di London', 'B', 'PBB ingin tahu suara rakyat Borneo.', 'PBB mewujudkan UNMM untuk mengesahkan persetujuan penduduk Sarawak dan Sabah.'),
(121, 1, 'Manakah bandar yang menjadi tempat Pemasyhuran Malaysia pada 16 September 1963?', 'Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall Singapura', 'Kuala Lumpur, Ipoh, Johor Bahru dan Pulau Pinang', 'Kuching, Brunei, Sandakan, Miri dan Labuan', 'London, Singapura, Kuching, Manila dan Jakarta', 'A', 'Empat tempat untuk empat wilayah.', 'Pemasyhuran diadakan di Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.'),
(122, 1, 'Siapakah Perdana Menteri Persekutuan Tanah Melayu yang mengetuai perwakilan ke London?', 'Tun Abdul Razak', 'Lee Kuan Yew', 'Tun V.T. Sambanthan', 'Tunku Abdul Rahman Putra Al-Haj', 'D', 'Pemimpin UMNO yang digelar Bapa Kemerdekaan.', 'Tunku Abdul Rahman mengetuai perwakilan Persekutuan Tanah Melayu dalam Perjanjian Malaysia di London.'),
(123, 1, 'Siapakah pemimpin PESAKA yang menganggotai JSKM dan menandatangani Perjanjian Malaysia di London?', 'Tan Sri Stephen Kalong Ningkan', 'Datu Bandar Abang Haji Mustapha', 'Tun Temenggung Jugah anak Barieng', 'Tun Datu Mustapha', 'C', 'Beliau Temenggung masyarakat Iban.', 'Tun Temenggung Jugah anak Barieng ialah pemimpin PESAKA.'),
(124, 1, 'Siapakah pemimpin USNO yang memberikan penjelasan tentang pembentukan Malaysia kepada penduduk Sabah?', 'Donald Stephens', 'Tun Datu Mustapha Datu Harun', 'Lee Kuan Yew', 'Tun Abdul Razak', 'B', 'USNO ialah parti Sabah.', 'Tun Datu Mustapha Datu Harun memimpin USNO dan menjelaskan Malaysia kepada penduduk Sabah.'),
(125, 1, 'Siapakah yang menyokong idea pembentukan Malaysia bagi membendung ideologi komunis di Singapura?', 'Lee Kuan Yew', 'Tun Temenggung Jugah', 'Stephen Kalong Ningkan', 'Tan Sri Wong Pow Nee', 'A', 'Beliau pemimpin PAP.', 'Lee Kuan Yew, pemimpin PAP, menyokong pembentukan Malaysia bagi membendung ideologi komunis.'),
(126, 1, 'Mengapakah SUPP menolak rancangan pembentukan Malaysia?', 'Menyokong penjajahan British ke atas Borneo', 'Mahu bergabung dengan Filipina secara terus', 'Tidak mahu kemerdekaan untuk Sarawak', 'Mahu persekutuan sendiri dengan Brunei, Sarawak dan Borneo Utara', 'D', 'SUPP mahu persekutuan sendiri.', 'SUPP mahu membentuk persekutuan sendiri yang terdiri daripada Brunei, Sarawak dan Borneo Utara.'),
(127, 1, 'Apakah yang dilakukan Indonesia terhadap Malaysia dari tahun 1963 hingga 1966?', 'Menandatangani perjanjian damai', 'Menyertai Malaysia', 'Mengisytiharkan konfrontasi', 'Menghantar bantuan makanan', 'C', 'Indonesia menganggap Malaysia mengancam kedudukannya.', 'Indonesia mengisytiharkan konfrontasi terhadap Malaysia kerana menganggap pembentukannya mengancam kedudukan negaranya.'),
(128, 1, 'Negara manakah yang mendakwa Sabah sebahagian daripada wilayahnya?', 'Indonesia', 'Filipina', 'Brunei', 'Singapura', 'B', 'Ia terletak di utara Sabah.', 'Filipina mendakwa Sabah sebahagian daripada wilayahnya.'),
(129, 1, 'Manakah negeri yang menolak penyertaan dalam Malaysia dan wilayah yang berpisah pada tahun 1965?', 'Brunei menolak dan Singapura berpisah', 'Sarawak menolak dan Sabah berpisah', 'Singapura menolak dan Brunei berpisah', 'Sabah menolak dan Sarawak berpisah', 'A', 'Satu menolak, satu berpisah.', 'Brunei menolak penyertaan, dan Singapura berpisah daripada Malaysia pada 1965.'),
(130, 1, 'Apakah peribahasa yang menggambarkan hubungan Malaysia dengan Indonesia dan Filipina yang kembali pulih?', 'Hendak seribu daya, tak hendak seribu dalih', 'Bagai aur dengan tebing', 'Sedikit-sedikit lama-lama menjadi bukit', 'Carik-carik bulu ayam, bercantum juga', 'D', 'Selepas bercerai, bercantum semula.', 'Hubungan tegang dapat dipulihkan melalui permuafakatan pemimpin.'),
(131, 1, 'Apakah yang disambut pada 16 September setiap tahun?', 'Hari Kebangsaan', 'Hari Pahlawan', 'Hari Malaysia', 'Hari Kemerdekaan', 'C', 'Ia hari Malaysia dibentuk.', 'Hari Malaysia disambut sebagai tanda syukur dan bangga atas permuafakatan dan perpaduan rakyat.'),
(132, 1, 'Manakah kesan pembentukan Malaysia?', 'Menambah ancaman luar negara', 'Mengekalkan keamanan dan mewujudkan permuafakatan', 'Memecahkan perpaduan rakyat berbilang kaum', 'Menghentikan pembangunan negara', 'B', 'Pilih kesan yang baik.', 'Pembentukan Malaysia mengekalkan keamanan, mewujudkan permuafakatan dan menyatupadukan rakyat berbilang kaum.'),
(133, 1, 'Mengapakah kita wajar menghargai jasa dan kebijaksanaan pemimpin yang memperjuangkan pembentukan Malaysia?', 'Supaya perpaduan kaum dapat dikekalkan', 'Supaya mereka mendapat gaji yang tinggi', 'Supaya negara lain menyerang kita', 'Supaya rakyat tidak bersatu padu', 'A', 'Jawapan yang melibatkan perpaduan.', 'Menghargai jasa pemimpin mengekalkan kestabilan perpaduan, kestabilan ekonomi dan politik, serta membentuk masyarakat yang positif.'),
(201, 2, 'Apakah maksud perkataan Siam prow-lowy yang dikaitkan dengan asal nama Perlis?', 'Air jernih', 'Kelapa hanyut', 'Pokok tinggi', 'Sungai besar', 'B', 'Ia berkaitan dengan buah di laut.', 'Prow-lowy dalam bahasa Siam bermaksud kelapa hanyut.'),
(202, 2, 'Nama Kedah dikatakan berasal daripada perkataan Kheddah yang bermaksud...', 'perangkap gajah', 'cawan berkaki', 'batu permata', 'kilatan ikan', 'A', 'Haiwan besar di hutan.', 'Kheddah bermaksud perangkap gajah. Perkataan Arab Qadah pula bermaksud cawan atau gelas berkaki.'),
(203, 2, 'Apakah nama asal Pulau Pinang?', 'Tanjong Pinang', 'Pulau Pinang Lama', 'Pulo Pinang Besar', 'Pulo Ka Satu', 'D', 'Nama asalnya bermula dengan Pulo.', 'Nama asal Pulau Pinang ialah Pulo Ka Satu. Orang Melayu Kedah menggelarnya Tanjong Penaga.'),
(204, 2, 'Nama Perak dikatakan bersempena dengan...', 'pokok mahang', 'sembilan luak', 'kilatan ikan di dalam air', 'pelanduk putih', 'C', 'Ia berkilau seperti logam.', 'Perak dikaitkan dengan kilatan ikan di dalam air atau bijih timah putih yang berkilat.'),
(205, 2, 'Pokok apakah yang dikaitkan dengan asal nama Selangor?', 'Pokok mahang', 'Pokok mentagau', 'Pokok penaga', 'Pokok Melaka', 'B', 'Ia banyak di kuala sungai.', 'Pokok mentagau di kuala sungai menjadi kuala selangau, kemudian Kuala Selangor.'),
(206, 2, 'Negeri Sembilan terbentuk daripada gabungan sembilan buah...', 'luak', 'daerah', 'pulau', 'mukim', 'A', 'Ia istilah Minangkabau.', 'Negeri Sembilan terbentuk daripada sembilan luak pada tahun 1773.'),
(207, 2, 'Manakah antara berikut ialah luak asal Negeri Sembilan?', 'Kedah', 'Terengganu', 'Kota Bharu', 'Sungai Ujong', 'D', 'Ia luak yang namanya mengandungi sungai.', 'Luak asal termasuk Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.'),
(208, 2, 'Mengikut sumber Arab, nama Melaka disebut Malakat yang bermaksud...', 'batu permata', 'tempat kapal singgah', 'perhimpunan para pedagang', 'pelangi', 'C', 'Pedagang Arab menggunakan nama ini.', 'Malakat bermaksud perhimpunan para pedagang.'),
(209, 2, 'Apakah maksud Jauhar yang dikaitkan dengan asal nama Johor?', 'Perangkap gajah', 'Batu permata yang bernilai', 'Pokok mahang', 'Pisang saba', 'B', 'Perkataan Arab.', 'Jauhar ialah perkataan Arab bagi batu permata yang bernilai.'),
(210, 2, 'Apakah nama Pahang dalam Sulalatus Salatin?', 'Inderapura atau Pura', 'Ujong Tanah', 'Malakat', 'Kadaram', 'A', 'Pura bermaksud bandar.', 'Dalam Sulalatus Salatin, Pahang dikenali sebagai Inderapura atau Pura.'),
(211, 2, 'Nama Terengganu dikatakan berasal daripada sebutan taring anu yang dijumpai di...', 'Pulau Pinang', 'Pulau Langkawi', 'Pulau Labuan', 'Pulau Duyong', 'D', 'Ia pulau di Terengganu.', 'Taring besar seperti gading gajah dijumpai di Pulau Duyong.'),
(212, 2, 'Nama Kelantan dikatakan berasal daripada perkataan kilatan yang dilihat oleh masyarakat...', 'Minangkabau', 'Siam', 'Melayu Patani', 'Jawa', 'C', 'Mereka dari selatan Thailand.', 'Kilatan ialah cahaya terang yang dilihat oleh masyarakat Melayu Patani.'),
(213, 2, 'Sarawak dikaitkan dengan Sungai Serak dan sejenis galian bijih yang disebut...', 'timah', 'sarawak', 'emas', 'besi', 'B', 'Nama galian itu sama dengan nama negeri.', 'Sungai Serak berubah menjadi Sungai Sarawak sempena bijih sarawak.'),
(214, 2, 'Nama Sabah dikaitkan dengan...', 'pisang saba', 'pokok mahang', 'pokok penaga', 'buah pinang', 'A', 'Ia ditanam di pantai barat.', 'Pisang saba banyak ditanam di pantai barat Sabah.'),
(215, 2, 'Apakah asal nama Kuala Lumpur?', 'Pokok mentagau', 'Perhimpunan pedagang', 'Batu permata', 'Muara sungai berlumpur akibat melombong bijih timah', 'D', 'Sungai Gombak dan Klang.', 'Kuala Lumpur dikaitkan dengan muara yang berlumpur akibat melombong bijih timah.'),
(216, 2, 'Nama Putrajaya bersempena dengan nama...', 'Tun Abdul Razak', 'Tun Hussein Onn', 'Tunku Abdul Rahman Putra', 'Tun Mahathir', 'C', 'Perdana Menteri pertama.', 'Putra daripada Tunku Abdul Rahman Putra; jaya bermaksud kemenangan.'),
(217, 2, 'Labuan dikatakan berasal daripada perkataan labuhan yang bermaksud...', 'batu permata', 'tempat persinggahan kapal', 'pokok mahang', 'perangkap gajah', 'B', 'Kapal berhenti di sini.', 'Labuhan ialah tempat persinggahan kapal.'),
(218, 2, 'Apakah gelaran ketua negeri di Perlis?', 'Raja', 'Sultan', 'Yang di-Pertuan Besar', 'Yang di-Pertua Negeri', 'A', 'Hanya satu negeri menggunakannya.', 'Perlis menggunakan gelaran Raja.'),
(219, 2, 'Apakah gelaran ketua negeri bagi negeri Selangor, Johor dan Pahang?', 'Raja', 'Yang di-Pertuan Besar', 'Yang di-Pertua Negeri', 'Sultan', 'D', 'Tujuh negeri menggunakannya.', 'Sultan digunakan di Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan.'),
(220, 2, 'Negeri manakah yang ketuanya bergelar Yang di-Pertuan Besar?', 'Perlis', 'Melaka', 'Negeri Sembilan', 'Sabah', 'C', 'Negeri bersejarah dengan sembilan luak.', 'Yang di-Pertuan Besar digunakan di Negeri Sembilan.'),
(221, 2, 'Manakah empat negeri yang ketuanya bergelar Yang di-Pertua Negeri?', 'Perlis, Kedah, Perak dan Johor', 'Pulau Pinang, Melaka, Sarawak dan Sabah', 'Selangor, Pahang, Kelantan dan Terengganu', 'Negeri Sembilan, Melaka, Johor dan Sabah', 'B', 'Dua di Semenanjung dan dua di Borneo.', 'Yang di-Pertua Negeri digunakan di Pulau Pinang, Melaka, Sarawak dan Sabah.'),
(222, 2, 'Siapakah ketua negeri bagi Wilayah Persekutuan?', 'Yang di-Pertuan Agong', 'Sultan Selangor', 'Perdana Menteri', 'Yang di-Pertua Negeri', 'A', 'Pemerintah tertinggi negara.', 'Ketua negeri bagi Wilayah Persekutuan ialah Yang di-Pertuan Agong.'),
(223, 2, 'Apakah kepentingan taat setia dan menghormati ketua negeri?', 'Menambah cukai negeri', 'Mengurangkan kawalan undang-undang', 'Menghentikan sekolah', 'Memastikan kestabilan negara', 'D', 'Hubungkan dengan keamanan.', 'Menghormati ketua negeri memastikan kestabilan dan memperkukuh sistem pemerintahan.'),
(224, 2, 'Apakah ibu negeri bagi negeri Perlis dan bandar dirajanya?', 'Alor Setar dan Anak Bukit', 'Kuantan dan Pekan', 'Kangar dan Arau', 'Ipoh dan Kuala Kangsar', 'C', 'Ibu negeri bermula huruf K.', 'Perlis: Kangar (ibu negeri) dan Arau (bandar diraja).'),
(225, 2, 'Apakah ibu negeri dan bandar diraja bagi Pahang?', 'Kangar dan Arau', 'Kuantan dan Pekan', 'Seremban dan Seri Menanti', 'Shah Alam dan Klang', 'B', 'Ibu negeri di pantai timur.', 'Pahang: Kuantan dan Pekan.'),
(226, 2, 'Negeri Sembilan mempunyai bandar diraja bernama...', 'Seri Menanti', 'Arau', 'Klang', 'Pekan', 'A', 'Ia terletak di kawasan istana lama.', 'Ibu negeri Seremban, bandar diraja Seri Menanti.'),
(227, 2, 'Siapakah antara berikut yang tidak mempunyai ibu negeri dan bandar diraja?', 'Perlis', 'Kedah', 'Johor', 'Wilayah Persekutuan', 'D', 'Ketuanya Yang di-Pertuan Agong.', 'Wilayah Persekutuan tidak mempunyai ibu negeri dan bandar diraja.'),
(228, 2, 'Apakah bandar diraja?', 'Bandar yang paling besar di negeri', 'Pusat pentadbiran negeri', 'Bandar yang terdapat warisan sejarah seperti istana dan muzium', 'Bandar pelabuhan antarabangsa', 'C', 'Fikirkan istana dan galeri.', 'Bandar diraja ialah bandar yang terdapat warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan galeri.'),
(229, 2, 'Lagu negeri Sabah ialah...', 'Ibu Pertiwiku', 'Sabah Tanah Airku', 'Untuk Negeri Kita', 'Melaka Maju Jaya', 'B', 'Nama lagu menyebut nama negeri.', 'Lagu negeri Sabah ialah Sabah Tanah Airku.'),
(230, 2, 'Lagu negeri Sarawak ialah...', 'Ibu Pertiwiku', 'Sabah Tanah Airku', 'Lagu Bangsa Johor', 'Duli Yang Maha Mulia', 'A', 'Lagu bertema tanah air.', 'Lagu negeri Sarawak ialah Ibu Pertiwiku.'),
(231, 2, 'Negeri manakah yang lagunya ialah Duli Yang Maha Mulia?', 'Johor', 'Perak', 'Kedah', 'Selangor', 'D', 'Ia negeri di Lembah Klang.', 'Lagu negeri Selangor ialah Duli Yang Maha Mulia.'),
(232, 2, 'Apakah lagu negeri Perak?', 'Allah Selamatkan Sultan Mahkota', 'Allah Selamatkan Sultan Kami', 'Allah Lanjutkan Usia Sultan', 'Berkatlah Yang di-Pertuan Besar', 'C', 'Menyebut usia sultan.', 'Lagu negeri Perak ialah Allah Lanjutkan Usia Sultan.'),
(233, 2, 'Lagu Berkatlah Yang di-Pertuan Besar ialah lagu negeri...', 'Johor', 'Negeri Sembilan', 'Selangor', 'Perlis', 'B', 'Menyebut gelaran ketua negeri.', 'Lagu negeri Negeri Sembilan ialah Berkatlah Yang di-Pertuan Besar.'),
(234, 2, 'Mengapakah kita perlu menghormati lambang negeri?', 'Ia melambangkan kedaulatan dan memupuk perpaduan', 'Supaya mendapat wang', 'Supaya negeri lain takut', 'Kerana ia hiasan sahaja', 'A', 'Hubungkan dengan identiti dan perpaduan.', 'Menghormati lambang negeri menghargai sejarah, memupuk perpaduan dan menjaga keamanan.'),
(235, 2, 'Bagaimanakah kita menunjukkan rasa bangga terhadap warisan negeri-negeri di Malaysia?', 'Membiarkan istana lama rosak', 'Melupakan lagu negeri', 'Menolak lambang negeri lain', 'Menghargai, mencintai dan mempromosikan warisan', 'D', 'Pilih tindakan yang menjaga warisan.', 'Menghargai, mencintai dan mempromosikan warisan serta memulihara kesan tinggalan menunjukkan rasa bangga.'),
(236, 2, 'Apakah tajuk lagu negeri Perlis?', 'Allah Selamatkan Sultan Mahkota', 'Allah Lanjutkan Usia Sultan', 'Aamiin-Aamiin', 'Untuk Negeri Kita', 'C', 'Negeri ini ketuanya bergelar Raja.', 'Lagu negeri Perlis ialah Aamiin-Aamiin.'),
(237, 2, 'Apakah tajuk lagu negeri Kedah?', 'Aamiin-Aamiin', 'Allah Selamatkan Sultan Mahkota', 'Allah Lanjutkan Usia Sultan', 'Untuk Negeri Kita', 'B', 'Tajuknya menyebut mahkota.', 'Lagu negeri Kedah ialah Allah Selamatkan Sultan Mahkota.'),
(238, 2, 'Apakah tajuk lagu negeri Pulau Pinang?', 'Untuk Negeri Kita', 'Melaka Maju Jaya', 'Lagu Bangsa Johor', 'Ibu Pertiwiku', 'A', 'Ketuanya bergelar Yang di-Pertua Negeri.', 'Lagu negeri Pulau Pinang ialah Untuk Negeri Kita.'),
(239, 2, 'Apakah tajuk lagu negeri Melaka?', 'Lagu Bangsa Johor', 'Duli Yang Maha Mulia', 'Untuk Negeri Kita', 'Melaka Maju Jaya', 'D', 'Tajuknya menyebut nama negeri itu.', 'Lagu negeri Melaka ialah Melaka Maju Jaya.'),
(240, 2, 'Apakah tajuk lagu negeri Johor?', 'Melaka Maju Jaya', 'Berkatlah Yang di-Pertuan Besar', 'Lagu Bangsa Johor', 'Duli Yang Maha Mulia', 'C', 'Tajuknya menyebut nama negeri itu.', 'Lagu negeri Johor ialah Lagu Bangsa Johor.'),
(241, 2, 'Apakah tajuk lagu negeri Pahang?', 'Selamat Sultan', 'Allah Selamatkan Sultan Kami', 'Allah Lanjutkan Usia Sultan', 'Sabah Tanah Airku', 'B', 'Tajuknya menyebut \'Kami\'.', 'Lagu negeri Pahang ialah Allah Selamatkan Sultan Kami.'),
(242, 2, 'Dua negeri manakah yang menggunakan tajuk lagu Selamat Sultan?', 'Terengganu dan Kelantan', 'Pahang dan Terengganu', 'Pahang dan Kelantan', 'Kedah dan Perak', 'A', 'Kedua-duanya di pantai timur, tetapi bukan Pahang.', 'Terengganu dan Kelantan sama-sama menggunakan tajuk Selamat Sultan.'),
(243, 2, 'Apakah tajuk lagu Wilayah Persekutuan?', 'Sabah Tanah Airku', 'Ibu Pertiwiku', 'Untuk Negeri Kita', 'Maju dan Sejahtera', 'D', 'Tajuknya tentang kemajuan.', 'Lagu Wilayah Persekutuan ialah Maju dan Sejahtera.'),
(244, 2, 'Apakah ibu negeri bagi Sarawak dan Sabah?', 'Kangar dan Arau', 'Kuantan dan Pekan', 'Kuching dan Kota Kinabalu', 'Ipoh dan Kuala Kangsar', 'C', 'Kedua-duanya di Borneo.', 'Ibu negeri Sarawak ialah Kuching dan Sabah ialah Kota Kinabalu.'),
(245, 2, 'Apakah ibu negeri dan bandar diraja bagi Selangor?', 'Seremban dan Seri Menanti', 'Shah Alam dan Klang', 'Johor Bahru dan Bandar Maharani', 'Ipoh dan Kuala Kangsar', 'B', 'Bandar diraja bermula dengan huruf K.', 'Ibu negeri Selangor ialah Shah Alam dan bandar dirajanya Klang.'),
(246, 2, 'Apakah ibu negeri dan bandar diraja bagi Johor?', 'Johor Bahru dan Bandar Maharani', 'Seremban dan Seri Menanti', 'Shah Alam dan Klang', 'Kangar dan Arau', 'A', 'Bandar dirajanya bermula dengan \'Bandar\'.', 'Ibu negeri Johor ialah Johor Bahru dan bandar dirajanya Bandar Maharani.'),
(247, 2, 'Apakah ibu negeri dan bandar diraja bagi Kedah?', 'Kangar dan Arau', 'Ipoh dan Kuala Kangsar', 'Kuantan dan Pekan', 'Alor Setar dan Anak Bukit', 'D', 'Bandar dirajanya bermula dengan \'Anak\'.', 'Ibu negeri Kedah ialah Alor Setar dan bandar dirajanya Anak Bukit.'),
(248, 2, 'Apakah ibu negeri dan bandar diraja bagi Perak?', 'Alor Setar dan Anak Bukit', 'Kangar dan Arau', 'Ipoh dan Kuala Kangsar', 'Shah Alam dan Klang', 'C', 'Bandar dirajanya bermula dengan \'Kuala\'.', 'Ibu negeri Perak ialah Ipoh dan bandar dirajanya Kuala Kangsar.'),
(249, 2, 'Apakah ibu negeri bagi Terengganu dan Kelantan?', 'Kuantan dan Pekan', 'Kuala Terengganu dan Kota Bharu', 'Kangar dan Arau', 'Seremban dan Seri Menanti', 'B', 'Peta tidak menanda bandar diraja bagi kedua-duanya.', 'Ibu negeri Terengganu ialah Kuala Terengganu dan Kelantan ialah Kota Bharu.'),
(250, 2, 'Apakah ibu negeri Pulau Pinang dan Melaka?', 'George Town dan Bandar Melaka', 'Ipoh dan Seremban', 'Alor Setar dan Kuantan', 'Shah Alam dan Klang', 'A', 'Peta tidak menanda bandar diraja bagi kedua-duanya.', 'Ibu negeri Pulau Pinang ialah George Town dan Melaka ialah Bandar Melaka.'),
(251, 2, 'Pada tahun berapakah sembilan luak asal Negeri Sembilan dicatat?', '1877', '1887', '1673', '1773', 'D', 'Ia tahun abad ke-18.', 'Tahun sembilan luak asal Negeri Sembilan ialah 1773.'),
(252, 2, 'Dokumen \'Maharajah of Sabah\' bertarikh pada tahun...', '1773', '1887', '1877', '1963', 'C', 'Ia tahun abad ke-19.', 'Dokumen Maharajah of Sabah bertarikh 1877.'),
(253, 2, 'Binatang apakah yang menendang anjing pemburu Parameswara di bawah pokok?', 'Gajah putih', 'Pelanduk putih', 'Harimau putih', 'Kijang', 'B', 'Ia binatang kecil dan berani.', 'Pelanduk putih menendang anjing pemburu Parameswara.'),
(254, 2, 'Apakah gelaran ketua negeri Perak dan Kedah?', 'Sultan', 'Raja', 'Yang di-Pertuan Besar', 'Yang di-Pertua Negeri', 'A', 'Gelaran paling banyak digunakan.', 'Perak dan Kedah menggunakan gelaran Sultan.'),
(255, 2, 'Apakah maksud Kadaram atau kalagam dalam tulisan Tamil?', 'Nama Perlis', 'Nama Sabah', 'Nama Johor', 'Nama Kedah', 'D', 'Berkait dengan negeri di utara.', 'Kadaram atau kalagam ialah nama Kedah dalam tulisan Tamil.'),
(256, 2, 'Apakah yang dilambangkan oleh bendera, lagu dan jata sesebuah negeri?', 'Cukai negeri', 'Keluasan negeri', 'Identiti dan lambang kemegahan negeri', 'Bilangan penduduk', 'C', 'Ia berkait dengan rasa bangga.', 'Bendera, lagu dan jata ialah identiti dan lambang kemegahan negeri.'),
(301, 3, 'Bilakah Rukun Negara diisytiharkan?', '31 Ogos 1957', '16 September 1963', '31 Ogos 1970', '13 Mei 1969', 'C', 'Bersempena ulang tahun Hari Kebangsaan yang ke-13.', 'Rukun Negara diisytiharkan pada 31 Ogos 1970.'),
(302, 3, 'Siapakah yang memasyhurkan Rukun Negara sebagai Pengisytiharan Diraja?', 'Perdana Menteri', 'Yang di-Pertuan Agong Keempat', 'Yang di-Pertuan Agong Pertama', 'Tunku Abdul Rahman', 'B', 'Beliau Tuanku Sultan Ismail Nasiruddin Shah.', 'Rukun Negara dimasyhurkan oleh Yang di-Pertuan Agong Keempat.'),
(303, 3, 'Apakah nama badan yang mengambil alih pentadbiran negara selepas peristiwa 13 Mei 1969?', 'MAGERAN', 'MAPEN', 'JSKM', 'JAK', 'A', 'Majlis Gerakan Negara.', 'MAGERAN mentadbir negara selepas peristiwa 13 Mei 1969.'),
(304, 3, 'Apakah jawatankuasa yang merangka dan memperkenalkan Rukun Negara?', 'Jawatankuasa Antara Kerajaan', 'Jawatankuasa Setia Kawan Malaysia', 'Suruhanjaya Cobbold', 'Jawatankuasa Rukun Negara di bawah MAPEN', 'D', 'Ia di bawah Majlis Perundingan Negara.', 'Jawatankuasa Rukun Negara di bawah MAPEN merangkanya pada 4 Mac 1970.'),
(305, 3, 'Berapakah jumlah wakil dalam MAPEN?', '33 orang', '99 orang', '66 orang', '13 orang', 'C', 'Nombor enam enam.', 'MAPEN dianggotai 66 orang wakil daripada pelbagai pihak.'),
(306, 3, 'Manakah tiga sebab pengenalan Rukun Negara?', 'Kekurangan hasil padi, banjir dan kemarau', 'Perbezaan kegiatan ekonomi, pengasingan tempat tinggal, perbezaan fahaman politik', 'Perang dengan negara jiran, penyakit dan kemiskinan', 'Kekurangan sekolah, jalan raya dan elektrik', 'B', 'Tiga sebab berkait dengan kaum.', 'Tiga sebab ialah perbezaan kegiatan ekonomi, pengasingan tempat tinggal dan perbezaan fahaman politik.'),
(307, 3, 'Apakah kegiatan ekonomi utama orang Melayu pada zaman British?', 'Pertanian sara diri', 'Perlombongan dan perniagaan', 'Perladangan', 'Perkapalan', 'A', 'Mereka tinggal di kampung.', 'Orang Melayu menjalankan pertanian sara diri.'),
(308, 3, 'Apakah kegiatan ekonomi utama orang Cina pada zaman British?', 'Pertanian sara diri', 'Perladangan', 'Perikanan', 'Perlombongan dan perniagaan', 'D', 'Mereka tinggal di bandar.', 'Orang Cina menjalankan perlombongan dan perniagaan.'),
(309, 3, 'Orang India pada zaman British banyak bekerja dalam bidang...', 'perlombongan', 'perniagaan di bandar', 'perladangan', 'pertanian sara diri', 'C', 'Mereka tinggal di ladang.', 'Orang India banyak bekerja dalam perladangan.'),
(310, 3, 'Mengapakah pengasingan tempat tinggal menjadi sebab pengenalan Rukun Negara?', 'Perpaduan yang kukuh antara kaum', 'Kurangnya peluang berinteraksi antara masyarakat', 'Keharmonian semua kaum', 'Permuafakatan antara kaum', 'B', 'Mereka jarang berjumpa.', 'Pengasingan tempat tinggal menyebabkan kurangnya peluang berinteraksi.'),
(311, 3, 'Peristiwa rusuhan kaum yang membawa kepada Rukun Negara berlaku pada...', '13 Mei 1969', '31 Ogos 1957', '16 September 1963', '4 Mac 1970', 'A', 'Tahun 1969.', 'Perbezaan fahaman politik mencetuskan rusuhan kaum 13 Mei 1969.'),
(312, 3, 'Berapakah matlamat dan prinsip Rukun Negara?', 'Tiga matlamat dan lima prinsip', 'Lima matlamat dan tiga prinsip', 'Sepuluh matlamat dan sepuluh prinsip', 'Lima matlamat dan lima prinsip', 'D', 'Dua-dua lima.', 'Rukun Negara mempunyai lima matlamat dan lima prinsip.'),
(313, 3, 'Manakah ialah matlamat Rukun Negara?', 'Menambah cukai', 'Menghalang pembangunan', 'Mencapai perpaduan yang lebih erat', 'Mengurangkan kebebasan beragama', 'C', 'Matlamat pertama.', 'Matlamat pertama ialah mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat.'),
(314, 3, 'Membina masyarakat progresif yang menggunakan sains dan teknologi moden ialah matlamat ke...', 'satu', 'lima', 'dua', 'tiga', 'B', 'Ia matlamat terakhir.', 'Matlamat kelima ialah membina masyarakat progresif yang menggunakan sains dan teknologi moden.'),
(315, 3, 'Apakah prinsip pertama Rukun Negara?', 'Kepercayaan kepada Tuhan', 'Kesetiaan kepada Raja dan Negara', 'Keluhuran Perlembagaan', 'Kedaulatan Undang-undang', 'A', 'Berkaitan agama.', 'Prinsip pertama ialah Kepercayaan kepada Tuhan.'),
(316, 3, 'Siapakah Ketua Utama Negara Malaysia?', 'Perdana Menteri', 'Sultan Selangor', 'Ketua Hakim Negara', 'Yang di-Pertuan Agong', 'D', 'Pemerintah tertinggi negara.', 'Yang di-Pertuan Agong ialah Ketua Utama Negara.'),
(317, 3, 'Apakah maksud keluhuran perlembagaan?', 'Perdana Menteri boleh mengubah undang-undang sesuka hati', 'Undang-undang hanya untuk rakyat biasa', 'Perlembagaan Persekutuan ialah undang-undang tertinggi negara', 'Perlembagaan boleh diabaikan', 'C', 'Tiada yang mengatasinya.', 'Keluhuran perlembagaan bermaksud Perlembagaan Persekutuan ialah undang-undang tertinggi.'),
(318, 3, 'Setiap rakyat perlu menghormati dan mematuhi undang-undang. Ini prinsip...', 'Kesopanan dan kesusilaan', 'Kedaulatan undang-undang', 'Kepercayaan kepada Tuhan', 'Kesetiaan kepada raja dan negara', 'B', 'Prinsip keempat.', 'Kedaulatan undang-undang bermaksud setiap rakyat menghormati dan mematuhi undang-undang.'),
(319, 3, 'Prinsip yang berperanan membentuk masyarakat untuk menghormati amalan beragama masyarakat lain ialah...', 'Kepercayaan kepada Tuhan', 'Keluhuran perlembagaan', 'Kedaulatan undang-undang', 'Kesopanan dan kesusilaan', 'A', 'Hormat amalan agama.', 'Kepercayaan kepada Tuhan melahirkan rakyat yang menghormati amalan beragama masyarakat lain.'),
(320, 3, 'Kesopanan dan kesusilaan bermaksud...', 'Hukuman bagi pesalah', 'Pelaburan asing', 'Kekayaan negara', 'Amalan nilai murni yang melambangkan keperibadian rakyat', 'D', 'Prinsip kelima.', 'Kesopanan dan kesusilaan ialah amalan nilai murni.'),
(321, 3, 'Apakah peranan Rukun Negara dalam kehidupan harian?', 'Menambah jurang kaum', 'Memisahkan agama', 'Mewujudkan rakyat bersatu padu dan bertoleransi', 'Mengurangkan cukai', 'C', 'Hubungkan dengan perpaduan.', 'Rukun Negara berperanan mewujudkan rakyat yang bersatu padu dan bersikap toleransi.'),
(322, 3, 'Manakah ialah lambang kedaulatan negara?', 'Pakaian, kasut dan beg', 'Jalur Gemilang, Jata Negara dan lagu Negaraku', 'Kereta, basikal dan motosikal', 'Rumah, kedai dan ladang', 'B', 'Bendera, jata dan lagu.', 'Rakyat patriotik menghormati Jalur Gemilang, Jata Negara dan lagu Negaraku.'),
(323, 3, 'Mengapakah rakyat perlu mematuhi undang-undang?', 'Mewujudkan keamanan dan kesejahteraan', 'Menambah jenayah', 'Mengurangkan sekolah', 'Menghentikan pembangunan', 'A', 'Fikirkan keselamatan negara.', 'Kepatuhan kepada undang-undang mewujudkan keamanan dan kesejahteraan.'),
(324, 3, 'Apakah yang dimaksudkan dengan integriti?', 'Sikap tamak', 'Sikap malas', 'Sikap sombong', 'Sikap kejujuran yang tulen dan tidak berubah', 'D', 'Contoh: tidak meniru dalam peperiksaan.', 'Integriti bermaksud kejujuran yang tulen dan tidak berubah.'),
(325, 3, 'Manakah contoh amalan integriti?', 'Meniru supaya lulus', 'Memberi rasuah', 'Tidak meniru dalam peperiksaan', 'Menipu kawan', 'C', 'Kejujuran dalam peperiksaan.', 'Tidak meniru dalam peperiksaan ialah contoh integriti.'),
(326, 3, 'Bagaimanakah agama dapat mengelakkan keruntuhan moral?', 'Menghentikan sekolah', 'Membentuk masyarakat yang patuh ajaran agama', 'Menambah kekayaan', 'Menghalang pelajaran', 'B', 'Fikirkan nilai agama.', 'Masyarakat yang beragama dapat mengelakkan dengki, rasuah, dadah dan keruntuhan moral.'),
(327, 3, 'Mengapakah rakyat perlu menghormati budaya kaum lain?', 'Memupuk perpaduan dan toleransi', 'Supaya menang pertandingan', 'Supaya mendapat hadiah', 'Supaya diam sahaja', 'A', 'Hubungkan dengan perpaduan.', 'Rakyat dibimbing menghormati budaya kaum lain melalui Rukun Negara.'),
(328, 3, 'Rukun Negara berperanan membentuk masyarakat yang cinta akan negara. Ini disebut masyarakat...', 'pesimis', 'individualistik', 'terasing', 'patriotik', 'D', 'Cinta negara.', 'Masyarakat patriotik cinta negara, taat setia dan sanggup berkorban.'),
(401, 4, 'Kaum manakah merupakan kaum terbesar di Sarawak?', 'Bidayuh', 'Melanau', 'Kenyah', 'Iban', 'D', 'Pakaian pua kumbu dan Hari Gawai.', 'Iban ialah kaum terbesar di Sarawak.'),
(402, 4, 'Kaum manakah merupakan kaum terbesar di Sabah?', 'Bajau', 'Murut', 'Kadazandusun', 'Rungus', 'C', 'Pesta Kaamatan.', 'Kadazandusun ialah kaum terbesar di Sabah.'),
(403, 4, 'Pakaian tradisional wanita Cina yang biasanya diperbuat daripada kain lembut seperti sutera ialah...', 'sari', 'ceongsam', 'kebaya', 'baju kurung', 'B', 'Pasangannya changsan untuk lelaki.', 'Ceongsam ialah pakaian tradisional wanita Cina; changsan untuk lelaki.'),
(404, 4, 'Kebanyakan kaum India bertutur dalam bahasa...', 'Tamil', 'Punjabi', 'Hokkien', 'Kristang', 'A', 'Ada juga Telugu dan Malayalam.', 'Kebanyakan kaum India bertutur dalam bahasa Tamil.'),
(405, 4, 'Tiga kumpulan terbesar Orang Asli di Semenanjung ialah...', 'Iban, Bidayuh dan Melanau', 'Murut, Rungus dan Bajau', 'Baba, Chetti dan Serani', 'Negrito (Semang), Senoi dan Melayu Proto', 'D', 'Salah satunya Semang.', 'Orang Asli terbahagi kepada Negrito (Semang), Senoi dan Melayu Proto.'),
(406, 4, 'Apakah dialek yang digunakan oleh masyarakat Baba dan Nyonya?', 'Melayu Sarawak', 'Bahasa Cina', 'Melayu Baba', 'Hokkien', 'C', 'Dialek tempatan di Melaka.', 'Baba dan Nyonya bertutur menggunakan dialek Melayu Baba.'),
(407, 4, 'Kaum Serani bertutur menggunakan bahasa...', 'Punjabi dan bahasa Siam', 'Kristang dan bahasa Inggeris', 'Tamil dan Telugu', 'Mandarin dan Hakka', 'B', 'Hasil perkahwinan orang Portugis dengan penduduk tempatan.', 'Kaum Serani menggunakan bahasa Kristang dan bahasa Inggeris.'),
(408, 4, 'Apakah nama tarian tradisional kaum Serani?', 'Branyo dan frapeirra', 'Zapin dan joget', 'Sumazau dan magunatip', 'Kuda kepang dan ulek mayang', 'A', 'Tarian yang paling popular.', 'Tarian yang paling popular dalam kaum Serani ialah branyo dan frapeirra.'),
(409, 4, 'Kaum manakah menyambut perayaan Songkran dan beribadat di wat?', 'Sikh', 'Chetti', 'Serani', 'Siam', 'D', 'Petempatan di Kedah, Kelantan, Perlis, Pulau Pinang dan Perak.', 'Kaum Siam menyambut Songkran dan menghadiri upacara di wat.'),
(410, 4, 'Apakah bahasa ibunda masyarakat Sikh?', 'Bahasa Tamil', 'Bahasa Kristang', 'Bahasa Punjabi', 'Bahasa Iban', 'C', 'Mereka memakai sarban.', 'Bahasa Punjabi ialah bahasa ibunda masyarakat Sikh.'),
(411, 4, 'Apakah pekerjaan masyarakat Cina pada masa dahulu?', 'Petani dan nelayan', 'Pelombong dan peniaga', 'Penjawat awam dan guru', 'Pengutip hasil hutan dan pemburu', 'B', 'Tinggal di pekan dan bandar.', 'Masyarakat Cina dahulu tinggal di pekan dan bandar sebagai pelombong dan peniaga.'),
(412, 4, 'Antara berikut, yang manakah kegiatan ekonomi masyarakat Orang Asli dahulu?', 'Berburu dan kegiatan kraf tangan', 'Pelombongan bijih timah', 'Penternakan haiwan secara besar-besaran', 'Perniagaan di bandar', 'A', 'Mereka tinggal di pedalaman.', 'Orang Asli dahulu berburu, mengutip hasil hutan dan membuat kraf tangan.'),
(413, 4, 'Kaum Iban dan Bisaya di Sarawak dahulu tinggal berhampiran...', 'pesisir pantai dan menjadi nelayan', 'pedalaman sebagai pemburu', 'bandar sebagai peniaga', 'lembah sungai dan menjadi petani', 'D', 'Dekat sungai.', 'Kaum Iban dan Bisaya tinggal berhampiran lembah sungai dan menjadi petani.'),
(414, 4, 'Kaum manakah di Sabah bekerja sebagai petani atau nelayan?', 'Murut', 'Rungus', 'Bajau', 'Kadazandusun', 'C', 'Terdapat juga di pesisir.', 'Kaum Bajau di Sabah bekerja sebagai petani atau nelayan.'),
(415, 4, 'Apakah perubahan petempatan masyarakat Malaysia sehingga kini?', 'Masih berasingan mengikut kaum', 'Tidak lagi berasingan mengikut kegiatan ekonomi', 'Semua tinggal di ladang', 'Semua tinggal di pedalaman', 'B', 'Toleransi dan kemakmuran.', 'Kini tidak berlaku pengasingan petempatan mengikut kegiatan ekonomi.'),
(416, 4, 'Gambus diperbuat daripada kayu keras seperti kayu pokok...', 'nangka', 'meranti', 'belian', 'merbau', 'A', 'Pokok yang berbuah besar.', 'Gambus diperbuat daripada kayu keras seperti kayu pokok nangka.'),
(417, 4, 'Alat muzik Melayu yang diperbuat daripada logam, lazimnya perak, ialah...', 'angklung', 'geduk', 'gambus', 'nafiri', 'D', 'Bahagian serombongnya agak leper.', 'Nafiri diperbuat daripada logam, lazimnya perak.'),
(418, 4, 'Alat muzik manakah dimainkan oleh masyarakat India?', 'Sape', 'Sompoton', 'Veenai', 'Geduk', 'C', 'Mempunyai tujuh tali logam.', 'Veenai ialah alat muzik masyarakat India; pullangkulal, talam dan mattalam juga.'),
(419, 4, 'Alat muzik bertali yang banyak dimainkan oleh kaum Kayan, Kelabit dan Kenyah ialah...', 'engkerurai', 'sape', 'tontog', 'kulintangan', 'B', 'Diperbuat daripada kayu meranti.', 'Sape banyak dimainkan oleh kaum Kayan, Kelabit dan Kenyah.'),
(420, 4, 'Kulintangan banyak dimainkan oleh kaum...', 'Bajau dan Kadazandusun', 'Iban dan Melanau', 'Melayu dan Cina', 'Sikh dan Siam', 'A', 'Sekumpulan gong kecil.', 'Kulintangan banyak dimainkan oleh kaum Bajau dan Kadazandusun.'),
(421, 4, 'Tarian yang disebut sumazau oleh kaum Kadazan dan sumayau oleh kaum Dusun ialah...', 'tarian pembuka tirai', 'tarian singa', 'tarian untuk perubatan Orang Asli', 'tarian untuk menghormati semangat padi', 'D', 'Diadakan semasa Pesta Kaamatan.', 'Sumazau dipersembahkan bagi menghormati semangat padi.'),
(422, 4, 'Tarian singa dipersembahkan antaranya untuk merayakan...', 'Hari Gawai', 'Pesta Kaamatan', 'Tahun Baharu Cina', 'Hari Raya Aidilfitri', 'C', 'Diiringi bo, gendang besar dan gong.', 'Tarian singa dipersembahkan untuk Tahun Baharu Cina dan majlis tertentu.'),
(423, 4, 'Tarian ngajat dipersembahkan semasa...', 'Pesta Kaamatan', 'Hari Gawai', 'Songkran', 'Tahun Baharu Cina', 'B', 'Tarian kaum Iban.', 'Tarian ngajat dipersembahkan semasa Hari Gawai dan upacara ritual.'),
(424, 4, 'Tarian bhangra ditarikan oleh masyarakat...', 'Sikh', 'Siam', 'Chetti', 'Melayu', 'A', 'Diiringi dram dhol.', 'Tarian bhangra ditarikan oleh masyarakat Sikh.'),
(425, 4, 'Antara berikut, yang manakah permainan laman?', 'Congkak dan paramapadham', 'Wau dan gasing', 'Tibau dan sepak manggis', 'Sepak raga dan kabaddi', 'D', 'Pilih dua permainan laman.', 'Sepak raga, chap teh dan kabaddi ialah permainan laman.'),
(426, 4, 'Congkak dan batu seremban dikategorikan sebagai...', 'permainan laman', 'permainan kawasan lapang', 'permainan anjung', 'permainan air', 'C', 'Dimainkan di bahagian rumah.', 'Congkak dan batu seremban ialah permainan anjung.'),
(427, 4, 'Wau, gasing dan tibau dikategorikan sebagai...', 'permainan anjung', 'permainan kawasan lapang', 'permainan laman', 'permainan dalam rumah', 'B', 'Memerlukan padang luas.', 'Wau, gasing, tibau dan sepak manggis ialah permainan kawasan lapang.'),
(428, 4, 'Permainan tibau dimainkan semasa Pesta Kaul oleh masyarakat...', 'Melanau', 'Iban', 'Bidayuh', 'Bajau', 'A', 'Sarawak.', 'Tibau dimainkan semasa Pesta Kaul oleh masyarakat Melanau.'),
(429, 4, 'Permainan tradisional yang dikenali juga sebagai tating lawi ialah...', 'kabaddi', 'sepak raga', 'congkak', 'chap teh', 'D', 'Bola lawi bulu ayam.', 'Chap teh disebut tating lawi oleh masyarakat Melayu.'),
(430, 4, 'Siapakah watak yang terkenal dengan kebijaksanaan dalam cerita Si Luncai dengan Labu-labunya?', 'Raja', 'Pesuruh raja', 'Si Luncai', 'Pembesar', 'C', 'Menggunakan labu air.', 'Si Luncai bijak memperdaya pesuruh raja; iktibar: jangan mempersendakan orang lain.'),
(431, 4, 'Apakah iktibar cerita Legenda Santubong Sang Puteri?', 'Jangan mempersendakan orang lain', 'Jangan bertengkar sesama sendiri', 'Menghargai asal usul keturunan', 'Menghormati orang tua', 'B', 'Mereka bertukar menjadi gunung.', 'Iktibar legenda Santubong: jangan bertengkar sesama sendiri.'),
(432, 4, 'Legenda Nunuk Ragang mengajar kita untuk...', 'menghargai asal usul keturunan', 'mempersendakan orang lain', 'bertengkar sesama sendiri', 'meninggalkan kampung halaman', 'A', 'Berkaitan kaum di Tambunan dan Ranau.', 'Iktibar Nunuk Ragang: menghargai asal usul keturunan.'),
(433, 4, 'Apakah kepentingan bertoleransi antara kaum sebagai asas perpaduan?', 'Menambah pergaduhan antara kaum', 'Mengelakkan persefahaman', 'Mengurangkan patriotisme', 'Mengekalkan keharmonian dan kesejahteraan negara', 'D', 'Pilih yang positif.', 'Toleransi memastikan tiada pergaduhan dan mengekalkan keharmonian.'),
(434, 4, 'Mengapakah kita perlu berkongsi maklumat tentang kepelbagaian kaum?', 'Menambah salah faham', 'Menjauhkan satu kaum daripada yang lain', 'Memupuk persefahaman dan mengeratkan perpaduan', 'Mengelakkan hormat-menghormati', 'C', 'Fikirkan perpaduan.', 'Berkongsi maklumat memupuk persefahaman, mengeratkan perpaduan dan hormat-menghormati.'),
(501, 5, 'Antara berikut, yang manakah agama atau ajaran di Malaysia?', 'Ajaran Konfusius', 'Ajaran Miring', 'Ajaran Tamarok', 'Ajaran Magavau', 'A', 'Ingat tujuh agama dan ajaran.', 'Agama dan ajaran: Islam, Kristian, Buddha, Hindu, Sikh, Ajaran Konfusius dan Ajaran Tao.'),
(502, 5, 'Terdapat dua teras kepercayaan dalam agama Islam, iaitu...', 'Al-Quran dan Bible', 'Karma dan Veda', 'Tao dan Analek', 'Rukun Islam dan Rukun Iman', 'D', 'Rukun apa dan rukun apa?', 'Dua teras kepercayaan dalam Islam ialah Rukun Islam dan Rukun Iman.'),
(503, 5, 'Kitab suci agama Islam ialah...', 'Bible', 'Tipitaka', 'al-Quran', 'Veda', 'C', 'Ditambah dengan Hadis.', 'Ajaran Islam berpandukan kitab suci al-Quran dan Hadis.'),
(504, 5, 'Penganut agama Kristian beribadat di gereja pada hari...', 'Jumaat', 'Ahad', 'Sabtu', 'Isnin', 'B', 'Hari yang dikhaskan.', 'Hari Ahad dikhaskan untuk aktiviti keagamaan di gereja.'),
(505, 5, 'Agama Buddha diasaskan oleh...', 'Siddharta Gautama', 'Guru Nanak', 'Lao Tzu', 'Kung Fu Tze', 'A', 'Dikenali sebagai Buddha.', 'Agama Buddha diasaskan oleh Siddharta Gautama.'),
(506, 5, 'Kitab suci agama Buddha ialah...', 'Veda', 'Analek', 'Sri Guru Granth Sahib', 'Tipitaka', 'D', 'Berasaskan Empat Kebenaran Mulia.', 'Kitab suci agama Buddha ialah Tipitaka.'),
(507, 5, 'Penganut agama Hindu mempercayai Hukum Karma yang berkaitan dengan...', 'hasil tanaman', 'cuaca', 'kelakuan manusia semasa hidup', 'bahasa pertuturan', 'C', 'Mereka percaya kelahiran semula.', 'Hukum Karma berkaitan dengan kelakuan manusia semasa hidup dan kelahiran semula.'),
(508, 5, 'Kitab suci agama Hindu dikenali sebagai...', 'Tipitaka', 'Veda', 'Bible', 'al-Quran', 'B', 'Empat huruf.', 'Kitab suci agama Hindu ialah Veda.'),
(509, 5, 'Agama Sikh diasaskan oleh...', 'Guru Nanak', 'Kung Fu Tze', 'Siddharta Gautama', 'Jesus Christ', 'A', 'Penganutnya kaum Sikh.', 'Agama Sikh diasaskan oleh Guru Nanak.'),
(510, 5, 'Tuhan yang dipercayai penganut agama Sikh dinamakan...', 'Petara', 'Kinorohingan', 'Tao', 'Waheguru', 'D', 'Satu Tuhan.', 'Penganut Sikh percaya kepada satu Tuhan bernama Waheguru.'),
