DROP TABLE IF EXISTS `scene`;
CREATE TABLE `scene` (
  `sceneID` varchar(100) NOT NULL,
  `sceneStoryline` text NOT NULL,
  `sceneOrder` int(11) NOT NULL,
  `narrativeID` bigint(20) NOT NULL,
  `asset` varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `scene`
--

INSERT INTO `scene` (`sceneID`, `sceneStoryline`, `sceneOrder`, `narrativeID`, `asset`) VALUES
('e1_n1_s1', 'Malam Mei 1961, Pejabat Perdana Menteri, Kuala Lumpur. Esok Tunku bertolak ke Singapura. Di atas meja ada peta besar dan tiga fail lama yang tersusun terbalik.', 1, 1, 'perancangan_pembentukan_malaysia.png'),
('e1_n1_s2', 'Malam yang sama. Razak menyediakan draf ucapan Parlimen, tetapi tahun 1951 dan 1955 bercampur. Sehelai telegram lama terselit di antara kertas.', 2, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s3', 'Keesokan paginya, Bilik Strategi Keselamatan, Kuala Lumpur. Lee Kuan Yew tiba membawa laporan. Peta strategi dan beberapa dokumen terletak di atas meja panjang.', 3, 1, 'bilik_strategi_keselamatan.png'),
('e1_n1_s4', 'Esoknya, bilik mesyuarat Kuala Lumpur. Wong Pow Nee dan Sambanthan datang dengan satu kerisauan: jika hanya Singapura bergabung, bilangan penduduk antara kaum tidak seimbang.', 4, 1, 'bilik_mesyuarat.png'),
('e1_n1_s5', 'Dewan Hotel Adelphi, Singapura. Kamera berkilat dan wartawan dari beberapa negara memenuhi dewan. Lee Kuan Yew duduk di sebelah Tunku dengan wajah serius.', 5, 1, 'grand_hotel_ballroom.png'),
('e1_n1_s6', 'Julai 1961, tebing sungai Sarawak. Tunku turun dari bot. Rumah panjang berdiri di seberang sungai dan penduduk berkumpul di tebing.', 6, 1, 'lawatan_ke_sarawak.png'),
('e1_n1_s7', 'Bilik JSKM, Kuala Lumpur, 23 Julai 1961. Donald Stephens dan Datu Mustapha Harun hadir bersama pemimpin Sarawak. Peta dan dokumen bertimbun di atas meja.', 7, 1, 'bilik_jskm.png'),
('e1_n1_s8', 'Bilik Suruhanjaya Cobbold, awal 1962. Fail, memorandum dan sebuah mesin taip memenuhi ruang. Lord Cobbold, Sir David Watherston dan Sir Anthony Abell sudah tiba.', 8, 1, 'bilik_suruhanjaya_cobbold.png'),
('e1_n1_s9', '21 Jun 1962, Pejabat Perdana Menteri. Laporan Suruhanjaya Cobbold terletak di atas meja panjang. Seorang wakil SUPP duduk di sudut bilik dengan muka tegang.', 9, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s10', 'Akhir Ogos 1962, bilik mesyuarat Kuala Lumpur. Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk di sekeliling meja. Sebuah buku besar terbuka di tengah.', 10, 1, 'bilik_mesyuarat_formal.png'),
('e1_n1_s11', 'Awal September 1962, Singapura. Bendera berkibar di jalan, dan orang ramai beratur untuk mengundi. Lee Kuan Yew menunggu dengan wajah tenang.', 11, 1, 'bandar.png'),
('e1_n1_s12', '9 Julai 1963, Marlborough House, London. Sebuah meja baldu merah, pen bulu dan dokumen perjanjian terletak di tengah dewan. Jugah kelihatan gementar.', 12, 1, 'marlborough_house.png'),
('e1_n1_s13', '12 Ogos 1963, bilik UNMM. Peti undi dan mesin telex memenuhi ruang. Pegawai PBB berkot biru menghitung kertas dan menaip laporan.', 13, 1, 'bilik_UNMM.png'),
('e1_n1_s14', '16 September 1963, Stadium Merdeka, Kuala Lumpur. Bendera berkibar dan orang ramai bersorak. Dokumen Pemasyhuran dalam tulisan Jawi dan Rumi terbentang di atas meja.', 14, 1, 'laungan_di_stadium_merdeka.png'),
('e1_n1_s15', 'Dewan sekolah, pagi esoknya. Kanak-kanak berkumpul di hadapan sebuah peta besar. Datu Mustapha Harun cuba menerangkan negeri mana yang bergabung, tetapi kad-kad negeri bercampur.', 15, 1, 'peta_negeri.png'),
('e1_n1_s16', '1963 hingga 1966, bilik mesyuarat Perdana Menteri. Akhbar bertimbun di atas meja dan telegram dari Jakarta dan Manila tiba satu demi satu.', 16, 1, 'bilik_mesyuarat_dunia.png'),
('e1_n1_s17', 'Pejabat Perdana Menteri, selepas Pemasyhuran. Arkib negara menunggu satu rekod lengkap dari Adelphi hingga Pemasyhuran. Ghazali membawa fail baharu.', 17, 1, 'bangunan_perlembagaan.png'),
('e1_n2_s1', 'Malam di pejabat UNKO, Sabah, sebelum satu berita besar tiba. Kipas siling berderit. Sebuah fail berhabuk dengan cop British North Borneo Company terselit di bawah meja.', 1, 2, 'bilik_mesyuarat.png'),
('e1_n2_s2', 'Meja panjang pejabat UNKO. Tiga fail terbuka di atas peta. Di dalamnya ada nama Brassey, Melayu Raya, MacDonald dan keratan akhbar 1955.', 2, 2, 'perancangan_pembentukan_malaysia.png'),
('e1_n2_s3', 'Bilik mesyuarat kecil, peta Asia Tenggara di dinding dan dokumen bertimbun di atas meja. Tun Abdul Razak tiba membawa laporan.', 3, 2, 'bilik_strategi_keselamatan.png'),
('e1_n2_s4', 'Dewan kampung penuh sesak. Kipas kayu berpusing perlahan. Orang kampung duduk bersila, dan Mustapha Harun berdiri dengan timbunan risalah di tangan.', 4, 2, 'kampung_dan_pedalaman.png'),
('e1_n2_s5', 'Pagi di pejabat UNKO. Akhbar terbentang di atas meja dan tajuk besar menarik perhatian semua orang. Mustapha Harun masuk dengan wajah cemas.', 5, 2, 'bilik_mesyuarat.png'),
('e1_n2_s6', 'Julai 1961, tebing sungai Kuching. Tunku berdiri di hadapan pemimpin Sarawak. Penduduk berkumpul di belakang mereka, dan rumah panjang berdiri di seberang sungai.', 6, 2, 'lawatan_ke_sarawak.png'),
('e1_n2_s7', '23 Julai 1961, bilik mesyuarat JSKM. Delegasi Sabah dan Sarawak duduk bersebelahan. Peta dan dokumen bertimbun di atas meja.', 7, 2, 'bilik_jskm.png'),
('e1_n2_s8', 'Dewan awam Sabah, 17 Januari 1962. Fail dan memorandum bertimbun di atas meja. Wong Pow Nee dan Ghazali Shafie duduk di meja suruhanjaya.', 8, 2, 'bilik_suruhanjaya_cobbold.png'),
('e1_n2_s9', 'Pejabat UNKO, 21 Jun 1962. Laporan Suruhanjaya Cobbold terbuka di atas meja. Seorang wakil SUPP menunggu di luar.', 9, 2, 'bilik_mesyuarat_formal.png'),
('e1_n2_s10', '30 Ogos 1962, bilik rundingan. Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk di sisi meja. Dokumen mesyuarat terletak di hadapan setiap orang.', 10, 2, 'bilik_mesyuarat_modern.png'),
('e1_n2_s11', 'Bilik tetamu, 1 September 1962. Radio bersiaran perlahan. Lee Kuan Yew mencari dokumen yang betul di tengah timbunan kertas.', 11, 2, 'bilik_mesyuarat_dunia.png'),
('e1_n2_s12', 'Balai penerangan Sabah, 9 Julai 1963. Orang ramai menunggu berita. Mustapha Harun memegang tiga telegram yang tiba serentak.', 12, 2, 'petempatan_pedalaman_sabah.png'),
('e1_n2_s13', '12 Ogos 1963, bilik UNMM. Peti undi dan mesin telex memenuhi ruang. Pegawai PBB berkot biru menghitung kertas dan menaip laporan.', 13, 2, 'bilik_UNMM.png'),
('e1_n2_s14', '16 September 1963, padang di tepi Kota Kinabalu. Bendera dinaikkan dan orang ramai berkumpul. Jugah dan Mustapha Harun hadir.', 14, 2, 'negeri_sabah.png'),
('e1_n2_s15', 'Pejabat UNKO selepas Pemasyhuran. Sebuah peta Asia Tenggara tergantung di dinding. Mustapha Harun menghulurkan sepucuk surat dari seberang laut.', 15, 2, 'bilik_mesyuarat_dunia.png'),
('e1_n2_s16', 'Pejabat UNKO, kini lengang. Fail Brassey masih di atas meja. Mustapha Harun menghulurkan kertas kosong untuk ucapan Donald.', 16, 2, 'bilik_mesyuarat.png'),
('e1_n3_s1', 'Pejabat Ghazali di Kuala Lumpur. Rak fail penuh. Tun Razak meletakkan sebuah fail lama berlabel 1938 di atas meja.', 1, 3, 'bilik_mesyuarat.png'),
('e1_n3_s2', 'Meja panjang dengan empat fail terbuka. Razak meminta Ghazali menyusun semula idea gabungan supaya kisahnya jelas.', 2, 3, 'perancangan_pembentukan_malaysia.png'),
('e1_n3_s3', 'Bilik strategi keselamatan. Peta Asia Tenggara di dinding dan kertas laporan bertaburan di atas meja.', 3, 3, 'bilik_strategi_keselamatan.png'),
('e1_n3_s4', 'Bilik mesyuarat. Razak menulis empat perkataan di papan hitam dan menyuruh Ghazali menerangkan satu persatu.', 4, 3, 'bilik_mesyuarat_formal.png'),
('e1_n3_s5', 'Satu hari sebelum pengumuman. Pembantu Tunku mencari teks ucapan yang betul di tengah timbunan kertas.', 5, 3, 'bilik_mesyuarat.png'),
('e1_n3_s6', 'Julai 1961. Ghazali menerima nota ringkas dari Kuching dengan tulisan tergesa-gesa.', 6, 3, 'lawatan_ke_sarawak.png'),
('e1_n3_s7', '23 Julai 1961, bilik JSKM. Delegasi Sabah dan Sarawak duduk bersama pegawai Persekutuan.', 7, 3, 'bilik_jskm.png'),
('e1_n3_s8', '17 Januari 1962. Suruhanjaya Cobbold bersidang. Ghazali menerima kertas arahan.', 8, 3, 'bilik_suruhanjaya_cobbold.png'),
('e1_n3_s9', '21 Jun 1962. T. Sambanthan mencari laporan yang betul. Wakil SUPP menunggu di luar.', 9, 3, 'bilik_mesyuarat_formal.png'),
('e1_n3_s10', '30 Ogos 1962. JAK bersidang. Wakil British, Persekutuan, Sarawak dan Sabah duduk di meja.', 10, 3, 'bilik_mesyuarat_formal.png'),
('e1_n3_s11', '1 September 1962. Radio melaporkan keputusan. Ghazali menerima nota ringkas.', 11, 3, 'bilik_mesyuarat_dunia.png'),
('e1_n3_s12', '9 Julai 1963. Di Kuala Lumpur, Ghazali menyemak fail perjanjian yang dihantar ke London.', 12, 3, 'marlborough_house.png'),
('e1_n3_s13', 'Fail empat badan terbuka di atas meja Ghazali. Razak menyuruh dia memadankan tugas setiap badan.', 13, 3, 'bilik_mesyuarat.png'),
('e1_n3_s14', '16 September 1963. Dokumen Pemasyhuran terbentang di atas meja.', 14, 3, 'perancangan_pembentukan_malaysia.png'),
('e1_n3_s15', 'Selepas Pemasyhuran. Ghazali menyusun laporan cabaran yang diterima.', 15, 3, 'bilik_mesyuarat_dunia.png'),
('e1_n3_s16', 'Pejabat Ghazali sunyi. Razak meminta rumusan terakhir sebelum fail ditutup.', 16, 3, 'bilik_mesyuarat.png'),
('e2_n1_s1', 'Perlis, tepi sawah. Buku Asal Usul terbuka di atas pangkin. Seorang pesawah menyeret sebiji kelapa tua dari parit dan sebuah catatan lama separuh pudar terletak di sebelahnya.', 1, 201, 'negeri_perlis.png'),
('e2_n1_s2', 'Kedah, pasar lama. Pemandu gajah bertengkar dengan penjual cawan berkaki. Di dinding kedai ada tulisan Tamil yang kelihatan kuno.', 2, 201, 'negeri_kedah.png'),
('e2_n1_s3', 'Pulau Pinang, jeti sibuk dengan karung pinang. Pelombong dari Perak turun menjual bijih dan bertelagah dengan nelayan tempatan.', 3, 201, 'negeri_pulau_pinang.png'),
('e2_n1_s4', 'Pejabat daerah lama di utara. Peta Semenanjung terbentang di meja dan titik merah serta kuning bertaburan di atasnya.', 4, 201, 'bilik_mesyuarat.png'),
('e2_n1_s5', 'Anjung rumah di utara. Radio lama berbunyi perlahan. Seorang pegawai radio tidak jumpa kaset yang betul di atas rak.', 5, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s6', 'Selangor, kuala sungai. Pedagang bertemu penghulu Minangkabau. Nelayan dan penghulu bertelagah tentang nama negeri masing-masing.', 6, 201, 'negeri_selangor.png'),
('e2_n1_s7', 'Melaka, di bawah pokok tua dekat pelabuhan. Orang tua dan peniaga berbalah. Seorang pembaca naskhah menunggu dengan buku Sulalatus Salatin.', 7, 201, 'negeri_melaka.png'),
('e2_n1_s8', 'Bilik mesyuarat di tengah semenanjung. Seorang pegawai membawa fail ibu negeri dan bandar diraja yang bercampur.', 8, 201, 'bilik_mesyuarat_formal.png'),
('e2_n1_s9', 'Anjung rumah di selatan. Pegawai radio yang lebih tegang memandang dua kaset yang kelihatan serupa. Majlis bermula dalam dua jam.', 9, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s10', 'Terengganu, pantai selepas hujan. Pelangi melengkung di atas Pulau Duyong. Penduduk Pahang, Terengganu dan Kelantan berbalah.', 10, 201, 'negeri_terengganu.png'),
('e2_n1_s11', 'Bilik peta di pantai timur. Titik merah dan kuning di peta menanda Kuantan, Pekan, Kuala Terengganu dan Kota Bharu.', 11, 201, 'bilik_mesyuarat_modern.png'),
('e2_n1_s12', 'Anjung rumah di pantai timur. Radio berbunyi dan dua orang tua berbalah tentang negeri yang memiliki lagu itu.', 12, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s13', 'Sarawak, tebing sungai dengan bot dan bijih galian. Seorang ahli sejarah tempatan tercari-cari dokumen tentang nama dua negeri Borneo.', 13, 201, 'negeri_sarawak.png'),
('e2_n1_s14', 'Wilayah Persekutuan. Tiga pelawat dari Kuala Lumpur, Labuan dan Putrajaya bertanya serentak di hadapan pentas.', 14, 201, 'wilayah_persekutuan.png'),
('e2_n1_s15', 'Pejabat daerah Kuching, jendela menghadap sungai. Pegawai dari Sarawak dan Sabah membawa dua fail.', 15, 201, 'bilik_mesyuarat.png'),
('e2_n1_s16', 'Anjung rumah, radio terakhir sebelum Pesta Warisan. Pegawai radio berpeluh kerana tiga negeri belum dimainkan.', 16, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s17', 'Dewan istana. Kerusi bergelar disusun untuk majlis. Seorang pegawai istiadat yang cemas menyusun kad nama ketua-ketua negeri.', 17, 201, 'bilik_mesyuarat_formal.png'),
('e2_n1_s18', 'Pentas Pesta Warisan Negara di Wilayah Persekutuan. Bendera berkibar, jata terpampang di dinding dan radio berbunyi di atas meja. Buku Asal Usul terbuka di hadapan penonton.', 18, 201, 'wilayah_persekutuan.png'),
('e2_n2_s1', 'Putrajaya, Hari 3. Sebuah fail istiadat terbuka dan satu kad kosong terletak di tempat ketua Wilayah Persekutuan.', 1, 202, 'bilik_mesyuarat_modern.png'),
('e2_n2_s2', 'Wilayah Persekutuan, pentas. Tiga papan nama bertukar tempat dan seorang juruteknik kebingungan.', 2, 202, 'wilayah_persekutuan.png'),
('e2_n2_s3', 'Bilik mesyuarat, kad gelaran bertaburan di atas meja panjang. Ada kesan tapak kaki berlumpur di lantai.', 3, 202, 'bilik_mesyuarat_formal.png'),
('e2_n2_s4', 'Bilik mesyuarat. Seorang pembantu Yang di-Pertua Negeri meminta dokumen yang betul. Beberapa dokumen palsu bercampur di atas meja.', 4, 202, 'bilik_mesyuarat.png'),
('e2_n2_s5', 'Selangor, kuala sungai awal pagi. Jejak kasut berlumpur membawa ke sebuah balai penghulu. Sehelai piagam lama tergantung di dinding.', 5, 202, 'negeri_selangor.png'),
('e2_n2_s6', 'Melaka, di bawah pokok tua. Satu nota tersangkut di akar pokok.', 6, 202, 'negeri_melaka.png'),
('e2_n2_s7', 'Pejabat daerah. Fail ibu negeri dan bandar diraja bercampur selepas Encik Zahar datang. Satu fail hilang.', 7, 202, 'bilik_mesyuarat.png'),
('e2_n2_s8', 'Bilik radio. Empat kaset tanpa label tersusun di atas meja dan bau minyak pelincir masih segar.', 8, 202, 'kampung_dan_pedalaman.png'),
('e2_n2_s9', 'Perlis, sawah di pagi kedua. Peti pos tepi jalan menyimpan nota bersama empat kad.', 9, 202, 'negeri_perlis.png'),
('e2_n2_s10', 'Pulau Pinang, jeti. Karung pinang bertimbun dan pokok penaga di tepi pantai. Seorang penjual cawan dari Kedah menunggu.', 10, 202, 'negeri_pulau_pinang.png'),
('e2_n2_s11', 'Pejabat daerah utara. Seorang pegawai daerah memerlukan dokumen yang betul sebelum petang. Salah satu fail mempunyai cop Zahar.', 11, 202, 'bilik_mesyuarat_formal.png'),
('e2_n2_s12', 'Anjung rumah. Radio lama berbunyi dan satu nota tertulis menyebut Aamiin-Aamiin.', 12, 202, 'kampung_dan_pedalaman.png'),
('e2_n2_s13', 'Terengganu, pantai berpasir selepas hujan. Zahar meninggalkan sehelai peta bertanda di sini.', 13, 202, 'negeri_terengganu.png'),
('e2_n2_s14', 'Bilik peta pantai timur dengan titik merah dan kuning. Kad ibu negeri bercampur di atas meja.', 14, 202, 'bilik_mesyuarat_modern.png'),
('e2_n2_s15', 'Bilik radio pantai timur. Jururadio bingung dengan dua kaset yang kelihatan serupa.', 15, 202, 'kampung_dan_pedalaman.png'),
('e2_n2_s16', 'Sarawak, tebing sungai. Sepucuk surat dari Sabah tiba bersama bot.', 16, 202, 'negeri_sarawak.png'),
('e2_n2_s17', 'Bilik mesyuarat, malam sebelum istiadat. Pegawai dua negeri Borneo menunggu di talian telefon. Dua kaset dan dua kad bercampur.', 17, 202, 'bilik_mesyuarat_dunia.png'),
('e2_n2_s18', 'Dewan Pesta Warisan Negara, Wilayah Persekutuan. Bendera berkibar, jata di dinding dan radio di atas meja. Zahar berdiri di tepi pentas dengan sampul.', 18, 202, 'wilayah_persekutuan.png'),
('e2_n3_s1', 'Sabah, kebun pisang di pantai barat. Pasport baharu masih kosong dan seorang penjaga cop menunggu di pondok.', 1, 203, 'negeri_sabah.png'),
('e2_n3_s2', 'Sarawak, tebing sungai. Penjaga cop menyerahkan satu surat dengan tulisan kabur.', 2, 203, 'negeri_sarawak.png'),
('e2_n3_s3', 'Bilik mesyuarat. Dua pegawai Borneo, satu dari Kuching dan satu dari Kota Kinabalu, menyerahkan kad ke tangan Pengembara.', 3, 203, 'bilik_mesyuarat.png'),
('e2_n3_s4', 'Wilayah Persekutuan. Seorang pemandu pelancong membantu Pengembara tetapi dokumennya bercampur.', 4, 203, 'wilayah_persekutuan.png'),
('e2_n3_s5', 'Bilik mesyuarat di Putrajaya. Penjaga cop Wilayah Persekutuan menyerahkan satu nota tersembunyi di bawah kad.', 5, 203, 'bilik_mesyuarat_modern.png'),
('e2_n3_s6', 'Johor, tepi selat. Peniaga permata dan pembaca naskhah berbalah di sebelah sehelai nota.', 6, 203, 'negeri_johor.png'),
('e2_n3_s7', 'Johor, balai penerangan. Peta menandakan titik merah dan kuning.', 7, 203, 'negeri_johor.png'),
('e2_n3_s8', 'Melaka, di bawah pokok tua dekat pelabuhan. Satu nota tersangkut di akar.', 8, 203, 'negeri_melaka.png'),
('e2_n3_s9', 'Bilik radio. Pegawai radio Melaka hilang kaset lagu negeri.', 9, 203, 'kampung_dan_pedalaman.png'),
('e2_n3_s10', 'Negeri Sembilan, balai penghulu dengan sembilan kerusi di dalam dewan.', 10, 203, 'negeri_sembilan.png'),
('e2_n3_s11', 'Negeri Sembilan, anjung istana lama. Peta menandakan titik merah dan kuning.', 11, 203, 'negeri_sembilan.png'),
('e2_n3_s12', 'Selangor, kuala sungai dengan pokok dan serangga. Tebing seberang berkait dengan Pahang.', 12, 203, 'negeri_selangor.png'),
('e2_n3_s13', 'Bilik mesyuarat. Dua peta, satu Selangor dan satu Pahang, dengan titik merah dan kuning.', 13, 203, 'bilik_mesyuarat_formal.png'),
('e2_n3_s14', 'Terengganu, pantai selepas hujan. Pelangi melengkung di atas Pulau Duyong. Pencerita Patani menunggu di tepi pantai.', 14, 203, 'negeri_terengganu.png'),
('e2_n3_s15', 'Anjung rumah. Radio berbunyi dan satu nota tersembunyi di bawah radio.', 15, 203, 'kampung_dan_pedalaman.png'),
('e2_n3_s16', 'Pulau Pinang, jeti dengan karung pinang. Pelombong dari Perak turun menjual bijih.', 16, 203, 'negeri_pulau_pinang.png'),
('e2_n3_s17', 'Pejabat daerah. Seorang pegawai daerah memerlukan dokumen yang betul bagi Perak dan Pulau Pinang.', 17, 203, 'bilik_mesyuarat.png'),
('e2_n3_s18', 'Kedah, pasar lama. Sawah di seberang menuju Perlis.', 18, 203, 'negeri_kedah.png'),
('e2_n3_s19', 'Bilik radio terakhir di utara. Dua kaset serupa menunggu di atas meja.', 19, 203, 'kampung_dan_pedalaman.png'),
('e2_n3_s20', 'Pentas Pesta Warisan Negara di Wilayah Persekutuan. Halaman terakhir pasport koyak. Bendera berkibar, jata terpampang dan radio berbunyi.', 20, 203, 'wilayah_persekutuan.png'),
('e3_n1_s1', 'Mei 1969, Kuala Lumpur. Jalan lengang dan sepi. Di bilik gerakan, sebuah papan tanda MAGERAN dipasang dan para pegawai berbisik cemas tentang peristiwa yang baru berlaku.', 1, 301, 'peristiwa_13mei1969.png'),
('e3_n1_s2', 'Zaman dahulu, di sebuah pemandangan yang menunjukkan ladang, kampung dan pekan. Pegawai awam membentangkan satu peta bertanda tiga kawasan petempatan. Tiga bukti tersembunyi menerangkan mengapa rakyat terpisah.', 2, 301, 'petempatan_semua_dahulu.png'),
('e3_n1_s3', '4 Mac 1970, bilik mesyuarat formal. Di hujung meja ada papan bertulis MAPEN. Wakil pelbagai pihak mengambil tempat; satu kad nama Jawatankuasa Rukun Negara hampir terjatuh.', 3, 301, 'bilik_mesyuarat_formal.png'),
('e3_n1_s4', 'Bilik Rukun Negara. Di dinding terpampang lukisan lima matlamat: perpaduan, demokrasi, keadilan, kebudayaan dan sains. Lima bukti tersembunyi dalam lukisan itu menunggu ditemui.', 4, 301, 'matlamat_rukun_negara.png'),
('e3_n1_s5', '31 Ogos 1970, Bangunan Perlembagaan. Di tengah ruang ada empat kad peristiwa penting dalam pembentukan Rukun Negara yang mesti disusun sebelum pengisytiharan.', 5, 301, 'bangunan_perlembagaan.png'),
('e3_n1_s6', 'Bilik penulisan teks Rukun Negara. Lima kad matlamat dan lima kad maksud bercampur-baur di atas meja. Pegawai menyatakan semuanya mesti dipadankan dengan teliti sebelum dicetak.', 6, 301, 'matlamat_rukun_negara_dahulu.png'),
('e3_n2_s1', 'Sebuah pekan lama. Tauke Lim menyusun barang di kedai, Pak Tani membawa hasil sawah dan Pak Muthu membawa getah. Di tangan Sambanthan ada senarai kegiatan ekonomi setiap kaum yang bercampur.', 1, 302, 'bandar.png'),
('e3_n2_s2', 'Di tepi kampung dan ladang. Sambanthan berjalan dari satu kawasan ke kawasan lain bersama Hafiz, Arun dan Wei Jie. Mereka berbalah tentang mengapa jarang berjumpa.', 2, 302, 'petempatan_semua_dahulu.png'),
('e3_n2_s3', 'Sebuah peta rantaian sebab dan akibat terbentang. Lima kad terletak berselerak: dari pentadbiran British hingga rusuhan 1969. Sambanthan perlu menyusun rantaian itu.', 3, 302, 'peristiwa_13mei1969.png'),
('e3_n2_s4', 'Sebuah lorong dengan masjid, gereja, kuil dan tokong berdekatan. Mei Ling, Pak Muthu dan Hafiz membahaskan mengapa agama begitu penting dalam Rukun Negara.', 4, 302, 'tempat_beribadat_semua.png'),
('e3_n2_s5', 'Taman peringatan. Sambanthan berdiri bersama rakyat. Di sekeliling ada tiga petunjuk prinsip Rukun Negara: orang berdoa, jata negara dan tugu negara.', 5, 302, 'prinsip_rukun_negara_.png'),
('e3_n2_s6', 'Sebuah dewan dengan lima papan nama prinsip dan lima papan maksud yang terpisah. Pak Tani, Tauke Lim dan Wei Jie sedang menyusun semula papan-papan itu.', 6, 302, 'bangunan_perlembagaan.png'),
('e3_n3_s1', 'Sebuah taman dengan masjid, kuil, gereja dan tokong bersebelahan. Tunku berdiri di tengah kerumunan. Beberapa kad peranan Rukun Negara di tangan murid saling bercampur.', 1, 303, 'tempat_beribadat_semua.png'),
('e3_n3_s2', 'Di bandar, murid menaikkan Jalur Gemilang. Di sebelah ada kad Jata Negara dan lagu Negaraku. Hafiz dan Mei Ling membantah apabila seorang murid menyindir lambang negara.', 2, 303, 'bandar.png'),
('e3_n3_s3', 'Di luar sebuah mahkamah, ramai pemuda berkumpul. Sebuah kempen anak muda bebas dadah berlangsung. Seorang murid menunjukkan kad kesalahan dan hukuman kepada Tunku.', 3, 303, 'bangunan_perlembagaan.png'),
('e3_n3_s4', 'Sebuah pasar malam pelbagai kaum. Kedai Tauke Lim, gerai Pak Tani dan kedai Pak Muthu bersebelahan. Dua pelanggan bertengkar tentang makanan kaum lain, dan Tunku berjalan melihat.', 4, 303, 'bandar.png'),
('e3_n3_s5', 'Sebuah bilik mesyuarat moden. Enam kad peranan Rukun Negara terbentang di atas meja. Kad tajuk dan kad penerangan bercampur-baur, dan murid-murid memerhati.', 5, 303, 'bilik_mesyuarat_modern.png'),
('e3_n3_s6', 'Taman prinsip. Di depan Tunku, empat petunjuk tersembunyi mewakili prinsip ketiga, keempat dan kelima: gulungan Perlembagaan, papan undang-undang, murid menanam pokok dan seorang membantu warga emas.', 6, 303, 'prinsip_rukun_negara_.png'),
('e4_n1_s1', 'Malam perayaan di sebuah padang kampung. Lampu pentas dipasang dan penonton pelbagai kaum datang. Di tangan pemuzik ada senarai bahasa setiap kaum yang bercampur-baur.', 1, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s2', 'Pinggir hutan di Perak. Tok Batin duduk di hadapan rumah buluh sambil menganyam bakul. Ubat herba dan kraf tangan tersusun di atas tikar, tetapi sebuah kad nota tertinggal di tepi.', 2, 401, 'petempatan_orang_asli_dahulu.png'),
('e4_n1_s3', 'Pasar malam di bandar Melaka. Kedai kuih, pasar tamu dan restoran berjejer. Empat kad kaum peranakan dan kaum kecil berselerak di atas meja pemuzik.', 3, 401, 'petempatan_semua_kini.png'),
('e4_n1_s4', 'Tebing sungai di Sarawak. Rumah panjang berjejer di tepi air, tikar pua kumbu dijemur. Apai Iban dan Linda dari Sabah berbalah tentang kaum mana lebih besar.', 4, 401, 'petempatan_lembah_sungai_sarawak.png'),
('e4_n1_s5', 'Pentas besar dengan lima sudut persembahan. Setiap sudut mempunyai alat muzik dan penari, tetapi papan petunjuk jatuh sehingga penonton keliru.', 5, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s6', 'Bengkel alat muzik di belakang pentas. Buluh, kayu dan kulit terbentang di atas meja. Seorang murid berkeras mahu menggantikan semuanya dengan alat elektronik.', 6, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s7', 'Tirai pentas hampir dibuka. Lapan penari bersiap, tetapi senarai tarian bercampur. Pengurus pentas bimbang acara bermula tanpa susunan yang tepat.', 7, 401, 'alat_muzik_dan_tarian_tradisional.png'),
('e4_n1_s8', 'Malam di kampung Orang Asli. Api unggun menyala dan penari bersedia. Dua kad tarian, sewang dan bhangra, tertukar di atas tikar.', 8, 401, 'petempatan_orang_asli_dahulu.png'),
('e4_n2_s1', 'Laci pertama dalam peti nenek terbuka. Gambar kampung tepi sungai, perahu nelayan dan sawah padi memenuhi pandangan. Cucu-cucu duduk bersila.', 1, 402, 'petempatan_melayu_dahulu.png'),
('e4_n2_s2', 'Laci kedua. Gambar lombong bijih, jalan pekan dan rumah kedai bertingkat. Kavitha dan Ah Meng berbalah sama ada kaum mereka dahulu tinggal di tempat yang sama.', 2, 402, 'petempatan_cina_dahulu.png'),
('e4_n2_s3', 'Laci ketiga. Gambar rumah buluh di pedalaman, anyaman rotan dan kulit kayu kering. Cucu bertanya sama ada Orang Asli hanya tinggal di satu negeri.', 3, 402, 'petempatan_orang_asli_dahulu.png'),
('e4_n2_s4', 'Laci keempat. Gambar Sarawak: pedalaman berbukit, lembah sungai dan pantai. Jenny dan Apai Iban berbalah tentang tempat tinggal kaum mereka.', 4, 402, 'petempatan_pedalaman_sarawak_dahulu.png'),
('e4_n2_s5', 'Laci kelima. Gambar Sabah: pedalaman bersawah, pantai nelayan dan perahu berlabuh. Linda dan Pak Bajau saling bertanya tentang kampung datuk mereka.', 5, 402, 'petempatan_pedalaman_sabah.png'),
('e4_n2_s6', 'Taman perumahan masa kini. Jiran Melayu, Cina, India dan kaum lain berkumpul untuk gotong-royong. Cucu bertanya mengapa kini tidak seperti dalam laci lama.', 6, 402, 'petempatan_semua_kini.png'),
('e4_n2_s7', 'Laci ketujuh. Sebuah perahu di tengah laut, guni di atas papan dan labu-labu air berguling di dalamnya. Si Luncai tersenyum licik dari dalam guni.', 7, 402, 'si_luncai.png'),
('e4_n2_s8', 'Laci terakhir. Gunung Santubong terbentang di pandangan, dan dua puteri kayangan bertelingkah di bawah kilat. Dua kampung berjiran, Pasir Kuning dan Pasir Putih, mengintai dari jauh.', 8, 402, 'puteri_santubong.png'),
('e4_n3_s1', 'Pagi Sabtu di gelanggang. Anjung rumah, laman luas dan padang lapang berjejer. Kanak-kanak tidak bersetuju di mana permainan harus dimainkan.', 1, 403, 'permainan_tradisional.png'),
('e4_n3_s2', 'Meja kayu di anjung. Papan congkak, lima biji batu, buah hitam dan putih dan bola lawi tersusun, tetapi nama permainan tercabut dan bercampur-baur.', 2, 403, 'permainan_tradisional.png'),
('e4_n3_s3', 'Padang lapang selepas musim menuai. Wau berterbangan, gasing berputar dan tiang tinggi dipasang. Empat kad permainan lapang diletakkan di atas tikar.', 3, 403, 'permainan_tradisional.png'),
('e4_n3_s4', 'Sudut gelanggang berasingan. Papan catur India dan dadu, yoyo diabolo dan papan go diletakkan di meja. Kanak-kanak bertanya sama ada permainan ini datang dari luar.', 4, 403, 'permainan_tradisional.png'),
('e4_n3_s5', 'Papan kenyataan di pintu gelanggang. Senarai permainan yang diangkat sebagai warisan kebangsaan negara tertulis separa terpadam.', 5, 403, 'permainan_tradisional.png'),
('e4_n3_s6', 'Tepi Sungai Liwagu di Sabah. Sebatang pohon nunuk besar menaungi penduduk yang berehat. Seekor ayam gergasi berwarna merah dan bertaji emas turun mengibas sayap.', 6, 403, 'nunuk_ragang.png'),
('e4_n3_s7', 'Taman permainan di kawasan perumahan. Dua kumpulan kanak-kanak berbalah kerana kumpulan lain bercakap bahasa yang tidak difahami. Tok Permainan datang melerai.', 7, 403, 'petempatan_semua_kini.png'),
('e4_n3_s8', 'Pameran budaya di dewan sekolah. Gambar alat muzik, tarian dan permainan terpampang. Ada pelancong asing mengambil gambar, dan murid mempersoalkan gunanya semua ini.', 8, 403, 'petempatan_semua_kini.png'),
('e5_n1_s1', 'Sebuah lorong dengan masjid, gereja, kuil, tokong dan gurdwara berdekatan. Enam sahabat sedang menyusun kad pengasas agama untuk projek sekolah, tetapi kad-kad itu bercampur.', 1, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s2', 'Perpustakaan kecil di tengah lorong. Enam kitab dan buku terletak di atas meja, tetapi label rak tercabut. Seorang pelawat hampir meletakkan Bible di rak al-Quran.', 2, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s3', 'Seorang kanak-kanak bertanya kepada Kavitha tentang kepercayaan agamanya. Sekeping kad tentang kepercayaan Hindu terletak di tangan.', 3, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s4', 'Satu pameran kecil tentang Ajaran Konfusius dan Ajaran Tao. Kenny menunjukkan dua buku berbeza, tetapi pengunjung selalu mengatakan kedua-duanya sama.', 4, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s5', 'Dewan seminar kecil. Papan putih bertulis tiga perkataan: pemerintah, pedagang dan golongan agama. Seorang murid keliru bagaimana agama-agama ini sampai ke Malaysia.', 5, 501, 'bangunan_perlembagaan.png'),
('e5_n1_s6', 'Tiga kad terjatuh dari buku nota: Rukun Islam dan Rukun Iman, hari Ahad di gereja, dan Waheguru. Pengkaji ingin menyusun semula supaya setiap agama dipadankan dengan amalan betul.', 6, 501, 'tempat_beribadat_semua.png'),
('e5_n1_s7', 'Satu jalan dengan enam rumah ibadat berdekatan: masjid, gereja, tokong, wat, kuil dan gurdwara. Pelancong asing mengambil gambar tetapi tidak mengenali nama setiap rumah ibadat.', 7, 501, 'tempat_beribadat_berdekat.png'),
('e5_n1_s8', 'Senja di lorong yang sama. Enam sahabat duduk di bangku sambil berfikir mengapa agama penting dalam kehidupan. Kad refleksi terletak di tengah bulatan.', 8, 501, 'tempat_beribadat_semua.png'),
('e5_n2_s1', 'Tepi pantai di Pulau Carey. Penghulu kampung berdiri di hadapan seorang murid yang bertanya mengapa penduduk mempercayai gua dan batu besar mempunyai roh.', 1, 502, 'mah_meri_puja_pantai.png'),
('e5_n2_s2', 'Upacara Puja Pantai di Pulau Carey. Orang kampung berarak ke pantai dengan persembahan. Tok Batin Temiar tiba dengan satu soalan tentang tujuan upacara.', 2, 502, 'mah_meri_puja_pantai.png'),
('e5_n2_s3', 'Rumah panjang di Sarawak. Lemambang membaca jampi mantera di hadapan sajian. Seorang tetamu bertanya kepada Apai Jelani siapa yang dipuja dalam upacara ini.', 3, 502, 'upacara_miring.png'),
('e5_n2_s4', 'Sebuah ladang baharu di Sarawak. Pak Tani Bisaya membaca jampi mantera sebelum memulakan kerja. Seorang pesakit terbaring di rumah berhampiran sedang menunggu upacara.', 4, 502, 'tamarok_bisaya.png'),
('e5_n2_s5', 'Pantai barat Sabah. Keluarga si mati menyediakan jamuan untuk tetamu. Seorang pelajar bertanya mengapa upacara Bajau di Semporna pula bernama lain.', 5, 502, 'ngeduang.png'),
('e5_n2_s6', 'Pesta Kaamatan di perkarangan rumah tradisi. Linda memegang kad Kinorohingan dan Magavau. Seorang tetamu bertanya apakah peranan Bobohizan dalam upacara.', 6, 502, 'kinorohingan.png'),
('e5_n2_s7', 'Perkampungan Bajau di atas air, Semporna. Perahu berhias dan gerbang upacara menyambut pelawat. Pelancong ingin tahu tempat untuk berjumpa petunjuk upacara Mag\'ombo dan Ngeduang.', 7, 502, 'upacara_pantai.png'),
('e5_n2_s8', 'Bulatan terakhir di persidangan. Lima penjaga adat berdiri di hadapan lima kad dan diminta berkongsi siapa mengetuai upacara masing-masing.', 8, 502, 'mah_meri_puja_pantai.png'),
('e5_n3_s1', 'Dewan Pesta Kepercayaan Sekolah. Empat kad kronologi tentang kedudukan Islam dalam Perlembagaan terletak di atas pentas. Seorang guru bimbang urutannya terbalik.', 1, 503, 'bangunan_perlembagaan.png'),
('e5_n3_s2', 'Papan kenyataan Perlembagaan. Tuanku Sultan dan Yang di-Pertua Negeri berdiri bersebelahan; seorang murid keliru siapa Ketua Agama Islam bagi negeri masing-masing.', 2, 503, 'bangunan_perlembagaan.png'),
('e5_n3_s3', 'Satu kempen kesedaran di luar Bangunan Perlembagaan. Seorang pemuda berbual dengan guru, katanya kebebasan beragama tidak wujud di negara ini. Seorang pelajar memegang kad Perkara 11.', 3, 503, 'bangunan_perlembagaan.png'),
('e5_n3_s4', 'Kawasan tumpuan pelancong. Enam rumah ibadat berselerak mengikut kad pameran. Pelancong asing hendak masuk, tetapi tidak tahu nama atau adab yang betul.', 4, 503, 'tempat_beribadat_semua.png'),
('e5_n3_s5', 'Pameran masjid tertua. Tiga papan kenyataan Masjid Negara, Masjid Kampung Laut dan Masjid Al-Qadim berselerak. Pelajar hendak menulis laporan tetapi kad bercampur.', 5, 503, 'tempat_beribadat_semua.png'),
('e5_n3_s6', 'Pameran rumah ibadat lain. Sekeping papan Gereja St. Michael, Wat Boonyaram, Tokong Cheng Hoon Teng, kuil kaca dan Wadda Gurdwara berselerak. Rakan-rakan membahaskan mana yang tertua.', 6, 503, 'tempat_beribadat_berdekat.png'),
('e5_n3_s7', 'Sebuah kumpulan murid bersiap melawat semua rumah ibadat. Guru memeriksa pakaian dan tingkah laku, tetapi seorang murid bertanya mengapa perlu menjaga adab di tempat ibadat kaum lain.', 7, 503, 'tempat_beribadat_semua.png'),
('e5_n3_s8', 'Hujung lawatan. Enam rakan berhimpun di perkarangan sekolah untuk menulis rumusan. Papan putih bertulis: mengapa menghormati kepelbagaian agama menjamin perpaduan?', 8, 503, 'tempat_beribadat_semua.png'),
('e6_n1_s1', 'Bengkel kraf di tengah bandar. Enam tempahan hiasan sampai serentak: tarikh perayaan tertulis pada kertas yang basah terkena hujan dan separuh luntur.', 1, 601, 'bandar.png'),
('e6_n1_s2', 'Bengkel dipenuhi kad Selamat Hari Raya. Dua pelanggan Muslim mahu menempah hiasan, tetapi seorang bertanya mengapa ada dua hari raya dengan makna berbeza.', 2, 601, 'suasana_dan_ucapan_raya_kini.png'),
('e6_n1_s3', 'Rumah keluarga Cina menjelang Tahun Baharu Cina. Seluruh ahli keluarga berkumpul. Ah Meng mahu mengatur senarai kegiatan perayaan, tetapi kad tertukar tempat.', 3, 601, 'makan_besar_cina_dahulu.png'),
('e6_n1_s4', 'Pelataran rumah menjelang Deepavali. Kavitha dan Harjit membincangkan perayaan masing-masing: Deepavali, Thaipusam dan Vaisakhi. Kad hiasan bercampur di atas tikar.', 4, 601, 'kolam_deepavali_dahulu.png'),
('e6_n1_s5', 'Rumah panjang di Sarawak menjelang 1 Jun. Apai Jelani dan Linda berbalah tentang perayaan petani di Sarawak dan Sabah. Dua kad bercampur.', 5, 601, 'hari_gawai_dayak_dahulu.png'),
('e6_n1_s6', 'Taman perayaan. Daniel dan Mei Ling berbual tentang Krismas dan Wesak. Murid yang lalu bertanya mengapa tarikh dan kegiatan kedua-dua perayaan sangat berbeza.', 6, 601, 'tempat_beribadat_berdekat.png'),
('e6_n1_s7', 'Perkampungan Orang Asli di Selangor. Tok Batin Temiar dan Pak Mah Meri mengira hari menjelang 31 Disember. Mereka berbalah tentang nama sambutan tahun baharu setiap suku.', 7, 601, 'petempatan_semua_kini.png'),
('e6_n1_s8', 'Pelabuhan kecil di Melaka pada bulan Jun. Pak Nelayan menghias kapal dengan bendera dan bunga. Seorang pelancong bertanya perayaan apa ini dan mengapa kapal dihias.', 8, 601, 'bandar.png'),
('e6_n2_s1', 'Halaman rumah nenek sehari sebelum raya. Anak-anak bertanya mengapa begitu banyak perayaan di Malaysia dan apa tujuannya. Nenek mengeluarkan sekeping kad tujuan perayaan.', 1, 602, 'petempatan_semua_kini.png'),
('e6_n2_s2', 'Ruang tamu nenek. Sebuah kotak lama berisi kad ucapan raya dari pos. Cucu menunjukkan telefon yang penuh ucapan digital.', 2, 602, 'suasana raya_dan_kad_ucapan_dahulu.png'),
('e6_n2_s3', 'Sebuah gambar lama kedai gambar di bandar. Nenek menunjukkan foto keluarga bergaya dengan latar lukisan. Cucu cuba mencari bukti di dalam gambar bahawa kisah nenek benar.', 3, 602, 'mengambil_foto_dahulu.png'),
('e6_n2_s4', 'Rumah Kavitha menjelang Deepavali. Keluarga duduk bersama membuat kolam. Cucu bertanya mengapa kolam kini berwarna-warni sedangkan dahulu hanya putih.', 4, 602, 'kolam_deepavali_sekarang.png'),
('e6_n2_s5', 'Restoran mewah pada malam Tahun Baharu Cina. Ah Meng bertanya mengapa keluarganya makan besar di restoran, sedangkan datuknya dahulu makan di rumah.', 5, 602, 'makan_besar_cina_sekarang.png'),
('e6_n2_s6', 'Dapur nenek. Beberapa jiran bergotong-royong menyediakan kuih. Cucu hairan mengapa kuih dahulu disediakan lama sedangkan kini boleh dibeli di kedai.', 6, 602, 'penyediaan_kuih_muih_tradisional.png'),
('e6_n2_s7', 'Kedai kuih di bandar. Rak penuh balang kuih raya dan hamper. Cucu membeli kuih dan bertanya kepada nenek sama ada beli kuih bermakna tradisi hilang.', 7, 602, 'pembelian_kuih_muih_kini.png'),
('e6_n2_s8', 'Pesta Kaamatan di tepi sawah. Linda dan nenek menonton pertandingan Unduk Ngadau. Murid bertanya bagaimana pemenang dipilih dahulu berbanding kini.', 8, 602, 'unduk_ngadau_dahulu.png'),
('e6_n2_s9', 'Petang hari raya. Keluarga besar pulang ke kampung dan bersalam-salaman. Cucu menerima duit raya dan nenek bertanya apa lagi yang masih kekal dari dahulu.', 9, 602, 'suasana_dan_ucapan_raya_kini.png'),
('e6_n3_s1', 'Sebuah rumah kedai pada hari terakhir sebelum cuti perayaan. Kerajaan menetapkan enam perayaan utama sebagai Rumah Terbuka Malaysia. Pelanggan bertanya perayaan mana yang termasuk.', 1, 603, 'bandar.png'),
('e6_n3_s2', 'Rak kad ucapan Selamat Hari Raya. Seorang pelanggan Muslim membeli kad untuk jiran Cina dan India. Dia bertanya mengapa perlu meraikan perayaan bersama keluarga.', 2, 603, 'petempatan_semua_kini.png'),
('e6_n3_s3', 'Hari raya kedua. Pelanggan Cina melawat jiran Melayu dan membawa makanan. Seorang kanak-kanak bertanya tentang adab melawat rumah perayaan kaum lain.', 3, 603, 'petempatan_semua_kini.png'),
('e6_n3_s4', 'Rumah panjang masa kini pada 1 Jun. Pelbagai kaum menyertai Gawai, termasuk tetamu Melayu dan Cina. Seorang tetua kehairanan mengapa ramai kaum lain turut menyambut.', 4, 603, 'festival_gawai_kini.png'),
('e6_n3_s5', 'Ruang pameran di tingkat atas kedai. Gambar kolam, makan besar dan kuih dari dahulu dan kini terpampang. Pelanggan diminta memadankan perubahan tradisi.', 5, 603, 'kolam_deepavali_dahulu.png'),
('e6_n3_s6', 'Papan putih di bahagian belakang kedai. Pekerja kedai membincangkan analisis SWOT untuk mengekalkan warisan perayaan. Sekeping kad SWOT tergantung senget.', 6, 603, 'petempatan_semua_dahulu.png'),
('e6_n3_s7', 'Hari terakhir sebelum kedai ditutup. Pelanggan terakhir meminta ringkasan perayaan: tujuan, cara sambutan dan amalan kekal. Kad berselerak di atas kaunter.', 7, 603, 'bandar.png'),
('e7_n1_s1', 'Pejabat Perdana Menteri di Putrajaya. Skrip siaran masih kosong. Yang di-Pertuan Agong menunggu soalan pertama, tetapi bahan latar menyatakan Perdana Menteri dilantik oleh pihak yang lain.', 1, 701, 'bangunan_perlembagaan.png'),
('e7_n1_s2', 'Bilik arkib stesen penyiaran. Empat pita rakaman pemimpin berselerak dan label tarikh luntur. Penerbit mahu urutan Perdana Menteri yang betul sebelum siaran ke udara.', 2, 701, 'bilik_mesyuarat_formal.png'),
('e7_n1_s3', 'Rakaman lama Stadium Merdeka pada 31 Ogos 1957. Penerbit mahu empat bukti dalam rakaman bahawa Tunku memperjuangkan kemerdekaan secara rundingan, bukan peperangan.', 3, 701, 'laungan_di_stadium_merdeka.png'),
('e7_n1_s4', 'Bilik temu bual. Tunku menjawab soalan tentang latar hidupnya. Penerbit mahu empat butir biodata dipadankan dengan betul sebelum disiarkan.', 4, 701, 'bilik_mesyuarat.png'),
('e7_n1_s5', 'Bilik penyiar menayangkan rakaman peristiwa 13 Mei 1969. Penerbit tersalah menulis bahawa Tun Razak memulihkan keamanan dengan menutup semua pejabat kerajaan. Kau perlu menyemak pencapaiannya.', 5, 701, 'peristiwa_13mei1969.png'),
('e7_n1_s6', 'Taman peringatan di Pulau Keladi, Pekan. Replika rumah kelahiran Tun Razak berdiri di tepi sungai. Penerbit mahu empat butir biodata Tun Razak dipadankan dengan betul.', 6, 701, 'wilayah_persekutuan.png'),
('e7_n1_s7', 'Studio kedua. Penerbit meletakkan kad Tun Hussein Onn di sebelah kad Tun Razak. Penonton muda bertanya mengapa Tun Hussein digelar Bapa Perpaduan.', 7, 701, 'bilik_mesyuarat_modern.png'),
('e7_n1_s8', 'Papan gelaran di dinding studio. Penerbit meminta kau menyiapkan ringkasan gelaran lima pemimpin dengan sumbangan mereka sebelum siaran terakhir.', 8, 701, 'bilik_mesyuarat_dunia.png'),
('e7_n2_s1', 'Bilik darjah Tahun 6. Gambar-gambar dari buku teks terlepas ke papan putih. Murid bertanya apakah tugas sebenar Perdana Menteri dan gambar mana yang menunjukkan setiap tugas.', 1, 702, 'bilik_mesyuarat_modern.png'),
('e7_n2_s2', 'Papan putih sekali lagi. Murid menyenaraikan tugas lain Perdana Menteri yang berkaitan Yang di-Pertuan Agong dan Jemaah Menteri. Ada kad yang tersalah letak.', 2, 702, 'bilik_mesyuarat_formal.png'),
('e7_n2_s3', 'Tun Dr. Mahathir keluar dari halaman buku. Murid menunjuk kad biodata beliau dan meminta kau memadankan dengan betul sebelum loceng berbunyi.', 3, 702, 'bilik_mesyuarat.png'),
('e7_n2_s4', 'Tayangan slaid pencapaian zaman Tun Dr. Mahathir. Murid mahu empat bukti bahawa Malaysia mahu menjadi negara maju melalui Wawasan 2020.', 4, 702, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e7_n2_s5', 'Tun Dr. Mahathir kembali sebagai Perdana Menteri kali kedua. Murid keliru tentang tempoh dan wawasan baharu beliau. Kad nota bertaburan.', 5, 702, 'bilik_mesyuarat_formal.png'),
('e7_n2_s6', 'Giliran Tun Abdullah Ahmad Badawi. Murid memegang kad biodata beliau dan bertanya mengapa beliau digelar Bapa Pembangunan Modal Insan.', 6, 702, 'wilayah_persekutuan.png'),
('e7_n2_s7', 'Papan putih menyenaraikan dua rancangan di bawah Tun Abdullah. Murid keliru antara Koridor Wilayah Ekonomi dengan Pelan Integriti Nasional. Cikgu menulis nota ringkas.', 7, 702, 'bilik_strategi_keselamatan.png'),
('e7_n2_s8', 'Tamat tayangan slaid. Dato\' Sri Najib muncul bersama logo 1Malaysia. Murid bertanya mengapa moto itu mengutamakan rakyat dan apa kaitannya dengan GTP.', 8, 702, 'bilik_mesyuarat_dunia.png'),
('e7_n2_s9', 'Kad terakhir. Muhyiddin dan Dato\' Seri Ismail Sabri muncul. Murid mahu membandingkan sumbangan dua pemimpin yang tampil dalam suasana pandemik.', 9, 702, 'bilik_mesyuarat.png'),
('e7_n3_s1', 'Halaman pertama album: gambar Bendahara Kesultanan Melayu Melaka di sebelah gambar Perdana Menteri. Cikgu bertanya apa kaitan kedua-dua jawatan itu. Murid keliru.', 1, 703, 'bilik_mesyuarat.png'),
('e7_n3_s2', 'Halaman kedua album hanya ada ruang kosong untuk lima Perdana Menteri terkini. Murid perlu menyusun mereka mengikut tarikh mula memegang jawatan.', 2, 703, 'bilik_mesyuarat_formal.png'),
('e7_n3_s3', 'Halaman ketiga: Tunku di meja rundingan pembentukan Malaysia. Murid mahu menulis kenyataan tentang pencapaian Tunku pada 16 September 1963.', 3, 703, 'perancangan_pembentukan_malaysia.png'),
('e7_n3_s4', 'Halaman keempat memaparkan sembilan kad kosong. Murid perlu memadankan enam pemimpin dengan pencapaian utama mereka untuk melengkapkan satu jadual.', 4, 703, 'bangunan_perlembagaan.png'),
('e7_n3_s5', 'Halaman kelima: gambar bilik mesyuarat kerajaan. Murid diminta menulis mengapa pemimpin yang berwibawa penting. Beberapa jawapan di dinding bercanggah.', 5, 703, 'bilik_strategi_keselamatan.png'),
('e7_n3_s6', 'Halaman keenam. Murid ditugaskan menulis cara menunjukkan penghargaan kepada Perdana Menteri. Ada kad yang menyebut cara menghina pemimpin, dan kau perlu memilih cara yang betul.', 6, 703, 'wilayah_persekutuan.png'),
('e7_n3_s7', 'Halaman ketujuh: Malaysia di pentas dunia. Murid mahu menulis kepentingan memberi sokongan kepada kepimpinan negara. Cikgu meminta kau memadankan faedah untuk diri, masyarakat dan negara.', 7, 703, 'malaysia_di_pentas_dunia.png'),
('e7_n3_s8', 'Halaman terakhir album. Cikgu meminta murid merumus nilai teras sivik unit ini. Dua nilai tertulis di bahagian atas, tetapi satu telah luntur.', 8, 703, 'bilik_mesyuarat_modern.png'),
('e8_n1_s1', 'Sawah kecil di tepi kampung. Pak Tani Dahulu menolak tawaran mesin kerana katanya cara lama sudah cukup. Kau perlu menunjukkan ciri ekonomi tradisional yang dia amalkan.', 1, 801, 'ekonomi_tradisional.png'),
('e8_n1_s2', 'Ladang besar bersebelahan. Petani Moden menunjukkan mesin penuai kepada Pak Tani. Mereka berbalah tentang perbezaan dua cara bercucuk tanam itu.', 2, 801, 'ekonomi_komersial.png'),
('e8_n1_s3', 'Pekan lama di pedalaman. Dua gambar perlombongan terselit di buku catatan: seorang lelaki sedang mendulang dan sebuah kapal korek besar di lombong emas Sungai Lebir. Gambar-gambar itu bercampur.', 3, 801, 'kampung_dan_pedalaman.png'),
('e8_n1_s4', 'Ladang getah dan kelapa sawit bersempadan. Penoreh Getah dan Petani Moden berselisih tentang industri mana yang bermula dahulu dan sejak bila.', 4, 801, 'ladang.png'),
('e8_n1_s5', 'Kilang pemprosesan getah dan sawit. Papan buih tentang lima manfaat industri tergantung di dinding, tetapi kad-kadnya jatuh ke lantai.', 5, 801, 'industri_getah_dan_kepala_sawit.png'),
('e8_n1_s6', 'Rak produk di kilang. Seorang pelawat bertanya apa maksud industri hiliran dan biodiesel dalam kad penerangan yang tertinggal di meja.', 6, 801, 'industri_getah_dan_kepala_sawit.png'),
('e8_n1_s7', 'Hasil dieksport menunggu di kotak. Label kotak sudah luntur dan penghantar tidak pasti apa isi dalam setiap kotak getah dan sawit.', 7, 801, 'kampung_dan_pedalaman.png'),
('e8_n1_s8', 'Ladang pada waktu senja. Kau menyiapkan ringkasan perubahan dan kesinambungan ekonomi untuk diserahkan kepada pengurus ladang.', 8, 801, 'ladang.png'),
('e8_n2_s1', 'Pejabat PETRONAS di Miri. Borang tarikh sejarah industri petroleum tersilap. Jurutera pelantar minyak menolak cop LULUS sehingga kau memperbetulkannya.', 1, 802, 'industri_petroleum_dan_gas.png'),
('e8_n2_s2', 'Papan pelaporan sumbangan industri petroleum. Lima kad sumbangan ada, tetapi pengurus kilang tidak tahu yang mana benar.', 2, 802, 'industri_petroleum_dan_gas.png'),
('e8_n2_s3', 'Litar permotoran. Penonton bersorak. Seorang wartawan bertanya mengapa syarikat minyak negara menaja sukan, bukan hanya mengeluarkan minyak.', 3, 802, 'sukan_permotoran.png'),
('e8_n2_s4', 'Kilang kereta nasional. Papan putih di pejabat inspektor mempunyai lima tarikh penting industri automotif yang bercampur. Penyelia kilang menunggu laporan.', 4, 802, 'industri_automotif.png'),
('e8_n2_s5', 'Pameran model kereta di kilang. Pengunjung keliru antara PROTON dan PERODUA. Beberapa kad butiran bertukar tempat.', 5, 802, 'industri_automotif.png'),
('e8_n2_s6', 'Jabatan pelancongan. Kempen Tahun Melawat Malaysia sedang dikaji. Papan promosi mahu empat bukti keistimewaan alam semula jadi yang menarik pelancong.', 6, 802, 'industri_pelancongan.png'),
('e8_n2_s7', 'Papan keistimewaan pelancongan tergantung di pejabat. Lima kad keistimewaan terpisah daripada kategorinya. Seorang pegawai mahu semuanya dipadankan sebelum mesyuarat.', 7, 802, 'industri_pelancongan.png'),
('e8_n2_s8', 'Litar antarabangsa pada hari perlumbaan. Pegawai pelancongan bertanya kegiatan antarabangsa mana yang dianjurkan di Malaysia dan di mana, kerana senarai itu bercampur.', 8, 802, 'formula_one_formula_e.png'),
('e8_n3_s1', 'Pintu kedai dibuka. Pelanggan lama menunjuk poster Kempen Beli Barangan Buatan Malaysia dan bertanya bila kempen itu dilancarkan.', 1, 803, 'barangan_buatan_malaysia.png'),
('e8_n3_s2', 'Rak berlabel Pertanian, Petroleum dan Automotif. Pelanggan mengambil tiga produk tetapi tersalah meletakkannya kembali. Kau perlu membetulkan susunan.', 2, 803, 'barangan_buatan_malaysia.png'),
('e8_n3_s3', 'Di luar kedai, pemandangan bandar penuh bangunan tinggi dan jaringan jalan raya. Pelanggan muda bertanya apakah bukti kemakmuran negara yang boleh dilihat.', 3, 803, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e8_n3_s4', 'Papan putih kedai. Pelanggan bertanya apakah tiga pencapaian pesat ekonomi dan apa maksud setiap satu. Kad-kad penerangan bercampur.', 4, 803, 'malaysia_dan_dunia_serantau.png'),
('e8_n3_s5', 'Sesi soal jawab pelanggan. Seorang remaja bertanya mengapa dia perlu bangga dengan barangan buatan Malaysia. Kad jawapan bertaburan di atas kaunter.', 5, 803, 'barangan_buatan_malaysia.png'),
('e8_n3_s6', 'Malam sebelum kedai ditutup. Kau membaca borang soal selidik pelanggan tentang kepentingan kemajuan ekonomi. Lapan pernyataan perlu ditanda benar atau salah, tetapi hanya satu kad betul ada di atas meja.', 6, 803, 'ladang.png'),
('e8_n3_s7', 'Kedai menutup pintu. Cikgu datang menyemak projek kedai sekolah. Dia bertanya apa peranan diri, masyarakat dan negara dalam menyokong ekonomi.', 7, 803, 'kampung_dan_pedalaman.png'),
('e8_n3_s8', 'Papan imbas kembali Unit 8 tergantung di dinding kedai. Pelanggan terakhir mahu rumusan: apa perbezaan ekonomi tradisional dan komersial, dan industri mana yang memacu kemajuan?', 8, 803, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e9_n1_s1', 'Dewan badminton. Papan skor menunjukkan nama Persatuan Badminton Malaysia, tetapi nota pengulas terselit di bawah kerusi dan mengelirukan.', 1, 901, 'badminton.png'),
('e9_n1_s2', 'Siaran ulangan perlawanan Piala Thomas. Seorang peminat bertanya apakah pencapaian antarabangsa badminton negara, dan mengaku sering keliru antara kejohanan.', 2, 901, 'piala_thomas.png'),
('e9_n1_s3', 'Stadium bola sepak. FAM menganjurkan liga, tetapi kad catatan pengulas terkoyak dan nama pasukan serta tahun bercampur.', 3, 901, 'bola_sepak.png'),
('e9_n1_s4', 'Peminat muda menunjukkan video gol jarak jauh. Dia bertanya sama ada pemain negara pernah mendapat anugerah dunia, dan berhujah gol itu tidak mungkin pernah menang apa-apa di peringkat dunia.', 4, 901, 'bola_sepak.png'),
('e9_n1_s5', 'Trek olahraga lama. Rakaman pecut tahun 1966 dan 1982 diputar. Pengulas mahu empat bukti bahawa atlet negara pernah memenangi emas 100 meter Sukan Asia.', 5, 901, 'olahraga.png'),
('e9_n1_s6', 'Pejabat KOM. Seorang peminat menanyakan sejarah KOM dan pencapaian terbaru atlet olahraga. Beberapa borang catatan bertukar-tukar.', 6, 901, 'olahraga.png'),
('e9_n1_s7', 'Padang hoki. Peminat sedang memperdebatkan kedudukan pasukan hoki negara dalam Piala Dunia. Papan kenyataan MHC tergantung senget.', 7, 901, 'hoki.png'),
('e9_n1_s8', 'Dinding galeri sukan. Empat legenda terdahulu berdiri dalam bingkai. Pengulas mahu gelaran dan pencapaian mereka dipadankan.', 8, 901, 'semua_podium_sukan.png'),
('e9_n2_s1', 'Dewan sekolah sebelum perhimpunan. Papan podium dipenuhi gambar pingat dan bendera. Murid bertanya bukti bahawa pencapaian atlet melambangkan kebanggaan negara.', 1, 902, 'semua_podium_sukan.png'),
('e9_n2_s2', 'Gelanggang badminton sekolah. Poster Lee Chong Wei tergantung di dinding. Murid mengaku keliru tentang anugerah dan gelaran yang pernah dimenangi beliau.', 2, 902, 'badminton.png'),
('e9_n2_s3', 'Dinding galeri atlet. Tiga poster Nicol Ann David, Pandelela Rinong dan Azizulhasni Awang tergantung terbalik. Murid diminta membetulkan gelaran dan pencapaian mereka.', 3, 902, 'sukan_komanwel.png'),
('e9_n2_s4', 'Padang hoki sekolah. Murid memegang kad S. Kuhan tetapi tidak pasti rekod pemain itu. Kad bercampur dengan rekod atlet lain.', 4, 902, 'hoki.png'),
('e9_n2_s5', 'Kolam renang sekolah. Murid mahu tahu berapa banyak pingat emas yang dimenangi Nurul Huda dan sejauh mana Abdul Malek mengharumkan nama negara.', 5, 902, 'sukan_sea.png'),
('e9_n2_s6', 'Seorang murid menunjukkan telefon dan bertanya sama ada permainan video boleh dianggap sukan. Cikgu menunjukkan satu kad e-sukan negara.', 6, 902, 'semua_podium_sukan.png'),
('e9_n2_s7', 'Perhimpunan sekolah. Empat atlet paralimpik muncul dalam bentuk poster di dinding dewan. Murid ingin tahu pencapaian setiap atlet, dan guru meminta mereka dipadankan.', 7, 902, 'sukan_alat_perpaduan_dan_keharmonian_kaum.png'),
('e9_n2_s8', 'Bilik guru. Pengetua bertanya faedah negara menjadi tuan rumah sukan antarabangsa. Kad kenyataan bertaburan di atas meja.', 8, 902, 'sukan_komanwel.png'),
('e9_n3_s1', 'Halaman pertama buku skrap: enam program sukan perpaduan. Keratan bercampur, dan tarikh serta fungsi tidak jelas.', 1, 903, 'sukan_alat_perpaduan_dan_keharmonian_kaum.png'),
('e9_n3_s2', 'Keratan akhbar SUKMA. Murid meragui bahawa ada temasya yang lebih besar daripada kejohanan sekolah. Cikgu bertanya temasya sukan terbesar dalam negara.', 2, 903, 'sukan_alat_perpaduan_dan_keharmonian_kaum.png'),
('e9_n3_s3', 'Halaman Sukan SEA dalam buku skrap. Cikgu mahu murid menyusun peristiwa penting penganjuran Sukan SEA.', 3, 903, 'sukan_sea.png'),
('e9_n3_s4', 'Halaman Piala Thomas dan Hoki Piala Dunia. Dua senarai tahun bercampur. Murid perlu membezakan tempat dan tahun penganjuran.', 4, 903, 'piala_thomas.png'),
('e9_n3_s5', 'Halaman sukan antarabangsa lain: permotoran, Le Tour de Langkawi, Komanwel, Formula One dan Piala Monsun. Enam keratan terlepas daripada kategorinya.', 5, 903, 'le_tour_de_langkawi.png'),
('e9_n3_s6', 'Halaman Komanwel. Murid terjumpa dua gambar maskot dan logo. Dia ragu sama ada maskot itu singa atau orang utan.', 6, 903, 'sukan_komanwel.png'),
('e9_n3_s7', 'Halaman kesimpulan. Cikgu meminta murid menulis cinta akan negara pada tiga peringkat: diri, masyarakat dan negara.', 7, 903, 'semua_podium_sukan.png'),
('e9_n3_s8', 'Halaman terakhir. Tiga pemimpin sukan negara muncul dalam keratan: seorang Sultan, seorang setiausaha agung bola sepak dan seorang bekas atlet polo air. Murid perlu memadankan jawatan dan sumbangan mereka.', 8, 903, 'semua_podium_sukan.png'),
('e10_n1_s1', 'Bilik pendaftaran sidang. Tiga lencana pertubuhan serantau bertukar tempat di atas meja. Wakil Indonesia ragu sama ada Malaysia menyertai ketiga-tiganya.', 1, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s2', 'Peta besar ASEAN di dinding sidang. Sepuluh bendera belum diletakkan mengikut tahun kemasukan. Wakil Indonesia meminta bantuan menyusunnya.', 2, 1001, 'bilik_mesyuarat_dunia.png'),
('e10_n1_s3', 'Bilik mesyuarat Menteri Luar ASEAN. Malaysia pernah menjadi tuan rumah mesyuarat ini. Wakil Indonesia mahu empat bukti keanggotaan ASEAN dalam gambar.', 3, 1001, 'bilik_mesyuarat.png'),
('e10_n1_s4', 'Papan latar belakang ASEAN di lobi. Kad tarikh, bilangan anggota dan ibu pejabat tertukar. Seorang wakil baharu bertanya fakta asas ASEAN.', 4, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s5', 'Dokumen matlamat penubuhan ASEAN di meja. Empat matlamat tertulis tetapi tidak dipadankan dengan butirannya. Pakar ekonomi meminta bantuan.', 5, 1001, 'bilik_mesyuarat_formal.png'),
('e10_n1_s6', 'Lobi dengan bendera ASEAN. Kanak-kanak menunjuk logo dan bertanya tentang warna dan lambangnya. Wakil muda perlu menjawab dengan tepat.', 6, 1001, 'bilik_mesyuarat_modern.png'),
('e10_n1_s7', 'Papan faedah penyertaan Malaysia dalam ASEAN. Kad bercampur antara faedah dan tempat. Wakil muda perlu menyusunnya.', 7, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s8', 'Sidang penutup ASEAN. Wakil dari negara lain bertanya apa sumbangan Malaysia. Dokumen sumbangan tertukar dengan sumbangan organisasi lain.', 8, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n2_s1', 'Dewan sidang PBB. Peta dunia di skrin besar menunjukkan kawasan tugas pasukan pengaman. Wakil PBB mahu kau menunjukkan bukti Malaysia terlibat.', 1, 1002, 'malaysia_di_pentas_dunia.png'),
('e10_n2_s2', 'Penyata latar belakang PBB di bilik mesyuarat. Seorang wakil baharu mengelirukan PBB dengan pertubuhan lain. Kad latar belakang bercampur.', 2, 1002, 'bilik_mesyuarat_dunia.png'),
('e10_n2_s3', 'Papan empat pertubuhan antarabangsa. Kad tahun dan bilangan anggota bertukar. Penjaga keamanan perlu memadankannya sebelum mesyuarat bermula.', 3, 1002, 'malaysia_di_pentas_dunia.png'),
('e10_n2_s4', 'Bilik mesyuarat gaya London. Utusan Komanwel menunjukkan dokumen tetapi sebahagian kata terpadam. Kau perlu membaca latar belakang Komanwel.', 4, 1002, 'bilik_mesyuarat_london.png'),
('e10_n2_s5', 'Papan faedah Komanwel. Empat bidang tertulis tetapi butiran tertukar. Utusan Komanwel meminta bantuan menyusunnya.', 5, 1002, 'bilik_mesyuarat_london.png'),
('e10_n2_s6', 'Sidang Komanwel di bilik formal. Tiga sumbangan Malaysia tercatat pada kertas yang basah. Kau perlu menentukan butiran yang betul.', 6, 1002, 'bilik_mesyuarat_formal.png'),
('e10_n2_s7', 'Bilik mesyuarat OIC. Gambar Tunku Abdul Rahman tergantung di dinding. Wakil OIC bertanya jawatan beliau dalam OIC dan kad butiran latar OIC tertukar.', 7, 1002, 'bilik_mesyuarat_modern.png'),
('e10_n2_s8', 'Sukarelawan OIC menyusun fail sumbangan Malaysia. Kad sumbangan tertukar. Wakil OIC meminta kau memadankannya sebelum laporan tahunan.', 8, 1002, 'malaysia_di_pentas_dunia.png'),
('e10_n3_s1', 'Bilik pertama pameran memaparkan peta misi pasukan pengaman PBB. Tujuh kad tarikh dan tempat bertaburan. Pelawat mahu urutan misi mengikut tahun.', 1, 1003, 'bilik_UNMM.png'),
('e10_n3_s2', 'Bilik sumbangan Malaysia dalam PBB. Empat kad besar tergantung senget. Pelawat mahu memahami empat sumbangan lain di luar misi pengaman.', 2, 1003, 'bilik_mesyuarat_dunia.png'),
('e10_n3_s3', 'Bilik faedah PBB. Pelawat bertanya apa faedah negara menyertai PBB. Kad butiran tertukar dengan faedah ASEAN.', 3, 1003, 'bilik_mesyuarat_formal.png'),
('e10_n3_s4', 'Bilik individu Malaysia berpengaruh di PBB. Dua gambar tokoh tergantung terbalik. Pelawat mahu jawatan setiap tokoh dipadankan.', 4, 1003, 'malaysia_di_pentas_dunia.png'),
('e10_n3_s5', 'Ruang UNESCO dengan peta bandar dan gua dalam kaca. Pelawat tidak pasti lokasi warisan dunia Malaysia. Pemandu perlu membimbing mereka.', 5, 1003, 'ruang_unesco.png'),
('e10_n3_s6', 'Empat almari kaca UNESCO. Pelawat keliru antara kategori pengiktirafan. Kad kategori dan contoh bertukar tempat.', 6, 1003, 'ruang_unesco.png'),
('e10_n3_s7', 'Dinding garis masa UNESCO. Lapan pengiktirafan tertulis tanpa tahun yang betul. Pelawat meminta pemandu menyusunnya.', 7, 1003, 'ruang_unesco.png'),
('e10_n3_s8', 'Bilik kepentingan hubungan baik. Pelawat bertanya mengapa Malaysia menjalin hubungan baik dengan negara luar. Kad jawapan bertukar tempat.', 8, 1003, 'bilik_mesyuarat_dunia.png'),
('e10_n3_s9', 'Bilik terakhir pameran. Pelawat diminta menulis cinta akan negara pada tiga peringkat: diri, masyarakat dan negara.', 9, 1003, 'malaysia_dan_dunia_serantau.png');

